const DB={"version":"18.2.2","date":"2026-11-28","modules":[{"id":"m1","title":"招聘与人才获取","english":"Recruitment & Talent Acquisition","desc":"招聘流程、面试评估与录用沟通","color":"#3B82F6"},{"id":"m2","title":"薪酬激励与福利","english":"Compensation & Benefits","desc":"薪酬体系、激励政策与福利沟通","color":"#8B5CF6"},{"id":"m3","title":"绩效管理","english":"Performance Management","desc":"目标制定、评价校准与绩效改进","color":"#F59E0B"},{"id":"m4","title":"学习培训与人才发展","english":"Learning & Development","desc":"培训体系、能力提升与领导力培养","color":"#10B981"},{"id":"m5","title":"组织与人才发展（OD/TD）","english":"Organization & Talent Development","desc":"组织设计、人才盘点与继任规划","color":"#EC4899"},{"id":"m6","title":"员工关系与劳动合规","english":"Employee Relations & Compliance","desc":"员工沟通、制度执行与合规风险","color":"#F97316"},{"id":"m7","title":"企业文化与员工体验","english":"Culture & Employee Experience","desc":"价值观、敬业度、多元与工作体验","color":"#06B6D4"},{"id":"m8","title":"HR运营与数据分析","english":"HR Operations & People Analytics","desc":"人事系统、数据指标与日常服务","color":"#64748B"},{"id":"m9","title":"海外派遣与全球流动","english":"Global Mobility & International Assignments","desc":"国际派遣、签证税务、回任与跨境合规","color":"#0e948b"},{"id":"m10","title":"HR商务沟通与汇报","english":"HR Business Communication","desc":"会议沟通、管理层汇报、项目推进与协同","color":"#e07849"}],"words":[{"id":"HR001","moduleId":"m1","module":"招聘与人才获取","term":"Job requisition","zh":"招聘申请单","definition":"正式提出招聘需求并供审批、跟踪的申请记录，通常包括岗位、人数及招聘理由。","example":"The recruiter cannot open the vacancy until the job requisition is approved.","collocation":"approve a job requisition","dialogue":[{"role":"Recruiter","en":"Should I put both openings on the same job requisition?","zh":"这两个空缺要填在同一张招聘申请单上吗？"},{"role":"Hiring Manager","en":"Yes. They’re both for the night shift and report to the same supervisor.","zh":"对，两个都是夜班岗位，直属主管也是同一位。"}],"usage":"","new":false,"order":1,"aliases":[],"distinction":"Job requisition 是内部招聘申请；job posting 是面向候选人的招聘信息；headcount approval 是人员编制审批。","collocationZh":"审批招聘申请单","collocationReview":"V18.2 模型编辑复核","ipaUK":"dʒɒb ˌrek.wɪˈzɪʃ.ən","ipaUS":"dʒɑːb ˌrek.wəˈzɪʃ.ən","ipaSource":"词典重点校订","speakTerm":"Job requisition","exampleZh":"招聘申请获批后，招聘专员才能启动该岗位招聘。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Has the hiring manager submitted the job requisition yet?","zh":"用人经理提交招聘申请单了吗？"},"extension":{"en":"Could you attach the business justification to the job requisition?","zh":"能否在招聘申请单中附上招聘的业务理由？"}},{"id":"HR002","moduleId":"m1","module":"招聘与人才获取","term":"Headcount approval","zh":"编制审批","definition":"对拟新增或补充的人员编制进行授权的流程，通常涉及预算和业务需求。","example":"Finance granted headcount approval for three additional analysts.","collocation":"secure headcount approval","dialogue":[{"role":"Hiring Manager","en":"Could we use the open support position to hire another analyst?","zh":"能用空着的客服编制再招一名分析师吗？"},{"role":"HRBP","en":"I’ll check with Finance to see whether the transfer needs new headcount approval.","zh":"我去问财务，看看调拨编制是否要重新审批。"}],"usage":"","new":false,"order":2,"aliases":[],"distinction":"Headcount approval 关注编制授权；budget approval 关注预算授权；job requisition 关注具体招聘申请。","collocationZh":"获得编制批准","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈhed.kaʊnt əˈpruː.vəl","ipaUS":"ˈhed.kaʊnt əˈpruː.vəl","ipaSource":"词典重点校订","speakTerm":"Headcount approval","exampleZh":"财务部门批准了新增三名分析师的编制。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can we open this vacancy before headcount is approved?","zh":"在人员编制获批前，我们能启动这个空缺岗位的招聘吗？"},"extension":{"en":"Please confirm headcount approval before we contact the agency.","zh":"请在联系招聘机构前确认编制已获批。"}},{"id":"HR003","moduleId":"m1","module":"招聘与人才获取","term":"Workforce planning","zh":"人力规划","definition":"根据业务战略预测人员需求与供给，并制定弥补人员数量和能力差距的行动计划。","example":"Our workforce planning process includes a review of critical skills.","collocation":"annual workforce planning","dialogue":[{"role":"Operations Director","en":"We’re adding a weekend shift in October. Can we cover it with the people we have?","zh":"我们十月要增开周末班，现有人员能排得过来吗？"},{"role":"HRBP","en":"Let’s model that in workforce planning. If there’s a gap, we can look at cross-training or hiring.","zh":"我们在人力规划里测算一下。如果有缺口，再考虑交叉培训或招人。"}],"usage":"","new":false,"order":3,"aliases":[],"distinction":"Workforce planning 涵盖需求、供给和行动计划；headcount planning 侧重人数编制；succession planning 侧重关键岗位继任。","collocationZh":"年度人力规划","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈwɜːk.fɔːs ˈplæn.ɪŋ","ipaUS":"ˈwɝːk.fɔːrs ˈplæn.ɪŋ","ipaSource":"词典重点校订","speakTerm":"Workforce planning","exampleZh":"我们在人力规划过程中会盘点关键技能。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we prepare for next year's expansion?","zh":"我们该如何为明年的业务扩张做好准备？"},"extension":{"en":"We should update the workforce plan when the demand forecast changes.","zh":"人力需求预测发生变化时，我们应更新人力规划。"}},{"id":"HR004","moduleId":"m1","module":"招聘与人才获取","term":"Job description","zh":"岗位说明书（JD）","definition":"说明岗位职责、工作范围及汇报关系的文件，也可包含任职要求。","example":"The job description should distinguish essential duties from occasional tasks.","collocation":"revise a job description","dialogue":[{"role":"Recruiter","en":"The job description still says the analyst owns the monthly forecast. Is that right?","zh":"岗位说明书上还写着分析师负责月度预测，这条还适用吗？"},{"role":"Hiring Manager","en":"They provide the sales data now. Finance owns the forecast.","zh":"现在分析师负责提供销售数据，预测由财务负责。"}],"usage":"可译“职位描述”，但 HR 文件场景优先用“岗位职责说明书/岗位说明书”。","new":false,"order":4,"distinction":"Job description 描述岗位；job specification 侧重任职资格；job posting 是招聘发布信息。","aliases":["JD","岗位说明书"],"collocationZh":"修订岗位说明书","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈdʒɒb dɪˌskrɪp.ʃən","ipaUS":"ˈdʒɑːb dɪˌskrɪp.ʃən","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/job-description","speakTerm":"Job description","exampleZh":"岗位说明书应区分核心职责和偶尔承担的任务。","ipaReview":"完整词头英美音标文本核对","ipaNote":"英美音标据 Cambridge 发音词头核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you update the job description for the revised role?","zh":"能否为调整后的岗位更新岗位说明书？"},"extension":{"en":"Let’s remove outdated responsibilities from the job description.","zh":"我们把已经不再承担的职责从岗位说明书里删掉吧。"}},{"id":"HR005","moduleId":"m1","module":"招聘与人才获取","term":"Job posting","zh":"职位招聘公告／招聘信息","definition":"向潜在应聘者发布的职位空缺信息，通常包含职责、要求和申请方式。","example":"The job posting lists the location and application deadline.","collocation":"publish a job posting","dialogue":[{"role":"Candidate","en":"The job posting says the role is based in Leeds. Would I need to be there every day?","zh":"招聘公告写的是工作地点在利兹。我需要每天到办公室吗？"},{"role":"Recruiter","en":"Two days a week is enough for this team. I’ll add that to the posting.","zh":"这个团队每周到办公室两天就可以，我会在公告里补充说明。"}],"usage":"Job posting 指发布的职位招聘信息，不等同于岗位职责说明书（JD）。","new":false,"order":5,"distinction":"Job posting 是发布的招聘信息；job description 是岗位说明；job requisition 是内部招聘申请。","aliases":[],"collocationZh":"发布职位招聘信息","collocationReview":"V18.2 模型编辑复核","ipaUK":"dʒɒb ˈpəʊstɪŋ","ipaUS":"dʒɑːb ˈpoʊstɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Job posting","exampleZh":"招聘公告列出了工作地点和申请截止日期。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Has our new position been published yet?","zh":"我们的新职位已经发布招聘信息了吗？"},"extension":{"en":"Please remove the job posting once applications close.","zh":"申请截止后，请撤下招聘公告。"}},{"id":"HR006","moduleId":"m1","module":"招聘与人才获取","term":"Employer branding","zh":"雇主品牌建设","definition":"通过真实员工体验、雇主价值主张及传播活动塑造和维护雇主形象。","example":"Employer branding can help candidates understand our workplace culture.","collocation":"strengthen employer branding","dialogue":[{"role":"Recruiter","en":"Candidates keep asking what a first week here looks like. Could we show them?","zh":"候选人总问入职第一周怎么过。我们能做些内容给他们看看吗？"},{"role":"Employer Brand Lead","en":"Yes. Let’s ask a recent hire to walk us through their first week for our employer branding campaign.","zh":"可以。请一位刚入职的同事讲讲自己第一周的经历，放到雇主品牌宣传里。"}],"usage":"作为一系列活动/策略时用 employer branding；品牌本身用 employer brand。","new":false,"order":6,"distinction":"Employer branding 是塑造雇主形象的过程；employer brand 是形成的雇主形象；EVP 是雇主向员工提供的价值主张。","aliases":["雇主品牌打造"],"collocationZh":"加强雇主品牌建设","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.ə ˈbræn.dɪŋ","ipaUS":"ɪmˈplɔɪ.ɚ ˈbræn.dɪŋ","ipaSource":"词典重点校订","speakTerm":"employer branding","exampleZh":"雇主品牌建设有助于候选人了解我们的职场文化。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What are we highlighting in our employer branding campaign?","zh":"这次雇主品牌宣传活动重点展示哪些内容？"},"extension":{"en":"Our employer branding messages should reflect the actual employee experience.","zh":"我们的雇主品牌传播内容应反映真实的员工体验。"}},{"id":"HR007","moduleId":"m1","module":"招聘与人才获取","term":"Candidate sourcing","zh":"人才寻访","definition":"主动识别、寻找并接触潜在候选人的招聘活动。","example":"Candidate sourcing is particularly important for specialist roles.","collocation":"improve candidate sourcing","dialogue":[{"role":"Hiring Manager","en":"We’ve had plenty of applicants, but nobody has worked with industrial robots.","zh":"申请收到不少，但还没人有工业机器人方面的工作经验。"},{"role":"Recruiter","en":"I’ll focus our candidate sourcing on robotics groups and ask the engineering team for referrals.","zh":"我会重点到机器人专业社群寻访，也请工程团队推荐人选。"}],"usage":"","new":false,"order":7,"aliases":[],"distinction":"Candidate sourcing 侧重主动寻找候选人；screening 侧重筛选；recruitment 涵盖更广泛的招聘流程。","collocationZh":"改进人才寻访工作","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkæn.dɪ.dət ˈsɔːsɪŋ","ipaUS":"ˈkæn.dɪ.dət ˈsɔːrsɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Candidate sourcing","exampleZh":"对于专业技术岗位，人才寻访尤为重要。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What's our priority for filling this difficult role?","zh":"为了填补这个难招的岗位，我们目前最优先做什么？"},"extension":{"en":"Which channels are most effective for sourcing candidates?","zh":"哪些渠道最适合寻访候选人？"}},{"id":"HR008","moduleId":"m1","module":"招聘与人才获取","term":"Talent pool","zh":"人才库","definition":"为当前或未来招聘需求而维护的潜在候选人集合。","example":"A well-maintained talent pool can support future hiring needs.","collocation":"build a talent pool","dialogue":[{"role":"Hiring Manager","en":"Didn’t we interview someone with Polish language skills last spring?","zh":"我们去年春天是不是面过一位会波兰语的候选人？"},{"role":"Recruiter","en":"I’ll check the talent pool. If we can still contact them under our data retention policy and applicable rules, I’ll ask if they’re interested.","zh":"我查一下人才库。如果按我们的数据保留政策和适用规定仍可以联系对方，我就去问问有没有兴趣。"}],"usage":"","new":false,"order":8,"aliases":[],"distinction":"Talent pool 是为当前或未来岗位保留的潜在人选集合。Candidate pipeline 强调候选人向招聘各阶段推进的情况，succession pool 则专指可培养或考虑接任关键岗位的人选。","collocationZh":"建立人才库","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtæl.ənt puːl","ipaUS":"ˈtæl.ənt puːl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Talent pool","exampleZh":"维护良好的人才库可以支持未来招聘需求。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we do with the qualified applicants we haven't hired?","zh":"那些符合条件但尚未录用的应聘者，我们应该如何处理？"},"extension":{"en":"Let’s review the talent pool before launching a new search.","zh":"启动新一轮寻访前，我们先查一查人才库吧。"}},{"id":"HR009","moduleId":"m1","module":"招聘与人才获取","term":"Applicant tracking system (ATS)","zh":"招聘管理系统","definition":"用于管理招聘申请、候选人信息及招聘流程的系统，简称 ATS。","example":"The applicant tracking system records each candidate’s current stage.","collocation":"update a candidate record in the ATS","dialogue":[{"role":"Hiring Manager","en":"I can see my own interview notes, but where’s Priya’s feedback?","zh":"我能看到自己的面试记录，但普里娅的反馈在哪里？"},{"role":"Recruiter","en":"It’s in the ATS under the second interview. I’ll send you the link.","zh":"在招聘管理系统的第二轮面试记录里，我把链接发给你。"}],"usage":"","new":false,"order":9,"aliases":[],"distinction":"ATS 侧重招聘流程；HRIS 侧重人事信息管理；招聘 CRM 侧重候选人关系维护。","collocationZh":"更新招聘管理系统中的候选人记录","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈæp.lɪ.kənt ˈtrækɪŋ ˈsɪstəm","ipaUS":"ˈæp.lɪ.kənt ˈtrækɪŋ ˈsɪstəm","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Applicant tracking system","exampleZh":"招聘管理系统记录每位候选人当前所处的阶段。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Where do we store interview feedback?","zh":"我们把面试反馈存放在哪里？"},"extension":{"en":"Could you check whether the candidate’s status is up to date in the ATS?","zh":"能否确认招聘管理系统里的候选人状态是最新的？"}},{"id":"HR010","moduleId":"m1","module":"招聘与人才获取","term":"Resume screening","zh":"简历筛选","definition":"依据岗位相关标准初步评估简历，确定是否进入后续招聘环节。","example":"Resume screening should focus on the requirements of the role.","collocation":"conduct resume screening","dialogue":[{"role":"Hiring Manager","en":"A few applicants list project leadership without saying how big their teams were.","zh":"有几位应聘者写了自己带过项目，但没说团队有多大。"},{"role":"Recruiter","en":"Let’s flag that during resume screening and ask about team size on the first call.","zh":"那我们筛简历时先记下来，第一次电话沟通时再问团队规模。"}],"usage":"","new":false,"order":10,"aliases":[],"distinction":"Resume screening 是简历初筛；phone screen 是电话初筛；shortlisting 是确定进入后续环节的候选人名单。","collocationZh":"进行简历筛选","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈrez.juː.meɪ ˈskriː.nɪŋ","ipaUS":"ˈrez.ə.meɪ ˈskriː.nɪŋ","ipaSource":"词典重点校订","speakTerm":"résumé screening","exampleZh":"简历筛选应聚焦岗位要求。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When will the initial resume screening be finished?","zh":"首轮简历筛选什么时候能够完成？"},"extension":{"en":"During resume screening, flag applications that need a second review.","zh":"筛选简历时，请标记需要再看一遍的申请。"}},{"id":"HR011","moduleId":"m1","module":"招聘与人才获取","term":"Phone screen","zh":"电话初筛","definition":"通过简短电话沟通核对候选人的基本条件，初步评估岗位匹配度。","example":"I’ve scheduled a phone screen with the candidate for tomorrow.","collocation":"arrange a phone screen","dialogue":[{"role":"Recruiter","en":"Your application mentions weekend shifts. Would Saturday mornings work for you?","zh":"您的申请里提到可以上周末班。周六上午方便吗？"},{"role":"Candidate","en":"Yes, most weeks. Could we talk through the shift rotation during the phone screen?","zh":"大多数时候可以。我们能在电话初筛时聊一下怎么轮班吗？"}],"usage":"","new":false,"order":11,"aliases":[],"distinction":"Phone screen 是电话里的第一轮初筛，通常确认基本经验、岗位匹配度或到岗时间。Resume screening 主要看申请材料，正式面试通常进一步考察能力和行为证据。","collocationZh":"安排电话初筛","collocationReview":"V18.2 模型编辑复核","ipaUK":"fəʊn skriːn","ipaUS":"foʊn skriːn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Phone screen","exampleZh":"我已安排明天与这位候选人进行电话初筛。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Have you arranged an initial call with the candidate?","zh":"你安排好与候选人的初步电话沟通了吗？"},"extension":{"en":"Allow a few minutes at the end of the phone screen for the candidate’s questions.","zh":"电话初筛快结束时，请留几分钟给候选人提问。"}},{"id":"HR012","moduleId":"m1","module":"招聘与人才获取","term":"Screening criteria","zh":"筛选标准","definition":"在招聘初期用于评估候选人是否满足岗位相关条件、能否进入下一环节的标准。","example":"We should align on the screening criteria before reviewing resumes.","collocation":"define screening criteria","dialogue":[{"role":"Recruiter","en":"The posting says a certification is preferred. I’ve got several applicants without it.","zh":"招聘公告写的是有证书优先，有几位申请人没有这项证书。"},{"role":"Hiring Manager","en":"Keep them in the running. Our screening criteria allow equivalent hands-on experience.","zh":"先保留这些候选人。按我们的筛选标准，同等的实践经验也可以。"}],"usage":"","new":false,"order":12,"aliases":[],"distinction":"Screening criteria 用于决定候选人是否进入下一轮。Job requirements 描述岗位要求，筛选时可把其中的必备项转成可核对的条件。Interview scoring criteria 用于评价面试中展示的能力。","collocationZh":"制定候选人筛选标准","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈskriːnɪŋ kraɪˈtiərɪə","ipaUS":"ˈskriːnɪŋ kraɪˈtɪriːə","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Screening criteria","exampleZh":"开始筛选简历前，我们应先就筛选标准达成一致。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we agree on before reviewing resumes?","zh":"在筛选简历前，我们应该统一哪些标准？"},"extension":{"en":"Document which screening criteria are mandatory and which are preferred.","zh":"请记录哪些筛选标准是必备条件，哪些是优先条件。"}},{"id":"HR013","moduleId":"m1","module":"招聘与人才获取","term":"Hiring manager","zh":"用人经理","definition":"提出或确认岗位需求、评估候选人并参与录用决策的用人部门管理者。","example":"The hiring manager wants to meet three shortlisted candidates.","collocation":"consult the hiring manager","dialogue":[{"role":"Recruiter","en":"The candidate asked how much time they’d spend with clients. Could you cover that in your interview?","zh":"候选人问这个岗位有多少时间要和客户打交道。你面试时能介绍一下吗？"},{"role":"Hiring Manager","en":"Of course. I’ll walk them through what a typical week on the team looks like.","zh":"没问题，我会给对方讲讲团队一周通常怎么安排。"}],"usage":"","new":false,"order":13,"aliases":[],"distinction":"Hiring manager 代表用人团队明确需求并参与录用决策。Recruiter 负责寻访和推进招聘流程。两者的决策权限由组织分工决定。","collocationZh":"征询用人经理的意见","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈhaɪərɪŋ ˈmæn.ɪ.dʒə","ipaUS":"ˈhaɪrɪŋ ˈmæn.ə.dʒɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Hiring manager","exampleZh":"用人经理希望面试三位入围候选人。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who does the hiring manager want to interview next?","zh":"用人经理接下来希望面试谁？"},"extension":{"en":"The hiring manager should brief the interviewers on what the role actually involves.","zh":"用人经理应向面试官介绍这个岗位具体要做什么。"}},{"id":"HR014","moduleId":"m1","module":"招聘与人才获取","term":"Interview panel","zh":"面试小组","definition":"为某个岗位共同面试和评估候选人的面试官小组。","example":"Our interview panel includes HR, engineering and product leaders.","collocation":"form an interview panel","dialogue":[{"role":"Recruiter","en":"Our engineering interviewer can’t make Thursday. Could you join the interview panel in her place?","zh":"工程部那位面试官周四来不了，你能替她参加面试小组吗？"},{"role":"Engineering Lead","en":"Yes. Send me the brief so I know which technical skills to assess.","zh":"可以。把面试简报发给我，我好知道要考察哪些技术能力。"}],"usage":"","new":false,"order":14,"aliases":[],"distinction":"Interview panel 指参与面试和评估的人员小组。Panel interview 指多位面试官共同面试同一位候选人的形式。","collocationZh":"组建面试小组","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈɪn.tə.vjuː ˈpænəl","ipaUS":"ˈɪn.tɚ.vjuː ˈpænəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Interview panel","exampleZh":"我们的面试小组包括人力资源、工程和产品部门的负责人。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who will sit on the interview panel?","zh":"哪些人将参加面试小组？"},"extension":{"en":"Send the candidate the names and roles of the interview panel in advance.","zh":"请提前告知候选人面试小组成员的姓名和职务。"}},{"id":"HR015","moduleId":"m1","module":"招聘与人才获取","term":"Structured interview","zh":"结构化面试","definition":"按预先制定的核心问题和统一评分规则评估同一岗位候选人的面试方式。","example":"A structured interview helps reduce inconsistent evaluations.","collocation":"run a structured interview","dialogue":[{"role":"New Interviewer","en":"What if someone gives me a vague answer during the structured interview?","zh":"做结构化面试时，如果候选人回答得很笼统怎么办？"},{"role":"Interview Lead","en":"Ask what they did personally, then return to the next question on the guide.","zh":"先追问对方本人做了什么，再按提纲问下一题。"}],"usage":"","new":false,"order":15,"aliases":[],"distinction":"Structured interview 强调核心问题和评分尺度统一。Behavioral interview 强调请候选人讲真实经历，行为题可以纳入结构化面试。","collocationZh":"开展结构化面试","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈstrʌktʃəd ˈɪn.tə.vjuː","ipaUS":"ˈstrʌktʃɚd ˈɪn.tɚ.vjuː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Structured interview","exampleZh":"结构化面试有助于提升面试评价的一致性。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we make interview assessments more consistent?","zh":"我们怎样使面试评价更加一致？"},"extension":{"en":"In a structured interview, record the evidence behind each rating.","zh":"在结构化面试中，请记录每项评分的事实依据。"}},{"id":"HR016","moduleId":"m1","module":"招聘与人才获取","term":"Competency-based interview","zh":"胜任力面试","definition":"以岗位所需的胜任力为框架，通过相关问题收集证据并评估候选人的面试方法。","example":"The competency-based interview will focus on stakeholder management.","collocation":"design competency-based questions","dialogue":[{"role":"Recruiter","en":"We’re covering problem-solving in the competency-based interview. What would count as strong evidence?","zh":"胜任力面试要考察解决问题的能力，什么样的表现能算有说服力的证据？"},{"role":"Hiring Manager","en":"I’d like to hear how they ruled out other causes before settling on a fix.","zh":"我想听听候选人在确定解决办法前，是怎么排除其他可能原因的。"}],"usage":"常与 STAR 追问法结合，但不是 STAR 的同义词。","new":false,"order":16,"distinction":"Competency-based interview 以岗位胜任力为考察框架，常用行为题，也可用情景题。Behavioral interview 侧重询问以往行为。STAR 是组织回答或追问时可用的框架。","aliases":[],"collocationZh":"设计胜任力面试题","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkɒmpɪtənsi beɪst ˈɪn.tə.vjuː","ipaUS":"ˈkɑːmpətɪnsiː beɪst ˈɪn.tɚ.vjuː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Competency-based interview","exampleZh":"此次胜任力面试将重点考察利益相关方管理能力。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which competencies will the interview focus on?","zh":"这次面试将重点考查哪些胜任力？"},"extension":{"en":"For the competency-based interview, prepare one follow-up question for each skill you want to assess.","zh":"准备胜任力面试时，为每项待考察能力设计一个追问。"}},{"id":"HR017","moduleId":"m1","module":"招聘与人才获取","term":"Behavioral interview","zh":"行为面试","definition":"通过候选人过去的实际经历收集行为证据，以评估与岗位相关的能力。通常会追问候选人面临的情境、采取的行动和取得的结果。","example":"In a behavioral interview, ask for a specific example of conflict resolution.","collocation":"use behavioral interview questions","dialogue":[{"role":"Interviewer","en":"Tell me about a time you missed a deadline. How did you handle it?","zh":"请分享一次你没能按时完成任务的经历。当时你是怎么处理的？"},{"role":"Candidate","en":"I told the client as soon as I had a revised delivery date and sent them the completed sections first.","zh":"我一确定新的交付日期就通知了客户，并先把已完成的部分发过去。"}],"usage":"美式写法为 behavioral interview，英式写法为 behavioural interview。","new":false,"order":17,"distinction":"Behavioral interview 请候选人复述实际经历中的行动和结果。Situational interview 则给出假设情景，询问候选人会如何应对。","aliases":["Behavioural interview","Behavior-based interview"],"collocationZh":"使用行为面试问题","collocationReview":"V18.2 模型编辑复核","ipaUK":"bɪˈheɪvjərəl ˈɪn.tə.vjuː","ipaUS":"bɪˈheɪvjɚəl ˈɪn.tɚ.vjuː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Behavioral interview","exampleZh":"在行为面试中，应请候选人举出解决冲突的具体事例。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we assess a candidate's conflict-resolution experience?","zh":"我们怎样评估候选人处理冲突的实际经验？"},"extension":{"en":"In a behavioral interview, probe for the candidate’s own contribution to a team result.","zh":"在行为面试中，要追问候选人本人对团队成果作出了什么贡献。"},"searchAliases":["Behavioral-Based Interview"]},{"id":"HR018","moduleId":"m1","module":"招聘与人才获取","term":"Assessment center","zh":"评价中心","definition":"通过多项模拟练习，由受训人员按预设标准观察和评估候选人或员工能力的测评方法。","example":"The assessment center includes a group exercise and a case presentation.","collocation":"attend an assessment center","dialogue":[{"role":"Candidate","en":"Do I need to prepare slides for the assessment center?","zh":"参加评价中心测评需要提前准备幻灯片吗？"},{"role":"Recruiter","en":"We’ll give you the materials on the day and allow twenty minutes to prepare.","zh":"当天会发给你材料，并留出二十分钟准备。"}],"usage":"","new":false,"order":18,"aliases":[],"distinction":"Assessment center 是多项练习与系统评价组成的测评流程，可虚拟进行。Interview panel 指面试小组，单项测试通常只提供某项能力的测评证据。","collocationZh":"参加评价中心测评","collocationReview":"V18.2 模型编辑复核","ipaUK":"əˈses.mənt ˈsentə","ipaUS":"əˈses.mənt ˈsentɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Assessment center","exampleZh":"此次评价中心测评包括一项小组练习和一次案例展示。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What exercises are included in the assessment center?","zh":"评价中心测评包括哪些项目？"},"extension":{"en":"At the assessment center, each assessor records observations independently.","zh":"在评价中心测评中，每位测评人员独立记录观察结果。"}},{"id":"HR019","moduleId":"m1","module":"招聘与人才获取","term":"Take-home assignment","zh":"独立测评任务","definition":"招聘中交由候选人在面试之外独立完成并按要求提交的测评任务。","example":"We gave the candidate a take-home assignment with a clear deadline.","collocation":"review a take-home assignment","dialogue":[{"role":"Candidate","en":"The take-home assignment mentions a short write-up. Would bullet points be enough?","zh":"独立测评任务里提到要写一小段说明，用要点列出来可以吗？"},{"role":"Recruiter","en":"Yes. A page of bullet points is fine as long as we can follow your reasoning.","zh":"可以。一页要点就够，只要能看清你的思路。"}],"usage":"","new":false,"order":19,"aliases":[],"distinction":"Take-home assignment 由候选人在约定的面试时段之外独立完成。Live exercise 在约定的现场或线上时段完成，评估者可观察过程。Work sample test 强调任务模拟真实工作，可采用上述任一种形式。","collocationZh":"评阅独立测评任务","collocationReview":"V18.2 模型编辑复核","ipaUK":"teɪk həʊm əˈsaɪnmənt","ipaUS":"teɪk hoʊm əˈsaɪnmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Take-home assignment","exampleZh":"我们给候选人布置了一项独立测评任务，并明确了提交期限。","meaningReview":"HR场景校订","exampleReview":"语义修订","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What kind of task will the candidate complete outside the interview?","zh":"候选人需要在面试之外完成哪种任务？"},"extension":{"en":"Please allow candidates enough time to complete the take-home assignment.","zh":"请给候选人留出足够时间完成独立测评任务。"},"legacyExtraBookmark":{"en":"Please allow candidates enough time to complete the take-home assignment.","zh":"请给候选人留出足够时间完成面试后的独立测评任务。"}},{"id":"HR020","moduleId":"m1","module":"招聘与人才获取","term":"Reference check","zh":"职业推荐人核查","definition":"按适用规定和组织流程联系职业推荐人，了解候选人的相关工作经历、表现和协作情况。","example":"We will conduct the reference check after the final interview.","collocation":"complete a reference check","dialogue":[{"role":"Candidate","en":"My current manager doesn’t know I’m applying. Could you speak to my former supervisor instead?","zh":"我现在的经理还不知道我在应聘。你们可以改为联系我以前的主管吗？"},{"role":"Recruiter","en":"Let me check whether a former supervisor is acceptable for this reference check.","zh":"我先确认一下，这次推荐人核查能否联系前任主管。"}],"usage":"“推荐人核查”和“背景调查”在 HR 流程中有关联，但范围不同。","new":false,"order":20,"distinction":"Reference check 通过职业推荐人了解对候选人工作表现的评价。Employment verification 主要核实任职单位、职务和任职时间等事实，background check 则可能覆盖多类核查。","aliases":["Reference checking","履历核查"],"collocationZh":"完成推荐人核查","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈrefrəns tʃek","ipaUS":"ˈrefɚəns tʃek","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Reference check","exampleZh":"我们将在终面结束后进行推荐人核查。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When will we contact the candidate's references?","zh":"我们什么时候联系候选人的推荐人进行核查？"},"extension":{"en":"Keep reference check questions focused on work the referee directly observed.","zh":"推荐人核查的问题应聚焦推荐人亲自观察过的工作表现。"}},{"id":"HR021","moduleId":"m1","module":"招聘与人才获取","term":"Background check","zh":"候选人背景调查（背调）","definition":"在适用法律允许的范围内，按规定履行告知、授权等要求后，对候选人的任职、学历等背景信息进行核实。","example":"For this role, the offer is conditional on a satisfactory background check.","collocation":"initiate a background check","dialogue":[{"role":"Recruiter","en":"The company running your background check couldn’t verify one of your previous jobs. Has that employer changed names?","zh":"背调机构没能核实您之前的一段任职经历。那家公司改过名字吗？"},{"role":"Candidate","en":"Yes. I can send you the name it used when I worked there.","zh":"改过。我可以把我任职时用的公司名称发给您。"}],"usage":"根据不同法域，可能涉及额外的隐私、告知与授权要求。","new":false,"order":21,"distinction":"Background check 可综合核实任职、学历等背景信息。Reference check 通过职业推荐人了解工作表现，可能是背调的一环。可查项目及告知、授权等要求依适用法域和岗位而定。","aliases":["Background screening","背景核验"],"collocationZh":"启动候选人背景调查","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈbækɡraʊnd tʃek","ipaUS":"ˈbækɡraʊnd tʃek","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Background check","exampleZh":"这个岗位的录用以背景调查结果符合要求为前提。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Is there anything the offer is conditional on?","zh":"这份录用通知有什么前置条件吗？"},"extension":{"en":"Confirm which checks are permitted for the role before requesting a background check.","zh":"申请背调前，先确认该岗位允许核查哪些项目。"}},{"id":"HR022","moduleId":"m1","module":"招聘与人才获取","term":"Candidate experience","zh":"候选人体验","definition":"候选人在了解职位、申请、面试和接收录用决定等招聘环节中的整体感受。","example":"Timely updates can improve the candidate experience.","collocation":"enhance candidate experience","dialogue":[{"role":"Recruiter","en":"A candidate arrived at reception and no one knew whom to call.","zh":"有位候选人到了前台，前台却不知道该联系谁。"},{"role":"Recruiting Coordinator","en":"Let’s put a contact number in every invitation. That would make for a better candidate experience.","zh":"以后每封面试邀请都附上联系电话吧，候选人的体验会好一些。"}],"usage":"","new":false,"order":22,"aliases":[],"distinction":"Candidate experience 关注候选人从了解岗位到收到结果期间的实际感受。Employer brand 是人们对该组织作为雇主的总体印象，招聘体验可能影响这种印象。","collocationZh":"改善候选人体验","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkæn.dɪ.dət ekˈspiərɪəns","ipaUS":"ˈkæn.dɪ.dət ɪkˈspɪriːəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Candidate experience","exampleZh":"及时告知招聘进展有助于改善候选人体验。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How could we improve the candidate experience?","zh":"我们该怎样改善候选人体验？"},"extension":{"en":"Ask rejected applicants what would have improved their candidate experience.","zh":"可以请未获录用的申请人说说，招聘过程中有哪些地方可以改进。"}},{"id":"HR023","moduleId":"m1","module":"招聘与人才获取","term":"Offer letter","zh":"录用通知书","definition":"以书面形式向候选人提出录用，通常载明岗位、薪酬、拟入职日期及适用的录用条件。","example":"Please review the offer letter before sending it to the candidate.","collocation":"issue an offer letter","dialogue":[{"role":"Candidate","en":"The offer letter says I’ll start on the fifth. Could we move that to the twelfth?","zh":"录用通知书写的是五号入职。能改到十二号吗？"},{"role":"Recruiter","en":"I’ll ask the team. If they can move it, I’ll send you a revised letter.","zh":"我去和团队确认。如果日期能改，我会发给您更新后的录用通知书。"}],"usage":"","new":false,"order":23,"aliases":[],"distinction":"Offer letter 书面告知岗位、薪酬或录用条件。Employment contract 约定雇佣关系中的权利义务。两类文件的内容可能重叠，法律效力取决于适用法律及具体条款。","collocationZh":"发放录用通知书","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈɒfə ˈletə","ipaUS":"ˈɔːfɚ ˈletɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Offer letter","exampleZh":"将录用通知书发送给候选人前，请先审核。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Is the offer letter ready to send?","zh":"录用通知书可以发送了吗？"},"extension":{"en":"Make sure the offer letter states when the candidate needs to respond.","zh":"请确认录用通知书写明候选人应在何时答复。"}},{"id":"HR024","moduleId":"m1","module":"招聘与人才获取","term":"Compensation expectations","zh":"薪酬期望","definition":"候选人对拟入职岗位报酬的预期，可包括基本工资、奖金及其他薪酬项目。","example":"We discussed the candidate’s compensation expectations in the first interview.","collocation":"clarify compensation expectations","dialogue":[{"role":"Recruiter","en":"You mentioned a figure of 90,000. Is that base salary or total cash compensation?","zh":"您刚才提到九万，指的是基本工资，还是现金薪酬总额？"},{"role":"Candidate","en":"That’s the base salary I’m looking for. I’d consider the bonus separately.","zh":"那是我期望的基本工资。奖金我会单独考虑。"}],"usage":"","new":false,"order":24,"aliases":[],"distinction":"Compensation expectations 指候选人对新岗位整体薪酬的预期，可能包括奖金或股权。Salary expectations 多指期望工资。Salary history 指候选人过去或目前的薪资，询问这类信息可能受当地法规限制。","collocationZh":"明确候选人的薪酬期望","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌkɒm.penˈseɪ.ʃən ˌek.spekˈteɪ.ʃənz","ipaUS":"ˌkɑːm.penˈseɪ.ʃən ˌek.spekˈteɪ.ʃənz","ipaSource":"https://dictionary.cambridge.org/dictionary/english/compensation | https://dictionary.cambridge.org/dictionary/english/expectation","speakTerm":"Compensation expectations","exampleZh":"我们在首轮面试中讨论了这位候选人的薪酬期望。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When should we discuss the candidate's compensation expectations?","zh":"我们应该在什么时候讨论候选人的薪酬期望？"},"extension":{"en":"Share the approved pay range before asking about compensation expectations.","zh":"在询问候选人的薪酬期望前，先告知已获批的薪资区间。"},"searchAliases":["Compensation expectation"]},{"id":"HR025","moduleId":"m1","module":"招聘与人才获取","term":"Salary negotiation","zh":"薪资谈判","definition":"候选人与雇主围绕基本工资等薪资条件进行协商的过程。","example":"Salary negotiations with our preferred candidate are still underway.","collocation":"lead salary negotiations","dialogue":[{"role":"Candidate","en":"I’m excited about the role. Is there room to move on the base salary?","zh":"我很期待这个岗位。基本工资还有商量的余地吗？"},{"role":"Recruiter","en":"Possibly. What figure would make the move worthwhile for you?","zh":"也许有。基本工资要到多少，您才觉得值得换工作？"}],"usage":"","new":false,"order":25,"aliases":[],"distinction":"Salary negotiation 通常围绕基本工资或约定工资金额。Compensation negotiation 范围更广，也可涉及奖金、股权或福利。Salary review 指组织重新评估工资水平。","collocationZh":"主导薪资谈判","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsæl.ər.i nɪˌɡəʊʃɪˈeɪʃən","ipaUS":"ˈsæl.ɚ.i nɪˌɡoʊʃiːˈeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Salary negotiation","exampleZh":"我们仍在与首选候选人进行薪资谈判。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Have we agreed on the salary with our preferred candidate?","zh":"我们已经与首选候选人谈妥薪资了吗？"},"extension":{"en":"Bring the approved pay range to the salary negotiation.","zh":"进行薪资谈判时，请带上已获批的薪资区间。"}},{"id":"HR026","moduleId":"m1","module":"招聘与人才获取","term":"Notice period","zh":"离职／解雇通知期","definition":"员工辞职或雇主终止雇佣时，按适用法律或合同约定应提前通知对方的期限。","example":"The candidate has a one-month notice period at the current company.","collocation":"confirm the notice period","dialogue":[{"role":"Recruiter","en":"Our next onboarding session is on the third. Would that work for you?","zh":"我们下次入职培训在三号，您来得及参加吗？"},{"role":"Candidate","en":"My notice period ends on the fifth. Is there another session later that month?","zh":"我的离职通知期五号才结束。那个月稍晚还有一场吗？"}],"usage":"在不同法律体系下适用范围、期限及安排不同，不一定只指员工主动辞职。","new":false,"order":26,"distinction":"Notice period 是终止雇佣前适用的提前通知期限。Garden leave 在一些法域或合约中指通知期内保留雇佣关系、通常仍领薪但无须正常上班的安排。","aliases":[],"collocationZh":"确认离职通知期","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈnəʊtɪs ˈpiərɪəd","ipaUS":"ˈnoʊtəs ˈpɪriːəd","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Notice period","exampleZh":"该候选人在现公司需履行一个月的离职通知期。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How soon can the selected candidate join?","zh":"被录用的候选人最早什么时候可以入职？"},"extension":{"en":"Ask the candidate to confirm the end date of their notice period.","zh":"请候选人确认其离职通知期的结束日期。"}},{"id":"HR027","moduleId":"m1","module":"招聘与人才获取","term":"Onboarding","zh":"新员工入职与融入","definition":"新员工完成入职手续、了解制度、熟悉岗位并逐步融入团队的过程。","example":"The onboarding plan includes a buddy and first-week check-ins.","collocation":"improve onboarding","dialogue":[{"role":"New Hire","en":"I’ve finished the onboarding modules. Could I sit in on a customer call this week?","zh":"我已经学完入职培训模块了，本周能旁听一次客户电话吗？"},{"role":"Team Lead","en":"Sure. Join Nina on Thursday, and she’ll walk you through the account beforehand.","zh":"可以。周四跟妮娜一起参加，她会事先给你介绍这个客户。"}],"usage":"区别于仅签合同或录入系统的入职手续。","new":false,"order":27,"distinction":"Onboarding 是新员工从手续办理到熟悉岗位、融入团队的过程。Orientation 通常是一场或一段集中入职介绍，preboarding 侧重正式到岗前的准备。","aliases":[],"collocationZh":"完善新员工入职与融入流程","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɒnˈbɔː.dɪŋ","ipaUS":"ɑːnˈbɔːr.dɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Onboarding","exampleZh":"入职计划包括安排一名入职伙伴，并在第一周定期沟通。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we helping the new joiner settle in?","zh":"我们如何帮助新员工尽快适应和融入？"},"extension":{"en":"A good onboarding plan tells new hires who to ask for help.","zh":"一份好的入职计划会告诉新员工遇到问题该找谁。"}},{"id":"HR028","moduleId":"m1","module":"招聘与人才获取","term":"Probation period","zh":"试用期","definition":"在适用法律及雇佣安排下设立的入职初期阶段，用于评估员工与岗位的匹配度。","example":"We will review performance near the end of the probation period.","collocation":"complete the probation period","dialogue":[{"role":"New Hire","en":"I’m halfway through my probation period. Could we go over how I’m doing on the reporting tasks?","zh":"我的试用期过了一半，能聊聊我在报表工作上的表现吗？"},{"role":"Manager","en":"Let’s look at the last two reports together and agree on what to work on next.","zh":"我们一起看看最近两份报表，再定一下接下来要改进什么。"}],"usage":"","new":false,"order":28,"aliases":[],"distinction":"Probation period 是新雇佣关系中的试用阶段。Onboarding 帮助员工熟悉岗位并融入团队，可与试用期重合。","collocationZh":"完成试用期","collocationReview":"V18.2 模型编辑复核","ipaUK":"prəʊˈbeɪʃən ˈpiərɪəd","ipaUS":"proʊˈbeɪʃən ˈpɪriːəd","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Probation period","exampleZh":"我们会在试用期即将结束时评估其工作表现。","exampleReview":"语义修订","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When will we review the new employee's performance?","zh":"什么时候评估这名新员工的工作表现？"},"extension":{"en":"Explain the probation period and the review process before the employee starts.","zh":"员工到岗前，请说明试用期及其评估流程。"}},{"id":"HR029","moduleId":"m1","module":"招聘与人才获取","term":"Time to fill","zh":"岗位填补周期","definition":"从招聘需求获批／职位开放到候选人接受录用等特定终点的时间；统计起止点需统一。","example":"Our time to fill decreased after we streamlined approvals.","collocation":"reduce time to fill","dialogue":[{"role":"Recruiting Analyst","en":"The search was paused for two weeks. Do we count those days in time to fill?","zh":"这个岗位的寻访暂停了两周。计算岗位填补周期时，这些天算进去吗？"},{"role":"Talent Acquisition Lead","en":"Our dashboard counts calendar days from approval to offer acceptance, so include them and flag the pause.","zh":"我们的看板从招聘获批到接受录用按自然日计算，所以要算进去，并标注暂停情况。"}],"usage":"HR 指标 time-to-fill 不是 time-to-hire。","new":false,"order":29,"distinction":"Time to fill 以岗位为统计对象，常从招聘申请获批或开放招聘算起。Time to hire 以候选人为统计对象，常从其进入流程算起。两项指标通常都可用接受录用为终点，比较时应统一实际采用的口径。","aliases":[],"collocationZh":"缩短岗位填补周期","collocationReview":"V18.2 模型编辑复核","ipaUK":"taɪm tuː fɪl","ipaUS":"taɪm tuː fɪl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Time to fill","exampleZh":"简化审批流程后，我们的岗位填补周期缩短了。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Did the streamlined approvals improve hiring speed?","zh":"审批流程简化后，招聘速度是否有所提升？"},"extension":{"en":"Report time to fill separately for specialist and high-volume roles.","zh":"请分别汇报专业岗位和批量招聘岗位的填补周期。"}},{"id":"HR030","moduleId":"m1","module":"招聘与人才获取","term":"Quality of hire","zh":"招聘质量","definition":"衡量录用成效的指标或一组指标，通常依据入职后一段时间的表现、留任等信息，具体口径因组织而异。","example":"Our quality-of-hire measure combines six-month performance and retention.","collocation":"measure quality of hire","dialogue":[{"role":"Recruiter","en":"We have the six-month retention figures. Is that enough for the quality-of-hire review?","zh":"我们拿到了六个月留任率的数据。用来评估招聘质量够吗？"},{"role":"People Analyst","en":"Let’s add the six-month performance ratings, where available, and show how many are missing.","zh":"也把能拿到的六个月绩效评分加进去，再注明有多少人缺少评分。"}],"usage":"指标没有全球统一计算公式，常结合试用表现、绩效、留任等维度。","new":false,"order":30,"aliases":[],"distinction":"Quality of hire 衡量录用后的成效，可结合岗位表现、上手速度或一段时期内的留任情况。Time to fill 衡量岗位填补速度。质量指标的维度、权重和观察期由组织定义。","collocationZh":"衡量招聘质量","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkwɒlɪti ɒv ˈhaɪə","ipaUS":"ˈkwɑːlətiː ʌv ˈhaɪɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Quality of hire","exampleZh":"我们的招聘质量指标综合考虑入职六个月时的表现和留任情况。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Should we focus only on how quickly we fill positions?","zh":"我们是否应该只关注岗位填补速度？"},"extension":{"en":"Use the same follow-up period when comparing quality of hire across teams.","zh":"比较不同团队的招聘质量时，应使用相同的入职后观察期。"}},{"id":"HR1-31","moduleId":"m1","module":"招聘与人才获取","term":"Talent acquisition","zh":"人才获取（TA）","definition":"为满足组织当前及未来的人才需求而开展的工作，可涵盖雇主品牌、候选人寻访、甄选及录用等环节。","example":"Our talent acquisition strategy focuses on engineering skills that are hard to find in the market.","collocation":"talent acquisition strategy","dialogue":[{"role":"Engineering Director","en":"We’re opening a second site next year. Can we start meeting local engineers before the roles go live?","zh":"我们明年要开设第二个站点。职位发布前，能先和当地工程师建立联系吗？"},{"role":"Talent Acquisition Lead","en":"Yes. I’ll add the new site to our talent acquisition plan and look for local meetups we can attend.","zh":"可以。我会把新站点纳入人才获取计划，再找找我们可以参加的当地专业交流活动。"}],"usage":"常用缩写 TA，中文可直接说“人才招聘”。","new":true,"order":31,"distinction":"Talent acquisition 和 recruitment 在实际使用中常重叠。企业谈 talent acquisition strategy 时，往往也涉及长期人才供给、人才寻访和雇主品牌。Recruitment 常用于具体职位的招聘工作。","aliases":["TA","人才招聘"],"collocationZh":"人才获取策略","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtæl.ənt ˌæk.wɪˈzɪʃ.ən","ipaUS":"ˈtæl.ənt ˌæk.wəˈzɪʃ.ən","ipaSource":"https://dictionary.cambridge.org/dictionary/english/talent | https://dictionary.cambridge.org/dictionary/english/acquisition","speakTerm":"Talent acquisition","exampleZh":"我们的人才获取策略重点关注市场上紧缺的工程技能。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How is our talent acquisition strategy changing this year?","zh":"我们今年的人才招聘策略会有哪些变化？"},"extension":{"en":"Our talent acquisition team meets with business leaders before setting next year’s hiring priorities.","zh":"确定明年招聘重点前，我们的人才获取团队会和业务负责人沟通。"}},{"id":"HR1-32","moduleId":"m1","module":"招聘与人才获取","term":"Time to hire","zh":"候选人招聘周期","definition":"从候选人进入招聘流程到接受录用的时间长度（或企业定义的其他终点）。","example":"We reduced time to hire by simplifying interview scheduling.","collocation":"reduce time to hire","dialogue":[{"role":"Recruiter","en":"I first contacted her in March, but she applied in May. Which date should I use?","zh":"我三月第一次联系她，但她五月才申请。该用哪个日期？"},{"role":"Recruiting Analyst","en":"Use May. For this report, time to hire starts on the application date.","zh":"用五月的申请日期。这份报告从申请日开始计算候选人招聘周期。"}],"usage":"衡量候选人阶段的招聘效率。","new":true,"order":32,"distinction":"Time to hire 从候选人进入流程算起，例如提交申请或被纳入招聘流程。Time to fill 从岗位层面计时，例如从招聘申请获批算起。两者常以接受录用为终点，分析前需确认内部口径。","aliases":[],"collocationZh":"缩短候选人招聘周期","collocationReview":"V18.2 模型编辑复核","ipaUK":"taɪm tuː ˈhaɪə","ipaUS":"taɪm tuː ˈhaɪɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Time to hire","exampleZh":"简化面试安排后，我们缩短了候选人招聘周期。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we reduce time to hire without compromising quality?","zh":"如何在不降低招聘质量的前提下缩短招聘周期？"},"extension":{"en":"Break down time to hire by interview stage to see where candidates wait the longest.","zh":"按面试阶段拆分候选人招聘周期，找出候选人等待最久的环节。"}},{"id":"HR1-33","moduleId":"m1","module":"招聘与人才获取","term":"Sourcing channel","zh":"人才寻访渠道","definition":"招聘人员用于发现并接触潜在候选人的渠道，如人才平台、专业社群及员工内推。","example":"We compare sourcing channels to improve the candidate pipeline.","collocation":"evaluate sourcing channels","dialogue":[{"role":"Recruiter","en":"Most of these specialists came from a trade association’s mailing list. Can we track that separately?","zh":"这批专业人才大多来自行业协会的邮件列表，能单独统计吗？"},{"role":"Recruiting Analyst","en":"Yes. I’ll add it as a sourcing channel so we can see how many reach the interview stage.","zh":"可以。我会把它加为一个寻访渠道，看有多少人能进入面试。"}],"usage":"","new":true,"order":33,"aliases":[],"distinction":"Sourcing channel 是找到或接触人选的渠道，如专业社群和员工内推。Source of hire 是录用后归因到的来源，通常根据组织的归因规则记录。","collocationZh":"评估人才寻访渠道","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsɔːsɪŋ ˈtʃænəl","ipaUS":"ˈsɔːrsɪŋ ˈtʃænəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Sourcing channel","exampleZh":"我们比较不同寻访渠道的效果，以改善候选人在各招聘阶段的供给情况。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which sourcing channel brings us the most qualified candidates?","zh":"哪个人才寻访渠道为我们带来了最多合格候选人？"},"extension":{"en":"Record the sourcing channel when you add a prospect to the system.","zh":"将潜在人选录入系统时，请记录是通过什么渠道找到的。"}},{"id":"HR1-34","moduleId":"m1","module":"招聘与人才获取","term":"Employee referral","zh":"员工内推","definition":"在职员工向组织推荐外部潜在候选人的做法，也可指一次具体推荐。","example":"Employee referrals account for a quarter of our new hires.","collocation":"employee referral program","dialogue":[{"role":"Employee","en":"A former teammate is interested in the analyst role. She already applied online. Can I still refer her?","zh":"我之前的一位同事对分析师岗位有兴趣，她已经在线申请了。我还能内推她吗？"},{"role":"Recruiter","en":"Send me the job ID. I’ll check what our employee referral policy says about existing applications.","zh":"把岗位编号发给我吧。我查一下内推政策，看已提交的申请怎么处理。"}],"usage":"","new":true,"order":34,"aliases":[],"distinction":"Employee referral 是在职员工推荐潜在人选，通常发生在招聘前期。Reference check 是招聘方联系职业推荐人，了解候选人的过往工作表现。","collocationZh":"员工内推计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː rɪˈfɜːrəl","ipaUS":"ɪmˈplɔɪ.iː rɪˈfɝːəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee referral","exampleZh":"员工内推占我们新入职人数的四分之一。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Is our employee referral program meeting its targets?","zh":"我们的员工内推计划达到预定目标了吗？"},"extension":{"en":"Track which employee referrals progress beyond the initial screen.","zh":"跟踪哪些内推候选人通过了初筛。"}},{"id":"HR1-35","moduleId":"m1","module":"招聘与人才获取","term":"Candidate pipeline","zh":"候选人储备（按招聘阶段跟进）","definition":"针对某个岗位或岗位类别持续识别、跟进的人选及其所处的招聘阶段。","example":"We have several candidates in the pipeline for senior roles, but only one has reached the final interview stage.","collocation":"build a candidate pipeline","dialogue":[{"role":"Hiring Manager","en":"Two candidates cleared the technical exercise. Should I keep Friday afternoon free?","zh":"有两位候选人通过了技术测评。我要把周五下午空出来吗？"},{"role":"Recruiter","en":"Yes. One is ready to book, and I’ll check the other’s availability before updating the candidate pipeline.","zh":"要的。一位已经可以约面试，我确认另一位的时间后会更新候选人进度。"}],"usage":"通常可在 ATS 中按候选人阶段跟踪。","new":true,"order":35,"distinction":"Candidate pipeline 强调各招聘阶段中有哪些人以及人选如何推进。Talent pool 侧重可供今后联系的人选储备。Recruitment funnel 用人数和转化率分析阶段间的变化。","aliases":[],"collocationZh":"建立并持续跟进候选人储备","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkæn.dɪ.dət ˈpaɪplaɪn","ipaUS":"ˈkæn.dɪ.dət ˈpaɪplaɪn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Candidate pipeline","exampleZh":"我们正在跟进几位高级岗位的候选人，但只有一位进入了终面阶段。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Do we have enough candidates in the pipeline for this role?","zh":"这个岗位的候选人储备是否充足？"},"extension":{"en":"Review the candidate pipeline before committing to an interview date with the hiring team.","zh":"和用人团队敲定面试日期前，先看看各阶段有多少候选人。"}},{"id":"HR1-36","moduleId":"m1","module":"招聘与人才获取","term":"Talent mapping","zh":"人才地图梳理","definition":"在招聘中，系统了解目标地区、行业和企业中的相关人才分布，为后续寻访提供线索。","example":"Talent mapping helps us identify experts in emerging markets.","collocation":"conduct talent mapping","dialogue":[{"role":"Recruiter","en":"The two companies on our list are both hiring for the same skills. Where else could we look?","zh":"名单上的两家公司也在招具备同样技能的人。我们还能去哪里找？"},{"role":"Sourcer","en":"I’ll broaden the talent mapping to suppliers and smaller firms that use the same technology.","zh":"我会扩大人才地图的范围，把采用同类技术的供应商和较小的公司也梳理进去。"}],"usage":"","new":true,"order":36,"aliases":[],"distinction":"Talent mapping 在本招聘语境中侧重摸清目标市场的人才分布。Candidate sourcing 侧重找人和接触人选，talent map 是这类梳理形成的图表或名单。","collocationZh":"绘制人才地图","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtæl.ənt ˈmæpɪŋ","ipaUS":"ˈtæl.ənt ˈmæpɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Talent mapping","exampleZh":"梳理人才地图有助于我们识别新兴市场中的专家。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Why are we conducting talent mapping before the search?","zh":"为什么在正式寻访之前要绘制人才地图？"},"extension":{"en":"Use talent mapping to see which cities have the skills this team needs.","zh":"通过人才地图梳理，了解哪些城市有团队所需技能的人才。"}},{"id":"HR1-37","moduleId":"m1","module":"招聘与人才获取","term":"Interview scorecard","zh":"面试评分表","definition":"按统一维度记录候选人面试评分及相关证据的表格。","example":"Please complete the interview scorecard before the debrief.","collocation":"complete an interview scorecard","dialogue":[{"role":"Interviewer","en":"We ran out of time before I could assess the candidate’s writing. Should I leave that row blank?","zh":"时间到了，我还没考察候选人的写作能力。评分表上这一行要留空吗？"},{"role":"Recruiter","en":"Mark it as “not assessed” on the interview scorecard. We’ll cover writing in the next round.","zh":"在面试评分表上标为“未评估”吧。下一轮再考察写作。"}],"usage":"","new":true,"order":37,"aliases":[],"distinction":"Interview scorecard 用来按考察维度记录评分和证据。Interview guide 帮助面试官提问和推进流程，scoring rubric 说明各档评分所对应的表现。","collocationZh":"填写面试评分表","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈɪn.tə.vjuː ˈskɔːkɑːd","ipaUS":"ˈɪn.tɚ.vjuː ˈskɔːrkɑːrd","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Interview scorecard","exampleZh":"请在面试复盘会前填写面试评分表。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Have all interviewers submitted their scorecards?","zh":"所有面试官都提交面试评分表了吗？"},"extension":{"en":"Add a concrete example to support each rating on the interview scorecard.","zh":"请在面试评分表上为每项评分补充一个具体事例。"}},{"id":"HR1-38","moduleId":"m1","module":"招聘与人才获取","term":"Hiring freeze","zh":"招聘冻结","definition":"组织在一定时期内暂停或限制部分或全部岗位招聘的措施，适用范围和例外依组织政策而定。","example":"Under our hiring freeze, critical vacancies can proceed only with an approved exception.","collocation":"temporary hiring freeze","dialogue":[{"role":"Hiring Manager","en":"Our analyst is leaving next month. Can I open a requisition for a replacement?","zh":"我们的分析师下个月离职。我能提交补缺申请吗？"},{"role":"HRBP","en":"Let’s check the hiring freeze memo. It should tell us whether backfills need an exception.","zh":"先看看招聘冻结通知吧，上面应该有补缺是否需要特批的说明。"}],"usage":"","new":true,"order":38,"aliases":[],"distinction":"Hiring freeze 暂停或限制特定范围内的招聘，可涉及新增或补缺岗位。Headcount freeze 侧重限制编制增长，在组织政策允许时仍可能补缺。个别岗位的例外以书面政策或审批结果为准。","collocationZh":"临时招聘冻结","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈhaɪərɪŋ friːz","ipaUS":"ˈhaɪrɪŋ friːz","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Hiring freeze","exampleZh":"按我们的招聘冻结规定，关键空缺岗位也要获得例外审批才能继续招聘。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Does the hiring freeze apply to this replacement role?","zh":"招聘冻结政策是否适用于这个补缺岗位？"},"extension":{"en":"Check whether the hiring freeze covers vacancies that are already advertised.","zh":"请确认招聘冻结是否适用于已经发布招聘公告的岗位。"}},{"id":"HR1-39","moduleId":"m1","module":"招聘与人才获取","term":"Contingent worker","zh":"灵活用工人员","definition":"组织为短期、阶段性或按需工作使用的人员。所涉用工形式及法律身份随组织口径和适用规则而异。","example":"For this project, we brought in two contingent workers through an approved staffing agency.","collocation":"contingent workforce","dialogue":[{"role":"Project Manager","en":"We need someone to cover the data migration for six weeks. Can I ask our staffing agency for help?","zh":"数据迁移需要有人负责六周。我可以请人力服务机构帮忙吗？"},{"role":"HRBP","en":"I’ll check which staffing arrangement fits the work and confirm the local requirements before we contact the agency.","zh":"我先确认哪种用工安排适合这项工作，再核对当地要求，然后联系机构。"}],"usage":"","new":true,"order":39,"aliases":[],"distinction":"Contingent worker 通常指按短期或特定需求安排工作的人员。Independent contractor 是基于工作关系实际情况及当地规则认定的类别，agency worker 则通常经用工机构派驻。","collocationZh":"灵活用工人员群体","collocationReview":"V18.2 模型编辑复核","ipaUK":"kənˈtɪndʒənt ˈwɜːkə","ipaUS":"kənˈtɪndʒənt ˈwɝːkɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Contingent worker","exampleZh":"这个项目通过一家获准合作的人力服务机构引入了两位灵活用工人员。","meaningReview":"HR场景校订","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can we use a contingent worker for this short-term project?","zh":"这个短期项目能否使用灵活用工人员？"},"extension":{"en":"Confirm who will supervise the contingent worker before the project starts.","zh":"项目开始前，请确认由谁负责指导这位灵活用工人员的日常工作。"}},{"id":"HR1-40","moduleId":"m1","module":"招聘与人才获取","term":"Recruitment funnel","zh":"招聘漏斗","definition":"用各阶段人数和相邻阶段转化率呈现招聘进程的分析方法，具体起止环节可按组织口径设定。","example":"Our recruitment funnel shows a drop-off after the technical test.","collocation":"recruitment funnel conversion rate","dialogue":[{"role":"Recruiter","en":"Applications doubled, but we’ve booked about the same number of interviews as last month.","zh":"申请量翻了一倍，约到的面试却和上月差不多。"},{"role":"Recruiting Analyst","en":"Let’s split the recruitment funnel by source and see where the extra applications are dropping out.","zh":"我们按渠道拆开看招聘漏斗，查查多出来的申请主要在哪一步没能往下走。"}],"usage":"","new":true,"order":40,"aliases":[],"distinction":"Recruitment funnel 看各招聘阶段的人数和转化率，帮助定位流失或淘汰集中在哪一环。Candidate pipeline 更侧重哪些候选人在各阶段，以及如何推进。","collocationZh":"招聘漏斗转化率","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˈkruːtmənt ˈfʌnəl","ipaUS":"rəˈkruːtmənt ˈfʌnəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Recruitment funnel","exampleZh":"招聘漏斗显示，技术测试过后，进入后续环节的人数明显减少。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Where are candidates dropping out of our recruitment funnel?","zh":"候选人主要在哪个招聘漏斗环节退出？"},"extension":{"en":"Use the recruitment funnel to track how many written offers are accepted.","zh":"用招聘漏斗跟踪有多少份书面录用通知被接受。"}},{"id":"HR031","moduleId":"m2","module":"薪酬激励与福利","term":"Base salary","zh":"基本工资","definition":"员工按约定定期获得的固定基本工资，通常与奖金、提成等浮动报酬分开列示。","example":"The base salary for this position is reviewed annually.","collocation":"adjust the base salary","dialogue":[{"role":"Candidate","en":"The recruiter quoted 95,000. Does that include the annual bonus?","zh":"招聘专员报的是九万五，里面包含年度奖金吗？"},{"role":"Compensation Partner","en":"No, that’s the base salary. I’ll send you the bonus terms separately.","zh":"九万五是基本工资，我会另外把奖金条款发给您。"}],"usage":"","new":false,"order":41,"aliases":[],"distinction":"Base salary 是约定的固定基本工资。Gross pay 是某个工资期扣款前的工资总额，可包括基本工资和当期奖金。Total cash compensation 则综合计算固定和浮动现金薪酬。","collocationZh":"调整基本工资","collocationReview":"V18.2 模型编辑复核","ipaUK":"beɪs ˈsæl.ər.i","ipaUS":"beɪs ˈsæl.ɚ.i","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Base salary","exampleZh":"该岗位的基本工资每年评估一次。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Base salary","note":"约定的固定基本工资。","relation":"本词"},{"term":"Gross pay","note":"某个工资期内扣税及其他扣款前的工资总额，可包括当期奖金等。","relation":"易混淆"},{"term":"Total cash compensation","note":"固定现金薪酬和浮动现金薪酬的合计。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"How often do we review the base salary for this role?","zh":"这个岗位的基本工资多久审核一次？"},"extension":{"en":"Quote base salary and target bonus separately in the offer.","zh":"在录用条件中分别列明基本工资和目标奖金。"}},{"id":"HR032","moduleId":"m2","module":"薪酬激励与福利","term":"Gross salary","zh":"税前工资","definition":"扣除个人适用税费及其他工资扣款前的工资金额。","example":"The offer letter lists the annual gross salary.","collocation":"calculate gross salary","dialogue":[{"role":"Employee","en":"My payslip shows a bigger amount than the deposit in my account. Which figure should I use on this form?","zh":"工资单上有个金额比到账金额高。这张表应该填哪个？"},{"role":"Payroll Specialist","en":"If the form asks for gross salary, use the amount before deductions. Check whether it wants a monthly or annual figure.","zh":"如果表格要求填税前工资，就填扣款前的金额，再确认它要的是月薪还是年薪。"}],"usage":"税前工资；与 Net pay（扣除税费和其他扣款后的实发工资）区分。","new":false,"order":42,"aliases":[],"distinction":"Gross salary 或 gross pay 的计算口径是扣款前。Base salary 区分的是固定工资与其他报酬项目，net pay 则是扣除适用税费及其他扣款后的实发金额。","collocationZh":"计算税前工资","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɡrəʊs ˈsæl.ər.i","ipaUS":"ɡroʊs ˈsæl.ɚ.i","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Gross salary","exampleZh":"录用通知书列明了税前年薪。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Gross salary","note":"扣除税费及其他工资扣款前的工资金额。","relation":"本词"},{"term":"Base salary","note":"约定的固定基本工资，侧重报酬构成。","relation":"易混淆"},{"term":"Net pay","note":"扣除适用税费及其他扣款后的实发金额。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Which salary amount is stated in the employment offer?","zh":"录用通知中列明的是哪一项工资金额？"},"extension":{"en":"Check your gross salary after a pay rise to make sure the new rate has been applied.","zh":"加薪后，请核对税前工资，确认已按新的工资标准发放。"}},{"id":"HR033","moduleId":"m2","module":"薪酬激励与福利","term":"Net pay","zh":"实发工资","definition":"扣除适用税费及扣款后的到手金额。","example":"Your net pay may change when your tax withholding changes.","collocation":"check net pay","dialogue":[{"role":"Employee","en":"My overtime is on the payslip, but the deposit is smaller than last month. Could you take a look?","zh":"工资单上已经列了加班工资，但到账金额比上个月少。能帮忙看一下吗？"},{"role":"Payroll Specialist","en":"Sure. Let’s compare the deductions on both payslips and see what changed in your net pay.","zh":"可以。我们对比两个月工资单上的扣款，看看是哪项变化影响了实发工资。"}],"usage":"实发金额不一定等于净收入；扣款项目随国家、地区与个人情况变化。","new":false,"order":43,"aliases":[],"distinction":"Net pay 指工资单上的实发金额，口语也常称 take-home pay。Gross pay 是扣款前的总额。只看税后金额时，还需留意工资单是否列有其他扣款。","collocationZh":"核对实发工资","collocationReview":"V18.2 模型编辑复核","ipaUK":"net peɪ","ipaUS":"net peɪ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Net pay","exampleZh":"当预扣税款发生变化时，您的实发工资也可能改变。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Net pay","note":"扣除适用税费及其他工资扣款后的实发金额，也称 take-home pay。","relation":"本词"},{"term":"Gross pay","note":"扣款前的工资总额，可能含当期奖金、提成或加班报酬。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Why might an employee's take-home pay change?","zh":"员工的税后实发工资为什么可能发生变化？"},"extension":{"en":"Compare your net pay with the deposit shown on your bank statement.","zh":"请将工资单上的实发工资与银行账单中的到账金额核对一下。"}},{"id":"HR034","moduleId":"m2","module":"薪酬激励与福利","term":"Total rewards","zh":"全面回报","definition":"组织为员工提供的整体回报，通常涵盖薪酬、福利、认可及职业发展等有形或无形回报。","example":"Our total rewards approach includes benefits and career development.","collocation":"total rewards strategy","dialogue":[{"role":"Employee","en":"I noticed the company’s retirement contribution on my total rewards statement. Where can I see how it’s calculated?","zh":"我在全面回报说明单上看到了公司的退休计划缴费。在哪里能看到计算方法？"},{"role":"Rewards Partner","en":"It’s in the retirement plan guide under employer contributions. I’ll send you the link to that section.","zh":"在退休计划指南的“雇主缴费”一节里，我把那一节的链接发给你。"}],"usage":"","new":false,"order":44,"aliases":[],"distinction":"Total rewards 是组织通过工作向员工提供的整体回报，可涵盖薪酬、福利、认可和职业发展。Total cash compensation 聚焦现金报酬，compensation package 通常指为具体岗位或个人拟定的待遇组合。","collocationZh":"全面回报策略","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtəʊtəl rɪˈwɔːdz","ipaUS":"ˈtoʊtəl rɪˈwɔːrdz","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Total rewards","exampleZh":"我们的全面回报体系涵盖员工福利和职业发展机会。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Total rewards","note":"薪酬、福利、认可和职业发展等员工回报的整体安排。","relation":"本词"},{"term":"Total cash compensation","note":"固定与浮动现金薪酬的合计。","relation":"易混淆"},{"term":"Compensation package","note":"通常指具体岗位或个人的薪酬待遇组合，包含哪些项目取决于组织和方案。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Does our total rewards approach cover development opportunities?","zh":"我们的全面薪酬回报体系是否包含职业发展机会？"},"extension":{"en":"Use the total rewards statement to show employees the value of their benefits.","zh":"可以通过全面回报说明单向员工展示各项福利的价值。"}},{"id":"HR035","moduleId":"m2","module":"薪酬激励与福利","term":"Compensation package","zh":"薪酬待遇组合","definition":"针对具体岗位或个人拟定的综合报酬安排，可包括基本工资、奖金、股权及福利，具体项目视方案而定。","example":"We put together a competitive compensation package for our preferred candidate.","collocation":"review a compensation package","dialogue":[{"role":"Candidate","en":"Does the compensation package include help with relocation?","zh":"这套薪酬待遇包含搬迁支持吗？"},{"role":"Recruiter","en":"I’ll check what’s available for this role. If it’s approved, I’ll spell it out separately in the offer letter.","zh":"我去确认这个岗位能提供哪些搬迁支持。如果获批，我会在录用通知书里另行写明。"}],"usage":"","new":false,"order":45,"aliases":[],"distinction":"Compensation package 是为具体岗位或个人列出的薪酬待遇组合。Base salary 只是其中的固定工资项目。Total rewards 范围通常还包括职业发展、认可等更广泛的员工回报。","collocationZh":"审阅薪酬待遇组合","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌkɒmpənˈseɪʃən ˈpækɪdʒ","ipaUS":"ˌkɑːmpənˈseɪʃən ˈpækədʒ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Compensation package","exampleZh":"我们为首选候选人拟定了一套有竞争力的薪酬待遇方案。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Compensation package","note":"针对具体岗位或个人的待遇组合，可包括工资、奖金、股权和福利。","relation":"本词"},{"term":"Base salary","note":"待遇组合中的固定基本工资。","relation":"易混淆"},{"term":"Total rewards","note":"组织提供的整体员工回报，可包含薪酬之外的认可和职业发展机会。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"What are we offering the final candidate?","zh":"我们向最终候选人提供怎样的薪酬方案？"},"extension":{"en":"Separate guaranteed pay from performance-based awards when explaining the compensation package.","zh":"介绍薪酬待遇组合时，请分别说明有保障的报酬和按绩效发放的奖励。"}},{"id":"HR036","moduleId":"m2","module":"薪酬激励与福利","term":"Salary band","zh":"薪资区间","definition":"薪酬体系为某岗位或薪级设定的基本薪资区间，通常有明确的上下限。","example":"The proposed starting salary falls within the updated salary band.","collocation":"review salary bands","dialogue":[{"role":"Recruiter","en":"The candidate is asking for a figure above our posted range. Do we have any room to move?","zh":"候选人的薪资要求超过了公布的区间。我们还有调整空间吗？"},{"role":"Compensation Partner","en":"Let me check the current salary band. We may have posted the old range.","zh":"我核对一下现行薪资区间。我们可能公布的是旧区间。"}],"usage":"","new":false,"order":46,"aliases":[],"distinction":"Salary band 指岗位或薪级对应的基本薪资上下限。Pay grade 是薪酬体系中的等级，一个等级通常对应一个区间。Pay range 常与 salary band 互用。","collocationZh":"审查薪资区间","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsæl.ər.i bænd","ipaUS":"ˈsæl.ɚ.i bænd","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Salary band","exampleZh":"拟定的起薪在更新后的薪资区间内。","exampleReview":"语义修订","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Salary band","note":"岗位或等级对应的薪资区间。","relation":"本词"},{"term":"Pay grade","note":"薪酬等级，通常关联一个薪资区间。","relation":"易混淆"},{"term":"Pay range midpoint","note":"薪资区间中点。","relation":"易混淆"},{"term":"Compa-ratio","note":"员工基本薪资除以适用薪资区间中点，采用同一计薪周期和币种。","relation":"易混淆"},{"term":"Salary range penetration","note":"员工基本薪资减去区间下限后，除以区间上限与下限之差，金额应使用相同口径。","relation":"易混淆"},{"term":"Broadbanding","note":"将多个窄薪资等级合并为宽薪资带。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Which salary band applies to this role?","zh":"这个岗位适用哪个薪资区间？"},"extension":{"en":"The salary band for this role has a minimum, a midpoint and a maximum.","zh":"这个岗位的薪资区间设有下限、中点和上限。"}},{"id":"HR037","moduleId":"m2","module":"薪酬激励与福利","term":"Pay grade","zh":"薪级／薪酬等级","definition":"薪酬体系中用于给岗位分级并关联适用薪资区间的等级。","example":"The compensation team assigned the new role to pay grade six.","collocation":"assign a pay grade","dialogue":[{"role":"Hiring Manager","en":"The title hasn’t changed, but the role now supervises six people.","zh":"岗位名称没变，但现在要带六个人。"},{"role":"Compensation Partner","en":"Send me the revised job description. I’ll check whether the responsibilities warrant a different pay grade.","zh":"把更新后的岗位说明书发我。我看看职责变化是否需要调整薪级。"}],"usage":"在岗位薪酬体系中配合 pay range 使用。","new":false,"order":47,"distinction":"Pay grade 是关联薪资区间的薪级，job grade 是依据岗位职责或复杂度等确定的岗位等级。两个等级体系可以一一对应，也可采用其他映射方式，取决于组织设计。","aliases":[],"collocationZh":"确定薪酬等级","collocationReview":"V18.2 模型编辑复核","ipaUK":"peɪ ɡreɪd","ipaUS":"peɪ ɡreɪd","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Pay grade","exampleZh":"薪酬团队将新岗位划入第六薪级。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Salary band","note":"岗位或等级对应的薪资区间。","relation":"易混淆"},{"term":"Pay grade","note":"薪酬等级，通常关联一个薪资区间。","relation":"本词"},{"term":"Pay range midpoint","note":"薪资区间中点。","relation":"易混淆"},{"term":"Compa-ratio","note":"员工基本薪资除以适用薪资区间中点，采用同一计薪周期和币种。","relation":"易混淆"},{"term":"Salary range penetration","note":"员工基本薪资减去区间下限后，除以区间上限与下限之差，金额应使用相同口径。","relation":"易混淆"},{"term":"Broadbanding","note":"将多个窄薪资等级合并为宽薪资带。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Has the new position been assigned a pay grade?","zh":"新岗位已经确定薪酬等级了吗？"},"extension":{"en":"Confirm the pay grade before entering the salary range in the posting.","zh":"把薪资区间填入招聘公告前，先确认薪级。"}},{"id":"HR038","moduleId":"m2","module":"薪酬激励与福利","term":"Salary benchmark","zh":"薪资基准／市场薪资基准","definition":"根据市场数据选定、用于比较某岗位或职级薪资水平的参考值。","example":"We check the salary benchmark before adjusting the pay range.","collocation":"market salary benchmark","dialogue":[{"role":"Hiring Manager","en":"This survey puts the analyst salary much higher than we expected.","zh":"这份调查给出的分析师薪资比我们预想的高很多。"},{"role":"Compensation Partner","en":"That salary benchmark is for senior analysts. I’ll pull the figures for the level we’re hiring at.","zh":"那个薪资基准对应资深分析师。我去找我们实际招聘职级的数据。"}],"usage":"","new":false,"order":48,"aliases":[],"distinction":"Salary benchmark 是用于对照的参考薪资，例如对应岗位的市场中位数。Salary benchmarking 是对标分析过程，salary survey 是获取市场薪资数据的来源之一。","collocationZh":"市场薪资基准","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsæl.ər.i ˈbentʃmɑːk","ipaUS":"ˈsæl.ɚ.i ˈbentʃmɑːrk","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Salary benchmark","exampleZh":"调整薪资区间前，我们会核对市场薪资基准。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Market pricing","note":"依据外部市场数据确定岗位薪酬水平。","relation":"易混淆"},{"term":"Salary benchmark","note":"用于比较的市场薪酬基准。","relation":"本词"},{"term":"Salary survey","note":"收集市场薪酬数据的调查。","relation":"易混淆"},{"term":"Internal equity","note":"关注内部岗位及员工之间的薪酬合理性。","relation":"易混淆"},{"term":"Pay equity","note":"关注薪酬公平，尤其是无不合理差异。","relation":"易混淆"},{"term":"Pay compression","note":"不同经验或职责员工之间的薪酬差距过小。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"How do we compare this role's salary with the market?","zh":"如何将这个岗位的薪资与市场水平进行比较？"},"extension":{"en":"Use a salary benchmark that matches the role’s location and level.","zh":"选用与岗位所在地和职级相匹配的薪资基准。"}},{"id":"HR039","moduleId":"m2","module":"薪酬激励与福利","term":"Market adjustment","zh":"市场调薪","definition":"根据外部劳动力市场的薪资数据，为保持或恢复薪资竞争力而作的调整。","example":"A market adjustment may be needed for scarce technical skills.","collocation":"propose a market adjustment","dialogue":[{"role":"Manager","en":"Two finalists turned down our offers. Both said the pay was below competing offers.","zh":"两位最终候选人都拒绝了录用邀约，说薪资低于其他公司的报价。"},{"role":"Compensation Partner","en":"I’ll check comparable roles in the survey. If the gap is consistent, we can propose a market adjustment.","zh":"我会核对调查里的可比岗位。如果普遍存在差距，我们可以提出市场调薪建议。"}],"usage":"","new":false,"order":49,"aliases":[],"distinction":"Market adjustment 以外部同类岗位的薪资水平为依据。Merit increase 侧重个人绩效，cost-of-living adjustment 则依据生活成本变化。组织可以在同一轮评审中分别处理这些调整。","collocationZh":"提出市场薪酬调整建议","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈmɑːkɪt əˈdʒʌstmənt","ipaUS":"ˈmɑːrkət əˈdʒʌstmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Market adjustment","exampleZh":"对于紧缺技术人才，可能需要进行市场薪酬调整。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Market adjustment","note":"依据外部市场薪酬水平调整薪资，主要关注市场竞争力；不以个人绩效为主要依据，但可与绩效调薪同时实施。","relation":"本词"},{"term":"Merit increase","note":"依据个人绩效决定的加薪。","relation":"易混淆"},{"term":"Salary increase","note":"泛指薪资上涨，不限定原因。","relation":"易混淆"},{"term":"Promotion increase","note":"因晋升而上调基本薪资，是否加薪及金额取决于适用政策。","relation":"易混淆"},{"term":"Cost-of-living adjustment (COLA)","note":"依据生活成本变化调整薪资。","relation":"易混淆"},{"term":"Annual increment","note":"年度常规加薪，是否与绩效挂钩取决于制度。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"How should we respond to the market for scarce technical skills?","zh":"针对市场上稀缺的技术技能，我们该如何调整薪酬？"},"extension":{"en":"The proposed market adjustment applies only to the affected job family.","zh":"拟议的市场调薪只适用于受影响的岗位族。"}},{"id":"HR040","moduleId":"m2","module":"薪酬激励与福利","term":"Internal equity","zh":"内部薪酬公平性","definition":"使组织内部岗位及员工间的薪资关系有合理依据的原则，比较时可考虑职责、经验及绩效等相关因素。","example":"We reviewed the proposed starting salary for internal equity before approving the offer.","collocation":"maintain internal equity","dialogue":[{"role":"Recruiter","en":"Can we offer the finalist the top of the range?","zh":"可以给最终候选人开到薪资区间上限吗？"},{"role":"Compensation Partner","en":"Let’s check internal equity first. We have two people already doing comparable work, and we should understand how their pay was set.","zh":"先核对内部薪酬公平性。已经有两个人在做类似的工作，我们要了解他们目前的薪资是怎么定的。"}],"usage":"这里 equity 非股权。","new":false,"order":50,"distinction":"Internal equity 关注组织内部的薪资关系是否有合理依据，例如可比岗位间的薪资差异。External competitiveness 关注相对于外部市场的薪资水平。这里的 equity 指公平性，股权激励语境中的 equity 指股权或相关权益。","aliases":[],"collocationZh":"维持内部薪酬公平","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪnˈtɜːnəl ˈekwɪti","ipaUS":"ˌɪnˈtɝːnəl ˈekwətiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Internal equity","exampleZh":"批准录用方案前，我们先从内部薪酬公平性的角度审查了拟定起薪。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Market pricing","note":"依据外部市场数据确定岗位薪酬水平。","relation":"易混淆"},{"term":"Salary benchmark","note":"用于比较的市场薪酬基准。","relation":"易混淆"},{"term":"Salary survey","note":"收集市场薪酬数据的调查。","relation":"易混淆"},{"term":"Internal equity","note":"关注内部岗位及员工之间的薪酬合理性。","relation":"本词"},{"term":"Pay equity","note":"关注薪酬公平，尤其是无不合理差异。","relation":"易混淆"},{"term":"Pay compression","note":"不同经验或职责员工之间的薪酬差距过小。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"What should we assess before approving the proposed pay?","zh":"在批准拟议薪资之前，我们应该评估哪些方面？"},"extension":{"en":"The pay proposal addresses both internal equity and market competitiveness.","zh":"这份薪资方案兼顾内部薪酬公平与市场竞争力。"}},{"id":"HR041","moduleId":"m2","module":"薪酬激励与福利","term":"Pay transparency","zh":"薪酬透明度","definition":"向相关人员说明或披露薪资区间、定薪规则及薪酬决策依据的程度。","example":"Pay transparency helps employees understand how pay decisions are made.","collocation":"improve pay transparency","dialogue":[{"role":"Employee","en":"I can see the range for my grade, but I don’t understand how people move through it.","zh":"我能看到本薪级的薪资区间，但不清楚个人薪资是怎么在区间内提高的。"},{"role":"HR Partner","en":"That’s a gap in our pay transparency. I’ll send you the progression criteria and add them to the FAQ.","zh":"这部分的薪酬信息还不够透明。我会把薪资晋档标准发给你，也会补到常见问题里。"}],"usage":"","new":false,"order":51,"aliases":[],"distinction":"Pay transparency 关注薪资区间、定薪依据等信息是否清楚、是否按适用规则向相关人员披露。Pay equity 关注薪酬差异是否公平合理。披露对象、内容和时点随所在地规定和组织政策而异。","collocationZh":"提升薪酬透明度","collocationReview":"V18.2 模型编辑复核","ipaUK":"peɪ trænˈspærənsi","ipaUS":"peɪ trænˈsperənsiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Pay transparency","exampleZh":"提高薪酬透明度有助于员工理解薪酬决策的依据。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can employees understand our pay decisions?","zh":"怎样让员工理解我们的薪酬决策？"},"extension":{"en":"Publishing pay ranges is one way to improve pay transparency.","zh":"公布薪资区间是提高薪酬透明度的一种做法。"}},{"id":"HR042","moduleId":"m2","module":"薪酬激励与福利","term":"Pay compression","zh":"薪酬压缩","definition":"按资历、职责或职级通常应存在的薪资差距缩得过小的现象。","example":"Pay compression became a concern after the market adjustment.","collocation":"address pay compression","dialogue":[{"role":"Manager","en":"The new hire will earn almost as much as someone who’s been doing the job for five years.","zh":"新员工的薪资几乎赶上做了五年同样工作的人。"},{"role":"Compensation Partner","en":"That could be pay compression. Let’s compare like-for-like roles and check how much the gap has narrowed.","zh":"这可能是薪酬压缩。先比较职责相当的岗位，再看差距缩小了多少。"}],"usage":"","new":false,"order":52,"aliases":[],"distinction":"Pay compression 指不同资历、职责或职级之间的薪资差距被压得过小。Pay inversion 指原本薪资较低的一方反而薪资更高，即薪酬倒挂。两种现象都可在比较新人和在职员工时出现。","collocationZh":"解决薪酬压缩问题","collocationReview":"V18.2 模型编辑复核","ipaUK":"peɪ kəmˈpreʃən","ipaUS":"peɪ kəmˈpreʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Pay compression","exampleZh":"市场调薪后，薪酬压缩问题引起了关注。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Market pricing","note":"依据外部市场数据确定岗位薪酬水平。","relation":"易混淆"},{"term":"Salary benchmark","note":"用于比较的市场薪酬基准。","relation":"易混淆"},{"term":"Salary survey","note":"收集市场薪酬数据的调查。","relation":"易混淆"},{"term":"Internal equity","note":"关注内部岗位及员工之间的薪酬合理性。","relation":"易混淆"},{"term":"Pay equity","note":"关注薪酬公平，尤其是无不合理差异。","relation":"易混淆"},{"term":"Pay compression","note":"不同经验或职责员工之间的薪酬差距过小。","relation":"本词"}],"legacyDialogueBookmark":{"en":"What concern arose after the market adjustment?","zh":"市场调薪后出现了什么问题？"},"extension":{"en":"The analysis found pay compression between team leads and some experienced specialists.","zh":"分析发现，团队主管与部分资深专员之间的薪资差距过小。"}},{"id":"HR043","moduleId":"m2","module":"薪酬激励与福利","term":"Annual bonus","zh":"年度奖金","definition":"以年度为核定周期的奖金，资格、金额和发放时间按适用计划确定。","example":"Under our plan, the annual bonus depends on company and individual performance.","collocation":"annual bonus payout","dialogue":[{"role":"Employee","en":"I changed teams in July. Which manager will submit my results for the annual bonus?","zh":"我七月换了团队。年度奖金所需的绩效结果由哪位经理提交？"},{"role":"HR Partner","en":"Your current manager coordinates it. She’ll get the first-half results from your previous manager.","zh":"由你现在的经理汇总。她会找前任经理拿上半年的绩效结果。"}],"usage":"","new":false,"order":53,"aliases":[],"distinction":"Annual bonus 按年度周期核定，发放条件可因计划而异。Performance bonus 强调奖金与绩效挂钩，可以按年度、季度或项目核定。同一笔奖金可能同时符合两种说法。","collocationZh":"年度奖金发放","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈænjuːəl ˈbəʊ.nəs","ipaUS":"ˈænjuːəl ˈboʊ.nəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Annual bonus","exampleZh":"按公司的计划，年度奖金取决于公司业绩和个人绩效。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Annual bonus","note":"按年度周期发放或评定的奖金。","relation":"本词"},{"term":"Performance bonus","note":"依据绩效结果确定的奖金。","relation":"易混淆"},{"term":"Target bonus","note":"达到目标时对应的奖金水平。","relation":"易混淆"},{"term":"Bonus pool","note":"可供分配的奖金总额。","relation":"易混淆"},{"term":"Sign-on bonus","note":"入职激励奖金。","relation":"易混淆"},{"term":"Retention bonus","note":"为鼓励员工留任而设的奖金。","relation":"易混淆"},{"term":"Commission","note":"通常按销售等业绩计算的提成。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"What determines the annual bonus payout?","zh":"年度奖金的发放金额由什么决定？"},"extension":{"en":"The annual bonus is calculated after the company closes its financial year.","zh":"公司完成财年结账后计算年度奖金。"}},{"id":"HR044","moduleId":"m2","module":"薪酬激励与福利","term":"Performance bonus","zh":"绩效奖金","definition":"与个人、团队或组织绩效挂钩的奖金。","example":"The performance bonus is tied to agreed goals.","collocation":"performance bonus criteria","dialogue":[{"role":"Employee","en":"I met all my individual targets. Why is my performance bonus below target?","zh":"我的个人目标都完成了。为什么绩效奖金低于目标金额？"},{"role":"Manager","en":"Our plan also weights the team result. Let’s go through both parts of the calculation.","zh":"计划里团队结果也占一定权重。我们一起看一下这两部分是怎么算的。"}],"usage":"","new":false,"order":54,"aliases":[],"distinction":"Performance bonus 按规定的个人、团队或组织绩效确定，可一次发放或按周期发放。Merit increase 是基于绩效的基本薪资上调，target bonus 是计划规定的目标奖金水平。","collocationZh":"绩效奖金发放标准","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈfɔːməns ˈbəʊ.nəs","ipaUS":"pɚˈfɔːrməns ˈboʊ.nəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Performance bonus","exampleZh":"绩效奖金与事先约定的目标挂钩。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Annual bonus","note":"按年度周期发放或评定的奖金。","relation":"易混淆"},{"term":"Performance bonus","note":"依据绩效结果确定的奖金。","relation":"本词"},{"term":"Target bonus","note":"达到目标时对应的奖金水平。","relation":"易混淆"},{"term":"Bonus pool","note":"可供分配的奖金总额。","relation":"易混淆"},{"term":"Sign-on bonus","note":"入职激励奖金。","relation":"易混淆"},{"term":"Retention bonus","note":"为鼓励员工留任而设的奖金。","relation":"易混淆"},{"term":"Commission","note":"通常按销售等业绩计算的提成。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"How is the performance bonus determined?","zh":"绩效奖金如何确定？"},"extension":{"en":"The performance bonus formula combines team and individual results.","zh":"绩效奖金公式综合考虑团队和个人的绩效结果。"}},{"id":"HR045","moduleId":"m2","module":"薪酬激励与福利","term":"Sign-on bonus","zh":"签约奖金","definition":"雇主为吸引候选人接受录用邀约并入职提供的额外奖金，支付方式和条件依具体约定而定。","example":"The sign-on bonus will be paid under the terms of the offer.","collocation":"offer a sign-on bonus","dialogue":[{"role":"Candidate","en":"The summary lists a sign-on bonus. Is that included in the annual base salary figure?","zh":"待遇摘要列了一笔签约奖金。它包含在年基本工资里吗？"},{"role":"Recruiter","en":"It’s a separate payment. I’ll show you the payment schedule in the offer letter.","zh":"这笔钱单独支付。我给你看一下录用通知书上的发放安排。"}],"usage":"","new":false,"order":55,"aliases":[],"distinction":"Sign-on bonus 用来吸引候选人接受邀约并入职，可能按录用条款一次或分期发放。Retention bonus 主要用于鼓励现有员工在约定期限内留任。返还等条件以适用条款和规则为准。","collocationZh":"提供签约奖金","collocationReview":"V18.2 模型编辑复核","ipaUK":"saɪn ɒn ˈbəʊ.nəs","ipaUS":"saɪn ɑːn ˈboʊ.nəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Sign-on bonus","exampleZh":"签约奖金将按录用邀约中的条款发放。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Annual bonus","note":"按年度周期发放或评定的奖金。","relation":"易混淆"},{"term":"Performance bonus","note":"依据绩效结果确定的奖金。","relation":"易混淆"},{"term":"Target bonus","note":"达到目标时对应的奖金水平。","relation":"易混淆"},{"term":"Bonus pool","note":"可供分配的奖金总额。","relation":"易混淆"},{"term":"Sign-on bonus","note":"入职激励奖金。","relation":"本词"},{"term":"Retention bonus","note":"为鼓励员工留任而设的奖金。","relation":"易混淆"},{"term":"Commission","note":"通常按销售等业绩计算的提成。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"When will the sign-on bonus be paid?","zh":"签约奖金什么时候发放？"},"extension":{"en":"The offer letter explains when the sign-on bonus becomes payable.","zh":"录用通知书说明了签约奖金何时达到支付条件。"}},{"id":"HR046","moduleId":"m2","module":"薪酬激励与福利","term":"Retention bonus","zh":"留任奖金","definition":"为鼓励现有员工留任至约定日期或完成指定阶段而设置的奖金，资格及付款条件依方案而定。","example":"We proposed a retention bonus for the project team.","collocation":"retention bonus agreement","dialogue":[{"role":"Project Lead","en":"We need the migration specialists through October. Their next assignments start in September.","zh":"迁移工作需要这几位专家一直做到十月，但他们九月就要开始新的任务。"},{"role":"HR Partner","en":"I’ll check whether a retention bonus is an option and talk to their managers about the staffing dates.","zh":"我会看看能不能用留任奖金，也会跟他们的经理协调人员安排的日期。"}],"usage":"","new":false,"order":56,"aliases":[],"distinction":"Retention bonus 面向现有员工，常以留任至约定日期为条件。Sign-on bonus 主要用于吸引新员工入职，performance bonus 则主要按绩效结果确定。资格和支付仍要看方案条款。","collocationZh":"留任奖金协议","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˈtenʃən ˈbəʊ.nəs","ipaUS":"riːˈtenʃən ˈboʊ.nəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Retention bonus","exampleZh":"我们建议为项目团队设立留任奖金。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Annual bonus","note":"按年度周期发放或评定的奖金。","relation":"易混淆"},{"term":"Performance bonus","note":"依据绩效结果确定的奖金。","relation":"易混淆"},{"term":"Target bonus","note":"达到目标时对应的奖金水平。","relation":"易混淆"},{"term":"Bonus pool","note":"可供分配的奖金总额。","relation":"易混淆"},{"term":"Sign-on bonus","note":"入职激励奖金。","relation":"易混淆"},{"term":"Retention bonus","note":"为鼓励员工留任而设的奖金。","relation":"本词"},{"term":"Commission","note":"通常按销售等业绩计算的提成。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"How can we encourage the project team to stay?","zh":"我们如何鼓励项目团队成员继续留任？"},"extension":{"en":"The retention bonus agreement specifies the required service period.","zh":"留任奖金协议列明了需要留任多久。"}},{"id":"HR047","moduleId":"m2","module":"薪酬激励与福利","term":"Commission","zh":"销售提成","definition":"在销售薪酬中，按规定的交易或业绩口径计算的浮动报酬。","example":"The sales team earns commission on eligible deals.","collocation":"sales commission plan","dialogue":[{"role":"Sales Representative","en":"I signed the contract last week, but I don’t see it on my commission statement.","zh":"我上周签了合同，但提成明细上没有这笔交易。"},{"role":"Sales Operations Lead","en":"Under this plan, we credit commission when the customer pays. I’ll check whether the invoice has been settled.","zh":"按这项计划，客户付款后才计入提成。我查一下发票是否已经结清。"}],"usage":"","new":false,"order":57,"aliases":[],"distinction":"Commission 在销售薪酬中通常指按合资格交易金额、件数或其他业绩口径计算的提成。Performance bonus 可依据更广的绩效目标，base salary 是固定基本工资。","collocationZh":"销售提成方案","collocationReview":"V18.2 模型编辑复核","ipaUK":"kəˈmɪʃən","ipaUS":"kəˈmɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Commission","exampleZh":"销售团队可就符合条件的交易获得提成。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Annual bonus","note":"按年度周期发放或评定的奖金。","relation":"易混淆"},{"term":"Performance bonus","note":"依据绩效结果确定的奖金。","relation":"易混淆"},{"term":"Target bonus","note":"达到目标时对应的奖金水平。","relation":"易混淆"},{"term":"Bonus pool","note":"可供分配的奖金总额。","relation":"易混淆"},{"term":"Sign-on bonus","note":"入职激励奖金。","relation":"易混淆"},{"term":"Retention bonus","note":"为鼓励员工留任而设的奖金。","relation":"易混淆"},{"term":"Commission","note":"通常按销售等业绩计算的提成。","relation":"本词"}],"legacyDialogueBookmark":{"en":"How do sales employees earn commission?","zh":"销售人员如何获得销售提成？"},"extension":{"en":"The commission statement shows which deals were credited this month.","zh":"提成明细列出了本月计入的交易。"}},{"id":"HR048","moduleId":"m2","module":"薪酬激励与福利","term":"Incentive plan","zh":"激励计划","definition":"规定奖励对象、目标或条件、计算口径和兑现方式的方案。","example":"The incentive plan should be clear and easy to administer.","collocation":"design an incentive plan","dialogue":[{"role":"Sales Director","en":"The new plan rewards volume. Could that encourage people to discount too heavily?","zh":"新计划奖励销量，会不会让大家把折扣打得太低？"},{"role":"Compensation Partner","en":"Let’s test the incentive plan on a few past deals and see what happens if we add a margin threshold.","zh":"我们拿几笔过去的交易测一下激励计划，再看看加入利润率门槛会有什么影响。"}],"usage":"","new":false,"order":58,"aliases":[],"distinction":"Incentive plan 规定如何通过奖励引导行为或达成目标，可涵盖奖金、提成或长期激励。Bonus plan 专门规定奖金如何确定及发放，bonus pool 则是可供分配的奖金总额。","collocationZh":"设计激励计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪnˈsentɪv plæn","ipaUS":"ˌɪnˈsentɪv plæn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Incentive plan","exampleZh":"激励计划应清晰易懂，便于执行。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What makes an incentive plan easy to understand?","zh":"怎样才能让激励计划易于理解？"},"extension":{"en":"The incentive plan explains how transfers affect eligibility.","zh":"激励计划说明了转岗如何影响参与资格。"}},{"id":"HR049","moduleId":"m2","module":"薪酬激励与福利","term":"Long-term incentive (LTI)","zh":"长期激励","definition":"以较长的服务期或业绩周期为基础、鼓励员工关注长期成果的奖励安排，可采用股权或现金等形式。","example":"The long-term incentive plan is designed for key leaders.","collocation":"LTI eligibility","dialogue":[{"role":"Employee","en":"The award says it’s a cash LTI. Does that mean it’s paid with this year’s bonus?","zh":"通知写的是现金长期激励。这笔钱会和今年的奖金一起发吗？"},{"role":"Compensation Partner","en":"It’s paid in cash, but the award has a separate three-year schedule. Let’s look at the dates and conditions in the agreement.","zh":"奖励以现金支付，但有单独的三年安排。我们看一下协议里的日期和条件。"}],"usage":"","new":false,"order":59,"aliases":[],"distinction":"Long-term incentive 按较长的服务期或业绩周期设计，可采用股票、期权或现金。Short-term incentive 通常对应较短周期，例如年度奖金。LTI 描述激励周期，equity incentive 描述奖励与股权关联的形式。","collocationZh":"长期激励计划的参与资格","collocationReview":"V18.2 模型编辑复核","ipaUK":"lɒŋ tɜːm ɪnˈsentɪv","ipaUS":"lɔːŋ tɝːm ˌɪnˈsentɪv","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Long-term incentive","exampleZh":"这项长期激励计划面向关键管理人员。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who is the long-term incentive plan designed for?","zh":"长期激励计划主要面向哪些人？"},"extension":{"en":"This long-term incentive has a three-year performance period.","zh":"这项长期激励的业绩考核期为三年。"}},{"id":"HR050","moduleId":"m2","module":"薪酬激励与福利","term":"Stock option","zh":"股票期权","definition":"在计划规定的条件和期限内，按约定行权价买入公司股票的权利。","example":"Some employees receive stock options as part of their package.","collocation":"exercise a stock option","dialogue":[{"role":"Employee","en":"The portal says my options have vested. Do I own the shares now?","zh":"系统显示我的期权已经归属。我现在就持有股票了吗？"},{"role":"Equity Plan Administrator","en":"You can now exercise the vested options under the plan rules. The portal shows the exercise price and what to do next.","zh":"你现在可以按计划规则对已归属的期权行权。系统里有行权价和操作步骤。"}],"usage":"","new":false,"order":60,"aliases":[],"distinction":"Stock option 在符合条件时赋予持有人按行权价买入股票的权利。RSU 在满足归属及交付条件后通常交付股票或现金等值，无须支付行权价。ESPP 则是员工按计划规则购买公司股票的安排。","collocationZh":"对股票期权行权","collocationReview":"V18.2 模型编辑复核","ipaUK":"stɒk ˈɒpʃən","ipaUS":"stɑːk ˈɑːpʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Stock option","exampleZh":"部分员工的薪酬方案中包含股票期权。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Stock option","note":"按约定价格购买股票的权利。","relation":"本词"},{"term":"Restricted stock unit (RSU)","note":"达到归属和交付条件后，按计划以股票或等值现金结算的奖励单位。","relation":"易混淆"},{"term":"Performance shares","note":"与绩效条件挂钩的股份奖励。","relation":"易混淆"},{"term":"Equity vesting","note":"股权奖励达到约定条件后取得相关权利，可一次或分批归属。","relation":"易混淆"},{"term":"Vesting schedule","note":"规定归属时间或条件的安排。","relation":"易混淆"},{"term":"Clawback provision","note":"在约定条件下追回已支付或授予报酬的条款。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Do any employees receive stock options?","zh":"是否有员工获得股票期权？"},"extension":{"en":"Check the expiration date before exercising a stock option.","zh":"股票期权行权前，请先确认到期日。"}},{"id":"HR051","moduleId":"m2","module":"薪酬激励与福利","term":"Restricted stock unit (RSU)","zh":"限制性股票单位","definition":"一种以股票价值计量的奖励单位，满足适用的归属和交付条件后，按计划以股票或等值现金结算。","example":"The employee received restricted stock units with a vesting schedule.","collocation":"RSU grant","dialogue":[{"role":"Employee","en":"My award shows 100 RSUs. Can I sell them through the portal today?","zh":"我的授予记录显示有 100 个限制性股票单位。今天能在系统里卖掉吗？"},{"role":"Equity Plan Administrator","en":"This award is still unvested. Once shares are delivered, the plan and any applicable trading restrictions will determine when you can sell them.","zh":"这笔奖励还没归属。股票交付后，什么时候能卖要看计划条款和适用的交易限制。"}],"usage":"RSU 是限制性股票单位；不同计划对归属、税务及实际交付方式规定不同。","new":false,"order":61,"aliases":[],"distinction":"RSU 是按计划在满足归属和交付条件后以股票或等值现金结算的奖励单位。Stock option 赋予按行权价购买股票的权利，restricted stock award 则通常直接授予受限制的股票。","collocationZh":"限制性股票单位授予","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˈstrɪktɪd stɒk ˈjuːnɪt","ipaUS":"riːˈstrɪktəd stɑːk ˈjuːnət","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Restricted stock unit","exampleZh":"该员工获得了附有归属安排的限制性股票单位。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Stock option","note":"按约定价格购买股票的权利。","relation":"易混淆"},{"term":"Restricted stock unit (RSU)","note":"达到归属和交付条件后，按计划以股票或等值现金结算的奖励单位。","relation":"本词"},{"term":"Performance shares","note":"与绩效条件挂钩的股份奖励。","relation":"易混淆"},{"term":"Equity vesting","note":"股权奖励达到约定条件后取得相关权利，可一次或分批归属。","relation":"易混淆"},{"term":"Vesting schedule","note":"规定归属时间或条件的安排。","relation":"易混淆"},{"term":"Clawback provision","note":"在约定条件下追回已支付或授予报酬的条款。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"What equity award did the employee receive?","zh":"这名员工获得了哪种股权激励？"},"extension":{"en":"The RSU grant notice lists the number of units and the vesting conditions.","zh":"限制性股票单位授予通知列明了单位数量和归属条件。"}},{"id":"HR052","moduleId":"m2","module":"薪酬激励与福利","term":"Equity vesting","zh":"股权归属","definition":"股权奖励达到协议约定的服务期、业绩等条件后，持有人取得相应权利的过程，可一次或分批完成。","example":"Equity vesting normally follows the terms of the award agreement.","collocation":"vesting schedule","dialogue":[{"role":"Employee","en":"Why hasn’t any of my award vested after six months?","zh":"已经过了六个月，为什么我的奖励还没归属？"},{"role":"Equity Plan Administrator","en":"Your equity vesting schedule starts with a one-year cliff. The first portion vests at the end of that period if you meet the award conditions.","zh":"你的股权归属安排设有一年的首次归属等待期。符合授予条件的话，第一部分会在期满时归属。"}],"usage":"","new":false,"order":62,"aliases":[],"distinction":"Equity vesting 指奖励满足服务期、绩效等条件后取得相关权益，可一次或分批归属。Grant 是授予奖励，settlement 是交付股票或款项，exercise 通常指期权行权。","collocationZh":"股权归属时间表","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈekwɪti ˈvestɪŋ","ipaUS":"ˈekwətiː ˈvestɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Equity vesting","exampleZh":"股权归属通常依照授予协议的条款执行。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Stock option","note":"按约定价格购买股票的权利。","relation":"易混淆"},{"term":"Restricted stock unit (RSU)","note":"达到归属和交付条件后，按计划以股票或等值现金结算的奖励单位。","relation":"易混淆"},{"term":"Performance shares","note":"与绩效条件挂钩的股份奖励。","relation":"易混淆"},{"term":"Equity vesting","note":"股权奖励达到约定条件后取得相关权利，可一次或分批归属。","relation":"本词"},{"term":"Vesting schedule","note":"规定归属时间或条件的安排。","relation":"易混淆"},{"term":"Clawback provision","note":"在约定条件下追回已支付或授予报酬的条款。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"What determines when an equity award vests?","zh":"股权激励在什么时候归属，由什么决定？"},"extension":{"en":"Check the equity vesting terms before assuming that a transfer changes the schedule.","zh":"先核对股权归属条款，再判断转岗是否影响归属安排。"}},{"id":"HR053","moduleId":"m2","module":"薪酬激励与福利","term":"Benefits enrollment","zh":"福利登记／福利参保登记","definition":"员工选择并加入适用福利计划的流程。","example":"Benefits enrollment opens next Monday for eligible employees.","collocation":"complete benefits enrollment","dialogue":[{"role":"New Hire","en":"I chose a medical plan yesterday. Is my enrollment complete?","zh":"我昨天选了医疗保险方案。福利登记办完了吗？"},{"role":"Benefits Adviser","en":"Your selection is saved as a draft. Submit it in the portal to complete benefits enrollment.","zh":"你的选择还保存在草稿里。到系统里提交后才算完成福利登记。"}],"usage":"","new":false,"order":63,"aliases":[],"distinction":"Benefits enrollment 指员工确认福利选项并办理参加手续。Benefits eligibility 指员工是否有资格参加。Open enrollment 是部分福利制度允许集中参保或调整选项的登记期。","collocationZh":"完成员工福利登记","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈbenɪˌfɪts enˈrəʊlmənt","ipaUS":"ˈbenəfɪts enˈroʊlmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Benefits enrollment","exampleZh":"符合条件的员工可于下周一开始办理福利登记。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When can eligible employees sign up for benefits?","zh":"符合资格的员工何时可以登记参加福利计划？"},"extension":{"en":"Review your dependent information before completing benefits enrollment.","zh":"提交福利登记前，请核对受扶养人信息。"}},{"id":"HR054","moduleId":"m2","module":"薪酬激励与福利","term":"Health insurance","zh":"医疗保险","definition":"依据保险计划条款分担合资格医疗费用的保障，可作为雇主提供的福利之一。","example":"Please check which health insurance options are available locally.","collocation":"health insurance coverage","dialogue":[{"role":"Employee","en":"My clinic has two locations. How do I know which one is covered?","zh":"我的诊所有两个地点。怎么知道哪个在保障范围内？"},{"role":"Benefits Adviser","en":"Check both addresses in the provider directory for your health insurance plan. The network can vary by location.","zh":"在你这项医疗保险的服务机构名录里查一下两个地址。不同地点的网络情况可能不同。"}],"usage":"","new":false,"order":64,"aliases":["Medical Insurance"],"distinction":"在许多员工福利场景中，health insurance 与 medical insurance 都指医疗保险，具体保障范围依计划而定。Health insurance coverage 强调保什么，wellness allowance 则往往补助符合政策的健康活动等支出。","collocationZh":"医疗保险保障范围","collocationReview":"V18.2 模型编辑复核","ipaUK":"helθ ɪnˈʃʊərəns","ipaUS":"helθ ˌɪnˈʃʊrəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Health insurance","exampleZh":"请核实当地提供哪些医疗保险方案。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Are the health insurance options the same in every country?","zh":"不同国家的医疗保险方案是否相同？"},"extension":{"en":"Check whether your health insurance covers treatment outside the network.","zh":"确认你的医疗保险是否保障网络外就医。"}},{"id":"HR055","moduleId":"m2","module":"薪酬激励与福利","term":"Retirement plan","zh":"退休保障计划／退休福利计划","definition":"为退休后提供收入或积累储蓄的安排，可采用按公式给付、账户缴费等模式。","example":"Retirement plan rules can vary by country and employer.","collocation":"retirement plan contribution","dialogue":[{"role":"Employee","en":"I’m moving to another country with the company. Will contributions to my current plan continue?","zh":"我要随公司调往另一个国家。目前的退休计划还会继续缴费吗？"},{"role":"Benefits Adviser","en":"I’ll check the retirement plan rules for both locations. The transfer can affect which plan you participate in.","zh":"我会核对两个地点的退休计划规则。调动可能影响你参加哪项计划。"}],"usage":"","new":false,"order":65,"aliases":[],"distinction":"Retirement plan 泛指为退休后收入提供保障或积累储蓄的安排。Defined benefit plan 按规则计算退休待遇，defined contribution plan 通常按个人账户缴费和投资表现等确定积累额。计划类型和适用资格因司法辖区和雇主而异。","collocationZh":"退休计划缴费","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˈtaɪəmənt plæn","ipaUS":"riːˈtaɪɚmənt plæn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Retirement plan","exampleZh":"退休计划规则可能因国家和雇主而异。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Does the same retirement plan apply in all locations?","zh":"所有工作地点都适用同一退休计划吗？"},"extension":{"en":"The retirement plan guide explains how employer contributions are calculated.","zh":"退休计划指南说明了如何计算雇主缴费。"}},{"id":"HR056","moduleId":"m2","module":"薪酬激励与福利","term":"Paid time off (PTO)","zh":"带薪休假","definition":"员工按适用规定或组织政策可以带薪休假的时间，具体涵盖哪些类别因制度而异。","example":"Employees can request paid time off through the HR system.","collocation":"PTO balance","dialogue":[{"role":"Employee","en":"I have a medical appointment on Friday. Should I enter that as sick leave?","zh":"我周五约了看医生。这应该填病假吗？"},{"role":"HR Adviser","en":"Our policy tracks sick leave separately from general PTO. Let’s check which code applies to your appointment.","zh":"我们的政策把病假与一般带薪休假分开记录。我们来核对这次预约该选哪个休假代码。"}],"usage":"","new":false,"order":66,"aliases":[],"distinction":"Paid time off 泛指带薪休假。部分雇主将 PTO 专指合并了年假和病假等类别的假期额度，也有雇主分设各类额度。Vacation leave 和 sick leave 各指特定休假类别，政策名称应结合当地法定休假规则解读。","collocationZh":"带薪休假剩余额度","collocationReview":"V18.2 模型编辑复核","ipaUK":"peɪd taɪm ɒf","ipaUS":"peɪd taɪm ɔːf","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Paid time off","exampleZh":"员工可通过人力资源系统申请带薪休假。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Where should employees request their paid time off?","zh":"员工应通过哪里申请带薪休假？"},"extension":{"en":"Check your PTO balance before booking a trip.","zh":"预订行程前，请先查看带薪休假余额。"}},{"id":"HR057","moduleId":"m2","module":"薪酬激励与福利","term":"Payroll cycle","zh":"薪资核算与发放周期／发薪周期","definition":"工资核算与支付的固定节奏。","example":"Our payroll cycle closes on the last working day of the month.","collocation":"monthly payroll cycle","dialogue":[{"role":"Manager","en":"If I approve the timesheet this afternoon, will those hours be in Friday’s pay?","zh":"如果我今天下午批准工时表，这些工时能计入周五的工资吗？"},{"role":"Payroll Specialist","en":"This payroll cycle has already closed. I’ll check whether we can still process the hours in time.","zh":"本轮薪资核算已经截止。我去看看是否还来得及处理这部分工时。"}],"usage":"","new":false,"order":67,"aliases":[],"distinction":"Payroll cycle 指汇总工资数据、核算和发放的重复周期。Pay period 是工资覆盖的工作或计薪期间，pay date 是约定发薪日。核算截止日与发薪日可以不同。","collocationZh":"每月薪资发放周期","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈpeɪrəʊl ˈsaɪkəl","ipaUS":"ˈpeɪroʊl ˈsaɪkəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Payroll cycle","exampleZh":"我们每月的薪资核算在最后一个工作日截止。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When does the payroll cycle close?","zh":"本轮薪资核算周期什么时候截止？"},"extension":{"en":"Record the approved hours before the current payroll cycle closes.","zh":"本轮薪资核算截止前，请录入已审批的工时。"}},{"id":"HR058","moduleId":"m2","module":"薪酬激励与福利","term":"Tax withholding","zh":"税款预扣／代扣税款","definition":"在薪资场景中，由发薪方依据适用税务规则从工资中预先扣缴税款，也可指相应扣款。","example":"The payroll team checks which tax withholding rules apply to employees who work across borders.","collocation":"adjust tax withholding","dialogue":[{"role":"Employee","en":"My tax withholding changed after I transferred to the new office. Where can I see what changed?","zh":"我调到新办公室后，工资预扣税额变了。在哪里能看到具体变动？"},{"role":"Payroll Specialist","en":"Let’s compare the two payslips and check which tax jurisdiction the payroll system used for each one.","zh":"我们对一下两期工资单，看看系统分别按哪个税务辖区处理。"}],"usage":"","new":false,"order":68,"aliases":[],"distinction":"Tax withholding 在薪资场景中指发薪时预先从工资扣缴税款。Payroll deduction 的范围更广，还可包括福利缴费等工资扣款。最终应纳税额与预扣额可能不同，适用规则取决于相关税务辖区和个人情况。","collocationZh":"调整预扣税额","collocationReview":"V18.2 模型编辑复核","ipaUK":"tæks wɪðˈhəʊldɪŋ","ipaUS":"tæks wɪθˈhoʊldɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Tax withholding","exampleZh":"薪资团队会核对跨境工作人员适用哪些税款预扣规则。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How is the tax withholding amount calculated?","zh":"预扣税金额如何计算？"},"extension":{"en":"Your payslip lists tax withholding separately from other deductions.","zh":"工资单将税款预扣额与其他扣款分开列示。"}},{"id":"HR059","moduleId":"m2","module":"薪酬激励与福利","term":"Overtime pay","zh":"加班工资／加班报酬","definition":"对符合条件且超过适用工时标准或约定的工作时间支付的工资，资格及支付标准依适用规定和用工安排而定。","example":"The payroll team checks the applicable overtime pay rules before processing the extra hours.","collocation":"overtime pay eligibility","dialogue":[{"role":"Employee","en":"I worked on Saturday. Will all those hours qualify for overtime pay?","zh":"我周六上了班。这些工时都能算加班工资吗？"},{"role":"Payroll Specialist","en":"Let’s check the recorded hours and the rules for your schedule and work location.","zh":"我们先核对工时记录，再看你的排班和工作地点适用哪些规则。"}],"usage":"","new":false,"order":69,"aliases":[],"distinction":"Overtime pay 是符合条件的加班工时所对应的工资。Overtime premium 通常专指超出正常工资率的加成部分，time off in lieu 指以补休处理额外工时。资格、计算方式和补休规则取决于适用规定及用工安排。","collocationZh":"加班工资领取资格","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈəʊvəˌtaɪm peɪ","ipaUS":"ˈoʊvɚˌtaɪm peɪ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Overtime pay","exampleZh":"薪资团队在处理额外工时前，会核对适用的加班工资规则。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What rules should we follow when calculating overtime pay?","zh":"计算加班工资时应遵循哪些规定？"},"extension":{"en":"The payslip shows overtime pay on a separate line.","zh":"工资单上单独列出了加班工资。"}},{"id":"HR060","moduleId":"m2","module":"薪酬激励与福利","term":"Merit increase","zh":"绩效加薪","definition":"以员工绩效为主要依据上调其基本薪资的做法，资格和增幅按适用政策确定。","example":"Merit increases are considered during the annual compensation review.","collocation":"merit increase budget","dialogue":[{"role":"Manager","en":"Morgan’s performance was rated highly, but their pay is near the top of the range.","zh":"摩根的绩效评级很高，但薪资已接近区间上限。"},{"role":"Compensation Partner","en":"Check the merit increase guidelines for people near the maximum. We’ll review the options before you talk to Morgan.","zh":"查一下临近区间上限的员工适用哪些绩效加薪规则。你和摩根谈之前，我们先看看有哪些选项。"}],"usage":"","new":false,"order":70,"aliases":[],"distinction":"Merit increase 因绩效表现上调基本薪资。Performance bonus 是按绩效核定的奖金，market adjustment 则主要以外部市场薪资数据为依据。绩效评级可能影响加薪，但还要看预算和适用政策。","collocationZh":"绩效加薪预算","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈmerɪt ˈɪn.kriːs","ipaUS":"ˈmerət ˈɪn.kriːs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Merit increase","exampleZh":"年度薪酬评审期间会考虑绩效加薪。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Market adjustment","note":"依据外部市场薪酬水平调整薪资，主要关注市场竞争力；不以个人绩效为主要依据，但可与绩效调薪同时实施。","relation":"易混淆"},{"term":"Merit increase","note":"依据个人绩效决定的加薪。","relation":"本词"},{"term":"Salary increase","note":"泛指薪资上涨，不限定原因。","relation":"易混淆"},{"term":"Promotion increase","note":"因晋升而上调基本薪资，是否加薪及金额取决于适用政策。","relation":"易混淆"},{"term":"Cost-of-living adjustment (COLA)","note":"依据生活成本变化调整薪资。","relation":"易混淆"},{"term":"Annual increment","note":"年度常规加薪，是否与绩效挂钩取决于制度。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"When are merit increases considered?","zh":"什么时候考虑绩效调薪？"},"extension":{"en":"The merit increase budget sets the amount available for performance-based raises.","zh":"绩效加薪预算规定了可用于绩效加薪的资金总额。"}},{"id":"HR2-31","moduleId":"m2","module":"薪酬激励与福利","term":"Compa-ratio","zh":"薪资与区间中点比率","definition":"员工基本薪资除以对应薪资区间中点所得的比率，分子和分母应采用相同的计薪周期、币种及工时口径。","example":"A compa-ratio below one means pay is below the range midpoint.","collocation":"calculate the compa-ratio","dialogue":[{"role":"HR Analyst","en":"Jordan and Lee earn the same base pay, but the dashboard shows different compa-ratios.","zh":"乔丹和李的基本薪资相同，看板上显示的薪资与区间中点比率却不一样。"},{"role":"Compensation Partner","en":"They’re in different grades. Check the midpoint used for each person before investigating further.","zh":"他们属于不同薪级。先核对各自使用的薪资区间中点，再往下查。"}],"usage":"公式：员工实际基本工资 ÷ 该职级薪资区间中点。它是薪酬位置指标，不直接代表公平与否。","new":true,"order":71,"aliases":[],"distinction":"Compa-ratio 用基本薪资除以对应区间中点，表示员工薪资相对于中点的位置。Salary range penetration 用基本薪资减区间下限，再除以区间宽度。两者都是位置指标，评估公平性还需结合可比岗位及其他证据。","collocationZh":"计算薪资与区间中点比率","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkɒm.pə ˈreɪ.ʃi.əʊ","ipaUS":"ˈkɑːm.pə ˈreɪ.ʃi.oʊ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"compa ratio","exampleZh":"比率低于 1，表示员工的基本薪资低于对应薪资区间中点。","meaningReview":"HR场景校订","exampleReview":"语义修订","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Salary band","note":"岗位或等级对应的薪资区间。","relation":"易混淆"},{"term":"Pay grade","note":"薪酬等级，通常关联一个薪资区间。","relation":"易混淆"},{"term":"Pay range midpoint","note":"薪资区间中点。","relation":"易混淆"},{"term":"Compa-ratio","note":"员工基本薪资除以适用薪资区间中点，采用同一计薪周期和币种。","relation":"本词"},{"term":"Salary range penetration","note":"员工基本薪资减去区间下限后，除以区间上限与下限之差，金额应使用相同口径。","relation":"易混淆"},{"term":"Broadbanding","note":"将多个窄薪资等级合并为宽薪资带。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"How do we interpret this employee's compa-ratio?","zh":"我们应该如何解读这名员工的薪酬比率？"},"extension":{"en":"A base salary of 54,000 against a range midpoint of 60,000 gives a compa-ratio of 90%.","zh":"基本薪资为 54,000、同口径的区间中点为 60,000 时，薪资与区间中点比率为 90%。"}},{"id":"HR2-32","moduleId":"m2","module":"薪酬激励与福利","term":"Pay range midpoint","zh":"薪资区间中点","definition":"组织设定的薪资区间中间参考值，可用于定薪比较和计算薪资与区间中点比率。","example":"We use the pay range midpoint to compare base salaries within a grade.","collocation":"review the pay range midpoint","dialogue":[{"role":"HR Analyst","en":"Should I use the market median as the midpoint in the dashboard?","zh":"看板里的中点要用市场薪资中位数吗？"},{"role":"Compensation Partner","en":"Use our approved pay range midpoint. The survey median belongs in the market comparison column.","zh":"用公司批准的薪资区间中点。调查数据的中位数放在市场比较那一栏。"}],"usage":"","new":true,"order":72,"aliases":[],"distinction":"Pay range midpoint 是组织为薪资区间设定的中点参考值，常用于比较个人基本薪资。Market median 是外部样本的第 50 百分位数，可用作设置中点的参考，两者可能不同。","collocationZh":"核对薪资区间中点","collocationReview":"V18.2 模型编辑复核","ipaUK":"peɪ reɪndʒ ˈmɪdpɔɪnt","ipaUS":"peɪ reɪndʒ ˈmɪdpɔɪnt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Pay range midpoint","exampleZh":"我们用薪资区间中点作为参照，比较同一薪级内的基本薪资。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Salary band","note":"岗位或等级对应的薪资区间。","relation":"易混淆"},{"term":"Pay grade","note":"薪酬等级，通常关联一个薪资区间。","relation":"易混淆"},{"term":"Pay range midpoint","note":"薪资区间中点。","relation":"本词"},{"term":"Compa-ratio","note":"员工基本薪资除以适用薪资区间中点，采用同一计薪周期和币种。","relation":"易混淆"},{"term":"Salary range penetration","note":"员工基本薪资减去区间下限后，除以区间上限与下限之差，金额应使用相同口径。","relation":"易混淆"},{"term":"Broadbanding","note":"将多个窄薪资等级合并为宽薪资带。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"What is the pay range midpoint for this grade?","zh":"这个薪酬等级对应的薪资区间中点是多少？"},"extension":{"en":"Use the new pay range midpoint when recalculating the compa-ratio.","zh":"重新计算薪资与区间中点比率时，请使用新的薪资区间中点。"}},{"id":"HR2-33","moduleId":"m2","module":"薪酬激励与福利","term":"Salary survey","zh":"薪酬调查","definition":"按岗位、级别或地区等口径收集、整理市场薪酬数据的调查。","example":"We use a salary survey to benchmark critical positions.","collocation":"participate in a salary survey","dialogue":[{"role":"Compensation Analyst","en":"The salary survey shows a higher figure than last year. Did the market really move that much?","zh":"薪酬调查的数字比去年高。市场真的涨了那么多吗？"},{"role":"Compensation Partner","en":"Let’s check the sample first. This year’s survey may include a different mix of employers.","zh":"先核对样本。今年调查覆盖的雇主构成可能不同。"}],"usage":"","new":true,"order":73,"aliases":[],"distinction":"Salary survey 系统收集市场薪资数据并按岗位、地区等整理。Salary benchmark 是从调查等来源选出的参考薪资，market pricing 是使用相应数据为岗位确定市场薪资参考水平的过程。","collocationZh":"参与薪酬调查","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsæl.ər.i ˈsɜː.veɪ","ipaUS":"ˈsæl.ɚ.i ˈsɝː.veɪ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Salary survey","exampleZh":"我们使用薪酬调查数据对关键岗位的薪酬做市场对标。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Market pricing","note":"依据外部市场数据确定岗位薪酬水平。","relation":"易混淆"},{"term":"Salary benchmark","note":"用于比较的市场薪酬基准。","relation":"易混淆"},{"term":"Salary survey","note":"收集市场薪酬数据的调查。","relation":"本词"},{"term":"Internal equity","note":"关注内部岗位及员工之间的薪酬合理性。","relation":"易混淆"},{"term":"Pay equity","note":"关注薪酬公平，尤其是无不合理差异。","relation":"易混淆"},{"term":"Pay compression","note":"不同经验或职责员工之间的薪酬差距过小。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Which salary survey should we use for this role?","zh":"这个岗位应该参考哪份薪酬调查？"},"extension":{"en":"This salary survey reports separate figures for base salary and total cash compensation.","zh":"这份薪酬调查分别报告基本薪资和现金薪酬总额。"}},{"id":"HR2-34","moduleId":"m2","module":"薪酬激励与福利","term":"Variable pay","zh":"浮动薪酬","definition":"金额或支付随个人、团队或组织业绩等约定条件变化的薪酬部分，例如按业绩计算的提成或奖金。","example":"Variable pay can account for a larger share of compensation in sales than in support roles.","collocation":"variable pay component","dialogue":[{"role":"Candidate","en":"Does the figure in the offer letter stay the same every year?","zh":"录用通知书上的这个金额每年都一样吗？"},{"role":"Recruiter","en":"The base salary is fixed unless it’s revised. The variable pay figure is an estimate at target, and the actual payout depends on results.","zh":"除非调薪，基本工资是固定的。浮动薪酬列的是达到目标时的估算值，实发金额取决于业绩。"}],"usage":"","new":true,"order":74,"aliases":[],"distinction":"Variable pay 随业绩或约定条件变化，可包括提成、绩效奖金等。Base salary 是固定基本工资。Total cash compensation 则把基本工资和纳入计算的浮动现金报酬相加。","collocationZh":"浮动薪酬项目","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈveərɪəbəl peɪ","ipaUS":"ˈveriːəbəl peɪ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Variable pay","exampleZh":"与支持类岗位相比，销售岗位的浮动薪酬占比可能更高。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Base salary","note":"固定基本薪资，不含浮动奖金。","relation":"易混淆"},{"term":"Gross salary","note":"扣税及其他扣款前的薪资。","relation":"易混淆"},{"term":"Net pay","note":"扣除税费等后的实发薪资。","relation":"易混淆"},{"term":"Total cash compensation","note":"固定及浮动现金薪酬，不含非现金福利。","relation":"易混淆"},{"term":"Total rewards","note":"涵盖薪酬、福利及其他回报。","relation":"易混淆"},{"term":"Compensation package","note":"薪酬待遇组合，具体范围取决于企业。","relation":"易混淆"},{"term":"Variable pay","note":"随绩效或其他条件变化的薪酬。","relation":"本词"}],"legacyDialogueBookmark":{"en":"What proportion of the package is variable pay?","zh":"薪酬方案中浮动薪酬占多大比例？"},"extension":{"en":"The statement lists base salary and variable pay separately.","zh":"薪酬明细分别列出基本工资和浮动薪酬。"}},{"id":"HR2-35","moduleId":"m2","module":"薪酬激励与福利","term":"Target bonus","zh":"目标奖金","definition":"奖金计划为达到规定目标时设定的参考发放水平，可用金额或基本薪资的百分比表示。","example":"The target bonus is fifteen percent of annual base salary.","collocation":"target bonus percentage","dialogue":[{"role":"Candidate","en":"The offer shows a target bonus. Should I include that number in my guaranteed income?","zh":"录用方案列了目标奖金。我能把这笔钱算进有保障的收入吗？"},{"role":"Recruiter","en":"Treat it as the payout at target. The amount you receive will depend on the plan rules and the results.","zh":"这个数字是达到目标时对应的奖金金额。实际能拿多少，要看计划规则和业绩结果。"}],"usage":"","new":true,"order":75,"aliases":[],"distinction":"Target bonus 是计划在目标条件达成时对应的奖金金额或比例。Actual bonus payout 是按结果和条款最终发放的金额，可能高于或低于目标。Bonus pool 是可供分配的奖金总额。","collocationZh":"目标奖金比例","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtɑːɡɪt ˈbəʊ.nəs","ipaUS":"ˈtɑːrɡət ˈboʊ.nəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Target bonus","exampleZh":"目标奖金为年度基本工资的 15%。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Annual bonus","note":"按年度周期发放或评定的奖金。","relation":"易混淆"},{"term":"Performance bonus","note":"依据绩效结果确定的奖金。","relation":"易混淆"},{"term":"Target bonus","note":"达到目标时对应的奖金水平。","relation":"本词"},{"term":"Bonus pool","note":"可供分配的奖金总额。","relation":"易混淆"},{"term":"Sign-on bonus","note":"入职激励奖金。","relation":"易混淆"},{"term":"Retention bonus","note":"为鼓励员工留任而设的奖金。","relation":"易混淆"},{"term":"Commission","note":"通常按销售等业绩计算的提成。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"What is the target bonus for this position?","zh":"这个岗位的目标奖金是多少？"},"extension":{"en":"The revised plan lowers the target bonus for that grade.","zh":"修订后的方案调低了该薪级的目标奖金。"}},{"id":"HR2-36","moduleId":"m2","module":"薪酬激励与福利","term":"Pay-for-performance","zh":"绩效付薪","definition":"使员工、团队或组织的绩效结果影响基本薪资调整、奖金等薪酬决定的原则或机制。","example":"Our pay-for-performance policy uses clear evaluation criteria.","collocation":"pay-for-performance philosophy","dialogue":[{"role":"Manager","en":"If two people receive the same rating, do they get the same raise?","zh":"如果两个人的评级相同，加薪幅度也一样吗？"},{"role":"Compensation Partner","en":"Our pay-for-performance approach considers the rating and where each person sits in the salary range. Let’s check the matrix for both cases.","zh":"我们的绩效付薪机制既看评级，也看各自的薪资在区间中的位置。我们按矩阵核对一下这两个情况。"}],"usage":"","new":true,"order":76,"aliases":[],"distinction":"Pay-for-performance 是让绩效结果影响薪酬的设计原则。Merit increase 和 performance bonus 是可采用的具体机制，分别影响基本薪资和奖金。绩效与薪酬如何挂钩取决于适用方案。","collocationZh":"绩效付薪理念","collocationReview":"V18.2 模型编辑复核","ipaUK":"peɪ fɔː pəˈfɔːməns","ipaUS":"peɪ fɔːr pɚˈfɔːrməns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Pay-for-performance","exampleZh":"我们的绩效付薪政策采用明确的评价标准。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we explain our pay-for-performance approach?","zh":"我们该如何解释公司的绩效付薪机制？"},"extension":{"en":"A pay-for-performance policy should explain how ratings affect pay decisions.","zh":"绩效付薪政策应说明评级如何影响薪酬决策。"}},{"id":"HR2-37","moduleId":"m2","module":"薪酬激励与福利","term":"Benefits eligibility","zh":"福利资格／福利参与资格","definition":"根据福利计划条款和适用规定，员工是否满足参加某项福利或获得保障的条件。","example":"Benefits eligibility depends on the applicable plan rules and may vary by employee group.","collocation":"confirm benefits eligibility","dialogue":[{"role":"New Hire","en":"I can see the dental plan in the portal. Does that mean I can enroll today?","zh":"我能在系统里看到牙科计划。这是不是表示我今天就可以登记？"},{"role":"Benefits Adviser","en":"Let’s check your benefits eligibility and the enrollment dates for new hires at your location.","zh":"我们先核对你的福利资格，再看你所在地点的新员工登记日期。"}],"usage":"","new":true,"order":77,"aliases":[],"distinction":"Benefits eligibility 回答员工是否满足福利条件。Benefits enrollment 回答是否完成登记或选项确认，coverage effective date 则是保障开始的日期。资格与生效时间都要按适用计划及规定确认。","collocationZh":"确认福利资格","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈbenɪˌfɪts ˌelɪdʒəˈbɪlɪti","ipaUS":"ˈbenəfɪts ˌelɪdʒəˈbɪlɪtiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Benefits eligibility","exampleZh":"福利资格由适用计划的规则决定，不同员工类别的条件可能不同。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Is this new hire eligible for the benefit plan?","zh":"这位新员工是否符合享受该福利计划的条件？"},"extension":{"en":"The portal lists benefits eligibility by employee group.","zh":"系统按员工类别列出福利资格条件。"}},{"id":"HR2-38","moduleId":"m2","module":"薪酬激励与福利","term":"Flexible benefits","zh":"弹性福利","definition":"允许员工在计划规定的项目、组合或额度内选择福利的安排。","example":"Flexible benefits let employees choose options that fit their needs.","collocation":"flexible benefits plan","dialogue":[{"role":"Employee","en":"I already have dental coverage through my partner. Can I choose a different benefit?","zh":"我已经通过伴侣的计划有了牙科保障。能改选别的福利吗？"},{"role":"Benefits Adviser","en":"Our flexible benefits plan lets you switch some optional items. Let’s check whether dental is one of them.","zh":"公司的弹性福利计划允许更换部分可选项目。我们看看牙科保障是否在其中。"}],"usage":"","new":true,"order":78,"aliases":[],"distinction":"Flexible benefits 允许员工在规定选项和额度内配置福利，部分方案采用福利积分或预算。Core benefits 是固定提供或必须保留的基本福利，flexible working 指灵活工作安排。","collocationZh":"弹性福利方案","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈfleksɪbəl ˈbenɪˌfɪts","ipaUS":"ˈfleksəbəl ˈbenəfɪts","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Flexible benefits","exampleZh":"弹性福利让员工能在计划范围内选择适合自己需求的项目。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can employees choose their own flexible benefits?","zh":"员工可以自行选择弹性福利项目吗？"},"extension":{"en":"The flexible benefits guide shows which options use benefit credits.","zh":"弹性福利指南说明了哪些选项可使用福利积分。"}},{"id":"HR2-39","moduleId":"m2","module":"薪酬激励与福利","term":"Pay equity","zh":"薪酬公平性","definition":"考察可比工作和不同员工群体间的薪酬差异是否有与工作相关的合理依据，具体比较标准应结合适用规定。","example":"The pay equity review compares roles with similar responsibilities and considers relevant pay factors.","collocation":"conduct a pay equity review","dialogue":[{"role":"HR Director","en":"The report shows a gap in average pay. Can we tell what’s driving it?","zh":"报告显示平均薪酬存在差距。我们知道是什么造成的吗？"},{"role":"Compensation Analyst","en":"We’ll use the pay equity review to see whether the gap persists among employees doing similar work.","zh":"我们会通过薪酬公平性审查，看看从事类似工作的员工之间是否仍存在这项差距。"}],"usage":"评估时注意依法定义的比较群体及岗位可比性。","new":true,"order":79,"distinction":"Pay equity 关注可比工作间及不同员工群体间的薪酬差异是否有合理依据。Internal equity 强调组织内部薪酬关系，pay transparency 强调薪酬信息如何披露。法律语境下，比较对象、标准和义务依适用规定而定。","aliases":[],"collocationZh":"开展薪酬公平性审查","collocationReview":"V18.2 模型编辑复核","ipaUK":"peɪ ˈekwɪti","ipaUS":"peɪ ˈekwətiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Pay equity","exampleZh":"薪酬公平性审查会比较职责相近的岗位，并考虑相关的定薪因素。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Market pricing","note":"依据外部市场数据确定岗位薪酬水平。","relation":"易混淆"},{"term":"Salary benchmark","note":"用于比较的市场薪酬基准。","relation":"易混淆"},{"term":"Salary survey","note":"收集市场薪酬数据的调查。","relation":"易混淆"},{"term":"Internal equity","note":"关注内部岗位及员工之间的薪酬合理性。","relation":"易混淆"},{"term":"Pay equity","note":"关注薪酬公平，尤其是无不合理差异。","relation":"本词"},{"term":"Pay compression","note":"不同经验或职责员工之间的薪酬差距过小。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"What did the pay equity review identify?","zh":"薪酬公平性审查发现了什么问题？"},"extension":{"en":"Document the criteria used to compare roles in the pay equity review.","zh":"记录薪酬公平性审查中比较岗位时所用的标准。"}},{"id":"HR2-40","moduleId":"m2","module":"薪酬激励与福利","term":"Deferred compensation","zh":"递延薪酬","definition":"按事先约定在未来日期或约定事件发生时支付的报酬，具体支付条件依相关协议和规定确定。","example":"Part of the executive’s pay package is structured as deferred compensation.","collocation":"deferred compensation arrangement","dialogue":[{"role":"Executive","en":"The statement shows a deferred amount from last year. Will it arrive with my next pay?","zh":"明细里有一笔去年的递延金额。下次发工资时会一起到账吗？"},{"role":"Compensation Partner","en":"I’ll look up the deferred compensation agreement. It has a separate payment schedule.","zh":"我查一下递延薪酬协议。那笔钱有单独的支付安排。"}],"usage":"","new":true,"order":80,"aliases":[],"distinction":"Deferred compensation 指按事先约定推迟支付的报酬。Long-term incentive 可以要求员工在未来满足服务或绩效条件后才获得奖励，某些方案兼具两者。延迟支付的时间、条件和税务处理依协议及适用规定而定。","collocationZh":"递延薪酬安排","collocationReview":"V18.2 模型编辑复核","ipaUK":"dɪˈfɜːd ˌkɒmpənˈseɪʃən","ipaUS":"dɪˈfɝːd ˌkɑːmpənˈseɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Deferred compensation","exampleZh":"这名高管的薪酬方案有一部分采用递延薪酬形式。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When is the deferred compensation paid?","zh":"递延薪酬什么时候支付？"},"extension":{"en":"The agreement lists the events that can trigger payment of deferred compensation.","zh":"协议列出了可以触发递延薪酬支付的事由。"}},{"id":"HR061","moduleId":"m3","module":"绩效管理","term":"Performance cycle","zh":"绩效周期","definition":"从设定目标到持续跟踪、沟通反馈和阶段或期末评价的一轮绩效管理过程。","example":"Our performance cycle begins with goal setting in January.","collocation":"annual performance cycle","dialogue":[{"role":"Manager","en":"A new analyst is joining in July. Do I wait until January to set their goals?","zh":"新分析师七月入职。我要等到明年一月再给他设目标吗？"},{"role":"HR Partner","en":"Set goals for the rest of this performance cycle. We can review them again when the next cycle opens.","zh":"先给这个绩效周期剩下的时间设目标。下一轮开始时，我们可以再回顾一遍。"}],"usage":"","new":false,"order":81,"aliases":[],"distinction":"Performance cycle 涵盖一个周期内的目标设定、进展跟踪、反馈和正式评估。Performance review 是其中一次正式的回顾或评价，check-in 通常是周期中的简短沟通。","collocationZh":"年度绩效周期","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈfɔːməns ˈsaɪkəl","ipaUS":"pɚˈfɔːrməns ˈsaɪkəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Performance cycle","exampleZh":"我们的绩效周期从一月设定目标开始。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the first step in our performance cycle?","zh":"我们绩效周期的第一步是什么？"},"extension":{"en":"The performance cycle includes a mid-year check-in and a year-end review.","zh":"这个绩效周期包括年中沟通和年终评估。"}},{"id":"HR062","moduleId":"m3","module":"绩效管理","term":"Goal setting","zh":"目标设定","definition":"确定预期成果、优先事项、时限和达成标准的过程。","example":"Effective goal setting requires clear priorities.","collocation":"facilitate a goal-setting discussion","dialogue":[{"role":"Manager","en":"Your draft lists six projects. Which two should take priority this quarter?","zh":"你的草稿列了六个项目。本季度应该优先推进哪两个？"},{"role":"Employee","en":"Let’s use our goal-setting meeting to pick them and agree on what success looks like.","zh":"我们在目标设定会上选出优先项目，再定好每项达到什么标准算完成。"}],"usage":"","new":false,"order":82,"aliases":[],"distinction":"Goal setting 是确定成果、优先事项及达成标准的过程。Performance objective 是设定出的一个具体绩效目标，goal review 是后来核对进展或调整目标的环节。","collocationZh":"主持目标设定讨论","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɡəʊl ˈsetɪŋ","ipaUS":"ɡoʊl ˈsetɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Goal setting","exampleZh":"有效的目标设定需要明确优先事项。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What makes goal setting effective?","zh":"怎样才能有效地制定目标？"},"extension":{"en":"Use the goal-setting discussion to agree on how progress will be measured.","zh":"在目标设定讨论中商定如何衡量进展。"}},{"id":"HR063","moduleId":"m3","module":"绩效管理","term":"SMART goals","zh":"SMART 目标","definition":"按 SMART 标准表述的目标，通常要求具体、可衡量、可实现、与工作重点相关并有明确时限。","example":"Managers help employees write SMART goals for the quarter.","collocation":"set SMART goals","dialogue":[{"role":"Employee","en":"I’ve written “respond faster to tickets.” Does that count as a SMART goal?","zh":"我写了「更快回复工单」。这算 SMART 目标吗？"},{"role":"Manager","en":"Give it a measure and a deadline. Try “Cut the average first-response time from eight hours to four by June 30.”","zh":"加上可衡量的标准和截止日期。可以写成「到 6 月 30 日，把平均首次响应时间从八小时缩短到四小时」。"}],"usage":"","new":false,"order":83,"aliases":[],"distinction":"SMART 是检查目标表述是否完整的一组标准，常见释义为 Specific、Measurable、Achievable、Relevant、Time-bound。KPI 是跟踪表现的指标，可以用来衡量某项 SMART 目标的完成情况。","collocationZh":"设定 SMART 目标","collocationReview":"V18.2 模型编辑复核","ipaUK":"smɑːt ɡəʊlz","ipaUS":"smɑːrt ɡoʊlz","ipaSource":"音素词典与英式语音规则推导","speakTerm":"smart goals","exampleZh":"管理者协助员工设定本季度的 SMART 目标。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should employees write their quarterly goals?","zh":"员工应如何制定季度目标？"},"extension":{"en":"SMART goals make it easier to check whether the agreed outcome was achieved.","zh":"SMART 目标让人更容易核对约定的成果是否达成。"}},{"id":"HR064","moduleId":"m3","module":"绩效管理","term":"Key performance indicators (KPIs)","zh":"关键绩效指标","definition":"用于持续跟踪某项关键业务或工作表现的可衡量指标。","example":"The team tracks key performance indicators in a monthly report.","collocation":"track KPIs","dialogue":[{"role":"Operations Manager","en":"The dashboard shows twelve metrics. Which ones should we bring to the weekly review?","zh":"看板上有十二项指标。周例会应该看哪几项？"},{"role":"HR Analyst","en":"Let’s start with the KPIs tied to this quarter’s priorities. For the service desk, that includes response time and reopen rate.","zh":"先看与本季度重点相关的关键绩效指标。服务台这边包括响应时间和工单重新打开率。"}],"usage":"","new":false,"order":84,"aliases":[],"distinction":"KPI 是用来判断关键业务或工作表现的指标，例如工单首次响应时间。KPI target 是预定的达标值。OKR 中的 key result 可以引用某项 KPI 与目标值来表述一段时期内要取得的变化。","collocationZh":"跟踪关键绩效指标（KPI）","collocationReview":"V18.2 模型编辑复核","ipaUK":"kiː pəˈfɔːməns ˈɪndɪˌkeɪtəz","ipaUS":"kiː pɚˈfɔːrməns ˈɪndəˌkeɪtɚz","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Key performance indicators (KPIs)","exampleZh":"团队在月报中跟踪关键绩效指标。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Where can we see the team's KPIs?","zh":"在哪里可以查看团队的关键绩效指标？"},"extension":{"en":"Review the KPI definitions before comparing results across teams.","zh":"跨团队比较结果前，请先核对关键绩效指标的定义。"}},{"id":"HR065","moduleId":"m3","module":"绩效管理","term":"Objectives and key results (OKRs)","zh":"目标与关键结果","definition":"由目标和用于验证目标达成程度的关键结果组成的目标管理框架。","example":"We review our OKRs at the end of each quarter.","collocation":"review OKRs","dialogue":[{"role":"Team Lead","en":"Our objective is to make onboarding easier. Is “rewrite the guide” enough as a key result?","zh":"我们的目标是让入职更省事。「重写指南」可以当关键结果吗？"},{"role":"HR Partner","en":"For this OKR, measure what improves for new hires. We could aim to cut the share who need help setting up their accounts.","zh":"这个 OKR 要衡量新员工的体验改善了什么。比如，可以把需要帮助才能开通账号的新员工占比降下来。"}],"usage":"OKR 是目标与关键结果框架；不要直接将其等同 KPI。","new":false,"order":85,"aliases":[],"distinction":"OKR 由目标及其可验证的关键结果组成，用来明确一段时间想实现的变化。KPI 通常持续衡量已有业务表现，可以作为制定关键结果的度量基础。","collocationZh":"回顾 OKR（目标与关键结果）","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɒbˈdʒektɪvz ænd kiː rɪˈzʌlts","ipaUS":"əbˈdʒektɪvz ənd kiː rɪˈzʌlts","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Objectives and key results (OKRs)","exampleZh":"我们在每个季度末回顾目标与关键结果（OKR）。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How often do we review the team's OKRs?","zh":"我们多久复盘一次团队的 OKR？"},"extension":{"en":"Each OKR should have an owner and a way to verify the results.","zh":"每个 OKR 都应明确负责人以及核验结果的方法。"}},{"id":"HR066","moduleId":"m3","module":"绩效管理","term":"Performance review","zh":"绩效评估","definition":"对员工在一定周期内的工作表现和成果进行的正式回顾或评价，也可讨论后续目标和发展安排。","example":"The performance review should include specific evidence.","collocation":"conduct a performance review","dialogue":[{"role":"Employee","en":"Will we talk about next year’s responsibilities at my performance review?","zh":"绩效评估时会谈到我明年的职责吗？"},{"role":"Manager","en":"Yes. We’ll start with this year’s work, then discuss what you’d like to take on next.","zh":"会。我们先回顾你今年的工作，再谈谈你接下来想承担什么职责。"}],"usage":"","new":false,"order":86,"aliases":[],"distinction":"Performance review 常指按周期进行的正式绩效回顾，可包含成果、改进方向和后续目标。在许多组织中，performance appraisal 与它互用，也有组织用 appraisal 专指正式考核和评级，用 check-in 指日常短会。","collocationZh":"开展绩效评估","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈfɔːməns rɪˈvjuː","ipaUS":"pɚˈfɔːrməns riːˈvjuː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Performance review","exampleZh":"绩效评估应包含具体的事实依据。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should managers include in a performance review?","zh":"经理在绩效评估中应包含哪些内容？"},"extension":{"en":"Bring examples from throughout the year to your performance review.","zh":"参加绩效评估时，请带上整个评估周期内的具体事例。"}},{"id":"HR067","moduleId":"m3","module":"绩效管理","term":"Self-assessment","zh":"自我评价／绩效自评","definition":"绩效评估中，员工对照目标和标准反思、说明自身表现并提供事例的做法，也指形成的书面材料。","example":"Please submit your self-assessment before the manager review.","collocation":"write a self-assessment","dialogue":[{"role":"Employee","en":"One goal was put on hold when the supplier pulled out. How should I handle that in my self-assessment?","zh":"供应商退出后，有个目标被搁置了。绩效自评里该怎么写？"},{"role":"Manager","en":"Explain why the work stopped and what you completed before then. Include the date we agreed to pause it.","zh":"说明为什么暂停，以及暂停前你完成了什么。把我们商定暂停的日期也写进去。"}],"usage":"","new":false,"order":87,"aliases":[],"distinction":"Self-assessment 是员工对自己表现作出的总结与评价，常用工作成果举证。Manager assessment 是主管独立作出的评价。两者可能使用同一套标准，结论也可能不同。","collocationZh":"撰写绩效自评","collocationReview":"V18.2 模型编辑复核","ipaUK":"self əˈses.mənt","ipaUS":"self əˈses.mənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Self-assessment","exampleZh":"请在直属主管开展评估前提交绩效自评。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should employees complete before the manager review?","zh":"经理开展评估前，员工需要完成什么？"},"extension":{"en":"Use your self-assessment to explain what changed and what you learned.","zh":"在绩效自评中说明发生了什么变化，以及你学到了什么。"}},{"id":"HR068","moduleId":"m3","module":"绩效管理","term":"Peer feedback","zh":"同事反馈","definition":"由同级同事或实际协作的同事就工作表现、行为或合作方式提供的反馈。","example":"Peer feedback can highlight collaboration strengths.","collocation":"collect peer feedback","dialogue":[{"role":"Manager","en":"You worked with Finance on most of this project. Who saw enough of your contribution to comment?","zh":"这个项目大部分时间你都在和财务合作。谁比较了解你的贡献，可以提供意见？"},{"role":"Employee","en":"I’ll ask Mei from Finance for peer feedback. We worked together on both releases.","zh":"我会请财务的梅对我的工作给些反馈。两次发布我们都一起做了。"}],"usage":"","new":false,"order":88,"aliases":[],"distinction":"Peer feedback 来自与评价对象处于同级或相近角色的同事，可包括其他团队的协作者。Manager feedback 来自上级，360-degree feedback 则汇集多个来源，可能包含同事反馈。","collocationZh":"收集同事反馈","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈpiə ˈfiːdbæk","ipaUS":"pɪr ˈfiːdbæk","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Peer feedback","exampleZh":"同事反馈能够帮助发现团队协作方面的优势。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What can peer feedback tell us about performance?","zh":"同事反馈能告诉我们哪些绩效信息？"},"extension":{"en":"Ask for peer feedback from people who worked with you directly.","zh":"向曾与你直接合作的同事征求反馈。"}},{"id":"HR069","moduleId":"m3","module":"绩效管理","term":"360-degree feedback","zh":"360 度反馈","definition":"从多个角色收集对同一员工工作行为或能力的反馈，来源可包括上级、同事、下属或员工本人。","example":"We use 360-degree feedback for leadership development.","collocation":"launch a 360-degree survey","dialogue":[{"role":"Team Lead","en":"Should I invite only people who report to me to complete the survey?","zh":"这份问卷只邀请我的直属下属填写吗？"},{"role":"HR Adviser","en":"For this 360-degree feedback exercise, include peers and your manager as well. Choose people who’ve seen you lead the work.","zh":"这次 360 度反馈还要邀请同级同事和你的上级。选那些见过你带团队做事的人。"}],"usage":"","new":false,"order":89,"aliases":[],"distinction":"360-degree feedback 汇集多个视角，例如上级、同事、下属及自评，来源按项目设计而定。Peer feedback 只代表同事视角。360 度反馈可用于发展辅导，匿名方式和用途由项目规则决定。","collocationZh":"发起 360 度反馈调查","collocationReview":"V18.2 模型编辑复核","ipaUK":"θriː ˈhʌndrəd ˈsɪksti dɪˈɡriː ˈfiːdbæk","ipaUS":"θriː ˈhʌndrəd ˈsɪkstiː dɪˈɡriː ˈfiːdbæk","ipaSource":"音素词典与英式语音规则推导","speakTerm":"three hundred sixty degree feedback","exampleZh":"我们用 360 度反馈支持领导力发展。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we collecting feedback for leadership development?","zh":"我们正在如何收集领导力发展方面的反馈？"},"extension":{"en":"The 360-degree feedback report groups responses by rater category.","zh":"360 度反馈报告按反馈者类别汇总答复。"}},{"id":"HR070","moduleId":"m3","module":"绩效管理","term":"Calibration meeting","zh":"绩效校准会","definition":"评估者共同核对绩效标准、评级和事实依据，以提高不同团队评价尺度一致性的会议。","example":"The calibration meeting will review ratings across departments.","collocation":"facilitate a calibration meeting","dialogue":[{"role":"Manager","en":"Two team members delivered similar results, but one had fewer resources. I gave them different ratings. Should I revisit those before the meeting?","zh":"两位员工的成果相近，但其中一位能用的资源更少，我给了他们不同的评级。开会前要重新看看这两个评级吗？"},{"role":"HR Partner","en":"Bring both examples to the calibration meeting. We’ll compare how the criteria apply before deciding whether to change either rating.","zh":"把两个案例都带到绩效校准会上。我们先对照评分标准，再决定是否需要调整评级。"}],"usage":"","new":false,"order":90,"aliases":[],"distinction":"Calibration meeting 让评估者对照标准和事实，检查各团队使用评级尺度是否一致。Review meeting 可指主管与员工讨论个人表现，forced distribution 则是按预设比例分配等级，两者用途各异。","collocationZh":"主持绩效校准会","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌkælɪˈbreɪʃən ˈmiːtɪŋ","ipaUS":"ˌkæləˈbreɪʃən ˈmiːtɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Calibration meeting","exampleZh":"绩效校准会将审查各部门的绩效评级。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What will we compare in the calibration meeting?","zh":"绩效校准会上将比较哪些内容？"},"extension":{"en":"Bring the evidence behind any unusually high or low rating to the calibration meeting.","zh":"参加绩效校准会时，请带上明显偏高或偏低评级的事实依据。"}},{"id":"HR071","moduleId":"m3","module":"绩效管理","term":"Performance rating","zh":"绩效等级","definition":"依据绩效标准对员工在某一周期内的表现给出的等级。","example":"Each performance rating must be supported by evidence.","collocation":"justify a performance rating","dialogue":[{"role":"Employee","en":"My performance rating stayed the same. What would it take to move up a level?","zh":"我的绩效等级没变。要提高一级，我需要做到什么？"},{"role":"Manager","en":"At the next level, you'd be expected to lead a rollout from planning through launch.","zh":"高一级要求你能带头把一个上线项目从规划推进到发布。"}],"usage":"","new":false,"order":91,"aliases":[],"distinction":"Performance rating 是评估给出的等级，如「达到预期」。Performance review 是回顾工作成果、交流反馈并讨论下一步的过程，有些评估流程不设等级。","collocationZh":"说明绩效等级的评定依据","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈfɔːməns ˈreɪtɪŋ","ipaUS":"pɚˈfɔːrməns ˈreɪtɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Performance rating","exampleZh":"每个绩效等级都须有事实依据。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should support an employee's performance rating?","zh":"员工的绩效评级应由哪些依据支撑？"},"extension":{"en":"The form records the performance rating and the manager’s comments in separate fields.","zh":"表单分别记录绩效等级和经理评语。"}},{"id":"HR072","moduleId":"m3","module":"绩效管理","term":"Rating scale","zh":"评分量表","definition":"用于划分和解释评分档位的一套标准，通常包含等级名称及各档的含义。","example":"The new rating scale has five clearly defined levels.","collocation":"apply a rating scale","dialogue":[{"role":"Manager","en":"Where does “met expectations” sit on our rating scale?","zh":"在我们的评分量表里，「达到预期」是第几档？"},{"role":"HRBP","en":"It’s a three. Check the notes under level four before you rate the team.","zh":"是第三档。给团队成员评分前，先看一下第四档的说明。"}],"usage":"","new":false,"order":92,"aliases":[],"distinction":"Rating scale 规定有哪些评分档位及各档所代表的水平。Scoring rubric（评分规则表）进一步说明应从哪些维度观察表现，以及每个水平对应的具体表现。","collocationZh":"使用评分量表","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈreɪtɪŋ skeɪl","ipaUS":"ˈreɪtɪŋ skeɪl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Rating scale","exampleZh":"新的评分量表有五个等级，每一级都有明确定义。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How many levels does the new rating scale have?","zh":"新的评分量表有几个等级？"},"extension":{"en":"Managers can open the rating scale directly from the review form.","zh":"经理可以直接从绩效评估表打开评分量表。"}},{"id":"HR073","moduleId":"m3","module":"绩效管理","term":"Competency framework","zh":"胜任力模型","definition":"按岗位或层级组织能力要求的一套框架，可包含通用能力、专业能力及相应行为标准。","example":"The competency framework defines what effective coaching looks like at each management level.","collocation":"update the competency framework","dialogue":[{"role":"Hiring Manager","en":"Should we ask senior engineers the same collaboration questions we use for junior hires?","zh":"招聘资深工程师时，协作方面的问题可以沿用初级岗位那套吗？"},{"role":"HRBP","en":"Keep the topic, but use the competency framework to set a higher bar. Ask for an example of resolving a disagreement between teams.","zh":"协作这个主题可以保留，但要按胜任力模型提高要求。请对方举例说明如何解决跨团队分歧。"}],"usage":"","new":false,"order":93,"aliases":[],"distinction":"Competency framework（胜任力框架或模型）集中呈现不同岗位或层级所需的能力及其行为标准。Job description（岗位说明书）说明某个岗位承担的职责，也可引用框架中的能力要求。","collocationZh":"更新胜任力模型","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkɒmpɪtənsi ˈfreɪmwɜːk","ipaUS":"ˈkɑːmpətɪnsiː ˈfreɪmwɝːk","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Competency framework","exampleZh":"胜任力模型说明了各管理层级应如何有效辅导员工。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we guide competency assessments?","zh":"我们该怎样指导胜任力评估？"},"extension":{"en":"We added accessibility to the competency framework for product designers.","zh":"我们在产品设计师的胜任力模型中加入了无障碍设计要求。"}},{"id":"HR074","moduleId":"m3","module":"绩效管理","term":"Behavioral indicators","zh":"行为指标","definition":"用于判断某项胜任力是否体现出来的可观察行为描述，可按熟练程度分级。","example":"Behavioral indicators show managers what to look for when assessing a competency.","collocation":"define behavioral indicators","dialogue":[{"role":"Manager","en":"I’ve written “takes ownership,” but that feels vague. What should I put in the rubric?","zh":"我写了「有责任心」，但感觉太笼统。评分表里应该怎么写？"},{"role":"HRBP","en":"For the behavioral indicator, you could write “Names the next owner before closing a handover.”","zh":"可以把行为指标写成「结束交接前，明确下一步由谁负责」。"}],"usage":"","new":false,"order":94,"aliases":[],"distinction":"Behavioral indicator（英式拼写 behavioural indicator）描述可观察的做法，例如「交接时确认接手人和截止日期」。Outcome metric（结果指标）衡量产出，例如按期交付率。两者可共同用于绩效评估。","collocationZh":"明确行为指标","collocationReview":"V18.2 模型编辑复核","ipaUK":"bɪˈheɪ.vjə.rəl ˈɪn.dɪ.keɪ.təz","ipaUS":"bɪˈheɪ.vjɚ.əl ˈɪn.də.keɪ.t̬ɚz","ipaSource":"https://dictionary.cambridge.org/dictionary/english/behavioral | https://dictionary.cambridge.org/dictionary/english/indicator","speakTerm":"Behavioral indicators","exampleZh":"行为指标说明经理评估某项胜任力时应观察哪些表现。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What can make performance discussions more objective?","zh":"怎样让绩效沟通更加客观？"},"extension":{"en":"The two interviewers agreed on behavioral indicators for active listening.","zh":"两位面试官就积极倾听的行为指标达成了一致。"},"searchAliases":["Behavior indicators"]},{"id":"HR075","moduleId":"m3","module":"绩效管理","term":"Continuous feedback","zh":"持续反馈","definition":"在日常工作中持续、及时地交流对工作表现的观察、肯定和改进建议。","example":"Continuous feedback helps employees adjust quickly.","collocation":"encourage continuous feedback","dialogue":[{"role":"Employee","en":"If I’m putting too much detail into the client updates, could you tell me after the next call?","zh":"如果我给客户汇报时讲得太细，下次通话结束后能跟我说一声吗？"},{"role":"Manager","en":"Of course. Let’s keep the feedback going both ways. Tell me if my briefs are missing anything, too.","zh":"当然。咱们平时互相反馈，我交代任务时要是漏了什么，你也告诉我。"}],"usage":"","new":false,"order":95,"aliases":[],"distinction":"Continuous feedback 强调贯穿工作过程，可随具体事件发生，也可融入定期沟通。Formal performance review（正式绩效评估）按约定周期汇总表现，并可能形成书面结果。","collocationZh":"鼓励持续反馈","collocationReview":"V18.2 模型编辑复核","ipaUK":"kənˈtɪnjuːəs ˈfiːdbæk","ipaUS":"kənˈtɪnjuːəs ˈfiːdbæk","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Continuous feedback","exampleZh":"持续反馈有助于员工及时调整工作方式。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we help employees adjust before the formal review?","zh":"如何帮助员工在正式评估前及时调整？"},"extension":{"en":"A two-minute debrief after each demo gives the team a simple way to keep continuous feedback going.","zh":"每次演示后花两分钟复盘，就能让团队持续交流反馈。"}},{"id":"HR076","moduleId":"m3","module":"绩效管理","term":"One-on-one meeting","zh":"一对一会议","definition":"两人单独进行的工作沟通。在绩效管理中，常指经理与员工定期讨论近况、困难和发展需求的会议。","example":"The one-on-one meeting is a good time to discuss blockers.","collocation":"schedule a one-on-one meeting","dialogue":[{"role":"Employee","en":"Can we use part of our one-on-one to talk about moving into product work?","zh":"一对一开会时，能留点时间聊聊我转做产品的可能性吗？"},{"role":"Manager","en":"Yes. Put it first on the agenda so we have enough time.","zh":"可以，把它放在议程第一项，这样时间充裕一些。"}],"usage":"","new":false,"order":96,"aliases":[],"distinction":"One-on-one meeting 描述两人单独沟通的形式。Performance review 描述周期性评估这一目的，可能以一对一形式进行。英式英语也常说 one-to-one meeting。","collocationZh":"安排一对一会议","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌwʌn.ɒnˈwʌn ˈmiː.tɪŋ","ipaUS":"ˌwʌn.ɑːnˈwʌn ˈmiː.t̬ɪŋ","ipaSource":"https://dictionary.cambridge.org/dictionary/english/one | https://dictionary.cambridge.org/dictionary/english/on | https://dictionary.cambridge.org/dictionary/english/meeting","speakTerm":"One-on-one meeting","exampleZh":"碰到工作卡点，可以在一对一会议上讨论。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When can employees raise obstacles with their managers?","zh":"员工什么时候可以向经理反映工作障碍？"},"extension":{"en":"Could we move our one-on-one meeting to Thursday morning?","zh":"咱们的一对一会议能改到周四上午吗？"}},{"id":"HR077","moduleId":"m3","module":"绩效管理","term":"Mid-year check-in","zh":"年中绩效回顾","definition":"在年度绩效周期中途回顾目标进展、讨论所需支持，并按需要调整后续安排的沟通。","example":"We use the mid-year check-in to revisit priorities.","collocation":"complete a mid-year check-in","dialogue":[{"role":"Employee","en":"The vendor delay has pushed the launch into October. Should I update my goal now?","zh":"供应商延期，导致上线推迟到十月。我现在要改目标吗？"},{"role":"Manager","en":"Bring your revised timeline to the mid-year check-in. We’ll agree on what’s still in scope this year.","zh":"把调整后的时间表带到年中绩效回顾会上，我们一起确认今年还能完成哪些事项。"}],"usage":"","new":false,"order":97,"aliases":[],"distinction":"Mid-year check-in 关注年度中途的进展和下半年的调整。Year-end review 汇总全年表现。年中沟通是否留档或给出评级，取决于组织制度。","collocationZh":"完成年中绩效回顾","collocationReview":"V18.2 模型编辑复核","ipaUK":"mɪd ˈjiə tʃek ɪn","ipaUS":"mɪd jɪr tʃek ɪn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Mid-year check-in","exampleZh":"我们借年中绩效回顾重新审视工作重点。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we use the mid-year check-in?","zh":"我们应如何开展年中绩效回顾？"},"extension":{"en":"I’ve booked my mid-year check-in for the week before I go on leave.","zh":"我已把年中绩效回顾安排在休假前一周。"}},{"id":"HR078","moduleId":"m3","module":"绩效管理","term":"Year-end review","zh":"年终绩效评估","definition":"在年度绩效周期末回顾工作成果、行为表现和发展情况的正式评估。","example":"The year-end review will focus on results and lessons learned.","collocation":"prepare a year-end review","dialogue":[{"role":"Employee","en":"Should I include the project I finished before I transferred to your team?","zh":"我调到你团队之前做完的那个项目，要写进去吗？"},{"role":"Manager","en":"Yes, include it in your year-end review. I’ll ask your previous manager for feedback on your work.","zh":"要，写进年终绩效评估材料里。我会请你上一位经理提供那段工作的反馈。"}],"usage":"","new":false,"order":98,"aliases":[],"distinction":"Year-end review 聚焦当年度的表现与发展情况。Annual review 强调每年举行一次，可以按财年、入职周年或组织设定的其他时间进行。","collocationZh":"准备年终绩效评估","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈjiə end rɪˈvjuː","ipaUS":"jɪr end riːˈvjuː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Year-end review","exampleZh":"年终绩效评估将着重讨论工作成果和经验教训。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we discuss during the year-end review?","zh":"年终评估时应该讨论哪些内容？"},"extension":{"en":"Employees can submit their self-assessments before their year-end reviews.","zh":"员工可以在年终绩效评估前提交自评。"}},{"id":"HR079","moduleId":"m3","module":"绩效管理","term":"Performance improvement plan (PIP)","zh":"绩效改进计划","definition":"针对具体绩效差距设定改进目标、期限、支持措施和评估方式的正式计划。","example":"The performance improvement plan specifies weekly targets and the support available to the employee.","collocation":"launch a PIP","dialogue":[{"role":"Employee","en":"Our new reporting tool won’t be ready next week. How will you measure my progress in the meantime?","zh":"新的报表工具下周还用不了。在这期间，你会怎么评估我的改进进度？"},{"role":"Manager","en":"For the first PIP checkpoint, let’s use the error log in the current system. I’ll update the plan to make that clear.","zh":"绩效改进计划的第一个检查节点，我们先用现有系统的差错日志评估。我会把这一点写进计划。"}],"usage":"绩效改进计划通常应明确目标、时间、资源和评估方式；不能把它等同于解雇通知。","new":false,"order":99,"aliases":[],"distinction":"PIP 针对已识别的绩效差距，列明预期表现和验收方式。Development plan（发展计划）侧重能力成长。PIP 的流程与可能后果需结合组织政策和适用劳动法规判断。","collocationZh":"启动绩效改进计划（PIP）","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈfɔːməns ɪmˈpruːvmənt plæn","ipaUS":"pɚˈfɔːrməns ˌɪmˈpruːvmənt plæn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Performance improvement plan","exampleZh":"绩效改进计划明确了每周目标以及员工可获得的支持。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What must the performance improvement plan include?","zh":"绩效改进计划必须包括哪些内容？"},"extension":{"en":"The employee received a copy of the performance improvement plan after the meeting.","zh":"会后，员工收到了一份绩效改进计划。"}},{"id":"HR080","moduleId":"m3","module":"绩效管理","term":"Underperformance","zh":"绩效不达标","definition":"工作表现低于岗位要求或约定的绩效标准。","example":"Managers should address underperformance with timely feedback.","collocation":"manage underperformance","dialogue":[{"role":"Manager","en":"Sam has missed two deadlines since we reassigned the approvals. Should I flag underperformance?","zh":"我们调整审批分工后，萨姆有两次没按时交付。我该把这记为绩效不达标吗？"},{"role":"HRBP","en":"First check when the approvals came through. His part may have been ready on time.","zh":"先查一下审批是什么时候通过的。他负责的部分可能按时就做好了。"}],"usage":"","new":false,"order":100,"aliases":[],"distinction":"Underperformance 指工作未达到既定标准。Misconduct 指违反行为规范或制度。两者可能同时出现，判断原因时应分别核实工作要求、实际表现和行为事实。","collocationZh":"处理绩效不达标问题","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌʌn.də.pəˈfɔː.məns","ipaUS":"ˌʌn.dɚ.pɚˈfɔːr.məns","ipaSource":"https://dictionary.cambridge.org/dictionary/english/underperformance","speakTerm":"Underperformance","exampleZh":"发现绩效不达标时，经理应及时给出反馈。","ipaReview":"完整词头英美音标文本核对","ipaNote":"英美音标据 Cambridge 发音词头核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should a manager respond to underperformance?","zh":"经理应如何应对绩效不达标的情况？"},"extension":{"en":"The team looked at staffing and workloads before drawing conclusions about what was causing underperformance.","zh":"团队在判断绩效不达标的原因之前，先检查了人员配置和工作量。"}},{"id":"HR081","moduleId":"m3","module":"绩效管理","term":"High performer","zh":"高绩效员工","definition":"在一段时间内持续达到较高绩效水平的员工，具体标准由组织明确。","example":"The high performer took on a challenging cross-team project.","collocation":"recognize high performers","dialogue":[{"role":"Manager","en":"Could I ask Maya to mentor the new hires? She’s one of our high performers.","zh":"我能请玛雅带带新员工吗？她是我们团队的高绩效员工之一。"},{"role":"HRBP","en":"Ask if she’s interested, and agree on what she can take off her plate to make time.","zh":"先问问她是否愿意，再商量可以减掉哪些工作，给辅导留出时间。"}],"usage":"","new":false,"order":101,"aliases":[],"distinction":"High performer 依据员工在现岗位的实际表现判断。High-potential employee（高潜人才）依据对未来承担更复杂职责的潜力判断。同一员工可能同时符合两者。","collocationZh":"表彰高绩效员工","collocationReview":"V18.2 模型编辑复核","ipaUK":"haɪ pəˈfɔːmə","ipaUS":"haɪ pɚˈfɔːrmɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"High performer","exampleZh":"这位高绩效员工承担了一项具有挑战性的跨团队项目。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What challenging work has the high performer taken on?","zh":"这名高绩效员工承担了哪些具有挑战性的工作？"},"extension":{"en":"Even high performers need clear feedback when their responsibilities change.","zh":"职责发生变化时，高绩效员工也需要得到明确的反馈。"}},{"id":"HR082","moduleId":"m3","module":"绩效管理","term":"Stretch goal","zh":"挑战性目标","definition":"高于通常绩效预期、需要额外努力或新的做法才有望实现的目标。","example":"We agreed on a stretch goal for the next quarter.","collocation":"set a stretch goal","dialogue":[{"role":"Manager","en":"Could we bring turnaround time down to two days?","zh":"我们能把处理时间缩短到两天吗？"},{"role":"Team Lead","en":"Two days is a stretch goal while approvals are still manual. Let’s try it on one queue first.","zh":"审批还得手工处理，两天是个挑战性目标。我们先选一个队列试试吧。"}],"usage":"","new":false,"order":102,"aliases":[],"distinction":"Stretch goal 是有意设得更具挑战性的目标。Baseline target（基准目标）是按正常预期制定的达标线。是否将挑战性目标计入正式评级，应事先明确。","collocationZh":"设定挑战性目标","collocationReview":"V18.2 模型编辑复核","ipaUK":"stretʃ ɡəʊl","ipaUS":"stretʃ ɡoʊl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Stretch goal","exampleZh":"我们商定了下一季度的一项挑战性目标。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Did we agree on a more ambitious goal for next quarter?","zh":"我们是否就下季度更具挑战性的目标达成一致了？"},"extension":{"en":"We kept service quality as a condition for meeting the stretch goal.","zh":"我们把维持服务质量列为达成挑战性目标的条件。"}},{"id":"HR083","moduleId":"m3","module":"绩效管理","term":"Goal alignment","zh":"目标对齐","definition":"使组织、团队和个人目标相互支持，并协调跨团队优先事项的过程或状态。","example":"Goal alignment helps everyone focus on shared priorities.","collocation":"improve goal alignment","dialogue":[{"role":"Sales Lead","en":"We’re pushing for more sign-ups, but Support is trying to cut its backlog. Can we make both work?","zh":"我们在争取更多注册用户，但客服团队正忙着消化积压工单。这两个目标能兼顾吗？"},{"role":"Operations Lead","en":"We need better goal alignment. Let’s agree on how many new accounts Support can onboard each week.","zh":"两边的目标得协调一下。先一起定个数，看看客服团队每周能协助多少新客户启用账号。"}],"usage":"","new":false,"order":103,"aliases":[],"distinction":"Goal alignment 关注不同层级或不同团队的目标是否互相支持。Goal cascading（目标分解）是把上层目标转成下层目标的方法之一。平级团队也可以直接协调目标。","collocationZh":"提高各层级目标的一致性","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɡəʊl əˈlaɪnmənt","ipaUS":"ɡoʊl əˈlaɪnmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Goal alignment","exampleZh":"目标对齐有助于大家把精力放在共同的重点上。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Why is goal alignment important across the company?","zh":"为什么公司各层级的目标对齐很重要？"},"extension":{"en":"The planning workshop exposed a gap in goal alignment between Product and Sales.","zh":"规划会上，大家发现产品团队和销售团队的目标有一处没有对齐。"}},{"id":"HR084","moduleId":"m3","module":"绩效管理","term":"Performance gap","zh":"绩效差距","definition":"按同一口径比较时，实际工作表现与预期绩效标准之间的差距。","example":"We found a performance gap in on-time project delivery.","collocation":"close a performance gap","dialogue":[{"role":"Manager","en":"Our target is ten cases a day, but we’re closing seven. Where’s the time going?","zh":"目标是每天处理完十个工单，我们只能完成七个。时间花在哪儿了？"},{"role":"Team Lead","en":"Most of the performance gap comes from waiting for approvals. I tracked a sample last week.","zh":"这个绩效差距主要来自等待审批。我上周抽样跟踪过。"}],"usage":"","new":false,"order":104,"aliases":[],"distinction":"Performance gap 先描述结果或表现差多少。Competency gap（胜任力差距）指能力与要求之间的差距，可能是绩效差距的原因之一。流程、工具和资源也需要排查。","collocationZh":"缩小绩效差距","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈfɔːməns ɡæp","ipaUS":"pɚˈfɔːrməns ɡæp","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Performance gap","exampleZh":"我们发现项目按时交付的表现没有达到预期。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What gap did we identify in the delivery results?","zh":"交付结果中发现了哪些绩效差距？"},"extension":{"en":"We agreed to measure the performance gap again after the backlog was cleared.","zh":"我们商定，待积压清理完再衡量一次绩效差距。"}},{"id":"HR085","moduleId":"m3","module":"绩效管理","term":"Development plan","zh":"发展计划","definition":"列明拟提升的能力、学习实践、支持资源及检视安排的成长计划。","example":"The development plan includes training and mentoring.","collocation":"create a development plan","dialogue":[{"role":"Employee","en":"I’ve finished the presentation course. Could I lead part of the next client meeting?","zh":"我上完演示技巧课了。下次客户会议能让我主持一个环节吗？"},{"role":"Manager","en":"Yes. Let’s add that to your development plan, and I’ll give you feedback right after the meeting.","zh":"可以。我们把这项实践写进你的发展计划，我会在会后马上给你反馈。"}],"usage":"","new":false,"order":105,"aliases":[],"distinction":"Development plan 可以面向个人或团队，安排成长目标和行动。Individual development plan（IDP）明确以某一位员工为对象，通常还会记录负责人、完成时间和进展。","collocationZh":"制定发展计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"dɪˈveləpmənt plæn","ipaUS":"dɪˈveləpmənt plæn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Development plan","exampleZh":"发展计划包括培训和导师指导。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What actions are included in this employee's development plan?","zh":"这名员工的发展计划包含哪些行动？"},"extension":{"en":"We set aside an hour next month to review progress on the development plan.","zh":"我们下个月留出一小时回顾发展计划的进展。"}},{"id":"HR086","moduleId":"m3","module":"绩效管理","term":"Recognition","zh":"员工认可与表彰","definition":"通过感谢、表扬或奖励，对员工的具体贡献和积极行为表示肯定。","example":"Regular recognition can reinforce desired behaviors.","collocation":"give meaningful recognition","dialogue":[{"role":"Manager","en":"I’d like to thank Lina at the all-hands for spotting the billing error. Is she comfortable with that?","zh":"我想在全员会上感谢莉娜发现账单错误。她愿意接受公开表扬吗？"},{"role":"HRBP","en":"Ask her first. She may prefer private recognition from you and the project lead.","zh":"先问问她。她可能更希望你和项目负责人私下向她道谢。"}],"usage":"不要只译成抽象“认可”而忽略 HR 奖励场景。","new":false,"order":106,"distinction":"Recognition 侧重肯定贡献，可以是口头感谢、公开表彰或附带奖励。Monetary reward（现金奖励）强调以金钱给予回报，也可能按激励规则发放。","aliases":[],"collocationZh":"有针对性地肯定员工的贡献","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌrekəɡˈnɪʃən","ipaUS":"ˌrekəɡˈnɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Recognition","exampleZh":"经常肯定员工的具体表现，有助于强化组织倡导的工作行为。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can managers reinforce positive work behaviors?","zh":"经理如何强化员工积极的工作行为？"},"extension":{"en":"A brief note of recognition can show someone exactly why their contribution mattered.","zh":"一封简短的感谢信，可以让对方明白自己的贡献具体帮到了哪里。"}},{"id":"HR087","moduleId":"m3","module":"绩效管理","term":"Promotion readiness","zh":"晋升准备度","definition":"员工在多大程度上已具备承担目标职级或更高职责的能力和相关经验。","example":"Promotion readiness requires evidence beyond strong current performance.","collocation":"assess promotion readiness","dialogue":[{"role":"Manager","en":"Priya led the rollout, but she hasn’t handled a budget yet. What should we do before the promotion review?","zh":"普丽娅牵头完成了上线，但还没管过预算。晋升评审前我们该怎么安排？"},{"role":"HRBP","en":"Let her own the pilot budget. That will give us more evidence of her promotion readiness.","zh":"让她负责试点预算，这样我们就有更多依据判断她是否已经准备好晋升。"}],"usage":"","new":false,"order":107,"aliases":[],"distinction":"Promotion readiness 关注员工现在或近期能否胜任目标职责。Promotion eligibility（晋升资格）关注员工是否符合制度规定的申报条件。实际晋升还取决于组织的决策流程。","collocationZh":"评估晋升准备度","collocationReview":"V18.2 模型编辑复核","ipaUK":"prəˈməʊʃən ˈredinəs","ipaUS":"prəˈmoʊʃən ˈrediːnəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Promotion readiness","exampleZh":"判断员工是否准备好晋升，还需考察其当前岗位绩效以外的证据。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Is strong performance alone enough to confirm promotion readiness?","zh":"仅凭优秀绩效就能认定员工具备晋升准备度吗？"},"extension":{"en":"The panel revisited his promotion readiness after he took on a larger team.","zh":"他接手规模更大的团队后，评审小组重新评估了他的晋升准备度。"}},{"id":"HR088","moduleId":"m3","module":"绩效管理","term":"Manager assessment","zh":"直属经理评价","definition":"由直属经理在绩效流程中根据工作成果、行为表现等对员工做出的评价。","example":"The manager assessment should reference observable outcomes.","collocation":"complete a manager assessment","dialogue":[{"role":"Manager","en":"Can I include work the employee did during the secondment?","zh":"员工借调期间完成的工作可以写进去吗？"},{"role":"HRBP","en":"Yes. Ask the host manager for examples, then summarize the relevant ones in your manager assessment.","zh":"可以，先请借调部门的经理提供事例，再把相关内容写进你负责填写的评价。"}],"usage":"","new":false,"order":108,"aliases":[],"distinction":"Manager assessment 在绩效表单语境中指经理给出的评价。Self-assessment 由员工回顾并评价自己的表现。材料标题应注明评价人和对象，以免与对经理本人的评价混淆。","collocationZh":"完成直属经理评价","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈmæn.ɪ.dʒə əˈses.mənt","ipaUS":"ˈmæn.ə.dʒɚ əˈses.mənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Manager assessment","exampleZh":"直属经理在评价中应引用可核实的工作成果。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What evidence should a manager use in the assessment?","zh":"经理在评价时应使用哪些证据？"},"extension":{"en":"The manager assessment was shared with the employee after the calibration meeting.","zh":"绩效校准会结束后，直属经理的评价发给了员工本人。"}},{"id":"HR089","moduleId":"m3","module":"绩效管理","term":"Rating bias","zh":"绩效评分偏差","definition":"绩效评分因近期印象、单一突出特征等与评估标准无关的因素而发生的系统性偏移。","example":"Calibration helps us reduce rating bias across teams.","collocation":"reduce rating bias","dialogue":[{"role":"Manager","en":"I keep thinking about last month’s client escalation when I score Elena. Am I giving it too much weight?","zh":"给埃琳娜评分时，我总想到上个月那起升级处理的客户投诉。我是不是把这件事看得太重了？"},{"role":"HRBP","en":"Let’s look at the full year. Giving that one incident too much weight could introduce rating bias.","zh":"我们把全年的情况一起看。过分看重这一次事件，可能会造成评分偏差。"}],"usage":"","new":false,"order":109,"aliases":[],"distinction":"Rating bias 是绩效评分中系统性偏移的总称。Recency bias（近因偏差）是其中一种，指赋予近期事件过高权重，忽视整个评估周期的表现。","collocationZh":"降低绩效评分偏差","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈreɪtɪŋ ˈbaɪəs","ipaUS":"ˈreɪtɪŋ ˈbaɪəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Rating bias","exampleZh":"绩效校准有助于减少团队之间的评分偏差。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we reduce bias when assigning performance ratings?","zh":"我们怎样降低绩效评级中的偏差？"},"extension":{"en":"The reviewers checked for rating bias by comparing how each manager applied the same criteria.","zh":"评估人员对照各位经理使用同一套标准的方式，检查是否存在评分偏差。"}},{"id":"HR090","moduleId":"m3","module":"绩效管理","term":"Performance documentation","zh":"绩效记录","definition":"记录绩效目标、反馈、工作实例与评估决定的材料，包括纸质或电子记录。","example":"Good performance documentation supports fair decisions.","collocation":"maintain performance documentation","dialogue":[{"role":"Manager","en":"I have my check-in notes in a shared team folder. Should I leave them there?","zh":"我把绩效面谈记录放在团队共享文件夹里。可以继续放在那里吗？"},{"role":"HRBP","en":"Please check who can access that folder. Our policy specifies where employee performance documentation belongs.","zh":"请先确认谁能访问该文件夹。员工绩效记录应存放在哪里，我们的内部政策有规定。"}],"usage":"","new":false,"order":110,"aliases":[],"distinction":"Performance documentation 泛指评估前后留存的目标、反馈和成果证据。Performance review form（绩效评估表）是用于汇总评价结果的特定表单。","collocationZh":"妥善保存绩效记录","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈfɔːməns ˌdɒkjuːmənˈteɪʃən","ipaUS":"pɚˈfɔːrməns ˌdɑːkjəmenˈteɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Performance documentation","exampleZh":"完整的绩效记录有助于作出公正判断。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Why is it important to keep performance records?","zh":"为什么保留绩效记录很重要？"},"extension":{"en":"Add the date and the relevant goal to each entry in the performance documentation.","zh":"请在每条绩效记录中注明日期和相关目标。"}},{"id":"HR3-31","moduleId":"m3","module":"绩效管理","term":"Performance calibration","zh":"绩效校准","definition":"跨经理或团队对照同一绩效标准和相关证据，复核初步评级的一致性。","example":"Performance calibration should be based on documented evidence.","collocation":"calibrate performance ratings","dialogue":[{"role":"Manager","en":"Two leads delivered similar results, but we’ve put them a level apart. Can we look at that in calibration?","zh":"两位组长的业绩相近，但初评分差了一档。校准时能一起看看吗？"},{"role":"HRBP","en":"Yes. Bring the original targets and the project handover notes for both roles.","zh":"可以。请带上两个岗位原先的目标和项目交接记录。"}],"usage":"","new":true,"order":111,"aliases":[],"distinction":"Performance calibration 让评估者共同核对同一等级是否按一致标准评定。Forced distribution（强制分布）按预设比例或名额分配等级。校准可以在没有固定分布要求的情况下进行。","collocationZh":"校准绩效评级","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈfɔːməns ˌkælɪˈbreɪʃən","ipaUS":"pɚˈfɔːrməns ˌkæləˈbreɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Performance calibration","exampleZh":"绩效校准应以有记录可查的证据为依据。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we make performance calibration more consistent?","zh":"如何提高绩效校准的一致性？"},"extension":{"en":"We added a second performance calibration session for managers who work across regions.","zh":"我们为负责跨区域团队的经理增设了一场绩效校准会。"}},{"id":"HR3-32","moduleId":"m3","module":"绩效管理","term":"Performance conversation","zh":"绩效沟通","definition":"经理与员工围绕工作目标、实际表现、改进措施和发展需要进行的双向交流。","example":"A good performance conversation includes specific examples.","collocation":"hold a performance conversation","dialogue":[{"role":"Employee","en":"The written feedback says I should speak up earlier. Can we go over what happened at the last planning meeting?","zh":"书面反馈说我应该更早提出意见。我们能回顾一下上次规划会的情况吗？"},{"role":"Manager","en":"Yes. Let’s use our performance conversation tomorrow to walk through it and agree on what to try next time.","zh":"可以。明天绩效沟通时，我们把当时的情况过一遍，再商量下次可以怎么做。"}],"usage":"","new":true,"order":112,"aliases":[],"distinction":"Performance conversation 是围绕工作表现的交流，可发生在日常辅导或正式评估中。Performance review 是按组织流程进行的阶段性评估，常包含书面记录或评级。","collocationZh":"开展绩效沟通","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈfɔːməns kɒnvəˈseɪʃən","ipaUS":"pɚˈfɔːrməns ˌkɑːnvɚˈseɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Performance conversation","exampleZh":"有效的绩效沟通会结合具体事例。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should managers prepare for a performance conversation?","zh":"经理在绩效沟通前应准备什么？"},"extension":{"en":"Leave time in the performance conversation for the employee to raise concerns.","zh":"绩效沟通时要留出时间，让员工提出自己的顾虑。"}},{"id":"HR3-33","moduleId":"m3","module":"绩效管理","term":"Goal cascading","zh":"目标逐级分解","definition":"将组织目标逐级转化为下属团队或个人可执行、可衡量的目标。","example":"Goal cascading connects team priorities to business strategy.","collocation":"cascade organizational goals","dialogue":[{"role":"Operations Director","en":"The company wants to cut delivery delays. What should our warehouse team own?","zh":"公司想减少交付延误。仓库团队应该负责其中哪一块？"},{"role":"Warehouse Manager","en":"Let’s cascade that goal by setting a target for the share of orders we pack before the daily cutoff. That’s something we can control.","zh":"我们就把每天截止时间前完成打包的订单占比作为分解目标。这项指标是我们能控制的。"}],"usage":"","new":true,"order":113,"aliases":[],"distinction":"Goal cascading 描述上层目标向下转化的过程。Goal alignment 描述不同层级或不同团队的目标是否相互支持，也可通过横向协商实现。","collocationZh":"将组织目标逐级分解","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɡəʊl kəˈskeɪdɪŋ","ipaUS":"ɡoʊl kæˈskeɪdɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Goal cascading","exampleZh":"通过逐级分解目标，团队的工作重点可以与业务战略衔接。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do our team goals connect to company priorities?","zh":"团队目标如何与公司优先事项衔接？"},"extension":{"en":"As part of goal cascading, each team agreed on a measure it could influence directly.","zh":"在逐级分解目标的过程中，每个团队都确定了一项自己能直接影响的衡量指标。"}},{"id":"HR3-34","moduleId":"m3","module":"绩效管理","term":"Balanced scorecard","zh":"平衡计分卡","definition":"把战略目标转化为多维度指标与行动的管理工具，经典框架包括财务、客户、内部流程、学习与成长四个视角。","example":"The balanced scorecard tracks financial and nonfinancial outcomes.","collocation":"balanced scorecard framework","dialogue":[{"role":"Finance Lead","en":"Cost per order is down, but we’re getting more complaints. Where should that show up?","zh":"每单成本降了，但投诉多了。这应该体现在哪里？"},{"role":"Strategy Lead","en":"Put the complaints under the customer perspective in the balanced scorecard. We’ll review them alongside cost.","zh":"把投诉放在平衡计分卡的客户维度，和成本一起看。"}],"usage":"","new":true,"order":114,"aliases":[],"distinction":"Balanced scorecard 将战略目标与不同视角的指标和行动联系起来。KPI dashboard（关键绩效指标看板）用于展示指标状态与趋势，也可用于呈现平衡计分卡的部分数据。","collocationZh":"平衡计分卡框架","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈbælənst ˈskɔːkɑːd","ipaUS":"ˈbælənst ˈskɔːrkɑːrd","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Balanced scorecard","exampleZh":"平衡计分卡用于跟踪财务和非财务成果。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Why are we using a balanced scorecard this year?","zh":"今年为什么要使用平衡计分卡？"},"extension":{"en":"The balanced scorecard connects a staff training initiative to a service quality objective.","zh":"平衡计分卡将一项员工培训举措与服务质量目标联系起来。"}},{"id":"HR3-35","moduleId":"m3","module":"绩效管理","term":"Performance threshold","zh":"绩效门槛","definition":"取得某项绩效评级、获得特定激励资格或进入后续评估所需达到的最低绩效要求。","example":"Under this plan, teams must meet a performance threshold to qualify for an incentive payout.","collocation":"meet the performance threshold","dialogue":[{"role":"Sales Manager","en":"We won’t hit the target this quarter. Is there still a chance we’ll qualify for a payout?","zh":"我们这季度完不成目标了。还有机会拿到奖金吗？"},{"role":"Compensation Partner","en":"You’re above the performance threshold, so you’re still eligible under this plan. The final amount depends on the full payout formula.","zh":"你们超过了绩效门槛，根据本方案仍有资格。实际金额要按完整的奖金计算规则来定。"}],"usage":"","new":true,"order":115,"aliases":[],"distinction":"Performance threshold 是达标底线，常用于判定是否具备某项资格。Performance target（绩效目标）是希望达到的水平，可以高于门槛。","collocationZh":"达到绩效门槛","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈfɔːməns ˈθreʃəʊld","ipaUS":"pɚˈfɔːrməns ˈθreʃoʊld","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Performance threshold","exampleZh":"根据本方案，团队须达到绩效门槛，才有资格获得激励奖金。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What happens if we do not meet the performance threshold?","zh":"如果未达到绩效门槛，会发生什么？"},"extension":{"en":"The policy sets a separate performance threshold for each service tier.","zh":"该制度为各服务层级分别设定绩效门槛。"}},{"id":"HR3-36","moduleId":"m3","module":"绩效管理","term":"Improvement milestone","zh":"改进里程碑","definition":"绩效改进过程中，在约定时间前需要达到并可核验的阶段性成果。","example":"The first improvement milestone is to complete five handovers in a row without missing a required field.","collocation":"track improvement milestones","dialogue":[{"role":"Employee","en":"We processed fewer requests this week. Can we move the first improvement milestone back?","zh":"这周处理的请求偏少。第一个改进里程碑可以往后延吗？"},{"role":"Manager","en":"Let’s keep Friday’s check-in and use it to agree on a date that gives you enough cases to work with.","zh":"周五还是照常沟通，到时一起定个日期，确保你有足够的案例可以处理。"}],"usage":"","new":true,"order":116,"aliases":[],"distinction":"Improvement milestone 说明某一阶段要完成什么。Checkpoint（检查节点）指何时核对进展。一次检查可以核验一个或多个阶段成果。","collocationZh":"跟踪改进里程碑","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈpruːvmənt ˈmaɪlstəʊn","ipaUS":"ˌɪmˈpruːvmənt ˈmaɪlstoʊn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Improvement milestone","exampleZh":"第一个改进里程碑是连续完成五次交接，每次都填齐必填项。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the first improvement milestone in the plan?","zh":"这个计划的第一个改进里程碑是什么？"},"extension":{"en":"We recorded the evidence for each improvement milestone as it was reached.","zh":"我们每达成一项改进里程碑，就记录相应的佐证材料。"}},{"id":"HR3-37","moduleId":"m3","module":"绩效管理","term":"Evidence-based assessment","zh":"基于证据的评估","definition":"按既定标准，依据可核查的工作成果、行为记录等材料作出的评估。","example":"Evidence-based assessment uses work samples and documented outcomes to support rating decisions.","collocation":"evidence-based performance assessment","dialogue":[{"role":"Manager","en":"The manager’s notes say Jo is a strong presenter, but there aren’t any examples. Can we use that?","zh":"经理的评语说乔很擅长演示，但没有举例。这个能作为依据吗？"},{"role":"HRBP","en":"For an evidence-based assessment, let’s review two recorded demos against the presentation criteria.","zh":"要做基于证据的评估，我们就按演示标准看两段录下来的演示吧。"}],"usage":"","new":true,"order":117,"aliases":[],"distinction":"Evidence-based assessment 强调判断须有可查证的材料支持。Data-driven assessment（数据驱动评估）通常强调用数据识别模式或形成判断。绩效证据也可包括与评估标准相关的定性材料。","collocationZh":"基于证据的绩效评估","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈevɪdəns beɪst əˈses.mənt","ipaUS":"ˈevədəns beɪst əˈses.mənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Evidence-based assessment","exampleZh":"基于证据的评估以工作样本和有记录的成果为评级提供依据。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What evidence supports this performance rating?","zh":"有哪些证据能够支持这一绩效评级？"},"extension":{"en":"For a fair evidence-based assessment, check that the records cover the entire review period.","zh":"为使基于证据的评估更公正，请确认材料覆盖整个评估周期。"}},{"id":"HR3-38","moduleId":"m3","module":"绩效管理","term":"Goal weighting","zh":"目标权重","definition":"绩效评价中各项目标在综合评价所占的比例，或分配这些比例的方法。","example":"Goal weighting reflects each objective's relative importance.","collocation":"adjust goal weighting","dialogue":[{"role":"Employee","en":"I’m spending most of my week on the migration now, but it’s only 10 percent of my review. Can we change that?","zh":"现在我一周大部分时间都在做迁移项目，但它只占绩效评估的 10%。可以调整吗？"},{"role":"Manager","en":"Let’s check how our policy handles mid-cycle changes to goal weighting. Then we can agree on what to put in writing.","zh":"我们先看制度对周期内调整目标权重有什么规定，再一起确认要记录哪些内容。"}],"usage":"","new":true,"order":118,"aliases":[],"distinction":"Goal weighting 决定各项目标对总评的影响程度。Goal attainment（目标达成情况）说明每项目标完成得怎样。综合评分可按规则对各目标表现加权。","collocationZh":"调整目标权重","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɡəʊl ˈweɪtɪŋ","ipaUS":"ɡoʊl ˈweɪtɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Goal weighting","exampleZh":"目标权重反映各项目标在综合评估中的相对重要性。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Should we adjust goal weighting after the priority shift?","zh":"优先事项改变后，我们是否应该调整目标权重？"},"extension":{"en":"The form shows how goal weighting affects the overall score.","zh":"表单显示了目标权重如何影响总分。"}},{"id":"HR3-39","moduleId":"m3","module":"绩效管理","term":"Feedback loop","zh":"反馈闭环","definition":"收集并处理反馈、向反馈者说明采取的行动或处理决定，再跟踪结果的循环。","example":"We need a feedback loop to verify the changes are working.","collocation":"close the feedback loop","dialogue":[{"role":"Employee","en":"We reported the scheduling issue last month. Did anything come of it?","zh":"我们上个月就反馈了排班问题，后来有进展吗？"},{"role":"Team Lead","en":"We’re piloting a new handover time next week. I’ll close the feedback loop by sharing the results with everyone who raised it.","zh":"下周会试行新的交接时间。我会把试行结果告诉每位反馈过这个问题的同事，把反馈流程走完。"}],"usage":"","new":true,"order":119,"aliases":[],"distinction":"Feedback loop 指从收集反馈到处理、沟通结果并复查的机制。Follow-up（后续跟进）可以是其中一次行动，例如向提出建议的人确认整改后的体验。","collocationZh":"完成反馈闭环","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈfiːdbæk luːp","ipaUS":"ˈfiːdbæk luːp","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Feedback loop","exampleZh":"我们需要建立反馈闭环，确认改动是否奏效。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will we close the feedback loop after the review?","zh":"评估结束后，我们将如何形成反馈闭环？"},"extension":{"en":"The feedback loop helped us catch a new issue after we changed the shift schedule.","zh":"调整排班后，我们通过反馈闭环发现了一个新问题。"}},{"id":"HR3-40","moduleId":"m3","module":"绩效管理","term":"Career conversation","zh":"职业发展面谈","definition":"经理、导师或 HR 与员工探讨职业兴趣、长期方向和可尝试的发展机会的交流。","example":"At our company, managers hold career conversations twice a year.","collocation":"career development conversation","dialogue":[{"role":"Employee","en":"I like leading projects, but I’m not sure I want direct reports. Can we talk through my options?","zh":"我喜欢带项目，但还不确定自己想不想直接带人。我们能聊聊有哪些选择吗？"},{"role":"Manager","en":"Let’s use our next career conversation to look at both the specialist and management tracks.","zh":"下次职业发展面谈时，我们一起看看专业和管理这两条发展通道。"}],"usage":"","new":true,"order":120,"aliases":[],"distinction":"Career conversation 聚焦员工未来想走什么方向、可通过什么经历探索。Performance conversation 主要讨论工作表现、反馈和后续行动。职业发展也可以是绩效沟通中的一项议题。","collocationZh":"职业发展面谈","collocationReview":"V18.2 模型编辑复核","ipaUK":"kəˈriə kɒnvəˈseɪʃən","ipaUS":"kɚˈɪr ˌkɑːnvɚˈseɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Career conversation","exampleZh":"在我们公司，经理每年与员工开展两次职业发展面谈。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When should we schedule the next career conversation?","zh":"下一次职业发展沟通应安排在什么时候？"},"extension":{"en":"The career conversation gave me a chance to ask about a lateral move into operations.","zh":"职业发展面谈给了我机会，向经理了解能否平级调到运营岗位。"}},{"id":"HR091","moduleId":"m4","module":"学习培训与人才发展","term":"Learning needs analysis","zh":"学习需求分析","definition":"从业务目标和目标人群出发，识别知识与技能差距，并判断培训、辅导或在岗实践等学习支持能否弥补差距。","example":"We completed a learning needs analysis before designing the program.","collocation":"conduct a learning needs analysis","dialogue":[{"role":"Operations Manager","en":"We’ve had more ticket errors since the tool changed. Should we bring everyone in for training?","zh":"工具更换后工单错误多了。要不要把大家都叫来培训？"},{"role":"L&D Partner","en":"Let’s do a learning needs analysis first. We should check whether people need practice or whether the form itself is confusing.","zh":"先做一次学习需求分析。我们得弄清楚，大家是需要练习，还是表单本身不好理解。"}],"usage":"也常写为 Training Needs Analysis（TNA）；两者范围可能不同。","new":false,"order":121,"aliases":[],"distinction":"Learning needs analysis 可覆盖课程、辅导和在岗实践等学习需求。Training needs analysis 或 training needs assessment（常缩写为 TNA）常用于判断是否需要培训及需要哪些培训。各组织界定的范围可能重叠。","collocationZh":"开展学习需求分析","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈlɜːnɪŋ niːdz əˈnæləˌsɪs","ipaUS":"ˈlɝːnɪŋ niːdz əˈnæləsəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Learning needs analysis","exampleZh":"在设计培训项目之前，我们完成了学习需求分析。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we do before designing next quarter's training?","zh":"在设计下一季度培训之前，我们应做什么？"},"extension":{"en":"The learning needs analysis included interviews with employees on both shifts.","zh":"学习需求分析包括对两个班次员工的访谈。"}},{"id":"HR092","moduleId":"m4","module":"学习培训与人才发展","term":"Learning objective","zh":"学习目标","definition":"课程或学习活动旨在让学员掌握并能展示的知识、技能或行为。","example":"Each module has a measurable learning objective.","collocation":"define learning objectives","dialogue":[{"role":"Trainer","en":"Is “understand the escalation process” clear enough for the first lesson?","zh":"第一课的目标写「理解升级流程」够清楚吗？"},{"role":"Instructional Designer","en":"For an observable learning objective, try “Choose the right escalation route for three sample cases.”","zh":"把学习目标写成能观察到的行为，比如「为三个模拟案例选出正确的升级处理路径」。"}],"usage":"","new":false,"order":122,"aliases":[],"distinction":"Learning objective 通常是设计阶段设定的学习目标。Learning outcome 可指预期展示的成果，也可指评估中实际观察到的成果。课程文件中若两者并用，应注明所指。","collocationZh":"明确学习目标","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈlɜːnɪŋ ɒbˈdʒektɪv","ipaUS":"ˈlɝːnɪŋ əbˈdʒektɪv","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Learning objective","exampleZh":"每个课程模块都有可衡量的学习目标。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we define a measurable learning objective?","zh":"如何定义可衡量的学习目标？"},"extension":{"en":"We dropped the activity because it didn’t support any learning objective.","zh":"这项活动无法帮助学员实现任何一个学习目标，所以我们删掉了。"}},{"id":"HR093","moduleId":"m4","module":"学习培训与人才发展","term":"Training roadmap","zh":"培训路线图","definition":"围绕业务或能力目标，按阶段安排培训项目、实施顺序和关键节点的规划。","example":"The training roadmap covers the next two quarters.","collocation":"publish a training roadmap","dialogue":[{"role":"Sales Manager","en":"Can we move negotiation training up to April? The new team starts then.","zh":"谈判培训能提前到四月吗？新团队那时入职。"},{"role":"L&D Lead","en":"April works if we move the product basics forward too. I’ll update the training roadmap.","zh":"如果产品基础课也提前，四月可以。我来更新培训路线图。"}],"usage":"","new":false,"order":123,"aliases":[],"distinction":"Training roadmap 展示一段时期内的培养重点、实施阶段及先后依赖关系。Training calendar（培训日历）列出已排定课程的日期和场次。","collocationZh":"发布培训路线图","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtreɪnɪŋ ˈrəʊdmæp","ipaUS":"ˈtreɪnɪŋ ˈroʊdmæp","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Training roadmap","exampleZh":"培训路线图涵盖未来两个季度。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Do we have a timeline for the upcoming training programs?","zh":"即将开展的培训项目有时间安排吗？"},"extension":{"en":"The training roadmap sets aside the final quarter for supervised practice.","zh":"培训路线图将最后一个季度留给有辅导的实践。"}},{"id":"HR094","moduleId":"m4","module":"学习培训与人才发展","term":"Training budget","zh":"培训预算","definition":"为一定时期内的培训活动及相关支出安排的经费，可涵盖讲师、课程、工具和场地等费用。","example":"The training budget has been approved for this year.","collocation":"allocate a training budget","dialogue":[{"role":"Trainer","en":"The venue quote came in higher than expected. Is there room in the training budget?","zh":"场地报价比预期高，培训预算还有余量吗？"},{"role":"L&D Lead","en":"Only if we use an internal trainer for the second session. I’ll check who’s available.","zh":"第二场改用内部讲师才有余量。我来看看谁有空。"}],"usage":"","new":false,"order":124,"aliases":[],"distinction":"Training budget 是为培训计划安排的可用经费额度。Training spend（培训支出）指实际发生的费用。比较两者时需使用相同期间和费用范围。","collocationZh":"分配培训预算","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtreɪnɪŋ ˈbʌdʒɪt","ipaUS":"ˈtreɪnɪŋ ˈbʌdʒɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Training budget","exampleZh":"今年的培训预算已经获批。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How much can we spend on the training program?","zh":"这个培训项目可以投入多少预算？"},"extension":{"en":"Travel for instructors is a separate line in this year’s training budget.","zh":"今年的培训预算单独列出了讲师差旅费。"}},{"id":"HR095","moduleId":"m4","module":"学习培训与人才发展","term":"Onboarding curriculum","zh":"新员工入职课程体系","definition":"按入职阶段安排的学习内容与活动组合，帮助新员工熟悉组织、岗位及开展工作所需的工具与规则。","example":"The onboarding curriculum includes product and security training.","collocation":"refresh the onboarding curriculum","dialogue":[{"role":"Manager","en":"New hires keep getting the tool demo before their accounts are active. Can we move it?","zh":"新员工总是在账号还没开通时就看工具演示。这一课能往后挪吗？"},{"role":"L&D Partner","en":"Yes. I’ll move the demo to day three in the onboarding curriculum, after IT has set up access.","zh":"可以。我会把入职课程体系里的演示移到第三天，等 IT 开通权限后再上。"}],"usage":"","new":false,"order":125,"aliases":[],"distinction":"Onboarding curriculum 指为新员工安排的课程、练习和学习顺序。Onboarding program（入职项目）涵盖更广，还可能包括设备发放、团队介绍与入职手续。","collocationZh":"更新新员工入职课程体系","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɒnˈbɔː.dɪŋ kʌˈrɪkjʊləm","ipaUS":"ɑːnˈbɔːr.dɪŋ kɚˈɪkjələm","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Onboarding curriculum","exampleZh":"新员工入职课程体系包含产品和安全培训。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What will new hires learn during onboarding?","zh":"新员工在入职培训中将学习什么？"},"extension":{"en":"The onboarding curriculum gives new hires a week to practice in the test system.","zh":"入职课程为新员工留出一周时间在测试系统里练习。"}},{"id":"HR096","moduleId":"m4","module":"学习培训与人才发展","term":"Instructor-led training","zh":"讲师主导式培训","definition":"由讲师实时讲解、组织练习和回答问题的培训，可在线下现场或线上同步进行。","example":"Instructor-led training gives participants time to discuss complex cases with the instructor.","collocation":"deliver instructor-led training","dialogue":[{"role":"Trainer","en":"Should we just send the slides to the night shift?","zh":"夜班同事那边，我们只把课件发过去就行吗？"},{"role":"L&D Lead","en":"They need practice with the new equipment. Let’s schedule a second instructor-led session at the start of their shift.","zh":"他们得练习操作新设备。我们在夜班刚开始时再安排一场讲师授课吧。"}],"usage":"","new":false,"order":126,"aliases":[],"distinction":"Instructor-led training（ILT）的学习进度与互动由讲师实时组织，形式可为线下或线上。Self-paced learning（自主进度学习）由学员在允许的时间范围内自行安排学习节奏。","collocationZh":"开展讲师主导式培训","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪnˈstrʌktə led ˈtreɪnɪŋ","ipaUS":"ˌɪnˈstrʌktɚ led ˈtreɪnɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Instructor-led training","exampleZh":"在讲师主导式培训中，学员有时间与讲师讨论复杂案例。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Is this course delivered by a facilitator?","zh":"这门课程由讲师现场授课吗？"},"extension":{"en":"We added a live demonstration to the instructor-led training for new technicians.","zh":"我们在面向新技术员的讲师主导式培训中加入了实时演示。"}},{"id":"HR097","moduleId":"m4","module":"学习培训与人才发展","term":"Virtual classroom","zh":"线上课堂","definition":"供讲师与学员远程同步上课和互动的在线环境，常支持讨论、演示及分组活动。","example":"The virtual classroom allows participants to ask questions.","collocation":"join a virtual classroom","dialogue":[{"role":"Participant","en":"Do I need a headset for tomorrow’s virtual classroom?","zh":"明天上线上课需要戴耳麦吗？"},{"role":"Trainer","en":"Yes, please. You’ll be discussing a case in a breakout room with two colleagues.","zh":"请准备一个。你会和两位同事在分组讨论室里分析一个案例。"}],"usage":"","new":false,"order":127,"aliases":[],"distinction":"Virtual classroom 强调学员和讲师远程同步参与及互动。Webinar（网络研讨会）也可实时举行，通常更偏重面向听众的演讲或展示，两者的互动形式可能重叠。","collocationZh":"参加线上课堂","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈvɜːtʃuːəl ˈklæsruːm","ipaUS":"ˈvɝːtʃuːəl ˈklæsruːm","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Virtual classroom","exampleZh":"学员可以在线上课堂实时提问。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can participants attend this workshop remotely?","zh":"参与者能否远程参加这场工作坊？"},"extension":{"en":"The trainer opened the virtual classroom early so participants could test their audio.","zh":"讲师提前开放了线上课堂，方便学员测试音频。"}},{"id":"HR098","moduleId":"m4","module":"学习培训与人才发展","term":"E-learning","zh":"在线学习","definition":"借助电子设备和数字内容开展的学习，在企业培训中多指通过网络平台学习课程。","example":"Our self-paced e-learning course lets employees choose when to study.","collocation":"launch an e-learning course","dialogue":[{"role":"Employee","en":"Can I do the e-learning on my phone? I won’t have my laptop on site.","zh":"我能用手机上这门在线课程吗？现场我不会带笔记本电脑。"},{"role":"L&D Partner","en":"Yes, the lessons work on mobile. The final simulation needs a computer, though.","zh":"课程内容可以用手机学。最后的模拟练习需要用电脑。"}],"usage":"","new":false,"order":128,"aliases":[],"distinction":"E-learning 强调使用数字技术或在线媒介学习。Self-paced learning 强调自定进度，可以通过在线课程，也可以用纸质阅读或离线练习完成。","collocationZh":"上线一门在线课程","collocationReview":"V18.2 模型编辑复核","ipaUK":"iː ˈlɜːnɪŋ","ipaUS":"iː ˈlɝːnɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"E-learning","exampleZh":"这门按个人进度学习的在线课程允许员工自行安排学习时间。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can employees complete this learning online?","zh":"员工可以在线完成这项学习吗？"},"extension":{"en":"The e-learning course saves your progress between sessions.","zh":"这门在线课程会保存你的学习进度，下次可以接着学。"}},{"id":"HR099","moduleId":"m4","module":"学习培训与人才发展","term":"Learning management system (LMS)","zh":"学习管理系统","definition":"用于分配和发布课程、管理报名并记录学习进度及完成情况的平台。","example":"The learning management system tracks course completion.","collocation":"assign a course in the LMS","dialogue":[{"role":"Employee","en":"I finished the course, but the LMS still says it’s incomplete. Can you check?","zh":"我学完了，但学习管理系统还显示未完成。能帮我查一下吗？"},{"role":"Learning Administrator","en":"I can see your quiz score. Go back to the last screen and click “Finish” so the LMS records the completion.","zh":"我能看到你的测验成绩。回到最后一页，点一下「完成」，系统就会记录。"}],"usage":"","new":false,"order":129,"aliases":[],"distinction":"LMS 侧重课程分配、进度和完成记录。LXP（学习体验平台）通常侧重内容发现、推荐和个性化学习体验，部分平台兼有两类功能。","collocationZh":"在学习管理系统中分配课程","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈlɜːnɪŋ ˈmænɪdʒmənt ˈsɪstəm","ipaUS":"ˈlɝːnɪŋ ˈmænədʒmənt ˈsɪstəm","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Learning management system","exampleZh":"学习管理系统用于跟踪课程完成情况。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Where can employees access the course materials?","zh":"员工可以在哪里获取课程资料？"},"extension":{"en":"Employees can download their training certificates from the LMS.","zh":"员工可以从学习管理系统下载培训证书。"}},{"id":"HR100","moduleId":"m4","module":"学习培训与人才发展","term":"Blended learning","zh":"混合式学习","definition":"将线上学习与讲师指导、现场活动或实操等环节有计划地结合起来，使不同环节服务于同一组学习目标。","example":"Blended learning combines short videos with workshops.","collocation":"design a blended learning program","dialogue":[{"role":"Trainer","en":"We keep running out of time for role-play. Could we move the policy walkthrough online?","zh":"角色扮演练习总是时间不够。能不能把政策讲解挪到线上？"},{"role":"L&D Lead","en":"Yes. Let’s try blended learning. We’ll send the walkthrough in advance and use the workshop to practice difficult conversations.","zh":"可以。我们试试混合式学习，先发线上讲解，再用工作坊练习怎么处理棘手的谈话。"}],"usage":"","new":false,"order":130,"aliases":[],"distinction":"Blended learning 让不同学习形式在同一培养方案中相互衔接。Hybrid delivery（混合授课）在企业培训中常指同一场活动让远程和到场人员共同参与，具体用法因机构而异。","collocationZh":"设计混合式学习方案","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈblendɪd ˈlɜːnɪŋ","ipaUS":"ˈblendɪd ˈlɝːnɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Blended learning","exampleZh":"混合式学习将短视频与工作坊结合起来。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can we combine online study with live workshops?","zh":"能否将线上学习与现场工作坊结合起来？"},"extension":{"en":"The blended learning pilot pairs prework with a supervised practice session.","zh":"混合式学习试点将课前学习任务与有指导的练习结合起来。"}},{"id":"HR101","moduleId":"m4","module":"学习培训与人才发展","term":"Microlearning","zh":"微学习","definition":"将学习内容组织成短小单元，每个单元围绕一个具体主题或学习目标。","example":"Microlearning is useful for quick policy refreshers.","collocation":"create a microlearning module","dialogue":[{"role":"Store Manager","en":"Can we turn the returns policy into one five-minute video?","zh":"能把整套退货政策做成一段五分钟的视频吗？"},{"role":"Instructional Designer","en":"For microlearning, I’d start with when to issue a refund. We can cover exceptions in a separate module.","zh":"如果做成微学习，我会先讲清楚什么时候该退款。例外情况可以另做一节。"}],"usage":"","new":false,"order":131,"aliases":[],"distinction":"Microlearning 强调每个短单元解决一个具体学习需求。Just-in-time learning（即时学习）强调在需要时获取学习支持。微学习单元可以用作即时学习资源。","collocationZh":"制作微学习模块","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈmaɪ.krəʊˌlɜː.nɪŋ","ipaUS":"ˈmaɪ.kroʊˌlɝː.nɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Microlearning","exampleZh":"微学习适合快速复习公司政策。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we fit learning into a busy workday?","zh":"怎样让学习融入忙碌的工作日？"},"extension":{"en":"A microlearning module can give staff a quick refresher before a seasonal task.","zh":"微学习模块可以帮助员工在处理季节性任务前快速温习要点。"}},{"id":"HR102","moduleId":"m4","module":"学习培训与人才发展","term":"Training attendance","zh":"培训出勤情况","definition":"员工是否参加培训的情况，可按需要记录到场、线上签到或实际参训时长。","example":"Training attendance rose from 18 to 24 after we moved the session to the afternoon.","collocation":"track training attendance","dialogue":[{"role":"Trainer","en":"Four people joined online, but only the people in the room signed the sheet. How should I record attendance?","zh":"有四个人在线参加，但只有到现场的人签了到。出勤该怎么记？"},{"role":"Learning Administrator","en":"Use the meeting log for remote attendees and check it against the sign-in sheet before you submit the numbers.","zh":"用会议记录核对线上参训人员，提交人数前再和签到表比一遍。"}],"usage":"attendance 在培训场景与工作考勤有所区别。","new":false,"order":132,"distinction":"Training attendance 记录是否到场或参与。Course completion（课程完成）按课程规则确认所需环节是否完成，可能还要求提交练习或通过测验。","aliases":[],"collocationZh":"记录培训出勤情况","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtreɪnɪŋ əˈtendəns","ipaUS":"ˈtreɪnɪŋ əˈtendəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Training attendance","exampleZh":"培训改到下午后，出勤人数从 18 人增加到 24 人。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we record who attended the workshop?","zh":"我们如何记录工作坊的出勤人员？"},"extension":{"en":"Please submit the training attendance record by Friday.","zh":"请在周五前提交培训出勤记录。"}},{"id":"HR103","moduleId":"m4","module":"学习培训与人才发展","term":"Completion rate","zh":"培训／课程完成率","definition":"在约定统计期间内，符合课程完成条件的人数占所选统计人群的比例，分母可为应学人数、报名人数或实际参训人数。","example":"The completion rate reached 92 percent this month.","collocation":"training completion rate","dialogue":[{"role":"Analyst","en":"One report shows an 89 percent completion rate. The other shows 76 percent. Are they using the same cutoff date?","zh":"一份报告显示完成率是 89%，另一份显示 76%。它们用的是同一个统计截止日吗？"},{"role":"L&D Lead","en":"Yes, but the first report only includes people who started the course. The second counts everyone assigned to it.","zh":"截止日一样，但第一份只统计了开始学习的人，第二份纳入了所有应学人员。"}],"usage":"该词在此属于培训模块，应明确分母是报名、应学还是实际参训人员。","new":false,"order":133,"distinction":"Completion rate（完成率）衡量按课程规则完成任务的人所占比例，pass rate（通过率）衡量达到合格标准的人所占比例。解读两者时都需确认分母，完成条件也可能包含通过测验。","aliases":[],"collocationZh":"培训完成率","collocationReview":"V18.2 模型编辑复核","ipaUK":"kəmˈpliːʃən reɪt","ipaUS":"kəmˈpliːʃən reɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Completion rate","exampleZh":"本月的课程完成率达到了92%。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How many participants completed the course?","zh":"有多少学员完成了课程？"},"extension":{"en":"The dashboard shows the completion rate for each intake of new hires.","zh":"仪表板按每批新员工显示课程完成率。"}},{"id":"HR104","moduleId":"m4","module":"学习培训与人才发展","term":"Knowledge check","zh":"知识测验","definition":"用简短题目或任务检验学员是否掌握课程要点，结果常用于即时反馈。","example":"A short knowledge check follows each lesson.","collocation":"take a knowledge check","dialogue":[{"role":"Trainer","en":"Most people selected the wrong approval route on question three. Should we go through the whole policy again?","zh":"第三题里大多数人选错了审批路径。要把整套政策再讲一遍吗？"},{"role":"Instructional Designer","en":"Let’s use the knowledge check to pinpoint the confusion and add a worked example to that section.","zh":"我们用这次知识测验找出大家具体卡在哪儿，再给那一节加一道带讲解的例题。"}],"usage":"","new":false,"order":134,"aliases":[],"distinction":"Knowledge check 通常是简短的理解检查，多用于及时发现知识盲点。Certification exam（认证考试）按规定标准判断是否达到某项资格要求。","collocationZh":"做一次知识测验","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈnɒlɪdʒ tʃek","ipaUS":"ˈnɑːlədʒ tʃek","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Knowledge check","exampleZh":"每节课后都有一次简短的知识测验。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will we verify what participants understood?","zh":"我们将如何验证学员学到了什么？"},"extension":{"en":"The knowledge check explains why each incorrect option is wrong.","zh":"知识测验会逐项解释错误选项为什么不对。"}},{"id":"HR105","moduleId":"m4","module":"学习培训与人才发展","term":"Skills assessment","zh":"技能评估","definition":"通过实操任务、工作样本或测验，按明确标准判断某项技能的掌握程度。","example":"The skills assessment identified gaps in data analysis.","collocation":"run a skills assessment","dialogue":[{"role":"Team Lead","en":"Everyone passed the quiz, but I’m still seeing errors in the spreadsheet. What should we check next?","zh":"大家都通过了测验，但电子表格里还是有错误。下一步该检查什么？"},{"role":"L&D Partner","en":"Let’s run a skills assessment. Give them a sample file and ask them to reconcile it without the walkthrough.","zh":"我们做一次技能评估，给大家一份样表，让他们不看操作演示，独立完成对账。"}],"usage":"","new":false,"order":135,"aliases":[],"distinction":"Skills assessment 衡量学员能否完成某项操作及完成质量。Knowledge check 主要确认对概念或规则的理解。会说出操作步骤与能独立完成操作是不同层面的证据。","collocationZh":"开展技能评估","collocationReview":"V18.2 模型编辑复核","ipaUK":"skɪlz əˈses.mənt","ipaUS":"skɪlz əˈses.mənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Skills assessment","exampleZh":"技能评估发现了数据分析方面的技能差距。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we assess participants' current skills?","zh":"我们该如何评估学员目前的技能水平？"},"extension":{"en":"The skills assessment includes a timed troubleshooting exercise.","zh":"技能评估包含一项限时故障排查练习。"}},{"id":"HR106","moduleId":"m4","module":"学习培训与人才发展","term":"Competency gap","zh":"胜任力差距","definition":"个人或团队当前展现的胜任力水平与岗位或业务所需水平之间的差距。","example":"We found a competency gap in stakeholder communication.","collocation":"address a competency gap","dialogue":[{"role":"Manager","en":"She knows how to build the report, but in client meetings she can’t explain what the figures mean. What should we work on?","zh":"她会做报表，但开客户会议时说不清楚数字意味着什么。我们该帮她练什么？"},{"role":"L&D Partner","en":"That points to a competency gap in client communication. Let’s start with a practice briefing and give her feedback on the explanation.","zh":"这可能是客户沟通方面的胜任力差距。先练一次简短汇报，再就她的讲解给出反馈。"}],"usage":"","new":false,"order":136,"aliases":[],"distinction":"Competency gap 可能涉及知识、技能以及运用它们时展现的行为。Skills gap（技能差距）通常指某项具体操作能力不足。岗位胜任力可以包含多项技能。","collocationZh":"弥补胜任力差距","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkɒmpɪtənsi ɡæp","ipaUS":"ˈkɑːmpətɪnsiː ɡæp","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Competency gap","exampleZh":"我们发现，与岗位要求相比，利益相关方沟通能力仍有差距。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What skills are missing from the current team?","zh":"当前团队缺少哪些技能？"},"extension":{"en":"We mapped the competency gap against the requirements for the senior role.","zh":"我们对照资深岗位的要求，梳理了胜任力差距。"}},{"id":"HR107","moduleId":"m4","module":"学习培训与人才发展","term":"Upskilling","zh":"技能提升","definition":"在现有岗位或职业领域中学习新的相关技能，或提高已有技能水平，以应对职责变化。","example":"Upskilling helps employees adapt to new tools.","collocation":"invest in upskilling","dialogue":[{"role":"Operations Manager","en":"Our schedulers will keep their roles, but next year they’ll need to use the forecasting tool. How should we prepare them?","zh":"排班员还是做原来的工作，不过明年要用预测工具。我们该怎么帮他们做好准备？"},{"role":"L&D Partner","en":"Let’s put together an upskilling plan. We can start with a guided forecast using last month’s data.","zh":"我们做个技能提升计划，可以先用上个月的数据带大家做一次预测。"}],"usage":"","new":false,"order":137,"aliases":[],"distinction":"Upskilling 面向现岗位或相关工作，重点是把技能做深或扩展到新工具。Reskilling 侧重获得不同岗位或工作所需的技能。两者均可通过在岗练习或正式培训开展。","collocationZh":"投入资源提升员工技能","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌʌpˈskɪl.ɪŋ","ipaUS":"ˌʌpˈskɪl.ɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Upskilling","exampleZh":"提升技能有助于员工适应新工具。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we help employees build skills for their current roles?","zh":"如何帮助员工提升现有岗位需要的技能？"},"extension":{"en":"The upskilling pilot pairs experienced operators with colleagues learning the new controls.","zh":"在技能提升试点中，经验丰富的操作员会带同事熟悉新的控制装置。"}},{"id":"HR108","moduleId":"m4","module":"学习培训与人才发展","term":"Reskilling","zh":"转岗技能再培训","definition":"帮助员工掌握不同岗位或显著不同的工作任务所需的新技能的培养过程。","example":"Reskilling supports employees moving into new roles.","collocation":"reskilling program","dialogue":[{"role":"Employee","en":"My processing role is being phased out. Can I apply for one of the network support jobs?","zh":"我现在的业务处理岗位将逐步取消。我能申请网络支持岗位吗？"},{"role":"HRBP","en":"You can apply. The reskilling program covers the basics, and we’ll explain how to qualify for an interview.","zh":"可以申请。转岗技能再培训会讲基础内容，我们也会说明怎样才能获得面试机会。"}],"usage":"","new":false,"order":138,"aliases":[],"distinction":"Reskilling 培养另一类工作所需的技能，常用于转岗准备。Upskilling 提升当前或相关职责所需的技能。完成再培训后是否转岗，仍取决于合格标准和岗位机会。","collocationZh":"转岗技能再培训项目","collocationReview":"V18.2 模型编辑复核","ipaUK":"riːˈskɪl.ɪŋ","ipaUS":"riːˈskɪl.ɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Reskilling","exampleZh":"转岗技能再培训帮助员工为承担新岗位的工作做好准备。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we prepare employees to move into new roles?","zh":"如何帮助员工为转向新岗位做好准备？"},"extension":{"en":"The reskilling program includes supervised practice on the new team.","zh":"转岗技能再培训项目包括在新团队中进行的指导式实践。"}},{"id":"HR109","moduleId":"m4","module":"学习培训与人才发展","term":"Coaching","zh":"教练式辅导","definition":"围绕具体工作或发展目标，通过提问、观察与反馈，帮助个人反思并尝试改进的辅导。","example":"Coaching helps managers improve decision-making skills.","collocation":"provide coaching","dialogue":[{"role":"Manager","en":"My team waits for me to answer every question. Could we work on that in coaching?","zh":"团队什么问题都等我来回答。我们能在教练式辅导时谈谈这个吗？"},{"role":"Coach","en":"Sure. Pick one decision the team could make this week and let’s talk through how you’d hand it over.","zh":"可以。先选一个本周可以由团队自己做的决定，我们来聊聊你准备怎么放手。"}],"usage":"","new":false,"order":139,"aliases":[],"distinction":"Coaching 在这个语境中侧重帮助对方反思具体问题并形成自己的行动方案。Mentoring（导师指导）通常由更有经验的人分享经验、建议和职业视角。两种做法可在同一关系中结合。","collocationZh":"提供教练式辅导","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkəʊtʃɪŋ","ipaUS":"ˈkoʊtʃɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Coaching","exampleZh":"教练式辅导帮助管理者提升决策能力。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What one-on-one development support can leaders receive?","zh":"管理者可以获得哪些一对一的发展辅导？"},"extension":{"en":"In coaching, we agreed to test just one change before the next session.","zh":"在教练式辅导中，我们约定下次会面前只试行一项调整。"}},{"id":"HR110","moduleId":"m4","module":"学习培训与人才发展","term":"Mentoring","zh":"导师指导","definition":"由具有相关经验的导师与学员建立发展关系，持续提供职业建议、经验分享和反思支持。","example":"Our mentoring program matches new managers with experienced colleagues.","collocation":"mentoring relationship","dialogue":[{"role":"New Manager","en":"Could I ask my mentor how she handled her first reorganization?","zh":"我能问导师，她第一次遇到组织调整时是怎么应对的吗？"},{"role":"L&D Lead","en":"Absolutely. Bring one decision you’re facing so you can talk about what might work for your team.","zh":"当然。带一个你眼下需要做的决定去聊，看看哪些经验适合你的团队。"}],"usage":"","new":false,"order":140,"aliases":[],"distinction":"Mentoring 通常借助导师的经验和行业视角支持较长期的职业发展。Coaching 常围绕明确的表现或发展目标，通过提问、反馈等方式推动行动。","collocationZh":"导师指导关系","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈmentɔːrɪŋ","ipaUS":"ˈmentɚɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Mentoring","exampleZh":"我们的导师计划为新任经理匹配经验丰富的同事。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can junior colleagues learn from experienced employees?","zh":"初级员工能否向经验丰富的同事学习？"},"extension":{"en":"At our first mentoring session, I asked how to build relationships outside my own department.","zh":"第一次和导师见面时，我请教了如何与本部门以外的同事建立联系。"},"legacyExtraBookmark":{"en":"Let’s establish a mentoring relationship for each new manager.","zh":"我们为每位新任管理者建立导师辅导关系吧。"}},{"id":"HR111","moduleId":"m4","module":"学习培训与人才发展","term":"Job shadowing","zh":"跟岗学习","definition":"跟随有经验的同事观察真实工作流程、判断和操作，以了解岗位如何运作。","example":"Job shadowing helps new hires understand customer support.","collocation":"arrange job shadowing","dialogue":[{"role":"New Hire","en":"During job shadowing, should I take any of the support calls myself?","zh":"跟岗学习时，我需要自己接客服来电吗？"},{"role":"Team Lead","en":"Just listen during the first hour. We’ll do a practice call together afterward.","zh":"头一个小时先听。之后我们一起模拟接一通电话。"}],"usage":"","new":false,"order":141,"aliases":[],"distinction":"Job shadowing 主要通过观察他人的实际工作来学习。Job rotation（岗位轮换）安排员工在不同岗位或职能中实际承担工作，通常时间更长。","collocationZh":"安排跟岗学习","collocationReview":"V18.2 模型编辑复核","ipaUK":"dʒɒb ˈʃædəʊɪŋ","ipaUS":"dʒɑːb ˈʃædoʊɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Job shadowing","exampleZh":"跟岗学习有助于新员工了解客户支持工作。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can employees observe another role in practice?","zh":"员工怎样通过实际观察了解另一个岗位？"},"extension":{"en":"We scheduled job shadowing for a morning when the team processes escalations.","zh":"我们把跟岗学习安排在团队处理升级事项的那个上午。"}},{"id":"HR112","moduleId":"m4","module":"学习培训与人才发展","term":"Cross-training","zh":"交叉培训","definition":"让团队成员学习其他岗位或同事负责的任务，以便协作或在需要时补位。","example":"Cross-training allows team members to cover critical tasks.","collocation":"cross-training plan","dialogue":[{"role":"Team Lead","en":"Only Dan can prepare the month-end file. What’s our backup if he’s away?","zh":"现在只有丹会做月末汇总表。他不在时谁来接手？"},{"role":"Operations Manager","en":"Let’s cross-train Mei. She can prepare the next file while Dan checks her work.","zh":"我们给梅做交叉培训。下次让她做汇总表，丹来复核。"}],"usage":"","new":false,"order":142,"aliases":[],"distinction":"Cross-training 培养员工兼做其他任务的能力，员工通常保留原岗位。Job rotation 给员工安排一段时间实际从事另一岗位或职能的工作。","collocationZh":"交叉培训计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"krɒs ˈtreɪnɪŋ","ipaUS":"krɔːs ˈtreɪnɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Cross-training","exampleZh":"交叉培训让团队成员能在需要时相互补位，承担关键任务。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can we teach employees tasks outside their usual roles?","zh":"我们能否培训员工承担其常规岗位之外的任务？"},"extension":{"en":"Cross-training gave the team a second person who could handle supplier returns.","zh":"通过交叉培训，团队多了一位能处理供应商退货的同事。"}},{"id":"HR113","moduleId":"m4","module":"学习培训与人才发展","term":"Learning path","zh":"学习路径","definition":"为达到岗位或能力目标而安排的课程、练习和在岗任务的学习顺序。","example":"The learning path includes beginner and advanced modules.","collocation":"personalized learning path","dialogue":[{"role":"Employee","en":"I’ve used this software for years. Do I still need to take the introductory module?","zh":"这套软件我用了好几年，还得上入门模块吗？"},{"role":"Learning Administrator","en":"Take the placement quiz first. If you meet the cutoff, I can move you to the next step in the learning path.","zh":"先做一下分级测验。如果达到要求，我可以把你调到学习路径的下一阶段。"}],"usage":"","new":false,"order":143,"aliases":[],"distinction":"Learning path 为学习者安排能力进阶的先后顺序。Course catalog（课程目录）用于查找可选课程，通常不会为每个目标指定完整的学习次序。","collocationZh":"个性化学习路径","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈlɜːnɪŋ pæθ","ipaUS":"ˈlɝːnɪŋ pæθ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Learning path","exampleZh":"该学习路径包括初级和高级课程模块。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will employees know which courses to take next?","zh":"员工如何知道下一步应该学习哪些课程？"},"extension":{"en":"The learning path ends with a project reviewed by a subject-matter expert.","zh":"学习路径的最后一项是项目实作，由领域专家评审。"}},{"id":"HR114","moduleId":"m4","module":"学习培训与人才发展","term":"Leadership development","zh":"领导力发展","definition":"有计划地培养引导团队、制定方向、作出决策和带动协作等领导能力。","example":"Leadership development is a priority in our program for new managers.","collocation":"leadership development program","dialogue":[{"role":"Project Lead","en":"Can I apply for leadership development? I lead projects but don’t manage anyone.","zh":"我能申请参加领导力发展项目吗？我带项目，但没有直接下属。"},{"role":"L&D Partner","en":"Yes. This cohort is open to project leads. We’ll ask you to bring a real example of influencing across teams.","zh":"可以，这一期也面向项目负责人。我们会请你带一个跨团队推动工作的真实案例来。"}],"usage":"","new":false,"order":144,"aliases":[],"distinction":"Leadership development 关注带领团队、影响他人和推动变革等能力，也可面向无管理头衔的员工。Management training（管理培训）常侧重分工、授权和绩效沟通等管理工作，两者可以重叠。","collocationZh":"领导力发展项目","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈliːdəˌʃɪp dɪˈveləpmənt","ipaUS":"ˈliːdɚˌʃɪp dɪˈveləpmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Leadership development","exampleZh":"领导力发展是我们新任经理培养项目的重点。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we preparing future leaders?","zh":"我们在如何培养未来的领导者？"},"extension":{"en":"The leadership development program includes practice giving feedback after a missed deadline.","zh":"领导力发展项目包含一项练习，让学员模拟怎么就交付延期给出反馈。"}},{"id":"HR115","moduleId":"m4","module":"学习培训与人才发展","term":"Management trainee program","zh":"管理培训生项目（管培生计划）","definition":"通常面向职业早期人才，通过有计划的轮岗、培训和项目实践，为未来承担管理及相关业务职责作准备。","example":"The management trainee program includes rotations across functions.","collocation":"join a management trainee program","dialogue":[{"role":"Trainee","en":"Do I get to choose my last rotation?","zh":"最后一次轮岗可以自己选吗？"},{"role":"Program Manager","en":"You can list two preferences. We’ll match them against what you need to learn and which teams have openings.","zh":"你可以填两个意向。我们会结合你的学习需求和各团队可接收的人数来安排。"}],"usage":"“管培生”是国内常见 HR 表达。","new":false,"order":145,"distinction":"Management trainee program（管培生项目）通常跨阶段培养并安排岗位或项目实践。Onboarding（入职融入）帮助新员工了解组织并开始工作。结业后的岗位安排取决于具体项目规则和岗位机会。","aliases":[],"collocationZh":"参加管理培训生项目","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈmæn.ɪdʒ.mənt ˌtreɪˈniː ˈprəʊ.ɡræm","ipaUS":"ˈmæn.ədʒ.mənt ˌtreɪˈniː ˈproʊ.ɡræm","ipaSource":"https://dictionary.cambridge.org/dictionary/english/management | https://dictionary.cambridge.org/dictionary/english/trainee | https://dictionary.cambridge.org/dictionary/english/program","speakTerm":"Management trainee program","exampleZh":"管理培训生项目包括跨职能轮岗。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What development program do we offer new management trainees?","zh":"我们为新入职的管理培训生提供什么发展项目？"},"extension":{"en":"Each participant in the management trainee program presents a project at the end of the year.","zh":"管理培训生项目的每位学员都会在年末汇报一个项目。"}},{"id":"HR116","moduleId":"m4","module":"学习培训与人才发展","term":"Individual development plan (IDP)","zh":"个人发展计划","definition":"由员工制定或与经理共同制定的个人成长计划，列明发展目标、行动、支持资源和进度安排。","example":"At our company, employees can update their individual development plans each quarter.","collocation":"review an IDP","dialogue":[{"role":"Employee","en":"I’ve put “learn SQL” in my IDP. Could I use the weekly report to practice?","zh":"我在个人发展计划里写了「学 SQL」。能用周报练习吗？"},{"role":"Manager","en":"Yes. Start by recreating one chart and ask the analyst to check your query.","zh":"可以，先试着复现其中一张图，再请分析师帮你检查查询语句。"}],"usage":"","new":false,"order":146,"aliases":[],"distinction":"IDP 记录员工想发展什么能力、如何实践及何时回顾。Performance plan（绩效计划）侧重该绩效周期要交付的工作及衡量标准。","collocationZh":"回顾个人发展计划（IDP）","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɪndɪˈvɪdʒuːəl dɪˈveləpmənt plæn","ipaUS":"ˌɪndəˈvɪdʒəwəl dɪˈveləpmənt plæn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Individual development plan","exampleZh":"在我们公司，员工可以每季度更新个人发展计划。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we record an employee's development goals?","zh":"我们如何记录员工的个人发展目标？"},"extension":{"en":"The IDP names the colleague who will provide feedback on each practice assignment.","zh":"个人发展计划注明了由哪位同事为每项实践任务提供反馈。"}},{"id":"HR117","moduleId":"m4","module":"学习培训与人才发展","term":"70-20-10 model","zh":"70-20-10 学习模型","definition":"用约 70% 的工作实践、20% 的他人互动、10% 的正式学习说明多渠道培养的参考模型。","example":"The 70-20-10 model reminds us to include on-the-job learning.","collocation":"apply the 70-20-10 model","dialogue":[{"role":"Manager","en":"Do I need to log seventy percent of everyone’s learning hours as on-the-job practice?","zh":"我需要把每个人学习时间的 70% 记成在岗实践吗？"},{"role":"L&D Partner","en":"Use the 70-20-10 model as a planning guide. Think about what people can practice on the job and who can give them feedback.","zh":"把 70-20-10 学习模型当作规划参考就行。想一想大家能在工作中练什么、谁能给他们反馈。"}],"usage":"","new":false,"order":147,"aliases":[],"distinction":"70-20-10 model 用比例表示实践、向他人学习与正式学习的组合，常作为培养设计参考。Training hours target（培训学时目标）是组织对学习时长的具体要求，需另行设定。","collocationZh":"运用 70-20-10 学习模型","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈseventi ˈtwenti ten ˈmɒdəl","ipaUS":"ˈsevəntiː ˈtwentiː ten ˈmɑːdəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"seventy twenty ten model","exampleZh":"70-20-10 学习模型提醒我们把在岗实践纳入培养方案。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How does the 70-20-10 model describe learning sources?","zh":"70-20-10 模型如何解释学习来源？"},"extension":{"en":"We used the 70-20-10 model to add peer feedback and a real assignment to the course.","zh":"我们借鉴 70-20-10 学习模型，为课程增加了同伴反馈和一项实际工作任务。"}},{"id":"HR118","moduleId":"m4","module":"学习培训与人才发展","term":"Learning transfer","zh":"学习迁移","definition":"学习者把学到的知识、技能或做法应用到实际工作，并在后续工作中持续使用的过程。","example":"Manager follow-ups can improve learning transfer.","collocation":"support learning transfer","dialogue":[{"role":"Trainer","en":"Everyone could use the checklist in class, but nobody has opened it since. What could we change?","zh":"大家上课时都会用检查清单，可课后没人打开过。我们能改些什么？"},{"role":"Manager","en":"I’ll add it to the handover template. That should help with learning transfer while the steps are still fresh.","zh":"我把它加到交接模板里，趁大家还记得这些步骤，帮他们把所学用到工作中。"}],"usage":"","new":false,"order":148,"aliases":[],"distinction":"Learning transfer 关注学员是否在真实工作中使用所学。Learning retention（学习保持）关注一段时间后是否仍记得或掌握内容。课堂测验可提供掌握情况的证据，工作样本有助于核验迁移。","collocationZh":"促进学习迁移","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈlɜːnɪŋ ˈtræns.fɜː","ipaUS":"ˈlɝːnɪŋ ˈtræns.fɝː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Learning transfer","exampleZh":"经理的后续跟进有助于员工把所学用到工作中。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we ensure new skills are used on the job?","zh":"怎样确保新技能能应用到实际工作中？"},"extension":{"en":"We checked learning transfer by reviewing real handovers a month after training.","zh":"培训结束一个月后，我们通过检查实际交接记录来了解学习迁移的情况。"}},{"id":"HR119","moduleId":"m4","module":"学习培训与人才发展","term":"Training effectiveness","zh":"培训有效性","definition":"培训在多大程度上实现预定目标，可依据知识技能、工作行为或业务结果的变化评估。","example":"We’ll evaluate the training’s effectiveness three months after the last workshop.","collocation":"measure training effectiveness","dialogue":[{"role":"Operations Manager","en":"The participants liked the course, but we haven’t seen fewer errors. What should we check?","zh":"学员很喜欢这门课，但错误没少。我们应该查什么？"},{"role":"L&D Partner","en":"Let’s look at a few work samples to see whether people are using the new steps. That will help us assess training effectiveness.","zh":"我们抽几份工作样本，看看大家有没有用上新步骤。这能帮助我们评估培训效果。"}],"usage":"","new":false,"order":149,"aliases":[],"distinction":"Training effectiveness 关注培训是否达成预定目标。Training satisfaction（培训满意度）反映学员对培训的主观体验。满意度可以帮助改进课程设计，技能或工作表现则需用相应证据评估。","collocationZh":"评估培训效果","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtreɪnɪŋ ɪˈfektɪvnəs","ipaUS":"ˈtreɪnɪŋ ɪˈfektɪvnəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Training effectiveness","exampleZh":"我们会在最后一场工作坊结束三个月后评估培训效果。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will we know whether the training worked?","zh":"我们如何判断培训是否有效？"},"extension":{"en":"We measured training effectiveness with the same task before and after the course.","zh":"我们在培训前后安排同一项任务，以评估培训效果。"}},{"id":"HR120","moduleId":"m4","module":"学习培训与人才发展","term":"Return on learning investment","zh":"学习投入回报","definition":"衡量学习项目的可归因收益相对于项目成本的水平。按货币口径计算投资回报率时，从可归因的货币收益中减去总成本，再除以总成本。","example":"To estimate the return on learning investment, we compared the cost of the course with the savings attributable to it.","collocation":"estimate the return on learning investment","dialogue":[{"role":"Finance Partner","en":"Order errors dropped after training, but we also fixed the form. How much of the savings can we count?","zh":"培训后订单错误减少了，但我们也修了表单。多少节省额可以归到培训上？"},{"role":"L&D Lead","en":"Let’s separate what we can verify. I’ll show a range for the return on learning investment and document the assumptions.","zh":"我们先把能核实的收益梳理清楚。我会给出学习投入回报的估算区间，并记录假设。"}],"usage":"","new":false,"order":150,"aliases":[],"distinction":"Return on learning investment 关注学习带来的收益相对于投入如何，量化为 ROI 时需明确成本和收益归因。Training effectiveness 关注学习目标是否达成，也可以用无需货币化的指标衡量。","collocationZh":"估算学习投入回报","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˈtɜːn ɒn ˈlɜːnɪŋ ɪnˈvestmənt","ipaUS":"rɪˈtɝːn ɑːn ˈlɝːnɪŋ ˌɪnˈvestmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Return on learning investment","exampleZh":"为估算学习投入回报，我们将课程成本与可归因于该课程的成本节省额作了比较。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we assess the value created by the learning program?","zh":"如何评估学习项目创造的价值？"},"extension":{"en":"The return on learning investment estimate includes paid time spent in class.","zh":"学习投入回报的估算将员工带薪上课时间计入成本。"}},{"id":"HR4-31","moduleId":"m4","module":"学习培训与人才发展","term":"Training needs assessment (TNA)","zh":"培训需求评估","definition":"结合业务、岗位和员工表现来识别能力缺口，并判断哪些问题适合通过培训解决、哪些人需要什么培训。","example":"The training needs assessment identified gaps in stakeholder communication.","collocation":"conduct a training needs assessment","dialogue":[{"role":"Operations Lead","en":"Day and night crews make different picking errors. Do they need the same course?","zh":"白班和夜班的拣货错误不一样。他们需要上同一门课吗？"},{"role":"L&D Partner","en":"Let’s use the training needs assessment to observe both shifts. The cause might differ even if the error rate is similar.","zh":"我们在培训需求评估时观察两个班次。就算错误率接近，原因也有可能不同。"}],"usage":"","new":true,"order":151,"aliases":[],"distinction":"Training needs assessment 与 training needs analysis 都可缩写为 TNA，实践中常互换。有些组织将 assessment 用于需求评估全流程，并把 analysis 用于其中的差距与原因分析。","collocationZh":"开展培训需求评估","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtreɪnɪŋ niːdz əˈses.mənt","ipaUS":"ˈtreɪnɪŋ niːdz əˈses.mənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Training needs assessment","exampleZh":"培训需求评估发现了利益相关方沟通方面的能力差距。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What did the training needs assessment reveal?","zh":"培训需求评估揭示了什么问题？"},"extension":{"en":"The training needs assessment helped us decide which roles needed hands-on practice.","zh":"培训需求评估帮助我们确定了哪些岗位需要实操练习。"}},{"id":"HR4-32","moduleId":"m4","module":"学习培训与人才发展","term":"Instructional design","zh":"教学设计","definition":"根据学习者的需求和预期学习成果，系统设计并评估课程内容、练习、反馈及测评方式的过程。","example":"In instructional design, we use the intended learning outcomes to choose activities and assessments.","collocation":"instructional design principles","dialogue":[{"role":"Trainer","en":"We have forty slides and twenty minutes. What should we keep?","zh":"四十页课件，只有二十分钟。该保留哪些内容？"},{"role":"Instructional Designer","en":"The instructional design brief says people need to spot three common errors. Keep one example of each and give them a case to try.","zh":"教学设计方案要求学员能识别三种常见错误。每种保留一个示例，再给大家一个案例练习。"}],"usage":"","new":true,"order":152,"aliases":[],"distinction":"Instructional design 关注学习如何发生、怎样组织练习与反馈、如何检验学会了什么。Content development（学习内容开发）侧重制作课件、案例和视频等材料，可以是教学设计的一部分。","collocationZh":"教学设计原则","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪnˈstrʌkʃənəl dɪˈzaɪn","ipaUS":"ˌɪnˈstrʌkʃənəl dɪˈzaɪn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Instructional design","exampleZh":"进行教学设计时，我们根据预期学习成果选择活动和测评方式。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can instructional design improve this workshop?","zh":"教学设计怎样改善这场工作坊？"},"extension":{"en":"The instructional design team tested the exercises with two new hires before launch.","zh":"课程上线前，教学设计团队请两名新员工试做了练习。"}},{"id":"HR4-33","moduleId":"m4","module":"学习培训与人才发展","term":"Learning outcome","zh":"学习成果","definition":"学习者完成学习后预期能展示，或经评估已经展示的知识、技能或行为。","example":"The learning outcome for this module is the ability to classify three types of service request.","collocation":"define learning outcomes","dialogue":[{"role":"Trainer","en":"Can we say the learning outcome is “understand the returns process”?","zh":"学习成果能写成「理解退货流程」吗？"},{"role":"L&D Partner","en":"Make it easier to assess. Could trainees process a sample return and explain which policy applies?","zh":"写得更便于评估一些。可以要求学员处理一笔模拟退货，并解释适用哪条规定吗？"}],"usage":"","new":true,"order":153,"aliases":[],"distinction":"Learning outcome 从学习者可展示的成果来表述，如「能独立完成对账」。Learning objective 是学习活动设定的目标。课程设计中两者可互换，评估时可注明是预期成果还是实际成果。","collocationZh":"明确预期学习成果","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈlɜːnɪŋ ˈaʊtkʌm","ipaUS":"ˈlɝːnɪŋ ˈaʊtkʌm","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Learning outcome","exampleZh":"本模块的预期学习成果是学员能够对三类服务请求进行分类。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should participants be able to do after the course?","zh":"课程结束后，学员应能够做到什么？"},"extension":{"en":"We used a simulated call to assess whether learners had achieved the learning outcome.","zh":"我们通过模拟通话来评估学员是否达到了预期学习成果。"}},{"id":"HR4-34","moduleId":"m4","module":"学习培训与人才发展","term":"Facilitator","zh":"引导师","definition":"在培训或工作坊中设计或主持互动环节，引导参与者讨论、反思并形成下一步行动的人。","example":"The facilitator asked each group to share one lesson from the exercise.","collocation":"workshop facilitator","dialogue":[{"role":"Workshop Participant","en":"We’re split on which idea to test. Will you pick one for us?","zh":"我们对试哪种方案意见不一。你能帮我们定一个吗？"},{"role":"Facilitator","en":"I’ll give everyone two minutes to explain their choice. Then we’ll use the criteria you agreed on to decide.","zh":"我会给每人两分钟说明自己的选择，然后按大家商定的标准来决定。"}],"usage":"","new":true,"order":154,"aliases":[],"distinction":"Facilitator 侧重引导讨论、协调参与和推进小组活动。Instructor（讲师）侧重讲授和指导练习。同一人可在活动中承担两种职责。","collocationZh":"工作坊引导师","collocationReview":"V18.2 模型编辑复核","ipaUK":"fəˈsɪlɪˌteɪtə","ipaUS":"fəˈsɪləˌteɪtɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Facilitator","exampleZh":"引导师请每组分享一项从练习中得到的收获。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who will act as the facilitator for the session?","zh":"谁将担任这场活动的引导师？"},"extension":{"en":"The facilitator invited remote participants to speak first.","zh":"引导师请远程参会者先发言。"}},{"id":"HR4-35","moduleId":"m4","module":"学习培训与人才发展","term":"Learning analytics","zh":"学习数据分析","definition":"收集和分析学习活动、进度、结果及相关情境的数据，用于了解学习过程和改进培训。","example":"Learning analytics shows which courses have low completion rates.","collocation":"learning analytics dashboard","dialogue":[{"role":"Learning Analyst","en":"There’s a big drop-off at lesson three. Should we cut it?","zh":"很多学员学到第三课就停了。我们要删掉这一课吗？"},{"role":"L&D Lead","en":"Let’s use learning analytics to see where they stop, then ask a few participants what happened.","zh":"先通过学习数据分析看看大家具体停在哪儿，再问几位学员当时遇到了什么。"}],"usage":"","new":true,"order":155,"aliases":[],"distinction":"Learning analytics 用学习相关数据找出过程或结果中的模式。Training evaluation（培训评估）依据事先设定的标准判断项目成效，可以结合数据、访谈和工作样本。","collocationZh":"学习数据分析仪表板","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈlɜːnɪŋ ˌænəˈlɪtɪks","ipaUS":"ˈlɝːnɪŋ ˌænəˈlɪtɪks","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Learning analytics","exampleZh":"学习数据分析显示哪些课程的完成率偏低。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What can learning analytics tell us about engagement?","zh":"学习数据分析可以告诉我们哪些参与度信息？"},"extension":{"en":"The learning analytics report combines quiz scores with course progress data.","zh":"学习数据分析报告结合了测验成绩和课程进度数据。"}},{"id":"HR4-36","moduleId":"m4","module":"学习培训与人才发展","term":"Capability building","zh":"能力建设","definition":"通过人才培养、流程改进和工具支持等措施，建立个人、团队或组织持续开展某类工作的能力。","example":"Capability building is central to our digital transformation plan.","collocation":"organizational capability building","dialogue":[{"role":"Operations Lead","en":"The team can use the new software, but no one knows who handles exceptions. Do we need more training?","zh":"团队已经会用新软件了，但没人知道例外情况归谁处理。还需要培训吗？"},{"role":"OD Partner","en":"Our capability building plan should cover the workflow, too. Let’s assign exception handlers and try the process on a real case.","zh":"能力建设计划也得包括工作流程。我们明确谁负责处理例外情况，再用真实案例跑一遍流程。"}],"usage":"","new":true,"order":156,"aliases":[],"distinction":"Capability building 可同时改善个人技能与团队执行所需的流程、工具和协作方式。Skills training（技能培训）着重练习特定技能，可以是能力建设的一项措施。","collocationZh":"组织能力建设","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌkeɪpəˈbɪlɪti ˈbɪldɪŋ","ipaUS":"ˌkeɪpəˈbɪlətiː ˈbɪldɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Capability building","exampleZh":"能力建设是我们数字化转型计划的核心。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which capabilities should we build first?","zh":"我们应优先建设哪些能力？"},"extension":{"en":"Capability building continued after the pilot through job aids and peer support.","zh":"试点结束后，团队通过工作辅助材料和同伴支持继续开展能力建设。"}},{"id":"HR4-37","moduleId":"m4","module":"学习培训与人才发展","term":"Learning agility","zh":"学习敏捷性","definition":"在陌生或变化的情境中从经验和反馈中学习，并能调整做法、把所学用于后续任务的能力。","example":"Our talent review considers learning agility when discussing leadership potential.","collocation":"assess learning agility","dialogue":[{"role":"Talent Partner","en":"She picked up the tool quickly. Is that enough evidence of learning agility?","zh":"她很快学会了这个工具。这足以说明她有学习敏捷性吗？"},{"role":"Manager","en":"I’d also look at how she used feedback from the pilot to change her approach on the second rollout.","zh":"我还会看她在第二次上线时，是怎么根据试点反馈调整做法的。"}],"usage":"","new":true,"order":157,"aliases":[],"distinction":"Learning agility 关注能否从反馈与经历中提炼经验，并把经验应用到陌生任务。Adaptability（适应能力）强调能否在变化后有效调整。两者相关，评估时应观察具体行为。","collocationZh":"评估学习敏捷性","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈlɜːnɪŋ æˈdʒɪlɪti","ipaUS":"ˈlɝːnɪŋ əˈdʒɪlətiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Learning agility","exampleZh":"我们在人才盘点时，会把学习敏捷性纳入对领导潜力的讨论。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we assess learning agility fairly?","zh":"我们该如何公平地评估学习敏捷性？"},"extension":{"en":"Interviewers asked candidates for a concrete example of learning agility in an unfamiliar role.","zh":"面试官请候选人举一个在陌生岗位上展现学习敏捷性的具体例子。"}},{"id":"HR4-38","moduleId":"m4","module":"学习培训与人才发展","term":"Peer learning","zh":"同伴学习","definition":"经验相近或面对相似任务的人通过交流经验、互相示范和反馈开展的学习。","example":"Peer learning sessions help teams share practical techniques.","collocation":"peer learning circle","dialogue":[{"role":"Team Lead","en":"Each site solved the same stock issue on its own. How can we share what worked?","zh":"各站点都独自处理了同样的库存问题。怎么让大家共享有效做法？"},{"role":"L&D Partner","en":"Let’s start a peer learning circle. Each site can bring one fix and one question for the others.","zh":"我们建个同伴学习小组吧。每个站点都带来一种解决办法和一个想请教其他站点的问题。"}],"usage":"","new":true,"order":158,"aliases":[],"distinction":"Peer learning 以同伴之间的互相学习为主，双方都可以提出问题和分享做法。Mentoring 通常由经验较丰富的一方持续提供发展支持。","collocationZh":"同伴学习小组","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈpiə ˈlɜːnɪŋ","ipaUS":"pɪr ˈlɝːnɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Peer learning","exampleZh":"同伴学习活动帮助团队分享实用技巧。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could we add peer learning to the development program?","zh":"我们可以在发展项目中增加同伴学习吗？"},"extension":{"en":"In our peer learning group, a different colleague brings a case each month.","zh":"我们的同伴学习小组每月轮流由一位同事带来一个案例。"}},{"id":"HR4-39","moduleId":"m4","module":"学习培训与人才发展","term":"Action learning","zh":"行动学习","definition":"小组围绕真实业务问题，通过提问、采取行动和反思来推进问题解决与成员学习的方法。","example":"Action learning teams work on live business challenges.","collocation":"action learning project","dialogue":[{"role":"Manager","en":"Could the group use our slow shift handovers as its action learning project?","zh":"小组能把交接班耗时太长作为行动学习项目吗？"},{"role":"Facilitator","en":"Yes, if they can test a small change on one shift and bring the results back for reflection.","zh":"可以，前提是他们能在一个班次上试行一项小改动，再带着结果回来复盘。"}],"usage":"","new":true,"order":159,"aliases":[],"distinction":"Action learning 将真实问题、提问、行动与反思结合起来，同时追求业务进展和个人学习。Case study（案例学习）通常分析提供给学员的案例，可以不在实际工作场景实施方案。","collocationZh":"行动学习项目","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈækʃən ˈlɜːnɪŋ","ipaUS":"ˈækʃən ˈlɝːnɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Action learning","exampleZh":"行动学习小组会围绕真实的业务难题开展工作。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which business problem should we use for action learning?","zh":"我们应该选择哪个业务问题开展行动学习？"},"extension":{"en":"The action learning group revisited its assumptions after the first trial.","zh":"第一次试验后，行动学习小组重新审视了原先的假设。"}},{"id":"HR4-40","moduleId":"m4","module":"学习培训与人才发展","term":"Kirkpatrick model","zh":"柯氏四级评估模型","definition":"从反应、学习、行为和结果四个层次评估培训，各层次分别关注学员体验、知识技能等学习成效、工作应用和预期业务结果的实现情况。","example":"We use the Kirkpatrick model to plan how we’ll evaluate the training.","collocation":"Kirkpatrick's four levels","dialogue":[{"role":"HRBP","en":"We already have the survey and the quiz. What else should we collect for the Kirkpatrick evaluation?","zh":"我们已经有满意度问卷和测验了。按柯氏模型评估，还要收集什么？"},{"role":"L&D Partner","en":"Let’s ask supervisors to observe the new behavior on the job and agree on a service metric to track.","zh":"请主管看看员工是否在工作中采用了新做法，再选一个服务指标持续跟踪。"}],"usage":"","new":true,"order":160,"aliases":[],"distinction":"Kirkpatrick model 将培训评估组织为反应、学习、行为和结果四个层次。ROI 评估还需比较可归因的货币收益与成本。观察到业务结果变化后，仍需判断培训发挥了多大作用。","collocationZh":"柯氏模型的四个评估层次","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkɜːkpəˌtrɪk ˈmɒdəl","ipaUS":"kɚkˈpætrɪk ˈmɑːdəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Kirkpatrick model","exampleZh":"我们用柯氏四级评估模型来规划如何评估这次培训。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we evaluate the leadership program beyond attendance?","zh":"除了出勤率，我们还应如何评估领导力培训项目？"},"extension":{"en":"At the behavior level of the Kirkpatrick model, we checked whether supervisors used the new feedback method at work.","zh":"在柯氏模型的行为层，我们检查了主管是否在工作中采用新的反馈方法。"}},{"id":"HR121","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Organization development (OD)","zh":"组织发展","definition":"通过有计划地改善组织的协作、流程、文化等系统因素，提升组织效能和应对变化的能力。","example":"Organization development focuses on long-term organizational effectiveness.","collocation":"OD initiative","dialogue":[{"role":"Business Lead","en":"We’ve changed the org chart twice, but the same handoff problems keep coming back. Where do we start?","zh":"组织架构图已经改了两遍，但交接老出同样的问题。我们该从哪里入手？"},{"role":"OD Partner","en":"Let’s start the OD work by observing a few handoffs and asking both teams where the current process breaks down.","zh":"组织发展项目先从观察几次交接做起，再问问两个团队现行流程在哪一步出了问题。"}],"usage":"行业常用缩写是 OD（Organization/Organizational Development）；OTD 在不同企业可能有不同内部含义，不宜当作统一标准缩写。","new":false,"order":161,"aliases":[],"distinction":"Organization development 也常写作 organizational development，两者均可缩写为 OD。组织发展关注整个组织系统如何改进，organization design（组织设计）更直接地处理结构、职责和运行机制。","collocationZh":"组织发展举措","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɔːɡənaɪˈzeɪʃən dɪˈveləpmənt","ipaUS":"ˌɔːrɡənəˈzeɪʃən dɪˈveləpmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Organization development","exampleZh":"组织发展着眼于提高组织的长期效能。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the goal of this organization development initiative?","zh":"这项组织发展举措的目标是什么？"},"extension":{"en":"The organization development initiative brought both sites together to agree on new ways of working.","zh":"这项组织发展举措让两个站点一起商定新的工作方式。"}},{"id":"HR122","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Talent development (TD)","zh":"人才发展","definition":"通过培训、在岗实践、辅导和职业发展机会，系统提升员工能力，满足当前和未来的人才需求。","example":"Our talent development strategy includes technical career paths as well as management training.","collocation":"TD strategy","dialogue":[{"role":"Engineering Director","en":"Our best engineers want to grow without moving into management. Can we give them a better option?","zh":"我们最出色的工程师想继续成长，但不想转管理。能给他们更好的选择吗？"},{"role":"Talent Partner","en":"Let’s add a specialist track to the talent development strategy and define the assignments people can take on at each level.","zh":"我们在人才发展战略中加入专业通道，并明确各层级可承担哪些任务。"}],"usage":"TD 为 Talent Development；与 OD（组织发展）有关联，但一个更聚焦人才能力成长，一个更聚焦组织系统变革。","new":false,"order":162,"aliases":[],"distinction":"Talent development（TD）关注员工能力和职业成长。Organization development（OD）主要改进组织系统，例如协作模式、文化和工作流程。两者可以在同一变革项目中相互配合。","collocationZh":"人才发展战略","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtæl.ənt dɪˈveləpmənt","ipaUS":"ˈtæl.ənt dɪˈveləpmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Talent development","exampleZh":"我们的人才发展战略既包括技术职业发展通道，也包括管理培训。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we investing in talent development?","zh":"我们正在如何投资人才发展？"},"extension":{"en":"The talent development plan reserves time for employees to practice new skills in their current roles.","zh":"人才发展计划为员工留出时间，让他们在现岗位上练习新技能。"}},{"id":"HR123","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Organization design","zh":"组织设计","definition":"根据业务目标安排组织结构、职责分工、决策权限与协作方式的过程及其形成的方案。","example":"The new organization design puts product and engineering in the same delivery teams.","collocation":"review the organization design","dialogue":[{"role":"Business Lead","en":"Should both regions keep their own support teams?","zh":"两个区域都要保留各自的支持团队吗？"},{"role":"OD Partner","en":"Let’s compare two organization designs. In one, the regions would share support but keep their own sales teams.","zh":"我们比较两套组织设计方案吧。其中一套是两区共享支持团队，各自保留销售团队。"}],"usage":"","new":false,"order":163,"aliases":[],"distinction":"Organization design 关注怎样划分团队、分配职责并协调工作。Reorganization（组织重组）指调整现有组织安排的行动，可以是实施新设计的一种方式。","collocationZh":"审视组织设计方案","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɔːɡənaɪˈzeɪʃən dɪˈzaɪn","ipaUS":"ˌɔːrɡənəˈzeɪʃən dɪˈzaɪn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Organization design","exampleZh":"新的组织设计将产品人员和工程人员编入同一批交付团队。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Are we redesigning the teams around business priorities?","zh":"我们是否要围绕业务优先事项重新设计团队？"},"extension":{"en":"The organization design gives each regional lead a clear area of responsibility.","zh":"这套组织设计为各区域负责人明确了各自的职责范围。"}},{"id":"HR124","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Operating model","zh":"组织运营模式／组织运作模式","definition":"描述组织如何配置人员、流程、技术和决策权限，以持续实现业务目标的运作安排。","example":"The operating model specifies which decisions are made at headquarters and which are made by local teams.","collocation":"target operating model","dialogue":[{"role":"Regional Lead","en":"Under the new model, can we approve refunds locally?","zh":"采用新模式后，我们可以在本地审批退款吗？"},{"role":"Operations Lead","en":"Yes, up to the limit in the operating model. Anything above it goes to the team at headquarters.","zh":"可以，但金额不能超过运营模式规定的上限。超出上限的申请要交给总部团队。"}],"usage":"在 OD 领域指运作机制，不是财务单独的运营模型。","new":false,"order":164,"distinction":"Operating model 说明组织日常怎样运行，包括流程、工具、人员和决策机制。Organizational chart（组织架构图）主要呈现团队、岗位及其汇报关系。","aliases":[],"collocationZh":"目标运营模式","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈɒpəˌreɪtɪŋ ˈmɒdəl","ipaUS":"ˈɑːpɚˌeɪtɪŋ ˈmɑːdəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Operating model","exampleZh":"组织运营模式明确哪些事项由总部统一决策，哪些由各地团队自行决策。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will the new operating model affect how teams work?","zh":"新的组织运营模式将如何影响团队的工作方式？"},"extension":{"en":"We’ll pilot the target operating model in two markets before expanding it.","zh":"我们会先在两个市场试行目标运营模式，再扩大实施范围。"}},{"id":"HR125","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Org chart","zh":"组织架构图","definition":"展示组织内团队、岗位及汇报关系的图表，可按需要附上员工姓名或空缺状态。","example":"Please update the org chart after the reorganization.","collocation":"update the org chart","dialogue":[{"role":"New Hire","en":"Is there a way to tell which team owns billing support?","zh":"有什么办法能查到哪支团队负责处理账单问题吗？"},{"role":"HR Coordinator","en":"Start with the org chart on the intranet. Expand Customer Operations to see the billing team and its lead.","zh":"先看内网的组织架构图，展开客户运营，就能看到处理账单问题的团队及其负责人。"}],"usage":"","new":false,"order":165,"aliases":[],"distinction":"Org chart 以图形展示组织结构和汇报关系。Employee directory（员工名录）侧重查找人员、职位及联系信息，可以与架构图联用。","collocationZh":"更新组织架构图","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɔːɡ tʃɑːt","ipaUS":"ɔːrɡ tʃɑːrt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Org chart","exampleZh":"组织重组后，请更新组织架构图。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Where can employees check the current org chart?","zh":"员工可以在哪里查看最新的组织架构图？"},"extension":{"en":"The org chart marks the roles that are currently vacant.","zh":"组织架构图标出了目前空缺的岗位。"}},{"id":"HR126","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Span of control","zh":"管理幅度","definition":"一位管理者直接管理的人数，具体测量也可按直接汇报的岗位数统计。","example":"A wide span of control may affect coaching capacity.","collocation":"review a manager’s span of control","dialogue":[{"role":"Operations Lead","en":"Once the teams merge, how many people will report directly to Nina?","zh":"团队合并后，会有多少人直接向妮娜汇报？"},{"role":"OD Partner","en":"Fourteen. Before we confirm that span of control, let’s look at how much support the new hires will need.","zh":"十四个。确定这个管理幅度前，我们先看看新员工需要多少支持。"}],"usage":"","new":false,"order":166,"aliases":[],"distinction":"Span of control 是一名经理直接管理的人数或岗位数。Organizational layers（组织层级）指从最高管理层到一线之间有多少层。判断管理幅度是否合适，还应考虑任务和团队特点。","collocationZh":"评估一位经理的管理幅度","collocationReview":"V18.2 模型编辑复核","ipaUK":"spæn ɒv kənˈtrəʊl","ipaUS":"spæn ʌv kənˈtroʊl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Span of control","exampleZh":"直接下属较多时，经理可能更难腾出时间辅导员工。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How many direct reports does this manager have?","zh":"这名经理有多少直接下属？"},"extension":{"en":"The OD team compared span of control across sites with similar types of work.","zh":"组织发展团队比较了工作类型相近的各站点的管理幅度。"}},{"id":"HR127","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Reporting line","zh":"汇报关系","definition":"岗位或员工向哪位管理者汇报并承担相应责任的关系，可包括主要和辅助汇报关系。","example":"The new reporting line becomes effective next month.","collocation":"change a reporting line","dialogue":[{"role":"Employee","en":"I’ll work on the regional project and keep my local role. Who signs off on my leave?","zh":"我会参加区域项目，同时保留本地岗位。那我的休假由谁批准？"},{"role":"HRBP","en":"Your primary reporting line stays with your local manager, who approves leave. The project lead sets priorities for the project.","zh":"你的主要汇报对象仍是本地经理，休假由本地经理审批。项目负责人负责定项目的工作重点。"}],"usage":"Line manager 是直接经理；solid-line reporting 通常是实线汇报，dotted-line reporting 通常是虚线汇报。","new":false,"order":167,"aliases":[],"distinction":"Reporting line 指汇报关系，line manager 指承担日常直属管理职责的人。Solid-line reporting（实线汇报）通常是主要关系，dotted-line reporting（虚线汇报）常用于辅助或矩阵协作，具体权限按组织规定。","collocationZh":"调整汇报关系","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˈpɔːtɪŋ laɪn","ipaUS":"riːˈpɔːrtɪŋ laɪn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Reporting line","exampleZh":"新的汇报关系将于下个月生效。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can you explain the reporting line in this organization?","zh":"你能解释一下这个组织中的汇报关系吗？"},"extension":{"en":"The transfer letter confirms the employee’s new reporting line.","zh":"调动通知确认了员工新的汇报关系。"}},{"id":"HR128","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Role clarity","zh":"职责清晰度","definition":"员工对自身工作范围、责任、决策权限及与其他岗位分工的理解程度。","example":"We improved role clarity during the merger by documenting who could approve exceptions.","collocation":"improve role clarity","dialogue":[{"role":"Support Lead","en":"Both teams think the other one owns customer refunds. Who should make the call?","zh":"两个团队都以为客户退款该由对方处理。到底谁来决定？"},{"role":"Operations Manager","en":"To improve role clarity, let’s write down who recommends a refund and who approves it, then walk both teams through the change.","zh":"为明确分工，我们把谁提出退款建议、谁审批写下来，再向两个团队说明这项调整。"}],"usage":"","new":false,"order":168,"aliases":[],"distinction":"Role clarity 关注员工实际是否清楚自己负责什么、可决定什么。Job description（岗位说明书）是用于传达这些信息的文件之一，跨团队边界还需在实际协作中确认。","collocationZh":"明确岗位职责","collocationReview":"V18.2 模型编辑复核","ipaUK":"rəʊl ˈklærɪti","ipaUS":"roʊl ˈklerətiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Role clarity","exampleZh":"团队合并期间，我们记录了谁有权批准例外事项，从而明确了岗位分工。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we make responsibilities clearer across teams?","zh":"我们如何让跨团队的职责分工更清晰？"},"extension":{"en":"We asked employees to name the decisions they owned as a check on role clarity.","zh":"为检验职责是否清楚，我们请员工说出哪些决定由自己负责。"}},{"id":"HR129","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Job architecture","zh":"岗位架构","definition":"用于归类和分级岗位的体系，通常涵盖职族、岗位层级及与之对应的标准。","example":"Job architecture helps standardize titles and career paths.","collocation":"build a job architecture","dialogue":[{"role":"HRBP","en":"Two roles have the same title, but one owns regional accounts and the other handles a single site. Should they be at the same level?","zh":"两个岗位头衔一样，一个负责区域客户，另一个只负责单一站点。它们应该同级吗？"},{"role":"Job Architecture Lead","en":"Let’s check the scope and decision rights against the job architecture before we compare levels.","zh":"先用岗位架构的标准核对职责范围和决策权限，再比较职级。"}],"usage":"","new":false,"order":169,"aliases":[],"distinction":"Job architecture 规定岗位怎样归入职族和职级。Org chart 展示当前团队和汇报关系。同一职族或职级的岗位可以分布在多个部门。","collocationZh":"建立岗位架构","collocationReview":"V18.2 模型编辑复核","ipaUK":"dʒɒb ˈɑːkɪˌtektʃə","ipaUS":"dʒɑːb ˈɑːrkəˌtektʃɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Job architecture","exampleZh":"岗位架构有助于统一职位名称和职业发展路径。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are job families and levels organized?","zh":"职族和岗位等级是如何设置的？"},"extension":{"en":"The job architecture shows how a specialist can advance without moving into management.","zh":"岗位架构说明了专业人员可以如何在不转管理的情况下晋级。"}},{"id":"HR130","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Job family","zh":"职族","definition":"按相近职能、工作性质或知识技能归类的一组岗位，可包含多个职级。","example":"In our job architecture, software engineering roles sit in the Technology job family.","collocation":"map roles to job families","dialogue":[{"role":"Hiring Manager","en":"This analyst reports to Sales but spends most of the time building data models. Which job family fits?","zh":"这位分析师向销售团队汇报，但大部分时间在建数据模型。该归到哪个职族？"},{"role":"HRBP","en":"Let’s review the core duties. If modeling is the main responsibility, the Analytics job family is likely a better fit.","zh":"先核对核心职责。如果建模是主要工作，数据分析职族可能更合适。"}],"usage":"job family 是职位序列组织，不是家庭成员。","new":false,"order":170,"distinction":"Job family 按工作性质归类，比如财务职族。Job level（岗位层级）按职责复杂度、影响范围等划分。同一个职族内可以有多个层级。","aliases":[],"collocationZh":"将岗位归入相应职族","collocationReview":"V18.2 模型编辑复核","ipaUK":"dʒɒb ˈfæmɪli","ipaUS":"dʒɑːb ˈfæməliː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Job family","exampleZh":"在我们的岗位架构中，软件工程岗位归入技术职族。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which job family does the new position belong to?","zh":"这个新岗位属于哪个职族？"},"extension":{"en":"The Finance job family covers both entry-level and senior specialist roles.","zh":"财务职族涵盖入门岗位和资深专业岗位。"}},{"id":"HR131","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Job leveling","zh":"岗位定级","definition":"按职责范围、复杂度、决策权限和业务影响等标准，为岗位确定层级的过程。","example":"We are reviewing job leveling across business units.","collocation":"job leveling framework","dialogue":[{"role":"Manager","en":"The person in this role has been here for eight years. Does that change the level?","zh":"现任员工已经做了八年。这会影响岗位层级吗？"},{"role":"HRBP","en":"In job leveling, we assess the role’s scope. Has the job taken on broader decisions or more complex work?","zh":"岗位定级要看职责范围。这个岗位的决策范围变大了吗，或者承担了更复杂的工作吗？"}],"usage":"","new":false,"order":171,"aliases":[],"distinction":"Job leveling 按通用标准确定岗位的层级。Job evaluation（岗位评价）更广泛地衡量岗位相对价值，可为定级或薪酬结构提供依据。具体流程因组织而异。","collocationZh":"岗位定级框架","collocationReview":"V18.2 模型编辑复核","ipaUK":"dʒɒb ˈlevəlɪŋ","ipaUS":"dʒɑːb ˈlevəlɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Job leveling","exampleZh":"我们正在复核各业务部门的岗位定级。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we evaluate jobs for consistent levels?","zh":"如何通过岗位评价确保岗位等级一致？"},"extension":{"en":"We reopened the job leveling discussion after two roles took on new responsibilities.","zh":"两个岗位承担了新的职责后，我们重新讨论了它们的定级。"}},{"id":"HR132","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Talent review","zh":"人才盘点","definition":"管理者按约定标准集中审视员工的绩效、能力、潜力与发展需要，并讨论后续培养或继任安排。","example":"The talent review will help us identify employees to consider for future leadership roles.","collocation":"conduct a talent review","dialogue":[{"role":"Business Lead","en":"Should we bring everyone’s ratings to the talent review?","zh":"人才盘点时要把每个人的绩效评级都带上吗？"},{"role":"Talent Partner","en":"Yes, and bring examples of how people handled unfamiliar work. That will help us discuss development options.","zh":"要，也请带上员工如何应对陌生任务的例子。这有助于讨论适合他们的发展机会。"}],"usage":"","new":false,"order":172,"aliases":[],"distinction":"Talent review 通常以一组员工为对象，综合讨论当前表现、未来潜力及培养方向。Performance review 通常以个人和已完成的绩效周期为对象，对照目标回顾表现。","collocationZh":"开展人才盘点","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtæl.ənt rɪˈvjuː","ipaUS":"ˈtæl.ənt riːˈvjuː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Talent review","exampleZh":"人才盘点将帮助我们找出有望承担领导职责的培养对象。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When will leaders review the talent pipeline?","zh":"领导者什么时候会审阅人才梯队？"},"extension":{"en":"After the talent review, each manager agreed to follow up on one development action.","zh":"人才盘点后，每位经理都同意跟进一项培养行动。"}},{"id":"HR133","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Nine-box grid","zh":"人才九宫格","definition":"将两个维度各分为三个等级，形成九个格子，常以绩效和潜力为轴辅助人才盘点。","example":"The nine-box grid gives managers a starting point for discussing development needs.","collocation":"use a nine-box grid","dialogue":[{"role":"Manager","en":"I have good performance evidence for this employee, but it’s too soon to judge potential. What should I put in the grid?","zh":"这位员工的绩效有充分证据，但现在判断潜力还太早。九宫格里该怎么填？"},{"role":"Talent Partner","en":"Record the performance evidence and flag potential as pending. We can revisit it after the project ends.","zh":"先记下绩效证据，把潜力标为待评估，项目结束后再看。"}],"usage":"九宫格常按“绩效表现 × 潜力”绘制；评估标准需明确定义。","new":false,"order":173,"aliases":[],"distinction":"Nine-box grid 是展示绩效和潜力判断的讨论工具。Talent review 是审视人才证据、讨论发展和作出后续安排的流程，可以选用九宫格辅助讨论。两轴标准应事先界定。","collocationZh":"使用人才九宫格","collocationReview":"V18.2 模型编辑复核","ipaUK":"naɪn bɒks ɡrɪd","ipaUS":"naɪn bɑːks ɡrɪd","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Nine-box grid","exampleZh":"人才九宫格为经理讨论员工的发展需求提供了一个起点。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we review performance and potential together?","zh":"我们如何结合绩效和潜力进行人才盘点？"},"extension":{"en":"We defined three levels of potential before using the nine-box grid.","zh":"使用人才九宫格前，我们先明确了潜力三个等级的含义。"}},{"id":"HR134","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Talent calibration","zh":"人才校准","definition":"让来自不同团队的评估者依据共同标准核对潜力、准备度等人才判断的一致性。","example":"Talent calibration helps departments apply the same criteria when assessing potential.","collocation":"hold a talent calibration meeting","dialogue":[{"role":"Manager","en":"Our teams are using “ready soon” for very different timelines. Can we resolve that before the names go into the plan?","zh":"两个团队说的「近期可接任」对应的时间差很多。能在把人选写进计划前统一一下吗？"},{"role":"Talent Partner","en":"Yes. At the talent calibration meeting, let’s agree on the timeframe and what evidence counts.","zh":"可以。我们在人才校准会上把时间范围和可采信的证据都定清楚。"}],"usage":"","new":false,"order":174,"aliases":[],"distinction":"Talent calibration 核对不同团队是否用相近标准判断潜力或继任准备度。Performance calibration（绩效校准）主要复核既往表现的评级是否一致。","collocationZh":"召开人才校准会议","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtæl.ənt ˌkælɪˈbreɪʃən","ipaUS":"ˈtæl.ənt ˌkæləˈbreɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Talent calibration","exampleZh":"人才校准有助于各部门用同一套标准评估员工潜力。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will we compare talent assessments across departments?","zh":"如何比较不同部门的人才评价结果？"},"extension":{"en":"The talent calibration meeting surfaced different interpretations of the readiness criteria.","zh":"人才校准会上，大家发现各团队对准备度标准的理解不同。"}},{"id":"HR135","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Succession planning","zh":"继任规划","definition":"识别关键岗位及潜在继任人选、评估准备程度，并安排培养与交接以维持业务连续性的过程。","example":"Succession planning helps us prepare for leadership transitions.","collocation":"succession planning process","dialogue":[{"role":"Business Lead","en":"Our site manager will retire next year. Does Morgan have enough time to prepare?","zh":"我们站点经理明年退休。摩根有足够的时间准备接手吗？"},{"role":"Talent Partner","en":"Let’s review that in succession planning. Morgan could lead the next staffing review while the current manager is still here to coach.","zh":"我们在做继任规划时评估一下。趁现任经理还能指导，摩根可以先负责下一轮人员配置评审。"}],"usage":"","new":false,"order":175,"aliases":[],"distinction":"Succession planning 持续评估和培养关键岗位的潜在继任者。Replacement planning（替补规划）通常侧重空缺出现时由谁暂时或迅速接手，可作为继任规划的一部分。","collocationZh":"继任规划流程","collocationReview":"V18.2 模型编辑复核","ipaUK":"səkˈseʃən ˈplæn.ɪŋ","ipaUS":"səkˈseʃən ˈplæn.ɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Succession planning","exampleZh":"继任规划有助于我们为领导岗位的交接做好准备。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we preparing successors for critical roles?","zh":"我们如何为关键岗位培养继任者？"},"extension":{"en":"The succession planning process includes a review of the development needs of each potential successor.","zh":"继任规划流程包括回顾每位潜在继任者的发展需求。"}},{"id":"HR136","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Critical role","zh":"关键岗位","definition":"一旦空缺或失去所需能力，可能显著影响业务连续性、关键交付或战略目标的岗位。","example":"We identified the critical roles for the next planning cycle.","collocation":"identify critical roles","dialogue":[{"role":"Operations Lead","en":"Only one specialist can restart the packaging line after a shutdown. Should we list that as a critical role?","zh":"产线停机后只有一位技术专员能恢复设备运行。要把这个岗位列为关键岗位吗？"},{"role":"OD Partner","en":"Let’s check how long it would take to restart without that specialist. The risk is tied to the role, regardless of grade.","zh":"先看看没这位技术专员的话，恢复生产需要多久。评估的是岗位风险，各职级都要纳入考虑。"}],"usage":"","new":false,"order":176,"aliases":[],"distinction":"Critical role 常按岗位空缺或能力缺失会带来的业务风险确定。Key position（核心岗位）也可指战略贡献较大的岗位，两词经常重叠，具体名单由组织按明确标准确定。","collocationZh":"识别关键岗位","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkrɪtɪkəl rəʊl","ipaUS":"ˈkrɪtɪkəl roʊl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Critical role","exampleZh":"我们明确了下一轮规划周期中的关键岗位。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which positions would put business continuity at risk if vacant?","zh":"哪些岗位一旦空缺会危及业务连续性？"},"extension":{"en":"A critical role can sit anywhere in the organization, including on the front line.","zh":"关键岗位可以出现在组织的任何层级，包括一线。"}},{"id":"HR137","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Key position","zh":"核心岗位","definition":"对战略执行、关键业务成果或特定能力有重要影响的岗位，具体认定标准因组织而异。","example":"We identified the key positions needed to support the regional expansion.","collocation":"identify key positions","dialogue":[{"role":"Regional Lead","en":"Do we include technical specialists when we list key positions for the expansion?","zh":"梳理扩张所需的核心岗位时，技术专家岗位也要考虑吗？"},{"role":"OD Partner","en":"Yes. Include the roles we need to launch the service, even if they don’t manage a team.","zh":"要。上线新服务所必需的岗位都应纳入，专业岗位也一样。"}],"usage":"","new":false,"order":177,"aliases":[],"distinction":"Key position 常从战略贡献、岗位职责或稀缺性判断。Critical role 往往从岗位失去人员或能力后造成的业务风险判断。实际用法常重叠，应先明确组织的划分口径。","collocationZh":"识别核心岗位","collocationReview":"V18.2 模型编辑复核","ipaUK":"kiː pəˈzɪʃən","ipaUS":"kiː pəˈzɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Key position","exampleZh":"我们识别了支持区域扩张所需的核心岗位。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Have we identified the key positions in the region?","zh":"我们确定了该地区的关键岗位吗？"},"extension":{"en":"We updated the list of key positions when the product strategy changed.","zh":"产品战略调整后，我们更新了核心岗位清单。"}},{"id":"HR138","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"High-potential employee (HiPo)","zh":"高潜人才","definition":"依据明确标准与多方证据，被评估为有潜力在未来承担更复杂或范围更广职责的员工。","example":"The team offered the high-potential employee a short assignment in another business unit.","collocation":"development opportunities for high-potential employees","dialogue":[{"role":"Manager","en":"She’s one of our strongest analysts. Should I nominate her as high-potential?","zh":"她是我们最出色的分析师之一。我应该提名她参加高潜人才评估吗？"},{"role":"Talent Partner","en":"Bring an example of how she handled a new or more complex assignment, and check what kind of work she wants to pursue.","zh":"请带一个她处理陌生或更复杂任务的实例，也了解一下她今后想做哪类工作。"}],"usage":"HiPo 是 High Potential 的习惯简称，不等同于仅当前绩效最高的人。","new":false,"order":178,"aliases":[],"distinction":"High-potential employee（HiPo）是对未来成长潜力的判断。High performer 是对已取得绩效的判断。具备发展潜力与已能立即胜任更高职责也是两项不同判断。","collocationZh":"高潜人才的发展机会","collocationReview":"V18.2 模型编辑复核","ipaUK":"haɪ pəˈtenʃəl ɪmˈplɔɪ.iː","ipaUS":"haɪ pəˈtenʃəl ɪmˈplɔɪ.iː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"High-potential employee (HiPo)","exampleZh":"团队为这位高潜人才提供了在另一个业务部门短期任职的机会。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we distinguish potential from current performance?","zh":"我们如何区分未来潜力和当前绩效？"},"extension":{"en":"High-potential employees in the program meet with a mentor once a month.","zh":"项目中的高潜人才每月与导师见面一次。"}},{"id":"HR139","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Leadership pipeline","zh":"领导人才梯队","definition":"为不同层级领导岗位持续培养的人才储备，以及支持候选人逐步承担更大职责的路径。","example":"Our leadership pipeline has few candidates ready for mid-level management roles.","collocation":"strengthen the leadership pipeline","dialogue":[{"role":"Operations Director","en":"We have plenty of supervisors, but very few have managed more than one site. How can we build that experience?","zh":"主管不少，但很少有人管过一个以上的站点。怎么帮他们积累这类经验？"},{"role":"Talent Partner","en":"Let’s add a two-site assignment to the leadership pipeline for people preparing for regional roles.","zh":"我们在领导人才梯队的培养安排中，为准备承担区域职责的人加一项双站点任务。"}],"usage":"","new":false,"order":179,"aliases":[],"distinction":"Leadership pipeline 强调领导人才在不同层级的培养和流动。Succession slate（继任候选名单）列出某个岗位的潜在人选，通常还标明接任准备度。","collocationZh":"加强领导人才梯队建设","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈliːdəˌʃɪp ˈpaɪplaɪn","ipaUS":"ˈliːdɚˌʃɪp ˈpaɪplaɪn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Leadership pipeline","exampleZh":"我们的领导人才梯队中，已准备好承担中层管理职责的人选不多。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Do we have enough future leaders in the pipeline?","zh":"我们有足够的未来领导者储备吗？"},"extension":{"en":"A temporary assignment can help employees gain the experience they need to progress through the leadership pipeline.","zh":"短期任职可帮助员工积累经验，为在领导人才梯队中承担更高职责做准备。"}},{"id":"HR140","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Bench strength","zh":"后备人才储备","definition":"组织对关键岗位可动用的后备人才深度，通常结合候选人数、接任准备度和岗位覆盖情况判断。","example":"We improved our bench strength by preparing two people to step into priority roles.","collocation":"build bench strength","dialogue":[{"role":"Business Lead","en":"If both plant supervisors leave this quarter, can we cover both roles?","zh":"如果两位工厂主管都在本季度离开，两个岗位都有人能接手吗？"},{"role":"Talent Partner","en":"Only one candidate is ready today. We need to build bench strength for the second role and agree on interim cover.","zh":"目前只有一位候选人可以接任。我们需要加强另一个岗位的后备人才储备，并商定临时补位安排。"}],"usage":"","new":false,"order":180,"aliases":[],"distinction":"Bench strength 强调现有后备人才有多少、准备程度如何、能覆盖哪些岗位。Leadership pipeline 更强调领导人才从培养到逐步承担更大职责的路径。","collocationZh":"加强后备人才储备","collocationReview":"V18.2 模型编辑复核","ipaUK":"bentʃ streŋθ","ipaUS":"bentʃ streŋkθ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Bench strength","exampleZh":"我们为优先保障的岗位培养了两名可以接任的人选，增强了后备人才储备。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How strong is the bench for leadership roles?","zh":"领导岗位的后备人才储备情况如何？"},"extension":{"en":"Our bench strength varies across sites, with ready successors at two locations and none at the third.","zh":"我们的后备人才储备并不均衡，有两个站点有可立即接任的人选，另一个站点还没有。"}},{"id":"HR141","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Talent mobility","zh":"人才流动","definition":"在企业人才管理中，指员工在岗位、职能、业务单元或地区之间的流动，可包括调岗、晋升、轮岗或派驻。","example":"Talent mobility helps us fill roles with internal skills.","collocation":"enable talent mobility","dialogue":[{"role":"Business Lead","en":"The Singapore launch needs someone who knows our payments platform, but I only need them for three months.","zh":"新加坡的上线项目需要懂我们支付平台的人，不过只需要三个月。"},{"role":"Talent Partner","en":"Let’s use the talent mobility program to look for someone who can take a short-term assignment.","zh":"我们通过人才流动项目，看看有没有人能接受一次短期派遣。"}],"usage":"","new":false,"order":181,"aliases":[],"distinction":"Talent mobility 强调让人才在不同岗位、业务单元或地区之间流动。Internal mobility 特别指出流动发生在同一机构内部。Global mobility 通常侧重跨境流动及所需的派遣、安置等支持。","collocationZh":"促进人才流动","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtæl.ənt məʊˈbɪlɪti","ipaUS":"ˈtæl.ənt moʊˈbɪlətiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Talent mobility","exampleZh":"人才流动让我们能用内部具备相关技能的员工填补岗位空缺。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we support career movement across the business?","zh":"我们该如何支持业务内部的人才流动？"},"extension":{"en":"A shared skills directory can make talent mobility easier across business units.","zh":"共享技能名录可以让人才更容易在各业务单元之间流动。"}},{"id":"HR142","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Internal mobility","zh":"内部流动","definition":"员工在同一组织内部的职业流动，例如调岗、晋升或临时调配。","example":"We support internal mobility by posting all eligible vacancies on our internal job board.","collocation":"support internal mobility","dialogue":[{"role":"Employee","en":"I’d like to try a role in Operations, but I’m not ready to leave my team permanently.","zh":"我想试试运营岗，但现在还不想正式离开原团队。"},{"role":"Talent Partner","en":"Our internal mobility program includes short placements. I can send you the current list.","zh":"公司的内部流动项目也有短期岗位安排。我可以把目前的机会清单发给你。"}],"usage":"","new":false,"order":182,"aliases":[],"distinction":"Internal mobility 涵盖机构内部的岗位、项目或职级变动。Internal recruitment 指面向内部员工发布岗位、接收申请和选拔的过程，是实现内部流动的一种渠道。Lateral move 特指相近职级的横向变动。","collocationZh":"支持内部流动","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪnˈtɜːnəl məʊˈbɪlɪti","ipaUS":"ˌɪnˈtɝːnəl moʊˈbɪlətiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Internal mobility","exampleZh":"我们在内部职位平台公开所有可开放给员工申请的空缺，以促进内部流动。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can employees apply for opportunities in other teams?","zh":"员工可以申请其他团队的岗位机会吗？"},"extension":{"en":"Internal mobility lets employees gain experience in a new function without leaving the company.","zh":"内部流动可以让员工留在公司，同时积累新职能领域的经验。"}},{"id":"HR143","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Job rotation","zh":"岗位轮换","definition":"员工阶段性参与不同岗位以积累经验。","example":"Job rotation gives future leaders a wider perspective.","collocation":"job rotation program","dialogue":[{"role":"Warehouse Supervisor","en":"Two people know how to handle returns, and both are out next week.","zh":"只有两个人会处理退货，而他们下周都不在。"},{"role":"Operations Manager","en":"Let’s start a job rotation next month so more people get hands-on experience at the returns desk.","zh":"我们从下个月开始轮岗，让更多人到退货柜台实操。"}],"usage":"","new":false,"order":183,"aliases":[],"distinction":"Job rotation 指在不同岗位间按计划轮换，常用于培养或交叉训练。Job transfer 泛指调往另一岗位或地点，可以是长期安排。Job shadowing 主要通过跟岗观察来学习。","collocationZh":"岗位轮换项目","collocationReview":"V18.2 模型编辑复核","ipaUK":"dʒɒb rəʊˈteɪʃən","ipaUS":"dʒɑːb roʊˈteɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Job rotation","exampleZh":"岗位轮换让未来的领导者获得更广阔的视野。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could job rotation help develop this future leader?","zh":"岗位轮换能否帮助培养这位未来领导者？"},"extension":{"en":"Each stage of the job rotation has a learning goal and a named supervisor.","zh":"岗位轮换的每个阶段都有学习目标和指定的指导主管。"}},{"id":"HR144","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Workforce segmentation","zh":"员工队伍细分","definition":"按岗位族、技能、关键程度或工作地点等与规划有关的维度划分员工群体，为用工和能力规划提供依据。","example":"Workforce segmentation helps prioritize development investment.","collocation":"segment the workforce","dialogue":[{"role":"Workforce Planner","en":"The retirement forecast combines all technicians in one group. We need to know which sites will lose electricians.","zh":"退休预测把所有技术人员合成了一组。我们得知道哪些地点会出现电工缺口。"},{"role":"People Analyst","en":"I’ll revise the workforce segmentation to show trade and site separately.","zh":"我会调整员工队伍分类，分别体现工种和工作地点。"}],"usage":"","new":false,"order":184,"aliases":[],"distinction":"Workforce segmentation 按岗位族、技能或工作地点等维度对员工队伍分类，常用于人力规划。Talent segmentation 常用于区分不同发展需求或继任准备情况，以安排人才培养。两者可能使用部分相同的数据。","collocationZh":"对员工队伍进行细分","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈwɜːk.fɔːs ˌseɡmənˈteɪʃən","ipaUS":"ˈwɝːk.fɔːrs ˌseɡmənˈteɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Workforce segmentation","exampleZh":"员工队伍细分有助于确定人才发展投入的优先次序。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will we identify different workforce groups?","zh":"我们会如何区分不同的员工群体？"},"extension":{"en":"Our workforce segmentation groups employees by job family and work location.","zh":"我们的员工队伍分类按岗位族和工作地点划分。"}},{"id":"HR145","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Change management","zh":"变革管理","definition":"为推动组织变化而开展的管理工作，通常通过沟通、参与、培训和后续支持，帮助员工采用新的工作方式。","example":"For this rollout, change management starts three months before the system goes live.","collocation":"change management plan","dialogue":[{"role":"Systems Lead","en":"The software is ready, but several teams are still using the old approval forms.","zh":"软件已经准备好了，但还有几个团队在用旧的审批表。"},{"role":"Change Lead","en":"Let’s add drop-in sessions to the change management plan so people can try the new forms before we retire the old ones.","zh":"我们在变革管理计划里加几场随到随问的辅导，让大家在旧表停用前先试用新表。"}],"usage":"","new":false,"order":185,"aliases":[],"distinction":"Change management 在组织语境中侧重帮助员工理解、接受并采用新的工作方式。Project management 侧重项目范围、进度、资源和交付。系统上线属于交付，支持员工学会使用新系统属于变革管理工作。","collocationZh":"变革管理计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"tʃeɪndʒ ˈmænɪdʒmənt","ipaUS":"tʃeɪndʒ ˈmænədʒmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Change management","exampleZh":"这次系统推行的变革管理工作在正式上线前三个月启动。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will we support people through the reorganization?","zh":"我们如何帮助员工应对组织重组？"},"extension":{"en":"Our change management plan gives supervisors time to practise the new process with their teams.","zh":"变革管理计划为主管留出了与团队一起练习新流程的时间。"}},{"id":"HR146","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Change readiness","zh":"变革准备度","definition":"组织或员工对拟议变革的理解、支持和实际准备程度，可涉及技能、资源和管理支持。","example":"We will assess change readiness before restructuring.","collocation":"assess change readiness","dialogue":[{"role":"Project Manager","en":"The night shift hasn’t had a demo yet. Can we still switch over on Monday?","zh":"夜班同事还没看过演示。我们还能在周一切换吗？"},{"role":"Change Lead","en":"Let’s check their change readiness after tonight’s demo before we decide.","zh":"等今晚演示结束，先确认他们准备得怎么样，再作决定。"}],"usage":"","new":false,"order":186,"aliases":[],"distinction":"Change readiness 关注受影响的团队是否理解变革、愿意参与，以及是否具备所需资源和能力。Change impact assessment 关注变化具体会影响哪些岗位、流程和人群。","collocationZh":"评估变革准备度","collocationReview":"V18.2 模型编辑复核","ipaUK":"tʃeɪndʒ ˈredinəs","ipaUS":"tʃeɪndʒ ˈrediːnəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Change readiness","exampleZh":"在组织重组前，我们将评估变革准备度。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Are teams ready for the upcoming changes?","zh":"各团队是否做好了应对即将到来的变革的准备？"},"extension":{"en":"Change readiness improved once managers had a chance to test the new scheduling tool.","zh":"管理者有机会试用新的排班工具后，团队对变革的准备更充分了。"}},{"id":"HR147","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Stakeholder mapping","zh":"利益相关方梳理","definition":"识别受项目或变革影响、或能影响其结果的人员和群体，并整理其影响力、受影响程度和相互关系。","example":"Stakeholder mapping helps us plan targeted communication.","collocation":"stakeholder mapping exercise","dialogue":[{"role":"Change Manager","en":"The vendor has a say in the timeline, but the site supervisors will have to explain the change to staff.","zh":"供应商能影响时间表，但要向员工解释这次调整的是各地点的主管。"},{"role":"Project Coordinator","en":"I’ll add both groups to the stakeholder map and note what we need from each.","zh":"我会把两组都加到利益相关方图里，并注明各自需要配合什么。"}],"usage":"","new":false,"order":187,"aliases":[],"distinction":"Stakeholder mapping 侧重列出利益相关方，并按受影响程度、影响力等维度绘制关系或分类。Stakeholder analysis 的范围可更广，还可评估各方立场与诉求，帮助制定参与策略。","collocationZh":"利益相关方梳理活动","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsteɪkhəʊldə ˈmæpɪŋ","ipaUS":"ˈsteɪkˌhoʊldɚ ˈmæpɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Stakeholder mapping","exampleZh":"利益相关方梳理有助于我们制定有针对性的沟通计划。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who needs to be involved in the change program?","zh":"哪些相关方需要参与变革项目？"},"extension":{"en":"Stakeholder mapping revealed that the help desk would handle most of the early queries.","zh":"利益相关方梳理发现，上线初期的大部分咨询会由服务台处理。"}},{"id":"HR148","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Organizational effectiveness","zh":"组织效能","definition":"组织实现目标时的整体运作效果。","example":"We track organizational effectiveness by reviewing service quality, delivery times and customer feedback.","collocation":"improve organizational effectiveness","dialogue":[{"role":"COO","en":"We’re closing cases faster, but more customers are calling back about the same problem.","zh":"我们结案更快了，但为同一问题再次来电的客户却更多了。"},{"role":"OD Partner","en":"Let’s include repeat contacts in the organizational effectiveness review so we can see whether cases are actually being resolved.","zh":"我们在组织效能评估里加上重复联系的数据，看看问题是否真的解决了。"}],"usage":"","new":false,"order":188,"aliases":[],"distinction":"Organizational effectiveness 关注组织能否实现目标。Organizational efficiency 关注产出与投入资源之间的关系。评估效果时，可结合质量、客户结果和执行情况等维度。","collocationZh":"改善组织效能","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɔːɡənaɪˈzeɪʃənəl ɪˈfektɪvnəs","ipaUS":"ˌɔːrɡənəˈzeɪʃənəl ɪˈfektɪvnəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Organizational effectiveness","exampleZh":"我们通过分析服务质量、交付时间和客户反馈来跟踪组织效能。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will we assess whether the organization is working well?","zh":"我们该如何评估组织运作是否高效？"},"extension":{"en":"Regional managers will review organizational effectiveness after the service teams merge.","zh":"服务团队合并后，区域管理者将评估组织效能。"}},{"id":"HR149","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Strategic workforce planning","zh":"战略人力规划","definition":"根据长期业务战略预测人员和技能需求，评估现有及潜在供给，识别差距并制定应对方案。","example":"Strategic workforce planning helps us decide which capabilities to build internally and which to hire for.","collocation":"strategic workforce planning process","dialogue":[{"role":"Business Lead","en":"If we automate the first review step, do we still need to hire ten more reviewers?","zh":"如果把第一道审核自动化，我们还需要再招十名审核员吗？"},{"role":"Workforce Planning Lead","en":"Let’s run both scenarios through our strategic workforce planning process before we request the headcount.","zh":"申请编制前，我们先按战略人力规划流程，把两种情景都测算一遍。"}],"usage":"","new":false,"order":189,"aliases":[],"distinction":"Strategic workforce planning 以战略和业务情景为起点，比较未来需求与人才供给，并选择招聘、培养或调配等方案。Headcount planning 通常侧重人数、编制和预算。","collocationZh":"战略人力规划流程","collocationReview":"V18.2 模型编辑复核","ipaUK":"strəˈtiːdʒɪk ˈwɜːk.fɔːs ˈplæn.ɪŋ","ipaUS":"strəˈtiːdʒɪk ˈwɝːk.fɔːrs ˈplæn.ɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Strategic workforce planning","exampleZh":"战略人力规划帮助我们判断哪些能力应在内部培养，哪些需要通过招聘引入。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we align long-term talent needs with business strategy?","zh":"如何将长期人才需求与业务战略对齐？"},"extension":{"en":"Strategic workforce planning showed that the region would need more bilingual service staff within two years.","zh":"战略人力规划显示，该地区将在两年内需要更多双语客服人员。"}},{"id":"HR150","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Talent strategy","zh":"人才战略","definition":"围绕吸引、培养、保留人才的整体方向。","example":"Our talent strategy focuses on critical capabilities.","collocation":"align the talent strategy with business priorities","dialogue":[{"role":"HR Director","en":"We keep recruiting for the same specialist roles, then losing people after their first year.","zh":"这些专业岗位我们一直在招人，可人做满第一年就流失了。"},{"role":"Business Lead","en":"Let’s revisit the talent strategy and see how we can give those specialists more room to grow.","zh":"我们再看看人才战略，想想怎么给这些专业人员更多发展空间。"}],"usage":"","new":false,"order":190,"aliases":[],"distinction":"Talent strategy 决定组织优先吸引、培养和保留哪些人才能力，以及采取什么途径。Talent plan 把这些选择转化为具体项目、责任人和时间表。","collocationZh":"使人才战略与业务重点相一致","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtæl.ənt ˈstrætədʒi","ipaUS":"ˈtæl.ənt ˈstrætədʒiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Talent strategy","exampleZh":"我们的人才战略聚焦于关键能力。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should our talent strategy prioritize over the next two years?","zh":"未来两年人才战略应该重点关注什么？"},"extension":{"en":"The talent strategy makes developing frontline supervisors an investment priority.","zh":"人才战略将培养一线主管列为优先投入事项。"}},{"id":"HR5-31","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Organizational restructuring","zh":"组织重组","definition":"调整组织架构、岗位或汇报关系。","example":"The organizational restructuring will combine two regional teams.","collocation":"organizational restructuring plan","dialogue":[{"role":"Regional Manager","en":"After the organizational restructuring, will Finance still review local purchase requests?","zh":"组织重组后，本地采购申请还是由财务审核吗？"},{"role":"Program Lead","en":"The approval process stays as it is for now. We’ll confirm any changes before the new structure takes effect.","zh":"审批流程暂时照旧。如有调整，我们会在新架构生效前确认。"}],"usage":"","new":true,"order":191,"aliases":["Restructuring"],"distinction":"Organizational restructuring 指调整现有组织架构、团队或汇报关系。Organizational redesign 侧重设计新的组织架构或运作方式。Redundancy 在英式用语中常涉及岗位不再需要，组织重组是否涉及裁员须看具体方案及适用规定。","collocationZh":"组织重组计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɔːɡənaɪˈzeɪʃənəl rɪˈstrʌktʃərɪŋ","ipaUS":"ˌɔːrɡənəˈzeɪʃənəl riːˈstrʌktʃɚɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Organizational restructuring","exampleZh":"这次组织重组将把两个区域团队合并。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will the restructuring affect the reporting lines?","zh":"本次重组将如何影响汇报关系？"},"extension":{"en":"The organizational restructuring moves customer support into a single reporting line.","zh":"此次组织重组将客户支持纳入统一的汇报体系。"}},{"id":"HR5-32","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Role mapping","zh":"岗位映射","definition":"将当前岗位对应到目标组织结构中的角色。","example":"Our rollout plan puts role mapping ahead of the change to the reporting structure.","collocation":"role mapping exercise","dialogue":[{"role":"Department Head","en":"Two of our existing coordinator roles seem to map to the same role in the new structure.","zh":"我们有两个现有的协调岗，似乎对应新架构中的同一个岗位。"},{"role":"HR Specialist","en":"Flag both in the role mapping exercise. We’ll review the duties with you before confirming the match.","zh":"在岗位映射时把这两个都标出来。确认对应关系前，我们会和你一起核对职责。"}],"usage":"","new":true,"order":192,"aliases":[],"distinction":"Role mapping 把现有岗位与新架构中的目标岗位对应起来。Job matching 常指对照任职条件或职责衡量匹配程度，在不同机构也可指薪酬调查中的岗位匹配。岗位映射后，如需确定具体任职人员，仍须按适用流程办理。","collocationZh":"岗位映射工作","collocationReview":"V18.2 模型编辑复核","ipaUK":"rəʊl ˈmæpɪŋ","ipaUS":"roʊl ˈmæpɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Role mapping","exampleZh":"按实施计划，我们先完成岗位映射，再调整汇报架构。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Have we mapped every current role to the future structure?","zh":"我们是否已将所有现有岗位映射到未来的组织架构？"},"extension":{"en":"The role mapping shows which duties will move from the regional team to the shared service centre.","zh":"岗位映射显示，哪些职责将从区域团队转入共享服务中心。"}},{"id":"HR5-33","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Talent segmentation","zh":"人才分层分类","definition":"按岗位要求、技能、发展需求或继任准备情况等划分人才群体，以安排相应的培养或保留措施。","example":"Talent segmentation helps tailor development investment.","collocation":"talent segmentation criteria","dialogue":[{"role":"Talent Director","en":"Right now everyone on the succession list gets the same development course. Is that too broad?","zh":"现在继任名单上的人都参加同一门培养课程。这样是不是太笼统？"},{"role":"People Partner","en":"Let’s use talent segmentation to group candidates by the experience they still need.","zh":"我们按候选人尚缺的经验做人才分组，再安排培养。"}],"usage":"","new":true,"order":193,"aliases":[],"distinction":"Talent segmentation 根据发展需求、关键技能或继任准备情况等划分人才群体，以匹配培养资源。Performance rating 评定某一时期的工作表现，可用于参考。Workforce segmentation 通常以岗位族、地点等维度服务人力规划。","collocationZh":"人才分层分类标准","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtæl.ənt ˌseɡmənˈteɪʃən","ipaUS":"ˈtæl.ənt ˌseɡmənˈteɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Talent segmentation","exampleZh":"人才分层分类有助于按不同人才群体的需求安排发展投入。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What criteria are we using for talent segmentation?","zh":"我们使用什么标准对人才进行分层分类？"},"extension":{"en":"Talent segmentation helped us design separate development tracks for new and experienced managers.","zh":"人才分层分类帮助我们为新任管理者和有经验的管理者分别设计了培养路径。"}},{"id":"HR5-34","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Successor readiness","zh":"继任者准备度","definition":"继任候选人在多大程度上已能承担目标岗位的职责，常结合经验、能力及预计需要的培养时间判断。","example":"Successor readiness is reviewed annually for critical positions.","collocation":"assess successor readiness","dialogue":[{"role":"Operations Director","en":"Jia knows the business well, but she hasn’t managed a budget of this size.","zh":"佳很熟悉业务，但还没管过这么大规模的预算。"},{"role":"Talent Partner","en":"Let’s reflect that in her successor readiness assessment and give her a chance to lead the next budget cycle.","zh":"我们把这一点写进她的继任准备度评估，并让她有机会牵头下一轮预算工作。"}],"usage":"","new":true,"order":194,"aliases":[],"distinction":"Successor readiness 评估特定候选人还有多久能承担某个目标岗位。Ready-now successor 是目前具备接任能力的候选人。Leadership potential 关注未来成长潜力，候选人即使潜力较高，也可能还需要历练。","collocationZh":"评估继任准备度","collocationReview":"V18.2 模型编辑复核","ipaUK":"səkˈsesə ˈredinəs","ipaUS":"səkˈsesɚ ˈrediːnəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Successor readiness","exampleZh":"公司每年评估关键岗位继任候选人的准备度。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Do we have a ready-now successor for this role?","zh":"这个岗位有随时可以接任的继任者吗？"},"extension":{"en":"Successor readiness is reassessed after each candidate completes a stretch assignment.","zh":"每位候选人完成一项有挑战性的任务后，公司会重新评估其继任准备度。"}},{"id":"HR5-35","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Leadership bench","zh":"领导人才储备","definition":"可在未来承担关键领导岗位的人才群体。","example":"We need to strengthen the leadership bench in Asia.","collocation":"build a leadership bench","dialogue":[{"role":"Regional Director","en":"Two site managers are retiring next year. Can we cover both roles internally?","zh":"明年有两位现场经理退休。两个岗位都能从内部补上吗？"},{"role":"Talent Partner","en":"Let’s review the leadership bench and see who could take a larger site with some support.","zh":"我们看看后备领导人才储备，有谁在获得一定支持后能接手规模更大的工作地点。"}],"usage":"","new":true,"order":195,"aliases":[],"distinction":"Leadership bench 指已有的后备领导人才群体，常关注储备深度和可用性。Leadership pipeline 侧重从早期识别到培养和任用的各个环节。Succession slate 通常针对具体岗位列出继任候选人。","collocationZh":"建立领导人才储备","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈliːdəˌʃɪp bentʃ","ipaUS":"ˈliːdɚˌʃɪp bentʃ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Leadership bench","exampleZh":"我们需要加强亚洲区域的领导人才储备。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How strong is our leadership bench for regional roles?","zh":"我们为区域领导岗位储备的后备人才是否充足？"},"extension":{"en":"Rotation across business units has helped us build a deeper leadership bench.","zh":"跨业务单元的轮岗帮助我们扩大了后备领导人才储备。"}},{"id":"HR5-36","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Critical talent","zh":"关键人才","definition":"对战略能力或重要业务连续性影响较大的员工。","example":"Critical talent retention is part of the annual talent plan.","collocation":"critical talent retention","dialogue":[{"role":"Engineering Director","en":"Marta is the only person who can sign off on this test. She’s also asked about moving to another team.","zh":"玛尔塔是唯一能签核这项检测的人，她最近也问过能否转到别的团队。"},{"role":"HR Business Partner","en":"Let’s discuss her options and make a coverage plan as part of our critical talent review.","zh":"我们和她谈谈有哪些选择，也在关键人才盘点时制订一份接替方案。"}],"usage":"","new":true,"order":196,"aliases":[],"distinction":"Critical talent 指具备业务所需关键技能、知识或经验的人员。Critical role 指对组织目标影响较大的岗位。High-potential talent 侧重未来承担更复杂职责的潜力，关键人才也可能主要因当前的稀缺技能而被识别。","collocationZh":"关键人才保留","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkrɪtɪkəl ˈtæl.ənt","ipaUS":"ˈkrɪtɪkəl ˈtæl.ənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Critical talent","exampleZh":"关键人才保留是年度人才计划的一部分。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which critical talent risks require immediate action?","zh":"哪些关键人才风险需要立即处理？"},"extension":{"en":"We document specialist processes to reduce disruption if critical talent moves on.","zh":"我们把专业流程记录下来，以减少关键人才离开后对业务的影响。"}},{"id":"HR5-37","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Change impact assessment","zh":"变革影响评估","definition":"识别组织变化对人员、岗位及流程的影响。","example":"The change impact assessment identified new training needs.","collocation":"conduct a change impact assessment","dialogue":[{"role":"Payroll Lead","en":"The new cutoff date affects managers who approve overtime as well as payroll staff.","zh":"新的截止日期会影响审批加班的经理，也会影响负责薪资的同事。"},{"role":"Change Analyst","en":"I’ll update the change impact assessment to show what each group will need to do differently.","zh":"我会更新变革影响评估，写清楚两组人员各自需要怎么调整工作。"}],"usage":"","new":true,"order":197,"aliases":[],"distinction":"Change impact assessment 梳理变革会改变哪些流程、岗位或工作安排，以及影响的程度。Change readiness assessment 则评估受影响团队是否具备应对变化所需的理解、技能和资源。","collocationZh":"开展变革影响评估","collocationReview":"V18.2 模型编辑复核","ipaUK":"tʃeɪndʒ ˈɪmpækt əˈses.mənt","ipaUS":"tʃeɪndʒ ɪmˈpækt əˈses.mənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Change impact assessment","exampleZh":"变革影响评估发现了新的培训需求。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What did the change impact assessment show?","zh":"变革影响评估显示了什么？"},"extension":{"en":"Our change impact assessment showed that supervisors would spend less time approving routine requests.","zh":"我们的变革影响评估显示，主管用于审批常规申请的时间将减少。"}},{"id":"HR5-38","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Organizational health","zh":"组织健康度","definition":"组织能否有效协作、执行目标并持续适应变化的整体状态，常结合领导力、协作和工作方式等维度评估。","example":"Our organizational health review covers leadership and ways of working.","collocation":"organizational health survey","dialogue":[{"role":"COO","en":"Our sites hit their targets, but managers say they can’t get decisions made across teams.","zh":"各地点都达标了，可管理者说跨团队的决策常常推不动。"},{"role":"OD Partner","en":"Let’s look at cross-team decision-making in the next organizational health review.","zh":"我们在下一轮组织健康度评估中看看跨团队决策的问题。"}],"usage":"","new":true,"order":198,"aliases":[],"distinction":"Organizational health 关注组织持续协作、执行和适应变化的能力。Organizational effectiveness 更直接关注组织实现目标的程度。组织健康度调查可提供员工反馈，还可结合行为及运营数据解读。","collocationZh":"组织健康度调查","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɔː.ɡən.aɪˈzeɪ.ʃən.əl helθ","ipaUS":"ˌɔːr.ɡən.əˈzeɪ.ʃən.əl helθ","ipaSource":"https://dictionary.cambridge.org/dictionary/english/organizational | https://dictionary.cambridge.org/dictionary/english/health","speakTerm":"Organizational health","exampleZh":"我们的组织健康度评估涵盖领导力和工作方式。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What indicators should we use to assess organization health?","zh":"我们应使用哪些指标评估组织健康度？"},"extension":{"en":"The organizational health survey asks employees whether decisions are made at the right level.","zh":"组织健康度调查请员工评价各项决策是否由合适的层级作出。"},"searchAliases":["Organization health"]},{"id":"HR5-39","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Decision rights","zh":"决策权限","definition":"机构对各类决策的授权安排，明确谁能作决定以及适用的权限范围。","example":"Clear decision rights help teams avoid sending routine approvals to the wrong person.","collocation":"clarify decision rights","dialogue":[{"role":"Operations Manager","en":"I can move staff between shifts, but can I also approve overtime?","zh":"我可以调班，但也能批准加班吗？"},{"role":"HR Business Partner","en":"Let’s check the decision rights for staffing so we’re clear on what still needs Finance approval.","zh":"我们核对一下人员安排的决策权限，确认哪些事项仍需财务审批。"}],"usage":"","new":true,"order":199,"aliases":[],"distinction":"Decision rights 指谁有权作出哪一类决定。Delegation 指把某项权限授予他人。Responsibility 主要说明谁负责完成工作，有执行职责的人可能还需要他人批准。","collocationZh":"明确决策权限","collocationReview":"V18.2 模型编辑复核","ipaUK":"dɪˈsɪʒən raɪts","ipaUS":"dɪˈsɪʒən raɪts","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Decision rights","exampleZh":"明确决策权限有助于避免把常规审批送给不具备相应权限的人。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who has the decision rights for this process?","zh":"谁拥有这一流程的决策权限？"},"extension":{"en":"The policy gives site managers decision rights over purchases within a defined limit.","zh":"按政策，现场经理有权决定限额内的采购事项。"}},{"id":"HR5-40","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"RACI matrix","zh":"RACI 职责矩阵","definition":"按任务划分职责的矩阵。R 是执行者，A 是最终责任人，C 是需征询意见者，I 是需知会者。","example":"The RACI matrix clarifies ownership across the project.","collocation":"build a RACI matrix","dialogue":[{"role":"Project Manager","en":"Procurement is preparing the vendor shortlist. Who gives it the final sign-off?","zh":"采购部在准备供应商候选名单。最终该由谁签批？"},{"role":"Project Sponsor","en":"I do. Let’s update the RACI matrix so that’s clear before the shortlist goes out.","zh":"由我签批。我们更新一下 RACI 职责矩阵，在名单发出前把这一点写清楚。"}],"usage":"","new":true,"order":200,"aliases":[],"distinction":"RACI matrix 按任务区分执行者、最终责任人、需征询意见者和需知会者。Decision rights 侧重谁有权作出决定。RACI 表中，执行工作的人和承担最终责任的人可以是不同角色。","collocationZh":"建立 RACI 职责矩阵","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɑː eɪ siː aɪ ˈmeɪtrɪks","ipaUS":"ɑːr eɪ siː aɪ ˈmeɪtrɪks","ipaSource":"https://dictionary.cambridge.org/dictionary/english/a","speakTerm":"R A C I matrix","exampleZh":"RACI 职责矩阵明确项目中各方的职责。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can we clarify ownership using a RACI matrix?","zh":"能否通过 RACI 矩阵明确职责归属？"},"extension":{"en":"The RACI matrix tells us which teams to consult before we change the process.","zh":"RACI 职责矩阵告诉我们，修改流程前要征询哪些团队的意见。"}},{"id":"HR151","moduleId":"m6","module":"员工关系与劳动合规","term":"Employee relations","zh":"员工关系管理","definition":"人力资源领域对员工沟通、争议处理、劳动纪律及雇佣关系的管理。","example":"Employee relations supports fair and consistent workplace practices.","collocation":"employee relations case","dialogue":[{"role":"Line Manager","en":"Two employees have raised the same concern about how shifts are assigned.","zh":"有两位员工都对班次分配方式提出了意见。"},{"role":"HR Business Partner","en":"Let’s ask Employee Relations to advise on how to handle both complaints consistently.","zh":"我们请员工关系团队给些建议，看看怎么用一致的标准处理这两起投诉。"}],"usage":"这里不是普通私人“人际关系”。","new":false,"order":201,"distinction":"Employee relations（ER）在这里指处理雇佣关系中员工沟通、申诉、纪律等事项的人力资源职能。Labor relations 在一些地区尤其侧重工会和集体协商。两者的分工随组织和地区而异。","aliases":[],"collocationZh":"员工关系个案","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː rɪˈleɪʃənz","ipaUS":"ɪmˈplɔɪ.iː riːˈleɪʃənz","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee relations","exampleZh":"员工关系管理有助于在工作场所采用公平、一致的管理做法。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who should the manager contact about this employee concern?","zh":"经理应该向谁咨询员工关系问题？"},"extension":{"en":"Employee relations tracks recurring complaints to identify where managers need more support.","zh":"员工关系团队跟踪反复出现的投诉，找出管理者需要更多支持的环节。"}},{"id":"HR152","moduleId":"m6","module":"员工关系与劳动合规","term":"Employee handbook","zh":"员工手册","definition":"汇总工作场所政策与员工须知的文件。","example":"The employee handbook explains core workplace policies.","collocation":"update the employee handbook","dialogue":[{"role":"New Hire","en":"The handbook and the benefits portal give different deadlines for enrollment.","zh":"员工手册和福利平台写的参保登记截止日期不一样。"},{"role":"HR Adviser","en":"I’ll confirm the date with Benefits and update the employee handbook if it’s out of date.","zh":"我会和福利团队确认日期。如果员工手册上的日期过时了，我就更新。"}],"usage":"","new":false,"order":202,"aliases":[],"distinction":"Employee handbook 汇总员工常用政策和办事指南。Employment contract 规定雇佣双方约定的条款。手册中的部分条款是否具有合同效力，须结合具体措辞和适用法律判断。","collocationZh":"更新员工手册","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˈhændbʊk","ipaUS":"ɪmˈplɔɪ.iː ˈhændbʊk","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee handbook","exampleZh":"员工手册说明了工作场所的主要规章制度。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Where can employees find our workplace policies?","zh":"员工可以在哪里查阅职场政策？"},"extension":{"en":"The employee handbook now includes instructions for reporting an absence.","zh":"员工手册现已加入缺勤报备说明。"}},{"id":"HR153","moduleId":"m6","module":"员工关系与劳动合规","term":"Code of conduct","zh":"行为准则","definition":"说明组织对员工或适用人员的行为要求，常涉及利益冲突、工作场所行为和职业诚信。","example":"At our company, employees review the code of conduct once a year.","collocation":"follow the code of conduct","dialogue":[{"role":"Employee","en":"A supplier sent me a gift basket. Is it okay to share it with the team?","zh":"供应商送了我一个礼篮。我可以和团队一起分享吗？"},{"role":"Compliance Adviser","en":"Let’s check the gifts section of the code of conduct before you open it.","zh":"打开前，我们先查一下行为准则里关于礼品的规定。"}],"usage":"","new":false,"order":203,"aliases":[],"distinction":"Code of conduct 规定期望员工遵守的行为准则。Employee handbook 通常汇总多项制度，可以收录行为准则。Disciplinary procedure 规定如何处理涉嫌违规以及作出纪律决定。","collocationZh":"遵守行为准则","collocationReview":"V18.2 模型编辑复核","ipaUK":"kəʊd ɒv ˈkɒndʌkt","ipaUS":"koʊd ʌv ˈkɑːndəkt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Code of conduct","exampleZh":"在我们公司，员工每年复习一次行为准则。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What standards of behavior apply to everyone?","zh":"所有人需要遵守哪些行为规范？"},"extension":{"en":"The code of conduct requires employees to disclose potential conflicts of interest.","zh":"行为准则要求员工披露潜在的利益冲突。"}},{"id":"HR154","moduleId":"m6","module":"员工关系与劳动合规","term":"Grievance procedure","zh":"员工申诉程序","definition":"员工正式提出工作相关申诉，及组织受理、处理和复核该申诉的程序。具体步骤依机构政策及适用规则而定。","example":"The grievance procedure describes how to raise concerns.","collocation":"follow the grievance procedure","dialogue":[{"role":"Employee","en":"I’ve tried to resolve the issue informally, but it keeps coming up. Who should I write to?","zh":"我试过私下沟通解决，但这个问题还是反复出现。我该给谁写信？"},{"role":"Employee Relations Adviser","en":"I’ll send you the grievance procedure and point out where to submit a formal grievance.","zh":"我把员工申诉程序发给你，告诉你该通过哪个渠道正式提交申诉。"}],"usage":"","new":false,"order":204,"aliases":[],"distinction":"Grievance procedure 指员工正式提出申诉以及组织受理、处理和复核的程序。Grievance handling 指依程序处理个案的实际工作。Disciplinary procedure 涉及雇主对涉嫌违规等事项采取纪律措施的流程。","collocationZh":"遵循员工申诉程序","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈɡriːvəns prəˈsiːdʒə","ipaUS":"ˈɡriːvəns prəˈsiːdʒɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Grievance procedure","exampleZh":"员工申诉程序说明了员工如何正式反映问题。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can employees raise a formal grievance?","zh":"员工如何正式提出申诉？"},"extension":{"en":"The grievance procedure explains how to request a review of the initial decision.","zh":"员工申诉程序说明了如何申请复核初次处理决定。"}},{"id":"HR155","moduleId":"m6","module":"员工关系与劳动合规","term":"Disciplinary action","zh":"纪律处分","definition":"组织依适用程序对认定的违规等事项采取的纪律措施。可采取哪些措施取决于政策和适用规则。","example":"Under our policy, managers must give employees a chance to respond before taking disciplinary action.","collocation":"consider disciplinary action","dialogue":[{"role":"Line Manager","en":"The time records don’t match the supervisor’s account. Can we issue a warning today?","zh":"考勤记录和主管的说法不一致。我们今天能发警告吗？"},{"role":"Employee Relations Partner","en":"Let’s verify the records and hear the employee’s account before we consider disciplinary action.","zh":"我们先核实记录，并听取员工的陈述，再考虑是否采取纪律处分。"}],"usage":"","new":false,"order":205,"aliases":[],"distinction":"Disciplinary action 指按纪律程序决定采取的管理措施，可包括书面警告等。Investigation 是在决定前查明情况的过程。Informal coaching 通常着重提醒和改进，是否属于纪律程序应查阅适用政策。","collocationZh":"考虑采取纪律处分","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈdɪsɪˌplɪnəri ˈækʃən","ipaUS":"ˈdɪsəpləˌneriː ˈækʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Disciplinary action","exampleZh":"根据公司政策，管理者在采取纪律处分前须给员工陈述意见的机会。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What process should we follow before disciplinary action?","zh":"采取纪律处分前，我们应遵循什么程序？"},"extension":{"en":"The outcome letter records the disciplinary action and explains the available review process.","zh":"处理结果通知函记录了纪律处分，并说明可以采用的复核程序。"}},{"id":"HR156","moduleId":"m6","module":"员工关系与劳动合规","term":"Verbal warning","zh":"口头警告","definition":"以口头方式向员工发出的纪律警告。是否属于正式措施、是否须留存记录，依机构政策及适用程序而定。","example":"The manager issued a verbal warning after reviewing the facts.","collocation":"give a verbal warning","dialogue":[{"role":"Supervisor","en":"I reminded him yesterday to call in if he’s going to be late. Should I log that as a verbal warning?","zh":"我昨天提醒他，如果要迟到就打电话报备。这要登记为口头警告吗？"},{"role":"HR Adviser","en":"Let’s check how the policy distinguishes a coaching conversation from a verbal warning.","zh":"我们先查一下政策，看其中怎么区分辅导谈话和口头警告。"}],"usage":"","new":false,"order":206,"aliases":[],"distinction":"Verbal warning 强调以口头方式告知，当事机构也可能要求留存书面记录。Written warning 以书面形式发给员工。口头警告属于正式处分还是非正式提醒，应按机构政策及适用程序判断。","collocationZh":"向员工发出口头警告","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈvɜːbəl ˈwɔːnɪŋ","ipaUS":"ˈvɝːbəl ˈwɔːrnɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Verbal warning","exampleZh":"经理核查事实后，向该员工发出了口头警告。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What happened after the manager reviewed the facts?","zh":"经理核实事实后发生了什么？"},"extension":{"en":"The supervisor recorded the date of the verbal warning in the case file.","zh":"主管在个案档案中记录了发出口头警告的日期。"}},{"id":"HR157","moduleId":"m6","module":"员工关系与劳动合规","term":"Written warning","zh":"书面警告","definition":"以书面形式发给员工的纪律警告，通常载明问题、应达到的要求及后续安排。","example":"HR kept a copy of the written warning in the case file.","collocation":"issue a written warning","dialogue":[{"role":"Manager","en":"The draft says “improve attendance,” but it doesn’t say what the employee needs to do.","zh":"草稿写了“改善出勤情况”，可没说明员工具体要做什么。"},{"role":"Employee Relations Partner","en":"Let’s spell out the attendance expectations in the written warning before it goes out.","zh":"发出书面警告前，我们把具体的出勤要求写清楚。"}],"usage":"","new":false,"order":207,"aliases":[],"distinction":"Written warning 是以书面形式发给员工的纪律警告。Verbal warning 可以留有书面记录，其告知方式仍是口头。Final written warning 表示在适用纪律流程中处于更严重的阶段，具体后果依规则而定。","collocationZh":"发出书面警告","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈrɪtən ˈwɔːnɪŋ","ipaUS":"ˈrɪtən ˈwɔːrnɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Written warning","exampleZh":"人力资源部门在个案档案中留存了一份书面警告副本。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What information should a written warning include?","zh":"书面警告应包括哪些信息？"},"extension":{"en":"The written warning specifies when the manager will review the employee’s progress.","zh":"书面警告明确了管理者何时检查员工的改进情况。"}},{"id":"HR158","moduleId":"m6","module":"员工关系与劳动合规","term":"Investigation","zh":"调查","definition":"为核实投诉、涉嫌违规或其他事件而收集和分析证据的过程。","example":"The investigation should be impartial and documented.","collocation":"conduct an investigation","dialogue":[{"role":"Employee Relations Adviser","en":"The complaint mentions two incidents. Do we have records for both dates?","zh":"投诉里提到两起事件。我们有这两个日期的记录吗？"},{"role":"Investigator","en":"I’ll request the records for both dates and add them to the investigation file.","zh":"我会申请调取这两个日期的记录，并放进调查档案。"}],"usage":"","new":false,"order":208,"aliases":[],"distinction":"Investigation 侧重收集证据、核实事实并记录调查结果。Disciplinary hearing 可用于听取员工对相关指称的陈述。Disciplinary decision 则是在适用程序下决定是否采取措施。","collocationZh":"开展调查","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪnˌvestɪˈɡeɪʃən","ipaUS":"ˌɪnˌvestəˈɡeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Investigation","exampleZh":"调查应保持公正，并留下书面记录。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we make sure the investigation is fair?","zh":"我们怎样确保调查公平？"},"extension":{"en":"The investigator expanded the scope of the investigation after a second witness came forward.","zh":"第二位证人主动提供情况后，调查人员扩大了调查范围。"}},{"id":"HR159","moduleId":"m6","module":"员工关系与劳动合规","term":"Confidentiality","zh":"保密","definition":"保护敏感信息，并按适用规则将信息披露限制在必要范围内。","example":"Confidentiality is important during workplace investigations.","collocation":"maintain confidentiality","dialogue":[{"role":"Employee","en":"I’d like to report something, but I’m worried my team will see my statement.","zh":"我想反映一件事，但担心团队里的同事会看到我的陈述。"},{"role":"Employee Relations Adviser","en":"I’ll explain how we handle confidentiality and who may need to see the information.","zh":"我会说明我们的保密做法，以及哪些人可能因处理需要看到相关信息。"}],"usage":"","new":false,"order":209,"aliases":[],"distinction":"Confidentiality 关注已知信息可以披露给谁以及披露条件。Anonymity 关注身份是否可被识别。保密举报的处理人员可能知道举报者身份，信息披露依适用规则及办理需要而定。","collocationZh":"履行保密要求","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌkɒn.fɪ.den.ʃiˈæl.ə.ti","ipaUS":"ˌkɑːn.fə.den.ʃiˈæl.ə.t̬i","ipaSource":"https://dictionary.cambridge.org/dictionary/english/confidentiality","speakTerm":"Confidentiality","exampleZh":"在工作场所调查中，保密很重要。","ipaReview":"完整词头英美音标文本核对","ipaNote":"英美音标据 Cambridge 发音词头核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we handle sensitive information during an investigation?","zh":"调查期间应如何处理敏感信息？"},"extension":{"en":"The confidentiality notice explains who may access interview notes and why.","zh":"保密告知说明了哪些人可以查阅访谈记录，以及为何允许这些人查阅。"}},{"id":"HR160","moduleId":"m6","module":"员工关系与劳动合规","term":"Conflict resolution","zh":"冲突解决","definition":"运用沟通、协商、调解等方式处理工作中的分歧，寻求可执行的解决办法。","example":"Conflict resolution training is available for team leaders.","collocation":"support conflict resolution","dialogue":[{"role":"Team Lead","en":"Support and Sales keep arguing about who should call customers after a delay.","zh":"发生延误后该由谁给客户打电话，客服和销售一直争执不下。"},{"role":"HR Partner","en":"I can facilitate a conflict resolution meeting and help them agree on who owns the next call.","zh":"我可以主持一次冲突协调会，帮助双方明确下一次应由谁联系客户。"}],"usage":"","new":false,"order":210,"aliases":[],"distinction":"Conflict resolution 涵盖处理和解决冲突的多种方式，例如直接协商或调解。Mediation 特指由中立第三方协助沟通。Escalation 是把问题提交给更有权限或资源的人处理。","collocationZh":"协助解决冲突","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkɒnflɪkt ˌrezəˈluːʃən","ipaUS":"ˈkɑːnflɪkt ˌrezəˈluːʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Conflict resolution","exampleZh":"团队负责人可以参加冲突解决培训。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What support is available for resolving team conflicts?","zh":"有哪些支持措施可以帮助解决团队冲突？"},"extension":{"en":"The conflict resolution guide includes questions for opening a difficult conversation.","zh":"冲突解决指南列出了一些问题，可用来开启难以开口的谈话。"}},{"id":"HR161","moduleId":"m6","module":"员工关系与劳动合规","term":"Mediation","zh":"调解","definition":"由中立第三方协助争议各方沟通，帮助他们自行寻求双方可接受的解决方案。","example":"Mediation may help resolve this workplace disagreement.","collocation":"offer mediation","dialogue":[{"role":"Employee","en":"If I agree to mediation, does the mediator decide who was right?","zh":"如果我同意调解，调解员会裁定谁有理吗？"},{"role":"Employee Relations Adviser","en":"The mediator helps you discuss what happened and work out a solution you can both accept.","zh":"调解员会帮助你们沟通发生了什么，并找到双方都能接受的解决办法。"}],"usage":"","new":false,"order":211,"aliases":[],"distinction":"Mediation 由中立第三方协助各方沟通并寻求协议，方案由各方决定。Arbitration 通常由仲裁员作出决定，决定的效力取决于约定及适用规则。","collocationZh":"提供调解","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌmiːdɪˈeɪʃən","ipaUS":"ˌmiːdiːˈeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Mediation","exampleZh":"调解可能有助于解决这起职场争议。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could a neutral third party help resolve this dispute?","zh":"中立第三方能帮助解决这起争议吗？"},"extension":{"en":"At the end of mediation, both employees agreed on a new handover routine.","zh":"调解结束时，两位员工就新的交接流程达成了一致。"}},{"id":"HR162","moduleId":"m6","module":"员工关系与劳动合规","term":"Workplace harassment","zh":"职场骚扰","definition":"工作相关情境中不受欢迎、可能侵犯尊严或造成威胁、羞辱或冒犯性环境的行为。具体涵盖范围依机构政策和适用法律而定。","example":"Under our policy, employees can report workplace harassment through designated channels.","collocation":"prevent workplace harassment","dialogue":[{"role":"Employee","en":"A colleague keeps sending me unwanted personal messages after work. Can I report that?","zh":"有位同事下班后一直给我发私人消息，我并不愿意收到这些消息。可以反映这件事吗？"},{"role":"Employee Relations Adviser","en":"Yes. I can explain the workplace harassment reporting process and help you document what happened.","zh":"可以。我能说明职场骚扰的报告流程，帮助你记录发生的情况。"}],"usage":"","new":false,"order":212,"aliases":[],"distinction":"Workplace harassment 指工作相关语境中的骚扰。Sexual harassment 侧重与性有关的不受欢迎行为。Workplace bullying 通常强调持续或反复的欺凌。具体定义、认定标准和适用范围须结合机构政策与当地法律。","collocationZh":"预防职场骚扰","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈwɜːkpleɪs həˈræsmənt","ipaUS":"ˈwɝːkpleɪs hɚˈæsmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Workplace harassment","exampleZh":"根据公司政策，员工可以通过指定渠道报告职场骚扰。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can employees report workplace harassment safely?","zh":"员工如何安全地举报职场骚扰？"},"extension":{"en":"Our workplace harassment policy applies to work-related events held off-site.","zh":"公司的职场骚扰政策也适用于在办公场所以外举行的工作相关活动。"}},{"id":"HR163","moduleId":"m6","module":"员工关系与劳动合规","term":"Discrimination","zh":"歧视","definition":"在招聘、任职或其他工作事项中，因受保护等相关特征受到不利对待，或在部分司法辖区因表面中立的规则受到不利影响。认定标准依适用法律和政策而异。","example":"Our policy prohibits discrimination in hiring and employment.","collocation":"prevent discrimination","dialogue":[{"role":"Hiring Manager","en":"The role involves travel. Can I ask candidates whether they have young children?","zh":"这个岗位需要出差。我可以问候选人有没有年幼的孩子吗？"},{"role":"Recruiter","en":"To avoid potential discrimination, let’s ask every candidate the same question about the travel requirements.","zh":"为避免潜在歧视，我们就出差要求向每位候选人提出同一个问题。"}],"usage":"","new":false,"order":213,"aliases":[],"distinction":"Discrimination 强调基于受保护或不应成为决定依据的特征给予不利对待。某些司法辖区也涵盖表面中立规则造成的差别影响。Harassment 侧重不受欢迎的行为。两者可能重叠，具体标准依适用规则而定。","collocationZh":"预防歧视","collocationReview":"V18.2 模型编辑复核","ipaUK":"dɪˌskrɪmɪˈneɪʃən","ipaUS":"dɪˌskrɪməˈneɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Discrimination","exampleZh":"我们的政策禁止招聘和雇佣过程中的歧视。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What does our policy prohibit in recruitment and employment?","zh":"我们的政策禁止招聘和雇佣中的哪些行为？"},"extension":{"en":"The discrimination complaint prompted a review of how overtime shifts were allocated.","zh":"收到歧视投诉后，公司开始审查加班班次是如何分配的。"}},{"id":"HR164","moduleId":"m6","module":"员工关系与劳动合规","term":"Retaliation","zh":"打击报复","definition":"因某人举报、参与调查或行使受保护的权利等而给予不利对待。受保护活动及认定标准依适用法律和机构政策而异。","example":"Our policy prohibits retaliation against anyone who raises a concern in good faith.","collocation":"prohibit retaliation","dialogue":[{"role":"Employee","en":"After I gave a witness statement, I was taken off a project. Can I ask for that decision to be reviewed?","zh":"我作证后被调出了一个项目。可以要求复核这个决定吗？"},{"role":"Employee Relations Adviser","en":"Yes. We’ll document what changed and review whether it may be retaliation.","zh":"可以。我们会记录发生了哪些变动，并核查是否可能涉及打击报复。"}],"usage":"","new":false,"order":214,"aliases":[],"distinction":"Retaliation 强调因举报、参与调查或行使相关权利而受到不利对待。Disciplinary action 指按程序处理违规的措施。评估是否构成打击报复，需要核查不利决定的原因及其与相关活动的联系。","collocationZh":"禁止打击报复","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˌtælɪˈeɪʃən","ipaUS":"riːˌtæliːˈeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Retaliation","exampleZh":"公司政策禁止对善意反映问题的人进行打击报复。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Are employees protected when they raise a concern in good faith?","zh":"员工善意反映问题时是否受到保护？"},"extension":{"en":"The investigator reviewed schedule changes for signs of possible retaliation.","zh":"调查人员核查了排班变动，以判断是否存在打击报复的迹象。"}},{"id":"HR165","moduleId":"m6","module":"员工关系与劳动合规","term":"Whistleblower policy","zh":"举报人保护政策","definition":"说明涉嫌违规事项的举报渠道、处理方式及举报人保护措施的机构政策。保护范围依政策和适用法律而定。","example":"The whistleblower policy provides confidential reporting options.","collocation":"review the whistleblower policy","dialogue":[{"role":"Employee","en":"I found invoices for work the supplier may never have done. Where should I raise this?","zh":"我发现有些发票对应的工作，供应商可能根本没做。应该通过什么渠道反映？"},{"role":"Compliance Adviser","en":"Check the whistleblower policy for the reporting options. Keep the invoice references so the team can follow up.","zh":"请查阅举报人保护政策里的报告渠道，并保留发票编号，方便负责团队跟进。"}],"usage":"","new":false,"order":215,"aliases":[],"distinction":"Whistleblower policy 通常规定如何报告涉嫌违规事项、如何处理报告以及如何防范报复。Grievance procedure 通常用于处理员工个人的工作诉求。若同一事件涉及两类事项，应按适用政策确认报告渠道和保护范围。","collocationZh":"查阅举报人保护政策","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈwɪsəlˌbləʊə ˈpɒlɪsi","ipaUS":"ˈwɪsəlˌbloʊɚ ˈpɑːləsiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Whistleblower policy","exampleZh":"举报人保护政策规定了可保密处理身份信息的举报方式。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Where can staff report concerns confidentially?","zh":"员工可以通过哪里保密举报问题？"},"extension":{"en":"The whistleblower policy explains when reports are referred to the compliance team.","zh":"举报人保护政策说明了哪些举报会转交合规团队处理。"}},{"id":"HR166","moduleId":"m6","module":"员工关系与劳动合规","term":"Policy violation","zh":"违反内部政策","definition":"违反适用的机构内部规则或政策的行为。","example":"We need to verify the facts before confirming a policy violation.","collocation":"address a policy violation","dialogue":[{"role":"Manager","en":"Someone sent a customer file to a personal email address. Should I mark it as a policy violation?","zh":"有人把客户文件发到了个人邮箱。我该把这事记作违规吗？"},{"role":"HR Adviser","en":"Log it as a suspected policy violation for now and follow the data incident reporting process.","zh":"先记为疑似违反政策，再按数据事件报告流程处理。"}],"usage":"","new":false,"order":216,"aliases":[],"distinction":"Policy violation 指违反适用的内部政策。Breach of law 指违反法律规定，同一行为可能同时涉及两者。Alleged policy violation 指尚待核实的涉嫌违规事项。","collocationZh":"处理违反公司政策的行为","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈpɒlɪsi vaɪəˈleɪʃən","ipaUS":"ˈpɑːləsiː vaɪəˈleɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Policy violation","exampleZh":"认定行为违反内部政策之前，我们需要先核实事实。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Should we confirm a violation before verifying the facts?","zh":"在核实事实前，我们就应该认定存在违规吗？"},"extension":{"en":"The case log records the date and nature of each confirmed policy violation.","zh":"个案记录注明每起已确认违规的日期和性质。"}},{"id":"HR167","moduleId":"m6","module":"员工关系与劳动合规","term":"Disciplinary hearing","zh":"纪律听证会","definition":"在机构纪律程序中审议相关事项并听取员工陈述的正式会议，具体安排依政策及适用规则而定。","example":"A disciplinary hearing may be required under local rules.","collocation":"attend a disciplinary hearing","dialogue":[{"role":"Employee","en":"I’ve received a letter about a disciplinary hearing. Can I bring a colleague with me?","zh":"我收到了一封纪律听证会通知。可以带一位同事一起参加吗？"},{"role":"Employee Relations Adviser","en":"Let’s check the procedure and the rules that apply at your site, then I can confirm your options.","zh":"我们查一下纪律程序和你所在工作地点适用的规定，再确认你有哪些选择。"}],"usage":"","new":false,"order":217,"aliases":[],"distinction":"Disciplinary hearing 是纪律流程中听取员工陈述并审议相关材料的正式会议。Investigation meeting 主要用于收集事实。Disciplinary appeal 是对处分决定提出复核。需要经过哪些环节，依适用程序和规则而定。","collocationZh":"参加纪律听证会","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈdɪsɪˌplɪnəri ˈhiərɪŋ","ipaUS":"ˈdɪsəpləˌneriː ˈhiːrɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Disciplinary hearing","exampleZh":"根据当地规定，可能需要举行纪律听证会。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What formal meeting may be required before a disciplinary decision?","zh":"作出纪律处分决定前，可能需要举行什么正式会议？"},"extension":{"en":"The invitation to the disciplinary hearing lists the issues that will be discussed.","zh":"纪律听证会的通知列出了将要讨论的事项。"}},{"id":"HR168","moduleId":"m6","module":"员工关系与劳动合规","term":"Collective bargaining","zh":"集体谈判","definition":"雇主一方与工会或有代表资格的员工代表，就薪资、工时及其他劳动条件进行谈判的过程。","example":"The employer and union began collective bargaining over next year’s pay and working hours.","collocation":"engage in collective bargaining","dialogue":[{"role":"Site Manager","en":"Can we announce the new weekend rota before the next bargaining meeting?","zh":"我们可以在下次谈判会议之前公布新的周末排班表吗？"},{"role":"Labor Relations Manager","en":"Let’s check the collective bargaining arrangements for this site before we communicate the change.","zh":"通知这项变更前，我们先核对这个工作地点适用的集体谈判安排。"}],"usage":"","new":false,"order":218,"aliases":[],"distinction":"Collective bargaining 是雇主一方与工会或有代表资格的员工代表就雇佣条件进行谈判的过程。Collective bargaining agreement 指谈判达成的协议。代表资格、谈判范围和协议效力依适用规则而定。","collocationZh":"开展集体谈判","collocationReview":"V18.2 模型编辑复核","ipaUK":"kəˈlektɪv ˈbɑːɡɪnɪŋ","ipaUS":"kəˈlektɪv ˈbɑːrɡɪnɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Collective bargaining","exampleZh":"雇主和工会开始就明年的薪酬与工时开展集体谈判。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Do collective bargaining rules work the same everywhere?","zh":"各地集体谈判规则都一样吗？"},"extension":{"en":"The union consulted its members before the next round of collective bargaining.","zh":"工会在下一轮集体谈判前征求了会员的意见。"}},{"id":"HR169","moduleId":"m6","module":"员工关系与劳动合规","term":"Labor union","zh":"工会","definition":"代表会员或依法代表相关员工的组织，可参与集体谈判、员工申诉及劳动条件协商。具体代表范围依当地规则而定。","example":"HR met with the labor union representatives to discuss changes.","collocation":"labor union representative","dialogue":[{"role":"New Hire","en":"I’d like to talk to somebody from the labor union about how shift bids work.","zh":"我想找工会的人了解一下怎么申请选班。"},{"role":"Colleague","en":"The union noticeboard has contact details for the representative on our shift.","zh":"工会公告栏上有我们这个班次的工会代表的联系方式。"}],"usage":"","new":false,"order":219,"aliases":[],"distinction":"Labor union 是美式常用表达，英式常用 trade union。Employee representative 泛指代表员工发言的人，也可能经非工会渠道产生。工会代表的资格和权限依当地制度及具体安排而定。","collocationZh":"工会代表","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈleɪbə ˈjuːniən","ipaUS":"ˈleɪbɚ ˈjuːnjən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Labor union","exampleZh":"人力资源团队与工会代表会面讨论相关变更。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who represented employees in the meeting about the proposed changes?","zh":"在讨论拟议调整的会议上，谁代表员工发言？"},"extension":{"en":"The labor union surveyed members before drawing up its bargaining proposals.","zh":"工会在拟定谈判提案前征求了会员的意见。"}},{"id":"HR170","moduleId":"m6","module":"员工关系与劳动合规","term":"Employment contract","zh":"劳动合同","definition":"明确雇佣双方主要权利和义务的协议，可涉及岗位、薪酬、工时和通知期。用语及制度含义依适用法律而异。","example":"We ask local counsel to review the employment contract template before we use it in a new jurisdiction.","collocation":"sign an employment contract","dialogue":[{"role":"Candidate","en":"The offer mentions two days of remote work. Where will that arrangement be recorded?","zh":"录用通知提到可以远程办公两天。这个安排会写在哪里？"},{"role":"HR Adviser","en":"I’ll check whether it belongs in the employment contract or a separate remote work agreement.","zh":"我会确认是该写进劳动合同，还是另行签订远程办公协议。"}],"usage":"","new":false,"order":220,"aliases":[],"distinction":"Employment contract 约定雇佣双方的权利和义务。Offer letter 用于发出录用邀请和列明主要条件，是否构成有约束力的约定须看具体措辞及适用法律。Employee handbook 主要汇总机构政策，条款效力视具体情形而定。","collocationZh":"签署劳动合同","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.mənt ˈkɒntrækt","ipaUS":"ɪmˈplɔɪ.mənt ˈkɑːntrækt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employment contract","exampleZh":"在新的司法辖区使用劳动合同模板前，我们会请当地法律顾问审查。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What must we check before finalizing the employment contract?","zh":"签订劳动合同前必须核查什么？"},"extension":{"en":"The employment contract sets out the employee’s normal working hours and notice period.","zh":"劳动合同载明了员工的正常工作时间和离职通知期。"}},{"id":"HR171","moduleId":"m6","module":"员工关系与劳动合规","term":"Fixed-term contract","zh":"固定期限劳动合同","definition":"以约定日期、项目完成或其他明确终止条件界定期限的劳动合同，具体规则依适用法律。","example":"The fixed-term contract expires at the end of December.","collocation":"renew a fixed-term contract","dialogue":[{"role":"Project Lead","en":"The project has been extended. Can we keep Liam on a fixed-term contract?","zh":"项目延期了。我们可以继续与利亚姆签固定期限合同吗？"},{"role":"HR Adviser","en":"I’ll check the renewal rules and the terms of his current contract.","zh":"我会核对续签规则和他现有合同的条款。"}],"usage":"","new":false,"order":221,"aliases":[],"distinction":"Fixed-term contract 规定期限或终止条件。Permanent 或 open-ended contract 通常无预定终止日期，仍可依法解除。","collocationZh":"续签固定期限劳动合同","collocationReview":"V18.2 模型编辑复核","ipaUK":"fɪkst tɜːm ˈkɒntrækt","ipaUS":"fɪkst tɝːm ˈkɑːntrækt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Fixed-term contract","exampleZh":"该固定期限劳动合同将在十二月底到期。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When does the current fixed-term contract end?","zh":"当前的固定期限合同什么时候到期？"},"extension":{"en":"HR will confirm whether we can extend the fixed-term contract for the remaining six months.","zh":"人力资源部门会确认这份固定期限合同能否再延长六个月。"}},{"id":"HR172","moduleId":"m6","module":"员工关系与劳动合规","term":"Non-compete clause","zh":"竞业限制条款","definition":"约定在特定期间、地域或业务范围内限制竞争活动的条款，效力与适用条件因司法辖区而异。","example":"Legal counsel will review the non-compete clause for enforceability.","collocation":"review a non-compete clause","dialogue":[{"role":"Hiring Manager","en":"Does the non-compete clause apply to every role in the business?","zh":"这项竞业限制条款适用于公司所有岗位吗？"},{"role":"Legal Counsel","en":"We need to review the role, the wording and applicable law first.","zh":"我们得先看岗位、条款措辞以及适用法律。"}],"usage":"","new":false,"order":222,"aliases":[],"distinction":"Non-compete clause 限制约定范围内的竞争活动。Non-solicitation clause 通常限制招揽特定客户或员工。","collocationZh":"审查竞业限制条款","collocationReview":"V18.2 模型编辑复核","ipaUK":"nɒn kəmˈpiːt klɔːz","ipaUS":"nɑːn kəmˈpiːt klɔːz","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Non-compete clause","exampleZh":"法律顾问将审查竞业限制条款是否具有可执行性。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can we enforce this non-compete clause in the local jurisdiction?","zh":"在当地司法管辖区，这项竞业限制条款是否可执行？"},"extension":{"en":"Ask local counsel to review the scope and duration of the non-compete clause.","zh":"请当地法律顾问审查竞业限制条款的范围和期限。"}},{"id":"HR173","moduleId":"m6","module":"员工关系与劳动合规","term":"Severance pay","zh":"遣散费／离职经济补偿","definition":"在裁员或其他符合条件的雇佣终止情形中向离职员工支付的补偿；资格和金额取决于法律、合同或政策。","example":"Severance pay is determined by the applicable rules and agreement.","collocation":"calculate severance pay","dialogue":[{"role":"Finance Partner","en":"Should we include unused leave in the severance pay figure?","zh":"要把未休假期金额计入离职补偿吗？"},{"role":"HR Adviser","en":"Let’s list it separately and confirm how local rules treat each payment.","zh":"我们先分开列出，再确认当地规则如何处理每项款项。"}],"usage":"在中国法律场景应结合适用制度判断能否对应“经济补偿金”。","new":false,"order":223,"distinction":"Severance pay 是符合条件时支付的离职补偿。Final pay 是离职时应结算的工资等款项，两者可能同时支付。","aliases":[],"collocationZh":"计算遣散费","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsevərəns peɪ","ipaUS":"ˈseˌvɝːəns peɪ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Severance pay","exampleZh":"离职补偿金按照适用规定和双方协议确定。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we determine severance pay for this case?","zh":"这起事件的离职补偿金该如何确定？"},"extension":{"en":"Please show severance pay separately from outstanding wages in the breakdown.","zh":"请在费用明细里把离职补偿和待付工资分开列出。"}},{"id":"HR174","moduleId":"m6","module":"员工关系与劳动合规","term":"Termination for cause","zh":"因故解除","definition":"雇主依据适用法律、合同或政策认可的特定事由终止雇佣关系。","example":"Termination for cause requires careful legal and factual review.","collocation":"review the grounds for termination for cause","dialogue":[{"role":"Manager","en":"Is this enough to consider termination for cause?","zh":"这些情况足以考虑因故解除吗？"},{"role":"HR Adviser","en":"We need to establish the facts and check the applicable standard before deciding.","zh":"作决定前，我们需要查清事实并核对适用标准。"}],"usage":"","new":false,"order":224,"aliases":[],"distinction":"Termination for cause 强调解除有认可的特定事由。Summary dismissal 在英国用法中通常指不经通知期即时解雇，适用门槛另行判断。","collocationZh":"审查因故解除的依据","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌtɜːmɪˈneɪʃən fɔː kɔːz","ipaUS":"tɚməˈneɪʃən fɔːr kɑːz","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Termination for cause","exampleZh":"因故解雇需要谨慎进行法律及事实审查。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Resignation","note":"员工主动辞职。","relation":"易混淆"},{"term":"Dismissal","note":"雇主解除雇佣关系。","relation":"易混淆"},{"term":"Layoff","note":"通常因业务原因裁减人员，美式也可指暂时停工。","relation":"易混淆"},{"term":"Redundancy","note":"英式常指岗位不再需要而导致的裁员。","relation":"易混淆"},{"term":"Termination for cause","note":"基于特定原因解除雇佣关系，具体标准依合同和法律。","relation":"本词"},{"term":"Mutual separation agreement","note":"双方协商结束劳动关系的协议。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Why does termination for cause require a careful review?","zh":"为什么因过错解除雇佣关系需要谨慎审查？"},"extension":{"en":"Have local counsel review the documented grounds for termination for cause.","zh":"请当地法律顾问复核已记录的因故解除事由。"}},{"id":"HR175","moduleId":"m6","module":"员工关系与劳动合规","term":"Redundancy","zh":"岗位冗余／因岗位冗余裁撤","definition":"在英国等用法中，指因业务关闭、工作地点关闭或对某类工作的人力需求减少等原因导致员工岗位冗余并可能被裁撤。","example":"We must review local obligations before implementing redundancy measures.","collocation":"redundancy consultation","dialogue":[{"role":"Operations Lead","en":"Are we considering redundancy because the site is closing?","zh":"我们是因为这个工作地点要关闭，才考虑裁撤岗位吗？"},{"role":"HR Partner","en":"Yes. We’re also reviewing vacancies that affected staff could move into.","zh":"是的。我们也在查看有哪些空缺岗位可供受影响员工转岗。"}],"usage":"在英国等法域是特定劳动法概念；不宜简单等同个人绩效辞退。","new":false,"order":225,"distinction":"Redundancy 强调岗位或工作需求减少。Layoff 在美式语境常用来指裁员，在英国劳动用语中也可专指暂时无工可做。","aliases":[],"collocationZh":"冗员裁撤协商程序","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˈdʌndənsi","ipaUS":"rɪˈdʌndənsiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Redundancy","exampleZh":"实施裁员措施前，我们必须审查当地的法定义务。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Resignation","note":"员工主动辞职。","relation":"易混淆"},{"term":"Dismissal","note":"雇主解除雇佣关系。","relation":"易混淆"},{"term":"Layoff","note":"通常因业务原因裁减人员，美式也可指暂时停工。","relation":"易混淆"},{"term":"Redundancy","note":"英式常指岗位不再需要而导致的裁员。","relation":"本词"},{"term":"Termination for cause","note":"基于特定原因解除雇佣关系，具体标准依合同和法律。","relation":"易混淆"},{"term":"Mutual separation agreement","note":"双方协商结束劳动关系的协议。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"What obligations should we review before implementing a redundancy?","zh":"实施岗位裁撤之前，我们应审查哪些义务？"},"extension":{"en":"HR is checking whether redeployment could avoid some compulsory redundancies.","zh":"人力资源部门正在评估能否通过内部转岗避免部分强制裁员。"}},{"id":"HR176","moduleId":"m6","module":"员工关系与劳动合规","term":"Layoff","zh":"裁员／裁撤人员","definition":"因业务或运营原因减少用工，具体可指永久裁员或暂时停止提供工作，须结合地区和上下文理解。","example":"The company announced a layoff alongside a support program.","collocation":"layoff support","dialogue":[{"role":"Manager","en":"Is the planned layoff expected to be temporary at this site?","zh":"这个站点拟议的裁员安排预计是暂时的吗？"},{"role":"HR Partner","en":"The current proposal is permanent, but we still need to complete the required review.","zh":"目前方案是永久裁员，但我们仍需完成必要的审查。"}],"usage":"须结合国家和组织使用习惯理解。","new":false,"order":226,"distinction":"Layoff 在美国常指因经营原因裁员。英国语境中的 lay-off 可以指员工暂时没有工作可做，区别于导致岗位结束的 redundancy。","aliases":[],"collocationZh":"裁员支持措施","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈleɪɒf","ipaUS":"ˈleɪɔːf","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Layoff","exampleZh":"公司宣布裁员，同时推出员工支持计划。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Resignation","note":"员工主动辞职。","relation":"易混淆"},{"term":"Dismissal","note":"雇主解除雇佣关系。","relation":"易混淆"},{"term":"Layoff","note":"通常因业务原因裁减人员，美式也可指暂时停工。","relation":"本词"},{"term":"Redundancy","note":"英式常指岗位不再需要而导致的裁员。","relation":"易混淆"},{"term":"Termination for cause","note":"基于特定原因解除雇佣关系，具体标准依合同和法律。","relation":"易混淆"},{"term":"Mutual separation agreement","note":"双方协商结束劳动关系的协议。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"What support will be provided following the announced layoff?","zh":"公布裁员决定后，将提供哪些支持？"},"extension":{"en":"The HR team created a schedule for informing employees affected by the layoffs.","zh":"人力资源团队制定了通知受裁员影响员工的时间安排。"}},{"id":"HR177","moduleId":"m6","module":"员工关系与劳动合规","term":"Exit interview","zh":"离职访谈","definition":"在员工离职前后开展的访谈，用于了解离职原因和可改进之处。","example":"The exit interview revealed recurring concerns about career paths.","collocation":"conduct an exit interview","dialogue":[{"role":"HR Partner","en":"Would you like me to conduct the exit interview?","zh":"你希望由我做离职访谈吗？"},{"role":"Line Manager","en":"I’ll lead it so she has an opportunity to speak with someone outside her reporting line.","zh":"我来主持，这样她可以和不在其汇报链上的人交流。"}],"usage":"","new":false,"order":227,"aliases":[],"distinction":"Exit interview 通过访谈收集个人反馈。Exit survey 通过问卷收集反馈，便于汇总比较。","collocationZh":"开展离职访谈","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈeɡzɪt ˈɪn.tə.vjuː","ipaUS":"ˈeɡzɪt ˈɪn.tɚ.vjuː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Exit interview","exampleZh":"离职面谈反映出员工对职业发展路径的反复担忧。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What did we learn from the exit interview?","zh":"我们从离职访谈中了解到什么？"},"extension":{"en":"We review exit interview themes without attributing comments to individuals in the summary.","zh":"我们汇总离职访谈中的共性问题，摘要不标注具体反馈者。"}},{"id":"HR178","moduleId":"m6","module":"员工关系与劳动合规","term":"Employee assistance program (EAP)","zh":"员工援助计划","definition":"雇主提供或委托服务方提供的员工支持项目，可涵盖心理咨询和转介等服务，覆盖范围由方案确定。","example":"Our EAP offers short-term counseling and referrals to other services.","collocation":"access the EAP","dialogue":[{"role":"Employee","en":"Can I contact the EAP without asking my manager first?","zh":"我可以先不找经理，直接联系员工援助计划吗？"},{"role":"Benefits Adviser","en":"Our plan allows self-referral. The provider can explain its confidentiality rules.","zh":"我们的计划允许员工自行联系。服务机构可以说明其保密规则。"}],"usage":"","new":false,"order":228,"aliases":[],"distinction":"EAP 通常提供短期支持或转介。Health insurance 主要依据保险条款承担符合条件的医疗费用。","collocationZh":"使用员工援助计划（EAP）","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː əˈsɪstəns ˈprəʊɡræm","ipaUS":"ɪmˈplɔɪ.iː əˈsɪstəns ˈproʊɡræm","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee assistance program","exampleZh":"我们的员工援助计划提供短期咨询，并可转介至其他服务。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Where can employees get confidential support?","zh":"员工可以从哪里获得保密支持？"},"extension":{"en":"Where can I find the EAP provider’s contact details and privacy notice?","zh":"我在哪里能找到员工援助计划服务机构的联系方式和隐私说明？"}},{"id":"HR179","moduleId":"m6","module":"员工关系与劳动合规","term":"Occupational health and safety","zh":"职业健康与安全","definition":"在工作中识别和控制可能导致工伤或损害身心健康的风险的管理领域，常缩写为 OHS 或 OSH。","example":"Occupational health and safety is part of our compliance training.","collocation":"health and safety policy","dialogue":[{"role":"Plant Manager","en":"Should the contractors join our occupational health and safety briefing?","zh":"合同人员要参加我们的职业健康与安全说明会吗？"},{"role":"Safety Lead","en":"Yes, anyone using this work area needs to know the site hazards and reporting procedure.","zh":"要。进入这个作业区域的人员都需要了解现场风险和报告流程。"}],"usage":"","new":false,"order":229,"aliases":[],"distinction":"Occupational health and safety 涵盖职业健康风险和事故预防。Workplace safety 在较窄的语境中常侧重防止事故及身体伤害。","collocationZh":"职业健康与安全政策","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɒkjʊˈpeɪʃənəl helθ ænd ˈseɪfti","ipaUS":"ɑːkjəˈpeɪʃənəl helθ ənd ˈseɪftiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Occupational health and safety","exampleZh":"职业健康与安全属于我们的合规培训内容。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we train employees on workplace safety?","zh":"我们如何培训员工掌握职业安全知识？"},"extension":{"en":"The occupational health and safety review included noise exposure on the production line.","zh":"职业健康与安全审查纳入了生产线的噪声暴露风险。"}},{"id":"HR180","moduleId":"m6","module":"员工关系与劳动合规","term":"Reasonable accommodation","zh":"合理便利安排","definition":"依适用法律和具体情形，为符合条件的员工或求职者调整招聘流程、工作安排或环境，使其能够平等参与就业。","example":"HR discussed a reasonable accommodation request with the employee.","collocation":"request a reasonable accommodation","dialogue":[{"role":"Employee","en":"Could I request a reasonable accommodation for the assessments?","zh":"我可以申请在测评中获得合理便利吗？"},{"role":"HR Adviser","en":"Yes. Let’s discuss which adjustment would make the process accessible to you.","zh":"可以。我们谈谈怎样调整，才能让你无障碍地参加测评。"}],"usage":"不是普通的住宿 accommodation，法律义务因司法辖区而异。","new":false,"order":230,"distinction":"Reasonable accommodation 常见于美国等地的制度用语。英国残障就业语境常用 reasonable adjustments，适用标准须按当地法律判断。","aliases":[],"collocationZh":"申请合理便利安排","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈriːzənəbəl əˌkɒməˈdeɪʃən","ipaUS":"ˈriːzənəbəl əˌkɑːməˈdeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Reasonable accommodation","exampleZh":"人力资源部门与员工讨论了合理便利安排的申请。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we handle an employee's accommodation request?","zh":"我们应如何处理员工提出的合理便利安排申请？"},"extension":{"en":"We discussed several possible accommodations before choosing an accessible workstation.","zh":"我们讨论了几种可能的便利安排，再选定无障碍工位。"}},{"id":"HR6-31","moduleId":"m6","module":"员工关系与劳动合规","term":"Employee grievance","zh":"员工申诉","definition":"员工就工作条件、待遇或职场行为，通过组织程序正式提出的申诉。","example":"The employee grievance was reviewed under the internal procedure.","collocation":"raise an employee grievance","dialogue":[{"role":"Employee","en":"I raised this informally last month. How do I submit an employee grievance now?","zh":"我上个月非正式反映过这件事。现在怎么正式申诉？"},{"role":"HR Adviser","en":"Put the concern and the outcome you’re seeking in writing, then send it to the designated contact.","zh":"请书面说明你反映的问题和希望达成的结果，再发给指定联系人。"}],"usage":"","new":true,"order":231,"aliases":[],"distinction":"Employee grievance 是员工正式提出的关切。Grievance procedure 是接收、调查和处理申诉的程序。","collocationZh":"提出员工申诉","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˈɡriːvəns","ipaUS":"ɪmˈplɔɪ.iː ˈɡriːvəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee grievance","exampleZh":"这起员工申诉已按内部程序进行了审查。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can an employee raise a grievance confidentially?","zh":"员工如何以保密方式提出申诉？"},"extension":{"en":"Please acknowledge receipt of the employee grievance and confirm the next step.","zh":"请确认收到员工申诉，并说明下一步怎么处理。"}},{"id":"HR6-32","moduleId":"m6","module":"员工关系与劳动合规","term":"Due process","zh":"正当程序","definition":"依据适用法律、合同或内部程序，在可能影响当事人权益的决定中提供公平处理，包括适当告知并给予陈述机会。","example":"Due process is important in disciplinary matters.","collocation":"follow due process","dialogue":[{"role":"Manager","en":"Can we make the decision before we hear the employee’s account?","zh":"可以在听取员工陈述之前作决定吗？"},{"role":"HR Partner","en":"Let’s follow due process and give the employee a chance to respond first.","zh":"我们按正当程序办，先给员工陈述的机会。"}],"usage":"","new":true,"order":232,"aliases":[],"distinction":"Due process 强调决定过程的程序保障。Procedural fairness 是更广的程序公平概念，具体要求随制度和情形而变。","collocationZh":"遵守正当程序","collocationReview":"V18.2 模型编辑复核","ipaUK":"djuː ˈprəʊses","ipaUS":"duː ˈprɑːses","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Due process","exampleZh":"在纪律处分事项中，正当程序非常重要。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we ensure due process in this investigation?","zh":"我们如何确保这项调查遵循正当程序？"},"extension":{"en":"Keep a record of the steps taken to provide due process during the review.","zh":"请记录审查期间为履行正当程序采取的各项措施。"}},{"id":"HR6-33","moduleId":"m6","module":"员工关系与劳动合规","term":"Protected characteristic","zh":"受法律保护的个人特征","definition":"在特定司法辖区的反歧视制度下受保护的个人特征，列举范围与适用场景由当地法律规定。","example":"Policies should address discrimination based on protected characteristics.","collocation":"protected characteristics under local law","dialogue":[{"role":"Recruiter","en":"Should we use the same list of protected characteristics in every country?","zh":"每个国家都用同一份受保护特征清单吗？"},{"role":"HR Adviser","en":"Use the global policy as a starting point, then check the local list and requirements.","zh":"先以全球政策为起点，再核对当地清单和要求。"}],"usage":"哪些特征受到保护取决于适用法律，不宜套用其他司法辖区的清单。","new":true,"order":233,"aliases":[],"distinction":"Protected characteristic 是依法受到保护的特征。Protected activity 是举报或参与调查等受反报复规则保护的活动。","collocationZh":"当地法律保护的个人特征","collocationReview":"V18.2 模型编辑复核","ipaUK":"prəˈtektɪd ˌkærɪktəˈrɪstɪk","ipaUS":"prəˈtektɪd ˌkerəktɚˈɪstɪk","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Protected characteristic","exampleZh":"政策应明确禁止因受保护特征而产生的歧视。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which protected characteristics are covered by local law?","zh":"当地法律保护哪些个人特征不受歧视？"},"extension":{"en":"The training uses local examples to explain which protected characteristics are covered.","zh":"培训用本地案例说明哪些个人特征受法律保护。"}},{"id":"HR6-34","moduleId":"m6","module":"员工关系与劳动合规","term":"Conflict of interest","zh":"利益冲突","definition":"个人关系、财务利益或其他外部利益可能妨碍其客观履行工作职责的情况。","example":"Employees must disclose potential conflicts of interest.","collocation":"declare a conflict of interest","dialogue":[{"role":"Hiring Manager","en":"One candidate is my former business partner. Does that create a conflict of interest?","zh":"有位候选人是我以前的生意伙伴，这算利益冲突吗？"},{"role":"HR Adviser","en":"Please disclose the relationship so we can decide whether you should step aside.","zh":"请先申报这段关系，我们再判断你是否应当回避。"}],"usage":"","new":true,"order":234,"aliases":[],"distinction":"A conflict of interest 可以在尚未发生不当行为时存在。Misconduct 是违反行为标准的行为。","collocationZh":"申报利益冲突","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkɒnflɪkt ɒv ˈɪntrəst","ipaUS":"ˈkɑːnflɪkt ʌv ˈɪntrəst","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Conflict of interest","exampleZh":"员工必须申报潜在的利益冲突。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Does this supplier relationship create a conflict of interest?","zh":"与这家供应商的关系是否构成利益冲突？"},"extension":{"en":"She declared a conflict of interest and stepped away from the selection panel.","zh":"她申报了利益冲突，并退出评选小组。"}},{"id":"HR6-35","moduleId":"m6","module":"员工关系与劳动合规","term":"Workplace investigation","zh":"职场调查","definition":"对工作场所内的投诉、疑似违规或事件，以访谈和材料核查等方式查明事实的程序。","example":"The workplace investigation should be impartial and timely.","collocation":"conduct a workplace investigation","dialogue":[{"role":"HR Manager","en":"What should we do with the messages the employee gave us?","zh":"员工交给我们的消息记录要怎么处理？"},{"role":"Investigator","en":"Preserve the originals and log who has access during the workplace investigation.","zh":"保留原件，并记录职场调查期间哪些人有权查阅。"}],"usage":"","new":true,"order":235,"aliases":[],"distinction":"Workplace investigation 查明事实。A disciplinary hearing 在适用程序中提供陈述机会，并可为决定是否处分提供依据。","collocationZh":"开展职场调查","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈwɜːkpleɪs ɪnˌvestɪˈɡeɪʃən","ipaUS":"ˈwɝːkpleɪs ˌɪnˌvestəˈɡeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Workplace investigation","exampleZh":"职场调查应公正且及时。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who will conduct the workplace investigation?","zh":"谁将负责开展职场调查？"},"extension":{"en":"The workplace investigation included interviews with people from two shifts.","zh":"这次职场调查访谈了两个班次的人员。"}},{"id":"HR6-36","moduleId":"m6","module":"员工关系与劳动合规","term":"Collective consultation","zh":"集体协商咨询","definition":"就可能影响一批员工的组织变动，与符合要求的员工代表交换信息并听取意见的过程；适用范围与义务依法律或协议。","example":"Collective consultation may be required before certain redundancies.","collocation":"collective consultation process","dialogue":[{"role":"HR Director","en":"Should we brief the employee representatives before the site changes are finalized?","zh":"在站点调整方案定稿之前，我们要先和员工代表沟通吗？"},{"role":"Legal Counsel","en":"Let’s first check whether the collective consultation rules apply and what information we must share.","zh":"先确认集体协商咨询规则是否适用，以及哪些信息必须提供。"}],"usage":"","new":true,"order":236,"aliases":[],"distinction":"Collective consultation 常用于拟议群体变动的意见征询。Collective bargaining 通常是代表双方对薪酬、工时等劳动条件进行谈判。","collocationZh":"集体协商程序","collocationReview":"V18.2 模型编辑复核","ipaUK":"kəˈlektɪv kɒnsəlˈteɪʃən","ipaUS":"kəˈlektɪv ˌkɑːnsəlˈteɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Collective consultation","exampleZh":"实施某些裁员措施前，可能需要进行集体协商。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Does this restructuring require collective consultation?","zh":"这次组织重组是否需要进行集体协商咨询？"},"extension":{"en":"The HR team kept a record of alternatives raised during collective consultation.","zh":"人力资源团队记录了集体协商咨询中提出的替代方案。"}},{"id":"HR6-37","moduleId":"m6","module":"员工关系与劳动合规","term":"Notice of termination","zh":"终止雇佣通知","definition":"正式告知另一方雇佣关系将终止的通知，可载明终止日期等信息，内容和形式依适用要求。","example":"The notice of termination must meet applicable requirements.","collocation":"issue a notice of termination","dialogue":[{"role":"Manager","en":"Can I send the notice of termination today?","zh":"今天可以发出终止雇佣通知吗？"},{"role":"HR Adviser","en":"Let’s check the approved wording and how it needs to be delivered first.","zh":"我们先核对获批措辞和送达方式。"}],"usage":"","new":true,"order":237,"aliases":[],"distinction":"Notice of termination 是终止雇佣的通知。Notice period 是发出通知到雇佣关系结束之间的期间。","collocationZh":"发出解雇通知","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈnəʊtɪs ɒv ˌtɜːmɪˈneɪʃən","ipaUS":"ˈnoʊtəs ʌv tɚməˈneɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Notice of termination","exampleZh":"终止雇佣通知必须符合适用要求。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What information must the termination notice include?","zh":"解雇通知应包含哪些信息？"},"extension":{"en":"Check the end date in the notice of termination against the applicable notice period.","zh":"请按适用的通知期核对终止雇佣通知上的结束日期。"}},{"id":"HR6-38","moduleId":"m6","module":"员工关系与劳动合规","term":"Garden leave","zh":"离职通知期带薪免到岗（花园假）","definition":"在英国雇佣等语境中，指员工在通知期仍受雇并依约领薪，由雇主安排在部分或全部期间暂停日常工作。","example":"The company placed him on garden leave for the final month of his notice period.","collocation":"place an employee on garden leave","dialogue":[{"role":"Employee","en":"Can I start at my new company while I’m on garden leave?","zh":"离职通知期内带薪免到岗时，我可以去新公司上班吗？"},{"role":"HR Adviser","en":"You’re still employed here. Please check your contract and the terms we’ve agreed.","zh":"你仍是本公司的员工。请核对合同及双方已约定的条件。"}],"usage":"HR 英式用语；不是旅游休假，也不等同于停职 suspension。须结合当地法律及合同条款判断能否适用。","new":true,"order":238,"distinction":"Garden leave 期间雇佣关系持续。Payment in lieu of notice 通常指以代通知金替代实际履行通知期，适用条件另行判断。","aliases":["Gardening leave","花园假","带薪待岗（通知期）","离职前带薪免到岗"],"collocationZh":"安排员工在通知期内带薪免到岗","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈɡɑː.dən liːv","ipaUS":"ˈɡɑːr.dən liːv","ipaSource":"词典重点校订","speakTerm":"Garden leave","exampleZh":"公司安排他在离职通知期的最后一个月带薪免到岗。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can we place the employee on garden leave during the notice period?","zh":"我们可以在离职通知期内安排该员工带薪免到岗吗？"},"extension":{"en":"While on garden leave, she remained an employee until the notice period ended.","zh":"带薪免到岗期间，她的雇佣关系持续至通知期结束。"}},{"id":"HR6-39","moduleId":"m6","module":"员工关系与劳动合规","term":"Workplace accommodation","zh":"工作场所合理便利／合理调整","definition":"为使员工能够平等参与工作而对工作环境、设备、流程或时间所作的调整，具体资格及义务以适用制度为准。","example":"HR discussed workplace accommodations with the employee.","collocation":"request a workplace accommodation","dialogue":[{"role":"Employee","en":"Could we discuss a workplace accommodation for my return to work?","zh":"能谈谈我返岗时需要的工作场所便利安排吗？"},{"role":"HR Adviser","en":"Of course. Tell me which parts of the current setup are creating barriers.","zh":"当然。你可以说说目前哪些工作设置带来了障碍。"}],"usage":"这里 accommodation 不指差旅住宿。","new":true,"order":239,"distinction":"Workplace accommodation 指工作场所内的便利调整。Reasonable accommodation 强调在相应制度下对调整合理性的判断。","aliases":[],"collocationZh":"申请工作场所合理便利","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈwɜːkpleɪs əˌkɒməˈdeɪʃən","ipaUS":"ˈwɝːkpleɪs əˌkɑːməˈdeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Workplace accommodation","exampleZh":"人力资源部门与员工讨论了职场合理便利安排。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do employees request workplace accommodation?","zh":"员工如何申请工作场所的合理便利安排？"},"extension":{"en":"Adjustable lighting can be one option when discussing a workplace accommodation.","zh":"讨论工作场所便利安排时，可调节照明可以作为一个方案。"}},{"id":"HR6-40","moduleId":"m6","module":"员工关系与劳动合规","term":"Non-disclosure agreement (NDA)","zh":"保密协议","definition":"约定一方或各方对特定信息承担保密义务的协议，可规定信息范围、例外和期限。","example":"The employee signed a non-disclosure agreement for the project.","collocation":"sign a non-disclosure agreement","dialogue":[{"role":"Project Lead","en":"Do the consultants need to sign an NDA before they see the draft materials?","zh":"顾问在查看材料草案前需要签保密协议吗？"},{"role":"Legal Counsel","en":"Yes. This project includes non-public information, so use the approved form.","zh":"需要。项目涉及非公开信息，请使用已获批的模板。"}],"usage":"","new":true,"order":240,"aliases":[],"distinction":"NDA 约束特定信息的披露或使用。Non-compete agreement 限制一定范围的竞争行为。","collocationZh":"签署保密协议（NDA）","collocationReview":"V18.2 模型编辑复核","ipaUK":"nɒn dɪsˈkləʊʒə əˈɡriːmənt","ipaUS":"nɑːn dɪsˈkloʊʒɚ əˈɡriːmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Non-disclosure agreement","exampleZh":"员工为该项目签署了保密协议。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Do contractors need to sign an NDA for this project?","zh":"承包商是否需要为这个项目签署保密协议？"},"extension":{"en":"Before sharing the payroll extracts, check whether the NDA covers that type of data.","zh":"共享工资数据摘录前，请确认保密协议是否覆盖这一类数据。"}},{"id":"HR181","moduleId":"m7","module":"企业文化与员工体验","term":"Organizational culture","zh":"组织文化","definition":"组织成员在长期协作中形成的共同假设、价值观和行为惯例，影响团队如何理解问题并作决定。","example":"Organizational culture shapes how teams make decisions.","collocation":"build organizational culture","dialogue":[{"role":"New Hire","en":"Where can I learn more about the organizational culture here?","zh":"我可以在哪里更了解这里的组织文化？"},{"role":"Manager","en":"Join a few team meetings and watch what happens when people disagree.","zh":"参加几次团队会议，看看大家意见不同时会怎么处理。"}],"usage":"","new":false,"order":241,"aliases":["Corporate Culture"],"distinction":"Organizational culture 关注组织内长期形成的行为模式。Organizational climate 关注员工目前如何感知工作环境。","collocationZh":"建立组织文化","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɔːɡənaɪˈzeɪʃənəl ˈkʌltʃə","ipaUS":"ˌɔːrɡənəˈzeɪʃənəl ˈkʌltʃɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Organizational culture","exampleZh":"组织文化影响团队作出决策的方式。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How does organizational culture influence our decisions?","zh":"组织文化如何影响我们的决策？"},"extension":{"en":"Organizational culture often shows up in how managers respond to bad news.","zh":"组织文化常体现在管理者如何回应坏消息上。"}},{"id":"HR182","moduleId":"m7","module":"企业文化与员工体验","term":"Core values","zh":"核心价值观","definition":"组织认同并希望在日常决策和行为中体现的基本原则。","example":"Our core values guide hiring and leadership decisions.","collocation":"live our core values","dialogue":[{"role":"Employee","en":"How do our core values apply when a project slips?","zh":"项目延期时，怎样体现我们的核心价值观？"},{"role":"Manager","en":"Take ownership. Tell the customer early and explain what we’re doing about it.","zh":"主动担责。尽早告诉客户，并说明我们在采取什么措施。"}],"usage":"","new":false,"order":242,"aliases":[],"distinction":"Core values 说明组织遵循哪些原则。A code of conduct 通常把行为底线或要求写成明确规定。","collocationZh":"践行企业核心价值观","collocationReview":"V18.2 模型编辑复核","ipaUK":"kɔː ˈvæljuːz","ipaUS":"kɔːr ˈvæljuːz","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Core values","exampleZh":"我们的核心价值观指导招聘和领导决策。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should our core values guide leadership decisions?","zh":"核心价值观应如何指导领导决策？"},"extension":{"en":"We used our core values to decide how to handle competing customer requests.","zh":"我们依据公司的核心价值观处理了相互冲突的客户诉求。"}},{"id":"HR183","moduleId":"m7","module":"企业文化与员工体验","term":"Company mission","zh":"企业使命","definition":"说明企业为何存在、服务谁或希望为其创造何种价值的陈述。","example":"The company mission explains why our work matters.","collocation":"communicate the company mission","dialogue":[{"role":"New Hire","en":"The company mission mentions access to healthcare. How does our team contribute?","zh":"企业使命提到改善医疗服务可及性，我们团队能做什么？"},{"role":"Team Lead","en":"We make it easier for clinics to book appointments for their patients.","zh":"我们帮助诊所更方便地为患者预约。"}],"usage":"","new":false,"order":243,"aliases":[],"distinction":"Company mission 说明企业当下存在的目的。Company vision 描述未来想达到的状态。","collocationZh":"传达公司使命","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkʌmpəni ˈmɪʃən","ipaUS":"ˈkʌmpəˌniː ˈmɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Company mission","exampleZh":"公司使命说明了我们的工作为什么重要。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Why does the company's mission matter to employees?","zh":"公司的使命为什么对员工重要？"},"extension":{"en":"Use the company mission to explain why the project matters to our customers.","zh":"请结合企业使命说明这一项目为何对我们的客户重要。"}},{"id":"HR184","moduleId":"m7","module":"企业文化与员工体验","term":"Company vision","zh":"企业愿景","definition":"对企业希望在长期实现的未来状态或方向的描述。","example":"Our company vision helps employees see the bigger picture.","collocation":"share the company vision","dialogue":[{"role":"Employee","en":"Does the company vision call for growth outside our home market?","zh":"企业愿景是否包括在本土市场之外发展？"},{"role":"Director","en":"Yes. It describes a business that can serve customers across the region.","zh":"包括。它描绘的是一家能够服务整个区域客户的企业。"}],"usage":"","new":false,"order":244,"aliases":[],"distinction":"Company vision 描绘长期希望实现的状态。Company mission 说明企业存在的目的。","collocationZh":"分享企业愿景","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkʌmpəni ˈvɪʒən","ipaUS":"ˈkʌmpəˌniː ˈvɪʒən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Company vision","exampleZh":"公司的愿景帮助员工理解更宏观的发展方向。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we help employees understand the long-term direction?","zh":"我们怎样帮助员工理解公司的长期发展方向？"},"extension":{"en":"The leadership team used the company vision to guide its three-year plan.","zh":"领导团队以企业愿景为指引制定三年规划。"}},{"id":"HR185","moduleId":"m7","module":"企业文化与员工体验","term":"Cultural fit","zh":"文化匹配","definition":"候选人或员工的工作方式与组织价值观或行为标准相契合的程度。招聘时应以与岗位有关、可观察的标准评估。","example":"We should not use cultural fit as a vague reason to reject candidates.","collocation":"avoid cultural fit bias","dialogue":[{"role":"Interviewer","en":"The notes say “poor cultural fit.” What did the panel actually observe?","zh":"面试记录写着“文化匹配度低”。小组具体观察到了什么？"},{"role":"Recruiter","en":"I’ll ask for a work-related example before we use that feedback.","zh":"在采纳这条反馈之前，我会请他们给出与工作有关的具体事例。"}],"usage":"","new":false,"order":245,"aliases":[],"distinction":"Cultural fit 关注与工作价值观或行为标准的契合。Culture add 关注候选人可以带来的互补经验或视角。","collocationZh":"避免文化匹配偏见","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkʌltʃərəl fɪt","ipaUS":"ˈkʌltʃɚəl fɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Cultural fit","exampleZh":"我们不应以含糊的“文化契合度”为由拒绝候选人。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Should we use vague cultural fit judgments to reject candidates?","zh":"我们是否应该用模糊的“文化匹配”判断淘汰候选人？"},"extension":{"en":"Ask the panel to tie any assessment of cultural fit to observed work behavior.","zh":"请面试小组用可观察的工作行为作为评价文化匹配度的依据。"}},{"id":"HR186","moduleId":"m7","module":"企业文化与员工体验","term":"Culture add","zh":"文化增益／文化互补","definition":"候选人或员工为现有团队带来的互补经验、观点或工作方式。","example":"We assess culture add by exploring diverse experiences and ideas.","collocation":"assess a candidate for culture add","dialogue":[{"role":"Hiring Manager","en":"How will we assess culture add for this role?","zh":"这个岗位怎么评估候选人能带来的文化增益？"},{"role":"Recruiter","en":"Ask candidates how they’ve helped teams consider a perspective that was missing.","zh":"请候选人举例，说明他们曾如何帮助团队考虑原先被忽略的视角。"}],"usage":"","new":false,"order":246,"aliases":[],"distinction":"Culture add 关注新成员能补充的视角。Cultural fit 关注与工作价值观及行为标准的契合，两者可同时考虑。","collocationZh":"评估候选人能为团队文化带来的互补价值","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkʌltʃə æd","ipaUS":"ˈkʌltʃɚ æd","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Culture add","exampleZh":"我们通过考察多样化的经历和观点来评价候选人能带来的文化增益。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can candidates contribute new perspectives to the team?","zh":"候选人如何为团队带来新的视角？"},"extension":{"en":"Use a structured interview to explore culture add without rewarding familiarity.","zh":"通过结构化面试了解候选人能带来的文化增益，避免仅凭熟悉感给高分。"}},{"id":"HR187","moduleId":"m7","module":"企业文化与员工体验","term":"Employee engagement","zh":"员工敬业度","definition":"员工对工作及组织表现出的投入程度和心理联结，具体维度因所用评估框架而异。","example":"Employee engagement improved after managers acted on survey feedback.","collocation":"increase employee engagement","dialogue":[{"role":"People Analyst","en":"Is employee engagement down across all shifts?","zh":"所有班次的员工敬业度都下降了吗？"},{"role":"Manager","en":"The decline was concentrated on the night shift. Let’s speak with that team first.","zh":"下降主要集中在夜班。我们先和这个班组谈谈。"}],"usage":"","new":false,"order":247,"aliases":[],"distinction":"Employee engagement 重在投入和联结。Employee satisfaction 重在员工对工作条件或体验的满意程度。","collocationZh":"提升员工敬业度","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː enˈɡeɪdʒmənt","ipaUS":"ɪmˈplɔɪ.iː enˈɡeɪdʒmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee engagement","exampleZh":"管理者根据敬业度调查反馈采取行动后，员工敬业度提高了。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What changed after managers acted on engagement survey results?","zh":"经理根据敬业度调查结果采取行动后，发生了什么变化？"},"extension":{"en":"We paired employee engagement scores with interview feedback before setting priorities.","zh":"确定重点之前，我们结合了员工敬业度得分与访谈反馈。"}},{"id":"HR188","moduleId":"m7","module":"企业文化与员工体验","term":"Employee experience (EX)","zh":"员工体验","definition":"员工在与组织互动的各个阶段形成的总体感受，包括入职、日常工作、发展及离职等环节。","example":"Employee experience includes every major moment in the employee journey.","collocation":"improve the employee experience","dialogue":[{"role":"Operations Lead","en":"Where should we start improving the employee experience at this site?","zh":"要改善本站点的员工体验，应该从哪里开始？"},{"role":"HRBP","en":"Let’s look at the first week. New hires say it takes too long to get system access.","zh":"先看入职第一周。新员工说开通系统权限要等太久。"}],"usage":"","new":false,"order":248,"aliases":[],"distinction":"Employee experience 是实际经历和感受。Employee value proposition 概括雇主向员工提供或承诺的价值。","collocationZh":"改善员工体验","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ekˈspiərɪəns","ipaUS":"ɪmˈplɔɪ.iː ɪkˈspɪriːəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee experience","exampleZh":"员工体验涵盖员工职业旅程中的每一个重要时刻。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which stages of employment shape employee experience?","zh":"雇佣关系中的哪些阶段会塑造员工体验？"},"extension":{"en":"We asked new hires to describe their employee experience during the first month.","zh":"我们请新员工谈谈入职第一个月的体验。"}},{"id":"HR189","moduleId":"m7","module":"企业文化与员工体验","term":"Employee value proposition (EVP)","zh":"雇主价值主张","definition":"雇主为吸引、激励和留住员工而提供的整体价值组合，包括薪酬、成长机会和工作体验等。","example":"Our employee value proposition emphasizes growth and flexibility.","collocation":"refresh the EVP","dialogue":[{"role":"Recruiter","en":"Can we include flexible scheduling in our EVP for store roles?","zh":"门店岗位的雇主价值主张里能写弹性排班吗？"},{"role":"HRBP","en":"Only if managers can consistently offer it. Let’s verify how scheduling actually works.","zh":"要看门店经理能否持续提供这种安排。我们先核实实际排班方式。"}],"usage":"","new":false,"order":249,"aliases":[],"distinction":"EVP 强调雇主提供什么价值。Employer brand 是候选人及员工等群体对雇主形成的形象和评价。","collocationZh":"更新雇主价值主张（EVP）","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˈvæljuː ˌprɒpəˈzɪʃən","ipaUS":"ɪmˈplɔɪ.iː ˈvæljuː ˌprɑːpəˈzɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee value proposition","exampleZh":"我们的员工价值主张突出成长机会和灵活性。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What makes our employee value proposition attractive?","zh":"雇主价值主张的吸引力体现在哪些方面？"},"extension":{"en":"We tested the revised EVP with current employees before using it in job ads.","zh":"把修订后的雇主价值主张写进招聘广告前，我们先征求了在职员工的反馈。"}},{"id":"HR190","moduleId":"m7","module":"企业文化与员工体验","term":"Psychological safety","zh":"心理安全感","definition":"团队成员相信自己可以提问、承认错误或提出不同意见，而不必担心受到羞辱或不当惩罚的共同感受。","example":"Psychological safety encourages people to speak up early.","collocation":"create psychological safety","dialogue":[{"role":"Team Lead","en":"People keep raising concerns after the meeting instead of in it.","zh":"大家总在会后才提出问题。"},{"role":"HRBP","en":"To build psychological safety, start by inviting objections before you announce your own view.","zh":"为了建立心理安全感，可以先请大家提出异议，再表明你自己的看法。"}],"usage":"","new":false,"order":250,"aliases":[],"distinction":"Psychological safety 关注承担人际风险时是否感到安全。Trust 可指对他人能力、可靠性或意图的信任，适用范围更广。","collocationZh":"营造心理安全氛围","collocationReview":"V18.2 模型编辑复核","ipaUK":"saɪkəˈlɒdʒɪkəl ˈseɪfti","ipaUS":"ˌsaɪkəˈlɑːdʒɪkəl ˈseɪftiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Psychological safety","exampleZh":"心理安全感鼓励员工及早表达意见。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we encourage team members to speak up?","zh":"我们怎样鼓励团队成员敢于表达意见？"},"extension":{"en":"The team built psychological safety by discussing mistakes openly during retrospectives.","zh":"团队在复盘中坦诚讨论错误，逐步建立了心理安全感。"}},{"id":"HR191","moduleId":"m7","module":"企业文化与员工体验","term":"Belonging","zh":"归属感","definition":"员工感到自己被接纳、受到尊重，并是团队或组织一员的体验。","example":"A sense of belonging helps new hires settle in.","collocation":"foster belonging","dialogue":[{"role":"Manager","en":"How can we foster belonging for colleagues who rarely work on site?","zh":"很少到现场办公的同事，怎么才能更有归属感？"},{"role":"People Partner","en":"Make sure they can join informal team conversations as well as scheduled meetings.","zh":"除了正式会议，也让他们有机会参与团队的非正式交流。"}],"usage":"","new":false,"order":251,"aliases":[],"distinction":"Belonging 是感到被接纳的体验。Inclusion 是使不同背景的人能参与和贡献的做法与环境。","collocationZh":"营造归属感","collocationReview":"V18.2 模型编辑复核","ipaUK":"bɪˈlɒŋɪŋ","ipaUS":"bɪˈlɔːŋɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Belonging","exampleZh":"归属感有助于新员工融入团队。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we help new hires feel that they belong?","zh":"如何帮助新员工建立归属感？"},"extension":{"en":"The interviews revealed that remote hires struggled to develop a sense of belonging.","zh":"访谈发现，远程入职的员工较难建立归属感。"}},{"id":"HR192","moduleId":"m7","module":"企业文化与员工体验","term":"Inclusion","zh":"包容","definition":"通过移除参与障碍，使不同背景和处境的人能够参与、表达并影响工作事务。","example":"Inclusion means everyone's ideas can be heard.","collocation":"promote inclusion at work","dialogue":[{"role":"Manager","en":"Would sharing the agenda early help with inclusion?","zh":"提前发议程能让更多人参与吗？"},{"role":"Facilitator","en":"Yes. It gives people time to reflect and prepare their input.","zh":"能。这样大家就有时间思考并准备意见。"}],"usage":"","new":false,"order":252,"aliases":[],"distinction":"Inclusion 关注不同人员能否参与并贡献。Diversity 关注群体成员的背景、经历与观点是否多元。","collocationZh":"促进职场包容","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪnˈkluːʒən","ipaUS":"ˌɪnˈkluːʒən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Inclusion","exampleZh":"包容性意味着每个人的想法都有被倾听的机会。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we make sure everyone's ideas are heard?","zh":"我们怎样确保每个人的想法都被听到？"},"extension":{"en":"We improved inclusion by collecting written input before each meeting.","zh":"我们在每次会议前收集书面意见，让更多人能够参与。"}},{"id":"HR193","moduleId":"m7","module":"企业文化与员工体验","term":"Diversity, equity and inclusion (DEI)","zh":"多元、公平与包容","definition":"关注群体多元性、减少制度中的不公平障碍，以及让不同人员参与并作出贡献的一组管理议题。","example":"Our diversity, equity and inclusion initiatives focus on fair processes.","collocation":"DEI initiatives","dialogue":[{"role":"Manager","en":"How can we make our DEI work more concrete this quarter?","zh":"这个季度怎样让多元、公平与包容工作更具体？"},{"role":"People Partner","en":"Start by reviewing who is able to access the manager training and where the barriers are.","zh":"先看看哪些人能参加经理培训，以及有哪些参与障碍。"}],"usage":"","new":false,"order":253,"aliases":[],"distinction":"Diversity 看人员构成的多元性，equity 看机会及规则是否公平，inclusion 看不同成员能否参与。Equality 常着眼于同等对待或同等权利。","collocationZh":"多元、公平与包容举措","collocationReview":"V18.2 模型编辑复核","ipaUK":"daɪˈvɜːsɪti ˈekwɪti ænd ɪnˈkluːʒən","ipaUS":"dɪˈvɝːsɪtiː ˈekwətiː ənd ˌɪnˈkluːʒən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Diversity, equity and inclusion","exampleZh":"我们的多元、公平与包容举措聚焦于公平的流程。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What are our DEI initiatives focusing on this year?","zh":"今年的多元、公平与包容举措重点是什么？"},"extension":{"en":"The DEI review examined whether our promotion criteria create barriers for some employees.","zh":"多元、公平与包容审查检视了晋升标准是否给部分员工造成障碍。"}},{"id":"HR194","moduleId":"m7","module":"企业文化与员工体验","term":"Employee resource group (ERG)","zh":"员工资源社群","definition":"通常由员工发起或参与、以共同身份、经历或兴趣为纽带，并由组织提供不同程度支持的内部网络。","example":"The employee resource group hosts mentoring events.","collocation":"launch an ERG","dialogue":[{"role":"Employee","en":"Can allies join the employee resource group?","zh":"支持这一议题的同事也能加入员工资源社群吗？"},{"role":"ERG Lead","en":"Yes. Our group welcomes anyone who wants to support its work.","zh":"可以。我们欢迎任何愿意支持社群工作的同事。"}],"usage":"","new":false,"order":254,"aliases":[],"distinction":"ERG 常组织互助、交流和倡议活动。Labor union 代表员工集体利益，并可能依法开展集体谈判。","collocationZh":"成立员工资源社群（ERG）","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː rɪˈzɔːs ɡruːp","ipaUS":"ɪmˈplɔɪ.iː ˈriːsɔːrs ɡruːp","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee resource group","exampleZh":"员工资源小组会举办导师交流活动。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What activities does the employee resource group organize?","zh":"员工资源社群组织哪些活动？"},"extension":{"en":"The ERG invited colleagues to a discussion on accessible meeting practices.","zh":"员工资源社群邀请同事讨论怎样让会议更无障碍。"}},{"id":"HR195","moduleId":"m7","module":"企业文化与员工体验","term":"Pulse survey","zh":"短频调查（脉搏调查）","definition":"以较短问卷快速了解员工对某一主题的反馈，可按较短周期开展以跟踪变化。","example":"We run a pulse survey after each major organizational change.","collocation":"monthly pulse survey","dialogue":[{"role":"Manager","en":"Can we add ten questions to the pulse survey?","zh":"我们能在这份短频调查里再加十道题吗？"},{"role":"People Analyst","en":"Let’s keep it brief and save the broader questions for the annual survey.","zh":"我们把这次调查做短一些，范围更广的问题留到年度调查。"}],"usage":"","new":false,"order":255,"aliases":[],"distinction":"Pulse survey 通常问题少，便于快速追踪。Engagement survey 聚焦敬业度，可以是全面调查，也可以采用短频调查形式。","collocationZh":"每月员工脉搏调查","collocationReview":"V18.2 模型编辑复核","ipaUK":"pʌls ˈsɜː.veɪ","ipaUS":"pʌls ˈsɝː.veɪ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Pulse survey","exampleZh":"每次重大组织变革后，我们都会开展一次脉搏调查。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When should we run a quick pulse survey?","zh":"我们应该什么时候开展快速脉搏调查？"},"extension":{"en":"Keep the next pulse survey focused on whether the new shift pattern is working.","zh":"下一轮短频调查请重点了解新排班模式是否有效。"}},{"id":"HR196","moduleId":"m7","module":"企业文化与员工体验","term":"Engagement survey","zh":"敬业度调查","definition":"通过问卷衡量员工投入与组织联结，并收集工作环境、管理支持等相关反馈。","example":"The engagement survey showed a need for better career conversations.","collocation":"analyze engagement survey results","dialogue":[{"role":"Department Head","en":"What should we do after the engagement survey closes?","zh":"敬业度调查结束后，我们该做什么？"},{"role":"People Partner","en":"Share the main findings and agree on one action the team can track.","zh":"先分享主要发现，再定一项团队可以持续跟踪的行动。"}],"usage":"","new":false,"order":256,"aliases":[],"distinction":"Engagement survey 聚焦敬业度及其相关因素。Satisfaction survey 侧重员工对工作各方面的满意程度。","collocationZh":"分析敬业度调查结果","collocationReview":"V18.2 模型编辑复核","ipaUK":"enˈɡeɪdʒmənt ˈsɜː.veɪ","ipaUS":"enˈɡeɪdʒmənt ˈsɝː.veɪ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Engagement survey","exampleZh":"员工敬业度调查显示，需要开展更好的职业发展沟通。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What did the latest engagement survey reveal?","zh":"最近一次敬业度调查揭示了什么？"},"extension":{"en":"Before sharing engagement survey results, check the minimum reporting size for small teams.","zh":"发布敬业度调查结果前，请核对小团队的最低汇报人数门槛。"}},{"id":"HR197","moduleId":"m7","module":"企业文化与员工体验","term":"Employee Net Promoter Score (eNPS)","zh":"员工净推荐值","definition":"以 0 至 10 分询问员工向他人推荐本组织为雇主的意愿，通常用 9–10 分人数占比减去 0–6 分人数占比计算。","example":"The latest survey put our employee Net Promoter Score at 24.","collocation":"track eNPS","dialogue":[{"role":"Manager","en":"Our eNPS fell. Do we know what changed?","zh":"员工净推荐值下降了。知道是什么变了吗？"},{"role":"People Analyst","en":"We’ll review response rates and employee comments before drawing conclusions.","zh":"下结论前，我们会查看回收率和员工留言。"}],"usage":"典型计算为推荐者占比减去贬损者占比；具体问卷口径需统一。","new":false,"order":257,"aliases":[],"distinction":"eNPS 衡量推荐意愿，取值为 −100 至 +100。Engagement score 可综合多道题衡量投入和联结，计算方式由调查设计决定。","collocationZh":"跟踪员工净推荐值（eNPS）","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː net prəˈməʊtə skɔː","ipaUS":"ɪmˈplɔɪ.iː net prəˈmoʊtɚ skɔːr","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee Net Promoter Score (eNPS)","exampleZh":"最新调查显示，我们的员工净推荐值为 24。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How has the employee Net Promoter Score changed?","zh":"员工净推荐值发生了什么变化？"},"extension":{"en":"Check the response rate before attributing a rise in eNPS to policy changes.","zh":"把员工净推荐值上涨归因于政策调整前，请先核对问卷回收率。"}},{"id":"HR198","moduleId":"m7","module":"企业文化与员工体验","term":"Employee recognition","zh":"员工认可","definition":"以口头肯定、公开表扬、奖项等方式，承认员工的具体贡献、成果或有价值的行为。","example":"Our employee recognition program celebrates cross-team support.","collocation":"employee recognition program","dialogue":[{"role":"Manager","en":"Can I nominate the whole team for employee recognition?","zh":"我可以提名整个团队接受表彰吗？"},{"role":"HR Partner","en":"Yes. Describe what they achieved together and who contributed.","zh":"可以。请说明他们共同取得了什么成果、哪些人作出了贡献。"}],"usage":"","new":false,"order":258,"aliases":[],"distinction":"Employee recognition 关注对贡献的肯定，可不涉及金钱。A reward 是因贡献或达标给予的回报，可以是金钱或非金钱形式。","collocationZh":"员工认可与表彰计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˌrekəɡˈnɪʃən","ipaUS":"ɪmˈplɔɪ.iː ˌrekəɡˈnɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee recognition","exampleZh":"我们的员工认可计划表彰跨团队协作和支持。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we celebrate employees who support other teams?","zh":"我们如何表彰支持其他团队的员工？"},"extension":{"en":"Our employee recognition program highlights specific actions that helped customers.","zh":"我们的员工认可计划重点表扬帮助客户的具体行为。"}},{"id":"HR199","moduleId":"m7","module":"企业文化与员工体验","term":"Leadership communication","zh":"领导层沟通","definition":"领导层与员工就组织方向、决策、进展或关切进行的信息交流，可包括提问和反馈。","example":"Leadership communication should explain both the decision and the rationale.","collocation":"improve leadership communication","dialogue":[{"role":"HR Director","en":"What should we include in next week’s leadership communication?","zh":"下周的领导层沟通要涵盖哪些内容？"},{"role":"Communications Lead","en":"Explain what has been approved and leave time for questions about the rollout.","zh":"说明哪些事项已获批，并留出时间回答实施方面的问题。"}],"usage":"","new":false,"order":259,"aliases":[],"distinction":"Leadership communication 特指来自或涉及领导层的沟通。Internal communication 还涵盖部门之间和组织各层级的沟通。","collocationZh":"改善领导层沟通","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈliːdəˌʃɪp kəˌmjuːnɪˈkeɪʃən","ipaUS":"ˈliːdɚˌʃɪp kəˌmjuːnəˈkeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Leadership communication","exampleZh":"领导层沟通既要说明决策，也要解释决策依据。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should leaders explain when announcing a decision?","zh":"领导者在宣布决策时应该解释哪些内容？"},"extension":{"en":"Good leadership communication includes a clear explanation of what remains undecided.","zh":"好的领导层沟通会明确说明哪些事项还有待决定。"}},{"id":"HR200","moduleId":"m7","module":"企业文化与员工体验","term":"Town hall meeting","zh":"全员交流会","definition":"通常由领导层面向较广泛的员工群体交流组织信息并回应员工问题的会议。","example":"The CEO will answer questions at the town hall meeting.","collocation":"host a town hall meeting","dialogue":[{"role":"Employee","en":"Will there be a recording of the town hall meeting?","zh":"全员交流会会有录播吗？"},{"role":"Organizer","en":"Yes. We’ll also post written answers to the questions we run out of time for.","zh":"有。如果有问题来不及回答，我们也会发布书面答复。"}],"usage":"","new":false,"order":260,"aliases":[],"distinction":"Town hall 常突出互动问答。All-hands 强调邀请某个组织或团队的全体人员参加，两种名称在企业中可能互用。","collocationZh":"主持全员交流会","collocationReview":"V18.2 模型编辑复核","ipaUK":"taʊn hɔːl ˈmiːtɪŋ","ipaUS":"taʊn hɔːl ˈmiːtɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Town hall meeting","exampleZh":"首席执行官将在全员沟通会上回答问题。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Will employees have a chance to ask the CEO questions?","zh":"员工是否有机会向 CEO 提问？"},"extension":{"en":"Employees can submit questions anonymously before the town hall meeting.","zh":"员工可以在全员交流会前匿名提交问题。"}},{"id":"HR201","moduleId":"m7","module":"企业文化与员工体验","term":"All-hands meeting","zh":"全体员工会议","definition":"以整个公司、部门或团队的所有成员为对象的会议，常用于同步信息、优先事项和进展。","example":"The all-hands meeting will cover our quarterly priorities.","collocation":"quarterly all-hands meeting","dialogue":[{"role":"Team Lead","en":"Is the all-hands meeting for the whole company?","zh":"这次全体会议是面向整个公司的吗？"},{"role":"Organizer","en":"This one is for the operations division. The company-wide meeting is next month.","zh":"这次只面向运营事业部，公司全员会议在下个月。"}],"usage":"","new":false,"order":261,"aliases":[],"distinction":"All-hands meeting 强调参会对象是某一组织单元的全体人员。Town hall 常突出员工和领导层的问答互动。","collocationZh":"季度全员大会","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɔːl hændz ˈmiːtɪŋ","ipaUS":"ɔːl hændz ˈmiːtɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"All-hands meeting","exampleZh":"全员会议将讨论本季度的重点工作。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What topics will we cover at the all-hands meeting?","zh":"全员大会将讨论哪些议题？"},"extension":{"en":"We scheduled two all-hands sessions so colleagues in both time zones could attend.","zh":"我们安排了两场全体会议，让两个时区的同事都有机会参加。"}},{"id":"HR202","moduleId":"m7","module":"企业文化与员工体验","term":"Feedback culture","zh":"反馈文化","definition":"团队习惯于及时、具体、尊重地提供和接收反馈，并将反馈用于改进。","example":"A strong feedback culture makes coaching part of daily work.","collocation":"build a feedback culture","dialogue":[{"role":"Manager","en":"What can I do to build a feedback culture on my team?","zh":"我怎样才能在团队里建立反馈文化？"},{"role":"HRBP","en":"Ask for feedback on a decision you made, then tell the team what you’ll do with it.","zh":"先就自己作过的一项决定征求反馈，再告诉团队你打算如何处理。"}],"usage":"","new":false,"order":262,"aliases":[],"distinction":"Feedback culture 涵盖日常的正面和改进性反馈。Speak-up culture 特别关注提出问题、异议或疑虑时获得的支持。","collocationZh":"建立反馈文化","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈfiːdbæk ˈkʌltʃə","ipaUS":"ˈfiːdbæk ˈkʌltʃɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Feedback culture","exampleZh":"良好的反馈文化使辅导成为日常工作的一部分。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we make coaching part of everyday work?","zh":"如何将辅导反馈融入日常工作？"},"extension":{"en":"A healthy feedback culture gives people time to ask questions about the feedback they receive.","zh":"健康的反馈文化让员工有机会就收到的反馈提问。"}},{"id":"HR203","moduleId":"m7","module":"企业文化与员工体验","term":"Speak-up culture","zh":"敢言文化","definition":"鼓励员工放心提出问题、异议和疑虑，并期待组织认真回应的工作氛围。","example":"A speak-up culture depends on how leaders respond to concerns.","collocation":"encourage a speak-up culture","dialogue":[{"role":"Employee","en":"How do we know whether a speak-up culture is developing?","zh":"怎么判断我们的敢言文化是否在形成？"},{"role":"HR Partner","en":"Ask whether people feel comfortable raising concerns and whether they get a response.","zh":"可以问大家是否敢于提出疑虑，以及提出之后能否得到回应。"}],"usage":"","new":false,"order":263,"aliases":[],"distinction":"Speak-up culture 涉及员工是否愿意并敢于发声。A reporting channel 是具体的反映途径，可以支持这一文化。","collocationZh":"鼓励敢言文化","collocationReview":"V18.2 模型编辑复核","ipaUK":"spiːk ʌp ˈkʌltʃə","ipaUS":"spiːk ʌp ˈkʌltʃɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Speak-up culture","exampleZh":"鼓励员工发声的文化取决于领导者如何回应员工关切。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What makes employees comfortable raising concerns?","zh":"怎样让员工敢于反映问题？"},"extension":{"en":"Leaders support a speak-up culture by explaining how they acted on concerns.","zh":"领导者说明如何处理员工提出的问题，有助于形成敢言文化。"}},{"id":"HR204","moduleId":"m7","module":"企业文化与员工体验","term":"Cross-functional collaboration","zh":"跨职能协作","definition":"来自不同职能的人员共同解决问题、协调工作或交付成果。","example":"Cross-functional collaboration is critical for the product launch.","collocation":"enable cross-functional collaboration","dialogue":[{"role":"Project Lead","en":"What would make cross-functional collaboration easier on this rollout?","zh":"怎样才能让这次推行工作中的跨职能协作更顺畅？"},{"role":"HRBP","en":"Give each function a named contact and make the decision-making process clear.","zh":"每个职能明确一位联系人，并把决策流程说清楚。"}],"usage":"","new":false,"order":264,"aliases":[],"distinction":"Cross-functional collaboration 涉及多个专业职能。Cross-team collaboration 涉及多个团队，团队也可能属于同一职能。","collocationZh":"促进跨职能协作","collocationReview":"V18.2 模型编辑复核","ipaUK":"krɒs ˈfʌŋkʃənəl kəˌlæbəˈreɪʃən","ipaUS":"krɔːs ˈfʌŋkʃənəl kəˌlæbɚˈeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Cross-functional collaboration","exampleZh":"跨职能协作对产品发布至关重要。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is essential for the cross-functional product launch?","zh":"跨职能产品发布最需要什么样的协作？"},"extension":{"en":"Cross-functional collaboration helped legal and product resolve the issue before launch.","zh":"法务和产品通过跨职能协作，在上线前解决了问题。"}},{"id":"HR205","moduleId":"m7","module":"企业文化与员工体验","term":"Team norms","zh":"团队协作规范","definition":"团队形成的共同工作约定或行为预期，例如沟通、会议和决策方式。","example":"We agreed on team norms for hybrid meetings.","collocation":"set team norms","dialogue":[{"role":"Team Lead","en":"Should we revisit our team norms now that half the team works remotely?","zh":"现在半数成员远程办公，我们要重新讨论团队协作规范吗？"},{"role":"Member","en":"Yes. Let’s agree on how to include remote colleagues in quick decisions.","zh":"要。我们先商量如何让远程同事也能参与临时决策。"}],"usage":"","new":false,"order":265,"aliases":[],"distinction":"Team norms 指特定团队的行为约定。Company policy 通常适用于制度所覆盖的员工，约束范围更广。","collocationZh":"设定团队协作规范","collocationReview":"V18.2 模型编辑复核","ipaUK":"tiːm nɔːmz","ipaUS":"tiːm nɔːrmz","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Team norms","exampleZh":"我们就混合办公会议的团队规范达成了共识。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we agree on for hybrid team meetings?","zh":"混合办公团队开会前需要约定哪些协作规范？"},"extension":{"en":"Our team norms specify when to use chat and when to document decisions by email.","zh":"我们的团队协作规范明确了何时用即时消息、何时用电子邮件记录决定。"}},{"id":"HR206","moduleId":"m7","module":"企业文化与员工体验","term":"Hybrid work","zh":"混合办公","definition":"在工作周期内结合现场办公和远程办公的工作安排，频率和地点由组织制度或双方约定。","example":"Our hybrid work policy sets expectations for team collaboration.","collocation":"hybrid work arrangement","dialogue":[{"role":"Employee","en":"Under our hybrid work policy, can I choose which days to come in?","zh":"按照我们的混合办公政策，我能自己选到岗日期吗？"},{"role":"Manager","en":"You can choose one day. The team agrees on the other day together.","zh":"你可以自行选一天，另一天由团队共同商定。"}],"usage":"","new":false,"order":266,"aliases":[],"distinction":"Hybrid work 结合现场与远程地点。Flexible hours 调整工作时间，也可以在完全现场办公的安排下使用。","collocationZh":"混合办公安排","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈhaɪbrɪd wɜːk","ipaUS":"ˈhaɪbrəd wɝːk","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Hybrid work","exampleZh":"我们的混合办公政策明确了团队协作的期望。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we set expectations for hybrid collaboration?","zh":"我们如何明确混合办公协作的预期？"},"extension":{"en":"The hybrid work arrangement sets aside Tuesdays for in-person planning.","zh":"该混合办公安排把周二留作线下规划日。"}},{"id":"HR207","moduleId":"m7","module":"企业文化与员工体验","term":"Remote work policy","zh":"远程办公政策","definition":"说明远程办公适用资格、工作要求、设备和信息安全等事项的组织政策。","example":"The remote work policy covers equipment and information security.","collocation":"review remote work policy","dialogue":[{"role":"Employee","en":"Does the remote work policy cover temporary work from another city?","zh":"远程办公政策涵盖临时在其他城市办公吗？"},{"role":"HR Adviser","en":"Yes, but you need approval before you change your work location.","zh":"涵盖，但变更办公地点之前需要获批。"}],"usage":"","new":false,"order":267,"aliases":[],"distinction":"Remote work policy 是适用的一般规则。Remote work agreement 通常记录特定员工与组织约定的具体安排。","collocationZh":"审阅远程办公政策","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˈməʊt wɜːk ˈpɒlɪsi","ipaUS":"rɪˈmoʊt wɝːk ˈpɑːləsiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Remote work policy","exampleZh":"远程办公政策涵盖设备和信息安全要求。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should the remote work policy cover?","zh":"远程办公政策应该包含哪些内容？"},"extension":{"en":"Check the remote work policy before working from a different country.","zh":"到其他国家远程办公之前，请先查阅远程办公政策。"}},{"id":"HR208","moduleId":"m7","module":"企业文化与员工体验","term":"Work-life balance","zh":"工作生活平衡","definition":"工作责任与非工作生活之间可持续的协调状态，具体需求和安排因人而异。","example":"Flexible schedules can support work-life balance.","collocation":"promote work-life balance","dialogue":[{"role":"Manager","en":"What would improve your work-life balance during the busy season?","zh":"旺季时，怎样才能改善你的工作生活平衡？"},{"role":"Employee","en":"A more predictable schedule would make it easier to arrange childcare.","zh":"如果排班更可预期，我就更容易安排照顾孩子的事情。"}],"usage":"","new":false,"order":268,"aliases":[],"distinction":"Work-life balance 强调协调工作和其他生活责任。Work-life integration 强调如何在日常中更灵活地结合两者。","collocationZh":"推动工作生活平衡","collocationReview":"V18.2 模型编辑复核","ipaUK":"wɜːk laɪf ˈbæləns","ipaUS":"wɝːk laɪf ˈbæləns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Work-life balance","exampleZh":"灵活的工作时间安排有助于实现工作与生活平衡。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can flexible scheduling support employees?","zh":"弹性排班如何帮助员工？"},"extension":{"en":"The team reviewed meeting hours to support better work-life balance across time zones.","zh":"团队重新审视了开会时段，以改善不同时区同事的工作生活平衡。"}},{"id":"HR209","moduleId":"m7","module":"企业文化与员工体验","term":"Employee wellbeing","zh":"员工身心健康","definition":"员工在工作环境中及工作影响下的身心健康和良好状态，可涉及工作量、人际支持等因素。","example":"Employee wellbeing requires both resources and manageable workloads.","collocation":"employee wellbeing initiatives","dialogue":[{"role":"Operations Lead","en":"Should our employee wellbeing plan include changes to shift patterns?","zh":"员工身心健康计划是否应考虑调整排班？"},{"role":"HRBP","en":"Yes. First, let’s talk to teams that regularly work consecutive night shifts.","zh":"应该考虑。我们先与经常连续上夜班的班组交流。"}],"usage":"","new":false,"order":269,"aliases":[],"distinction":"Employee wellbeing 涵盖身心健康和工作环境等因素。Employee engagement 侧重员工对工作和组织的投入及联结。","collocationZh":"员工身心健康举措","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˈwelbiːɪŋ","ipaUS":"ɪmˈplɔɪ.iː ˌwelˈbiːɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee wellbeing","exampleZh":"员工身心健康既需要支持资源，也需要合理的工作负荷。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Does our wellbeing approach address workload as well as resources?","zh":"我们的员工健康举措是否同时关注工作负荷和支持资源？"},"extension":{"en":"We included workload and recovery time in the employee wellbeing review.","zh":"员工身心健康评估纳入了工作量和休息恢复时间。"}},{"id":"HR210","moduleId":"m7","module":"企业文化与员工体验","term":"Change communication","zh":"变革沟通","definition":"在组织变革期间与相关人员交流变革缘由、预期影响、时间安排和后续行动的过程。","example":"Change communication should address employee questions honestly.","collocation":"change communication plan","dialogue":[{"role":"Change Lead","en":"How often should we send change communication updates during the pilot?","zh":"试点期间，我们应该多久同步一次变革进展？"},{"role":"HRBP","en":"Send a short update each week and keep a channel open for urgent questions.","zh":"每周提供一次简短更新，并保留处理紧急问题的渠道。"}],"usage":"","new":false,"order":270,"aliases":[],"distinction":"Change communication 聚焦信息交流与反馈。Change management 还包括准备评估、培训、执行和采纳跟踪。","collocationZh":"变革沟通计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"tʃeɪndʒ kəˌmjuːnɪˈkeɪʃən","ipaUS":"tʃeɪndʒ kəˌmjuːnəˈkeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Change communication","exampleZh":"变革沟通应坦诚回应员工的疑问。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we explain the reasons and impact of the reorganization?","zh":"我们应如何解释组织重组的原因和影响？"},"extension":{"en":"The change communication plan explains which decisions are final and which are still open.","zh":"变革沟通计划说明了哪些决定已经确定、哪些仍可讨论。"}},{"id":"HR7-31","moduleId":"m7","module":"企业文化与员工体验","term":"Employee listening","zh":"倾听员工意见","definition":"通过调查、访谈等渠道持续了解员工的感受与意见，并跟进和反馈的做法。","example":"Employee listening should lead to visible follow-up.","collocation":"employee listening strategy","dialogue":[{"role":"HR Partner","en":"The survey is months away, and the night shift keeps raising the same issue at handover.","zh":"距离下次调查还有好几个月，夜班同事却一直在交接时提到同一个问题。"},{"role":"Operations Manager","en":"Let’s add a night-shift session to our employee listening plan. I’ll join and report back on what we can change.","zh":"在倾听员工意见的计划里加一场夜班座谈吧。我会到场，也会向大家反馈哪些地方可以调整。"}],"usage":"","new":true,"order":271,"aliases":[],"distinction":"Employee listening（倾听员工意见）是持续了解并回应员工意见的做法。employee voice（员工发声）指员工表达意见并参与影响工作决策的机会与渠道。employee survey（员工调查）只是倾听渠道之一。","collocationZh":"倾听员工意见的方案","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˈlɪsənɪŋ","ipaUS":"ɪmˈplɔɪ.iː ˈlɪsənɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee listening","exampleZh":"倾听员工意见后，应采取员工看得见的跟进行动。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we turn employee listening into action?","zh":"我们如何将员工心声收集转化为实际行动？"},"extension":{"en":"An employee listening strategy should include staff who rarely have access to email.","zh":"制定倾听员工意见的方案时，也应覆盖很少能使用电子邮件的员工。"}},{"id":"HR7-32","moduleId":"m7","module":"企业文化与员工体验","term":"Culture survey","zh":"组织文化调查","definition":"了解员工如何看待组织倡导的价值观及日常行为的调查。","example":"The culture survey revealed gaps between stated values and daily behavior.","collocation":"run a culture survey","dialogue":[{"role":"People Analyst","en":"The draft asks whether people like our values. We won’t learn much from that.","zh":"草稿问大家是否喜欢公司的价值观，这样问恐怕得不到多少有用的信息。"},{"role":"HR Partner","en":"For the culture survey, let’s ask what happens when someone challenges a decision.","zh":"在这次组织文化调查里，不如问问员工对一项决定提出异议后通常会发生什么。"}],"usage":"","new":true,"order":272,"aliases":[],"distinction":"Culture survey（组织文化调查）关注员工实际看到的组织规范和行为。engagement survey（员工敬业度调查）主要衡量员工对工作和组织的投入程度，两类调查的题项可以重叠。","collocationZh":"开展组织文化调查","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkʌltʃə ˈsɜː.veɪ","ipaUS":"ˈkʌltʃɚ ˈsɝː.veɪ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Culture survey","exampleZh":"组织文化调查发现，公司倡导的价值观与日常行为之间存在差距。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What did the culture survey tell us about teamwork?","zh":"文化调查告诉了我们哪些团队合作方面的信息？"},"extension":{"en":"Add a culture survey question about how teams handle mistakes.","zh":"请在组织文化调查中增加一道有关团队如何处理失误的问题。"}},{"id":"HR7-33","moduleId":"m7","module":"企业文化与员工体验","term":"Inclusion index","zh":"包容性指数","definition":"依据选定的题项或指标汇总员工包容体验的量化分数，题项与算法由具体调查设定。","example":"The inclusion index improved in the latest employee survey.","collocation":"track the inclusion index","dialogue":[{"role":"People Analyst","en":"The item about speaking up was skipped by half the team.","zh":"有一半团队成员跳过了关于能否坦率发言的题目。"},{"role":"HR Director","en":"Before we publish the inclusion index, check how our scoring rules handle skipped items.","zh":"公布包容性指数前，先看看我们的计分规则怎么处理未作答的题目。"}],"usage":"","new":true,"order":273,"aliases":[],"distinction":"Inclusion index（包容性指数）通常综合归属感、受尊重程度或表达意见的体验等题项。diversity metrics（多元化指标）可以描述群体构成。指数跨期比较前应核对题项、样本和计分方式。","collocationZh":"跟踪包容性指数","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪnˈkluːʒən ˈɪndeks","ipaUS":"ˌɪnˈkluːʒən ˈɪndeks","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Inclusion index","exampleZh":"最新员工调查中的包容性指数有所提高。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How is the inclusion index calculated?","zh":"包容性指数如何计算？"},"extension":{"en":"The inclusion index combines responses to four questions about belonging and voice.","zh":"包容性指数汇总了四道关于归属感和表达意见机会的题目的回答。"}},{"id":"HR7-34","moduleId":"m7","module":"企业文化与员工体验","term":"Employee journey map","zh":"员工旅程地图","definition":"从员工视角呈现工作历程中的关键接触点、体验和障碍的可视化工具。","example":"The employee journey map highlights pain points during onboarding.","collocation":"create an employee journey map","dialogue":[{"role":"HR Designer","en":"New hires get three versions of the same checklist. Who sends the first one?","zh":"新员工会收到三个版本的同一份清单。第一份是谁发的？"},{"role":"Recruiter","en":"I send it with the offer. Put that handoff on the employee journey map, and I’ll show you the email.","zh":"我随录用通知一起发。把这个交接点标在员工旅程地图上吧，我把邮件给你看。"}],"usage":"","new":true,"order":274,"aliases":[],"distinction":"Employee journey map（员工旅程地图）从员工视角标出接触点、体验和障碍。process map（流程图）更侧重任务顺序、责任人和处理步骤。","collocationZh":"绘制员工旅程地图","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˈdʒɜːni mæp","ipaUS":"ɪmˈplɔɪ.iː ˈdʒɝːniː mæp","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee journey map","exampleZh":"员工旅程地图突出了入职环节的体验痛点。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Where are the biggest gaps in the employee journey?","zh":"员工旅程中存在哪些最明显的体验缺口？"},"extension":{"en":"The employee journey map shows a gap between accepting the offer and receiving system access.","zh":"员工旅程地图显示，接受录用后，员工还要等一段时间才能获得系统权限。"}},{"id":"HR7-35","moduleId":"m7","module":"企业文化与员工体验","term":"Moments that matter","zh":"关键体验时刻","definition":"显著影响员工感受的重要事件节点。","example":"We focused on moments that matter, such as an employee’s first day or first promotion.","collocation":"moments that matter in the employee journey","dialogue":[{"role":"HR Partner","en":"When a parent returns from leave, no one is sure who should check in with them.","zh":"有员工休完育儿假返岗时，大家都不确定该由谁主动和他们沟通。"},{"role":"Team Lead","en":"Let’s treat that first week back as a moment that matters and make the check-in the manager’s responsibility.","zh":"把返岗第一周列为关键体验时刻，由直属经理负责沟通吧。"}],"usage":"","new":true,"order":275,"aliases":[],"distinction":"Moments that matter（关键体验时刻）指对员工体验影响特别大的节点。touchpoints（接触点）包括员工与组织的各类互动。哪些节点最关键，可以结合员工反馈判断。","collocationZh":"员工旅程中的关键体验时刻","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈməʊmənts ðæt ˈmætə","ipaUS":"ˈmoʊmənts ðæt ˈmætɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Moments that matter","exampleZh":"我们重点关注员工入职第一天、首次晋升等关键体验时刻。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which moments matter most to our employees?","zh":"哪些关键体验时刻对员工最重要？"},"extension":{"en":"Learning who you’ll report to after a reorganization can be a moment that matters.","zh":"得知组织重组后将向谁汇报，对员工而言可能是一个关键体验时刻。"}},{"id":"HR7-36","moduleId":"m7","module":"企业文化与员工体验","term":"Workplace flexibility","zh":"灵活工作安排","definition":"对工作时间、地点或方式作出的灵活安排。","example":"Workplace flexibility can improve access to talent.","collocation":"workplace flexibility options","dialogue":[{"role":"Team Lead","en":"Rina needs to finish by three on Tuesdays, but she can take the early shift.","zh":"里娜每周二得在三点前下班，不过她可以上早班。"},{"role":"HR Partner","en":"That’s an option under our workplace flexibility policy. Let’s check who can cover the late calls.","zh":"我们的灵活工作政策允许考虑这种安排。先看看谁能接手较晚时段的来电。"}],"usage":"","new":true,"order":276,"aliases":[],"distinction":"Workplace flexibility（灵活工作安排）可涉及工时、地点或班次。remote work（远程办公）侧重地点。flexitime（弹性工时）侧重一定范围内选择上下班时间。","collocationZh":"可选的灵活工作安排","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈwɜːkpleɪs ˌfleksəˈbɪlɪti","ipaUS":"ˈwɝːkpleɪs ˌfleksəˈbɪlətiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Workplace flexibility","exampleZh":"灵活的工作安排有助于扩大组织可以接触的人才范围。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What workplace flexibility options can we offer?","zh":"我们能提供哪些灵活办公安排？"},"extension":{"en":"Staggered start times offer workplace flexibility for teams that need to be on site.","zh":"对必须到现场工作的团队，错峰上班可以增加工作安排的灵活性。"}},{"id":"HR7-37","moduleId":"m7","module":"企业文化与员工体验","term":"Burnout prevention","zh":"职业倦怠预防","definition":"通过调整工作负荷、管理方式和工作支持等，降低长期工作压力导致职业倦怠的风险。","example":"Burnout prevention can involve revising workloads and changing management practices.","collocation":"burnout prevention measures","dialogue":[{"role":"Team Lead","en":"The same two people have covered every weekend this month.","zh":"这个月每个周末都是同两个人值班。"},{"role":"People Partner","en":"Let’s rotate the on-call shifts and defer the nonessential work. That should be part of our burnout prevention plan.","zh":"把值班轮换起来，再把不紧急的工作往后排。这些都该纳入职业倦怠预防计划。"}],"usage":"","new":true,"order":277,"aliases":[],"distinction":"Burnout prevention（职业倦怠预防）关注长期工作压力及其组织成因，如过重的工作量或缺少支持。stress management（压力管理）还可涵盖员工应对短期压力的方法。","collocationZh":"职业倦怠预防措施","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈbɜːnaʊt prɪˈvenʃən","ipaUS":"ˈbɝːnaʊt priːˈvenʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Burnout prevention","exampleZh":"预防职业倦怠可以从调整工作负荷和改变管理方式入手。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What actions will help prevent burnout on this team?","zh":"哪些行动有助于预防团队成员的职业倦怠？"},"extension":{"en":"For burnout prevention, set realistic deadlines during peak season.","zh":"为预防职业倦怠，应在业务高峰期设定切合实际的截止时间。"}},{"id":"HR7-38","moduleId":"m7","module":"企业文化与员工体验","term":"Employee advocacy","zh":"员工倡导","definition":"在雇主品牌语境中，指员工自愿向外界分享在职经历或推荐雇主。","example":"Employee advocacy can give job seekers a firsthand view of the workplace.","collocation":"employee advocacy program","dialogue":[{"role":"Employee","en":"I’d like to post about our apprenticeship, but I’d rather use my own words.","zh":"我想发帖介绍我们的学徒项目，但我想用自己的话来写。"},{"role":"Communications Lead","en":"Please do. The employee advocacy program has optional prompts if you want a starting point.","zh":"当然可以。员工倡导计划有一些可选的写作提示，需要时可以参考。"}],"usage":"","new":true,"order":278,"aliases":[],"distinction":"在雇主品牌语境中，employee advocacy（员工倡导）指员工自愿对外分享或推荐雇主。employee voice（员工发声）侧重向组织表达意见。brand ambassador（品牌大使）往往是经指定的身份。","collocationZh":"员工倡导计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˈædvəkəsi","ipaUS":"ɪmˈplɔɪ.iː ˈædvəkəsiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee advocacy","exampleZh":"员工倡导可以让求职者从员工的亲身分享中了解工作环境。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we support voluntary employee advocacy?","zh":"我们如何支持员工自愿成为雇主品牌倡导者？"},"extension":{"en":"Our employee advocacy program lets staff decide whether to share company news on their personal accounts.","zh":"在我们的员工倡导计划中，是否通过个人账号分享公司动态，由员工自己决定。"}},{"id":"HR7-39","moduleId":"m7","module":"企业文化与员工体验","term":"Recognition platform","zh":"员工认可平台","definition":"用于同事互相表扬或记录贡献的工具。","example":"The recognition platform makes peer appreciation more visible.","collocation":"launch a recognition platform","dialogue":[{"role":"Warehouse Lead","en":"Can the night crew thank coworkers from the shared kiosk?","zh":"夜班同事能在共用的自助终端上向同事表达感谢吗？"},{"role":"HR Coordinator","en":"Yes, the recognition platform is on the kiosk. I’ll add a shortcut so the crew can find it.","zh":"可以，终端上有员工认可平台。我会添加一个快捷入口，方便大家找到。"}],"usage":"","new":true,"order":279,"aliases":[],"distinction":"Recognition platform（员工认可平台）是公开或私下表扬、记录贡献的系统。recognition program（员工认可计划）涵盖表扬标准和实施机制。rewards platform（奖励平台）通常还支持发放或兑换奖励。","collocationZh":"上线员工认可平台","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌrekəɡˈnɪʃən ˈplætfɔːm","ipaUS":"ˌrekəɡˈnɪʃən ˈplætfɔːrm","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Recognition platform","exampleZh":"员工认可平台让同事之间的认可与感谢更容易被看见。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will we measure adoption of the recognition platform?","zh":"我们将如何衡量员工认可平台的采用情况？"},"extension":{"en":"The recognition platform lets employees send a private thank-you after a difficult handover.","zh":"员工可以在一次棘手的交接后，通过员工认可平台私下向同事致谢。"}},{"id":"HR7-40","moduleId":"m7","module":"企业文化与员工体验","term":"Culture transformation","zh":"文化转型","definition":"通过制度、行为和领导方式改变组织文化的过程。","example":"Culture transformation depends on sustained leadership action.","collocation":"culture transformation roadmap","dialogue":[{"role":"Operations Director","en":"We say people should flag problems early, but the review score still drops when they do.","zh":"我们希望员工尽早报告问题，可他们这样做了，考评分数还是会下降。"},{"role":"HR Director","en":"Let’s review that scoring rule first. Put it on the culture transformation roadmap with a deadline.","zh":"那就先审查这项评分规则，把它列入文化转型路线图并设定完成期限。"}],"usage":"","new":true,"order":280,"aliases":[],"distinction":"Culture transformation（文化转型）涉及组织惯常行为及其背后管理机制的改变。culture change initiative（文化变革举措）可以是其中一项具体行动。internal communications campaign（内部宣传活动）主要传达信息。","collocationZh":"文化转型路线图","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkʌltʃə trænsfɔːˈmeɪʃən","ipaUS":"ˈkʌltʃɚ ˌtrænsfɚˈmeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Culture transformation","exampleZh":"文化转型依赖领导层持续采取行动。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What changes will demonstrate real culture transformation?","zh":"哪些变化可以证明企业文化正在真正转型？"},"extension":{"en":"The culture transformation roadmap links each desired behavior to a change in management practice.","zh":"文化转型路线图将每项期望行为对应到一项管理实践的调整。"}},{"id":"HR211","moduleId":"m8","module":"HR运营与数据分析","term":"Human resources information system (HRIS)","zh":"人力资源信息系统","definition":"集中维护员工与组织数据并支持核心人力资源事务的信息系统。","example":"The human resources information system stores employee records.","collocation":"HRIS implementation","dialogue":[{"role":"HR Coordinator","en":"A manager changed teams last week, but the directory still shows her old department.","zh":"一位经理上周调了团队，但员工目录还显示她原来的部门。"},{"role":"HR Systems Analyst","en":"I’ll check the effective date in the HRIS and see whether the directory picked up the update.","zh":"我去人力资源信息系统里核对生效日期，再看看目录有没有同步这次更新。"}],"usage":"","new":false,"order":281,"aliases":[],"distinction":"HRIS（人力资源信息系统）通常侧重员工档案、组织数据和核心人事事务。HCM platform（人力资本管理平台）常涵盖招聘、绩效与人才发展等功能。各供应商的产品命名和范围可能重叠。","collocationZh":"人力资源信息系统（HRIS）实施","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈhjuːmən rɪˈzɔːsɪz ˌɪnfəˈmeɪʃən ˈsɪstəm","ipaUS":"ˈhjuːmən ˈriːsɔːrsɪz ˌɪnfɚˈmeɪʃən ˈsɪstəm","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Human resources information system","exampleZh":"人力资源信息系统（HRIS）保存员工档案。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Where do we store and manage employee records?","zh":"我们在哪里存储和管理员工档案记录？"},"extension":{"en":"Check which employee fields are mandatory before importing records into the HRIS.","zh":"向人力资源信息系统导入记录前，先确认哪些员工信息字段是必填的。"}},{"id":"HR212","moduleId":"m8","module":"HR运营与数据分析","term":"Human capital management (HCM)","zh":"人力资本管理","definition":"覆盖人员配置、绩效、发展和薪酬等环节的人力资本管理体系。软件语境中也常指支持这些流程的系统。","example":"Our human capital management platform supports global HR processes.","collocation":"HCM platform","dialogue":[{"role":"Talent Lead","en":"Can managers see performance reviews and development plans in one place?","zh":"经理能在同一个地方查看绩效评估和发展计划吗？"},{"role":"HR Systems Lead","en":"Both modules are in our HCM platform. I’ll set up a demo using a test account.","zh":"这两个模块都在我们的人力资本管理平台上。我用测试账号演示一下。"}],"usage":"","new":false,"order":282,"aliases":[],"distinction":"HCM（人力资本管理）可指涵盖人员配置、绩效与发展等环节的管理体系。HCM platform 指支持这些实践的软件。HRIS 通常更侧重人事数据和核心事务，具体取决于产品。","collocationZh":"人力资本管理平台","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈhjuːmən ˈkæpɪtəl ˈmænɪdʒmənt","ipaUS":"ˈhjuːmən ˈkæpətəl ˈmænədʒmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Human capital management","exampleZh":"我们的人力资本管理（HCM）平台支持全球人力资源流程。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which platform supports our global HR processes?","zh":"哪个平台支持我们的全球 HR 流程？"},"extension":{"en":"We use the HCM platform to link development goals to learning plans.","zh":"我们通过人力资本管理平台，把员工的发展目标与学习计划关联起来。"}},{"id":"HR213","moduleId":"m8","module":"HR运营与数据分析","term":"Employee master data","zh":"员工主数据","definition":"识别员工、任职及组织归属并供多个流程或系统复用的核心结构化数据。","example":"Please verify employee master data before payroll closes.","collocation":"maintain employee master data","dialogue":[{"role":"Payroll Analyst","en":"Why does Nina still show up under the old cost center?","zh":"为什么妮娜还归在原来的成本中心下？"},{"role":"HR Data Steward","en":"Her transfer is in the employee master data, but the new cost center doesn’t take effect until Monday.","zh":"员工主数据里已经有她的调动记录了，不过新的成本中心要到周一才生效。"}],"usage":"","new":false,"order":283,"aliases":[],"distinction":"Employee master data（员工主数据）是各系统常复用的核心记录，如员工编号、任职关系和成本中心。transaction data（事务数据）记录某次请假、审批等具体事件。主数据也可以带生效日期或历史版本。","collocationZh":"维护员工主数据","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˈmæstə ˈdeɪtə","ipaUS":"ɪmˈplɔɪ.iː ˈmæstɚ ˈdeɪtə","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee master data","exampleZh":"薪资结算前，请核对员工主数据。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What information must we verify before payroll closes?","zh":"薪资结算前必须核验哪些信息？"},"extension":{"en":"Use the ID in the employee master data to match records across systems.","zh":"跨系统匹配记录时，请使用员工主数据中的员工编号。"}},{"id":"HR214","moduleId":"m8","module":"HR运营与数据分析","term":"Personnel file","zh":"员工人事档案","definition":"按员工归集的与雇佣关系有关的记录，如劳动合同、岗位变动文件等。","example":"Access to a personnel file is restricted to authorized staff.","collocation":"review a personnel file","dialogue":[{"role":"HR Coordinator","en":"The signed contract is still sitting in the team inbox. Where should I move it?","zh":"签好的合同还在团队邮箱里，我该把它移到哪里？"},{"role":"HR Operations Lead","en":"File it in the employee’s personnel file using the approved document type. I’ll check the folder permissions.","zh":"按规定的文件类别存入该员工的人事档案吧。我来检查文件夹权限。"}],"usage":"","new":false,"order":284,"aliases":[],"distinction":"Personnel file（员工人事档案）是按员工归集的雇佣记录。employee master data（员工主数据）主要是供系统复用的结构化字段，二者在存放方式、访问权限和保留期限上可能不同。","collocationZh":"审阅员工人事档案","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌpɜːsəˈnel faɪl","ipaUS":"ˌpɝːsəˈnel faɪl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Personnel file","exampleZh":"只有获得授权的人员才能访问人事档案。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who is authorized to access personnel files?","zh":"哪些人有权查阅员工人事档案？"},"extension":{"en":"File the signed promotion letter in the employee’s personnel file.","zh":"请将签署后的晋升通知存入该员工的人事档案。"}},{"id":"HR215","moduleId":"m8","module":"HR运营与数据分析","term":"Employee lifecycle","zh":"员工全生命周期","definition":"员工与组织建立、发展和结束雇佣关系所经历的各阶段，通常包括招聘、入职、发展及离职。","example":"We mapped the employee lifecycle to find service gaps.","collocation":"map the employee lifecycle","dialogue":[{"role":"People Operations Lead","en":"We have an onboarding checklist, but nothing tells managers what to do when someone transfers internally.","zh":"我们有入职清单，但员工内部调动时，没有资料告诉经理该做什么。"},{"role":"HR Partner","en":"Let’s add internal transfers to the employee lifecycle map and mark who owns each handoff.","zh":"把内部调动加进员工全生命周期图，再标明每次交接由谁负责。"}],"usage":"","new":false,"order":285,"aliases":[],"distinction":"Employee lifecycle（员工全生命周期）按招聘、入职、发展、流动和离职等阶段组织管理活动。employee journey（员工旅程）侧重员工在这些阶段经历的接触点和感受。","collocationZh":"梳理员工全生命周期","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˈlaɪfsaɪkəl","ipaUS":"ɪmˈplɔɪ.iː ˈlaɪfˌsaɪkəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee lifecycle","exampleZh":"我们梳理了员工全生命周期，以识别人力资源服务中的缺口。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we identify gaps throughout an employee's journey?","zh":"如何识别员工全生命周期中的服务缺口？"},"extension":{"en":"Internal transfers are a stage to account for when designing employee lifecycle processes.","zh":"设计员工全生命周期流程时，应把内部调动纳入考虑。"}},{"id":"HR216","moduleId":"m8","module":"HR运营与数据分析","term":"HR shared services","zh":"人力资源共享服务","definition":"集中提供标准化HR事务服务的模式。","example":"Our HR shared services team handles routine employee inquiries.","collocation":"HR shared services center","dialogue":[{"role":"Site Manager","en":"Three people have asked me for employment verification letters this week. Who prepares them now?","zh":"这周有三个人找我开在职证明，现在由谁办理？"},{"role":"HR Partner","en":"Send them to the HR shared services center. It can issue a standard letter through the employee portal.","zh":"请他们联系人力资源共享服务中心。中心可以通过员工门户出具标准证明。"}],"usage":"","new":false,"order":286,"aliases":[],"distinction":"HR shared services（人力资源共享服务）集中办理可标准化的事务。HR business partners（人力资源业务伙伴）与业务部门协作处理团队和人才议题。center of expertise（专家中心）侧重专业方案和制度设计。","collocationZh":"人力资源共享服务中心","collocationReview":"V18.2 模型编辑复核","ipaUK":"eɪtʃ ɑː ʃeəd ˈsɜːvɪsɪz","ipaUS":"eɪtʃ ɑːr ʃerd ˈsɝːvəsəz","ipaSource":"音素词典与英式语音规则推导","speakTerm":"H R shared services","exampleZh":"我们的人力资源共享服务团队负责处理员工的日常咨询。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who handles routine employee HR questions?","zh":"谁负责解答员工日常的 HR 问题？"},"extension":{"en":"The HR shared services center handles address changes for all three sites.","zh":"三个站点的地址变更申请都由人力资源共享服务中心处理。"}},{"id":"HR217","moduleId":"m8","module":"HR运营与数据分析","term":"Service level agreement (SLA)","zh":"服务级别协议","definition":"约定服务范围及响应时限、办结时限或质量标准等服务目标的协议。","example":"Our service level agreement sets a target of two business days for the first response.","collocation":"meet an SLA","dialogue":[{"role":"Service Manager","en":"We replied to this ticket in an hour, but it stayed open for a week.","zh":"我们一小时内就回复了这张工单，但一周后才结案。"},{"role":"HR Operations Lead","en":"Our SLA tracks first response and resolution separately. Flag the delay on the resolution report.","zh":"我们的服务级别协议分别跟踪首次响应和办结时长。请在办结情况报告里标出这次延误。"}],"usage":"","new":false,"order":287,"aliases":[],"distinction":"SLA（服务级别协议）约定服务范围及可衡量的响应或办结承诺。KPI（关键绩效指标）用于衡量表现，也可用于检验协议执行情况。首次响应时限和办结时限应分别看。","collocationZh":"达到服务级别协议（SLA）的要求","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsɜːvɪs ˈlevəl əˈɡriːmənt","ipaUS":"ˈsɝːvəs ˈlevəl əˈɡriːmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Service level agreement","exampleZh":"我们的服务级别协议规定，首次响应目标为两个工作日。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What response time have we committed to?","zh":"我们承诺的响应时间是多少？"},"extension":{"en":"Our service level agreement specifies when the response clock starts.","zh":"我们的服务级别协议明确规定了从何时开始计算响应时间。"}},{"id":"HR218","moduleId":"m8","module":"HR运营与数据分析","term":"Case management","zh":"工单管理","definition":"记录、分派和跟进员工服务请求的流程。","example":"Case management helps us track complex HR requests.","collocation":"HR case management","dialogue":[{"role":"HR Service Adviser","en":"The employee sent the missing attachment in a separate email.","zh":"员工另发了一封邮件，把缺少的附件补过来了。"},{"role":"Case Coordinator","en":"Attach it to the original case and notify Priya in the case management system. She’s already reviewing it.","zh":"把附件存到原工单，再通过工单管理系统通知普丽娅。她已经在处理这件事了。"}],"usage":"","new":false,"order":288,"aliases":[],"distinction":"HR case management（人力资源工单管理）涵盖分类、分派、升级和关闭等处理步骤。service ticket（服务工单）是其中的一条请求记录。在员工关系场景中，case 也可指需要单独管理的个案。","collocationZh":"人力资源工单管理","collocationReview":"V18.2 模型编辑复核","ipaUK":"keɪs ˈmænɪdʒmənt","ipaUS":"keɪs ˈmænədʒmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Case management","exampleZh":"工单管理有助于跟踪较复杂的人力资源服务请求。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can we track complex HR service requests?","zh":"如何跟踪复杂的 HR 服务请求？"},"extension":{"en":"The case management system records who took over a request and when.","zh":"工单管理系统记录由谁接手请求以及何时接手。"}},{"id":"HR219","moduleId":"m8","module":"HR运营与数据分析","term":"Employee self-service (ESS)","zh":"员工自助服务","definition":"员工自行查工资条、请假等的功能。","example":"Employee self-service reduces routine HR tickets.","collocation":"ESS portal","dialogue":[{"role":"Employee","en":"My emergency contact has a new number. Do I need to submit a form?","zh":"我的紧急联系人的号码换了，需要填表吗？"},{"role":"HR Adviser","en":"You can update it in employee self-service under Personal Details. Save the change before you close the page.","zh":"可以在员工自助服务的「个人信息」页面修改。关掉页面前记得保存。"}],"usage":"","new":false,"order":289,"aliases":[],"distinction":"Employee self-service（员工自助服务）供员工查询或办理自己的事项。manager self-service（经理自助服务）按权限向经理提供团队事务的发起或审批功能。","collocationZh":"员工自助服务（ESS）门户","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː self ˈsɜːvɪs","ipaUS":"ɪmˈplɔɪ.iː self ˈsɝːvəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee self-service","exampleZh":"员工自助服务减少了常规人力资源工单。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can employees manage requests through self-service?","zh":"员工可以通过自助服务办理申请吗？"},"extension":{"en":"Employees can download their payslips through employee self-service even when the HR desk is closed.","zh":"人力资源服务台下班后，员工仍可通过员工自助服务下载工资单。"}},{"id":"HR220","moduleId":"m8","module":"HR运营与数据分析","term":"Manager self-service (MSS)","zh":"经理自助服务","definition":"经理直接提交或审批相关HR事项的功能。","example":"Manager self-service lets leaders approve team requests.","collocation":"MSS dashboard","dialogue":[{"role":"Store Manager","en":"One of my team members transferred in yesterday, but I can’t see her request.","zh":"昨天有位同事调入我的团队，但我看不到她的申请。"},{"role":"HR Systems Adviser","en":"I’ll check the reporting line in the system. Her requests will appear in manager self-service once the update takes effect.","zh":"我去核对系统里的汇报关系。更新生效后，她的申请就会出现在经理自助服务页面。"}],"usage":"","new":false,"order":290,"aliases":[],"distinction":"Manager self-service（经理自助服务）支持经理处理获授权的团队事务。employee self-service（员工自助服务）供员工办理个人事项。审批权限仍取决于组织配置。","collocationZh":"经理自助服务（MSS）看板","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈmæn.ɪ.dʒə self ˈsɜːvɪs","ipaUS":"ˈmæn.ə.dʒɚ self ˈsɝːvəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Manager self-service","exampleZh":"经理自助服务让管理者能够审批团队申请。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can managers approve team requests in the HR system?","zh":"经理可以在 HR 系统中批准团队申请吗？"},"extension":{"en":"The manager self-service dashboard shows which approvals are waiting for your team.","zh":"经理自助服务看板会显示本团队有哪些事项待审批。"}},{"id":"HR221","moduleId":"m8","module":"HR运营与数据分析","term":"Attendance tracking","zh":"考勤记录","definition":"记录员工到岗、离岗和缺勤等情况，并识别考勤异常的过程。","example":"Our attendance tracking system feeds into payroll.","collocation":"attendance tracking system","dialogue":[{"role":"Shift Supervisor","en":"Leo clocked in at the gate, but he’s showing as absent.","zh":"利奥在门岗打过卡，但系统显示他缺勤。"},{"role":"Payroll Coordinator","en":"Check whether the gate terminal synced with the attendance tracking system. I’ll hold that entry for review.","zh":"看看门岗终端有没有把记录同步到考勤系统。我先把这条记录留待核查。"}],"usage":"","new":false,"order":291,"aliases":[],"distinction":"Attendance tracking（考勤记录）侧重到岗、迟到和缺勤。time tracking（工时记录）侧重工作的时长及其任务归属。两者可共享打卡数据，也可以采用不同的采集方式。","collocationZh":"考勤系统","collocationReview":"V18.2 模型编辑复核","ipaUK":"əˈtendəns ˈtrækɪŋ","ipaUS":"əˈtendəns ˈtrækɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Attendance tracking","exampleZh":"我们的考勤系统向薪资系统提供数据。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How is employee attendance connected to payroll?","zh":"员工出勤记录如何关联薪资核算？"},"extension":{"en":"Attendance tracking flags missed clock-ins for a supervisor to review.","zh":"考勤系统会标记漏打卡的情况，供主管核查。"}},{"id":"HR222","moduleId":"m8","module":"HR运营与数据分析","term":"Leave of absence","zh":"正式离岗休假","definition":"员工因特定事由按适用制度暂时离岗的正式休假安排，可有薪或无薪，时长视具体情形而定。","example":"The employee requested a leave of absence for family reasons.","collocation":"request a leave of absence","dialogue":[{"role":"Employee","en":"I may need six weeks away to care for my father. Can we talk through the options?","zh":"我可能需要请六周假照顾父亲。我们能聊聊有哪些选择吗？"},{"role":"HR Adviser","en":"Let’s review which leave-of-absence options apply to your situation before you choose a start date.","zh":"在确定休假开始日期前，我们先看看哪些正式休假安排适用于你的情况。"}],"usage":"","new":false,"order":292,"aliases":[],"distinction":"Leave of absence（正式离岗休假）通常指经批准或按适用规定安排的暂时离岗。annual leave（年假）是特定假别。时长、工资待遇和岗位保护取决于适用规则。","collocationZh":"申请正式离岗休假","collocationReview":"V18.2 模型编辑复核","ipaUK":"liːv ɒv ˈæbsəns","ipaUS":"liːv ʌv ˈæbsəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Leave of absence","exampleZh":"该员工因家庭原因提出了正式离岗休假申请。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Why has the employee requested an extended leave of absence?","zh":"员工为什么申请长期休假？"},"extension":{"en":"The leave-of-absence form asks for an expected return date.","zh":"正式离岗休假申请表要求填写预计返岗日期。"}},{"id":"HR223","moduleId":"m8","module":"HR运营与数据分析","term":"Sick leave","zh":"病假","definition":"因疾病或健康原因按规定休假。","example":"Record sick leave in line with the policy that applies to the employee’s work location.","collocation":"sick leave entitlement","dialogue":[{"role":"Employee","en":"I’m too unwell to work today. Is a message to my supervisor enough?","zh":"我今天身体不舒服，没法工作。给主管发条消息就可以了吗？"},{"role":"HR Adviser","en":"Let your supervisor know now. I’ll send you the sick leave reporting steps for your site.","zh":"现在先通知主管。我把你所在站点的病假报备流程发给你。"}],"usage":"","new":false,"order":293,"aliases":[],"distinction":"Sick leave（病假）通常用于员工因自身健康状况休假。caregiver leave（照护假）涉及照顾他人。具体能否使用病假照顾家属，以及付薪和证明要求，取决于当地规则和公司政策。","collocationZh":"病假待遇","collocationReview":"V18.2 模型编辑复核","ipaUK":"sɪk liːv","ipaUS":"sɪk liːv","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Sick leave","exampleZh":"请按适用于员工工作所在地的政策登记病假。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we record sick leave under local policy?","zh":"按照当地政策，应该如何记录病假？"},"extension":{"en":"The sick leave policy explains when supporting documentation may be requested.","zh":"病假政策说明了哪些情况下可能需要提供证明材料。"}},{"id":"HR224","moduleId":"m8","module":"HR运营与数据分析","term":"Maternity leave","zh":"产假","definition":"与分娩相关的法定或公司休假安排。","example":"Maternity leave entitlements depend on local law and policy.","collocation":"maternity leave policy","dialogue":[{"role":"Employee","en":"The hospital moved my expected delivery date forward by two weeks.","zh":"医院把我的预产期提前了两周。"},{"role":"HR Adviser","en":"Send me the revised date, and we’ll check whether your planned maternity leave start date needs to change.","zh":"请把新的日期发给我，我们看看原定的产假开始日期是否需要调整。"}],"usage":"","new":false,"order":294,"aliases":[],"distinction":"Maternity leave（产假）通常与妊娠、分娩及产后恢复有关。parental leave（育儿假）侧重照顾子女，有些制度把它作为更广的父母休假类别。名称、资格和安排因地区而异。","collocationZh":"产假政策","collocationReview":"V18.2 模型编辑复核","ipaUK":"məˈtɜːnɪti liːv","ipaUS":"məˈtɝːnɪtiː liːv","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Maternity leave","exampleZh":"产假权益取决于当地法律和公司政策。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Are maternity leave entitlements the same in every country?","zh":"每个国家的产假权益都相同吗？"},"extension":{"en":"Use the maternity leave policy for the employee’s work location when reviewing a request.","zh":"审查申请时，请使用适用于该员工工作所在地的产假政策。"}},{"id":"HR225","moduleId":"m8","module":"HR运营与数据分析","term":"Paternity leave","zh":"陪产假","definition":"父亲或其他符合适用规定的非生育方在子女出生前后可享有的休假，资格、时长和待遇依地区及政策而异。","example":"The employee asked HR about paternity leave eligibility.","collocation":"paternity leave entitlement","dialogue":[{"role":"Employee","en":"Our baby is due next month. Can I split my time off into two blocks?","zh":"我们的孩子预计下个月出生。我能分两段休假吗？"},{"role":"HR Adviser","en":"I’ll check how the paternity leave policy at your site handles split dates.","zh":"我查一下你所在站点的陪产假政策，看看能否分段休。"}],"usage":"","new":false,"order":295,"aliases":[],"distinction":"Paternity leave（陪产假）通常面向父亲或符合当地规定的非生育方。parental leave（育儿假）覆盖照顾子女的更广泛需求。收养或不同家庭关系是否适用须看当地制度。","collocationZh":"陪产假待遇","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈtɜːnɪti liːv","ipaUS":"pəˈtɝːnɪtiː liːv","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Paternity leave","exampleZh":"该员工向人力资源部门询问陪产假申请资格。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What did the employee ask about paternity leave?","zh":"员工就陪产假询问了什么？"},"extension":{"en":"The paternity leave policy lists the documents employees may need to provide.","zh":"陪产假政策列出了员工可能需要提交的材料。"}},{"id":"HR226","moduleId":"m8","module":"HR运营与数据分析","term":"Shift scheduling","zh":"排班","definition":"规划轮班时间与人员覆盖。","example":"Shift scheduling must account for any applicable minimum rest periods.","collocation":"manage shift scheduling","dialogue":[{"role":"Shift Supervisor","en":"Can Ava cover Sunday morning if she closes Saturday night?","zh":"艾娃周六上完打烊班，周日早上还能来顶班吗？"},{"role":"Scheduling Coordinator","en":"I’ll check the required rest interval before changing the shift schedule.","zh":"我先核对适用的最短休息间隔，再改排班。"}],"usage":"","new":false,"order":296,"aliases":[],"distinction":"Shift scheduling（排班）预先安排班次和人员覆盖。attendance tracking（考勤记录）核对实际到岗。time sheet（工时表）记录实际投入的工时。","collocationZh":"负责排班","collocationReview":"V18.2 模型编辑复核","ipaUK":"ʃɪft ˈʃedjuːlɪŋ","ipaUS":"ʃɪft ˈskedʒʊlɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Shift scheduling","exampleZh":"排班时须遵守适用的最短休息时限。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What must we consider when creating shift schedules?","zh":"制定排班计划时必须考虑哪些因素？"},"extension":{"en":"The shift scheduling system flags unfilled shifts before the roster is published.","zh":"班表发布前，排班系统会标出还无人值守的班次。"}},{"id":"HR227","moduleId":"m8","module":"HR运营与数据分析","term":"Time sheet","zh":"工时表","definition":"用于记录工作时间或项目投入的表格。","example":"Please submit your time sheet before Friday.","collocation":"approve a time sheet","dialogue":[{"role":"Project Lead","en":"You logged six hours of client work on Wednesday. Did that include the internal training?","zh":"你周三记了六小时客户项目工时，里面算了内部培训的时间吗？"},{"role":"Analyst","en":"Yes. I’ll move the training hour to the internal code and resubmit my time sheet.","zh":"算进去了。我把那一小时改到内部项目代码下，再重新提交工时表。"}],"usage":"","new":false,"order":297,"aliases":[],"distinction":"Time sheet 或 timesheet（工时表）记录员工申报的实际工时，也可区分项目。shift roster（班表）记录预定班次。clock-in record（打卡记录）主要记录进出或上下班时间戳。","collocationZh":"审批工时表","collocationReview":"V18.2 模型编辑复核","ipaUK":"taɪm ʃiːt","ipaUS":"taɪm ʃiːt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Time sheet","exampleZh":"请在周五之前提交工时表。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When should team members submit their time sheets?","zh":"团队成员应在什么时候提交工时表？"},"extension":{"en":"Record travel time on the time sheet using the appropriate project code.","zh":"请在工时表里用相应的项目代码记录出行时间。"}},{"id":"HR228","moduleId":"m8","module":"HR运营与数据分析","term":"Data privacy","zh":"数据隐私","definition":"关于如何恰当收集、使用、共享和保留个人数据，以及如何尊重相关个人权利的要求与实践。","example":"Data privacy is essential when handling employee records.","collocation":"protect data privacy","dialogue":[{"role":"People Analyst","en":"The vendor template has a field for date of birth. We only need age bands for this report.","zh":"供应商的模板有出生日期字段，但这份报告只需要年龄段。"},{"role":"Privacy Adviser","en":"Remove the date of birth field to protect data privacy, and confirm the vendor can use age bands.","zh":"为保护数据隐私，删掉出生日期字段，再确认供应商能否使用年龄段。"}],"usage":"","new":false,"order":298,"aliases":[],"distinction":"Data privacy（数据隐私）关注个人数据的收集、使用、共享以及个人权利。data security（数据安全）关注防止未经授权的访问、篡改或泄露。访问控制可同时服务于两者。","collocationZh":"保护数据隐私","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈdeɪtə ˈprɪvəsi","ipaUS":"ˈdeɪtə ˈpraɪvəsiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Data privacy","exampleZh":"处理员工档案时，保护数据隐私至关重要。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Why is data privacy important for employee records?","zh":"为什么员工档案的数据隐私很重要？"},"extension":{"en":"A data privacy review should check whether each field is necessary for the stated purpose.","zh":"数据隐私审查应核对各字段对既定用途是否必要。"}},{"id":"HR229","moduleId":"m8","module":"HR运营与数据分析","term":"Access control","zh":"访问控制","definition":"按身份、角色或其他权限规则，决定谁可以访问系统或数据以及可以执行哪些操作。","example":"Access controls can restrict who is allowed to change salary data.","collocation":"role-based access control","dialogue":[{"role":"Payroll Lead","en":"The temporary analyst needs totals by department. She won’t be editing individual salaries.","zh":"临时分析员只需要各部门的汇总数据，不会修改个人薪资。"},{"role":"Systems Admin","en":"I’ll use role-based access control to give her read-only access to the totals.","zh":"我会通过基于角色的访问控制，只给她汇总数据的读取权限。"}],"usage":"","new":false,"order":299,"aliases":[],"distinction":"Access control（访问控制）决定谁可以对资源执行哪些操作。authentication（身份验证）确认访问者是谁。role-based access control 根据其获分配的角色授予权限。","collocationZh":"基于角色的访问控制","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈækses kənˈtrəʊl","ipaUS":"ˈækses kənˈtroʊl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Access control","exampleZh":"访问控制可以限制哪些人员有权修改薪资数据。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we prevent unauthorized access to salary data?","zh":"我们如何防止未经授权访问薪酬数据？"},"extension":{"en":"Review access controls when an employee moves to a different team.","zh":"员工调入其他团队时，应复核其访问权限。"}},{"id":"HR230","moduleId":"m8","module":"HR运营与数据分析","term":"HR audit","zh":"人力资源审计","definition":"依据适用法规、制度或其他既定标准，对人力资源流程、控制与记录进行检查和评价。","example":"The HR audit identified gaps in document retention.","collocation":"conduct an HR audit","dialogue":[{"role":"Auditor","en":"The policy calls for two approvals, but I can see only one on this sample.","zh":"制度要求两次审批，但这份样本只有一次的记录。"},{"role":"HR Operations Lead","en":"I’ll pull the workflow log and add it to the HR audit file so we can see what happened.","zh":"我去调取流程日志，放进人力资源审计档案，看看当时发生了什么。"}],"usage":"","new":false,"order":300,"aliases":[],"distinction":"HR audit（人力资源审计）依据既定标准收集证据、评价控制和流程。HR process review（人力资源流程复盘）常侧重效率或体验改进，两者都可以提出整改建议。","collocationZh":"开展人力资源审计","collocationReview":"V18.2 模型编辑复核","ipaUK":"eɪtʃ ɑː ˈɔːdɪt","ipaUS":"eɪtʃ ɑːr ˈɔːdɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"H R audit","exampleZh":"人力资源审计发现了文件留存方面的不足。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What issues did the HR audit identify?","zh":"HR 审计发现了哪些问题？"},"extension":{"en":"The HR audit sampled onboarding records from three business units.","zh":"这次人力资源审计抽查了三个业务部门的入职记录。"}},{"id":"HR231","moduleId":"m8","module":"HR运营与数据分析","term":"Compliance training","zh":"合规培训","definition":"帮助员工理解法规及内部要求的课程。","example":"Our policy requires employees who handle payments to complete this compliance training.","collocation":"complete compliance training","dialogue":[{"role":"Site Manager","en":"The contractors already completed their agency induction. Which of our courses do they still need?","zh":"承包商人员已经参加过派出机构的入场培训了。他们还需要上我们的哪些课程？"},{"role":"Compliance Lead","en":"I’ll check the compliance training matrix for this site and send you the modules that apply to their work.","zh":"我查一下这个站点的合规培训清单，再把适用于他们工作的课程发给你。"}],"usage":"","new":false,"order":301,"aliases":[],"distinction":"Compliance training（合规培训）围绕适用法规或内部规范。orientation（入职介绍）帮助新员工了解组织和工作环境，可以包含合规模块。completion record（完成记录）只反映培训完成情况。","collocationZh":"完成合规培训","collocationReview":"V18.2 模型编辑复核","ipaUK":"kəmˈplaɪəns ˈtreɪnɪŋ","ipaUS":"kəmˈplaɪəns ˈtreɪnɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Compliance training","exampleZh":"根据本公司的规定，经手付款的员工须完成这项合规培训。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who must complete compliance training?","zh":"哪些人必须完成合规培训？"},"extension":{"en":"Keep a completion record for each compliance training module assigned to the team.","zh":"团队被安排参加的每项合规培训，都应保留完成记录。"}},{"id":"HR232","moduleId":"m8","module":"HR运营与数据分析","term":"Headcount report","zh":"员工人数报告","definition":"汇总某一时点或期间的实际员工人数及变动，可按部门、地点等维度呈现，并视用途与已批准岗位数对照。","example":"The headcount report shows both actual employee counts and the number of approved positions.","collocation":"monthly headcount report","dialogue":[{"role":"Finance Partner","en":"Operations shows 86 people in the system, but the budget lists 90 positions.","zh":"系统显示运营部门有 86 人，但预算列了 90 个岗位。"},{"role":"People Analyst","en":"I’ll show the two figures side by side in the headcount report and confirm which positions are still vacant.","zh":"我会在员工人数报告中并列呈现这两个数字，再确认哪些岗位仍然空缺。"}],"usage":"","new":false,"order":302,"aliases":[],"distinction":"Headcount report（员工人数报告）主要汇总实际员工人数及变动。position report（岗位报告）统计岗位及其状态，可以包括空缺。FTE report（全职当量报告）按标准工时折算。","collocationZh":"月度员工人数报告","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈhedkaʊnt rɪˈpɔːt","ipaUS":"ˈhedkaʊnt riːˈpɔːrt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Headcount report","exampleZh":"员工人数报告同时列出实际员工人数和已批准岗位数。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What information does the headcount report contain?","zh":"人员编制报告包含哪些信息？"},"extension":{"en":"The headcount report shows the number of active employees as of month-end.","zh":"员工人数报告列出了截至月末在职的员工人数。"}},{"id":"HR233","moduleId":"m8","module":"HR运营与数据分析","term":"Attrition rate","zh":"员工流失率","definition":"特定统计期内离开组织的员工相对员工规模的比例；应明确是否包含自愿及非自愿离职及所用分母。","example":"Our employee attrition rate rose from 8% last year to 10% this year.","collocation":"calculate the attrition rate","dialogue":[{"role":"HR Director","en":"Why does the regional slide show a lower figure than ours?","zh":"为什么区域汇报材料上的数字比我们的低？"},{"role":"People Analyst","en":"Their attrition rate excludes involuntary departures. I’ll rerun ours on the same basis before comparing them.","zh":"他们的员工流失率不包含非自愿离职。我先按同一口径重新计算我们的数据，再做比较。"}],"usage":"常用于 HR 人力指标；与 turnover rate 口径可能接近，但应以企业指标字典为准。","new":false,"order":303,"distinction":"Attrition 是员工流失现象，attrition rate 是按指定期间和分母计算的流失率。turnover rate 在有些组织与其同义，有些组织则采用不同口径。和 retention rate（留任率）比较时，先核对统计人群与分母。","aliases":[],"collocationZh":"计算员工流失率","collocationReview":"V18.2 模型编辑复核","ipaUK":"əˈtrɪʃən reɪt","ipaUS":"əˈtrɪʃən reɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Attrition rate","exampleZh":"我们的员工流失率从去年的 8% 升至今年的 10%。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Our attrition rate increased in the customer support team.","zh":"客户支持团队的员工流失率上升了。"},"extension":{"en":"Use the same denominator when comparing the attrition rate across departments.","zh":"比较各部门的员工流失率时，应采用一致的分母口径。"}},{"id":"HR234","moduleId":"m8","module":"HR运营与数据分析","term":"Voluntary turnover","zh":"员工主动离职","definition":"员工自行提出并结束雇佣关系的离职。退休等特殊情形是否计入，视组织统计口径而定。","example":"The report tracks voluntary turnover by department and reason for leaving.","collocation":"monitor voluntary turnover","dialogue":[{"role":"HR Partner","en":"Two people left when the customer contract ended. Should I include those departures?","zh":"客户合同到期后有两人离开。这两笔离职要算进去吗？"},{"role":"People Analyst","en":"Check the recorded reasons first. Count them under voluntary turnover only if they chose to resign.","zh":"先核对记录的离职原因。只有他们是自己选择辞职的，才计入主动离职。"}],"usage":"如果指标是“主动离职率”，对应 voluntary turnover rate。","new":false,"order":304,"distinction":"Voluntary turnover（主动离职）指由员工发起的离职。voluntary turnover rate（主动离职率）是按约定分母计算的比率。involuntary turnover（非自愿离职）通常由雇主发起。退休等特殊情形依指标字典归类。","aliases":[],"collocationZh":"跟踪员工主动离职情况","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈvɒləntəri ˈtɜːnəʊvə","ipaUS":"ˈvɑːlənteriː ˈtɝːˌnoʊvɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Voluntary turnover","exampleZh":"报告按部门和离职原因跟踪员工主动离职情况。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What happened to voluntary turnover after the retention initiative?","zh":"实施留任举措后，员工主动离职情况有什么变化？"},"extension":{"en":"The exit report breaks down voluntary turnover by tenure at the time of departure.","zh":"离职报告按离职时的司龄分组统计主动离职情况。"}},{"id":"HR235","moduleId":"m8","module":"HR运营与数据分析","term":"Retention rate","zh":"留任率","definition":"在约定观察期内，基准人群中到期末仍在职的员工所占比例。需明确基准人群和统计时点。","example":"The retention rate is one indicator of workforce stability.","collocation":"improve the retention rate","dialogue":[{"role":"People Analyst","en":"Do you want everyone employed at quarter-end, or just the people who were here on day one?","zh":"你需要季末所有在职员工的数据，还是只看季度首日在职的员工？"},{"role":"HR Director","en":"Use the day-one group for this retention rate. We want to know how many of them were still here at quarter-end.","zh":"这次留任率按季度首日的那批员工算。我们想知道他们到季末还有多少人留任。"}],"usage":"","new":false,"order":305,"aliases":[],"distinction":"Retention rate（留任率）常跟踪期初或指定人群中到期末仍在职的比例。attrition rate（流失率）可能以期间平均人数为分母，且离职范围可能不同。两项指标的互补关系取决于口径。","collocationZh":"提高员工留任率","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˈtenʃən reɪt","ipaUS":"riːˈtenʃən reɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Retention rate","exampleZh":"员工留任率是衡量人员队伍稳定性的指标之一。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which metric could indicate how stable our workforce is?","zh":"哪个指标可以反映人员队伍的稳定程度？"},"extension":{"en":"We calculate the six-month retention rate for each group of new hires.","zh":"我们分别计算各批新员工的六个月留任率。"}},{"id":"HR236","moduleId":"m8","module":"HR运营与数据分析","term":"Absenteeism rate","zh":"员工缺勤率","definition":"某一期间内缺勤天数或工时占相应计划天数或工时的比例。需明确哪些缺勤纳入统计。","example":"The absenteeism rate should be interpreted alongside leave policies.","collocation":"track the absenteeism rate","dialogue":[{"role":"Warehouse Lead","en":"The outage closed the site for half a day. Did those missed hours end up in our absenteeism rate?","zh":"停电让站点关闭了半天，这些没上的工时也算进缺勤率了吗？"},{"role":"People Analyst","en":"They were coded separately. I’ll check whether the report excludes closure hours from the scheduled total.","zh":"系统用了单独代码。我去看看报表是否把停工时数从排班总时数里扣除了。"}],"usage":"可按缺勤工时、缺勤天数等口径统计。","new":false,"order":306,"distinction":"Absenteeism rate（缺勤率）按选定的缺勤天数或工时与对应的计划总量计算。leave utilization（休假使用情况）侧重各类假期的使用量或使用比例。比较之前应核对批准的休假是否计入缺勤。","aliases":[],"collocationZh":"跟踪员工缺勤率","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌæbsənˈtiːɪzəm reɪt","ipaUS":"ˌæbsənˈtiːɪzəm reɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Absenteeism rate","exampleZh":"解读缺勤率时，应结合休假政策考虑。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we interpret the absenteeism rate?","zh":"我们应如何解读员工缺勤率？"},"extension":{"en":"Compare the absenteeism rate by shift using the same definition of scheduled hours.","zh":"按班次比较缺勤率时，应统一计划工时的定义。"}},{"id":"HR237","moduleId":"m8","module":"HR运营与数据分析","term":"Cost per hire","zh":"人均招聘成本","definition":"按约定期间及费用范围，将内部和外部招聘费用合计除以录用人数得出的平均成本。","example":"Our cost per hire calculation includes recruiter time and agency fees.","collocation":"reduce cost per hire","dialogue":[{"role":"Recruiting Lead","en":"The agency invoice arrived after month-end. Which quarter gets the expense?","zh":"猎头公司的账单月底后才收到。这笔费用进哪个季度？"},{"role":"Finance Partner","en":"Let’s follow the agreed accounting period for cost per hire and reconcile the hiring count for that quarter.","zh":"按人均招聘成本约定的费用归属期间处理，再核对那个季度的录用人数。"}],"usage":"","new":false,"order":307,"aliases":[],"distinction":"Cost per hire（人均招聘成本）用纳入口径的招聘费用除以录用人数。recruiting spend（招聘支出）是总费用，受业务量影响。cost per applicant（每名申请者成本）以申请人数为分母。","collocationZh":"降低人均招聘成本","collocationReview":"V18.2 模型编辑复核","ipaUK":"kɒst pɜː ˈhaɪə","ipaUS":"kɑːst pɝː ˈhaɪɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Cost per hire","exampleZh":"我们计算人均招聘成本时，将招聘人员投入的工时成本和招聘机构服务费计入。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What costs are included in our cost-per-hire calculation?","zh":"单次招聘成本计算包含哪些费用？"},"extension":{"en":"Compare cost per hire across channels only after applying the same cost rules.","zh":"先统一费用归集规则，再比较各招聘渠道的人均招聘成本。"}},{"id":"HR238","moduleId":"m8","module":"HR运营与数据分析","term":"Time to productivity","zh":"达到预期产出所需时间","definition":"从入职或到岗等约定起点，到员工首次达到事先定义的岗位产出标准所需的时间。","example":"Better onboarding can shorten time to productivity.","collocation":"measure time to productivity","dialogue":[{"role":"Support Manager","en":"New hires can handle password resets by week two, but billing cases still need supervision.","zh":"新员工到第二周就能处理密码重置了，但处理账单问题还需要有人指导。"},{"role":"L&D Partner","en":"For time to productivity, let’s agree on which tasks count and what quality score they need to meet.","zh":"衡量达到预期产出所需的时间前，我们先确定哪些任务计入，以及质量分数要达到多少。"}],"usage":"","new":false,"order":308,"aliases":[],"distinction":"Time to productivity（达到预期产出所需时间）从约定起点计到达成岗位产出标准。time to fill（岗位填补用时）通常计算招聘启动到达成录用里程碑的时长。两者的起止点都需明确。","collocationZh":"衡量达到预期产出所需的时间","collocationReview":"V18.2 模型编辑复核","ipaUK":"taɪm tuː ˌprɒdəkˈtɪvɪti","ipaUS":"taɪm tuː ˌproʊdəkˈtɪvətiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Time to productivity","exampleZh":"改善入职支持可以缩短新员工达到预期产出所需的时间。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How can onboarding help new hires become productive sooner?","zh":"入职融入措施如何帮助新员工更快达到有效产出？"},"extension":{"en":"We measure time to productivity from the start date to the first week the employee meets the agreed quality target.","zh":"我们从员工入职日开始计时，到其首次达到约定质量目标的那一周为止，以此衡量达到预期产出所需的时间。"}},{"id":"HR239","moduleId":"m8","module":"HR运营与数据分析","term":"HR dashboard","zh":"人力资源看板","definition":"集中展示关键人事指标的可视化页面。","example":"The HR dashboard shows headcount and turnover trends.","collocation":"build an HR dashboard","dialogue":[{"role":"Regional Director","en":"Why is the turnover chart still showing last month’s data?","zh":"为什么离职率图表还在显示上个月的数据？"},{"role":"People Analyst","en":"We’re still waiting for the final payroll file. I’ll add the date of the latest available data to the HR dashboard.","zh":"我们还在等最终的薪资数据文件。我先在人力资源看板上标出目前数据截至哪一天。"}],"usage":"","new":false,"order":309,"aliases":[],"distinction":"HR dashboard（人力资源看板）汇集并呈现持续更新的指标。HR report（人力资源报告）常面向某一统计期或议题作说明。看板中的趋势仍需结合定义与数据更新日期解读。","collocationZh":"建立人力资源看板","collocationReview":"V18.2 模型编辑复核","ipaUK":"eɪtʃ ɑː ˈdæʃbɔːd","ipaUS":"eɪtʃ ɑːr ˈdæʃbɔːrd","ipaSource":"音素词典与英式语音规则推导","speakTerm":"H R dashboard","exampleZh":"人力资源看板展示员工人数和离职率的变化趋势。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which HR metrics can leaders see on the dashboard?","zh":"领导者可以在 HR 看板中看到哪些指标？"},"extension":{"en":"The HR dashboard lets managers filter headcount by work location.","zh":"经理可在人力资源看板上按工作地点筛选员工人数。"}},{"id":"HR240","moduleId":"m8","module":"HR运营与数据分析","term":"People analytics","zh":"人力数据分析","definition":"通过分析员工及组织相关数据，为人员管理和组织决策提供依据。","example":"People analytics helped us identify which onboarding steps were taking new hires the longest.","collocation":"use people analytics to inform decisions","dialogue":[{"role":"HR Partner","en":"Internal transfers are down. Could we look at where applications are getting stuck?","zh":"内部调动少了。能不能看看内部申请卡在哪个环节？"},{"role":"People Analyst","en":"Yes. We’ll use people analytics to compare applications, interviews, and approvals by department.","zh":"可以。我们会用人力数据分析，按部门比较申请、面试和审批各环节的数据。"}],"usage":"","new":false,"order":310,"aliases":[],"distinction":"People analytics（人力数据分析）围绕人员和组织问题分析数据。HR reporting（人力资源报告）侧重定期呈现指标。两者可共用数据，看见关联后仍需要证据验证成因。","collocationZh":"借助人力数据分析辅助决策","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈpiːpəl ˌænəˈlɪtɪks","ipaUS":"ˈpiːpəl ˌænəˈlɪtɪks","ipaSource":"音素词典与英式语音规则推导","speakTerm":"People analytics","exampleZh":"人力数据分析帮助我们找出哪些入职环节对新员工来说最耗时。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What can people analytics reveal about workforce patterns?","zh":"人力数据分析可以揭示哪些人员变化规律？"},"extension":{"en":"We used people analytics to compare promotion outcomes across job levels.","zh":"我们通过人力数据分析，对比了不同职级员工的晋升结果。"}},{"id":"HR8-31","moduleId":"m8","module":"HR运营与数据分析","term":"Full-time equivalent (FTE)","zh":"全职当量","definition":"将不同工时折算为标准全职工作量的指标。","example":"The workforce plan assumes 120 full-time equivalents.","collocation":"calculate full-time equivalents","dialogue":[{"role":"Clinic Manager","en":"We have four people on the weekend roster, but three work half shifts.","zh":"周末排了四个人，其中三个人只上半个班次。"},{"role":"Workforce Planner","en":"Show me their weekly hours. I’ll convert those to FTEs for the staffing plan.","zh":"把他们每周的工时给我，我换算成全职当量后纳入人员配置计划。"}],"usage":"示例：两位各工作 0.5 个全职工时的人员，合计约为 1.0 FTE；不等同于 Headcount。","new":true,"order":311,"aliases":[],"distinction":"FTE（全职当量）是工时折算单位。full-time employee 是全职员工这一用工身份。headcount（人数）按人计数。采用同一全职工时基准时，两位各半工时的员工合计为 1 FTE。","collocationZh":"计算全职当量（FTE）","collocationReview":"V18.2 模型编辑复核","ipaUK":"fʊl taɪm ɪˈkwɪvələnt","ipaUS":"fʊl taɪm ɪˈkwɪvələnt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Full-time equivalent","exampleZh":"人力规划按 120 个全职当量（FTE）编制。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How many FTEs are in our staffing plan?","zh":"我们的人员配置计划包含多少全职当量？"},"extension":{"en":"Two employees working 20 hours a week represent one FTE on a 40-hour standard.","zh":"以每周 40 小时为全职标准，两名每周各工作 20 小时的员工合计为 1 个全职当量。"}},{"id":"HR8-32","moduleId":"m8","module":"HR运营与数据分析","term":"Vacancy rate","zh":"岗位空缺率","definition":"在指定时点或报告期，空缺岗位占纳入统计的岗位总数的比例。需说明哪些岗位计入分子和分母。","example":"The vacancy rate is highest in customer operations.","collocation":"monitor the vacancy rate","dialogue":[{"role":"Finance Partner","en":"Are the frozen roles still showing up as vacancies in this report?","zh":"这份报告还把冻结招聘的岗位算作空缺吗？"},{"role":"Workforce Analyst","en":"They are in this view. I’ll add a note to the vacancy rate chart so readers know how frozen roles are treated.","zh":"这个视图里算进去了。我在岗位空缺率图上补个注，说明冻结岗位的处理方式。"}],"usage":"","new":true,"order":312,"aliases":[],"distinction":"Vacancy rate（岗位空缺率）通常以空缺岗位数除以纳入统计的岗位总数。open requisitions（未完成招聘申请）按申请计数，一单可对应多个岗位。冻结岗位和统计时点需明确。","collocationZh":"监控岗位空缺率","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈveɪkənsi reɪt","ipaUS":"ˈveɪkənsiː reɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Vacancy rate","exampleZh":"客户运营部门的职位空缺率最高。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which team has the highest vacancy rate?","zh":"哪个团队的岗位空缺率最高？"},"extension":{"en":"Calculate the vacancy rate for approved positions as of the last day of the month.","zh":"请以月末最后一天为时点，计算已核准岗位的空缺率。"}},{"id":"HR8-33","moduleId":"m8","module":"HR运营与数据分析","term":"Regrettable attrition","zh":"组织希望避免的人才流失","definition":"依据组织预先设定的保留标准，认定为原本希望留住的员工离职，例如具有关键技能的员工离开。","example":"We track regrettable attrition among employees with hard-to-replace skills.","collocation":"track regrettable attrition","dialogue":[{"role":"HR Partner","en":"We lost a certified technician, and there’s nobody qualified to take over that work.","zh":"一名持证技师离职了，现在没有具备资质的人能接手那项工作。"},{"role":"Talent Lead","en":"That may qualify as regrettable attrition under our criteria. Let’s document why before we code it.","zh":"按我们的标准，这可能属于不希望发生的人才流失。归类前先把理由记录下来。"}],"usage":"","new":true,"order":313,"aliases":[],"distinction":"Regrettable attrition（组织希望避免的人才流失）按离岗对组织的影响或保留意愿分类。voluntary turnover（主动离职）按离职发起方分类。相关标准可涉及关键技能或绩效，具体由组织定义。","collocationZh":"跟踪组织希望避免的人才流失","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˈɡretəbəl əˈtrɪʃən","ipaUS":"rɪˈɡretəbəl əˈtrɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Regrettable attrition","exampleZh":"我们跟踪具备难以替代技能的员工中，哪些离职属于组织希望避免的人才流失。","meaningReview":"HR场景校订","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Are we seeing more regrettable attrition this quarter?","zh":"本季度关键人才流失情况是否有所增加？"},"extension":{"en":"We review the criteria for regrettable attrition before comparing results across business units.","zh":"比较各业务部门的人才流失情况前，我们先核对哪些离职被认定为组织希望避免的流失。"}},{"id":"HR8-34","moduleId":"m8","module":"HR运营与数据分析","term":"Data governance","zh":"数据治理","definition":"为数据的定义、质量、访问和使用等建立规则，并明确管理责任和决策权限。","example":"HR data governance requires clear ownership of employee records.","collocation":"HR data governance framework","dialogue":[{"role":"HR Systems Lead","en":"The HR and finance systems show different department codes for the same team.","zh":"同一个团队在人力资源系统和财务系统里的部门编码不同。"},{"role":"Data Steward","en":"Let’s use our data governance process to name one owner and document who can approve changes.","zh":"按数据治理流程指定一个管理责任人，再记录谁有权批准变更。"}],"usage":"","new":true,"order":314,"aliases":[],"distinction":"Data governance（数据治理）为数据制定标准、责任和决策权限。data management（数据管理）把这些安排落实为采集、维护与归档等日常工作。data quality（数据质量）关注准确性等具体属性。","collocationZh":"人力资源数据治理框架","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈdeɪtə ˈɡʌvənəns","ipaUS":"ˈdeɪtə ˈɡʌvɚnəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Data governance","exampleZh":"人力资源数据治理需要明确员工数据的管理责任人。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who owns the employee data governance process?","zh":"谁负责人事数据治理流程？"},"extension":{"en":"Our HR data governance framework requires a review before employee data is shared with a new vendor.","zh":"根据我们的人力资源数据治理框架，向新供应商共享员工数据前须开展审查。"}},{"id":"HR8-35","moduleId":"m8","module":"HR运营与数据分析","term":"Data retention policy","zh":"数据保留政策","definition":"规定不同类别数据的保留原则、期限和到期处置方式，并说明何时需要暂停处置的政策。","example":"The data retention policy specifies when records should be deleted or archived.","collocation":"data retention schedule","dialogue":[{"role":"Records Coordinator","en":"These files have reached the usual deletion date, but Legal flagged one case for preservation.","zh":"这些档案已到常规删除日期，但法务标记了其中一个案件，要求保留相关文件。"},{"role":"Privacy Adviser","en":"Pause deletion for the flagged files and check the data retention policy for the rest.","zh":"对标记过的档案暂停删除，其余档案按数据保留政策核对处理。"}],"usage":"","new":true,"order":315,"aliases":[],"distinction":"Data retention policy（数据保留政策）规定保存、暂停处置和到期处理原则。retention schedule（保留期限表）列出各类记录的起算点和期限。legal hold（法律保全指令）可能暂停相关记录的常规处置。","collocationZh":"数据保留期限表","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈdeɪtə rɪˈtenʃən ˈpɒlɪsi","ipaUS":"ˈdeɪtə riːˈtenʃən ˈpɑːləsiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Data retention policy","exampleZh":"数据保留政策规定了何时应删除或归档记录。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When should personnel records be deleted under our policy?","zh":"根据公司政策，员工档案应在何时删除？"},"extension":{"en":"The data retention policy sets different schedules for applicant files and employee files.","zh":"数据保留政策为候选人档案和员工档案设定了不同的保留期限。"}},{"id":"HR8-36","moduleId":"m8","module":"HR运营与数据分析","term":"Workforce analytics","zh":"员工队伍分析","definition":"分析人员规模、能力构成、工时、成本和流动趋势等信息，以支持人员配置和规划。","example":"Workforce analytics helps us forecast staffing needs.","collocation":"use workforce analytics for staffing forecasts","dialogue":[{"role":"Operations Director","en":"Can we staff the evening shift without bringing in agency workers?","zh":"晚班能不能在不用外部派遣人员的情况下排得开？"},{"role":"Workforce Analyst","en":"I’ll use workforce analytics to see what the current team can cover after training and approved leave are accounted for.","zh":"我用员工队伍分析看看，把培训和已批准的休假都考虑进去后，现有团队能覆盖哪些班次。"}],"usage":"","new":true,"order":316,"aliases":[],"distinction":"Workforce analytics（员工队伍分析）在规划语境中常聚焦队伍规模、技能组合、工时和成本。people analytics（人力数据分析）还常用于分析员工体验或发展。两者的命名和范围可因组织而重叠。","collocationZh":"利用员工队伍分析预测用人需求","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈwɜːk.fɔːs ˌænəˈlɪtɪks","ipaUS":"ˈwɝːk.fɔːrs ˌænəˈlɪtɪks","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Workforce analytics","exampleZh":"员工队伍分析帮助我们预测人员配置需求。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can workforce analytics help predict seasonal demand?","zh":"人力分析能否帮助预测季节性人员需求？"},"extension":{"en":"Workforce analytics helped us estimate how much overtime the new schedule would require.","zh":"员工队伍分析帮助我们估算新班表需要增加多少加班工时。"}},{"id":"HR8-37","moduleId":"m8","module":"HR运营与数据分析","term":"People metrics","zh":"人力资源指标","definition":"用于衡量员工和组织情况的各类指标。","example":"We agreed on consistent definitions for our people metrics.","collocation":"standardize people metrics","dialogue":[{"role":"HR Partner","en":"One team counts rehires as new hires, and another leaves them out.","zh":"一个团队把返聘员工算作新员工，另一个团队没有算进去。"},{"role":"People Analyst","en":"Let’s agree on the definition and update the people metrics guide before the next reporting cycle.","zh":"我们先把定义定下来，在下个报告周期前更新人力资源指标指南。"}],"usage":"","new":true,"order":317,"aliases":[],"distinction":"People metrics（人力资源指标）是如留任率、人数等有确定口径的度量。people analytics（人力数据分析）用这些度量回答问题。只有被选来衡量关键目标的指标才是 KPI。","collocationZh":"统一人力资源指标的口径","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈpiːpəl ˈmetrɪks","ipaUS":"ˈpiːpəl ˈmetrɪks","ipaSource":"音素词典与英式语音规则推导","speakTerm":"People metrics","exampleZh":"我们就各项人力资源指标的统一定义达成了共识。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which people metrics should the board review?","zh":"董事会应该关注哪些人力指标？"},"extension":{"en":"Document the source and reporting period for each people metric.","zh":"请记录每项人力资源指标的数据来源和统计期间。"}},{"id":"HR8-38","moduleId":"m8","module":"HR运营与数据分析","term":"Data dictionary","zh":"数据字典","definition":"记录数据字段的含义、类型、来源、允许取值等信息的文档，也可包含指标口径。","example":"The data dictionary defines which employment statuses count as active.","collocation":"maintain a data dictionary","dialogue":[{"role":"HR Analyst","en":"Is the termination date in the export the last day worked or the end of employment?","zh":"导出表里的离职日期指最后实际工作日，还是雇佣关系终止日？"},{"role":"Data Steward","en":"The data dictionary says it’s the end of employment. The last day worked is a separate field.","zh":"数据字典里写的是雇佣关系终止日。最后实际工作日另有一个字段。"}],"usage":"","new":true,"order":318,"aliases":[],"distinction":"Data dictionary（数据字典）说明字段含义、类型、允许取值及来源。metrics dictionary（指标字典）侧重分子、分母、过滤条件和报告周期。组织也可将两类说明合并维护。","collocationZh":"维护数据字典","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈdeɪtə ˈdɪkʃənəri","ipaUS":"ˈdeɪtə ˈdɪkʃəˌneriː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Data dictionary","exampleZh":"数据字典明确了哪些雇佣状态归为在职。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Where can I find the definition of active headcount?","zh":"哪里可以找到“在岗人数”的定义？"},"extension":{"en":"Update the data dictionary when a field gains a new allowed value.","zh":"字段新增允许取值时，请更新数据字典。"}},{"id":"HR8-39","moduleId":"m8","module":"HR运营与数据分析","term":"HR service ticket","zh":"人力资源服务工单","definition":"记录人力资源服务请求及其进度、沟通和处理结果的单条记录。","example":"The team resolved the HR service ticket within the agreed resolution time.","collocation":"resolve an HR service ticket","dialogue":[{"role":"Employee","en":"I’ve uploaded the receipt again. Should I open a new ticket?","zh":"我重新上传了收据，需要再开一张工单吗？"},{"role":"HR Service Agent","en":"Please add it to your existing HR service ticket. That keeps the receipt and the earlier replies together.","zh":"请把它补到原来的人力资源服务工单里，这样收据和之前的回复能放在一起。"}],"usage":"","new":true,"order":319,"aliases":[],"distinction":"HR service ticket（人力资源服务工单）是一项请求及其处理记录。case management（工单管理）是处理这些请求的流程。service level agreement（服务级别协议）可以为响应或办结设定目标。","collocationZh":"处理并办结人力资源服务工单","collocationReview":"V18.2 模型编辑复核","ipaUK":"eɪtʃ ɑː ˈsɜːvɪs ˈtɪkɪt","ipaUS":"eɪtʃ ɑːr ˈsɝːvəs ˈtɪkət","ipaSource":"音素词典与英式语音规则推导","speakTerm":"H R service ticket","exampleZh":"团队在人力资源服务约定的办结时限内处理完了这张工单。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Has the payroll service ticket been resolved?","zh":"工资发放相关的 HR 服务工单解决了吗？"},"extension":{"en":"Include the pay period when opening an HR service ticket about a payslip.","zh":"如果工资单有疑问，提交人力资源服务工单时请注明对应的薪资周期。"}},{"id":"HR8-40","moduleId":"m8","module":"HR运营与数据分析","term":"Predictive analytics","zh":"预测分析","definition":"利用已有数据和统计或机器学习方法估计未来可能发生的结果。","example":"Before using predictive analytics in HR, assess how well the model performs overall and across relevant groups.","collocation":"predictive analytics in HR","dialogue":[{"role":"People Analyst","en":"The forecast looks good overall, but it missed last quarter’s demand at two regional sites.","zh":"整体预测看起来还行，可上季度有两个区域站点的需求没预测准。"},{"role":"Workforce Lead","en":"Before we use predictive analytics for staffing, let’s check the forecast errors by site and shift.","zh":"把预测分析用于人员配置前，先按站点和班次核查预测误差。"}],"usage":"","new":true,"order":320,"aliases":[],"distinction":"Predictive analytics（预测分析）估计未来可能的结果。descriptive analytics（描述性分析）总结已经发生的情况。prescriptive analytics（处方性分析）进一步比较或推荐行动。预测结果应结合误差和适用范围解读。","collocationZh":"人力资源预测分析","collocationReview":"V18.2 模型编辑复核","ipaUK":"prɪˈdɪktɪv ˌænəˈlɪtɪks","ipaUS":"prɪˈdɪktɪv ˌænəˈlɪtɪks","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Predictive analytics","exampleZh":"将预测分析用于人力资源决策前，应评估模型的整体表现，以及它在相关群体中的表现。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will we validate this predictive model before use?","zh":"在使用预测模型之前，我们如何验证其有效性？"},"extension":{"en":"Test the predictive analytics model on a later period that was held out of training.","zh":"请用训练时未纳入的后续一段时期的数据测试预测模型。"}},{"id":"HR9-01","moduleId":"m9","module":"海外派遣与全球流动","term":"Global mobility","zh":"全球人才流动","definition":"管理员工跨境工作或调动的实践，可涵盖国际派遣、长期调动、跨境远程工作等安排。","example":"Our global mobility policy covers international assignments.","collocation":"global mobility program","dialogue":[{"role":"Engineering Lead","en":"We need someone in the regional office for the launch. It could take three weeks or three months.","zh":"上线期间我们需要有人去区域办公室，可能要三周，也可能要三个月。"},{"role":"HR Partner","en":"Let’s bring in global mobility before we commit to dates. They can help us choose the right arrangement.","zh":"先请全球人才流动团队参与，再确定日期。他们可以帮我们选合适的安排。"}],"usage":"","new":true,"order":321,"aliases":[],"distinction":"Global mobility（全球人才流动）管理跨境派遣、调动或其他跨境工作安排。international assignment（国际派遣）是其中一种用工安排。international recruitment（国际招聘）侧重跨境寻聘人才。","collocationZh":"全球人才流动计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈɡləʊbəl məʊˈbɪlɪti","ipaUS":"ˈɡloʊbəl moʊˈbɪlətiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Global mobility","exampleZh":"我们的全球人才流动政策涵盖国际派遣。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who manages global mobility for the Asia-Pacific region?","zh":"谁负责亚太地区的全球人才流动事务？"},"extension":{"en":"Involve global mobility when planning a cross-border internal transfer.","zh":"规划跨境内部调动时，请让全球人才流动团队参与。"}},{"id":"HR9-02","moduleId":"m9","module":"海外派遣与全球流动","term":"International assignment","zh":"国际派遣","definition":"组织安排员工在一定期限内赴另一国家或地区执行工作任务。","example":"The international assignment will last eighteen months.","collocation":"long-term international assignment","dialogue":[{"role":"Regional Lead","en":"The local team can run the launch, but they need someone on site to train the new supervisors.","zh":"当地团队能负责上线，但需要有人到现场培训新任主管。"},{"role":"Mobility Adviser","en":"A short-term international assignment might fit. Send me the proposed duties and dates.","zh":"短期国际派遣可能合适。把拟定的工作职责和日期发给我。"}],"usage":"","new":true,"order":322,"aliases":[],"distinction":"International assignment（国际派遣）通常指在约定期限内赴另一国家或地区履职。permanent transfer（永久调动）通常指不设预定返回日期的长期转移。business trip（商务出差）通常围绕短期商务活动。分类应结合实际工作内容和当地规则。","collocationZh":"长期国际派遣","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɪntəˈnæʃənəl əˈsaɪnmənt","ipaUS":"ˌɪntɚˈnæʃənəl əˈsaɪnmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"International assignment","exampleZh":"此次国际派遣将持续18个月。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How long will the international assignment last?","zh":"这次国际派遣会持续多久？"},"extension":{"en":"The international assignment starts after the local team takes over customer support.","zh":"当地团队接手客户支持工作后，这次国际派遣就会开始。"}},{"id":"HR9-03","moduleId":"m9","module":"海外派遣与全球流动","term":"Expatriate","zh":"外派员工","definition":"在企业全球流动语境中，指被派往境外生活和工作的员工。","example":"The expatriate will receive relocation support.","collocation":"expatriate employee","dialogue":[{"role":"Host HR Manager","en":"Marco starts on Monday. Is he joining us on a local contract?","zh":"马尔科周一到岗。他会和我们签当地合同吗？"},{"role":"Mobility Coordinator","en":"He’s coming as an expatriate on a two-year assignment. I’ll send you the terms we agreed for his placement.","zh":"他是来做两年派遣的外派员工。我把这次派驻约定的条件发给你。"}],"usage":"","new":true,"order":323,"aliases":[],"distinction":"Expatriate（外派员工）在企业流动语境中常指在派驻地生活并工作的员工，在一般英语中也可泛指居住在国外的人。assignee（受派员工）强调接受特定派遣这一身份。","collocationZh":"海外派遣员工","collocationReview":"V18.2 模型编辑复核","ipaUK":"ekˈspæt.ri.ət","ipaUS":"ekˈspeɪ.tri.ət","ipaSource":"https://dictionary.cambridge.org/dictionary/english/expatriate","speakTerm":"Expatriate","exampleZh":"该外派员工将获得搬迁支持。","ipaReview":"完整词头英美音标文本核对","ipaNote":"英美音标据 Cambridge 发音词头核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What support is available to the expatriate?","zh":"外派员工可以获得哪些支持？"},"extension":{"en":"The expatriate kept a mentor in the home office throughout the assignment.","zh":"在整个派驻期间，这位外派员工一直与派出机构的导师保持联系。"}},{"id":"HR9-04","moduleId":"m9","module":"海外派遣与全球流动","term":"Host country","zh":"派驻国","definition":"员工被派往工作的国家。","example":"The host-country HR team will help with local onboarding.","collocation":"host-country requirements","dialogue":[{"role":"Mobility Coordinator","en":"The employee already has an ID from our head office. Can she use it on her first day abroad?","zh":"这位员工已经有总部的工牌，到境外上班第一天可以用这张吗？"},{"role":"Local HR Adviser","en":"She’ll need a site badge in the host country. I can arrange one once I have her start date.","zh":"她在派驻国需要当地办公地点的门禁卡。你告诉我到岗日期，我就能安排。"}],"usage":"","new":true,"order":324,"aliases":[],"distinction":"Host country（派驻国）是员工赴任的国家。home country（派出国）是该次派遣认定的来源国。两者是派遣管理用语，签证或税务分析还须看相应法律身份。","collocationZh":"派驻国的要求","collocationReview":"V18.2 模型编辑复核","ipaUK":"həʊst ˈkʌntri","ipaUS":"hoʊst ˈkʌntriː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Host country","exampleZh":"派驻国的人力资源团队将协助办理当地的入职手续。","meaningReview":"HR场景校订","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which host-country rules apply to this assignment?","zh":"本次派遣适用哪些派驻国规定？"},"extension":{"en":"The host-country office will provide a local emergency contact before the employee arrives.","zh":"派驻国的办公室会在员工抵达前提供一位当地紧急联系人。"}},{"id":"HR9-05","moduleId":"m9","module":"海外派遣与全球流动","term":"Home country","zh":"派出国","definition":"全球流动政策为某次派遣确定的来源国，通常依据派遣前的工作地或雇佣关系认定。","example":"The home-country HR team will retain the employee’s personnel file under our records policy.","collocation":"home-country payroll","dialogue":[{"role":"Mobility Adviser","en":"Ravi’s passport was issued in India, but he transferred from our Singapore team.","zh":"拉维的护照由印度签发，但他是从我们新加坡团队调过来的。"},{"role":"Payroll Lead","en":"For this assignment, our policy treats Singapore as the home country. I’ll use that for the home payroll review.","zh":"按我们针对这次派遣的政策，新加坡是派出国。我会按这个口径审核派出国的薪资安排。"}],"usage":"","new":true,"order":325,"aliases":[],"distinction":"Home country（派出国）在派遣管理中通常按派遣前的工作或雇佣基准确定。country of citizenship（国籍国）以国籍确定。host country（派驻国）是赴任地。","collocationZh":"派出国薪资发放","collocationReview":"V18.2 模型编辑复核","ipaUK":"həʊm ˈkʌntri","ipaUS":"hoʊm ˈkʌntriː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Home country","exampleZh":"根据我们的档案政策，派出国的人力资源团队将继续保管该员工的人事档案。","meaningReview":"HR场景校订","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Will the employee stay on home-country payroll?","zh":"员工是否继续通过派出国薪资体系发薪？"},"extension":{"en":"The home-country HR team confirmed which benefits would continue during the assignment.","zh":"派出国的人力资源团队确认了哪些福利将在派遣期间继续提供。"}},{"id":"HR9-06","moduleId":"m9","module":"海外派遣与全球流动","term":"Assignment letter","zh":"外派函","definition":"载明派遣地点、期限、职责、薪酬福利及其他约定的书面文件。","example":"HR is preparing the assignment letter for approval.","collocation":"international assignment letter","dialogue":[{"role":"Employee","en":"The draft says I’ll report to the regional director, but my manager mentioned the country lead.","zh":"草稿写我向区域总监汇报，但我经理说的是派驻国负责人。"},{"role":"Mobility Adviser","en":"I’ll confirm the reporting line with both teams and update the assignment letter before we ask you to sign.","zh":"我会和两边的团队确认汇报关系，并在请你签字前更新外派函。"}],"usage":"","new":true,"order":326,"aliases":[],"distinction":"Assignment letter（外派函）记录外派期限、职责及适用待遇等安排。employment contract（雇佣合同）约定雇佣关系及条件。外派函是否补充或变更合同条款要看文本和适用规则。","collocationZh":"国际派遣函","collocationReview":"V18.2 模型编辑复核","ipaUK":"əˈsaɪnmənt ˈletə","ipaUS":"əˈsaɪnmənt ˈletɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Assignment letter","exampleZh":"人力资源部门正在准备外派函并将提交审批。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When will the assignment letter be ready?","zh":"派遣函什么时候准备好？"},"extension":{"en":"The assignment letter specifies who will cover the return trip.","zh":"外派函写明了返程费用由谁承担。"}},{"id":"HR9-07","moduleId":"m9","module":"海外派遣与全球流动","term":"Assignment allowance","zh":"外派津贴","definition":"根据外派安排额外发放的津贴，发放目的、金额及期限由适用政策或约定确定。","example":"The assignment allowance is outlined in the mobility policy.","collocation":"assignment allowance policy","dialogue":[{"role":"Employee","en":"My first payslip overseas shows only my base salary. Is the assignment allowance paid separately?","zh":"我到境外后的第一张工资单上只有基本工资。外派津贴是另发的吗？"},{"role":"Payroll Adviser","en":"Let me check your assignment letter and the payroll cut-off. The allowance may be scheduled for the next run.","zh":"我核对一下你的外派函和薪资结算截止日期。这笔津贴可能排到了下一轮发放。"}],"usage":"","new":true,"order":327,"aliases":[],"distinction":"Assignment allowance（外派津贴）是因外派安排发放的额外款项，具体含义随政策而定。COLA（生活成本补贴）着眼于生活成本差额。expense reimbursement（费用报销）通常根据符合条件的实际支出办理。","collocationZh":"外派津贴政策","collocationReview":"V18.2 模型编辑复核","ipaUK":"əˈsaɪnmənt əˈlaʊəns","ipaUS":"əˈsaɪnmənt əˈlaʊəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Assignment allowance","exampleZh":"外派津贴的具体规定载于全球流动政策。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Is an assignment allowance included in this package?","zh":"这项派遣待遇方案包含派遣津贴吗？"},"extension":{"en":"The assignment allowance ends when the employee moves onto local terms under this policy.","zh":"按这项政策，员工转为当地雇佣待遇后，外派津贴就会停止发放。"}},{"id":"HR9-08","moduleId":"m9","module":"海外派遣与全球流动","term":"Cost-of-living allowance (COLA)","zh":"生活成本补贴","definition":"在外派薪酬语境中，为补偿派驻地与政策基准地之间纳入口径的生活成本差额而设的补贴。","example":"A cost-of-living allowance may be available if the host location is more expensive under the policy’s calculation.","collocation":"calculate the cost-of-living allowance","dialogue":[{"role":"Assignee","en":"My rent went up. Does that mean my cost-of-living allowance will change?","zh":"我的房租涨了，生活成本补贴会跟着调整吗？"},{"role":"Mobility Adviser","en":"This policy reviews housing separately. I’ll check which prices are included in the COLA calculation.","zh":"这项政策单独核算住房费用。我查一下计算生活成本补贴时纳入了哪些价格。"}],"usage":"","new":true,"order":328,"aliases":[],"distinction":"外派语境中的 COLA（生活成本补贴）通常参考两地的一篮子日常开支。housing allowance（住房津贴）针对住房支出。住房是否计入生活成本补贴的测算，须看具体政策。","collocationZh":"计算生活成本补贴","collocationReview":"V18.2 模型编辑复核","ipaUK":"kɒst ɒv ˈlɪvɪŋ əˈlaʊəns","ipaUS":"kɑːst ʌv ˈlɪvɪŋ əˈlaʊəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Cost-of-living allowance","exampleZh":"如果按政策测算的派驻地生活成本更高，员工可能符合领取生活成本补贴的条件。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Is the employee eligible for a cost-of-living allowance?","zh":"这名员工符合领取生活成本补贴的条件吗？"},"extension":{"en":"Our policy recalculates the cost-of-living allowance when it updates its price and exchange-rate data.","zh":"我们的政策规定，更新物价和汇率数据时会重新计算生活成本补贴。"}},{"id":"HR9-09","moduleId":"m9","module":"海外派遣与全球流动","term":"Housing allowance","zh":"住房津贴","definition":"按外派政策或约定，补助员工在派驻地符合条件的住房支出的津贴。","example":"The housing allowance is subject to the approved cap.","collocation":"monthly housing allowance","dialogue":[{"role":"Assignee","en":"I found a flat within the budget, but the landlord bills utilities separately.","zh":"我找到了一套预算内的公寓，但房东会单独收取水电等费用。"},{"role":"Mobility Adviser","en":"Send me the draft lease. I’ll check whether our housing allowance covers any of those charges.","zh":"把租约草稿发给我吧，我看看我们的住房津贴能不能支付其中一些费用。"}],"usage":"","new":true,"order":329,"aliases":[],"distinction":"Housing allowance（住房津贴）用于补助住房支出，可以按定额或政策标准发放。housing reimbursement（住房费用报销）通常按合规凭证核销。temporary accommodation（临时住宿）常用于过渡期。","collocationZh":"每月住房津贴","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈhaʊzɪŋ əˈlaʊəns","ipaUS":"ˈhaʊzɪŋ əˈlaʊəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Housing allowance","exampleZh":"住房津贴不得超过核准的上限。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the housing allowance limit in this city?","zh":"这个城市的住房津贴上限是多少？"},"extension":{"en":"The housing allowance starts on the lease date under this assignment policy.","zh":"根据这项外派政策，住房津贴从租约起始日开始计算。"}},{"id":"HR9-10","moduleId":"m9","module":"海外派遣与全球流动","term":"Relocation assistance","zh":"搬迁支持","definition":"协助员工搬迁及落脚的支持，可包括搬家服务、过渡住宿、费用报销或津贴。","example":"Our relocation assistance covers shipment of household goods and temporary accommodation.","collocation":"relocation assistance package","dialogue":[{"role":"Employee","en":"We won’t have our furniture for the first month. Is there any help with somewhere to stay?","zh":"头一个月我们的家具还运不到，住宿方面能有些支持吗？"},{"role":"Relocation Coordinator","en":"Your relocation assistance package includes temporary accommodation. I’ll send you the booking options.","zh":"你的搬迁支持方案包含临时住宿，我会把可以预订的选项发给你。"}],"usage":"","new":true,"order":330,"aliases":[],"distinction":"Relocation assistance（搬迁支持）可包括服务、报销或津贴，帮助员工搬家和落脚。relocation allowance（搬迁津贴）是其中一个现金给付选项。destination services（目的地安置服务）侧重派驻地的安家事务。","collocationZh":"搬迁支持方案","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪləʊˈkeɪʃən əˈsɪstəns","ipaUS":"ˌriːˈloʊˈkeɪʃən əˈsɪstəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Relocation assistance","exampleZh":"我们的搬迁支持包括运输家庭物品和提供临时住宿。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What relocation assistance can we provide?","zh":"我们可以提供哪些搬迁支持？"},"extension":{"en":"Confirm which moving expenses are covered before booking services under the relocation assistance package.","zh":"根据搬迁支持方案预订服务前，请先确认哪些搬家费用在支持范围内。"}},{"id":"HR9-11","moduleId":"m9","module":"海外派遣与全球流动","term":"Work permit","zh":"工作许可","definition":"按目的地制度取得的工作授权，可对雇主、岗位、工作活动或期限设限。","example":"If a work permit is required, check its effective date before the employee starts work.","collocation":"apply for a work permit","dialogue":[{"role":"Hiring Manager","en":"Can we schedule hands-on training for the day after she arrives?","zh":"能把实操培训安排在她抵达后的第二天吗？"},{"role":"Immigration Adviser","en":"Send me the training agenda. I’ll check whether the activities are permitted before her work permit takes effect.","zh":"把培训安排发给我，我查一下在她的工作许可生效前能否参加这些活动。"}],"usage":"","new":true,"order":331,"aliases":[],"distinction":"Work permit（工作许可）侧重获得在当地从事特定或允许范围内工作的授权。employment visa（工作签证）是就业相关的签证类别。签证可否同时赋予工作权、是否另办许可，依目的地制度而定。","collocationZh":"申请工作许可","collocationReview":"V18.2 模型编辑复核","ipaUK":"wɜːk ˈpɜː.mɪt","ipaUS":"wɝːk ˈpɝː.mɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Work permit","exampleZh":"如需办理工作许可，应在员工开始工作前核对许可的生效日期。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Has the employee's work permit been approved?","zh":"员工的工作许可获批了吗？"},"extension":{"en":"Check for any employer or job restrictions in the work permit before requesting a transfer.","zh":"申请调动前，请核对工作许可是否对雇主或岗位有限制。"}},{"id":"HR9-12","moduleId":"m9","module":"海外派遣与全球流动","term":"Employment visa","zh":"工作签证","definition":"用于就业目的的签证类别，其允许的入境、停留及工作活动取决于目的地制度与获批条件。","example":"The supporting documents for an employment visa vary by destination and visa category.","collocation":"employment visa application","dialogue":[{"role":"Employee","en":"The approval email arrived this morning. Can I book a nonrefundable flight now?","zh":"批准邮件今天早上收到了。我现在可以买不可退款的机票吗？"},{"role":"Immigration Coordinator","en":"Let me check what that notice covers and when you can enter on the employment visa.","zh":"我先看看这份通知批准了什么，再确认你何时能持工作签证入境。"}],"usage":"","new":true,"order":332,"aliases":[],"distinction":"Employment visa（工作签证）通常指与就业目的相关的入境或停留凭证。work permit（工作许可）侧重工作授权。同一签证或身份能否兼具这些效力，取决于目的地制度及获批条件。","collocationZh":"工作签证申请","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.mənt ˈviːzə","ipaUS":"ɪmˈplɔɪ.mənt ˈviːzə","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employment visa","exampleZh":"工作签证所需的证明材料因目的地和签证类别而异。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What documents are needed for the employment visa?","zh":"申请工作签证需要哪些材料？"},"extension":{"en":"Keep a copy of the employment visa application submitted for the new role.","zh":"请留存为新岗位提交的工作签证申请副本。"}},{"id":"HR9-13","moduleId":"m9","module":"海外派遣与全球流动","term":"Immigration compliance","zh":"移民合规","definition":"在跨境工作场景中，遵守目的地适用的入境、停留、居留和工作授权等要求。","example":"Our immigration compliance review covers the activities planned for each destination.","collocation":"immigration compliance review","dialogue":[{"role":"Sales Director","en":"The visit has changed. We’re now planning to install the demo equipment at the client’s office.","zh":"行程变了，我们现在打算到客户办公室安装演示设备。"},{"role":"Immigration Adviser","en":"Send me the revised itinerary. The immigration compliance review needs to cover the installation work too.","zh":"把更新后的行程发我。移民合规审查也得把安装工作考虑进去。"}],"usage":"","new":true,"order":333,"aliases":[],"distinction":"Immigration compliance（移民合规）关注入境、停留和工作授权等要求。tax compliance（税务合规）关注纳税和申报义务。同一次派遣可以同时涉及这两个领域。","collocationZh":"移民合规审查","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɪmɪˈɡreɪʃən kəmˈplaɪəns","ipaUS":"ˌɪməˈɡreɪʃən kəmˈplaɪəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Immigration compliance","exampleZh":"我们的移民合规审查涵盖计划在各目的地开展的活动。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who is responsible for immigration compliance?","zh":"谁负责移民事务合规？"},"extension":{"en":"Update the immigration compliance review if duties or work locations change.","zh":"工作职责或地点发生变化时，请更新移民合规审查。"}},{"id":"HR9-14","moduleId":"m9","module":"海外派遣与全球流动","term":"Tax equalization","zh":"税负平衡","definition":"按公司外派政策，将员工应负担的约定范围内税款与假设留在基准地应承担的税负对齐的安排。","example":"Tax equalization is explained in the assignment policy.","collocation":"tax equalization policy","dialogue":[{"role":"Assignee","en":"My host-country tax bill came in higher than projected. Who should I send it to?","zh":"派驻国的税单比预计金额高。我应该发给谁？"},{"role":"Mobility Tax Adviser","en":"Send it to the mobility tax team. We’ll check which items the tax equalization policy covers before the year-end settlement.","zh":"发给全球流动税务团队吧。年终结算前，我们会核对哪些项目属于税负平衡政策的覆盖范围。"}],"usage":"税负平衡不等于免税；不同公司的 hypothetical tax、返还和结算规则不同。","new":true,"order":334,"aliases":[],"distinction":"Tax equalization（税负平衡）通常按假设留在派出地的税负基准进行结算，可双向调整。tax protection（税负保护）通常只对超出政策基准的合格税负提供保护。适用收入、计算及结算以政策为准。","collocationZh":"税负平衡政策","collocationReview":"V18.2 模型编辑复核","ipaUK":"tæks ˌiːkwəlaɪˈzeɪʃən","ipaUS":"tæks ˌiːkwəlɪˈzeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Tax equalization","exampleZh":"税负平衡安排在外派政策中作了说明。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Does our assignment policy include tax equalization?","zh":"我们的派遣政策包含税负平衡安排吗？"},"extension":{"en":"Check whether a promotion changes the baseline used for tax equalization.","zh":"请核对晋升是否会改变税负平衡采用的税负基准。"}},{"id":"HR9-15","moduleId":"m9","module":"海外派遣与全球流动","term":"Hypothetical tax","zh":"假设税额","definition":"税负平衡下，以员工留在政策基准地为假设，对政策涵盖的收入测算的税额。","example":"Under our tax equalization policy, payroll deducts hypothetical tax each month.","collocation":"hypothetical tax calculation","dialogue":[{"role":"Assignee","en":"Why is there a hypothetical tax line on my payslip when the host return hasn’t been filed yet?","zh":"派驻国的税表还没提交，为什么我的工资单上已经列了假设税额？"},{"role":"Payroll Adviser","en":"That line is a deduction under our equalization policy. The actual tax return is handled separately.","zh":"那一项是根据我们的税负平衡政策扣除的金额。实际纳税申报另行处理。"}],"usage":"","new":true,"order":335,"aliases":[],"distinction":"Hypothetical tax（假设税额）是税负平衡下按假设留在基准地工作测算的员工税负，可由雇主按政策从薪资中扣收。actual tax（实际税额）依据适用税法计算并向税务机关结算。","collocationZh":"假设税额计算","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌhaɪpəˈθetɪkəl tæks","ipaUS":"ˌhaɪpəˈθetəkəl tæks","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Hypothetical tax","exampleZh":"按我们的税负平衡政策，薪资团队每月从工资中扣除假设税额。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How is hypothetical tax calculated?","zh":"假设税是如何计算的？"},"extension":{"en":"A bonus may change the hypothetical tax if it is included under the equalization policy.","zh":"如果税负平衡政策把奖金纳入计算，奖金可能改变假设税额。"}},{"id":"HR9-16","moduleId":"m9","module":"海外派遣与全球流动","term":"Tax protection","zh":"税负保护","definition":"按政策保护员工不因派遣承担超出某基准的税负。","example":"Tax protection may apply if the covered tax liability exceeds the policy baseline.","collocation":"tax protection arrangement","dialogue":[{"role":"Assignee","en":"The tax estimate is lower than it would have been at home. Does that change the company payment?","zh":"这个税额估算比留在派出国时还低。公司支付的金额会因此变化吗？"},{"role":"Mobility Tax Adviser","en":"Under our tax protection policy, we reimburse only eligible tax above the baseline. Let’s check the figures once the returns are ready.","zh":"按我们的税负保护政策，只补偿符合条件且超出基准的税额。等报税资料齐备后，我们再核对数字。"}],"usage":"税负保护与 tax equalization（税负平衡）机制不同，具体受雇佣协议与政策约束。","new":true,"order":336,"aliases":[],"distinction":"Tax protection（税负保护）通常补偿符合条件的超额税负，低于基准时的节省通常归员工。tax equalization（税负平衡）通常围绕基准双向结算。实际规则以适用政策为准。","collocationZh":"税负保护安排","collocationReview":"V18.2 模型编辑复核","ipaUK":"tæks prəˈtekʃən","ipaUS":"tæks prəˈtekʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Tax protection","exampleZh":"如果政策涵盖的应纳税额高于政策基准，可能适用税负保护。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the difference between tax protection and tax equalization?","zh":"税负保护与税负平衡有什么区别？"},"extension":{"en":"The tax protection policy specifies which income is included in the baseline calculation.","zh":"税负保护政策明确了哪些收入纳入基准税负的计算。"}},{"id":"HR9-17","moduleId":"m9","module":"海外派遣与全球流动","term":"Tax residency","zh":"税收居民身份","definition":"依适用税法及相关税收协定确定的税收居民身份，可影响纳税和申报范围。","example":"The tax team reviewed the employee’s tax residency in both jurisdictions.","collocation":"determine tax residency","dialogue":[{"role":"Employee","en":"I split last year between two countries and moved my family halfway through the assignment.","zh":"去年我在两个国家都住过，外派期间还把家人接到了派驻地。"},{"role":"Tax Adviser","en":"I’ll need your travel dates and housing details to review tax residency under the relevant rules.","zh":"我需要你的出入境日期和住房情况，才能按相关规则核查你的税收居民身份。"}],"usage":"","new":true,"order":337,"aliases":[],"distinction":"Tax residency（税收居民身份）依据相关税法及适用税收协定判断。citizenship（国籍）和 immigration residence status（移民居留身份）分别由其他规则确定。两地均认定为居民时，适用协定可能另有判定规则。","collocationZh":"确定税收居民身份","collocationReview":"V18.2 模型编辑复核","ipaUK":"tæks ˈrezɪdənsi","ipaUS":"tæks ˈrezɪdənsiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Tax residency","exampleZh":"税务团队审查了该员工在两个税收管辖区的税收居民身份。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could the assignment affect the employee's tax residency?","zh":"派遣可能影响员工的税收居民身份吗？"},"extension":{"en":"Use the correct tax year when documenting a change in tax residency.","zh":"记录税收居民身份的变化时，请确认适用的纳税年度。"}},{"id":"HR9-18","moduleId":"m9","module":"海外派遣与全球流动","term":"Permanent establishment (PE)","zh":"常设机构","definition":"在适用国内法或税收协定下，企业在另一税收管辖区的固定营业场所或符合条件的代理人活动等形成的企业所得税征税联结。","example":"We need to assess permanent establishment risk before approving the role.","collocation":"permanent establishment risk","dialogue":[{"role":"Sales Director","en":"The employee in the new market will negotiate contracts. Headquarters will still sign them.","zh":"新市场的员工将负责谈判合同，但仍由总部签署。"},{"role":"Tax Adviser","en":"Let’s review permanent establishment risk against the applicable rules before we finalize the role.","zh":"在敲定这个岗位前，我们先按适用规则评估常设机构风险。"}],"usage":"涉及税务常设机构风险，不等同于员工个人税务居民身份；跨境工作前需专业评估。","new":true,"order":338,"aliases":[],"distinction":"Permanent establishment（常设机构）是企业所得税语境中的跨境经营概念，可涉及固定营业场所或代理人活动等。tax residency（税收居民身份）着眼于纳税主体的居民归属。具体判定应结合适用国内法和税收协定。","collocationZh":"常设机构风险","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈpɜːmənənt ɪˈstæblɪʃmənt","ipaUS":"ˈpɝːmənənt ɪˈstæblɪʃmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Permanent establishment","exampleZh":"在批准该岗位前，我们需要评估常设机构（PE）税务风险。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could this remote arrangement create permanent establishment risk?","zh":"这种远程办公安排是否可能产生常设机构风险？"},"extension":{"en":"Tell the tax team if the foreign office’s activities change so it can reassess permanent establishment risk.","zh":"境外办事处的业务活动有变化时，请通知税务团队重新评估常设机构风险。"}},{"id":"HR9-19","moduleId":"m9","module":"海外派遣与全球流动","term":"Social security coverage","zh":"社保参保安排","definition":"员工在跨境工作期间适用的法定社会保障制度及其涵盖项目，具体取决于各地规则和适用的协调协定。","example":"Social security coverage depends on local rules and any applicable agreements.","collocation":"cross-border social security coverage","dialogue":[{"role":"Assignee","en":"My first payslip abroad shows a social security deduction. I’m still paying contributions at home.","zh":"我到境外后的第一张工资单上扣了社保费，可我在派出国也还在缴费。"},{"role":"Mobility Adviser","en":"I’ll ask both payroll teams to verify your social security coverage and check whether a coordination agreement applies.","zh":"我会请两地的薪资团队核实你适用的社保安排，并确认是否有适用的社保协调协定。"}],"usage":"","new":true,"order":339,"aliases":[],"distinction":"Social security coverage（社保参保安排）关注员工适用哪地的法定社保制度及其涵盖项目。private health insurance（商业医疗保险）是独立的保障安排，不能据此推定法定社保义务。","collocationZh":"跨境社保参保安排","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsəʊʃəl sɪˈkjʊərɪti ˈkʌvərɪdʒ","ipaUS":"ˈsoʊʃəl sɪˈkjʊrətiː ˈkʌvɚədʒ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Social security coverage","exampleZh":"社保参保安排取决于当地规则及适用的协调协定。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Where will the employee make social security contributions?","zh":"员工将在哪里缴纳社会保险？"},"extension":{"en":"Check cross-border social security coverage again if the assignment is extended.","zh":"外派期限延长时，请重新核查跨境社保参保安排。"}},{"id":"HR9-20","moduleId":"m9","module":"海外派遣与全球流动","term":"Certificate of coverage","zh":"社保适用证明","definition":"主管机构根据适用的跨境社保协调安排签发，用于证明特定期间适用哪一方社保制度的文件。","example":"Under an applicable agreement, a certificate of coverage can help establish an exemption from duplicate contributions for covered programs.","collocation":"request a certificate of coverage","dialogue":[{"role":"Payroll Analyst","en":"We have the employee’s enrollment letter. Can we process the exemption with that?","zh":"我们有员工的参保证明，可以凭这份材料办理免缴吗？"},{"role":"Mobility Adviser","en":"Check which document the relevant authority accepts. It may require a certificate of coverage issued under the agreement.","zh":"先确认相关机构接受哪种文件。对方可能要求提交按协定签发的社保适用证明。"}],"usage":"","new":true,"order":340,"aliases":[],"distinction":"Certificate of coverage（社保适用证明）通常证实适用的社保制度和期间。ordinary proof of enrollment（普通参保证明）通常只表明已参保。跨境免缴是否适用取决于相关协定、涵盖项目和办理条件。","collocationZh":"申请社保适用证明","collocationReview":"V18.2 模型编辑复核","ipaUK":"səˈtɪfɪkət ɒv ˈkʌvərɪdʒ","ipaUS":"sɚˈtɪfɪkət ʌv ˈkʌvɚədʒ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Certificate of coverage","exampleZh":"在适用协定下，社保适用证明可作为对所涵盖社保项目免于重复缴费的依据。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Do we need a certificate of coverage for this assignment?","zh":"这次派遣需要社保参保证明吗？"},"extension":{"en":"Verify that the dates on the certificate of coverage match the period you need to document.","zh":"请核对社保适用证明上的日期是否与需证明的期间一致。"}},{"id":"HR9-21","moduleId":"m9","module":"海外派遣与全球流动","term":"Split payroll","zh":"分地发薪","definition":"将同一员工的实际薪酬分由两个国家或地区的薪资系统或实体支付的安排。","example":"Split payroll requires coordination between the two payroll teams.","collocation":"split payroll arrangement","dialogue":[{"role":"Assignee","en":"I still have a mortgage at home, but I’ll need money in my host-country account for rent.","zh":"我在派出国还要还房贷，不过派驻国的账户里也得有钱付房租。"},{"role":"Payroll Adviser","en":"Let’s see whether our split payroll arrangement can cover both payments. I’ll confirm what each payroll can pay.","zh":"我们看看分地发薪安排能否兼顾这两笔支出。我会确认两地各能发放多少。"}],"usage":"","new":true,"order":341,"aliases":[],"distinction":"Split payroll（分地发薪）将实际薪资分由两地的薪资系统或实体支付。shadow payroll（影子薪资核算）在另一地补记并处理属地申报或扣缴，通常不向员工再发一份净薪资。","collocationZh":"分地发薪安排","collocationReview":"V18.2 模型编辑复核","ipaUK":"splɪt ˈpeɪrəʊl","ipaUS":"splɪt ˈpeɪroʊl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Split payroll","exampleZh":"分地发薪需要两地的薪资团队相互协调。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Will the salary be paid through a split payroll arrangement?","zh":"工资会采用跨国分拆发薪的方式支付吗？"},"extension":{"en":"Under split payroll, confirm the amount and currency each entity is scheduled to pay.","zh":"采用分地发薪时，请确认各实体预计支付的金额和币种。"}},{"id":"HR9-22","moduleId":"m9","module":"海外派遣与全球流动","term":"Shadow payroll","zh":"影子薪资核算","definition":"对在另一地支付的薪酬在本地作并行核算，以满足适用的申报或代扣代缴要求，通常不产生第二笔净工资。","example":"Shadow payroll may be needed to report compensation paid abroad.","collocation":"shadow payroll reporting","dialogue":[{"role":"Home Payroll Lead","en":"We paid the bonus at home last Friday. Do you need that amount for your next run?","zh":"我们上周五在派出国发了奖金。你们下次核算要用这个金额吗？"},{"role":"Host Payroll Lead","en":"Yes. Send me the gross amount so I can include it in shadow payroll for the host-country filing.","zh":"需要。把税前金额发给我，我会计入影子薪资核算，用于派驻国申报。"}],"usage":"不是“暗箱工资”或“隐藏工资”。","new":true,"order":342,"distinction":"Shadow payroll（影子薪资核算）主要用于记录已在其他地方支付的薪酬并履行当地适用的申报或扣缴要求，通常不另向员工发放净工资。split payroll（分地发薪）则涉及两地实际支付。","aliases":[],"collocationZh":"通过影子薪资核算进行申报","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈʃædəʊ ˈpeɪrəʊl","ipaUS":"ˈʃædoʊ ˈpeɪroʊl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Shadow payroll","exampleZh":"申报在境外支付的薪酬时，可能需要通过影子薪资核算办理。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Does the host country require shadow payroll reporting?","zh":"派驻国是否要求进行影子薪资申报？"},"extension":{"en":"Send the home payroll figures before the host-country shadow payroll cut-off.","zh":"请在派驻国影子薪资核算的截止时间前发来派出地的薪资数据。"}},{"id":"HR9-23","moduleId":"m9","module":"海外派遣与全球流动","term":"Balance sheet approach","zh":"外派薪酬平衡表法","definition":"以派出地的薪酬和消费结构为基准，按政策调整派驻地生活成本、住房、税务等项目的外派薪酬设计方法。","example":"The balance sheet approach aims to maintain purchasing power.","collocation":"balance sheet approach to expatriate pay","dialogue":[{"role":"Assignee","en":"The host salary survey is lower than my current pay. Is that what my new base salary will be?","zh":"派驻地薪资调查的水平比我现在的薪资低。我的新基本工资会按那个水平定吗？"},{"role":"Compensation Adviser","en":"We’re using the balance sheet approach for this assignment. We’ll start with your home pay and explain the adjustments.","zh":"这次外派采用外派薪酬平衡表法。我们会以你在派出地的薪资为起点，再说明各项调整。"}],"usage":"外派薪酬 Balance Sheet Approach 不等于公司财务资产负债表。","new":true,"order":343,"aliases":[],"distinction":"Balance sheet approach（外派薪酬平衡表法）以派出地薪酬和消费基准为起点调整外派薪酬。host-based approach（派驻地定薪法）通常以当地市场薪酬为基准。此处的 balance sheet 指外派薪酬测算表。","collocationZh":"用于外派薪酬设计的平衡表法","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈbæləns ʃiːt əˈprəʊtʃ","ipaUS":"ˈbæləns ʃiːt əˈproʊtʃ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Balance sheet approach","exampleZh":"外派薪酬平衡表法旨在帮助员工在派驻期间保持原有的购买力水平。","meaningReview":"HR场景校订","exampleReview":"语义修订","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Why do we use the balance sheet approach for this assignment?","zh":"为什么这次派遣采用薪酬平衡表法？"},"extension":{"en":"Under the balance sheet approach, the team updates the assumptions for spendable income before recalculating the allowance.","zh":"采用外派薪酬平衡表法时，团队会先更新可用于日常消费的收入基准，再重新计算津贴。"}},{"id":"HR9-24","moduleId":"m9","module":"海外派遣与全球流动","term":"Localization","zh":"雇佣待遇本地化","definition":"在外派语境中，指结束或逐步退出外派待遇，转为派驻地的雇佣条件和薪酬福利安排。","example":"Localization may be considered after the assignment ends.","collocation":"localization of expatriate terms","dialogue":[{"role":"Assignee","en":"If I accept the local role, will my housing allowance stop on the same day?","zh":"如果我接受当地岗位，住房津贴会在同一天停发吗？"},{"role":"Mobility Adviser","en":"Let’s review the localization proposal. It sets out when your local terms begin and which benefits have a transition period.","zh":"我们看看本地化方案吧。上面会写明当地雇佣条件何时生效，以及哪些福利设有过渡期。"}],"usage":"","new":true,"order":344,"aliases":[],"distinction":"外派语境中的 localization（雇佣待遇本地化）指由外派安排过渡到派驻地的雇佣条件。local-plus package（当地薪酬加额外福利方案）以当地待遇为基础，保留或增加部分约定福利。","collocationZh":"外派待遇本地化","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌləʊkəlaɪˈzeɪʃən","ipaUS":"ˌloʊkələˈzeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Localization","exampleZh":"外派结束后，可以考虑按派驻地的雇佣待遇安排员工转为当地任职。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When should we discuss localization with the employee?","zh":"我们应该什么时候与员工讨论待遇本地化？"},"extension":{"en":"The localization plan sets a transition date for each expatriate benefit.","zh":"雇佣待遇本地化方案为各项外派福利设定了过渡日期。"}},{"id":"HR9-25","moduleId":"m9","module":"海外派遣与全球流动","term":"Local-plus package","zh":"当地薪酬加额外福利方案","definition":"以派驻地市场薪酬和当地待遇为基础，按约定增加选定津贴或福利的方案。","example":"Our local-plus package combines a local salary with a temporary housing allowance.","collocation":"offer a local-plus package","dialogue":[{"role":"Hiring Manager","en":"She’s willing to take the role on local pay, but she’ll need help with school fees for the first year.","zh":"她愿意按当地薪酬接受岗位，但第一年需要学费方面的支持。"},{"role":"Mobility Adviser","en":"We could propose a local-plus package with temporary education support, subject to approval.","zh":"我们可以提一份当地薪酬加额外福利的方案，纳入限期的教育补助，再提交审批。"}],"usage":"","new":true,"order":345,"aliases":[],"distinction":"Local-plus package（当地薪酬加额外福利方案）以派驻地薪酬或待遇为基础，加上选定福利或津贴。balance sheet approach（外派薪酬平衡表法）一般从派出地薪酬和消费基准出发。","collocationZh":"提供当地薪酬加额外福利的方案","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈləʊkəl plʌs ˈpækɪdʒ","ipaUS":"ˈloʊkəl plʌs ˈpækədʒ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Local-plus package","exampleZh":"我们的当地薪酬加额外福利方案包括当地薪资和限期发放的住房津贴。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Would a local-plus package be appropriate here?","zh":"本案采用本地薪酬加补贴方案是否合适？"},"extension":{"en":"Specify which benefits end after the first year in the local-plus package.","zh":"请在当地薪酬加额外福利方案中注明哪些福利在第一年结束后停止。"}},{"id":"HR9-26","moduleId":"m9","module":"海外派遣与全球流动","term":"Repatriation","zh":"外派回任","definition":"在全球流动语境中，指员工外派结束后返回外派前的工作地或原组织的过程。","example":"Repatriation planning should begin before the assignment ends.","collocation":"repatriation plan","dialogue":[{"role":"Assignee","en":"My project ends in September, but our shipment can’t leave until October.","zh":"我的项目九月结束，可家里的物品要到十月才能运走。"},{"role":"Mobility Coordinator","en":"I’ll update the repatriation plan with both dates and check how much temporary storage we can cover.","zh":"我会在外派回任计划里更新这两个日期，再确认我们能承担多少临时仓储费用。"}],"usage":"","new":true,"order":346,"aliases":[],"distinction":"在外派语境中，repatriation（外派回任）指外派结束后返回派出地或原组织。reintegration（回任融入）指回来后重新适应团队和职责。回任不必然意味着回到原岗位。","collocationZh":"外派回任计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˌpætrɪˈeɪʃən","ipaUS":"riːˌpeɪtriːˈeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Repatriation","exampleZh":"外派回任规划应在派遣结束前启动。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When should we start repatriation planning?","zh":"我们应何时开始规划外派结束后的回任？"},"extension":{"en":"The repatriation plan should name the person responsible for the return move.","zh":"外派回任计划应明确由谁负责返程搬迁。"}},{"id":"HR9-27","moduleId":"m9","module":"海外派遣与全球流动","term":"Reintegration","zh":"回任融入","definition":"员工结束外派后重新融入原组织并适应回任岗位的过程，可包括明确职责、重建协作关系和分享外派经验。","example":"Our reintegration program pairs returnees with a manager who can help them settle into their new role.","collocation":"reintegration program","dialogue":[{"role":"Returning Employee","en":"The reporting lines changed while I was away. I’m not sure who makes decisions on my project now.","zh":"我外派期间汇报关系变了，现在不清楚谁负责我的项目决策。"},{"role":"Manager","en":"I’ll set up introductions with the new leads this week. We can add them to your reintegration plan.","zh":"这周我安排你和几位新负责人见个面，再把这些安排纳入你的回任融入计划。"}],"usage":"","new":true,"order":347,"aliases":[],"distinction":"Reintegration（回任融入）关注员工回任后的职责衔接、关系重建和经验转移。repatriation（外派回任）着重返回派出地或原组织的安排。","collocationZh":"回任融入计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌriːˌɪntɪˈɡreɪʃən","ipaUS":"riːˈɪntəˌɡreɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Reintegration","exampleZh":"我们的回任融入计划为外派回任员工安排一名经理，帮助他们适应新的岗位。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will we support reintegration after the assignment?","zh":"派遣结束后，我们将如何帮助员工重新融入？"},"extension":{"en":"The reintegration program gives returning employees time to share what they learned abroad.","zh":"回任融入计划为返回的员工安排了时间，分享他们在境外学到的经验。"}},{"id":"HR9-28","moduleId":"m9","module":"海外派遣与全球流动","term":"Assignment extension","zh":"派遣延期","definition":"延长原定国际派遣期限的安排。","example":"The business requested an assignment extension of six months.","collocation":"approve an assignment extension","dialogue":[{"role":"Regional Manager","en":"The handover has slipped by a month. Can Mei stay through the end of November?","zh":"交接推迟了一个月。小梅能留到十一月底吗？"},{"role":"Mobility Adviser","en":"Before we approve an assignment extension, I’ll confirm her availability and review the permit and lease dates.","zh":"在批准延长外派前，我会确认她能否继续留在派驻地，并核对工作许可和租约的日期。"}],"usage":"","new":true,"order":348,"aliases":[],"distinction":"Assignment extension（外派延期）指延长同一次外派的约定期限。permit extension（许可延期）是另行延长许可有效期。同意外派延期后，仍需核查相关许可和待遇。","collocationZh":"批准延长外派","collocationReview":"V18.2 模型编辑复核","ipaUK":"əˈsaɪnmənt ekˈstenʃən","ipaUS":"əˈsaɪnmənt ɪkˈstenʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Assignment extension","exampleZh":"业务部门申请将外派期限延长六个月。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Has the assignment extension been approved?","zh":"派遣延期获批了吗？"},"extension":{"en":"Record the revised end date and cost estimate before submitting an assignment extension for approval.","zh":"提交外派延期审批前，请记录调整后的结束日期和成本估算。"}},{"id":"HR9-29","moduleId":"m9","module":"海外派遣与全球流动","term":"Assignment termination","zh":"外派终止","definition":"按约定结束某次外派安排。提前结束时，可能需另行安排职责交接、待遇结算或返程。","example":"Early assignment termination requires a clear transition plan.","collocation":"early assignment termination","dialogue":[{"role":"Regional Lead","en":"The client has cancelled the rollout. We won’t need the assignee on site after this month.","zh":"客户取消了推广，下个月起现场不用再留外派员工了。"},{"role":"Mobility Adviser","en":"Let’s agree on the handover date and check what the letter says about early assignment termination.","zh":"先商定交接日期，再看看外派函对提前终止外派有什么约定。"}],"usage":"","new":true,"order":349,"aliases":[],"distinction":"Assignment termination（外派终止）结束的是派遣安排。early assignment termination 专指提前结束外派。termination of employment（雇佣关系终止）结束的是雇佣关系，后续处理须看约定及适用规则。","collocationZh":"提前终止外派","collocationReview":"V18.2 模型编辑复核","ipaUK":"əˈsaɪnmənt ˌtɜːmɪˈneɪʃən","ipaUS":"əˈsaɪnmənt tɚməˈneɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Assignment termination","exampleZh":"提前终止外派需要明确的交接和过渡计划。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What steps are needed for early assignment termination?","zh":"提前终止派遣需要办理哪些步骤？"},"extension":{"en":"The assignment termination notice specifies the last working day at the host site.","zh":"外派终止通知写明了在派驻地点的最后一个工作日。"}},{"id":"HR9-30","moduleId":"m9","module":"海外派遣与全球流动","term":"Dependent support","zh":"随行家属支持","definition":"为符合外派政策条件的家属提供的跨境搬迁及安置支持，范围可能涵盖择校和办理当地手续等。","example":"Dependent support may include school search assistance.","collocation":"dependent relocation support","dialogue":[{"role":"Assignee","en":"My partner and I will arrive first, and the children will join us a month later.","zh":"我和伴侣先到，孩子们一个月后再来。"},{"role":"Mobility Coordinator","en":"Send me their expected arrival dates. I’ll check which dependent support services we can arrange before they travel.","zh":"把孩子们预计抵达的日期发给我，我查一下在他们出发前可以安排哪些家属支持服务。"}],"usage":"","new":true,"order":350,"aliases":[],"distinction":"Dependent support（随行家属支持）针对符合政策定义的随行家属，可涉及安置或择校。dependent visa support（家属签证协助）是其中一类，签证资格按当地制度判断。","collocationZh":"随行家属搬迁支持","collocationReview":"V18.2 模型编辑复核","ipaUK":"dɪˈpendənt səˈpɔːt","ipaUS":"dɪˈpendənt səˈpɔːrt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Dependent support","exampleZh":"随行家属支持可能包括协助择校。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What dependent support is included in the policy?","zh":"这项政策包含哪些随行家属支持措施？"},"extension":{"en":"Under our dependent support policy, eligible partners can take local language classes.","zh":"根据我们的随行家属支持政策，符合条件的伴侣可以参加当地语言课程。"}},{"id":"HR9-31","moduleId":"m9","module":"海外派遣与全球流动","term":"Destination services","zh":"目的地安置服务","definition":"围绕员工及家属在派驻地安家所提供的服务，可包括找房、熟悉当地环境及办理登记等。","example":"Destination services can help with housing and local registration.","collocation":"destination services provider","dialogue":[{"role":"Assignee","en":"I need to view flats on Tuesday, but I don’t know which neighborhoods are a reasonable commute.","zh":"我周二想去看房，还不知道住在哪些街区通勤比较方便。"},{"role":"Mobility Coordinator","en":"Our destination services provider can suggest areas near the office and arrange viewings around your schedule.","zh":"我们的目的地安置服务商可以推荐办公室附近的区域，并按你的时间安排看房。"}],"usage":"","new":true,"order":351,"aliases":[],"distinction":"Destination services（目的地安置服务）侧重赴任地找房、熟悉社区和办理当地手续等实务。relocation assistance（搬迁支持）范围更广，还可包括搬运、旅费报销或临时住宿。","collocationZh":"目的地安置服务商","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌdestɪˈneɪʃən ˈsɜːvɪsɪz","ipaUS":"ˌdestəˈneɪʃən ˈsɝːvəsəz","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Destination services","exampleZh":"目的地安置服务可包括协助找房及办理当地登记手续。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which destination services provider are we using?","zh":"我们选用了哪家目的地安置服务商？"},"extension":{"en":"Ask the destination services provider what documents to bring to the local registration appointment.","zh":"请向目的地安置服务商确认，去办理当地登记时要带哪些文件。"}},{"id":"HR9-32","moduleId":"m9","module":"海外派遣与全球流动","term":"Hardship allowance","zh":"艰苦地区津贴","definition":"根据适用政策，为在生活或工作条件较为艰苦的地点任职而发放的津贴。","example":"We review hardship allowance rates when a location’s rating changes.","collocation":"hardship allowance eligibility","dialogue":[{"role":"Regional Manager","en":"The project moved from the capital to a remote site with limited medical facilities.","zh":"项目从首都搬到了偏远站点，那里的医疗设施有限。"},{"role":"Mobility Adviser","en":"I’ll check how the site is rated under our hardship allowance policy before we amend the offer.","zh":"修改外派方案前，我会按我们的艰苦地区津贴政策核对该站点的评级。"}],"usage":"","new":true,"order":352,"aliases":[],"distinction":"Hardship allowance（艰苦地区津贴）依据派驻地的艰苦程度设置，可参考医疗、交通或基础设施等条件。COLA（生活成本补贴）主要参考价格差异。两者的资格和金额可分别设定。","collocationZh":"艰苦地区津贴领取资格","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈhɑːdʃɪp əˈlaʊəns","ipaUS":"ˈhɑːrdʃɪp əˈlaʊəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Hardship allowance","exampleZh":"派驻地点的评级变化时，我们会复核艰苦地区津贴的标准。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Does this location qualify for a hardship allowance?","zh":"这个派驻地点符合发放艰苦地区津贴的条件吗？"},"extension":{"en":"Review hardship allowance eligibility when an assignee moves to a different site.","zh":"外派员工改去其他站点工作时，应重新核对其领取艰苦地区津贴的资格。"}},{"id":"HR9-33","moduleId":"m9","module":"海外派遣与全球流动","term":"Foreign exchange risk","zh":"汇率风险","definition":"汇率波动使薪资折算、外派成本或员工实际购买力偏离预期的风险。","example":"Foreign exchange risk matters when an assignment budget includes expenses payable in another currency.","collocation":"manage foreign exchange risk","dialogue":[{"role":"Finance Partner","en":"We priced the rent in euros, but the assignment budget is in dollars.","zh":"房租是用欧元报价的，但外派预算用美元编制。"},{"role":"Mobility Analyst","en":"I’ll show how different exchange rates affect the total so we can see the foreign exchange risk.","zh":"我会列出几种汇率对总成本的影响，让大家看清汇率风险。"}],"usage":"","new":true,"order":353,"aliases":[],"distinction":"Foreign exchange risk（汇率风险）来自不同货币之间的汇率波动。inflation risk（通胀风险）来自当地物价水平上涨。两者都可能影响外派成本或购买力。","collocationZh":"管理汇率风险","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈfɒrən eksˈtʃeɪndʒ rɪsk","ipaUS":"ˈfɔːrən ɪksˈtʃeɪndʒ rɪsk","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Foreign exchange risk","exampleZh":"外派预算纳入以其他币种支付的费用时，应考虑汇率风险。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will we manage exchange-rate changes in the package?","zh":"我们将如何应对待遇方案中的汇率变动？"},"extension":{"en":"Paying a location allowance in the host currency can reduce the employee’s foreign exchange risk on local expenses.","zh":"用派驻地货币发放驻地津贴，可以降低员工在支付当地费用时面临的汇率风险。"}},{"id":"HR9-34","moduleId":"m9","module":"海外派遣与全球流动","term":"Assignment cost projection","zh":"外派成本预测","definition":"根据外派期限和相关假设，估算派驻期间及相关搬迁阶段的薪酬福利、雇主承担的税费和支持服务等支出。","example":"This assignment cost projection includes housing and tax preparation fees.","collocation":"prepare an assignment cost projection","dialogue":[{"role":"Finance Partner","en":"The twelve-month option drops temporary housing after the first month. Is that assumption still valid?","zh":"十二个月的方案只给第一个月安排临时住宿，这个假设还成立吗？"},{"role":"Mobility Analyst","en":"I’ll check with the relocation team and update the assignment cost projection if the employee needs a longer stay.","zh":"我和搬迁团队核对一下。如果员工需要住得更久，我会更新外派成本预测。"}],"usage":"","new":true,"order":354,"aliases":[],"distinction":"Assignment cost projection（外派成本预测）按期限、汇率和待遇等假设估算未来支出。actual assignment cost（实际外派成本）反映已发生的支出。assignment ROI（外派投资回报）还考察收益。","collocationZh":"编制外派成本预测","collocationReview":"V18.2 模型编辑复核","ipaUK":"əˈsaɪnmənt kɒst prəˈdʒekʃən","ipaUS":"əˈsaɪnmənt kɑːst prəˈdʒekʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Assignment cost projection","exampleZh":"这份外派成本预测包括住房支出和税务申报服务费。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is included in the assignment cost projection?","zh":"派遣成本预测包含哪些费用？"},"extension":{"en":"The assignment cost projection shows one-time relocation expenses separately from recurring allowances.","zh":"外派成本预测将一次性搬迁费用与定期发放的津贴分别列示。"}},{"id":"HR9-35","moduleId":"m9","module":"海外派遣与全球流动","term":"Mobility policy exception","zh":"全球流动政策例外","definition":"组织依据内部授权，对某项全球流动安排批准偏离标准政策条款的个案。","example":"Our company requires written approval for a mobility policy exception.","collocation":"request a mobility policy exception","dialogue":[{"role":"Assignee","en":"The lease I can get starts two weeks after the company-paid hotel stay ends.","zh":"我能租到的房子要到公司支付的酒店住宿结束两周后才能入住。"},{"role":"Mobility Adviser","en":"I can submit a mobility policy exception request for the extra nights. I’ll attach the lease dates for the approver.","zh":"我可以为额外的住宿天数提交全球流动政策例外申请，并把租约日期附上供审批人查看。"}],"usage":"","new":true,"order":355,"aliases":[],"distinction":"Mobility policy exception（全球流动政策例外）是对内部标准条款的个案例外批准。policy amendment（政策修订）改变通用规则。法定要求仍按适用规定执行。","collocationZh":"申请全球流动政策例外","collocationReview":"V18.2 模型编辑复核","ipaUK":"məʊˈbɪlɪti ˈpɒlɪsi ekˈsepʃən","ipaUS":"moʊˈbɪlətiː ˈpɑːləsiː ɪkˈsepʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Mobility policy exception","exampleZh":"我们公司规定，全球流动政策例外须获得书面批准。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who can approve a mobility policy exception?","zh":"谁有权批准派遣政策例外？"},"extension":{"en":"Document the reason and end date for each approved mobility policy exception.","zh":"请记录每项已批准的全球流动政策例外所依据的理由和到期日期。"}},{"id":"HR9-36","moduleId":"m9","module":"海外派遣与全球流动","term":"Cross-border remote work","zh":"跨境远程办公","definition":"员工在其通常工作地所在国家或地区以外远程履行工作职责的安排，可涉及临时或持续性的跨境工作。","example":"Cross-border remote work can create tax and immigration issues.","collocation":"cross-border remote work request","dialogue":[{"role":"Employee","en":"I’m visiting family overseas next month. Could I work from there for two weeks?","zh":"我下个月要去国外看家人，能在那里远程工作两周吗？"},{"role":"HR Adviser","en":"Send me the country, dates and work you plan to do. We’ll use those details to review your cross-border remote work request.","zh":"把你要去的国家、日期和计划做的工作发给我，我们会根据这些信息审查你的跨境远程办公申请。"}],"usage":"","new":true,"order":356,"aliases":[],"distinction":"Cross-border remote work（跨境远程办公）指员工从通常工作地所在国家或地区以外远程履职。international assignment（国际派遣）通常由雇主安排赴任。business travel（商务出差）通常围绕特定商务活动。","collocationZh":"跨境远程办公申请","collocationReview":"V18.2 模型编辑复核","ipaUK":"krɒs ˈbɔːdə rɪˈməʊt wɜːk","ipaUS":"krɔːs ˈbɔːrdɚ rɪˈmoʊt wɝːk","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Cross-border remote work","exampleZh":"跨境远程办公可能引发税务和移民合规问题。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can we approve cross-border remote work for three months?","zh":"我们可以批准为期三个月的跨境远程办公吗？"},"extension":{"en":"The cross-border remote work review also checks whether company data can be accessed from the proposed location.","zh":"审查跨境远程办公申请时，也会核查员工是否能从拟工作地点访问公司数据。"}},{"id":"HR9-37","moduleId":"m9","module":"海外派遣与全球流动","term":"Business traveler","zh":"商务出差人员","definition":"在全球人才流动语境中，指为开会、谈判等短期商务活动赴境外的员工，具体合规类别取决于实际活动及当地规定。","example":"Tracking business travelers helps the mobility team identify trips that need a compliance review.","collocation":"business traveler tracking","dialogue":[{"role":"Project Manager","en":"Jules is flying in for a meeting, but the client may ask him to run part of the installation.","zh":"朱尔斯本来飞过去开会，但客户可能会请他参与安装工作。"},{"role":"Travel Compliance Lead","en":"Ask Jules for the full agenda. We screen business travelers based on what they’ll actually do on the trip.","zh":"请朱尔斯发来完整日程。我们按商务出差人员在行程中实际开展的活动来审查。"}],"usage":"商务出差并不自动豁免签证、税务或社保要求，具体需评估。","new":true,"order":357,"aliases":[],"distinction":"Business traveler（商务出差人员）在全球流动场景中通常指短期跨境参加商务活动的员工。international assignee（国际受派员工）在约定期间赴境外履职。具体合规判断取决于活动、地点和期限等因素。","collocationZh":"跟踪商务出差人员的行程","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈbɪznəs ˈtrævələ","ipaUS":"ˈbɪznəs ˈtrævəlɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Business traveler","exampleZh":"跟踪商务出差人员的行程，有助于全球流动团队识别需要开展合规审查的出差安排。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Do short-term business travelers need immigration review?","zh":"短期商务出差人员是否需要进行移民与签证合规审查？"},"extension":{"en":"Ask business travelers to report material changes to their planned duties.","zh":"商务出差人员计划开展的工作如有重大变化，请及时报告。"}},{"id":"HR9-38","moduleId":"m9","module":"海外派遣与全球流动","term":"Duty of care","zh":"雇主保护义务","definition":"在适用法律及具体情境下，雇主为保护员工健康和安全应采取合理措施的义务。","example":"As part of our duty of care, we provide employees with an emergency contact for overseas travel.","collocation":"fulfill the employer’s duty of care","dialogue":[{"role":"Travel Coordinator","en":"The hotel lost power after the storm, and two employees can’t reach the front desk.","zh":"暴风雨后酒店停电，有两名员工联系不上前台。"},{"role":"Security Lead","en":"I’ll call them and arrange another place to stay if needed. Let’s log the response under our duty of care procedures.","zh":"我打电话给他们，需要的话就安排其他住处。按员工保护流程把这次处理过程记录下来。"}],"usage":"","new":true,"order":358,"aliases":[],"distinction":"Duty of care（雇主保护义务）关注雇主在适用法律和情境下为员工健康与安全应采取的措施。travel insurance（差旅保险）按条款提供保障，可以作为风险管理措施之一。","collocationZh":"履行雇主保护义务","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈdjuːti ɒv keə","ipaUS":"ˈduːtiː ʌv ker","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Duty of care","exampleZh":"为境外出差员工提供紧急联系人，是我们履行雇主保护义务的措施之一。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What duty of care measures apply to international assignees?","zh":"哪些雇主关怀与保护措施适用于国际派遣员工？"},"extension":{"en":"Our duty of care procedures include a risk briefing before travel to a high-risk location.","zh":"按照我们的员工保护流程，员工前往高风险地点出差前须接受风险简报。"}},{"id":"HR9-39","moduleId":"m9","module":"海外派遣与全球流动","term":"Emergency evacuation","zh":"紧急撤离","definition":"在安全等紧急风险下，将人员从受影响地点转移到较安全地点的行动及相关安排。","example":"The emergency evacuation plan includes a 24-hour contact line.","collocation":"emergency evacuation protocol","dialogue":[{"role":"Site Coordinator","en":"The main road is closed. The team won’t be able to reach the usual pick-up point.","zh":"主路封了，团队到不了平时的集合接送点。"},{"role":"Security Lead","en":"I’ll contact the transport provider and confirm the alternate pick-up point in the emergency evacuation plan.","zh":"我联系运输服务商，确认紧急撤离预案中的备用接送点。"}],"usage":"","new":true,"order":359,"aliases":[],"distinction":"Emergency evacuation（紧急撤离）是在紧急风险下将人员转移到较安全地点。medical evacuation（医疗撤离）将人员转送至能提供必要医疗照护的地点。repatriation（外派回任）在本模块指返回派出地或原组织。","collocationZh":"紧急撤离程序","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪˈmɜːdʒənsi ɪˌvækjuːˈeɪʃən","ipaUS":"ɪˈmɝːdʒənsiː ɪˌvækjəˈweɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Emergency evacuation","exampleZh":"紧急撤离预案列有一条 24 小时联络热线。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who activates the emergency evacuation plan?","zh":"由谁启动紧急撤离计划？"},"extension":{"en":"The emergency evacuation plan identifies how to account for staff at the assembly point.","zh":"紧急撤离预案说明了如何在集合点清点人员。"}},{"id":"HR9-40","moduleId":"m9","module":"海外派遣与全球流动","term":"Assignment ROI","zh":"外派投资回报","definition":"衡量可归因于外派的收益与成本之间的关系。采用财务口径时，通常用净收益除以成本。难以货币化的成效可另行报告。","example":"Our assignment ROI review compares documented savings with the total cost of the placement.","collocation":"measure assignment ROI","dialogue":[{"role":"Finance Partner","en":"We know what the placement cost. Can we show whether it helped the local team hit its production target?","zh":"外派花了多少钱我们清楚。能看出这次外派是否帮助当地团队达到产量目标吗？"},{"role":"Operations Lead","en":"I’ll pull the baseline and actual figures for the assignment ROI review. We’ll also record what the team can now do without outside help.","zh":"我会为外派投资回报复盘调取基线和实际数据，再记录当地团队现在能独立完成哪些工作。"}],"usage":"","new":true,"order":360,"aliases":[],"distinction":"Assignment ROI（外派投资回报）评价外派收益与成本的关系。assignment cost projection（外派成本预测）估算支出。assignment outcomes（外派成果）可包含技能转移等难以直接货币化的成效。","collocationZh":"衡量外派投资回报","collocationReview":"V18.2 模型编辑复核","ipaUK":"əˈsaɪnmənt ɑː əʊ aɪ","ipaUS":"əˈsaɪnmənt ɑːr oʊ aɪ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Assignment R O I","exampleZh":"评估外派投资回报时，我们将有记录的成本节约额与外派总成本对照。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do we evaluate the assignment ROI after completion?","zh":"派遣结束后，我们如何评估派遣投资回报？"},"extension":{"en":"Exclude savings that would have occurred without the placement from the assignment ROI calculation.","zh":"计算外派投资回报时，应剔除即使不安排外派也能实现的成本节约。"}},{"id":"HR10-01","moduleId":"m10","module":"HR商务沟通与汇报","term":"Stakeholder alignment","zh":"利益相关方达成共识","definition":"与项目有关的各方对目标、方案或职责分工形成共同理解的状态，或达成这一状态的过程。","example":"We need stakeholder alignment before launching the new policy.","collocation":"secure stakeholder alignment","dialogue":[{"role":"HR Director","en":"Finance has budgeted for the pilot, but Operations still expects us to launch at every site.","zh":"财务已经为试点安排了预算，但运营仍以为我们会在所有站点上线。"},{"role":"Program Lead","en":"I’ll bring both teams together on Tuesday. We need stakeholder alignment on which sites go first.","zh":"我周二把两边约到一起。我们得先就首批上线地点达成共识。"}],"usage":"","new":true,"order":361,"aliases":[],"distinction":"Stakeholder alignment 强调相关方对目标、做法或分工形成共同理解。Stakeholder buy-in 强调相关方愿意支持并投入，formal approval 则是有权限的人正式批准。","collocationZh":"促成相关方达成共识","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsteɪkhəʊldə əˈlaɪnmənt","ipaUS":"ˈsteɪkˌhoʊldɚ əˈlaɪnmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Stakeholder alignment","exampleZh":"在推出新政策之前，我们需要与利益相关方达成一致。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Have all stakeholders aligned on the policy change?","zh":"所有利益相关方都就政策调整达成一致了吗？"},"extension":{"en":"The workshop helped build stakeholder alignment on the new intake process.","zh":"这次工作坊帮助各方就新的申请受理流程达成共识。"}},{"id":"HR10-02","moduleId":"m10","module":"HR商务沟通与汇报","term":"Executive summary","zh":"管理层摘要","definition":"在汇报中简述关键发现、影响、风险和需要管理层决策的要点。","example":"The executive summary highlights the decisions needed and the main risks.","collocation":"prepare an executive summary","dialogue":[{"role":"HR Analyst","en":"I’ve added the hiring forecast to the appendix. Does anything else need to move up front?","zh":"我把招聘预测放进了附录。还有什么需要提到前面吗？"},{"role":"HR Director","en":"Put the budget shortfall in the executive summary. The board needs to decide whether to fund the gap.","zh":"把预算缺口写进管理层摘要。董事会要决定是否拨款填补缺口。"}],"usage":"面向经营层汇报时可译“高管摘要”或“管理层摘要”。","new":true,"order":362,"distinction":"Executive summary 把管理层需要知道的发现、风险和决策事项集中在短篇幅内。Table of contents 供读者查找章节，abstract 通常概述研究目的、方法和结果。","aliases":[],"collocationZh":"撰写管理层摘要","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪɡˈzek.jə.tɪv ˈsʌm.ər.i","ipaUS":"ɪɡˈzek.jə.t̬ɪv ˈsʌm.ɚ.i","ipaSource":"https://dictionary.cambridge.org/dictionary/english/executive | https://dictionary.cambridge.org/dictionary/english/summary","speakTerm":"Executive summary","exampleZh":"管理层摘要重点列出了待决策事项和主要风险。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we include in the executive summary?","zh":"管理层摘要应该包括哪些内容？"},"extension":{"en":"Keep the executive summary to one page for the steering committee.","zh":"给指导委员会看的管理层摘要请控制在一页以内。"}},{"id":"HR10-03","moduleId":"m10","module":"HR商务沟通与汇报","term":"Key takeaway","zh":"核心结论","definition":"汇报或分析中最重要的信息。","example":"The key takeaway is that retention improved in critical roles.","collocation":"highlight the key takeaway","dialogue":[{"role":"HR Analyst","en":"The overall survey score was flat, but new hires reported a much better first week.","zh":"调查总分持平，但新员工反映第一周的体验好多了。"},{"role":"People Partner","en":"That’s the key takeaway for the onboarding team. Put the new-hire results first.","zh":"这才是入职团队最该关注的发现。把新员工的结果放到前面。"}],"usage":"","new":true,"order":363,"aliases":[],"distinction":"Key takeaway 是希望读者记住的一条关键信息，可以是结论或启示。Finding 是分析得出的具体发现，recommendation 则指建议采取的行动。","collocationZh":"强调核心结论","collocationReview":"V18.2 模型编辑复核","ipaUK":"kiː ˈteɪkəˌweɪ","ipaUS":"kiː ˈteɪkəˌweɪ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Key takeaway","exampleZh":"最重要的结论是，关键岗位的员工留存情况有所改善。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the key takeaway from the survey?","zh":"这次调查最重要的结论是什么？"},"extension":{"en":"Use the slide title to state the key takeaway.","zh":"把幻灯片标题写成你希望听众记住的核心结论。"}},{"id":"HR10-04","moduleId":"m10","module":"HR商务沟通与汇报","term":"Action item","zh":"待办事项","definition":"在会议、评审等工作沟通中明确提出、需要落实的具体任务。","example":"Each action item has an owner and a deadline.","collocation":"track action items","dialogue":[{"role":"Project Lead","en":"Two offices still use the old form. Who can replace it on their local sites?","zh":"还有两个办公室在用旧表。谁能把它们本地站点上的表换掉？"},{"role":"HR Coordinator","en":"I can do that. Add it as my action item for Thursday.","zh":"我来处理。把这项待办记在我名下，周四前完成。"}],"usage":"","new":true,"order":364,"aliases":[],"distinction":"Action item 是有待落实的具体任务，通常标明负责人和时限。Decision 记录已作出的决定，next steps 还可包含尚未分派的后续安排。","collocationZh":"跟踪待办事项","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈækʃən ˈaɪtəm","ipaUS":"ˈækʃən ˈaɪtəm","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Action item","exampleZh":"每项待办事项都有负责人和截止日期。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who is responsible for this action item?","zh":"谁负责这项待办行动？"},"extension":{"en":"Mark the action item as complete once the checklist is published.","zh":"清单发布后，把对应的待办事项标记为已完成。"}},{"id":"HR10-05","moduleId":"m10","module":"HR商务沟通与汇报","term":"Next steps","zh":"下一步安排","definition":"当前阶段之后拟开展的工作及其先后顺序、分工或时间安排。","example":"Let's summarize the next steps before we close the meeting.","collocation":"agree on next steps","dialogue":[{"role":"HR Director","en":"The pilot is approved. Do we need to tell all sites today?","zh":"试点已经获批。今天要通知所有站点吗？"},{"role":"Program Lead","en":"Not yet. Our next steps are to brief the pilot managers and agree on a start date.","zh":"先不用。接下来先向试点负责人说明情况，再定启动日期。"}],"usage":"","new":true,"order":365,"aliases":[],"distinction":"Next steps 泛指接下来要做什么，可涵盖工作顺序、沟通安排或待定事项。Action items 是可以逐项跟踪的具体任务，通常已经明确由谁完成。","collocationZh":"就下一步安排达成共识","collocationReview":"V18.2 模型编辑复核","ipaUK":"nekst steps","ipaUS":"nekst steps","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Next steps","exampleZh":"结束会议前，我们总结一下下一步安排吧。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can we confirm the next steps before we finish?","zh":"我们能否在会议结束前确认下一步安排？"},"extension":{"en":"I’ll email the next steps once the survey results are in.","zh":"调查结果出来后，我会邮件通知大家下一步安排。"}},{"id":"HR10-06","moduleId":"m10","module":"HR商务沟通与汇报","term":"Decision log","zh":"决策记录","definition":"集中记录已作决定、相关依据和决策人等信息，供项目后续查阅的文档。","example":"The decision log records why we selected this option.","collocation":"maintain a decision log","dialogue":[{"role":"Implementation Lead","en":"Does the pilot include contractors? The two slide decks say different things.","zh":"试点包括承包人员吗？两份演示文稿写得不一样。"},{"role":"HR Project Manager","en":"It doesn’t. I’ll send you the decision log entry from last week’s review.","zh":"不包括。我把上周评审的那条决策记录发给你。"}],"usage":"","new":true,"order":366,"aliases":[],"distinction":"Decision log 便于跨会议追踪哪些决定已经作出、谁作的决定以及依据。Meeting minutes 以单次会议为单位，还记录讨论和待办事项。","collocationZh":"维护决策记录","collocationReview":"V18.2 模型编辑复核","ipaUK":"dɪˈsɪʒən lɒɡ","ipaUS":"dɪˈsɪʒən lɔːɡ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Decision log","exampleZh":"决策记录说明了我们选择这一方案的原因。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Where can we find the decision log for this project?","zh":"在哪里可以找到这个项目的决策记录？"},"extension":{"en":"Add a link to the supporting analysis in the decision log.","zh":"在决策记录中附上支持该决定的分析链接。"}},{"id":"HR10-07","moduleId":"m10","module":"HR商务沟通与汇报","term":"Meeting minutes","zh":"会议纪要","definition":"会议讨论、决定和任务的书面记录。","example":"I'll circulate the meeting minutes after the call.","collocation":"circulate meeting minutes","dialogue":[{"role":"People Partner","en":"I missed the last ten minutes. Did we agree to change the launch date?","zh":"最后十分钟我没听到。大家同意改上线日期了吗？"},{"role":"Project Coordinator","en":"Yes, we moved it to the 18th. I’ve noted the reason in the meeting minutes.","zh":"同意了，改到 18 日。我已经把原因写进会议纪要。"}],"usage":"","new":true,"order":367,"aliases":[],"distinction":"Meeting minutes 提炼会议议题、决定和行动项。Transcript 逐字或近乎逐字记录发言，agenda 列的是会前拟讨论的议程。","collocationZh":"分发会议纪要","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈmiːtɪŋ ˈmɪnɪts","ipaUS":"ˈmiːtɪŋ ˈmɪnəts","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Meeting minutes","exampleZh":"通话结束后，我会发送会议纪要。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"When will the meeting minutes be shared?","zh":"会议纪要什么时候共享？"},"extension":{"en":"Please send any corrections to the meeting minutes by Friday.","zh":"如需更正会议纪要，请在周五前发给我。"}},{"id":"HR10-08","moduleId":"m10","module":"HR商务沟通与汇报","term":"Escalation path","zh":"升级处理路径","definition":"问题超出当前人员的权限、处理能力或时限时，转交适当负责人或团队的规则和路径。","example":"The escalation path is documented in the service guide.","collocation":"follow the escalation path","dialogue":[{"role":"Payroll Analyst","en":"This site’s payroll file failed validation, and the cutoff is at noon.","zh":"这个站点的薪资文件校验失败了，中午就是处理截止时间。"},{"role":"Payroll Lead","en":"Follow the escalation path and call the duty manager. I’ll let the site know we’re investigating.","zh":"按升级流程联系值班经理。我先通知站点，我们正在排查。"}],"usage":"","new":true,"order":368,"aliases":[],"distinction":"Escalation path 规定问题在何种情况下该转给哪一级或哪个团队。Reporting line 指日常汇报关系，紧急事项的处理路径可能跨部门。","collocationZh":"按升级流程处理","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌeskəˈleɪʃən pæθ","ipaUS":"ˌeskəˈleɪʃən pæθ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Escalation path","exampleZh":"升级处理路径已记录在服务指南中。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the escalation path for urgent payroll issues?","zh":"紧急薪资问题的升级处理路径是什么？"},"extension":{"en":"The escalation path identifies who handles payroll issues after hours.","zh":"升级处理路径明确了下班后由谁处理薪资问题。"}},{"id":"HR10-09","moduleId":"m10","module":"HR商务沟通与汇报","term":"Business case","zh":"立项论证／商业论证","definition":"说明为什么值得采取某项方案或投入资源的材料，通常涵盖需求、备选方案、成本、收益和风险。","example":"The business case supports additional investment in hiring.","collocation":"build a business case","dialogue":[{"role":"HR Operations Lead","en":"We’ve had three scheduling errors this month. Could we buy a dedicated tool?","zh":"这个月排班已经出了三次错。能采购一款专门的工具吗？"},{"role":"Finance Partner","en":"Build a business case first. Include the time spent fixing errors and the annual license fee.","zh":"先做一份立项论证，把纠错耗时和年度许可费都算进去。"}],"usage":"","new":true,"order":369,"aliases":[],"distinction":"Business case 为是否投入资源提供判断依据，常比较成本、收益、风险和备选方案。Business plan 侧重业务如何运营和发展，project plan 侧重项目获批后如何实施。","collocationZh":"编制立项论证","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈbɪznəs keɪs","ipaUS":"ˈbɪznəs keɪs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Business case","exampleZh":"这份论证为增加招聘投入提供了依据。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can you prepare a business case for the new program?","zh":"能否为新项目准备一份商业论证？"},"extension":{"en":"The business case compares building the tool in-house with buying it.","zh":"这份立项论证比较了自研和采购工具两种方案。"}},{"id":"HR10-10","moduleId":"m10","module":"HR商务沟通与汇报","term":"Trade-off","zh":"权衡取舍","definition":"在相互冲突的目标或资源限制下作出的选择。","example":"We discussed the trade-off between speed and cost.","collocation":"assess the trade-offs","dialogue":[{"role":"Recruiter","en":"If we add a work sample, candidates will need another hour.","zh":"如果加做工作样本测试，候选人就得多花一小时。"},{"role":"Hiring Manager","en":"I’m comfortable with that trade-off for this role. We’ll drop one of the interviews to keep the process manageable.","zh":"这个岗位我愿意做这个取舍。我们可以减一轮面试，免得整个流程太长。"}],"usage":"","new":true,"order":370,"aliases":[],"distinction":"Trade-off 强调获得一项好处时可能牺牲另一项目标。Compromise 常指各方通过让步达成折中方案，constraint 则是限制选择的条件。","collocationZh":"评估各项取舍","collocationReview":"V18.2 模型编辑复核","ipaUK":"treɪd ɒf","ipaUS":"treɪd ɔːf","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Trade-off","exampleZh":"我们讨论了速度与成本之间需要作出的权衡。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What trade-offs should leadership consider?","zh":"领导层应该考虑哪些取舍？"},"extension":{"en":"A shorter pilot involves a trade-off between speed and the depth of feedback.","zh":"缩短试点意味着要在推进速度和反馈的深入程度之间做取舍。"}},{"id":"HR10-11","moduleId":"m10","module":"HR商务沟通与汇报","term":"Risk mitigation","zh":"风险缓解","definition":"降低风险发生概率或影响的措施。","example":"Risk mitigation measures include extra compliance checks.","collocation":"risk mitigation plan","dialogue":[{"role":"HR Systems Lead","en":"What happens if the import puts people in the wrong reporting groups?","zh":"如果导入后有人被分到了错误的汇报组，怎么办？"},{"role":"Implementation Lead","en":"Add a test import to the risk mitigation plan. We’ll start with one department’s file.","zh":"把测试导入写进风险缓解计划。我们先用一个部门的文件试导入。"}],"usage":"","new":true,"order":371,"aliases":[],"distinction":"Risk mitigation 通过控制措施降低风险发生的可能性或影响。Risk avoidance 通过放弃或改变相关活动避开风险来源，contingency plan 则预先安排风险发生后的应对。","collocationZh":"风险缓解计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪsk ˌmɪtɪˈɡeɪʃən","ipaUS":"rɪsk ˌmɪtɪˈɡeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Risk mitigation","exampleZh":"风险缓解措施包括增加合规检查。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What risk mitigation steps do you recommend?","zh":"你建议采取哪些风险缓解措施？"},"extension":{"en":"The risk mitigation plan calls for a backup approver.","zh":"风险缓解计划要求安排一名备用审批人。"}},{"id":"HR10-12","moduleId":"m10","module":"HR商务沟通与汇报","term":"Assumption","zh":"假设","definition":"分析或预算中暂时成立的前提条件。","example":"The forecast is based on the assumption that monthly turnover will remain stable.","collocation":"validate an assumption","dialogue":[{"role":"Finance Partner","en":"This plan shows two recruiters covering the holiday period. Has either of them booked time off?","zh":"计划里假期期间安排了两名招聘专员。有谁已经请假了吗？"},{"role":"Recruiting Lead","en":"I’ll check today. I assumed both would be available. If either is away, we’ll have to change the schedule.","zh":"我今天确认一下。我原来假设两人都能上班。如果有人休假，就得调整排期。"}],"usage":"","new":true,"order":372,"aliases":[],"distinction":"Assumption 是在尚未充分验证时暂用作分析前提的判断。Estimate 是对数值或范围的估算，constraint 是必须遵守的限制条件。","collocationZh":"验证一项假设","collocationReview":"V18.2 模型编辑复核","ipaUK":"əˈsʌmpʃən","ipaUS":"əˈsʌmpʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Assumption","exampleZh":"这份预测以月度离职率保持稳定为前提。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What assumptions underlie this workforce forecast?","zh":"这份人员需求预测基于哪些假设？"},"extension":{"en":"Our budget assumption is that agency fees will stay flat.","zh":"我们的预算假设是招聘机构的收费将保持不变。"}},{"id":"HR10-13","moduleId":"m10","module":"HR商务沟通与汇报","term":"Dependency","zh":"依赖事项","definition":"一项工作启动或完成所依赖的其他工作、资源或决定，也指这种依赖关系。","example":"System integration is a key dependency for the launch.","collocation":"manage dependencies","dialogue":[{"role":"HR Coordinator","en":"Can we send the training invitations today?","zh":"我们今天能发培训邀请吗？"},{"role":"Project Manager","en":"The shift roster is a dependency. We need it before we can assign people to sessions.","zh":"先得拿到排班表，有了它才能给大家分培训场次。"}],"usage":"","new":true,"order":373,"aliases":[],"distinction":"Dependency 描述一项工作需要另一项工作、资源或决定到位的关系。Blocker 指已经使工作无法继续的障碍，前置事项如期完成时，dependency 无须升级处理。","collocationZh":"管理依赖事项","collocationReview":"V18.2 模型编辑复核","ipaUK":"dɪˈpendənsi","ipaUS":"dɪˈpendənsiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Dependency","exampleZh":"完成系统集成是项目上线的一项关键前提。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Are there any dependencies that could delay the launch?","zh":"是否有可能推迟上线的依赖事项？"},"extension":{"en":"Payroll testing has a dependency on the availability of sample data.","zh":"薪资系统测试要等样本数据就绪。"}},{"id":"HR10-14","moduleId":"m10","module":"HR商务沟通与汇报","term":"Timeline","zh":"项目时间表／时间安排","definition":"按时间顺序列出项目阶段、主要活动和关键日期的安排。","example":"The timeline includes policy drafting and manager training.","collocation":"confirm the project timeline","dialogue":[{"role":"L&D Lead","en":"The trainer can’t start until the week of the 12th. Will that push back the launch?","zh":"讲师要到 12 日那周才有空。上线会因此推迟吗？"},{"role":"Project Manager","en":"We can keep the launch date if we move the practice sessions online. I’ll revise the timeline this afternoon.","zh":"如果把实操课改到线上，上线日期就可以照旧。我下午更新项目时间表。"}],"usage":"","new":true,"order":374,"aliases":[],"distinction":"Timeline 展示多个活动、阶段或节点在时间上的先后与跨度。Deadline 指某项工作的最晚完成时间，milestone 指预期达到的关键节点。","collocationZh":"确认项目时间表","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtaɪmlaɪn","ipaUS":"ˈtaɪmlaɪn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Timeline","exampleZh":"项目时间表包括政策起草和管理者培训。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Is the implementation timeline still realistic?","zh":"实施时间表现在仍然现实可行吗？"},"extension":{"en":"The timeline allows two weeks for employee feedback.","zh":"时间表给员工预留了两周时间反馈意见。"}},{"id":"HR10-15","moduleId":"m10","module":"HR商务沟通与汇报","term":"Milestone","zh":"里程碑","definition":"标识项目阶段完成的关键节点。","example":"The next milestone is executive approval of the policy.","collocation":"hit a milestone","dialogue":[{"role":"HR Systems Lead","en":"We’ve migrated the employee records. Is that enough to start testing?","zh":"员工记录已经迁移了。可以开始测试了吗？"},{"role":"Project Manager","en":"The next milestone is getting both sites to reconcile their totals. Then we can start testing.","zh":"下一个里程碑是两个站点都完成总数核对。之后就能开始测试。"}],"usage":"","new":true,"order":375,"aliases":[],"distinction":"Milestone 是项目达到的关键状态或事件，例如试点验收。Deliverable 是实际提交的成果，例如验收报告。Deadline 是要求完成的最晚时间。","collocationZh":"达成里程碑","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈmaɪlstəʊn","ipaUS":"ˈmaɪlstoʊn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Milestone","exampleZh":"下一个里程碑是获得管理层对政策的批准。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next milestone for the HR program?","zh":"这个 HR 项目的下一个里程碑是什么？"},"extension":{"en":"Completing the first payroll test was a major milestone.","zh":"完成首次薪资系统测试是一个重要的里程碑。"}},{"id":"HR10-16","moduleId":"m10","module":"HR商务沟通与汇报","term":"Deliverable","zh":"交付成果","definition":"项目需在约定节点提交的具体产出。","example":"The revised policy handbook is our final deliverable.","collocation":"project deliverables","dialogue":[{"role":"HR Project Manager","en":"The vendor ran the workshop yesterday. Do we have what we need to close this phase?","zh":"供应商昨天办完了工作坊。这一阶段可以结项了吗？"},{"role":"L&D Lead","en":"We’re still waiting for one deliverable, the facilitator guide in an editable format.","zh":"还有一项交付成果没收到，就是可编辑的讲师手册。"}],"usage":"","new":true,"order":376,"aliases":[],"distinction":"Deliverable 是约定提交、可供验收的产出。Task 是为产出所做的工作，outcome 是交付后所要实现的实际变化。","collocationZh":"项目交付成果","collocationReview":"V18.2 模型编辑复核","ipaUK":"dɪˈlɪvərəbəl","ipaUS":"dɪˈlɪvɚəbəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Deliverable","exampleZh":"修订后的政策手册是我们的最终交付成果。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What deliverables are due this month?","zh":"本月有哪些交付成果到期？"},"extension":{"en":"Each deliverable must meet the acceptance criteria agreed at kickoff.","zh":"每项交付成果都必须符合启动时约定的验收标准。"}},{"id":"HR10-17","moduleId":"m10","module":"HR商务沟通与汇报","term":"Scope","zh":"工作范围","definition":"项目或流程涵盖与不涵盖的内容。","example":"The scope includes HR operations in five markets.","collocation":"define the project scope","dialogue":[{"role":"HR Operations Lead","en":"The regional team also wants us to review the leave approval process.","zh":"区域团队还希望我们一起审查请假审批流程。"},{"role":"Project Manager","en":"Let’s keep the scope to onboarding this quarter. I can log the leave request for the next planning cycle.","zh":"本季度先把范围限定在入职流程。我可以把请假流程这项需求记到下一轮规划里。"}],"usage":"","new":true,"order":377,"aliases":[],"distinction":"Scope 划定做哪些工作、覆盖哪些对象以及交付什么。Requirements 说明范围内的成果需满足哪些条件，scope change 指对边界或交付约定的变更。","collocationZh":"明确项目范围","collocationReview":"V18.2 模型编辑复核","ipaUK":"skəʊp","ipaUS":"skoʊp","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Scope","exampleZh":"本次工作范围包括五个市场的人力资源运营。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can we clarify the scope of this initiative?","zh":"我们能否明确这项举措的工作范围？"},"extension":{"en":"We narrowed the scope to salaried roles for the first review.","zh":"我们将首轮审查范围缩小到领取固定薪资的岗位。"}},{"id":"HR10-18","moduleId":"m10","module":"HR商务沟通与汇报","term":"Out of scope","zh":"超出范围／不在范围内","definition":"用于说明某事项不属于当前约定的项目、阶段或任务范围。","example":"Payroll system replacement is out of scope for phase one.","collocation":"out-of-scope request","dialogue":[{"role":"Site HR Lead","en":"Can the new dashboard also track overtime by shift?","zh":"新的看板能不能也按班次统计加班？"},{"role":"Analytics Lead","en":"Shift reporting is out of scope for this release. I can estimate it as an addition for the next release.","zh":"这一版不包含按班次统计。我可以估算把它加到下一版需要多少工作量。"}],"usage":"","new":true,"order":378,"aliases":[],"distinction":"Out of scope 表示事项落在已约定工作范围之外。Deprioritized 表示优先级被调低，deferred 表示延后安排，两者都可能仍在范围内。","collocationZh":"超出项目范围的请求","collocationReview":"V18.2 模型编辑复核","ipaUK":"aʊt ɒv skəʊp","ipaUS":"aʊt ʌv skoʊp","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Out of scope","exampleZh":"第一阶段不包括替换薪资系统。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Is payroll redesign out of scope for this project?","zh":"薪资流程重设计是否不在本项目范围内？"},"extension":{"en":"Any out-of-scope request needs a separate estimate.","zh":"超出项目范围的需求都需要单独估算。"}},{"id":"HR10-19","moduleId":"m10","module":"HR商务沟通与汇报","term":"Alignment meeting","zh":"协调会／对齐会议","definition":"为统一目标、方案与分工召开的会议。","example":"The alignment meeting will address outstanding questions.","collocation":"schedule an alignment meeting","dialogue":[{"role":"People Partner","en":"Local HR expects to handle employee questions, but the service desk has already drafted replies.","zh":"当地人力资源团队以为会由他们解答员工问题，但服务台已经起草了答复。"},{"role":"Service Desk Lead","en":"Let’s use the alignment meeting to agree who handles each type of question.","zh":"我们在协调会上定一下每类问题由谁处理。"}],"usage":"","new":true,"order":379,"aliases":[],"distinction":"Alignment meeting 用于消除各方理解差异、明确目标与分工。Status meeting 主要交换进展，decision meeting 主要推动有权限的人作出决定。","collocationZh":"安排协调会","collocationReview":"V18.2 模型编辑复核","ipaUK":"əˈlaɪnmənt ˈmiːtɪŋ","ipaUS":"əˈlaɪnmənt ˈmiːtɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Alignment meeting","exampleZh":"协调会将讨论仍待解决的问题。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Should we schedule an alignment meeting with finance?","zh":"我们应该安排与财务部门的对齐会议吗？"},"extension":{"en":"We scheduled an alignment meeting to resolve conflicting launch dates.","zh":"我们安排了一场协调会，解决上线日期不一致的问题。"}},{"id":"HR10-20","moduleId":"m10","module":"HR商务沟通与汇报","term":"Touch base","zh":"简短联系／简短沟通","definition":"在较非正式的工作沟通中，与某人简短联系，交换近况或确认信息。","example":"Let's touch base on the hiring plan tomorrow.","collocation":"touch base with someone","dialogue":[{"role":"Recruiter","en":"I’m speaking to the candidate at three. Has the hiring manager settled on a start date?","zh":"我三点要和候选人通话。用人经理定好入职日期了吗？"},{"role":"Recruiting Coordinator","en":"She’s free now. I’ll touch base with her and get back to you before the call.","zh":"她现在有空。我去跟她确认一下，通话前给你消息。"}],"usage":"常用于非正式工作对话，正式文件可用 follow up / discuss。","new":true,"order":380,"aliases":[],"distinction":"Touch base 是较口语化的说法，强调简单联系、交换近况或确认信息。Follow up 通常有明确的前情或待跟进事项，check in 还可侧重了解对方的状态。","collocationZh":"和某人简短沟通","collocationReview":"V18.2 模型编辑复核","ipaUK":"tʌtʃ beɪs","ipaUS":"tʌtʃ beɪs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Touch base","exampleZh":"明天我们再简短沟通一下招聘计划。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can we touch base after the leadership review?","zh":"领导层评审后，我们能否简短沟通一下进展？"},"extension":{"en":"I’ll touch base with the site lead before sending the invite.","zh":"发邀请前，我会先和站点负责人简单确认一下。"}},{"id":"HR10-21","moduleId":"m10","module":"HR商务沟通与汇报","term":"Follow up","zh":"跟进","definition":"就上一轮沟通继续确认或推进。","example":"I’ll follow up with the legal team about the contract wording.","collocation":"follow up on an issue","dialogue":[{"role":"Payroll Lead","en":"The vendor promised a corrected file yesterday. Did anything come through?","zh":"供应商说昨天会发更正后的文件。有收到吗？"},{"role":"Payroll Analyst","en":"Nothing yet. I’ll follow up with their support team and ask for a delivery time.","zh":"还没有。我会联系他们的支持团队，确认什么时候能发来。"}],"usage":"","new":true,"order":381,"aliases":[],"distinction":"Follow up 强调把已有事项继续查清或推进。Follow up with 后接联系人，follow up on 后接事项。作名词或形容词时通常写作 follow-up。","collocationZh":"跟进某个问题","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈfɒləʊ ʌp","ipaUS":"ˈfɑːloʊ ʌp","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Follow up","exampleZh":"我会联系法务团队，跟进合同措辞的问题。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you follow up on the pending approval?","zh":"能否跟进一下尚待批准的事项？"},"extension":{"en":"I’ll follow up on the access request if there’s no reply by noon.","zh":"如果到中午还没收到回复，我会跟进权限申请。"}},{"id":"HR10-22","moduleId":"m10","module":"HR商务沟通与汇报","term":"Circle back","zh":"稍后再讨论","definition":"把当前议题暂放一边，待有更多信息或时机合适时再继续讨论。","example":"Let's circle back once the budget is confirmed.","collocation":"circle back to a topic","dialogue":[{"role":"Finance Partner","en":"Should we pick a reporting tool today?","zh":"我们今天就定用哪个报表工具吗？"},{"role":"Analytics Lead","en":"Let’s circle back on Thursday. I’ll have seen both demos by then.","zh":"周四再谈吧。到时两场演示我都看过了。"}],"usage":"较偏口语，正式场景可用 revisit this topic。","new":true,"order":382,"aliases":[],"distinction":"Circle back 是较口语化的商务表达，指暂时搁置一个话题，稍后再继续谈。Follow up 更侧重追问进度或推动已有事项落实。","collocationZh":"稍后再讨论某个话题","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsɜːkəl bæk","ipaUS":"ˈsɝːkəl bæk","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Circle back","exampleZh":"等预算确定后，我们再讨论这件事。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can we circle back after finance reviews the numbers?","zh":"等财务部门审核数字后，我们再讨论这个问题好吗？"},"extension":{"en":"We can circle back to the rollout dates after the vendor demo.","zh":"供应商演示结束后，我们可以再谈推行日期。"}},{"id":"HR10-23","moduleId":"m10","module":"HR商务沟通与汇报","term":"Heads-up","zh":"提前提醒","definition":"在事情发生前给相关方一个简短通知。","example":"Just a heads-up, the survey closes on Friday.","collocation":"give someone a heads-up","dialogue":[{"role":"People Partner","en":"A few employees may ask about the new leave form tomorrow. The link has changed.","zh":"明天可能有员工来问新的请假表，链接已经换了。"},{"role":"Service Desk Lead","en":"Thanks for the heads-up. I’ll pin the new link in our team chat.","zh":"谢谢提前说一声。我会把新链接置顶到团队群里。"}],"usage":"","new":true,"order":383,"aliases":[],"distinction":"Heads-up 是较非正式的提醒或预告，目的是让对方提前有所准备。Notice 可指正式通知，reminder 常用于提醒对方留意已经知道的事项。","collocationZh":"提前提醒某人","collocationReview":"V18.2 模型编辑复核","ipaUK":"hedz ʌp","ipaUS":"hedz ʌp","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Heads-up","exampleZh":"提醒一下，调查周五截止。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you give managers a heads-up before the announcement?","zh":"能否在发布公告前提前提醒各位经理？"},"extension":{"en":"Give the service desk a heads-up about the planned outage.","zh":"提前跟服务台说一声，系统将按计划停运。"}},{"id":"HR10-24","moduleId":"m10","module":"HR商务沟通与汇报","term":"Flag an issue","zh":"指出问题／提醒关注问题","definition":"在沟通中指出某个问题，让相关人员注意并视情况处理。","example":"I want to flag an issue with the assignment timeline.","collocation":"flag an issue with the schedule","dialogue":[{"role":"HR Coordinator","en":"Can I flag an issue with the training list? Half the night shift is missing.","zh":"我提个问题，培训名单上少了一半夜班员工。"},{"role":"L&D Lead","en":"Good catch. Hold the invites while I check the list against the roster.","zh":"你发现得及时。先别发邀请，我拿排班表核对一下名单。"}],"usage":"","new":true,"order":384,"aliases":[],"distinction":"Flag an issue 是把现有问题提出来请人注意。Flag a risk 指提醒他人留意尚未发生的风险，escalate an issue 则表示将问题转交更合适的层级或负责人。","collocationZh":"指出日程安排中的问题","collocationReview":"V18.2 模型编辑复核","ipaUK":"flæɡ æn ˈɪʃuː","ipaUS":"flæɡ æn ˈɪʃuː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Flag an issue","exampleZh":"我想提醒大家关注外派时间安排上的一个问题。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Is there anything we should flag to leadership?","zh":"有没有什么问题需要向领导层提示？"},"extension":{"en":"Please flag any issues that could delay the employee data transfer.","zh":"如发现可能拖延员工数据传输的问题，请及时指出。"}},{"id":"HR10-25","moduleId":"m10","module":"HR商务沟通与汇报","term":"On the same page","zh":"理解一致／有共同认识","definition":"对信息和预期有一致理解。","example":"Let's make sure we are on the same page about the criteria.","collocation":"get on the same page","dialogue":[{"role":"Recruiter","en":"I thought references were optional for the pilot roles.","zh":"我以为试点岗位可以不做推荐人核查。"},{"role":"Hiring Manager","en":"I thought we needed two. Let’s pull up the pilot guidelines so we’re on the same page.","zh":"我以为要核查两位。我们打开试点指南核对一下，免得理解不一致。"}],"usage":"常用于表达各方对某事有一致理解，避免生硬直译为“同一页”。","new":true,"order":385,"aliases":[],"distinction":"On the same page 强调大家对工作内容、标准或预期的理解一致，常用于团队口头沟通。Agreement 更偏向就某项选择达成一致，sign-off 则涉及正式确认或批准。","collocationZh":"统一理解","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɒn ðə seɪm peɪdʒ","ipaUS":"ɑːn ðə seɪm peɪdʒ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"On the same page","exampleZh":"我们要确保对相关标准的理解保持一致。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Are we on the same page about the new grading rules?","zh":"对于新的岗位定级规则，我们是否已经达成共识？"},"extension":{"en":"Let’s get on the same page about who answers employee questions.","zh":"我们先确认一下，大家对由谁解答员工问题的理解是否一致。"}},{"id":"HR10-26","moduleId":"m10","module":"HR商务沟通与汇报","term":"Deep dive","zh":"深入分析","definition":"针对某个问题进行细致讨论或研究。","example":"We will do a deep dive into the attrition data next week.","collocation":"do a deep dive into the data","dialogue":[{"role":"People Analyst","en":"The average wait time is stable, but one site takes twice as long as the others.","zh":"平均等待时间没变，但有一个站点要花其他站点两倍的时间。"},{"role":"HR Operations Lead","en":"Let’s do a deep dive on that site. Can you break the wait down by approval stage?","zh":"我们深入看看这个站点。你能按审批环节拆分等待时间吗？"}],"usage":"较偏商务口语；正式汇报可说 detailed analysis。","new":true,"order":386,"aliases":[],"distinction":"Deep dive 表示针对一个问题作细致探查，可指分析工作或专题讨论。High-level overview 提供全貌，root cause analysis 专门追查问题的成因。","collocationZh":"深入分析数据","collocationReview":"V18.2 模型编辑复核","ipaUK":"diːp daɪv","ipaUS":"diːp daɪv","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Deep dive","exampleZh":"下周我们将深入分析员工流失数据。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Should we do a deep dive before proposing actions?","zh":"提出行动建议之前，我们应该深入分析一下吗？"},"extension":{"en":"The deep dive found a bottleneck at the offer approval stage.","zh":"深入分析后发现，发放录用通知前的审批环节存在瓶颈。"}},{"id":"HR10-27","moduleId":"m10","module":"HR商务沟通与汇报","term":"High-level overview","zh":"概览","definition":"对主题的背景、主要组成部分或整体安排作简要介绍，省略操作层面的细节。","example":"I'll start with a high-level overview of the talent strategy.","collocation":"provide a high-level overview","dialogue":[{"role":"HR Director","en":"The site leads have ten minutes with us. How much of the new process should we walk through?","zh":"站点负责人只留了十分钟。新流程要讲到什么程度？"},{"role":"HR Operations Lead","en":"I’ll give them a high-level overview and send the step-by-step guide afterward.","zh":"我会先讲整体流程，会后再把操作指南发给他们。"}],"usage":"","new":true,"order":387,"aliases":[],"distinction":"High-level overview 以简洁方式说明主题的主要部分和背景。Executive summary 通常提炼完整材料的关键发现、建议或待决策事项，二者可在同一份汇报中承担不同作用。","collocationZh":"提供概览","collocationReview":"V18.2 模型编辑复核","ipaUK":"haɪ ˈlevəl ˈəʊvəˌvjuː","ipaUS":"haɪ ˈlevəl ˈoʊvɚˌvjuː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"High-level overview","exampleZh":"我先简要介绍一下人才战略的整体情况。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can you give us a high-level overview first?","zh":"能否先做一个高层次的概览？"},"extension":{"en":"The first slide gives a high-level overview of the review process.","zh":"第一张幻灯片简要介绍了评审流程的全貌。"}},{"id":"HR10-28","moduleId":"m10","module":"HR商务沟通与汇报","term":"Bottom line","zh":"最终结论","definition":"在讨论中指最终归纳出的关键判断或实际结果，在财务语境中也可指净利润。","example":"The bottom line is that the program needs a larger budget.","collocation":"get to the bottom line","dialogue":[{"role":"HR Director","en":"We’ve heard the pros and cons. Can we staff both pilots this quarter?","zh":"利弊都听过了。本季度有足够人手同时跑两个试点吗？"},{"role":"Program Lead","en":"The bottom line is we can staff one. For the second, we’d need help from another region.","zh":"结论是人手只够一个。要做第二个，就得请另一个区域支援。"}],"usage":"在商务沟通中表示关键结论；会计场景下也可指净利润。","new":true,"order":388,"aliases":[],"distinction":"Bottom line 在讨论中引出归纳后的关键判断或实际结果，语气直接。Key takeaway 侧重希望听众带走的信息。在财务语境中，the bottom line 还可指净利润。","collocationZh":"直接说明关键结论","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈbɒtəm laɪn","ipaUS":"ˈbɑːtəm laɪn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Bottom line","exampleZh":"归根结底，这个项目需要更多预算。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the bottom line for this proposal?","zh":"这个提案最核心的结论是什么？"},"extension":{"en":"The bottom line is that we can launch in June if testing starts next week.","zh":"结论是，只要下周开始测试，我们就能在六月上线。"}},{"id":"HR10-29","moduleId":"m10","module":"HR商务沟通与汇报","term":"Data point","zh":"数据点","definition":"数据中的一项观测或数值，可以用于比较或支持分析。","example":"One data point alone is not enough to explain turnover.","collocation":"verify a data point","dialogue":[{"role":"HR Manager","en":"The East site filled that role in six days. Can we promise the same turnaround elsewhere?","zh":"东区站点六天就招到了人。其他站点也能承诺这个速度吗？"},{"role":"Recruiting Analyst","en":"That’s one data point. Let’s look at the last ten hires for that role before setting a target.","zh":"这只是一个数据点。我们先看看这个岗位最近十次招聘用了多久，再定目标。"}],"usage":"","new":true,"order":389,"aliases":[],"distinction":"Data point 指一项观察值或具体数据，例如某站点本月的离职人数。Metric 指按统一口径衡量的指标，例如离职率，同一指标可在不同时间或分组产生多个数据点。","collocationZh":"核实一条数据","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈdeɪtə pɔɪnt","ipaUS":"ˈdeɪtə pɔɪnt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Data point","exampleZh":"仅凭一个数据点不足以解释员工流失情况。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Which data points support this recommendation?","zh":"有哪些数据点支持这一建议？"},"extension":{"en":"The July figure is the first data point in the new series.","zh":"七月的数值是这个新序列里的第一个数据点。"}},{"id":"HR10-30","moduleId":"m10","module":"HR商务沟通与汇报","term":"Insight","zh":"洞察","definition":"通过分析、比较或观察获得的、能够加深对问题理解的判断。","example":"One insight from the survey was that employees wanted more specific feedback from their managers.","collocation":"actionable insight","dialogue":[{"role":"People Analyst","en":"People give the same training very different scores depending on when they joined.","zh":"同一项培训，员工的评分因入职时间而有很大差异。"},{"role":"L&D Lead","en":"That’s a useful insight. Let’s check whether people hired later missed the hands-on session.","zh":"这个发现很有用。我们查一下，后入职的人是不是没参加实操课。"}],"usage":"","new":true,"order":390,"aliases":[],"distinction":"Insight 是从证据中提炼出的、能帮助理解问题的判断。Finding 是分析直接发现的现象，recommendation 是据此提出的行动建议。","collocationZh":"可付诸行动的洞察","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈɪnsaɪt","ipaUS":"ˈɪnsaɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Insight","exampleZh":"调查揭示的一点是，员工希望直属主管给出更具体的反馈。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the most actionable insight from this report?","zh":"这份报告中最具有可操作性的洞察是什么？"},"extension":{"en":"The most useful insight came from comparing responses by tenure.","zh":"按工龄比较答复后，我们得出了最有价值的洞察。"}},{"id":"HR10-31","moduleId":"m10","module":"HR商务沟通与汇报","term":"Root cause","zh":"根本原因","definition":"使问题发生或反复出现的深层成因，一个问题可能有多个根本原因。","example":"We should investigate the root cause before changing the policy.","collocation":"root cause analysis","dialogue":[{"role":"Payroll Analyst","en":"We fixed the totals on Friday, but the same error is back this week.","zh":"周五已经改好合计金额了，但这周又出现同样的错误。"},{"role":"Payroll Lead","en":"Let’s trace where the figures first diverge. That should help us get to the root cause.","zh":"找找数字是从哪一步开始对不上的，这样才有线索找到根本原因。"}],"usage":"","new":true,"order":391,"aliases":[],"distinction":"Root cause 是使问题发生或反复出现的深层成因，可以有多个。Symptom 是可见表现，contributing factor 是促成或加剧问题的因素。","collocationZh":"根本原因分析","collocationReview":"V18.2 模型编辑复核","ipaUK":"ruːt kɔːz","ipaUS":"ruːt kɑːz","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Root cause","exampleZh":"调整政策前，我们应该先调查根本原因。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Have we identified the root cause of the delay?","zh":"我们找到延误的根本原因了吗？"},"extension":{"en":"The team tested whether a missing validation step was a root cause of the errors.","zh":"团队验证了缺少校验步骤是否是这些错误的根源之一。"}},{"id":"HR10-32","moduleId":"m10","module":"HR商务沟通与汇报","term":"Recommendation","zh":"建议方案","definition":"基于评估提出的具体行动方向。","example":"My recommendation is to pilot the policy in two markets.","collocation":"make a recommendation","dialogue":[{"role":"HR Director","en":"We can fund one change this quarter. Which would help managers most?","zh":"本季度只能拨款做一项改动。哪一项对经理帮助最大？"},{"role":"People Partner","en":"My recommendation is to fix the approval form first. It’s generating most of the support tickets.","zh":"我建议先改审批表。大部分支持工单都是由这张表引起的。"}],"usage":"","new":true,"order":392,"aliases":[],"distinction":"Recommendation 是评估后建议采取的做法，decision 是有权决策的一方作出的选择。Finding 提供事实依据，通常还要说明该依据怎样支持建议。","collocationZh":"提出建议","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌrekəmenˈdeɪʃən","ipaUS":"ˌrekəmənˈdeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Recommendation","exampleZh":"我的建议是先在两个市场试点这项政策。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is your recommendation for the next phase?","zh":"你对下一阶段有什么建议？"},"extension":{"en":"The recommendation includes an owner and a proposed start date.","zh":"这项建议明确了拟负责的人和建议启动日期。"}},{"id":"HR10-33","moduleId":"m10","module":"HR商务沟通与汇报","term":"Approval workflow","zh":"审批流程","definition":"规定申请如何提交、流转、审核和决定，并明确相应角色的流程。","example":"The approval workflow involves HR, finance and legal.","collocation":"streamline the approval workflow","dialogue":[{"role":"Hiring Manager","en":"The offer is within budget. Why is it sitting with Finance?","zh":"录用方案没有超预算，怎么还卡在财务？"},{"role":"Recruiter","en":"The approval workflow sends any signing bonus to Finance. I’ll check who has it now.","zh":"只要有签约奖金，审批流程就会送财务审核。我去看看现在在谁手上。"}],"usage":"","new":true,"order":393,"aliases":[],"distinction":"Approval workflow 说明申请由谁审核、按什么顺序流转以及遇到例外怎么处理。Sign-off 指某个节点的正式批准或确认，approval matrix 通常用于列明各类事项的审批权限。","collocationZh":"简化审批流程","collocationReview":"V18.2 模型编辑复核","ipaUK":"əˈpruːvəl ˈwɜːkfləʊ","ipaUS":"əˈpruːvəl ˈwɝːkfloʊ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Approval workflow","exampleZh":"这套审批流程涉及人力资源、财务和法务部门。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Can we simplify the approval workflow for exceptions?","zh":"能否简化例外事项的审批流程？"},"extension":{"en":"The approval workflow routes exceptions to a regional reviewer.","zh":"审批流程会把例外申请转给区域审核人。"}},{"id":"HR10-34","moduleId":"m10","module":"HR商务沟通与汇报","term":"Sign-off","zh":"正式确认／签批","definition":"由授权负责人对文件、预算或方案作出最后批准或签字确认。","example":"We need legal sign-off before sending the announcement.","collocation":"obtain final sign-off","dialogue":[{"role":"HR Coordinator","en":"Finance said the figures look fine. Can I close the ticket?","zh":"财务说数字没问题。我能关工单了吗？"},{"role":"HR Project Manager","en":"Wait until their sign-off is recorded in the ticket. Then you can close it.","zh":"等工单里记录了财务的正式确认，再关单。"}],"usage":"HR 政策、预算或项目方案常用。","new":true,"order":394,"distinction":"Sign-off 通常指由获授权人员作出的正式确认，形式可以是工单批准、电子审批或签字。Approval 用义更广，可用于中间或最终授权，informal agreement 只表示口头或非正式同意。动词写作 sign off。","aliases":[],"collocationZh":"获得最终批准","collocationReview":"V18.2 模型编辑复核","ipaUK":"saɪn ɒf","ipaUS":"saɪn ɔːf","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Sign-off","exampleZh":"发布公告前，我们需要法务正式确认。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Who gives the final sign-off on the new policy?","zh":"谁负责对新政策作最终签批？"},"extension":{"en":"We’re waiting for final sign-off on the revised handbook.","zh":"我们在等修订版手册的最终批准。"}},{"id":"HR10-35","moduleId":"m10","module":"HR商务沟通与汇报","term":"Rollout plan","zh":"推行计划","definition":"新政策或项目上线的沟通与执行安排。","example":"The rollout plan includes training for managers.","collocation":"phased rollout plan","dialogue":[{"role":"Site HR Lead","en":"We can’t train the warehouse team during stocktake. Could we go live a week later?","zh":"盘点期间没法给仓库团队做培训。我们能晚一周上线吗？"},{"role":"Program Lead","en":"Yes. I’ll move your site to the second wave in the rollout plan.","zh":"可以。我会在推行计划里把你的站点挪到第二批。"}],"usage":"","new":true,"order":395,"aliases":[],"distinction":"Rollout plan 描述新政策、系统或流程按什么顺序推向哪些群体，以及如何沟通和提供支持。Pilot plan 侧重如何小范围试验，project plan 还覆盖设计、开发等上线前的环节。","collocationZh":"分阶段推行计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈrəʊlaʊt plæn","ipaUS":"ˈroʊlaʊt plæn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Rollout plan","exampleZh":"推行计划包括面向管理者的培训。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What does the rollout plan look like across regions?","zh":"这项计划将在各地区如何推行？"},"extension":{"en":"The rollout plan gives each site two weeks to prepare.","zh":"推行计划给每个站点留了两周准备时间。"}},{"id":"HR10-36","moduleId":"m10","module":"HR商务沟通与汇报","term":"Pilot program","zh":"试点项目","definition":"先在小范围验证方案效果的项目。","example":"The pilot program will run in two offices for eight weeks.","collocation":"launch a pilot program","dialogue":[{"role":"People Partner","en":"The pilot participants want to keep using the form. Can we open it to everyone on Monday?","zh":"参加试点的人想继续用这张表。周一能向所有员工开放吗？"},{"role":"Program Lead","en":"Let’s review the pilot program results first. We still need to see how many requests had to be sent back.","zh":"先看试点结果。我们还要查一下有多少申请被退回重填。"}],"usage":"","new":true,"order":396,"aliases":[],"distinction":"Pilot program 用有限时间、范围或参与群体检验方案，结果可影响是否扩大实施。Phased rollout 分批推开已决定实施的方案，试点也可作为正式推行前的一个阶段。","collocationZh":"启动试点项目","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈpaɪlət ˈprəʊɡræm","ipaUS":"ˈpaɪlət ˈproʊɡræm","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Pilot program","exampleZh":"试点项目将在两个办公地点开展八周。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Where should we launch the pilot program?","zh":"我们应该在哪里启动试点项目？"},"extension":{"en":"The pilot program will test whether the new form reduces processing time.","zh":"试点项目将检验新表单能否缩短处理时间。"}},{"id":"HR10-37","moduleId":"m10","module":"HR商务沟通与汇报","term":"Lessons learned","zh":"经验教训","definition":"根据项目中有效或失误的做法总结出的经验和教训，供今后工作参考。","example":"We captured lessons learned after the policy rollout.","collocation":"document lessons learned","dialogue":[{"role":"Program Lead","en":"Three managers got the training link after their session had started.","zh":"有三位经理是在培训开始后才收到链接的。"},{"role":"L&D Lead","en":"Add that to the lessons learned. Next time we’ll send calendar invites a week ahead.","zh":"把这一点记进经验教训里。下次我们提前一周发日历邀请。"}],"usage":"","new":true,"order":397,"aliases":[],"distinction":"Lessons learned 指实践中总结出的经验与教训。Retrospective 或 lessons-learned session 是开展复盘的会议或活动，action items 是据此安排的后续任务。","collocationZh":"记录经验教训","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈlesənz lɜːnd","ipaUS":"ˈlesənz lɝːnd","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Lessons learned","exampleZh":"政策推行后，我们总结了经验教训。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What lessons learned should we share with the team?","zh":"我们应该与团队分享哪些复盘经验？"},"extension":{"en":"We used the lessons learned from the first launch to revise the checklist.","zh":"我们根据首次上线总结的经验教训修订了清单。"}},{"id":"HR10-38","moduleId":"m10","module":"HR商务沟通与汇报","term":"Status update","zh":"进度更新","definition":"向相关方说明当前状态与风险的沟通。","example":"The status update covers progress, risks and blockers.","collocation":"send a status update","dialogue":[{"role":"HR Director","en":"I’ve only got five minutes before the leadership call. What’s changed since Tuesday?","zh":"离领导层会议只剩五分钟了。从周二到现在有什么变化？"},{"role":"Project Manager","en":"I’ll send you a quick status update. Testing is back on track, but two sites still need training dates.","zh":"我马上发个简短的进度更新。测试已经回到正轨，但还有两个站点没定培训日期。"}],"usage":"","new":true,"order":398,"aliases":[],"distinction":"Status update 是对当前进展、风险及待办事项的简要更新，形式可以是邮件、口头说明或正式记录。Progress report 通常按约定周期较系统地汇报工作完成情况。","collocationZh":"发送进展简报","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsteɪ.təs ˈʌp.deɪt","ipaUS":"ˈsteɪ.t̬əs ˈʌp.deɪt","ipaSource":"https://dictionary.cambridge.org/dictionary/english/status | https://dictionary.cambridge.org/dictionary/english/update","speakTerm":"Status update","exampleZh":"进度更新涵盖工作进展、风险和当前障碍。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you send a status update before Friday?","zh":"能否在周五之前发送进展更新？"},"extension":{"en":"Include the revised launch date in Friday’s status update.","zh":"在周五的进度更新里写上调整后的上线日期。"}},{"id":"HR10-39","moduleId":"m10","module":"HR商务沟通与汇报","term":"Blocker","zh":"阻碍事项","definition":"使某项工作无法继续推进、需先解决的障碍。","example":"Lack of data access is the main blocker for this analysis.","collocation":"remove a blocker","dialogue":[{"role":"Project Manager","en":"Can the vendor start the import today?","zh":"供应商今天能开始导入吗？"},{"role":"HR Systems Lead","en":"There’s one blocker. The test account can read the file, but it can’t upload it.","zh":"还有一个障碍。测试账号能读取文件，但没有上传权限。"}],"usage":"","new":true,"order":399,"aliases":[],"distinction":"Blocker 是当前使某项工作无法继续的障碍。Risk 是可能发生的不利事件，dependency 是工作所依赖的事项，只有它未满足并卡住工作时才构成 blocker。","collocationZh":"排除阻碍","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈblɒkə","ipaUS":"ˈblɑːkɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Blocker","exampleZh":"缺少数据访问权限是这项分析目前面临的主要障碍。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What's the biggest blocker for the HR dashboard?","zh":"HR 看板项目面临的最大阻碍是什么？"},"extension":{"en":"The team resolved the last blocker before the data migration.","zh":"团队在数据迁移前解决了最后一个阻碍。"}},{"id":"HR10-40","moduleId":"m10","module":"HR商务沟通与汇报","term":"Stakeholder feedback","zh":"利益相关方意见","definition":"受方案影响或参与实施的相关人员或团队对方案、过程或成果提出的意见。","example":"We incorporated stakeholder feedback into the final draft.","collocation":"collect stakeholder feedback","dialogue":[{"role":"Program Lead","en":"Why did you move the employee briefing to the afternoon?","zh":"你为什么把员工说明会改到下午了？"},{"role":"Site HR Lead","en":"That came from stakeholder feedback. The shift leads said the morning slot would leave the floor short-staffed.","zh":"这是根据相关方反馈改的。班组负责人说，排上午会导致现场人手不足。"}],"usage":"","new":true,"order":400,"aliases":[],"distinction":"Stakeholder feedback 指相关方提出的评价、顾虑或建议。Stakeholder alignment 指各方形成共同理解，sign-off 则是有权限的一方正式确认或批准。","collocationZh":"收集利益相关方意见","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsteɪkhəʊldə ˈfiːdbæk","ipaUS":"ˈsteɪkˌhoʊldɚ ˈfiːdbæk","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Stakeholder feedback","exampleZh":"我们已将利益相关方的反馈纳入最终草案。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Have we collected stakeholder feedback from local HR?","zh":"我们收集到当地 HR 团队的相关方反馈了吗？"},"extension":{"en":"Summarize the stakeholder feedback before deciding what to change.","zh":"在决定改哪些内容之前，先汇总相关方的反馈。"}},{"id":"HRV6-M1-101","moduleId":"m1","module":"招聘与人才获取","term":"Application form","zh":"求职申请表／应聘申请表","definition":"候选人应聘某职位时填写的标准化个人与工作背景表单。","example":"Please complete the application form before your interview.","collocation":"complete an application form","dialogue":[{"role":"Applicant","en":"I’ve uploaded my CV, but the portal still shows my application as incomplete.","zh":"我已经上传了简历，但系统仍显示申请未完成。"},{"role":"Recruiter","en":"The application form is a separate step. Open the draft and fill in the two fields marked in red.","zh":"申请表需要另外填写。打开草稿，把标红的两个字段补上就行。"}],"usage":"与简历不同，application form 为公司统一要求填写的申请表。","distinction":"Application form 是雇主设置的标准化申请表。Job application 可指整份求职申请，包括表格和其他材料。Résumé 或 CV 通常由求职者自行编写。","aliases":[],"new":true,"order":401,"collocationZh":"填写求职申请表","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌæplɪˈkeɪʃən fɔːm","ipaUS":"ˌæpləˈkeɪʃən fɔːrm","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Application form","exampleZh":"面试前请填写应聘申请表。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"You can save the application form and return to it later.","zh":"你可以先保存申请表，稍后回来继续填写。"}},{"id":"HRV6-M1-102","moduleId":"m1","module":"招聘与人才获取","term":"Campus recruiting","zh":"校园招聘","definition":"雇主通过高校及相关线上渠道面向在校生和应届毕业生开展的招聘活动。","example":"Our campus recruiting campaign starts in September.","collocation":"campus recruiting program","dialogue":[{"role":"University Careers Adviser","en":"Our engineering fair is fully booked. Do you still want to meet students here this term?","zh":"我们的工程类招聘会展位已经订满了。你们这学期还想来校和学生见面吗？"},{"role":"Campus Recruiter","en":"Yes. We can run a CV workshop as part of our campus recruiting program.","zh":"想。我们可以把简历工作坊作为校招项目的一项活动。"}],"usage":"也常写 campus recruitment；适用于校招专场、校园宣讲等场景。","distinction":"Campus recruiting 与 campus recruitment 均可表示校园招聘。Career fair 指招聘会，是校招的一种渠道，graduate recruitment 则可覆盖通过官网等非校园渠道面向毕业生的招聘。","aliases":[],"new":true,"order":402,"collocationZh":"校园招聘项目","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkæmpəs rɪˈkruːtɪŋ","ipaUS":"ˈkæmpəs rəˈkruːtɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Campus recruiting","exampleZh":"我们的校园招聘活动将于九月启动。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"The campus recruiting team added a virtual session for students on placement.","zh":"校招团队为在外实习的学生加开了一场线上活动。"}},{"id":"HRV6-M1-103","moduleId":"m1","module":"招聘与人才获取","term":"External labor market","zh":"外部劳动力市场","definition":"企业外部劳动力的供给与需求、工资水平和人才流动等市场环境。","example":"The external labor market for experienced engineers is tight.","collocation":"analyze the external labor market","dialogue":[{"role":"Hiring Manager","en":"We’ve only had two qualified applicants in a month. Can we increase the budget?","zh":"一个月只有两位应聘者符合条件。能提高预算吗？"},{"role":"Recruiter","en":"I’ll compare our offer with the external labor market first. We may also need to widen the search area.","zh":"我先把我们的待遇和外部市场水平做个比较。可能还需要扩大招聘地域。"}],"usage":"区别于 internal labor market（企业内部人才市场）。","distinction":"External labor market 关注组织外部的劳动力供给、用工需求和工资等市场状况。Internal labor market 关注组织内部人员的流动与晋升，job board 是发布招聘信息的一种渠道。","aliases":[],"new":true,"order":403,"collocationZh":"分析外部劳动力市场","collocationReview":"V18.2 模型编辑复核","ipaUK":"ekˈstɜːnəl ˈleɪbə ˈmɑːkɪt","ipaUS":"ɪkˈstɝːnəl ˈleɪbɚ ˈmɑːrkət","ipaSource":"音素词典与英式语音规则推导","speakTerm":"External labor market","exampleZh":"经验丰富的工程师在外部人才市场上供不应求。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"We checked the external labor market before setting the pay range.","zh":"确定薪资区间前，我们调查了外部劳动力市场。"}},{"id":"HRV6-M1-104","moduleId":"m1","module":"招聘与人才获取","term":"Candidate","zh":"（招聘）候选人","definition":"招聘中被考虑或评估是否适合某个岗位的人，可能是主动应聘者，也可能由招聘团队寻访获得。","example":"We have shortlisted three candidates for the final interview.","collocation":"shortlist a candidate","dialogue":[{"role":"Hiring Manager","en":"The candidate from yesterday could be a better fit for the analyst opening. Can we discuss that with her?","zh":"昨天那位候选人可能更适合分析师岗位。我们能和她谈谈吗？"},{"role":"Recruiter","en":"I’ll ask if she’s interested before sharing her profile with the other hiring team.","zh":"我先问她有没有兴趣，再决定是否把她的资料转给另一个招聘团队。"}],"usage":"HR 最常用“候选人”，比日常“选举候选人”更符合招聘语境。","distinction":"Applicant 是已提交申请的人。Candidate 是被考虑或评估的人，也可包括由招聘团队主动接触的人。系统怎样划分申请人和候选人，取决于组织的流程。","aliases":[],"new":true,"order":404,"collocationZh":"筛选某位候选人进入下一轮","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkæn.dɪ.dət","ipaUS":"ˈkæn.dɪ.dət","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Candidate","exampleZh":"我们已选出三位候选人参加最终面试。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"The recruiter asked the candidate to bring a portfolio to the interview.","zh":"招聘专员请候选人面试时带上作品集。"}},{"id":"HRV6-M1-105","moduleId":"m1","module":"招聘与人才获取","term":"Competency model","zh":"胜任力模型","definition":"系统描述岗位、岗位族或组织所需的知识、技能和可观察行为等胜任力的框架，可用于招聘、评估与发展。","example":"The interview questions are aligned with our competency model.","collocation":"build a competency model","dialogue":[{"role":"Hiring Manager","en":"Both applicants say they’re good at handling conflict. How do we score their examples consistently?","zh":"两位应聘者都说自己擅长处理冲突。怎么用同一标准给他们的案例打分？"},{"role":"Recruiter","en":"Let’s use the conflict-management behaviors in the competency model to anchor our scores.","zh":"我们用胜任力模型里关于冲突管理的具体行为作为评分依据。"}],"usage":"常与 competency framework（胜任力框架）并用。","distinction":"Competency model 说明完成工作所需的能力及可观察的行为，并可按熟练程度分级。Job description 侧重岗位职责和工作范围，interview guide 则把相关能力转化为可用于面试的提问和评分提示。","aliases":[],"new":true,"order":405,"collocationZh":"建立胜任力模型","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkɒmpɪtənsi ˈmɒdəl","ipaUS":"ˈkɑːmpətɪnsiː ˈmɑːdəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Competency model","exampleZh":"面试问题与我们的胜任力模型相匹配。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"The competency model describes what effective coaching looks like at each level.","zh":"胜任力模型说明了不同职级上有效辅导的具体表现。"}},{"id":"HRV6-M1-106","moduleId":"m1","module":"招聘与人才获取","term":"Initial interview","zh":"初轮面试／初试","definition":"招聘流程中的第一轮面试，用于初步了解候选人的经历、能力及岗位匹配度。","example":"The initial interview will focus on your relevant experience.","collocation":"schedule an initial interview","dialogue":[{"role":"Applicant","en":"Will I need to prepare a presentation for Thursday?","zh":"周四的面试需要准备演示吗？"},{"role":"Recruiter","en":"No presentation for the initial interview. Just be ready to talk through a recent project.","zh":"首轮面试不用做演示。准备好讲一个近期参与的项目就行。"}],"usage":"","distinction":"Initial interview 指招聘流程中被列为第一轮的面试，可以由招聘人员或用人团队主持。Screening call 通常侧重快速核实基本条件，有的流程把它计入首轮，有的单独安排。","aliases":[],"new":true,"order":406,"collocationZh":"安排初轮面试","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪˈnɪʃəl ˈɪn.tə.vjuː","ipaUS":"ˌɪˈnɪʃəl ˈɪn.tɚ.vjuː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Initial interview","exampleZh":"首轮面试将重点了解您与该岗位相关的经历。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"The initial interview is scheduled for Tuesday afternoon.","zh":"首轮面试安排在周二下午。"}},{"id":"HRV6-M1-107","moduleId":"m1","module":"招聘与人才获取","term":"Job analysis","zh":"岗位分析","definition":"系统收集和分析岗位任务、职责、工作条件和任职所需能力的过程。","example":"We completed the job analysis before revising the job description.","collocation":"conduct a job analysis","dialogue":[{"role":"Hiring Manager","en":"The current description says this role owns onboarding. Does that still reflect the work?","zh":"现有说明书写着这个岗位负责入职流程。这还符合实际吗？"},{"role":"HR Partner","en":"Let’s do a job analysis with the people doing the work. I’d like to see which tasks they handle now.","zh":"我们和实际做这份工作的人一起做岗位分析。我想看看他们现在负责哪些任务。"}],"usage":"岗位分析是制定岗位说明书及任职资格标准的基础。","distinction":"Job analysis 是系统收集和分析岗位信息的过程。Job description 是可依据分析编写的岗位说明书。Job evaluation 则是评估岗位相对价值，常用于职级或薪酬管理。","aliases":[],"new":true,"order":407,"collocationZh":"开展岗位分析","collocationReview":"V18.2 模型编辑复核","ipaUK":"dʒɒb əˈnæləˌsɪs","ipaUS":"dʒɑːb əˈnæləsəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Job analysis","exampleZh":"修订岗位说明书前，我们完成了岗位分析。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"The job analysis identified tasks that had shifted to the service desk.","zh":"岗位分析发现，部分职责已转由服务台承担。"}},{"id":"HRV6-M1-108","moduleId":"m1","module":"招聘与人才获取","term":"Job requirements and qualifications","zh":"岗位要求与任职资格","definition":"招聘中对工作条件和任职人员的要求，包括技能、经验、学历、证书或执照等，可区分必备与优先条件。","example":"The job requirements and qualifications are listed in the posting.","collocation":"meet the job requirements","dialogue":[{"role":"Recruiter","en":"The draft asks for a license on day one. Is it enough for new hires to earn it during training?","zh":"草稿要求入职第一天就持证。新员工能在培训期间取得证书吗？"},{"role":"Hiring Manager","en":"For this role, yes. Update the job requirements and qualifications so applicants know they can earn it after joining.","zh":"这个岗位可以。把招聘信息里的岗位要求和任职资格改一下，让应聘者知道入职后可以取得证书。"}],"usage":"参考图中的 Job Qualification and Restriction：该表达不够地道，HR 招聘中更常使用 job requirements / qualifications。","distinction":"Job requirements 是对胜任岗位所需条件的概括，可包含经验、技能和工作安排。Qualifications 更侧重候选人具备的资历，如教育背景、专业证书或从业经验。发布招聘信息时，可明确区分必备条件和优先条件。","aliases":["Job Qualification and Restriction","任职条件和资格","Job qualifications"],"new":true,"order":408,"collocationZh":"满足岗位任职条件","collocationReview":"V18.2 模型编辑复核","ipaUK":"dʒɒb rɪˈkwaɪəmənts ænd ˌkwɒlɪfɪˈkeɪʃənz","ipaUS":"dʒɑːb rɪˈkwaɪrmənts ənd ˌkwɑːləfəˈkeɪʃənz","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Job requirements and qualifications","exampleZh":"招聘信息中列明了岗位要求与任职资格。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Should we revise the job requirements and qualifications?","zh":"我们是否需要调整岗位任职条件与资格要求？"},"extension":{"en":"Check that the job requirements and qualifications reflect the work people will actually do.","zh":"核对岗位要求和任职资格是否符合实际工作内容。"}},{"id":"HRV6-M1-109","moduleId":"m1","module":"招聘与人才获取","term":"Behavior-based interview (BBI)","zh":"行为面试（BBI）","definition":"通过请候选人描述过往实际经历中的情境、个人行动和结果，评估与岗位相关的胜任力。","example":"We use behavior-based interviews to assess problem-solving skills.","collocation":"conduct a behavior-based interview","dialogue":[{"role":"Hiring Manager","en":"My question is, “What would you do if two teams disagreed on a deadline?” Does that work here?","zh":"我想问「如果两个团队对截止日期有分歧，你会怎么做？」这题适合吗？"},{"role":"Recruiter","en":"For a behavior-based interview, ask for a time that actually happened. Then ask how they handled it.","zh":"行为面试要请对方讲一次实际发生的例子，再追问当时是怎么处理的。"}],"usage":"","distinction":"Behavior-based interview 与 behavioral interview 指同类行为面试（BBI 见于部分组织用语）。行为题请候选人讲述实际经历，情境题询问假设条件下会怎么做，STAR 是梳理或追问行为案例的框架。","aliases":["Behaviour-based interview","BBI"],"new":true,"order":409,"collocationZh":"开展行为面试","collocationReview":"V18.2 模型编辑复核","ipaUK":"bɪˈheɪ.vjə beɪst ˈɪn.tə.vjuː","ipaUS":"bɪˈheɪ.vjɚ beɪst ˈɪn.t̬ɚ.vjuː","ipaSource":"https://dictionary.cambridge.org/dictionary/english/behavior | https://dictionary.cambridge.org/dictionary/english/based | https://dictionary.cambridge.org/dictionary/english/interview","speakTerm":"Behavioral-based interview","exampleZh":"我们通过行为面试评估候选人解决问题的能力。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will we assess the candidate’s leadership skills?","zh":"我们如何评估候选人的领导力？"},"extension":{"en":"In a behavior-based interview, ask what the candidate personally did.","zh":"行为面试中，要追问候选人本人具体做了什么。"},"searchAliases":["Behavioral-based interview (BBI)"]},{"id":"HRV6-M1-110","moduleId":"m1","module":"招聘与人才获取","term":"Interview guide","zh":"面试提纲／面试指南","definition":"供面试官组织面试的文件，可包含问题、追问提示、评分标准和流程说明。","example":"Please review the interview guide before meeting the candidate.","collocation":"prepare an interview guide","dialogue":[{"role":"Panelist","en":"If a candidate skips the outcome, should I move on to the next question?","zh":"如果候选人没有讲到结果，我该直接问下一题吗？"},{"role":"Recruiter","en":"Check the interview guide. It has a prompt for that, so you can ask about the outcome before moving on.","zh":"看一下面试指南。里面有针对这种情况的追问，你可以问清结果再往下走。"}],"usage":"","distinction":"Interview guide 规定面试如何进行，可包含问题、追问提示和评分标准。Interview scorecard 侧重记录面试官的评分及依据，两者可以放在同一份文件里。","aliases":[],"new":true,"order":410,"collocationZh":"准备面试指南","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈɪn.tə.vjuː ɡaɪd","ipaUS":"ˈɪn.tɚ.vjuː ɡaɪd","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Interview guide","exampleZh":"与候选人见面前，请先查阅面试指南。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"The interview guide includes follow-up prompts for each competency.","zh":"面试指南针对每项胜任力都提供了追问提示。"}},{"id":"HRV6-M1-111","moduleId":"m1","module":"招聘与人才获取","term":"Candidate shortlist","zh":"候选人入围名单／候选人短名单","definition":"经过初步筛选、进入重点评估或面试阶段的候选人名单。","example":"The recruiter sent the candidate shortlist to the hiring manager.","collocation":"finalize a candidate shortlist","dialogue":[{"role":"Hiring Manager","en":"Can we add Maya to the interviews? I don’t see her name on the schedule.","zh":"我们能安排玛雅参加面试吗？我没在日程上看到她的名字。"},{"role":"Recruiter","en":"She’s on the candidate shortlist. I’m just waiting for her to confirm a time.","zh":"她已经入围了。我在等她确认时间。"}],"usage":"","distinction":"Candidate shortlist 是针对当前岗位经筛选后拟继续评估的人选名单。Longlist 是更宽的初步名单，talent pool 可以为多个岗位长期储备人选。","aliases":[],"new":true,"order":411,"collocationZh":"敲定候选人入围名单","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkæn.dɪ.dət ˈʃɔːt.lɪst","ipaUS":"ˈkæn.dɪ.dət ˈʃɔːrt.lɪst","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Candidate shortlist","exampleZh":"招聘专员将入围候选人名单发给了用人经理。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"We removed two names from the candidate shortlist after they withdrew.","zh":"两人退出后，我们把他们从候选人入围名单中移除了。"}},{"id":"HRV6-M1-112","moduleId":"m1","module":"招聘与人才获取","term":"Hiring decision","zh":"录用决策","definition":"根据岗位需求和评估结果，决定是否录用以及拟录用谁。","example":"We need the panel's feedback before making the hiring decision.","collocation":"make a hiring decision","dialogue":[{"role":"Recruiter","en":"Both finalists meet the requirements. Are we ready to make a hiring decision?","zh":"两位最终候选人都符合要求。现在可以作录用决定了吗？"},{"role":"Hiring Manager","en":"Let’s compare their work samples once more. The role needs someone who can explain the numbers to non-specialists.","zh":"再对比一下他们的工作样本吧。这个岗位需要能把数据讲给非专业人士听的人。"}],"usage":"","distinction":"Hiring decision 是选择录用对象、拒绝录用或决定暂不录用。Interview recommendation 是面试官提出的建议，job offer 是向候选人提出的正式录用邀约。","aliases":[],"new":true,"order":412,"collocationZh":"作出录用决策","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈhaɪərɪŋ dɪˈsɪʒən","ipaUS":"ˈhaɪrɪŋ dɪˈsɪʒən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Hiring decision","exampleZh":"作出录用决定前，我们需要面试小组的反馈。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"Record the reasons for the hiring decision in the recruitment system.","zh":"在招聘系统中记录作出录用决策的理由。"}},{"id":"HRV6-M1-113","moduleId":"m1","module":"招聘与人才获取","term":"Offer acceptance rate","zh":"录用通知接受率","definition":"在约定统计口径下，被接受的录用通知数占纳入统计的录用通知总数的比例。统计规则应说明待答复或撤回的通知如何处理。","example":"Our offer acceptance rate improved after we simplified approvals.","collocation":"track the offer acceptance rate","dialogue":[{"role":"HR Director","en":"Why did the offer acceptance rate drop on this week’s dashboard?","zh":"这周看板上的录用通知接受率为什么下降了？"},{"role":"Recruiting Analyst","en":"Three offers are still open. I’ll show the pending offers separately so you can see which candidates have responded.","zh":"有三份通知还没收到答复。我会把待答复的单列出来，方便看哪些候选人已经回复。"}],"usage":"","distinction":"Offer acceptance rate 衡量发出的录用通知有多少被接受。Offer-to-start rate 关注发出录用通知后实际入职的比例。比较不同报告时，要对齐统计期间、计数单位以及待答复通知的处理方式。","aliases":[],"new":true,"order":413,"collocationZh":"跟踪录用通知接受率","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈɒfə əkˈseptəns reɪt","ipaUS":"ˈɔːfɚ ækˈseptəns reɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Offer acceptance rate","exampleZh":"简化审批流程之后，录用通知接受率提高了。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"We report the offer acceptance rate separately for each job family.","zh":"我们按岗位族分别报告录用通知接受率。"}},{"id":"HRV6-M1-114","moduleId":"m1","module":"招聘与人才获取","term":"Candidate withdrawal","zh":"候选人退出招聘流程","definition":"候选人在招聘流程中主动退出面试或拒绝继续参与的情况。","example":"We recorded the candidate withdrawal in the ATS.","collocation":"record a candidate withdrawal","dialogue":[{"role":"Recruiting Coordinator","en":"Nina cancelled tomorrow’s interview and said she’s taken another job. Should I mark the slot as a no-show?","zh":"妮娜取消了明天的面试，说她已经接受了另一份工作。要记成面试缺席吗？"},{"role":"Recruiter","en":"Log it as a candidate withdrawal. She let us know in advance, so we can release the slot today.","zh":"记为候选人主动退出。她提前告知了我们，今天就可以把时段释放出来。"}],"usage":"","distinction":"Candidate withdrawal 指候选人主动退出招聘流程。Rejection 是招聘方淘汰候选人，offer decline 是候选人在收到录用通知后明确拒绝。系统如何区分这几类状态取决于招聘流程。","aliases":[],"new":true,"order":414,"collocationZh":"记录候选人退出招聘流程","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkæn.dɪ.dət wɪðˈdrɔːl","ipaUS":"ˈkæn.dɪ.dət wɪðˈdrɔːəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Candidate withdrawal","exampleZh":"我们已在招聘管理系统（ATS）中记录该候选人主动退出。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"Record the reason for the candidate withdrawal in the recruitment system.","zh":"在招聘系统里记录候选人退出的原因。"}},{"id":"HRV6-M1-115","moduleId":"m1","module":"招聘与人才获取","term":"Job advertisement","zh":"岗位招聘广告","definition":"为吸引求职者申请某个空缺岗位而发布的广告，通常列明岗位要点、应聘条件和申请方式。","example":"We updated the job advertisement to reflect the new salary range.","collocation":"publish a job advertisement","dialogue":[{"role":"Hiring Manager","en":"We’ve had a lot of applications from people who can’t work weekends.","zh":"不少应聘者周末没办法上班。"},{"role":"Recruiter","en":"I’ll move the weekend requirement into the first paragraph of the job advertisement.","zh":"我会把周末排班要求移到招聘广告的第一段。"}],"usage":"","distinction":"Job advertisement 与 job posting 在很多招聘场景中可互用。Advertisement 更突出吸引应聘者的宣传用途，posting 也可指仅在组织内部发布的空缺信息。Job description 则记录岗位职责及范围。","aliases":[],"new":true,"order":415,"collocationZh":"发布岗位招聘广告","collocationReview":"V18.2 模型编辑复核","ipaUK":"dʒɒb ədˈvɜːtɪsmənt","ipaUS":"dʒɑːb ædˈvɝːtəzmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Job advertisement","exampleZh":"我们更新了招聘广告，写明新的薪资区间。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"The job advertisement links directly to the application form.","zh":"这则招聘广告直接链接到求职申请表。"}},{"id":"HRV6-M1-116","moduleId":"m1","module":"招聘与人才获取","term":"Interview feedback","zh":"面试反馈／面试评价","definition":"面试官对候选人能力、表现与岗位匹配度形成的具体评价。","example":"Please submit your interview feedback by the end of the day.","collocation":"submit interview feedback","dialogue":[{"role":"Hiring Manager","en":"Your draft says he was a strong communicator. What did he do that stood out?","zh":"你的草稿说他沟通能力很强。具体哪一点让你印象深刻？"},{"role":"Panelist","en":"He explained the cost estimate without jargon. I’ll add that example to my interview feedback.","zh":"他解释成本估算时没用行话。我会把这个例子补到面试反馈里。"}],"usage":"","distinction":"Interview feedback 是对候选人面试表现的具体评价，可包括评分和支持判断的事例。Interview notes 是面试中的记录，candidate feedback 还可能指候选人对招聘流程提出的意见。","aliases":[],"new":true,"order":416,"collocationZh":"提交面试反馈","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈɪn.tə.vjuː ˈfiːdbæk","ipaUS":"ˈɪn.tɚ.vjuː ˈfiːdbæk","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Interview feedback","exampleZh":"请在今天下班前提交面试反馈。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"Keep your interview feedback tied to the selection criteria.","zh":"请围绕选拔标准撰写面试反馈。"}},{"id":"HRV6-M1-117","moduleId":"m1","module":"招聘与人才获取","term":"Pre-employment screening","zh":"入职前核验／雇用前筛查","definition":"在建立雇佣关系或正式入职前，按岗位需要及适用规则核验候选人的任职资格或相关背景。部分流程会在发出有条件录用通知后进行。","example":"Before arranging pre-employment screening, the recruiter checks the requirements for the role and location.","collocation":"complete pre-employment screening","dialogue":[{"role":"Candidate","en":"The screening portal is asking me to upload documents. What does it need for this role?","zh":"核验平台让我上传材料。这个岗位需要交哪些？"},{"role":"Recruiter","en":"I’ll send you the pre-employment screening checklist for this location. For this role, it lists your current license and two references.","zh":"我把这个工作地点适用的入职前核验清单发给你。这个岗位要提交有效执照和两位推荐人的联系方式。"}],"usage":"","distinction":"Pre-employment screening 泛指雇用或入职前的核验流程，可包含资历核验等项目。Background check 通常指其中对特定背景信息的核查。核查项目、时点及授权要求因适用法律和岗位而异。","aliases":[],"new":true,"order":417,"collocationZh":"完成入职前核验","collocationReview":"V18.2 模型编辑复核","ipaUK":"priː ɪmˈplɔɪ.mənt ˈskriːnɪŋ","ipaUS":"priː ɪmˈplɔɪ.mənt ˈskriːnɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Pre-employment screening","exampleZh":"安排入职前核验之前，招聘专员先核对该岗位及工作地点适用的要求。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"The recruiter confirmed which pre-employment screening steps applied to the role.","zh":"招聘专员确认了该岗位适用哪些入职前核验步骤。"}},{"id":"HRV6-M1-118","moduleId":"m1","module":"招聘与人才获取","term":"Applicant","zh":"求职申请人／应聘者","definition":"已针对某个职位提交应聘申请的人员。","example":"Each applicant receives a confirmation email.","collocation":"review an applicant's profile","dialogue":[{"role":"Hiring Manager","en":"Leo uploaded his résumé to our talent pool. Why isn’t he in the applicant list?","zh":"利奥已经把简历传到人才库了，为什么申请人名单里没有他？"},{"role":"Recruiter","en":"He hasn’t applied for this opening yet. The system will list him as an applicant once he submits the form.","zh":"他还没申请这个岗位。提交申请表后，系统才会把他列为应聘者。"}],"usage":"","distinction":"Applicant 指已提交申请的人。Candidate 强调正在被考虑，可能是招聘团队主动接触的人。Prospect 通常指可以继续接触的潜在人选，可能尚未申请。","aliases":[],"new":true,"order":418,"collocationZh":"审阅求职者档案","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈæp.lɪ.kənt","ipaUS":"ˈæp.lɪ.kənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Applicant","exampleZh":"每位应聘者都会收到一封确认邮件。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What is the next step in our hiring process?","zh":"我们招聘流程的下一步是什么？"},"extension":{"en":"The recruiter contacted the applicant to confirm availability.","zh":"招聘专员联系这位应聘者，确认其方便的时间。"}},{"id":"HRV6-M2-101","moduleId":"m2","module":"薪酬激励与福利","term":"Tuition reimbursement","zh":"学费报销／员工学费报销","definition":"企业福利计划按规定报销员工参加获批课程、学位项目或继续教育发生的学费。","example":"Under our policy, employees can apply for tuition reimbursement after completing an approved course.","collocation":"apply for tuition reimbursement","dialogue":[{"role":"Employee","en":"My university bill lists tuition and a separate lab fee. Should I submit both?","zh":"学校的账单把学费和实验室费用分开列了。两项都要提交吗？"},{"role":"Benefits Adviser","en":"Submit the itemized bill. I’ll check whether the lab fee is covered by our tuition reimbursement policy.","zh":"把明细账单交上来吧。我查一下公司学费报销政策是否涵盖实验室费用。"}],"usage":"通常是先完成或支付课程，再按政策凭材料报销；政策可能设置课程相关性与成绩要求。","distinction":"Tuition reimbursement 侧重员工已发生的学费支出按规定得到偿付。Tuition assistance 是更广的学费资助，可采取报销、补助或直接向学校付款等方式。","aliases":["学费补助报销","Tuition fee reimbursement","education reimbursement"],"new":true,"order":419,"collocationZh":"申请学费报销","collocationReview":"V18.2 模型编辑复核","ipaUK":"tjuˈɪʃ.ən ˌriː.ɪmˈbɜːs.mənt","ipaUS":"tuˈɪʃ.ən ˌriː.ɪmˈbɝːs.mənt","ipaSource":"词典重点校订","speakTerm":"Tuition reimbursement","exampleZh":"按我们的政策，员工完成获批课程后可申请学费报销。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Does the company offer tuition reimbursement for job-related courses?","zh":"公司是否报销与岗位相关的课程学费？"},"extension":{"en":"Attach proof of payment to your tuition reimbursement request.","zh":"申请学费报销时，请附上付款凭证。"}},{"id":"HRV6-M2-102","moduleId":"m2","module":"薪酬激励与福利","term":"Tuition assistance","zh":"员工学费资助","definition":"雇主为员工教育培训提供的财务支持，可能通过预付、补贴或报销实现。","example":"Our tuition assistance program supports job-related degree courses.","collocation":"tuition assistance program","dialogue":[{"role":"Employee","en":"My university needs payment before classes start. Do I have to cover the cost myself first?","zh":"学校要求开课前交费。我得先自己垫付吗？"},{"role":"Benefits Adviser","en":"Our tuition assistance program can pay this school directly. Send me the invoice so I can check the deadline.","zh":"我们的学费资助计划可以直接付给这所学校。把账单发给我，我核一下付款截止日期。"}],"usage":"政策有时也称 education assistance。","distinction":"Tuition assistance 泛指针对学费的资助，付款方式可以是预付、直接付给学校或向员工报销。Tuition reimbursement 明确指偿付员工已发生的学费支出。","aliases":[],"new":true,"order":420,"collocationZh":"员工学费资助计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"tʃuːˈɪʃ.ən əˈsɪs.təns","ipaUS":"tuːˈɪʃ.ən əˈsɪs.təns","ipaSource":"https://dictionary.cambridge.org/dictionary/english/tuition | https://dictionary.cambridge.org/dictionary/english/assistance","speakTerm":"Tuition assistance","exampleZh":"我们的学费资助计划覆盖与工作相关的学位课程。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you clarify how this compensation or benefit item works?","zh":"能否解释一下这项薪酬或福利项目的具体运作方式？"},"extension":{"en":"Ask whether the tuition assistance program requires approval before enrollment.","zh":"问一下学费资助计划是否要求在注册课程前获批。"}},{"id":"HRV6-M2-103","moduleId":"m2","module":"薪酬激励与福利","term":"Education assistance program","zh":"员工教育资助计划","definition":"雇主按制度支持员工教育或职业学习的福利计划，可覆盖获批的课程、学位或认证等费用。","example":"The education assistance program covers selected professional courses.","collocation":"apply through an education assistance program","dialogue":[{"role":"Employee","en":"I’m interested in a certificate course, but it isn’t part of a degree. Can I still apply for help?","zh":"我想上一门证书课程，但它不属于学位项目。还能申请资助吗？"},{"role":"Benefits Adviser","en":"Possibly. Our education assistance program covers some stand-alone courses. Send me the course link and I’ll check the list.","zh":"有可能。我们的教育资助计划涵盖部分独立课程。把课程链接发给我，我核对一下清单。"}],"usage":"","distinction":"Education assistance program 是支持员工学习的综合计划，视制度可覆盖学费、书本费或认证费用。Tuition assistance 通常专指学费资助。两种计划名称在一些雇主的制度里可能互用。","aliases":[],"new":true,"order":421,"collocationZh":"通过教育资助计划申请资助","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌedʒuːˈkeɪʃən əˈsɪstəns ˈprəʊɡræm","ipaUS":"ˌedʒəˈkeɪʃən əˈsɪstəns ˈproʊɡræm","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Education assistance program","exampleZh":"员工教育资助计划涵盖部分专业课程。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you clarify how this compensation or benefit item works?","zh":"能否解释一下这项薪酬或福利项目的具体运作方式？"},"extension":{"en":"The education assistance program lists approved courses in the HR portal.","zh":"员工教育资助计划在 HR 门户上列出了获批课程。"}},{"id":"HRV6-M2-104","moduleId":"m2","module":"薪酬激励与福利","term":"Reimbursement policy","zh":"费用报销政策","definition":"明确可报销支出、额度、审批、凭证及付款时间的公司规则。","example":"Please check the reimbursement policy before paying the course fee.","collocation":"review the reimbursement policy","dialogue":[{"role":"Employee","en":"I found a cheaper workshop, but the organizer only provides a payment confirmation. Will Finance accept it?","zh":"我找到一个更便宜的工作坊，但主办方只能提供付款确认。财务接受吗？"},{"role":"Finance Adviser","en":"Let’s check the reimbursement policy before you book. It spells out which documents we can accept.","zh":"先别预订。我们查一下报销政策，里面写明了可以接受哪些凭证。"}],"usage":"","distinction":"Reimbursement policy 规定哪些已发生支出可报、如何申请和审批。Reimbursement claim 是个人提交的一笔报销申请，expense policy 还可能规范员工怎样预订或支付。","aliases":[],"new":true,"order":422,"collocationZh":"查阅费用报销政策","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌriːɪmˈbɜːsmənt ˈpɒlɪsi","ipaUS":"ˌriːɪmˈbɝːsmənt ˈpɑːləsiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Reimbursement policy","exampleZh":"支付课程费用前，请先查看报销政策。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you clarify how this compensation or benefit item works?","zh":"能否解释一下这项薪酬或福利项目的具体运作方式？"},"extension":{"en":"The reimbursement policy sets a deadline for submitting receipts.","zh":"报销政策规定了提交收据的截止时间。"}},{"id":"HRV6-M2-105","moduleId":"m2","module":"薪酬激励与福利","term":"Benefits package","zh":"员工福利组合／福利待遇方案","definition":"雇主提供的保险、休假、学习补助等福利项目的组合，具体内容依雇主制度和适用规定而定。","example":"The benefits package includes medical coverage and learning support.","collocation":"review the benefits package","dialogue":[{"role":"Candidate","en":"I’ve seen the salary figure. Could you send me details on leave and health coverage?","zh":"我已经看到薪资金额了。能把休假和医疗保障的细则发给我吗？"},{"role":"Recruiter","en":"I’ll send the benefits package for this location, including when each benefit starts.","zh":"我会发给你这个工作地点的福利待遇说明，上面也写了各项福利何时生效。"}],"usage":"","distinction":"Benefits package 指福利项目的组合，例如保险与带薪休假。Compensation package 常指薪资、奖金和其他待遇的整体组合，是否把福利计入取决于雇主口径。","aliases":[],"new":true,"order":423,"collocationZh":"了解员工福利待遇方案","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈbenɪˌfɪts ˈpækɪdʒ","ipaUS":"ˈbenəfɪts ˈpækədʒ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Benefits package","exampleZh":"福利方案包括医疗保障和学习支持。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you clarify how this compensation or benefit item works?","zh":"能否解释一下这项薪酬或福利项目的具体运作方式？"},"extension":{"en":"The benefits package varies by work location.","zh":"福利待遇组合因工作地点而异。"}},{"id":"HRV6-M2-106","moduleId":"m2","module":"薪酬激励与福利","term":"Salary review","zh":"薪资评审／调薪评审","definition":"依据岗位、市场水平、绩效或预算等因素，评估现有薪资是否需要调整的过程。","example":"The annual salary review will take place in March.","collocation":"conduct a salary review","dialogue":[{"role":"Manager","en":"Does everyone in the salary review get an increase?","zh":"参加薪资评审的人都会加薪吗？"},{"role":"Compensation Partner","en":"Some salaries may stay the same. We’ll look at each role’s pay range and the available budget before making decisions.","zh":"有些人的薪资可能会维持原样。作决定前我们会逐一考虑岗位薪资区间和可用预算。"}],"usage":"","distinction":"Salary review 是检查现行薪资并评估是否调整的过程，结果可以是维持原薪。Salary increase 是加薪结果，market adjustment 则指依据外部市场薪资水平作出的调整。","aliases":[],"new":true,"order":424,"collocationZh":"开展薪资评审","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsæl.ər.i rɪˈvjuː","ipaUS":"ˈsæl.ɚ.i riːˈvjuː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Salary review","exampleZh":"年度薪资评审将于三月进行。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you clarify how this compensation or benefit item works?","zh":"能否解释一下这项薪酬或福利项目的具体运作方式？"},"extension":{"en":"Market pay data will inform the next salary review.","zh":"市场薪资数据将为下一轮薪资评审提供参考。"}},{"id":"HRV6-M2-107","moduleId":"m2","module":"薪酬激励与福利","term":"Pay slip","zh":"工资单／薪资明细单","definition":"按发薪周期列示应发工资、税费及其他扣款、实发金额等内容的凭单。","example":"Employees can download their pay slips from the HR portal.","collocation":"download a pay slip","dialogue":[{"role":"Employee","en":"My bank deposit is lower this month. Where can I see what was deducted?","zh":"我这个月到账少了。去哪里看扣了哪些钱？"},{"role":"Payroll Specialist","en":"Open this month’s pay slip and look under deductions. I can help you check any line you don’t recognize.","zh":"打开本月工资单看扣款栏。哪一项看不明白，我可以帮你核对。"}],"usage":"也写 payslip，英语国家和地区使用习惯不同。","distinction":"Pay slip 也写作 payslip，指列明应发工资、扣款和实发金额的凭单。美式英语也常说 pay stub。Payroll 指薪资核算及发放流程，也可指工资名册。","aliases":[],"new":true,"order":425,"collocationZh":"下载工资单","collocationReview":"V18.2 模型编辑复核","ipaUK":"peɪ slɪp","ipaUS":"peɪ slɪp","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Pay slip","exampleZh":"员工可以从人力资源门户下载工资单。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you clarify how this compensation or benefit item works?","zh":"能否解释一下这项薪酬或福利项目的具体运作方式？"},"extension":{"en":"Keep a copy of your final pay slip for your records.","zh":"请留存最后一期工资单。"}},{"id":"HRV6-M2-108","moduleId":"m2","module":"薪酬激励与福利","term":"Salary increase","zh":"加薪／基本薪资上调","definition":"员工基本薪资提高，可因绩效、晋升或市场调整等发生。","example":"The salary increase will take effect next month.","collocation":"approve a salary increase","dialogue":[{"role":"Employee","en":"The letter lists a bonus and a salary increase. Which one changes my monthly base pay?","zh":"信里既有奖金又有加薪。哪一项会改变我的每月基本工资？"},{"role":"HR Partner","en":"The salary increase changes your base pay. The bonus will appear as a separate payment.","zh":"加薪会改变基本工资。奖金会作为一笔单独的款项列出。"}],"usage":"","distinction":"Salary increase 指基本薪资上调，原因可以是绩效、晋升或市场调整。Salary adjustment 用义更广，也可能是下调。One-time bonus 是一次性支付，通常不改变基本薪资。","aliases":[],"new":true,"order":426,"collocationZh":"批准加薪","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsæl.ər.i ˈɪn.kriːs","ipaUS":"ˈsæl.ɚ.i ˈɪn.kriːs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Salary increase","exampleZh":"此次加薪将于下个月生效。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Market adjustment","note":"依据外部市场薪酬水平调整薪资，主要关注市场竞争力；不以个人绩效为主要依据，但可与绩效调薪同时实施。","relation":"易混淆"},{"term":"Merit increase","note":"依据个人绩效决定的加薪。","relation":"易混淆"},{"term":"Salary increase","note":"泛指薪资上涨，不限定原因。","relation":"本词"},{"term":"Promotion increase","note":"因晋升而上调基本薪资，是否加薪及金额取决于适用政策。","relation":"易混淆"},{"term":"Cost-of-living adjustment (COLA)","note":"依据生活成本变化调整薪资。","relation":"易混淆"},{"term":"Annual increment","note":"年度常规加薪，是否与绩效挂钩取决于制度。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Could you clarify how this compensation or benefit item works?","zh":"能否解释一下这项薪酬或福利项目的具体运作方式？"},"extension":{"en":"The letter confirms the amount and effective date of your salary increase.","zh":"信中确认了你的加薪金额和生效日期。"}},{"id":"HRV6-M2-109","moduleId":"m2","module":"薪酬激励与福利","term":"Promotion increase","zh":"晋升加薪","definition":"雇主依据薪资政策，在员工晋升时对其基本薪资作出的上调。","example":"In this case, the promotion increase takes effect on the promotion date.","collocation":"calculate a promotion increase","dialogue":[{"role":"Manager","en":"Sam is moving up a grade just before the annual review. Where do I enter the pay change?","zh":"萨姆将在年度评审前升一级。薪资变动要填在哪里？"},{"role":"Compensation Partner","en":"Enter the promotion increase on the promotion form. We track any merit increase separately.","zh":"把晋升加薪填在晋升表上。绩效加薪如果有，要另行记录。"}],"usage":"","distinction":"Promotion increase 指因晋升带来的基本薪资上调。Merit increase 主要依据个人绩效，market adjustment 主要依据同类岗位的外部薪资水平。是否有晋升加薪以及加多少，取决于适用政策。","aliases":[],"new":true,"order":427,"collocationZh":"计算晋升加薪金额","collocationReview":"V18.2 模型编辑复核","ipaUK":"prəˈməʊʃən ˈɪn.kriːs","ipaUS":"prəˈmoʊʃən ˈɪn.kriːs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Promotion increase","exampleZh":"这次晋升加薪与晋升在同一天生效。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Market adjustment","note":"依据外部市场薪酬水平调整薪资，主要关注市场竞争力；不以个人绩效为主要依据，但可与绩效调薪同时实施。","relation":"易混淆"},{"term":"Merit increase","note":"依据个人绩效决定的加薪。","relation":"易混淆"},{"term":"Salary increase","note":"泛指薪资上涨，不限定原因。","relation":"易混淆"},{"term":"Promotion increase","note":"因晋升而上调基本薪资，是否加薪及金额取决于适用政策。","relation":"本词"},{"term":"Cost-of-living adjustment (COLA)","note":"依据生活成本变化调整薪资。","relation":"易混淆"},{"term":"Annual increment","note":"年度常规加薪，是否与绩效挂钩取决于制度。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Could you clarify how this compensation or benefit item works?","zh":"能否解释一下这项薪酬或福利项目的具体运作方式？"},"extension":{"en":"The promotion increase was calculated using the new grade’s pay range.","zh":"晋升加薪金额按新职级的薪资区间计算。"}},{"id":"HRV6-M2-110","moduleId":"m2","module":"薪酬激励与福利","term":"Cost-of-living adjustment (COLA)","zh":"生活成本调整（COLA）","definition":"为应对生活成本变化而作的工资或津贴调整，具体机制依制度。","example":"The company approved a cost-of-living adjustment for eligible employees.","collocation":"apply a cost-of-living adjustment","dialogue":[{"role":"Employee","en":"The notice mentions a COLA. Is that tied to my performance rating?","zh":"通知提到了生活成本调整。它和我的绩效等级挂钩吗？"},{"role":"Compensation Partner","en":"Under our plan, the COLA is based on a published price index. Merit increases go through a separate review.","zh":"按公司的计划，生活成本调整依据公开发布的价格指数。绩效加薪有单独的评审流程。"}],"usage":"","distinction":"Cost-of-living adjustment 依据生活成本变动，通常参考指定的价格指数。Market adjustment 比较外部同类岗位的薪资水平，merit increase 依据个人绩效。计算方法和适用对象取决于具体计划。","aliases":[],"new":true,"order":428,"collocationZh":"实施生活成本调整","collocationReview":"V18.2 模型编辑复核","ipaUK":"kɒst ɒv ˈlɪvɪŋ əˈdʒʌstmənt","ipaUS":"kɑːst ʌv ˈlɪvɪŋ əˈdʒʌstmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Cost-of-living adjustment","exampleZh":"公司批准按生活成本变化为符合条件的员工调整薪资。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Market adjustment","note":"依据外部市场薪酬水平调整薪资，主要关注市场竞争力；不以个人绩效为主要依据，但可与绩效调薪同时实施。","relation":"易混淆"},{"term":"Merit increase","note":"依据个人绩效决定的加薪。","relation":"易混淆"},{"term":"Salary increase","note":"泛指薪资上涨，不限定原因。","relation":"易混淆"},{"term":"Promotion increase","note":"因晋升而上调基本薪资，是否加薪及金额取决于适用政策。","relation":"易混淆"},{"term":"Cost-of-living adjustment (COLA)","note":"依据生活成本变化调整薪资。","relation":"本词"},{"term":"Annual increment","note":"年度常规加薪，是否与绩效挂钩取决于制度。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Could you clarify how this compensation or benefit item works?","zh":"能否解释一下这项薪酬或福利项目的具体运作方式？"},"extension":{"en":"Check which price index the plan uses to calculate the COLA.","zh":"查一下该计划用哪个价格指数计算生活成本调整幅度。"}},{"id":"HRV6-M2-111","moduleId":"m2","module":"薪酬激励与福利","term":"Bonus eligibility","zh":"奖金资格／奖金领取资格","definition":"员工是否符合奖金计划规定的参与或发放条件，具体取决于适用计划条款及相关规定。","example":"Under this plan, bonus eligibility depends on an employee’s status at the end of the quarter.","collocation":"confirm bonus eligibility","dialogue":[{"role":"Manager","en":"Ravi moved to Sales halfway through the quarter. Which plan should I use for him?","zh":"拉维在季度过半时转到了销售部。他该按哪个计划算？"},{"role":"Compensation Partner","en":"I’ll check his bonus eligibility under both plans. The transfer date may affect which one applies.","zh":"我会核对他在两项计划下的奖金资格。转岗日期可能影响适用的计划。"}],"usage":"","distinction":"Bonus eligibility 说明员工是否有资格参与计划或被纳入发放范围。Bonus entitlement 在某些合同或法律语境下涉及领取权利，bonus payout 指最终发放的金额。具备资格后，是否发放及发放多少仍取决于计划条款和适用规定。","aliases":[],"new":true,"order":429,"collocationZh":"确认奖金领取资格","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈbəʊ.nəs ˌelɪdʒəˈbɪlɪti","ipaUS":"ˈboʊ.nəs ˌelɪdʒəˈbɪlɪtiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Bonus eligibility","exampleZh":"按这项计划，奖金资格取决于员工在季度末的任职状态。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you clarify how this compensation or benefit item works?","zh":"能否解释一下这项薪酬或福利项目的具体运作方式？"},"extension":{"en":"The plan sets out how bonus eligibility is assessed for new hires.","zh":"该计划说明了如何认定新员工的奖金资格。"}},{"id":"HRV6-M2-112","moduleId":"m2","module":"薪酬激励与福利","term":"Total cash compensation","zh":"现金薪酬总额","definition":"指定期间内的基本工资与纳入统计口径的现金奖金、佣金等现金薪酬之和，可按目标额或实发额列示。","example":"The offer includes a breakdown of total cash compensation.","collocation":"calculate total cash compensation","dialogue":[{"role":"Candidate","en":"Does the figure at the top include the stock grant?","zh":"顶部的金额里包括授予的股票吗？"},{"role":"Recruiter","en":"That’s your target total cash compensation. It combines base salary and the target bonus. The equity grant is listed below.","zh":"那是你的目标现金薪酬总额，由基本工资和目标奖金组成。股权授予单独列在下面。"}],"usage":"","distinction":"Total cash compensation 合计基本工资与计入口径的现金奖金、佣金等。Base salary 只计固定基本工资，total rewards 还可包含股权、福利及其他回报。比较报价时，先确认奖金按目标值还是实际发放额计入。","aliases":[],"new":true,"order":430,"collocationZh":"计算现金薪酬总额","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtəʊtəl kæʃ ˌkɒmpənˈseɪʃən","ipaUS":"ˈtoʊtəl kæʃ ˌkɑːmpənˈseɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Total cash compensation","exampleZh":"录用方案列明了现金薪酬总额的构成。","meaningReview":"HR场景校订","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Base salary","note":"固定基本薪资，不含浮动奖金。","relation":"易混淆"},{"term":"Gross salary","note":"扣税及其他扣款前的薪资。","relation":"易混淆"},{"term":"Net pay","note":"扣除税费等后的实发薪资。","relation":"易混淆"},{"term":"Total cash compensation","note":"固定及浮动现金薪酬，不含非现金福利。","relation":"本词"},{"term":"Total rewards","note":"涵盖薪酬、福利及其他回报。","relation":"易混淆"},{"term":"Compensation package","note":"薪酬待遇组合，具体范围取决于企业。","relation":"易混淆"},{"term":"Variable pay","note":"随绩效或其他条件变化的薪酬。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Could you clarify how this compensation or benefit item works?","zh":"能否解释一下这项薪酬或福利项目的具体运作方式？"},"extension":{"en":"Separate target and actual total cash compensation in the report.","zh":"在报告中分别列示目标现金薪酬总额和实际现金薪酬总额。"}},{"id":"HRV6-M2-113","moduleId":"m2","module":"薪酬激励与福利","term":"Employee stock purchase plan (ESPP)","zh":"员工股票购买计划","definition":"允许符合条件的员工按计划规则购买公司股票的安排，参与资格、付款方式和购买条件依计划而定。","example":"Eligible employees can enroll in the company’s employee stock purchase plan during the enrollment period.","collocation":"enroll in an employee stock purchase plan","dialogue":[{"role":"Employee","en":"If I enroll today, will I own shares as soon as the first deduction appears on my payslip?","zh":"如果今天报名，工资单上出现第一笔扣款后，我就持有股票了吗？"},{"role":"Equity Plan Administrator","en":"In our ESPP, deductions build up until the purchase date. You can find that date in the plan summary.","zh":"按我们的员工股票购买计划，扣款会累积，到购买日才用于买入股票。日期可以在计划概要里查到。"}],"usage":"","distinction":"Employee stock purchase plan 允许员工按计划规则买入公司股票，部分计划设有折扣或通过工资扣款缴费。Stock option 授予员工在规定条件下按约定价格买入股票的权利。计划资格、折扣和税务处理因计划及司法辖区而异。","aliases":[],"new":true,"order":431,"collocationZh":"参加员工股票购买计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː stɒk ˈpɜːtʃɪs plæn","ipaUS":"ɪmˈplɔɪ.iː stɑːk ˈpɝːtʃəs plæn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee stock purchase plan","exampleZh":"符合条件的员工可在报名期内参加公司的员工股票购买计划。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you clarify how this compensation or benefit item works?","zh":"能否解释一下这项薪酬或福利项目的具体运作方式？"},"extension":{"en":"Check the purchase dates before enrolling in the ESPP.","zh":"参加员工股票购买计划前，请先查看股票购买日期。"}},{"id":"HRV6-M2-114","moduleId":"m2","module":"薪酬激励与福利","term":"Dependent care assistance","zh":"受扶养人照护支持／家属照护补助","definition":"雇主为照护符合条件的子女或其他受扶养人提供的支持，可采取费用补助、报销或提供照护服务等形式，具体依计划及适用规定。","example":"The benefits team introduced dependent care assistance this year.","collocation":"apply for dependent care assistance","dialogue":[{"role":"Employee","en":"My child starts an after-school program next month. Does our benefit cover it?","zh":"我的孩子下个月要参加课后托管。公司的福利能补助这笔费用吗？"},{"role":"Benefits Adviser","en":"Send me the program details. I’ll check the provider and expense rules for our dependent care assistance plan.","zh":"把托管项目的资料发给我。我帮你核对照护支持计划对服务机构和费用的要求。"}],"usage":"","distinction":"Dependent care assistance 指雇主为受扶养人照护提供的支持，可包含费用补助等安排。Dependent care FSA 是美国部分雇主提供的一种照护费用账户安排。医疗保险家属保障则侧重医疗费用。","aliases":[],"new":true,"order":432,"collocationZh":"申请受扶养人照护支持","collocationReview":"V18.2 模型编辑复核","ipaUK":"dɪˈpendənt keə əˈsɪstəns","ipaUS":"dɪˈpendənt ker əˈsɪstəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Dependent care assistance","exampleZh":"福利团队今年推出了受扶养人照护支持项目。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you clarify how this compensation or benefit item works?","zh":"能否解释一下这项薪酬或福利项目的具体运作方式？"},"extension":{"en":"The dependent care assistance policy lists the types of care it covers.","zh":"受扶养人照护支持政策列出了涵盖的照护类型。"}},{"id":"HRV6-M2-115","moduleId":"m2","module":"薪酬激励与福利","term":"Wellness allowance","zh":"员工健康津贴","definition":"雇主依据政策为健身、身心健康活动等合资格支出提供的津贴或补助。","example":"Employees can use the wellness allowance for eligible fitness activities.","collocation":"claim a wellness allowance","dialogue":[{"role":"Employee","en":"I’m signing up for a swimming class. Is that on the approved list?","zh":"我准备报个游泳班。这项在获批清单上吗？"},{"role":"Benefits Adviser","en":"Check the fitness section of our wellness allowance policy. If the class is listed, keep the receipt for your claim.","zh":"看一下公司健康津贴政策里的健身类别。如果清单里有这项，留好收据报销。"}],"usage":"","distinction":"Wellness allowance 通常按雇主政策支持健身、身心健康活动等支出。Health insurance 按保险条款提供医疗保障，wellness program 则可涵盖团体活动、课程或咨询等更广泛的安排。","aliases":[],"new":true,"order":433,"collocationZh":"申领员工健康津贴","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈwelnəs əˈlaʊəns","ipaUS":"ˈwelnəs əˈlaʊəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Wellness allowance","exampleZh":"员工可将健康津贴用于符合规定的健身活动。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you clarify how this compensation or benefit item works?","zh":"能否解释一下这项薪酬或福利项目的具体运作方式？"},"extension":{"en":"The wellness allowance has a separate annual limit.","zh":"健康津贴单独设有年度额度上限。"}},{"id":"HRV6-M2-116","moduleId":"m2","module":"薪酬激励与福利","term":"Payroll deduction","zh":"工资扣款／工资代扣款项","definition":"工资核算时按适用规定或有效授权从应发工资中扣除的款项，例如代扣税款或由员工承担的福利缴费。","example":"Check that the payroll deduction matches the amount on the benefits enrollment form.","collocation":"verify a payroll deduction","dialogue":[{"role":"Employee","en":"My payslip shows two deductions for the dental plan. Could one be from last month?","zh":"工资单上有两笔牙科保险扣款。有一笔可能是上个月的吗？"},{"role":"Payroll Specialist","en":"I’ll check the effective date and the previous payslip before we make any changes to the payroll deduction.","zh":"调整工资扣款前，我会先核对保险生效日期和上一期工资单。"}],"usage":"","distinction":"Payroll deduction 指通过工资核算从应发工资扣除的款项，例如税款代扣或员工承担的福利缴费。Withholding 常用于雇主代扣税款等特定语境，employer contribution 则指雇主承担的缴费。","aliases":[],"new":true,"order":434,"collocationZh":"核对一项工资扣款","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈpeɪrəʊl dɪˈdʌkʃən","ipaUS":"ˈpeɪroʊl dɪˈdʌkʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Payroll deduction","exampleZh":"请核对工资扣款金额是否与福利登记表上的金额一致。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you clarify how this compensation or benefit item works?","zh":"能否解释一下这项薪酬或福利项目的具体运作方式？"},"extension":{"en":"The payroll deduction appears as a separate line on each payslip.","zh":"这项工资扣款在每期工资单上都单独列出。"}},{"id":"HRV6-M3-101","moduleId":"m3","module":"绩效管理","term":"Performance appraisal","zh":"员工绩效考核／评价","definition":"根据岗位目标和绩效标准对员工在一定周期的工作表现作出正式评价。","example":"The annual performance appraisal includes an assessment by the employee’s manager.","collocation":"complete a performance appraisal","dialogue":[{"role":"Manager","en":"Taylor worked on a different team for the first half of the year. Should I include that work?","zh":"泰勒上半年在另一个团队工作。那段工作也要纳入考核吗？"},{"role":"HR Partner","en":"Yes, the performance appraisal covers the whole cycle. Ask the previous manager for examples tied to the agreed goals.","zh":"要。这次绩效考核覆盖整个周期。请前任主管提供与约定目标相关的具体案例。"}],"usage":"","distinction":"Performance appraisal 指按一定周期和标准作出的正式绩效评价，常形成记录或评级。Performance feedback 可以随工作即时给出，performance management 还包括目标设定、辅导及进度跟进。","aliases":[],"new":true,"order":435,"collocationZh":"完成员工绩效考核","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈfɔːməns əˈpreɪzəl","ipaUS":"pɚˈfɔːrməns əˈpreɪzəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Performance appraisal","exampleZh":"年度绩效考核包括直属主管对员工表现的评估。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we handle this in the performance cycle?","zh":"在本轮绩效周期中，我们应该如何处理这件事？"},"extension":{"en":"The performance appraisal draws on examples from the full review period.","zh":"绩效考核参考整个考核周期内的工作实例。"}},{"id":"HRV6-M3-102","moduleId":"m3","module":"绩效管理","term":"Performance feedback","zh":"绩效反馈","definition":"根据具体工作行为或结果，向员工说明表现及其影响，肯定有效做法或讨论改进方向的沟通。","example":"Managers should provide specific performance feedback throughout the year.","collocation":"give performance feedback","dialogue":[{"role":"Manager","en":"Can I give you some performance feedback on yesterday’s handover? The summary was clear, but the open cases didn’t have owners.","zh":"我能就昨天的交接给你一点绩效反馈吗？摘要写得很清楚，但没标出未结事项由谁负责。"},{"role":"Employee","en":"That explains why the new shift called me. I’ll add an owner to each case next time.","zh":"难怪接班的人给我打电话。下次我会给每项事情都标上负责人。"}],"usage":"","distinction":"Performance feedback 是围绕工作表现、影响和改进方向的具体反馈，可以由主管或其他合作方提供。Coaching 通常侧重引导对方探索做法或练习改进，performance rating 则是按尺度给出的评价等级。","aliases":[],"new":true,"order":436,"collocationZh":"提供绩效反馈","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈfɔːməns ˈfiːdbæk","ipaUS":"pɚˈfɔːrməns ˈfiːdbæk","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Performance feedback","exampleZh":"管理者应在全年持续提供具体的绩效反馈。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we handle this in the performance cycle?","zh":"在本轮绩效周期中，我们应该如何处理这件事？"},"extension":{"en":"Good performance feedback links a specific behavior to its impact.","zh":"有效的绩效反馈会说明某个具体行为产生了什么影响。"}},{"id":"HRV6-M3-103","moduleId":"m3","module":"绩效管理","term":"Rating distribution","zh":"绩效等级分布","definition":"各个绩效等级中员工人数或占比的分布情况。","example":"HR reviewed the rating distribution before calibration.","collocation":"review the rating distribution","dialogue":[{"role":"Business Leader","en":"Two teams have very different rating distributions. Should we adjust the scores?","zh":"两个团队的绩效等级分布差异很大。需要调整评级吗？"},{"role":"HR Partner","en":"Let’s see how each team applied the criteria first. The distribution tells us where to look, and we can review the evidence from there.","zh":"先看看各团队如何应用评分标准。分布可以指引我们从哪里查起，然后再看具体依据。"}],"usage":"","distinction":"Rating distribution 描述各绩效等级的人数或占比，可以报告实际分布或显示拟评级分布。Forced distribution 是要求等级人数或比例符合预设分配规则的办法。","aliases":[],"new":true,"order":437,"collocationZh":"查看绩效等级分布","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈreɪtɪŋ ˌdɪstrɪˈbjuːʃən","ipaUS":"ˈreɪtɪŋ ˌdɪstrəˈbjuːʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Rating distribution","exampleZh":"人力资源团队在绩效校准前检查了各等级的分布情况。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we handle this in the performance cycle?","zh":"在本轮绩效周期中，我们应该如何处理这件事？"},"extension":{"en":"The rating distribution shows that most employees received the middle rating.","zh":"绩效等级分布显示，多数员工被评为中间等级。"}},{"id":"HRV6-M3-104","moduleId":"m3","module":"绩效管理","term":"Forced distribution","zh":"绩效强制分布法","definition":"要求将员工以预设人数、比例或区间分配到各绩效等级的评价办法。","example":"The company decided not to use forced distribution this year.","collocation":"use forced distribution","dialogue":[{"role":"Manager","en":"We have five people who meet the criteria for the top rating. Do I have to cut that number to two?","zh":"我们有五个人符合最高等级的标准。我必须减到两个吗？"},{"role":"HR Partner","en":"Our policy doesn’t use forced distribution. Bring the evidence for all five to calibration so we can check the criteria consistently.","zh":"我们公司的政策不采用强制分布。把这五个人的依据都带到校准会上，我们按统一标准核对。"}],"usage":"","distinction":"Forced distribution 要求各绩效等级的人数或占比符合预设规则。Forced ranking 强制按相对表现给员工排顺序，两者可结合使用。Calibration 旨在统一评价尺度，是否设有配额取决于制度。","aliases":[],"new":true,"order":438,"collocationZh":"采用绩效强制分布法","collocationReview":"V18.2 模型编辑复核","ipaUK":"fɔːst ˌdɪstrɪˈbjuːʃən","ipaUS":"fɔːrst ˌdɪstrəˈbjuːʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Forced distribution","exampleZh":"公司决定今年不采用强制分布法。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we handle this in the performance cycle?","zh":"在本轮绩效周期中，我们应该如何处理这件事？"},"extension":{"en":"A mandatory cap on top ratings is one form of forced distribution.","zh":"为最高绩效等级设置强制人数或比例上限，是强制分布的一种做法。"}},{"id":"HRV6-M3-105","moduleId":"m3","module":"绩效管理","term":"Performance objective","zh":"绩效目标","definition":"在绩效周期内对员工或团队明确设定的工作成果与要求。","example":"Each performance objective should have clear success criteria.","collocation":"set a performance objective","dialogue":[{"role":"Employee","en":"My draft objective says “improve onboarding.” Is that specific enough?","zh":"我的目标草稿写着「改善入职流程」。这够具体吗？"},{"role":"Manager","en":"Let’s make the performance objective more concrete. Aim to reduce new-hire setup time to two days by the end of June.","zh":"我们把绩效目标定得更具体些。争取在六月底前把为新员工开通账号、配齐设备的时间缩短到两天。"}],"usage":"","distinction":"Performance objective 说明员工或团队在考核周期中应达成什么。Performance metric 是衡量进度或结果的指标。一个目标可以结合多项指标或完成标准。","aliases":[],"new":true,"order":439,"collocationZh":"设定绩效目标","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈfɔːməns ɒbˈdʒektɪv","ipaUS":"pɚˈfɔːrməns əbˈdʒektɪv","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Performance objective","exampleZh":"每项绩效目标都应有明确的达成标准。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we handle this in the performance cycle?","zh":"在本轮绩效周期中，我们应该如何处理这件事？"},"extension":{"en":"Set a performance objective that measures response quality as well as speed.","zh":"设定绩效目标时，兼顾答复质量和速度。"}},{"id":"HRV6-M3-106","moduleId":"m3","module":"绩效管理","term":"Key result","zh":"关键结果（OKR）","definition":"用于衡量目标是否实现的可验证结果，属于 OKR 框架的一部分。","example":"We revised the key result to include a clear metric.","collocation":"define a key result","dialogue":[{"role":"Operations Lead","en":"One draft key result says “redesign the request form.” How will we know it worked?","zh":"有一条关键结果写的是「重新设计申请表」。我们怎么知道这项工作有没有效果？"},{"role":"People Analyst","en":"Let’s measure the outcome. Make the key result “Reduce the share of incomplete submissions from 20% to 5% by quarter-end.”","zh":"我们来衡量实际效果。把关键结果改成「在季度末前将不完整申请的比例从 20% 降到 5%」。"}],"usage":"","distinction":"在 OKR 中，objective 描述想实现的方向，key result 说明到期时用什么可验证结果判断目标是否达成。Initiative 是为实现目标开展的工作，KPI 则常用于持续监测某项表现。","aliases":[],"new":true,"order":440,"collocationZh":"设定关键结果","collocationReview":"V18.2 模型编辑复核","ipaUK":"kiː rɪˈzʌlt","ipaUS":"kiː rɪˈzʌlt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Key result","exampleZh":"我们修订了关键结果，加入明确的衡量指标。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we handle this in the performance cycle?","zh":"在本轮绩效周期中，我们应该如何处理这件事？"},"extension":{"en":"A key result should make progress toward the objective measurable.","zh":"关键结果应让人能够衡量距离目标还有多远。"}},{"id":"HRV6-M3-107","moduleId":"m3","module":"绩效管理","term":"Performance evidence","zh":"绩效事实依据","definition":"支撑绩效评价的具体工作成果、数据与可核实行为记录。","example":"The manager collected performance evidence before the review.","collocation":"document performance evidence","dialogue":[{"role":"Manager","en":"I was going to write that Daria communicates well. Will that support the rating?","zh":"我本来想写达莉娅沟通能力强。这能支撑评级吗？"},{"role":"HR Partner","en":"Add performance evidence. For example, note how her handover checklist helped the next shift resolve open cases.","zh":"补上绩效事实依据。比如，写清她的交接清单怎样帮助接班的人处理未结事项。"}],"usage":"","distinction":"Performance evidence 是能核对的事实依据，例如交付记录、数据或具体行为事例。Performance rating 是依据评价标准作出的判断，总体印象或笼统评价需要有事实支持。","aliases":[],"new":true,"order":441,"collocationZh":"记录绩效事实依据","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈfɔːməns ˈevɪdəns","ipaUS":"pɚˈfɔːrməns ˈevədəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Performance evidence","exampleZh":"经理在绩效评估前收集了绩效事实依据。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we handle this in the performance cycle?","zh":"在本轮绩效周期中，我们应该如何处理这件事？"},"extension":{"en":"Use performance evidence from across the review period.","zh":"使用覆盖整个绩效周期的事实依据。"}},{"id":"HRV6-M3-108","moduleId":"m3","module":"绩效管理","term":"Goal achievement rate","zh":"目标达成率","definition":"按预先约定的公式衡量一个或多个目标完成程度的比率，常用百分比表示。","example":"The goal achievement rate is one input into the review.","collocation":"calculate the goal achievement rate","dialogue":[{"role":"Employee","en":"We completed eight out of ten migrations. Why does the dashboard show a goal achievement rate below 80%?","zh":"十项迁移我们完成了八项，为什么看板上的目标达成率不到 80%？"},{"role":"Manager","en":"This dashboard weights projects by site size. The two largest sites are still outstanding.","zh":"这个看板按站点规模给项目加权。最大的两个站点还没完成。"}],"usage":"","distinction":"Goal achievement rate 按约定口径计算目标达成程度。对于可直接按比例衡量的单项目标，可以用实际结果除以目标值。跨目标汇总时，还需明确权重、封顶规则以及数值越低越好的指标如何计分。Performance rating 是综合判断，可能同时考虑行为和其他因素。","aliases":[],"new":true,"order":442,"collocationZh":"计算目标达成率","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɡəʊl əˈtʃiːvmənt reɪt","ipaUS":"ɡoʊl əˈtʃiːvmənt reɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Goal achievement rate","exampleZh":"目标达成率是绩效评估的参考因素之一。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we handle this in the performance cycle?","zh":"在本轮绩效周期中，我们应该如何处理这件事？"},"extension":{"en":"Check whether the goal achievement rate is capped at 100%.","zh":"确认目标达成率是否以 100% 为上限。"}},{"id":"HRV6-M3-109","moduleId":"m3","module":"绩效管理","term":"Mid-year performance review","zh":"年中绩效回顾／年中绩效评估","definition":"在绩效年度中段回顾目标进展、工作成果和后续安排，可按组织流程调整目标或作中期评价。","example":"The mid-year performance review will include development goals.","collocation":"hold a mid-year performance review","dialogue":[{"role":"Employee","en":"Two projects were cancelled after we set my goals. Should I still report against them?","zh":"定目标后有两个项目取消了。我还要按原目标汇报吗？"},{"role":"Manager","en":"Bring them to the mid-year performance review. We’ll document what changed and set new priorities for the second half.","zh":"年中绩效回顾时把这两项目标带来。我们会记录变动，再定下半年的工作重点。"}],"usage":"","distinction":"Mid-year performance review 在绩效年度中段回顾进展、调整目标或商定后续支持，有的组织也会记录评级。Year-end performance review 通常评估整个周期的表现，日常 check-in 的形式和频率更灵活。","aliases":[],"new":true,"order":443,"collocationZh":"开展年中绩效回顾","collocationReview":"V18.2 模型编辑复核","ipaUK":"mɪd ˈjiə pəˈfɔːməns rɪˈvjuː","ipaUS":"mɪd jɪr pɚˈfɔːrməns riːˈvjuː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Mid-year performance review","exampleZh":"年中绩效回顾将涵盖个人发展目标。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we handle this in the performance cycle?","zh":"在本轮绩效周期中，我们应该如何处理这件事？"},"extension":{"en":"Bring your updated goals to the mid-year performance review.","zh":"参加年中绩效回顾时请带上更新后的目标。"}},{"id":"HRV6-M3-110","moduleId":"m3","module":"绩效管理","term":"Performance rating appeal","zh":"绩效评级申诉","definition":"员工对绩效评级提出异议，并按适用程序申请正式复核的做法。","example":"Under our policy, employees have ten working days after receiving their rating to submit a performance rating appeal.","collocation":"submit a performance rating appeal","dialogue":[{"role":"Employee","en":"My rating cites a missed deadline, but the revised date was approved. How can I get that reviewed?","zh":"我的评级写着我没按时完成，但调整后的日期已经获批。怎么申请复核？"},{"role":"HR Adviser","en":"Use the performance rating appeal form and attach the approval email. The form also lists the submission deadline.","zh":"请用绩效评级申诉表，并附上批准邮件。表上也写了提交期限。"}],"usage":"","distinction":"Performance rating appeal 是员工按适用程序正式申请复核绩效评级。Feedback discussion 可用于了解评级依据或提出问题。是否设有申诉渠道、可申诉事项和适用时限，要看组织制度及适用规定。","aliases":[],"new":true,"order":444,"collocationZh":"提交绩效评级申诉","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈfɔːməns ˈreɪtɪŋ əˈpiːl","ipaUS":"pɚˈfɔːrməns ˈreɪtɪŋ əˈpiːl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Performance rating appeal","exampleZh":"按公司政策，员工可在收到评级后的十个工作日内提交绩效评级申诉。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we handle this in the performance cycle?","zh":"在本轮绩效周期中，我们应该如何处理这件事？"},"extension":{"en":"Include the rating you’re disputing in your performance rating appeal.","zh":"在绩效评级申诉中注明你有异议的评级。"}},{"id":"HRV6-M3-111","moduleId":"m3","module":"绩效管理","term":"Manager effectiveness","zh":"管理者效能／管理效能","definition":"管理者在带领团队达成目标、提供工作支持和发展员工等方面的实际效果。","example":"The survey collects employees’ views on manager effectiveness across departments.","collocation":"assess manager effectiveness","dialogue":[{"role":"HR Analyst","en":"Delivery is on target, but several employees say they rarely hear from their manager.","zh":"交付达标了，但好几位员工说很少得到经理反馈。"},{"role":"HR Director","en":"Let’s look at both when we assess manager effectiveness. Meeting targets is one part of how the team is managed.","zh":"评估管理效能时，把这两方面都考虑进去。达成目标只是团队管理的一个方面。"}],"usage":"","distinction":"Manager effectiveness 关注管理者带领团队达成目标、提供支持和发展员工的效果。Employee engagement 关注员工与工作的投入和联结程度，团队敬业度可作为参考，解读时还需结合其他证据。","aliases":[],"new":true,"order":445,"collocationZh":"评估管理者效能","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈmæn.ɪ.dʒə ɪˈfektɪvnəs","ipaUS":"ˈmæn.ə.dʒɚ ɪˈfektɪvnəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Manager effectiveness","exampleZh":"这项调查收集各部门员工对管理者效能的看法。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we handle this in the performance cycle?","zh":"在本轮绩效周期中，我们应该如何处理这件事？"},"extension":{"en":"The manager effectiveness survey asks whether employees receive timely feedback.","zh":"管理效能调查会询问员工是否及时收到反馈。"}},{"id":"HRV6-M3-112","moduleId":"m3","module":"绩效管理","term":"Continuous performance management","zh":"持续绩效管理","definition":"在绩效周期内通过定期目标回顾、具体反馈和辅导来支持员工表现的管理方式，可与正式年度考核并行。","example":"Continuous performance management encourages timely coaching.","collocation":"adopt continuous performance management","dialogue":[{"role":"Manager","en":"I already hold a team meeting every Monday. Where would individual feedback fit?","zh":"我每周一已经开团队会了。个人反馈要安排在哪儿？"},{"role":"HR Partner","en":"Start with a short one-to-one every other week. The idea behind continuous performance management is to give people feedback while they can still use it.","zh":"可以先每隔一周做一次简短的一对一。这种持续绩效管理的做法，是让员工在来得及调整时就收到反馈。"}],"usage":"","distinction":"Continuous performance management 把目标回顾、反馈与辅导安排在日常工作中，可与正式年度考核并存。Annual appraisal 侧重在特定时点汇总并评价整个周期的表现。","aliases":[],"new":true,"order":446,"collocationZh":"采用持续绩效管理方式","collocationReview":"V18.2 模型编辑复核","ipaUK":"kənˈtɪnjuːəs pəˈfɔːməns ˈmænɪdʒmənt","ipaUS":"kənˈtɪnjuːəs pɚˈfɔːrməns ˈmænədʒmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Continuous performance management","exampleZh":"持续绩效管理鼓励管理者及时辅导员工。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we handle this in the performance cycle?","zh":"在本轮绩效周期中，我们应该如何处理这件事？"},"extension":{"en":"Short, regular check-ins are part of continuous performance management.","zh":"简短、定期的沟通是持续绩效管理的一部分。"}},{"id":"HRV6-M4-101","moduleId":"m4","module":"学习培训与人才发展","term":"Professional development","zh":"职业能力发展／专业发展","definition":"帮助员工提升当前和未来岗位所需能力的持续学习发展过程。","example":"We support professional development through internal courses.","collocation":"support professional development","dialogue":[{"role":"Employee","en":"I’d like to get better at presenting to clients. Do I have to enroll in a course?","zh":"我想提高向客户做演示的能力。一定得报名上课吗？"},{"role":"Manager","en":"No, you could shadow Priya on two client calls and lead the third one. Let’s put that in your professional development plan.","zh":"不用。你可以旁听普丽娅的两场客户会议，第三场由你来主持。我们把这个安排写进你的职业能力发展计划。"}],"usage":"","distinction":"Professional development 侧重通过课程、辅导或实践提升职业能力。Career development 更关注长期职业方向和机会，job training 常聚焦完成当前岗位特定任务所需的技能。","aliases":[],"new":true,"order":447,"collocationZh":"支持职业能力发展","collocationReview":"V18.2 模型编辑复核","ipaUK":"prəˈfeʃənəl dɪˈveləpmənt","ipaUS":"prəˈfeʃənəl dɪˈveləpmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Professional development","exampleZh":"我们通过内部课程支持员工发展职业能力。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What learning support is available to employees?","zh":"员工可以获得哪些学习支持？"},"extension":{"en":"The mentoring program is part of our professional development offering.","zh":"导师计划是公司提供的一项职业能力发展支持。"}},{"id":"HRV6-M4-102","moduleId":"m4","module":"学习培训与人才发展","term":"Certification reimbursement","zh":"专业认证费用报销","definition":"雇主按制度偿付员工取得或维持获认可的专业认证所支出的合资格费用，具体项目取决于政策。","example":"Our certification reimbursement policy covers exam fees for approved certifications.","collocation":"request certification reimbursement","dialogue":[{"role":"Employee","en":"I booked the course and the exam together. Can I submit one receipt?","zh":"我一起订了课程和考试。可以提交同一张收据吗？"},{"role":"L&D Adviser","en":"Ask for an itemized receipt. Our certification reimbursement policy treats the exam fee separately from the course fee.","zh":"请开一张分项收据。按我们的专业认证费用报销政策，考试费和课程费要分开处理。"}],"usage":"","distinction":"Certification reimbursement 侧重偿付获认可的专业认证费用，如适用的考试费。Tuition reimbursement 侧重课程学费。同一培训项目含课程和考试时，两类费用可以按不同规则处理。","aliases":[],"new":true,"order":448,"collocationZh":"申请专业认证费用报销","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌsɜːtɪfɪˈkeɪʃən ˌriːɪmˈbɜːsmənt","ipaUS":"ˌsɝːtəfəˈkeɪʃən ˌriːɪmˈbɝːsmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Certification reimbursement","exampleZh":"公司的专业认证费用报销政策涵盖获批准的认证考试费用。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What learning support is available to employees?","zh":"员工可以获得哪些学习支持？"},"extension":{"en":"Check whether the certification reimbursement policy covers renewal fees.","zh":"查一下专业认证费用报销政策是否涵盖续证费。"}},{"id":"HRV6-M4-103","moduleId":"m4","module":"学习培训与人才发展","term":"Training repayment agreement","zh":"培训费用返还协议","definition":"雇主承担培训费用时，约定员工在特定可适用条件下可能返还部分或全部合资格费用的协议。条款效力和可返还范围依适用法律及具体事实而定。","example":"HR reviewed the training repayment agreement with legal counsel.","collocation":"sign a training repayment agreement","dialogue":[{"role":"Employee","en":"Does the training repayment agreement apply if I transfer to another team?","zh":"如果我转到另一个团队，培训费用返还协议还适用吗？"},{"role":"HR Adviser","en":"Let’s check the wording and confirm how the rules apply to an internal transfer in your location.","zh":"我们一起看看条款，再确认你所在地区的相关规定如何适用于内部转岗。"}],"usage":"","distinction":"Training repayment agreement 明确指约定员工可能返还雇主所承担培训费用的协议。Reimbursement 的付款方向取决于具体文件，training reimbursement policy 常指雇主向员工报销培训费的政策。返还条款是否有效、可追偿哪些费用，要看协议及适用法律。","aliases":[],"new":true,"order":449,"collocationZh":"签署培训费用返还协议","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtreɪ.nɪŋ rɪˈpeɪ.mənt əˈɡriː.mənt","ipaUS":"ˈtreɪ.nɪŋ rɪˈpeɪ.mənt əˈɡriː.mənt","ipaSource":"https://dictionary.cambridge.org/dictionary/english/training | https://dictionary.cambridge.org/dictionary/english/repayment | https://dictionary.cambridge.org/dictionary/english/agreement","speakTerm":"Training repayment agreement","exampleZh":"人力资源部门与法律顾问一起审查了培训费用返还协议。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What learning support is available to employees?","zh":"员工可以获得哪些学习支持？"},"extension":{"en":"The training repayment agreement specifies which costs may have to be repaid.","zh":"培训费用返还协议列明了哪些费用可能需要返还。"},"searchAliases":["Training reimbursement agreement"]},{"id":"HRV6-M4-104","moduleId":"m4","module":"学习培训与人才发展","term":"Learning stipend","zh":"学习津贴／个人学习额度","definition":"雇主按制度为符合条件的员工提供的个人学习经费，通常设定固定金额或可用上限。","example":"At our company, eligible employees receive an annual learning stipend.","collocation":"use a learning stipend","dialogue":[{"role":"Employee","en":"Can I use my learning stipend for books, or is it limited to classes?","zh":"学习津贴能买书吗？还是只限课程？"},{"role":"L&D Adviser","en":"Our policy covers work-related books. Check your balance first, then keep the receipt for your claim.","zh":"我们的政策涵盖与工作相关的书。先看一下剩余额度，再留好收据报销。"}],"usage":"","distinction":"Learning stipend 通常为员工自主学习提供固定额度或上限，可按津贴发放，也可凭据核销。Tuition reimbursement 专指符合政策的学费支出报销，department training budget 则通常由部门统筹使用。","aliases":[],"new":true,"order":450,"collocationZh":"使用学习津贴","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈlɜːnɪŋ ˈstaɪpənd","ipaUS":"ˈlɝːnɪŋ ˈstaɪpənd","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Learning stipend","exampleZh":"在我们公司，符合条件的员工每年可获得学习津贴。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What learning support is available to employees?","zh":"员工可以获得哪些学习支持？"},"extension":{"en":"Check whether the unused portion of your learning stipend carries over.","zh":"确认学习津贴的未用额度能否结转。"}},{"id":"HRV6-M4-105","moduleId":"m4","module":"学习培训与人才发展","term":"Continuing education","zh":"继续教育／在职进修","definition":"员工为更新知识、提升技能或获得资格持续参加的正规或非正规教育。","example":"The policy supports continuing education related to the role.","collocation":"support continuing education","dialogue":[{"role":"Employee","en":"I found a weekend course on accessibility. Does it count as continuing education under our policy?","zh":"我找到一门周末开课的无障碍设计课程。按公司政策，这算继续教育吗？"},{"role":"L&D Partner","en":"Send me the syllabus and I'll check whether the course qualifies for funding.","zh":"把课程大纲发给我，我来确认这门课是否符合资助条件。"}],"usage":"","distinction":"Continuing education 指进入职业生涯后继续参加的教育或进修，常以课程或学分计；continuing professional development（CPD）更侧重持续维持和发展专业能力，也可包括同业交流、实践反思等活动。","aliases":[],"new":true,"order":451,"collocationZh":"支持继续教育","collocationReview":"V18.2 模型编辑复核","ipaUK":"kənˈtɪnjuːɪŋ ˌedʒuːˈkeɪʃən","ipaUS":"kənˈtɪnjuːɪŋ ˌedʒəˈkeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Continuing education","exampleZh":"该政策支持与岗位相关的继续教育。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What learning support is available to employees?","zh":"员工可以获得哪些学习支持？"},"extension":{"en":"Some continuing education courses are offered in the evenings.","zh":"有些继续教育课程在晚间开课。"}},{"id":"HRV6-M4-106","moduleId":"m4","module":"学习培训与人才发展","term":"Professional certification","zh":"职业认证／专业资格认证","definition":"由专业机构或其他认证组织按其标准认定个人具备某一专业领域所需知识、技能或经验的资格。","example":"This role requires a relevant professional certification.","collocation":"obtain a professional certification","dialogue":[{"role":"Hiring Manager","en":"Her résumé lists a project management course. Has she earned the professional certification as well?","zh":"她的简历里写了上过项目管理课程。她也取得职业认证了吗？"},{"role":"Recruiter","en":"Yes. She sent us her credential number so we can verify it with the issuing body.","zh":"取得了。她把认证编号发给我们了，可以向发证机构核验。"}],"usage":"","distinction":"Professional certification 指对专业能力的认证；certificate of completion 主要证明完成了课程；professional license 指主管机构依法授予的执业许可，是否需要许可取决于职业和当地规定。","aliases":[],"new":true,"order":452,"collocationZh":"取得职业认证","collocationReview":"V18.2 模型编辑复核","ipaUK":"prəˈfeʃənəl ˌsɜːtɪfɪˈkeɪʃən","ipaUS":"prəˈfeʃənəl ˌsɝːtəfəˈkeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Professional certification","exampleZh":"该岗位要求持有相关职业认证。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What learning support is available to employees?","zh":"员工可以获得哪些学习支持？"},"extension":{"en":"Some professional certifications require renewal every few years.","zh":"有些职业认证每隔几年需要续期。"}},{"id":"HRV6-M4-107","moduleId":"m4","module":"学习培训与人才发展","term":"Training nomination","zh":"培训人员提名／选派","definition":"管理者或部门推荐特定员工参加培训课程或培养项目的流程或提名。","example":"Managers must submit training nominations by Friday.","collocation":"submit a training nomination","dialogue":[{"role":"Team Lead","en":"I'd like to put Mina forward for the facilitation workshop. Can I nominate her if she's on leave this week?","zh":"我想推荐米娜参加会议引导工作坊。她这周休假，我还能提名她吗？"},{"role":"L&D Coordinator","en":"Check that she can make the workshop dates, then submit the training nomination for her.","zh":"先确认她能参加那几天的培训，再替她提交提名。"}],"usage":"","distinction":"Training nomination 是推荐人选，通常还要经过审核或名额确认；training enrollment 指正式报名或登记；training assignment 通常指把课程分配给指定员工。","aliases":[],"new":true,"order":453,"collocationZh":"提交培训人员提名","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtreɪnɪŋ ˌnɒmɪˈneɪʃən","ipaUS":"ˈtreɪnɪŋ ˌnɑːməˈneɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Training nomination","exampleZh":"管理者须最迟于周五提交培训提名。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What learning support is available to employees?","zh":"员工可以获得哪些学习支持？"},"extension":{"en":"A training nomination can include a short note on what the employee hopes to learn.","zh":"提交培训提名时，可以简要说明员工希望学到什么。"}},{"id":"HRV6-M4-108","moduleId":"m4","module":"学习培训与人才发展","term":"Mandatory training","zh":"强制性培训／必修培训","definition":"根据适用法规、岗位要求或组织政策，指定员工必须完成的培训。","example":"Under our onboarding policy, new hires must complete their mandatory training within 30 days of starting.","collocation":"complete mandatory training","dialogue":[{"role":"Employee","en":"I took the security course at my old company. Do I still need to take this one?","zh":"我在上一家公司上过信息安全课。这门还要上吗？"},{"role":"L&D Coordinator","en":"Yes, it's mandatory training here. It covers how to report a security incident using our own systems.","zh":"要，这门课在我们公司是必修的，里面会讲怎么用我们的系统报告安全事件。"}],"usage":"","distinction":"Mandatory training 泛指规定必须完成的培训；compliance training 按主题划分，侧重法律、监管或内部规范。公司也可把设备操作培训设为必修。","aliases":[],"new":true,"order":454,"collocationZh":"完成强制性培训","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈmændətəri ˈtreɪnɪŋ","ipaUS":"ˈmændəˌtɔːriː ˈtreɪnɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Mandatory training","exampleZh":"按公司的入职政策，新员工须在入职后 30 天内完成必修培训。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What learning support is available to employees?","zh":"员工可以获得哪些学习支持？"},"extension":{"en":"The reminder lists each mandatory training module and its due date.","zh":"提醒邮件列出了各项必修培训及其完成期限。"}},{"id":"HRV6-M4-109","moduleId":"m4","module":"学习培训与人才发展","term":"Skills matrix","zh":"员工技能矩阵","definition":"按员工与技能维度列示能力水平、资格或培训差距的工具。","example":"The skills matrix helps us identify capability gaps.","collocation":"update the skills matrix","dialogue":[{"role":"Shift Supervisor","en":"Do we have anyone on the evening shift who can troubleshoot the new scanner?","zh":"晚班有没有人能排查新扫描仪的故障？"},{"role":"Operations Trainer","en":"The skills matrix shows that Noor can handle basic faults. I'll see if we can pair her with a technician for the first week.","zh":"技能矩阵显示，努尔能处理常见故障。我看看第一周能不能给她安排一名技术员搭班。"}],"usage":"","distinction":"Skills matrix 把人员和技能交叉列出，常标注熟练程度或资格；competency framework 定义岗位或职级所需的能力及行为标准。前者可用后者的标准记录团队现状。","aliases":[],"new":true,"order":455,"collocationZh":"更新员工技能矩阵","collocationReview":"V18.2 模型编辑复核","ipaUK":"skɪlz ˈmeɪtrɪks","ipaUS":"skɪlz ˈmeɪtrɪks","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Skills matrix","exampleZh":"技能矩阵有助于我们识别技能缺口。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What learning support is available to employees?","zh":"员工可以获得哪些学习支持？"},"extension":{"en":"The skills matrix shows who can train others on each machine.","zh":"技能矩阵显示了每台设备可以由谁来培训其他员工。"}},{"id":"HRV6-M4-110","moduleId":"m4","module":"学习培训与人才发展","term":"Training evaluation","zh":"培训效果评估","definition":"评估培训质量及成效的过程，可根据目标考察学员反馈、学习成果、工作中的应用或业务结果。","example":"We will conduct a training evaluation after the program.","collocation":"conduct a training evaluation","dialogue":[{"role":"Program Sponsor","en":"The workshop got great ratings. Do we know if managers are giving better feedback now?","zh":"工作坊的评分很高。我们知道经理们现在给员工的反馈有没有改进吗？"},{"role":"L&D Analyst","en":"Not yet. For the training evaluation, I'd like to review a few examples from their next round of check-ins.","zh":"还不知道。做培训效果评估时，我想看看下一轮员工沟通中实际给出的几条反馈。"}],"usage":"","distinction":"Training evaluation 关注培训是否达到目标；training needs analysis 在设计培训前识别学习需求；learner assessment 评估学员个人掌握程度，可为培训效果评估提供证据。","aliases":[],"new":true,"order":456,"collocationZh":"开展培训效果评估","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtreɪnɪŋ ɪˌvæljuːˈeɪʃən","ipaUS":"ˈtreɪnɪŋ ɪˌvæljuːˈeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Training evaluation","exampleZh":"培训项目结束后，我们将开展培训效果评估。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What learning support is available to employees?","zh":"员工可以获得哪些学习支持？"},"extension":{"en":"A follow-up survey can show whether participants are using what they learned at work.","zh":"后续调查可以了解学员有没有把所学内容用到工作中。"}},{"id":"HRV6-M4-111","moduleId":"m4","module":"学习培训与人才发展","term":"Learning budget","zh":"学习与发展预算","definition":"组织用于课程、平台、教材及其他学习发展的资金计划。","example":"The learning budget covers both internal and external training.","collocation":"allocate a learning budget","dialogue":[{"role":"Team Lead","en":"Could we use some of our learning budget for a shared subscription instead of buying individual courses?","zh":"我们能不能从学习与发展预算里拿出一部分买团队订阅，省得一门课一门课地买？"},{"role":"Finance Partner","en":"Yes, if it fits the team's budget. Send me the quote before you commit.","zh":"可以，只要在团队预算内。先把报价发给我，再确认购买。"}],"usage":"","distinction":"Learning budget 可覆盖课程、平台、辅导等多种支出；training budget 通常聚焦培训活动。两者在企业预算表中可能是同一个科目，具体以内部口径为准。","aliases":[],"new":true,"order":457,"collocationZh":"划拨学习与发展预算","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈlɜːnɪŋ ˈbʌdʒɪt","ipaUS":"ˈlɝːnɪŋ ˈbʌdʒɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Learning budget","exampleZh":"学习预算涵盖内部和外部培训。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What learning support is available to employees?","zh":"员工可以获得哪些学习支持？"},"extension":{"en":"We set aside part of the learning budget for team coaching.","zh":"我们从学习与发展预算中留出一部分，用于团队教练辅导。"}},{"id":"HRV6-M4-112","moduleId":"m4","module":"学习培训与人才发展","term":"External training provider","zh":"外部培训服务商","definition":"向组织提供培训课程、授课人员或其他培训服务的外部机构或个人。","example":"We selected an external training provider for the leadership program.","collocation":"select an external training provider","dialogue":[{"role":"Procurement Partner","en":"Can we see how the facilitator handles a group discussion before we sign?","zh":"签约前，我们能看看讲师怎么带小组讨论吗？"},{"role":"L&D Manager","en":"I've asked the external training provider to run a short demo for us next Tuesday.","zh":"我已经请外部培训服务商下周二给我们做一场简短演示。"}],"usage":"","distinction":"External training provider 是承担外部培训交付的服务方，可负责课程设计、组织或授课；external trainer 指外聘讲师本人；training platform 则通常指承载课程的系统。","aliases":[],"new":true,"order":458,"collocationZh":"遴选外部培训服务商","collocationReview":"V18.2 模型编辑复核","ipaUK":"ekˈstɜːnəl ˈtreɪnɪŋ prəˈvaɪdə","ipaUS":"ɪkˈstɝːnəl ˈtreɪnɪŋ prəˈvaɪdɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"External training provider","exampleZh":"我们为领导力项目选择了一家外部培训机构。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What learning support is available to employees?","zh":"员工可以获得哪些学习支持？"},"extension":{"en":"The external training provider adapted the exercises to reflect our customer support workflow.","zh":"外部培训服务商根据我们的客户支持流程调整了练习内容。"}},{"id":"HRV6-M4-113","moduleId":"m4","module":"学习培训与人才发展","term":"Course completion certificate","zh":"课程结业证明／课程结业证书","definition":"由课程提供方出具、证明学员按要求完成课程的文件。","example":"Please upload your course completion certificate for reimbursement.","collocation":"submit a course completion certificate","dialogue":[{"role":"Employee","en":"The training portal still says my course is in progress, but I've passed the final quiz.","zh":"我已经通过结课测验了，可培训平台还显示课程未完成。"},{"role":"Training Coordinator","en":"It may take a day to update. Once it shows as complete, you can download your course completion certificate.","zh":"状态可能要一天才会更新。显示已完成之后，你就可以下载课程结业证明了。"}],"usage":"","distinction":"Course completion certificate 证明课程已修完；attendance certificate 主要证明出席；professional certification 通常另有专业资格标准，不能仅凭结业证明推断已取得认证。","aliases":[],"new":true,"order":459,"collocationZh":"提交课程结业证明","collocationReview":"V18.2 模型编辑复核","ipaUK":"kɔːs kəmˈpliːʃən səˈtɪfɪkət","ipaUS":"kɔːrs kəmˈpliːʃən sɚˈtɪfɪkət","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Course completion certificate","exampleZh":"请上传课程结业证明，以便申请报销。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What learning support is available to employees?","zh":"员工可以获得哪些学习支持？"},"extension":{"en":"The course completion certificate shows the total number of learning hours.","zh":"课程结业证明上注明了总学时。"}},{"id":"HRV6-M4-114","moduleId":"m4","module":"学习培训与人才发展","term":"Education benefit eligibility","zh":"教育福利申领资格","definition":"员工按组织政策获得学费报销、教育资助等福利的资格，通常取决于员工和所选课程是否符合规定条件。","example":"Under our policy, education benefit eligibility depends on length of service and prior course approval.","collocation":"check education benefit eligibility","dialogue":[{"role":"Employee","en":"I'm moving to part-time next month. Will I still be eligible for the education benefit?","zh":"我下个月要转为兼职。我还能申领教育福利吗？"},{"role":"Benefits Specialist","en":"Let's check the policy before you enroll. Your scheduled hours may affect your eligibility.","zh":"你先别报名，我们查一下政策。你的排班工时可能会影响申领资格。"}],"usage":"","distinction":"Education benefit eligibility 关注员工或课程是否符合申领条件；education benefit coverage 关注可报销哪些费用及其额度；course approval 是对具体课程的审批，可能只是资格条件之一。","aliases":[],"new":true,"order":460,"collocationZh":"核查是否符合教育福利申领条件","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌedʒuːˈkeɪʃən ˈbenɪˌfɪt ˌelɪdʒəˈbɪlɪti","ipaUS":"ˌedʒəˈkeɪʃən ˈbenəfɪt ˌelɪdʒəˈbɪlɪtiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Education benefit eligibility","exampleZh":"按公司政策，员工能否申领教育福利取决于司龄以及课程是否事先获批。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What learning support is available to employees?","zh":"员工可以获得哪些学习支持？"},"extension":{"en":"The benefits guide explains when employees become eligible for the education benefit.","zh":"福利指南说明了员工从什么时候起可以申领教育福利。"}},{"id":"HRV6-M5-101","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Organizational structure","zh":"组织结构／组织架构","definition":"组织部门、汇报关系、管理层级及岗位分工的总体安排。","example":"The new organizational structure clarifies reporting relationships.","collocation":"review the organizational structure","dialogue":[{"role":"Department Head","en":"If we move the analysts into a central team, who sets their day-to-day priorities?","zh":"如果把分析师集中到一个团队，谁来定他们每天的工作重点？"},{"role":"HR Partner","en":"Let's make that explicit in the proposed organizational structure before we circulate it.","zh":"我们先在组织架构方案里把这一点写清楚，再发给大家看。"}],"usage":"","distinction":"Organizational structure 指部门划分、职责和汇报关系等整体安排，organization structure 也是可见变体；organizational chart 是把这些关系画出来的组织架构图。","aliases":[],"new":true,"order":461,"collocationZh":"审查组织架构","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɔː.ɡən.aɪˈzeɪ.ʃən.əl ˈstrʌk.tʃə","ipaUS":"ˌɔːr.ɡən.əˈzeɪ.ʃən.əl ˈstrʌk.tʃɚ","ipaSource":"https://dictionary.cambridge.org/dictionary/english/organizational | https://dictionary.cambridge.org/dictionary/english/structure","speakTerm":"Organizational structure","exampleZh":"新的组织架构明确了汇报关系。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What does this mean for our talent and organization plan?","zh":"这对我们的人才与组织规划意味着什么？"},"extension":{"en":"The organizational structure places product and engineering under a single executive.","zh":"按该组织架构，产品和工程团队由同一名高管负责。"},"searchAliases":["Organization structure"]},{"id":"HRV6-M5-102","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Position management","zh":"岗位编制管理","definition":"对获批岗位的设立、预算、变更、占用和撤销进行管理，可跟踪一个岗位对应的一名或多名任职者。","example":"Position management helps us track whether vacant positions are approved and funded.","collocation":"strengthen position management","dialogue":[{"role":"Hiring Manager","en":"Leo has moved to sales. Can I recruit a replacement using his old position number?","zh":"利奥已经调到销售部了。我能用他原来的岗位编号招人补缺吗？"},{"role":"HR Operations Partner","en":"I'll check in the position management system whether that position is still open and funded.","zh":"我在岗位编制管理系统里查一下，看看那个岗位是否仍可补员、还有没有预算。"}],"usage":"","distinction":"Position management 管理组织里获批的具体岗位及占用情况；job management 通常管理可供多个岗位共用的职务分类或岗位档案。不同 HR 系统对岗位和任职者的对应规则可能不同。","aliases":[],"new":true,"order":462,"collocationZh":"加强岗位编制管理","collocationReview":"V18.2 模型编辑复核","ipaUK":"pəˈzɪʃən ˈmænɪdʒmənt","ipaUS":"pəˈzɪʃən ˈmænədʒmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Position management","exampleZh":"岗位编制管理有助于跟踪空缺岗位是否已获批并落实预算。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What does this mean for our talent and organization plan?","zh":"这对我们的人才与组织规划意味着什么？"},"extension":{"en":"With position management, HR can track a vacant position after its previous holder leaves.","zh":"通过岗位编制管理，人力资源部门可以跟踪原任职者离开后空出的岗位。"}},{"id":"HRV6-M5-103","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Organizational hierarchy","zh":"组织层级结构","definition":"组织内部从高到低的管理层级和汇报链条。","example":"The organizational hierarchy will be simplified next quarter.","collocation":"simplify the organizational hierarchy","dialogue":[{"role":"Operations Director","en":"Why does a routine purchasing request go through three managers?","zh":"为什么一笔日常采购要经过三位经理审批？"},{"role":"HR Partner","en":"The approvals follow the organizational hierarchy. Finance can help us see which levels actually need to sign off.","zh":"审批是按组织层级走的。我们可以请财务一起看看，哪些层级确实需要签批。"}],"usage":"","distinction":"Organizational hierarchy 聚焦上下级和管理层数；organizational structure 还包括部门、职能和协作安排；chain of command 更侧重指令或问题上报沿哪条管理链传递。","aliases":[],"new":true,"order":463,"collocationZh":"精简组织层级","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɔːɡənaɪˈzeɪʃənəl ˈhaɪərɑːki","ipaUS":"ˌɔːrɡənəˈzeɪʃənəl ˈhaɪɚˌɑːrkiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Organizational hierarchy","exampleZh":"下季度将简化组织层级。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What does this mean for our talent and organization plan?","zh":"这对我们的人才与组织规划意味着什么？"},"extension":{"en":"The organizational hierarchy shows where operational decisions are escalated.","zh":"组织层级反映了运营决策需要报请哪一级处理。"}},{"id":"HRV6-M5-104","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Succession candidate","zh":"继任候选人","definition":"在继任规划中被列为未来可能接任某个关键岗位的人选，通常还会评估其准备度。","example":"We identified two succession candidates for the finance director role.","collocation":"identify a succession candidate","dialogue":[{"role":"Talent Partner","en":"Should we add Amira as a succession candidate for the plant manager role?","zh":"要不要把阿米拉列为工厂厂长的继任候选人？"},{"role":"Operations Director","en":"Yes. She knows production well, and a rotation in maintenance would round out her experience.","zh":"可以。她熟悉生产流程，再去设备维护部门轮岗一段时间，经历就更全面了。"}],"usage":"","distinction":"Succession candidate 是纳入继任评估的潜在人选；designated successor 通常指已明确指定的接任人；interim appointee 指实际获任临时代理的人。","aliases":[],"new":true,"order":464,"collocationZh":"识别继任候选人","collocationReview":"V18.2 模型编辑复核","ipaUK":"səkˈseʃən ˈkæn.dɪ.dət","ipaUS":"səkˈseʃən ˈkæn.dɪ.dət","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Succession candidate","exampleZh":"我们为财务总监岗位确定了两位继任候选人。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What does this mean for our talent and organization plan?","zh":"这对我们的人才与组织规划意味着什么？"},"extension":{"en":"Each succession candidate has a development plan tied to the requirements of the role.","zh":"每位继任候选人都有一份与目标岗位要求相对应的发展计划。"}},{"id":"HRV6-M5-105","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Career pathing","zh":"职业发展路径规划","definition":"帮助员工探索可行的晋升、横向流动和专业发展路线，并明确各路线所需能力的过程。","example":"Career pathing helps employees understand growth opportunities.","collocation":"build a career pathing framework","dialogue":[{"role":"Employee","en":"I enjoy the technical work, but the only next step I see is managing a team.","zh":"我喜欢做技术工作，但眼下看起来，想再往上走就只能带团队。"},{"role":"Manager","en":"Let's look at the specialist track in our career pathing guide. There's a lead engineer role with no direct reports.","zh":"我们看看职业发展路径指南里的专业序列吧。主任工程师这个岗位就没有直属下属。"}],"usage":"","distinction":"Career pathing 着重梳理有哪些可走的路线以及如何到达；career path 指其中一条具体路线；individual development plan 则落实到个人的学习目标、行动和时间安排。","aliases":[],"new":true,"order":465,"collocationZh":"建立职业发展路径框架","collocationReview":"V18.2 模型编辑复核","ipaUK":"kəˈriə ˈpɑː.θɪŋ","ipaUS":"kɚˈɪr ˈpæ.θɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Career pathing","exampleZh":"职业发展路径规划帮助员工了解成长机会。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What does this mean for our talent and organization plan?","zh":"这对我们的人才与组织规划意味着什么？"},"extension":{"en":"Career pathing can show specialists how to advance without moving into management.","zh":"职业发展路径规划可以帮助专业人员了解如何在不转管理岗的情况下继续发展。"}},{"id":"HRV6-M5-106","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Promotion criteria","zh":"晋升标准／晋升评审条件","definition":"用于判断员工是否满足晋升职级要求的业绩、能力与行为标准。","example":"The promotion criteria should be transparent to employees.","collocation":"define promotion criteria","dialogue":[{"role":"Employee","en":"I've met my targets all year. What else should I bring to the promotion discussion?","zh":"我今年一直完成目标。谈晋升的时候，我还应该准备哪些材料？"},{"role":"Manager","en":"One of the promotion criteria is independent decision-making. Bring an example of a decision you took ownership of.","zh":"晋升标准中有一项是独立决策。准备一个你独立作出决定并负责到底的例子。"}],"usage":"","distinction":"Promotion criteria 是评估能否晋升的实质标准；promotion eligibility 是能否进入评审的资格条件；promotion process 则是提名、评审和批准等步骤。","aliases":[],"new":true,"order":466,"collocationZh":"制定晋升标准","collocationReview":"V18.2 模型编辑复核","ipaUK":"prəˈməʊʃən kraɪˈtiərɪə","ipaUS":"prəˈmoʊʃən kraɪˈtɪriːə","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Promotion criteria","exampleZh":"应向员工公开晋升标准。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What does this mean for our talent and organization plan?","zh":"这对我们的人才与组织规划意味着什么？"},"extension":{"en":"The promotion criteria spell out what leadership looks like at each level.","zh":"晋升标准明确说明了各职级应展现怎样的领导力。"}},{"id":"HRV6-M5-107","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Talent pipeline","zh":"人才梯队／人才储备渠道","definition":"为未来岗位需求持续识别、接触或培养潜在人选形成的储备，可面向内部发展或外部招聘。","example":"We need a stronger leadership talent pipeline.","collocation":"build a talent pipeline","dialogue":[{"role":"Recruiting Lead","en":"We keep going back to the same two agencies for field engineers.","zh":"每次要招现场工程师，我们找来找去都是那两家招聘机构。"},{"role":"Engineering Manager","en":"Could we build a talent pipeline with the local technical college? We already host their students for site visits.","zh":"我们能不能和本地职业院校一起建立人才储备渠道？他们的学生已经来我们现场参观过了。"}],"usage":"","distinction":"Talent pipeline 强调人选从识别到培养或聘用的持续流转；talent pool 强调已有的潜在人选集合；succession bench 专指关键岗位的继任储备。","aliases":[],"new":true,"order":467,"collocationZh":"建立人才梯队","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtæl.ənt ˈpaɪplaɪn","ipaUS":"ˈtæl.ənt ˈpaɪplaɪn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Talent pipeline","exampleZh":"我们需要加强领导人才梯队储备。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What does this mean for our talent and organization plan?","zh":"这对我们的人才与组织规划意味着什么？"},"extension":{"en":"Apprenticeships can help build a talent pipeline for hard-to-fill technical roles.","zh":"学徒项目有助于为难招的技术岗位储备人才。"}},{"id":"HRV6-M5-108","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Lateral move","zh":"横向岗位调动／平级转岗","definition":"员工在相近职级之间转换岗位或职能领域的内部流动。","example":"A lateral move can broaden an employee's experience.","collocation":"support a lateral move","dialogue":[{"role":"Employee","en":"Would a move to the data team put me on a different job grade?","zh":"如果调到数据团队，我的职级会变吗？"},{"role":"HR Partner","en":"It would be a lateral move at your current grade. Let's go over how the responsibilities would change.","zh":"这是按你现有职级平级转岗。我们来看看职责会有哪些变化。"}],"usage":"","distinction":"Lateral move 指同级或相近职级的岗位变动；promotion 涉及职级上升；job rotation 通常是带有明确学习目标或期限的轮岗安排。","aliases":[],"new":true,"order":468,"collocationZh":"支持员工平级转岗","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈlætərəl muːv","ipaUS":"ˈlætɚəl muːv","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Lateral move","exampleZh":"平级转岗有助于员工拓宽工作经验。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What does this mean for our talent and organization plan?","zh":"这对我们的人才与组织规划意味着什么？"},"extension":{"en":"A lateral move into operations gave me experience working directly with suppliers.","zh":"平级转到运营岗后，我有了直接和供应商打交道的经验。"}},{"id":"HRV6-M5-109","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Workforce capacity planning","zh":"人力供需与产能规划","definition":"根据预计工作量、人员技能和可用工时判断团队能否满足需求，并安排补员、排班或跨岗支援的过程。","example":"During workforce capacity planning, we identified a likely staffing gap on the evening shift.","collocation":"use workforce capacity planning to forecast staffing needs","dialogue":[{"role":"Service Manager","en":"Ticket volume usually jumps after a product launch. Can we cover it with the people we have?","zh":"产品一发布，工单量通常就会大涨。现有的人手能应付吗？"},{"role":"Workforce Planner","en":"I'll use that forecast in our workforce capacity planning and factor in the time agents spend away from the queue.","zh":"我会把这个预测纳入人力产能规划，也会考虑客服人员离开工单队列处理其他事务的时间。"}],"usage":"","distinction":"Workforce capacity planning 关注给定时段内可用人力能否承担预计工作量；headcount planning 重在规划人数或编制；workforce planning 范围更广，还可涉及长期技能和人才供给。","aliases":[],"new":true,"order":469,"collocationZh":"通过人力产能规划预测人员需求","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈwɜːk.fɔːs kəˈpæsɪti ˈplæn.ɪŋ","ipaUS":"ˈwɝːk.fɔːrs kəˈpæsətiː ˈplæn.ɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Workforce capacity planning","exampleZh":"在人力产能规划中，我们发现晚班可能人手不足。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What does this mean for our talent and organization plan?","zh":"这对我们的人才与组织规划意味着什么？"},"extension":{"en":"Workforce capacity planning should account for time spent on training.","zh":"做人员产能规划时，应计入培训占用的工时。"}},{"id":"HRV6-M5-110","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Talent retention plan","zh":"人才保留计划／留才方案","definition":"针对识别出的留才风险，制定职业发展、工作安排、薪酬或管理支持等改进措施的计划。","example":"The talent retention plan targets hard-to-replace skills.","collocation":"develop a talent retention plan","dialogue":[{"role":"Engineering Manager","en":"Two experienced technicians said the rotating night shifts are wearing them out.","zh":"有两位经验丰富的技术员说，轮值夜班让他们吃不消。"},{"role":"HR Partner","en":"Let's see whether we can redesign the rota and put that action in the talent retention plan.","zh":"我们看看能否重新排班，把这项措施写进留才方案。"}],"usage":"","distinction":"Talent retention plan 是落实具体留才措施、负责人和时间的计划；retention strategy 是组织的整体留才思路；succession plan 则为关键岗位出现空缺做准备。","aliases":[],"new":true,"order":470,"collocationZh":"制定人才保留计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈtæl.ənt rɪˈtenʃən plæn","ipaUS":"ˈtæl.ənt riːˈtenʃən plæn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Talent retention plan","exampleZh":"人才保留计划重点关注具备难以替代技能的员工。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What does this mean for our talent and organization plan?","zh":"这对我们的人才与组织规划意味着什么？"},"extension":{"en":"The talent retention plan gives senior specialists a clearer route to more challenging work.","zh":"人才保留计划为资深专业人员安排了更明确的路径，让他们有机会承担更有挑战性的工作。"}},{"id":"HRV6-M5-111","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Succession bench","zh":"关键岗位继任人才储备","definition":"组织为一个或多个关键岗位储备的潜在继任者群体，各人所处的准备阶段可能不同。","example":"Our succession bench for regional leadership is still limited.","collocation":"strengthen the succession bench","dialogue":[{"role":"Talent Director","en":"Who could step in if one of our site leads left this year?","zh":"如果今年有一位站点负责人离任，谁能接上？"},{"role":"Operations VP","en":"There's one person ready now. To build the succession bench, I'd like two more to lead a site for a few weeks.","zh":"目前有一位人选已经准备好了。为了充实继任储备，我想再安排两个人各试带一个站点几周。"}],"usage":"","distinction":"Succession bench 强调关键岗位有多少继任者以及他们何时能接任；succession candidate 指其中一名人选；succession plan 还包括培养安排和交接准备。","aliases":[],"new":true,"order":471,"collocationZh":"加强关键岗位继任人才储备","collocationReview":"V18.2 模型编辑复核","ipaUK":"səkˈseʃən bentʃ","ipaUS":"səkˈseʃən bentʃ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Succession bench","exampleZh":"我们的区域管理岗位继任储备仍然不足。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What does this mean for our talent and organization plan?","zh":"这对我们的人才与组织规划意味着什么？"},"extension":{"en":"A deeper succession bench gives us more options when a key role opens up.","zh":"继任储备越充足，关键岗位出现空缺时可选的人就越多。"}},{"id":"HRV6-M5-112","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Organizational capability","zh":"组织能力","definition":"组织通过人才、流程和机制持续实现战略目标的整体能力。","example":"The transformation requires new organizational capabilities.","collocation":"build organizational capability","dialogue":[{"role":"Transformation Lead","en":"Only the pilot team knows how to run the new scheduling process.","zh":"目前只有试点团队会操作新的排班流程。"},{"role":"HR Director","en":"Let's build that organizational capability across sites by pairing each local lead with someone from the pilot.","zh":"我们给每个站点的负责人配一位试点成员带一带，把这项能力推广到各站点。"}],"usage":"","distinction":"Organizational capability 指组织调动人员、流程和资源持续做到某件事的能力；individual competency 指个人能力；workforce capacity 聚焦一定时段内人力所能承担的工作量。","aliases":[],"new":true,"order":472,"collocationZh":"建设组织能力","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɔːɡənaɪˈzeɪʃənəl ˌkeɪpəˈbɪlɪti","ipaUS":"ˌɔːrɡənəˈzeɪʃənəl ˌkeɪpəˈbɪlətiː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Organizational capability","exampleZh":"这次转型需要新的组织能力。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What does this mean for our talent and organization plan?","zh":"这对我们的人才与组织规划意味着什么？"},"extension":{"en":"Cross-training helped build organizational capability in incident response.","zh":"交叉培训帮助组织提升了事件响应能力。"}},{"id":"HRV6-M5-113","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Job grading","zh":"岗位等级划分／岗位定级","definition":"根据岗位职责、复杂程度和影响范围等标准，把岗位归入相应等级的过程。","example":"Job grading helps maintain consistent role levels.","collocation":"conduct job grading","dialogue":[{"role":"Department Head","en":"The coordinator now owns the supplier budget. Should we review the grade?","zh":"协调员现在负责供应商预算了。要重新评估这个岗位的级别吗？"},{"role":"Compensation Partner","en":"Yes. Send me the updated job description so I can compare it with roles in the same job grading framework.","zh":"可以。把新版岗位说明书发给我，我好和同一岗位定级体系下的其他岗位比较。"}],"usage":"","distinction":"Job evaluation 侧重评估岗位的相对价值；job grading 侧重依据标准或评估结果确定岗位等级；performance appraisal 则评价任职者的工作表现。","aliases":[],"new":true,"order":473,"collocationZh":"开展岗位定级","collocationReview":"V18.2 模型编辑复核","ipaUK":"dʒɒb ˈɡreɪdɪŋ","ipaUS":"dʒɑːb ˈɡreɪdɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Job grading","exampleZh":"岗位定级有助于保持岗位等级划分的一致性。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What does this mean for our talent and organization plan?","zh":"这对我们的人才与组织规划意味着什么？"},"extension":{"en":"Job grading looks at the scope of the role rather than the current job title.","zh":"岗位定级看的是职责范围，而非现有的岗位头衔。"}},{"id":"HRV6-M6-101","moduleId":"m6","module":"员工关系与劳动合规","term":"Contract renewal","zh":"合同续订／合同续约","definition":"现有合同临近到期时，按合同约定或适用规则让合同关系延续至下一期的安排。可通过签订新协议或按约定的续订机制办理。","example":"Our team starts the contract renewal process 60 days before the current term ends.","collocation":"start the contract renewal process","dialogue":[{"role":"L&D Manager","en":"The training platform expires in June. Can we cut the number of seats when we renew?","zh":"培训平台的合同六月到期。续约时能减少账号名额吗？"},{"role":"Procurement Partner","en":"Let's raise that during the contract renewal discussions. I'll pull up last year's usage first.","zh":"我们在谈续约时提一下。我先把去年的使用数据调出来。"}],"usage":"HR 沟通中常说“劳动合同续签”；并不一定意味着只修改到期日。","distinction":"Contract renewal 通常指进入下一合同期，既可指劳动合同，也可指供应商等其他合同；contract extension 通常指延后现有期限的结束日期。条款如何生效取决于合同和适用法律。","aliases":["Contract renewal process","合同续约"],"new":true,"order":474,"collocationZh":"启动合同续订流程","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkɒn.trækt rɪˈnjuː.əl","ipaUS":"ˈkɑːn.trækt rɪˈnuː.əl","ipaSource":"词典重点校订","speakTerm":"Contract renewal","exampleZh":"我们团队会在本期合同到期前 60 天启动续订流程。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Contract renewal","note":"按约定进入下一合同期，可能需要签署新协议，也可能按原合同的续订机制办理。","relation":"本词"},{"term":"Contract extension","note":"通常指延长现有合同的期限。","relation":"易混淆"},{"term":"Contract expiration","note":"合同约定期限届满，届满后的处理取决于合同和适用法律。英式英语也常用 contract expiry。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"The employee’s fixed-term contract expires next month. Should we start the renewal process?","zh":"这名员工的固定期限劳动合同下月到期，我们是否需要启动续签流程？"},"extension":{"en":"The supplier proposed a rate change as part of the contract renewal.","zh":"供应商在洽谈合同续订时提出调整费率。"}},{"id":"HRV6-M6-102","moduleId":"m6","module":"员工关系与劳动合规","term":"Employment contract renewal","zh":"劳动合同续签","definition":"依照劳动合同及适用规则，在本期合同到期时延续雇佣约定的安排，可能涉及确认下一期的期限及条款。","example":"For this employment contract renewal, HR will send the employee the proposed terms for review.","collocation":"complete an employment contract renewal","dialogue":[{"role":"Employee","en":"The draft keeps my current job title, but my hours changed in March.","zh":"草案还是我现在的职务名称，不过我的工时三月就变了。"},{"role":"HR Adviser","en":"Thanks for flagging that. I'll check what hours should appear in the employment contract renewal before we send the final version.","zh":"谢谢你提醒。我会先核对续签合同时应写明的工时，再发定稿。"}],"usage":"常见表达 renew an employment contract；适用法律的续签次数、期限等须另行判断。","distinction":"Employment contract renewal 把合同续订明确限定在劳动关系中；contract renewal 也可用于服务、租赁等合同；contract extension 多指延长现有期限。续签或延长期限的手续取决于当地法律和合同。","aliases":[],"new":true,"order":475,"collocationZh":"完成劳动合同续签","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.mənt ˈkɒntrækt rɪˈnjuːəl","ipaUS":"ɪmˈplɔɪ.mənt ˈkɑːntrækt rɪˈnuːəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employment contract renewal","exampleZh":"这次续签劳动合同，人力资源部门会把拟议条款发给员工审阅。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will HR handle this employment matter?","zh":"HR 将如何处理这项雇佣关系事务？"},"extension":{"en":"The tracker records the proposed start date for each employment contract renewal.","zh":"跟踪表记录了每份拟续签劳动合同的起始日期。"}},{"id":"HRV6-M6-103","moduleId":"m6","module":"员工关系与劳动合规","term":"Contract extension","zh":"劳动合同期限延长／合同延期","definition":"延长既有劳动合同约定期限的安排；与重新签订续约合同的法律效果可能不同。","example":"The parties agreed to a three-month contract extension.","collocation":"agree to a contract extension","dialogue":[{"role":"Project Manager","en":"The handover now runs into May. Could we keep Alex on until it's finished?","zh":"交接现在要持续到五月。能让亚历克斯留到交接结束吗？"},{"role":"HR Adviser","en":"I'll check whether a contract extension is an option before we discuss a new end date with Alex.","zh":"我先看看能不能延长合同，再和亚历克斯谈新的结束日期。"}],"usage":"如果只是调整既有合同到期日，更常用 extension。","distinction":"Contract extension 通常在现有合同基础上延后到期日；contract renewal 通常着眼于下一合同期。措辞与法律效果可能因条款和法域而异。","aliases":[],"new":true,"order":476,"collocationZh":"同意延长劳动合同期限","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkɒntrækt ekˈstenʃən","ipaUS":"ˈkɑːntrækt ɪkˈstenʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Contract extension","exampleZh":"双方同意将合同延长三个月。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Contract extension","note":"通常指延后现有合同的到期日。","relation":"本词"},{"term":"Contract renewal","note":"通常指续订下一合同期，办理方式以合同和适用法律为准。","relation":"易混淆"},{"term":"Contract expiration","note":"指约定期限届满。英式英语也常用 contract expiry。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"How will HR handle this employment matter?","zh":"HR 将如何处理这项雇佣关系事务？"},"extension":{"en":"The draft contract extension changes the end date and keeps the other terms as they are.","zh":"这份合同延期草案调整了结束日期，其余条款沿用原约定。"}},{"id":"HRV6-M6-104","moduleId":"m6","module":"员工关系与劳动合规","term":"Contract expiration","zh":"劳动合同到期／合同期满","definition":"合同约定期限届满。期满后是否续订或继续雇佣，取决于合同约定、实际情况和适用法律。","example":"The system will alert HR before contract expiration.","collocation":"monitor contract expiration","dialogue":[{"role":"HR Coordinator","en":"This record shows contract expiration on 31 August, but the signed agreement says 30 September.","zh":"系统里的合同到期日是 8 月 31 日，可签好的协议上写的是 9 月 30 日。"},{"role":"HR Adviser","en":"Check for a later amendment first. If there isn't one, correct the end date in the system.","zh":"先看看后来有没有签过补充协议。如果没有，就把系统里的到期日改过来。"}],"usage":"","distinction":"Contract expiration 和英式英语常用的 contract expiry 都指期限届满；contract termination 更侧重合同被终止。劳动合同期满对雇佣关系的影响要结合当地规则和事实判断。","aliases":[],"new":true,"order":477,"collocationZh":"跟踪劳动合同到期情况","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkɒntrækt ekspəˈreɪʃən","ipaUS":"ˈkɑːntrækt ˌekspɚˈeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Contract expiration","exampleZh":"系统将在合同到期前提醒人力资源部门。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Contract expiration","note":"合同约定期限届满；是否续签或自动终止取决于合同及适用法律。英式常用 contract expiry。","relation":"本词"},{"term":"Employment termination","note":"劳动关系结束的广义概念，不一定提前结束。","relation":"易混淆"},{"term":"Terminate","note":"动词，终止合同或劳动关系；不必然指提前解除。","relation":"易混淆"},{"term":"Expire","note":"动词，期限届满。","relation":"易混淆"},{"term":"Expiry","note":"名词，英式常用，指到期。","relation":"易混淆"},{"term":"Expiration","note":"名词，美式常用，指到期。","relation":"易混淆"},{"term":"Contract renewal","note":"续订合同。","relation":"易混淆"},{"term":"Contract extension","note":"延长现有合同期限。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"How will HR handle this employment matter?","zh":"HR 将如何处理这项雇佣关系事务？"},"extension":{"en":"The dashboard flags upcoming contract expiration dates by department.","zh":"仪表板按部门标出即将到期的合同及其到期日。"}},{"id":"HRV6-M6-105","moduleId":"m6","module":"员工关系与劳动合规","term":"Renewal notice","zh":"合同续签通知","definition":"就合同拟续签、续签选项或办理安排发出的通知。具体内容和法律效力取决于合同、当地规则和通知措辞。","example":"HR sent the renewal notice to the employee last week.","collocation":"issue a renewal notice","dialogue":[{"role":"Employee","en":"I received a renewal notice. Do I need to reply, or is it just letting me know what's coming?","zh":"我收到了续签通知。我需要回复，还是这封邮件只是提前告知安排？"},{"role":"HR Coordinator","en":"For this round, please reply by Friday to let us know if you'd like to discuss the proposed terms.","zh":"这次请最迟周五回复，告诉我们你是否想进一步讨论拟议条款。"}],"usage":"","distinction":"Renewal notice 涉及续签安排或通知要求；expiry reminder 主要提醒到期；notice of non-renewal 用于告知不续签。通知本身是否触发续签要看条款和适用规则。","aliases":[],"new":true,"order":478,"collocationZh":"发出合同续签通知","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˈnjuːəl ˈnəʊtɪs","ipaUS":"rɪˈnuːəl ˈnoʊtəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Renewal notice","exampleZh":"人力资源部门上周已向该员工发出续签通知。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will HR handle this employment matter?","zh":"HR 将如何处理这项雇佣关系事务？"},"extension":{"en":"The renewal notice tells employees whom to contact with questions about the proposed terms.","zh":"续签通知列明了员工对拟议条款有疑问时可联系谁。"}},{"id":"HRV6-M6-106","moduleId":"m6","module":"员工关系与劳动合规","term":"Dismissal","zh":"解雇／雇主解除雇佣关系","definition":"雇主主动结束员工雇佣关系的行为；可能因绩效、违纪或其他适用事由发生。","example":"HR checked whether the proposed dismissal followed the procedure required for that case.","collocation":"review a dismissal decision","dialogue":[{"role":"Line Manager","en":"Should I tell the employee we're going ahead with dismissal at tomorrow's meeting?","zh":"明天开会时，我该告诉员工我们会作出解雇决定吗？"},{"role":"Employee Relations Adviser","en":"Let's review the employee's response and any alternatives before you communicate a decision.","zh":"在正式传达决定前，我们先看员工的回应，再考虑有没有其他处理办法。"}],"usage":"在招聘/员工关系管理语境中应译为“解雇”。","distinction":"Dismissal 通常指雇主结束雇佣关系；resignation 指员工辞职；termination 常泛指雇佣关系终止。英式法律语境下，redundancy 可指因岗位需求减少等原因造成的解雇。","aliases":[],"new":true,"order":479,"collocationZh":"审查解雇决定","collocationReview":"V18.2 模型编辑复核","ipaUK":"dɪˈsmɪsəl","ipaUS":"dɪˈsmɪsəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Dismissal","exampleZh":"人力资源部门核查了拟议的解雇处理是否遵循该个案适用的程序。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Resignation","note":"员工主动辞职。","relation":"易混淆"},{"term":"Dismissal","note":"雇主解除雇佣关系。","relation":"本词"},{"term":"Layoff","note":"通常因业务原因裁减人员，美式也可指暂时停工。","relation":"易混淆"},{"term":"Redundancy","note":"英式常指岗位不再需要而导致的裁员。","relation":"易混淆"},{"term":"Termination for cause","note":"基于特定原因解除雇佣关系，具体标准依合同和法律。","relation":"易混淆"},{"term":"Mutual separation agreement","note":"双方协商结束劳动关系的协议。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"How will HR handle this employment matter?","zh":"HR 将如何处理这项雇佣关系事务？"},"extension":{"en":"The manager recorded the reasons for the dismissal decision in the case file.","zh":"经理在个案档案里记录了解雇决定的理由。"}},{"id":"HRV6-M6-107","moduleId":"m6","module":"员工关系与劳动合规","term":"Wrongful dismissal","zh":"不当解雇（具体法律含义依地区）","definition":"雇主解除雇佣关系引发的法律概念，具体请求依据因法域而异。在大不列颠的雇佣语境中，通常指雇主解雇时违反雇佣合同，例如未按约提供通知或相应付款。","example":"The legal team reviewed the risk of wrongful dismissal.","collocation":"wrongful dismissal claim","dialogue":[{"role":"HR Manager","en":"This claim in England alleges wrongful dismissal. What should I pull together for counsel?","zh":"这宗英格兰案件提出了不当解雇申索。我该给法律顾问准备哪些材料？"},{"role":"Legal Adviser","en":"Start with the signed contract, the notice letter and any record of payment instead of notice.","zh":"先找出已签署的合同、解雇通知和任何代通知付款的记录。"}],"usage":"","distinction":"在大不列颠，wrongful dismissal 通常涉及合同义务，例如通知期；unfair dismissal 是有独立适用条件的法定申索，涉及解雇的公平性。其他法域的 wrongful dismissal 可能采用不同标准。","aliases":[],"new":true,"order":480,"collocationZh":"不当解雇申索","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈrɒŋfəl dɪˈsmɪsəl","ipaUS":"ˈrɔːŋfəl dɪˈsmɪsəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Wrongful dismissal","exampleZh":"法务团队审查了不当解雇的法律风险。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will HR handle this employment matter?","zh":"HR 将如何处理这项雇佣关系事务？"},"extension":{"en":"The adviser compared the notice given with the contract when reviewing the wrongful dismissal claim.","zh":"审查不当解雇申索时，顾问将实际发出的通知与合同约定进行了比对。"}},{"id":"HRV6-M6-108","moduleId":"m6","module":"员工关系与劳动合规","term":"Termination letter","zh":"雇佣关系终止通知书／解雇通知书","definition":"书面通知员工雇佣关系将结束的文件，常列明终止日期及相关事项。名称和内容要求随情形和当地规定而异。","example":"Our termination letter template includes a field for the effective date.","collocation":"issue a termination letter","dialogue":[{"role":"Line Manager","en":"The termination letter lists the same date for the last day on site and the end of employment. Are those dates correct?","zh":"终止通知书把最后一天到岗和劳动关系终止写成了同一天。这两个日期都对吗？"},{"role":"HR Adviser","en":"Let me check the agreed dates with payroll before we send it.","zh":"发出前，我先跟薪资团队核对一下已确认的日期。"}],"usage":"","distinction":"Termination letter 用于正式通知雇佣关系结束；warning letter 用于告知问题及改进要求；separation agreement 则记录双方就结束雇佣关系达成的约定。","aliases":[],"new":true,"order":481,"collocationZh":"发出解除雇佣通知书","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌtɜːmɪˈneɪʃən ˈletə","ipaUS":"tɚməˈneɪʃən ˈletɚ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Termination letter","exampleZh":"我们的雇佣关系终止通知书模板设有一栏，用来填写终止生效日期。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will HR handle this employment matter?","zh":"HR 将如何处理这项雇佣关系事务？"},"extension":{"en":"HR filed the signed termination letter with the delivery record.","zh":"人力资源部门把签署后的终止通知书和送达记录一并归档。"}},{"id":"HRV6-M6-109","moduleId":"m6","module":"员工关系与劳动合规","term":"Mutual separation agreement","zh":"协商解除劳动关系协议","definition":"雇主与员工通过书面协议约定结束雇佣关系的条件。","example":"Both parties signed a mutual separation agreement.","collocation":"sign a mutual separation agreement","dialogue":[{"role":"Employee","en":"I'd like time to read the mutual separation agreement and get advice before I respond.","zh":"我想先花些时间读完协商解除协议，再听听专业意见，然后作答复。"},{"role":"HR Partner","en":"Of course. I'll send you the draft we discussed, and we can arrange a call once you've had a chance to review it.","zh":"可以。我会把刚讨论的草案发给你，等你看过后，我们再约时间通话。"}],"usage":"","distinction":"Mutual separation agreement 由双方协商确定离职安排；resignation 是员工辞职，dismissal 通常由雇主作出。Settlement agreement 在一些法域还涉及争议和解或权利放弃，并可能有特定形式要求。","aliases":[],"new":true,"order":482,"collocationZh":"签署协商解除劳动关系协议","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈmjuːtʃuːəl ˌsepəˈreɪʃən əˈɡriːmənt","ipaUS":"ˈmjuːtʃuːəl ˌsepɚˈeɪʃən əˈɡriːmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Mutual separation agreement","exampleZh":"双方签署了协商解除劳动关系协议。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","comparison":[{"term":"Resignation","note":"员工主动辞职。","relation":"易混淆"},{"term":"Dismissal","note":"雇主解除雇佣关系。","relation":"易混淆"},{"term":"Layoff","note":"通常因业务原因裁减人员，美式也可指暂时停工。","relation":"易混淆"},{"term":"Redundancy","note":"英式常指岗位不再需要而导致的裁员。","relation":"易混淆"},{"term":"Termination for cause","note":"基于特定原因解除雇佣关系，具体标准依合同和法律。","relation":"易混淆"},{"term":"Mutual separation agreement","note":"双方协商结束劳动关系的协议。","relation":"本词"}],"legacyDialogueBookmark":{"en":"How will HR handle this employment matter?","zh":"HR 将如何处理这项雇佣关系事务？"},"extension":{"en":"The draft mutual separation agreement sets out the proposed departure date and handover arrangements.","zh":"协商解除协议草案列明了拟定的离职日期和交接安排。"}},{"id":"HRV6-M6-110","moduleId":"m6","module":"员工关系与劳动合规","term":"Severance package","zh":"离职补偿方案／遣散方案","definition":"雇佣关系结束时涉及的补偿与支持安排，可包括现金补偿、福利延续或职业过渡服务，具体视适用规定、政策和协议而定。","example":"The proposed severance package includes a lump-sum payment and career transition support.","collocation":"negotiate a severance package","dialogue":[{"role":"Employee","en":"Does the severance package cover career coaching, or is it just the payment in this table?","zh":"离职补偿方案包括职业辅导吗，还是只有表里这笔款项？"},{"role":"HR Partner","en":"It includes three coaching sessions under this offer. I'll show you where the terms explain how to book them.","zh":"按这份方案，包括三次辅导。我给你指出条款里写预约方式的地方。"}],"usage":"","distinction":"Severance package 指整体补偿和支持安排；severance pay 专指其中的现金补偿；final pay 指最后一期工资结算，未休假折算等款项是否计入依当地规则和具体情况而定。","aliases":[],"new":true,"order":483,"collocationZh":"协商离职补偿方案","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsev.ər.əns ˈpæk.ɪdʒ","ipaUS":"ˈsev.ɚ.əns ˈpæk.ɪdʒ","ipaSource":"https://dictionary.cambridge.org/dictionary/english/severance | https://dictionary.cambridge.org/dictionary/english/package","speakTerm":"Severance package","exampleZh":"拟议的离职补偿方案包括一笔一次性补偿款和职业过渡支持。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will HR handle this employment matter?","zh":"HR 将如何处理这项雇佣关系事务？"},"extension":{"en":"The employee asked HR for a written breakdown of the severance package.","zh":"员工请人力资源部门提供一份书面的离职补偿明细。"}},{"id":"HRV6-M6-111","moduleId":"m6","module":"员工关系与劳动合规","term":"Payment in lieu of notice (PILON)","zh":"代通知金／以付款替代通知期","definition":"在适用法律或合同允许的情况下，用付款替代全部或部分通知期的安排。PILON 常见于英式雇佣语境。","example":"The employer offered payment in lieu of notice.","collocation":"make a payment in lieu of notice","dialogue":[{"role":"HR Partner","en":"The contract has a payment in lieu of notice clause. Can we use it for only part of the notice period?","zh":"合同有代通知金条款。可以只对部分通知期使用这项条款吗？"},{"role":"Employment Counsel","en":"Let's check the wording and the applicable rules before we propose an end date.","zh":"先核对条款措辞和适用规则，再提出劳动关系结束日期。"}],"usage":"常见于英式雇佣合同；代通知金可能使雇佣立即结束，法律效果依条款。","distinction":"英国雇佣语境下，PILON 通常以付款替代通知期，雇佣关系可随之提前结束；garden leave 通常指员工在通知期内继续受雇，但按安排不实际履职。是否适用及金额取决于条款和当地规则。","aliases":[],"new":true,"order":484,"collocationZh":"支付代通知金","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈpeɪmənt ɪn luː ɒv ˈnəʊtɪs","ipaUS":"ˈpeɪmənt ɪn luː ʌv ˈnoʊtəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Payment in lieu of notice","exampleZh":"雇主提出支付代通知金。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will HR handle this employment matter?","zh":"HR 将如何处理这项雇佣关系事务？"},"extension":{"en":"Payroll recorded the payment in lieu of notice separately from the final salary payment.","zh":"薪资团队将代通知金和最后一笔工资分开入账。"}},{"id":"HRV6-M6-112","moduleId":"m6","module":"员工关系与劳动合规","term":"Non-solicitation clause","zh":"禁止招揽条款","definition":"限制招揽特定客户、员工等对象的合同条款。在雇佣合同中常涉及离职后的行为，适用范围和可执行性依条款及当地法律而异。","example":"The agreement includes a non-solicitation clause.","collocation":"review a non-solicitation clause","dialogue":[{"role":"Sales Manager","en":"A former client contacted me first. Does that matter under the non-solicitation clause?","zh":"以前的客户先来联系我。按禁止招揽条款，这一点有影响吗？"},{"role":"Employment Counsel","en":"It could. Send me the clause and the client's message so I can check what the restriction covers.","zh":"可能有影响。把条款和客户的消息发给我，我核对一下限制范围。"}],"usage":"","distinction":"Non-solicitation clause 通常限制主动招揽特定客户或员工；non-compete clause 侧重限制从事竞争业务；non-dealing clause 可能连未主动招揽的交易也涵盖。实际范围以条款和适用法律为准。","aliases":[],"new":true,"order":485,"collocationZh":"审阅禁止招揽条款","collocationReview":"V18.2 模型编辑复核","ipaUK":"nɒn səˌlɪsɪˈteɪʃən klɔːz","ipaUS":"nɑːn səˌlɪsɪˈteɪʃən klɔːz","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Non-solicitation clause","exampleZh":"协议中包含禁止招揽条款。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will HR handle this employment matter?","zh":"HR 将如何处理这项雇佣关系事务？"},"extension":{"en":"The non-solicitation clause lists the types of clients it covers.","zh":"禁止招揽条款列明了其涵盖的客户类别。"}},{"id":"HRV6-M6-113","moduleId":"m6","module":"员工关系与劳动合规","term":"Restrictive covenant","zh":"离职后限制性约定","definition":"在雇佣语境中，约束员工离职后某些行为的合同约定，例如竞业限制或禁止招揽。具体限制及其可执行性取决于条款与适用法律。","example":"Legal counsel reviewed the restrictive covenant before the offer.","collocation":"review a restrictive covenant","dialogue":[{"role":"Recruiter","en":"The candidate says a restrictive covenant from her last job may affect her start date.","zh":"候选人说，上一份工作的离职后限制性约定可能影响她的入职日期。"},{"role":"HR Partner","en":"Let's ask legal to review the wording before we confirm when she can start.","zh":"我们先请法务看看条款，再确认她什么时候能入职。"}],"usage":"","distinction":"Restrictive covenant 是限制性约定的上位说法；non-compete 和 non-solicitation 分别限制竞争活动和招揽行为。Confidentiality clause 则保护特定信息，可在任职期间及离职后适用。","aliases":[],"new":true,"order":486,"collocationZh":"审查离职后限制性约定","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˈstrɪktɪv ˈkʌvenənt","ipaUS":"riːˈstrɪktɪv ˈkʌvənənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Restrictive covenant","exampleZh":"发出录用通知前，法律顾问审查了离职后限制性约定。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will HR handle this employment matter?","zh":"HR 将如何处理这项雇佣关系事务？"},"extension":{"en":"The legal team reviewed whether the restrictive covenant was enforceable in the employee's jurisdiction.","zh":"法务团队审查了这项离职后限制性约定在该员工所在法域是否具有可执行性。"}},{"id":"HRV6-M6-114","moduleId":"m6","module":"员工关系与劳动合规","term":"Suspension","zh":"停职／暂停履职","definition":"暂时停止员工履行工作职责的措施，可用于调查、风险控制或纪律处理。是否带薪及其他条件取决于当地法律、合同和公司政策。","example":"The employee was suspended pending the outcome of the investigation.","collocation":"suspension pending investigation","dialogue":[{"role":"Line Manager","en":"What should I tell the team while Kai is on suspension?","zh":"凯停职期间，我该怎么跟团队说？"},{"role":"Employee Relations Adviser","en":"Tell them who's covering his work. Any questions about the investigation should come to me.","zh":"告诉大家谁来接手他的工作就好。有关调查的问题，让他们来问我。"}],"usage":"在纪律调查场景中是暂停履职，不等于通知期带薪免到岗。","distinction":"Suspension 可发生在员工仍受雇期间，例如等待调查结果；garden leave 通常发生在离职通知期。调查期间停职本身不代表认定员工存在违纪。","aliases":[],"new":true,"order":487,"collocationZh":"调查期间停职","collocationReview":"V18.2 模型编辑复核","ipaUK":"səˈspenʃən","ipaUS":"səˈspenʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Suspension","exampleZh":"调查结果出来前，该员工暂时停职。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Is the employee on suspension while the investigation is ongoing?","zh":"调查期间，这名员工是否处于停职状态？"},"extension":{"en":"The suspension letter names the contact who will provide updates during the investigation.","zh":"停职通知书写明了调查期间由谁提供进展信息。"}},{"id":"HRV6-M6-115","moduleId":"m6","module":"员工关系与劳动合规","term":"Employee misconduct","zh":"员工违纪行为／不当行为","definition":"员工在工作相关情境中违反适用行为规范、公司政策或法律义务的行为。是否构成违纪需要根据事实及适用规则判断。","example":"The investigation examined the alleged employee misconduct.","collocation":"investigate employee misconduct","dialogue":[{"role":"Line Manager","en":"Two employees say a colleague changed the time records without approval. Should I treat that as misconduct?","zh":"两名员工说有位同事未经批准改了考勤记录。我要按违纪处理吗？"},{"role":"Employee Relations Adviser","en":"Record what was reported and preserve the original entries. We'll review the facts before drawing a conclusion.","zh":"先记录他们反映的情况，保留原始记录。我们核查事实后再作判断。"}],"usage":"","distinction":"Employee misconduct 关注违反行为规范；poor performance 关注未达到工作要求；gross misconduct 指可能构成严重违纪的行为，具体判断依事实、政策及当地法律。","aliases":[],"new":true,"order":488,"collocationZh":"调查员工违纪行为","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː mɪˈskɒndʌkt","ipaUS":"ɪmˈplɔɪ.iː mɪˈskɑːndəkt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee misconduct","exampleZh":"调查审查了有关员工涉嫌不当行为的指控。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will HR handle this employment matter?","zh":"HR 将如何处理这项雇佣关系事务？"},"extension":{"en":"The handbook gives examples of employee misconduct and explains how concerns are reviewed.","zh":"员工手册列举了员工不当行为的例子，并说明如何处理相关反映。"}},{"id":"HRV6-M6-116","moduleId":"m6","module":"员工关系与劳动合规","term":"Exit clearance","zh":"离职手续确认／离职交接核验","definition":"离职流程中核验资产归还、工作交接、系统权限处理等事项是否完成的环节，各组织所需的签核项目可能不同。","example":"Our exit clearance checklist asks managers to confirm that company equipment has been returned.","collocation":"complete exit clearance","dialogue":[{"role":"Departing Employee","en":"I've handed over my projects, but my exit clearance still shows one item open.","zh":"我的项目都交接完了，不过离职交接系统里还有一项没完成。"},{"role":"HR Coordinator","en":"It's the access card. Reception can mark it as returned when you drop it off.","zh":"还差门禁卡。你把卡交给前台，他们就能登记归还。"}],"usage":"","distinction":"Exit clearance 侧重逐项核验或签核离职交接事项；offboarding 指完整离职流程；final pay 是工资结算事项，应按适用规定处理。","aliases":[],"new":true,"order":489,"collocationZh":"完成离职交接确认","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈeɡzɪt ˈkliərəns","ipaUS":"ˈeɡzɪt ˈklɪrəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Exit clearance","exampleZh":"我们的离职交接清单要求经理确认公司设备已归还。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How will HR handle this employment matter?","zh":"HR 将如何处理这项雇佣关系事务？"},"extension":{"en":"The exit clearance record shows which departments have signed off.","zh":"离职交接记录显示哪些部门已经签核。"}},{"id":"HRV6-M7-101","moduleId":"m7","module":"企业文化与员工体验","term":"Employer brand","zh":"雇主品牌","definition":"求职者、员工与社会公众对企业作为雇主的整体认知和评价。","example":"Our employer brand is strongest among early-career talent.","collocation":"strengthen the employer brand","dialogue":[{"role":"Recruiter","en":"Candidates keep asking whether our flexible hours apply to the support team, too.","zh":"候选人总问，客服团队也能享受灵活工时吗？"},{"role":"Communications Lead","en":"Let's check with the team before we use flexible hours to promote our employer brand.","zh":"先跟客服团队核实，再把灵活工时当作雇主品牌的卖点。"}],"usage":"Employer brand 是品牌本身；employer branding 是建设品牌的策略和活动。","distinction":"Employer brand 是企业作为雇主给人留下的形象；employer branding 指塑造和维护这种形象的活动；employer reputation 更侧重外界基于实际经历或公开信息形成的口碑。","aliases":[],"new":true,"order":490,"collocationZh":"提升雇主品牌影响力","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.ə brænd","ipaUS":"ɪmˈplɔɪ.ɚ brænd","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employer brand","exampleZh":"在初入职场的人才群体中，我们的雇主品牌最具吸引力。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How do applicants perceive our employer brand?","zh":"应聘者如何看待我们的雇主品牌？"},"extension":{"en":"Our employer brand benefits when employees can see the career opportunities we talk about in recruitment.","zh":"当员工确实能获得招聘时所介绍的职业发展机会，雇主品牌也会受益。"}},{"id":"HRV6-M7-102","moduleId":"m7","module":"企业文化与员工体验","term":"Employee satisfaction","zh":"员工满意度","definition":"员工对工作内容、管理方式、薪酬福利或整体任职体验的满意程度。","example":"The employee satisfaction score improved this quarter.","collocation":"measure employee satisfaction","dialogue":[{"role":"People Analyst","en":"The overall employee satisfaction score is steady, but the comments on workload are getting worse.","zh":"员工满意度总分没什么变化，但关于工作量的反馈越来越差。"},{"role":"HR Partner","en":"Can you pull out the workload responses by shift for teams with enough responses to report separately?","zh":"能按班次把工作量方面的反馈单独整理出来吗？只看反馈数量足够、可以单独报告的团队。"}],"usage":"","distinction":"Employee satisfaction 衡量员工对工作及相关条件是否满意；employee engagement 侧重投入、热忱和对工作的联结；满意度高的员工也可能参与度较低。","aliases":[],"new":true,"order":491,"collocationZh":"衡量员工满意度","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˌsætɪsˈfækʃən","ipaUS":"ɪmˈplɔɪ.iː ˌsætəsˈfækʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee satisfaction","exampleZh":"本季度员工满意度得分有所提升。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we improving the employee experience?","zh":"我们正在采取哪些措施改善员工体验？"},"extension":{"en":"Employee satisfaction with scheduling rose after teams gained more control over shift swaps.","zh":"团队获得更大的换班自主权后，员工对排班的满意度提高了。"}},{"id":"HRV6-M7-103","moduleId":"m7","module":"企业文化与员工体验","term":"Stay interview","zh":"留任访谈","definition":"雇主主动与在职员工沟通其留任动机、风险与改善需求的访谈。","example":"Managers will conduct stay interviews with key employees.","collocation":"conduct a stay interview","dialogue":[{"role":"Manager","en":"At the stay interview, Priya said she'd like more chances to lead client meetings.","zh":"留任访谈时，普丽娅说她希望有更多机会主持客户会议。"},{"role":"HR Partner","en":"Could she lead the next one with you there for support?","zh":"下次能不能让她来主持，你在场支持一下？"}],"usage":"","distinction":"Stay interview 与仍在职的员工讨论其愿意留下的原因和可能影响留任的因素；exit interview 面向即将离职的员工；performance review 主要评估工作表现。","aliases":[],"new":true,"order":492,"collocationZh":"开展留任访谈","collocationReview":"V18.2 模型编辑复核","ipaUK":"steɪ ˈɪn.tə.vjuː","ipaUS":"steɪ ˈɪn.tɚ.vjuː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Stay interview","exampleZh":"管理者将与关键员工开展留任访谈。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we improving the employee experience?","zh":"我们正在采取哪些措施改善员工体验？"},"extension":{"en":"In the stay interview, the employee said that a more predictable schedule would make it easier to stay.","zh":"在留任访谈中，员工说，如果排班更稳定，自己就更容易留下来。"}},{"id":"HRV6-M7-104","moduleId":"m7","module":"企业文化与员工体验","term":"Employee feedback channel","zh":"员工意见反馈渠道","definition":"员工用来提交意见、建议、问题或关切的途径，例如反馈表、热线或定期座谈。","example":"We launched an anonymous employee feedback channel.","collocation":"open an employee feedback channel","dialogue":[{"role":"Employee","en":"Several of us have ideas for making shift handovers easier. Where should we send them?","zh":"我们几个人有些想法，能让交接班更顺畅。建议应该发到哪里？"},{"role":"HR Coordinator","en":"Use the employee feedback channel and choose “Work processes.” The operations team reviews those suggestions each week.","zh":"到员工意见反馈渠道里选“工作流程”。运营团队每周都会看这类建议。"}],"usage":"","distinction":"Employee feedback channel 可收集一般建议、问题和关切；grievance procedure 通常指正式申诉及处理程序；whistleblowing channel 往往用于举报特定类型的不当行为，适用范围因地区和制度而异。","aliases":[],"new":true,"order":493,"collocationZh":"开通员工意见反馈渠道","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˈfiːdbæk ˈtʃænəl","ipaUS":"ɪmˈplɔɪ.iː ˈfiːdbæk ˈtʃænəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee feedback channel","exampleZh":"我们开通了匿名员工反馈渠道。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we improving the employee experience?","zh":"我们正在采取哪些措施改善员工体验？"},"extension":{"en":"The employee feedback channel publishes a monthly summary of common themes and responses.","zh":"员工意见反馈渠道每月公布一份摘要，汇总常见问题和处理回应。"}},{"id":"HRV6-M7-105","moduleId":"m7","module":"企业文化与员工体验","term":"Employer reputation","zh":"雇主声誉","definition":"员工、求职者和社会公众基于雇佣实践、员工待遇等形成的对企业的评价。","example":"A strong employer reputation can encourage more qualified candidates to apply.","collocation":"protect employer reputation","dialogue":[{"role":"Recruiter","en":"Two candidates mentioned the same online reviews about unpaid overtime.","zh":"有两位候选人都提到网上那些说加班没有报酬的评价。"},{"role":"HR Director","en":"Let's look at what's happening in those teams. Our employer reputation will depend on how we address any real issues.","zh":"我们先了解那些团队的实际情况。如果确实有问题，我们怎么处理会影响雇主声誉。"}],"usage":"","distinction":"Employer reputation 侧重员工、候选人等人群已经形成的口碑；employer brand 还涉及企业主动塑造的雇主形象；corporate reputation 涵盖产品、经营和社会责任等更广泛的评价。","aliases":[],"new":true,"order":494,"collocationZh":"维护雇主声誉","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.ə ˌrepjuːˈteɪʃən","ipaUS":"ɪmˈplɔɪ.ɚ ˌrepjəˈteɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employer reputation","exampleZh":"良好的雇主声誉有助于吸引更多符合条件的候选人申请。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we improving the employee experience?","zh":"我们正在采取哪些措施改善员工体验？"},"extension":{"en":"How a company handles candidate feedback can affect its employer reputation.","zh":"企业如何处理候选人的反馈，可能影响其雇主声誉。"}},{"id":"HRV6-M7-106","moduleId":"m7","module":"企业文化与员工体验","term":"New hire experience","zh":"新员工入职体验","definition":"员工从录用到融入团队期间，对手续、培训、支持和文化的整体感受。","example":"The survey tracks the new hire experience during employees' first 90 days on the job.","collocation":"improve the new hire experience","dialogue":[{"role":"Team Lead","en":"Our last two hires spent their first morning waiting for system access.","zh":"最近入职的两位新员工，第一天上午都在等系统权限。"},{"role":"Onboarding Partner","en":"Let's ask IT to check access the day before. That would make a real difference to the new hire experience.","zh":"我们请 IT 提前一天确认权限吧。这样新员工入职时会顺利很多。"}],"usage":"","distinction":"New hire experience 指新员工在入职及融入过程中的整体感受；onboarding 指企业为帮助新员工上手所安排的流程；orientation 通常指入职初期的介绍或说明活动。","aliases":[],"new":true,"order":495,"collocationZh":"改善新员工入职体验","collocationReview":"V18.2 模型编辑复核","ipaUK":"njuː ˈhaɪə ekˈspiərɪəns","ipaUS":"nuː ˈhaɪɚ ɪkˈspɪriːəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"New hire experience","exampleZh":"这项调查跟踪新员工入职后前 90 天的体验。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we improving the employee experience?","zh":"我们正在采取哪些措施改善员工体验？"},"extension":{"en":"Having a named contact before day one can improve the new hire experience.","zh":"如果在上班第一天之前就有明确的联系人，新员工的入职体验会更好。"}},{"id":"HRV6-M7-107","moduleId":"m7","module":"企业文化与员工体验","term":"Employee volunteering","zh":"员工志愿服务","definition":"企业组织或支持员工自愿参加公益与社区服务的活动。","example":"Employee volunteering is part of our community program.","collocation":"promote employee volunteering","dialogue":[{"role":"Employee","en":"The food bank needs help on Thursday mornings. Could we make that one of our employee volunteering options?","zh":"食品银行周四上午需要人帮忙。能把这项活动加到员工志愿服务的选项里吗？"},{"role":"Community Program Lead","en":"Yes. I'll ask how many people they can take, and we can open a sign-up once we know.","zh":"可以。我先问问他们能接收多少人，确定后就可以开放报名。"}],"usage":"","distinction":"Employee volunteering 指由员工自愿投入时间或技能参与公益；corporate giving 侧重公司捐款或捐物；volunteer time off 是部分企业给员工提供的志愿服务休假安排。","aliases":[],"new":true,"order":496,"collocationZh":"推动员工志愿服务","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˌvɒlənˈtiərɪŋ","ipaUS":"ɪmˈplɔɪ.iː ˌvɔːlənˈtɪrɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee volunteering","exampleZh":"员工志愿服务是公司社区项目的一部分。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we improving the employee experience?","zh":"我们正在采取哪些措施改善员工体验？"},"extension":{"en":"Employee volunteering can include sharing professional skills with a local nonprofit.","zh":"员工志愿服务可以是为当地非营利机构提供专业技能支持。"}},{"id":"HRV6-M7-108","moduleId":"m7","module":"企业文化与员工体验","term":"Recognition program","zh":"员工表彰计划","definition":"以公开致谢、提名、奖项等方式认可员工贡献和团队成就的制度化安排。","example":"The recognition program celebrates employees who collaborate across teams.","collocation":"launch a recognition program","dialogue":[{"role":"Team Lead","en":"Could I nominate everyone who helped with the system migration?","zh":"参与系统迁移的同事，我能一起提名吗？"},{"role":"HR Coordinator","en":"Yes, the recognition program has a team category. Tell us what the group achieved together.","zh":"可以，表彰计划设有团队类别。写清楚他们一起完成了什么就行。"}],"usage":"","distinction":"Recognition program 侧重认可已经展现的贡献或行为；incentive plan 往往事先规定达成目标可获何种激励；recognition 可以采用公开致谢等非现金形式。","aliases":[],"new":true,"order":497,"collocationZh":"推出员工表彰计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌrekəɡˈnɪʃən ˈprəʊɡræm","ipaUS":"ˌrekəɡˈnɪʃən ˈproʊɡræm","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Recognition program","exampleZh":"员工表彰计划嘉奖积极开展跨团队协作的员工。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we improving the employee experience?","zh":"我们正在采取哪些措施改善员工体验？"},"extension":{"en":"The recognition program accepts nominations from peers as well as managers.","zh":"员工表彰计划接受同事提名，也接受管理者提名。"}},{"id":"HRV6-M7-109","moduleId":"m7","module":"企业文化与员工体验","term":"Employee sentiment","zh":"员工情绪与态度／员工态度倾向","definition":"通过调查、访谈或其他反馈反映出的员工对工作、政策或组织的总体情绪与态度。","example":"Survey responses suggested that employee sentiment toward the policy became more positive after the update.","collocation":"track employee sentiment","dialogue":[{"role":"People Analyst","en":"Employee sentiment about the new shift pattern looks mixed. The comments from night staff are mostly about commuting.","zh":"员工对新排班的态度有好有坏。夜班员工的留言主要讲的是通勤。"},{"role":"Operations Lead","en":"Let's check which start times cause the most problems before we adjust the rota.","zh":"我们先弄清楚哪些上班时间最不方便，再调整排班。"}],"usage":"","distinction":"Employee sentiment 可以针对某件事，反映反馈中的正负倾向或具体情绪；employee satisfaction 通常直接衡量满意程度；engagement 更侧重投入和联结。","aliases":[],"new":true,"order":498,"collocationZh":"跟踪员工情绪与态度倾向","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˈsentɪmənt","ipaUS":"ɪmˈplɔɪ.iː ˈsentəmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee sentiment","exampleZh":"调查反馈显示，政策更新后，员工对该政策的态度似乎更加积极。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we improving the employee experience?","zh":"我们正在采取哪些措施改善员工体验？"},"extension":{"en":"The analyst coded open-ended comments to understand employee sentiment about the office move.","zh":"分析师对开放题留言做了分类，以了解员工对办公室搬迁的态度。"}},{"id":"HRV6-M7-110","moduleId":"m7","module":"企业文化与员工体验","term":"Workplace climate","zh":"职场氛围／工作氛围","definition":"员工对团队互动、领导方式及日常工作环境的集体体验。","example":"The survey assesses workplace climate across teams.","collocation":"improve workplace climate","dialogue":[{"role":"Team Lead","en":"People seem comfortable raising problems one-on-one, but the team meetings are silent.","zh":"大家私下愿意提问题，到了团队会上却都不说话。"},{"role":"HR Partner","en":"That tells us something about the workplace climate. Could we ask the team what would make it easier to speak up in meetings?","zh":"这反映出团队的工作氛围。我们能不能问问大家，怎样才能让他们在会上更愿意开口？"}],"usage":"","distinction":"Workplace climate 指员工对当前工作环境、人际互动或公平性的共同感受；organizational culture 涉及较深层、长期形成的价值观和惯例；psychological safety 聚焦能否放心提问、发言或承认错误。","aliases":[],"new":true,"order":499,"collocationZh":"改善职场氛围","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈwɜːkpleɪs ˈklaɪmət","ipaUS":"ˈwɝːkpleɪs ˈklaɪmət","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Workplace climate","exampleZh":"调查评估了不同团队的职场氛围。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we improving the employee experience?","zh":"我们正在采取哪些措施改善员工体验？"},"extension":{"en":"A change in how managers respond to mistakes can improve the workplace climate.","zh":"管理者改变处理错误的方式，有助于改善职场氛围。"}},{"id":"HRV6-M7-111","moduleId":"m7","module":"企业文化与员工体验","term":"Employee voice","zh":"员工发声／员工意见表达","definition":"员工通过个人或集体渠道表达意见、提出关切，并有机会影响工作相关决策的实践。","example":"Employee voice is a key part of an inclusive culture.","collocation":"strengthen employee voice","dialogue":[{"role":"Employee Representative","en":"The draft schedule is already on the wall. Is there still room for employee voice before it goes live?","zh":"排班草案已经贴出来了。正式实行前，员工还有机会提意见吗？"},{"role":"Operations Manager","en":"Yes. We're holding a review on Wednesday, and we can still change the start times based on what we hear.","zh":"有。周三开会讨论，大家提了意见，我们还可以调整上班时间。"}],"usage":"","distinction":"Employee voice 指员工表达并有机会影响决策的广义实践；feedback channel 只是其中一种途径；employee representation 则指通过员工代表、工会等集体机制表达意见，具体形式依地区和制度而异。","aliases":[],"new":true,"order":500,"collocationZh":"拓宽员工发声渠道","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː vɔɪs","ipaUS":"ɪmˈplɔɪ.iː vɔɪs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee voice","exampleZh":"员工发声是包容性文化的重要组成部分。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we improving the employee experience?","zh":"我们正在采取哪些措施改善员工体验？"},"extension":{"en":"Employee voice helped shape the changes to the shift-swap policy.","zh":"员工的意见帮助公司调整了换班政策。"}},{"id":"HRV6-M7-112","moduleId":"m7","module":"企业文化与员工体验","term":"Culture fit interview","zh":"文化契合度面试","definition":"围绕与岗位相关的组织价值观及工作方式，以结构化问题了解候选人过往行为的面试安排。","example":"For the culture fit interview, ask each candidate the same job-related questions and use a common scoring guide.","collocation":"design a culture fit interview","dialogue":[{"role":"Interviewer","en":"I wrote “not a fit” in my notes, but I'm struggling to explain why.","zh":"我在面试记录里写了“不契合”，但说不上来原因。"},{"role":"Recruiter","en":"For the culture fit interview, tie your rating to something the candidate did or said that relates to one of the agreed criteria.","zh":"评文化契合度时，要用候选人的具体言行来说明评分，并对应到事先约定的一项标准。"}],"usage":"","distinction":"Culture fit interview 关注与岗位有关的组织价值观和工作方式，宜以具体行为为依据，避免把个人相似性当成标准；culture add 强调候选人可以带来的新视角和经验。","aliases":[],"new":true,"order":501,"collocationZh":"设计文化契合度面试","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈkʌltʃə fɪt ˈɪn.tə.vjuː","ipaUS":"ˈkʌltʃɚ fɪt ˈɪn.tɚ.vjuː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Culture fit interview","exampleZh":"做文化契合度面试时，应向每位候选人提出同样的岗位相关问题，并采用统一的评分指引。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we improving the employee experience?","zh":"我们正在采取哪些措施改善员工体验？"},"extension":{"en":"The culture fit interview asks candidates how they handled disagreement on a cross-functional team.","zh":"文化契合度面试会请候选人讲述自己如何处理跨职能团队中的分歧。"}},{"id":"HRV6-M7-113","moduleId":"m7","module":"企业文化与员工体验","term":"Wellbeing program","zh":"员工身心健康支持计划","definition":"为员工身心健康、压力管理和工作生活平衡提供的企业项目。","example":"Our wellbeing program includes access to counseling through an external provider.","collocation":"offer a wellbeing program","dialogue":[{"role":"Employee","en":"If I book a counseling session through the wellbeing program, what information goes back to the company?","zh":"如果我通过身心健康支持计划预约心理咨询，公司会收到哪些信息？"},{"role":"Benefits Partner","en":"The provider's privacy notice explains what they share and when. I'll send you the link before you decide whether to book.","zh":"服务机构的隐私说明写了什么情况会共享哪些信息。我把链接发给你，你看过再决定是否预约。"}],"usage":"","distinction":"Wellbeing program 可覆盖身心健康、压力管理或工作生活平衡等；employee assistance program（EAP）通常提供咨询、转介等具体服务，可能是身心健康计划的一部分。","aliases":[],"new":true,"order":502,"collocationZh":"提供员工身心健康支持计划","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈwelbiːɪŋ ˈprəʊɡræm","ipaUS":"ˌwelˈbiːɪŋ ˈproʊɡræm","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Wellbeing program","exampleZh":"我们的员工身心健康支持计划包括由外部服务机构提供的心理咨询。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How are we improving the employee experience?","zh":"我们正在采取哪些措施改善员工体验？"},"extension":{"en":"The wellbeing program added lunchtime sessions on managing stress during peak periods.","zh":"员工身心健康支持计划增设了午间课程，介绍业务旺季如何管理压力。"}},{"id":"HRV6-M8-101","moduleId":"m8","module":"HR运营与数据分析","term":"Employee turnover rate","zh":"员工离职率","definition":"一定统计期内离职人数相对于同期约定在职人数基数的比例，常以期间平均在职人数为分母。需说明纳入哪些离职类型。","example":"The employee turnover rate declined in the second quarter.","collocation":"calculate the employee turnover rate","dialogue":[{"role":"Finance Partner","en":"Does the employee turnover rate include people who moved to another team?","zh":"员工离职率算进调到其他团队的人吗？"},{"role":"People Analyst","en":"In the company-wide figure, no. We count people who left the company during the quarter.","zh":"公司整体数据里不算。我们只统计本季度离开公司的人。"}],"usage":"计算时需明确分母（期初、期末或平均人数）及离职类型。","distinction":"Employee turnover rate 通常衡量一定期间的员工离职比例，可按主动、非主动等类型拆分；attrition rate 有时近义，有时专指自然减员或离岗后不补员，比较前要核对分子和分母。","aliases":[],"new":true,"order":503,"collocationZh":"计算员工离职率","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˈtɜːnəʊvə reɪt","ipaUS":"ɪmˈplɔɪ.iː ˈtɝːˌnoʊvɚ reɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee turnover rate","exampleZh":"第二季度员工离职率下降了。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What needs to be updated in HR operations?","zh":"HR 运营方面有哪些信息需要更新？"},"extension":{"en":"The report breaks down the employee turnover rate by tenure group.","zh":"报告按司龄组拆分了员工离职率。"}},{"id":"HRV6-M8-102","moduleId":"m8","module":"HR运营与数据分析","term":"Employee ID","zh":"员工编号／工号","definition":"在组织或 HR 系统中用于区分员工记录的唯一标识，可由数字或字母组成。","example":"Please enter your employee ID to access the HR portal.","collocation":"verify an employee ID","dialogue":[{"role":"Payroll Analyst","en":"I have two people named Alex Chen in this file. Which one did the adjustment apply to?","zh":"文件里有两个人都叫亚历克斯·陈。这笔调整是给谁的？"},{"role":"HR Coordinator","en":"Check the employee ID on the approved adjustment form. It ends in 482.","zh":"看已审批的调整单上的工号，尾号是 482。"}],"usage":"","distinction":"Employee ID 在 HR 系统中通常指员工编号，也可在门禁语境中指员工证件；employee ID number 明确指编号；position ID 用于识别岗位，可在任职者更换后保留。","aliases":[],"new":true,"order":504,"collocationZh":"核验员工工号","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː aɪ diː","ipaUS":"ɪmˈplɔɪ.iː aɪ diː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee I D","exampleZh":"请输入工号以访问人力资源门户。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What needs to be updated in HR operations?","zh":"HR 运营方面有哪些信息需要更新？"},"extension":{"en":"Use the employee ID to match records when two employees have the same name.","zh":"两名员工同名时，可用员工编号匹配记录。"}},{"id":"HRV6-M8-103","moduleId":"m8","module":"HR运营与数据分析","term":"Employee status","zh":"员工雇佣状态","definition":"人事系统记录的员工任职状态，例如在职、休假或雇佣已结束。具体分类和生效规则依系统配置而异。","example":"HR updated the employee status in the system to reflect the confirmed separation date.","collocation":"update employee status","dialogue":[{"role":"Payroll Coordinator","en":"Sam's still showing as active, but HR approved his leave yesterday.","zh":"系统里萨姆还是在职状态，但人力资源部门昨天已经批了他的休假。"},{"role":"HR Systems Analyst","en":"What's the effective date? The employee status will change when that date is reached in the system.","zh":"休假从哪天生效？系统到了生效日才会切换雇佣状态。"}],"usage":"","distinction":"Employee status 通常指在职、休假、离职等状态；employment type 通常指全职、兼职、固定期限等雇佣类别。有些系统会用相近字段名，需核对配置。","aliases":[],"new":true,"order":505,"collocationZh":"更新员工雇佣状态","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.iː ˈsteɪtəs","ipaUS":"ɪmˈplɔɪ.iː ˈstætəs","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employee status","exampleZh":"人力资源部门根据已确认的离职日期更新了系统中的雇佣状态。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What needs to be updated in HR operations?","zh":"HR 运营方面有哪些信息需要更新？"},"extension":{"en":"The report filters records by employee status as of the last day of the month.","zh":"报告按月末的员工雇佣状态筛选记录。"}},{"id":"HRV6-M8-104","moduleId":"m8","module":"HR运营与数据分析","term":"Payroll processing","zh":"薪资处理／工资核算与发放","definition":"按薪资周期收集和核对数据，计算工资、扣款和实发金额，并按流程安排支付和相关记录。","example":"Payroll processing for this pay cycle includes a review of overtime and deductions.","collocation":"complete payroll processing","dialogue":[{"role":"HR Coordinator","en":"A department sent us a corrected attendance file. Can it still go into this payroll run?","zh":"有个部门发来了更正后的考勤文件。还能赶上这期发薪吗？"},{"role":"Payroll Lead","en":"Payroll processing is still at the review stage. Send the approved file and I'll check what we can update.","zh":"本期薪资还在复核。把审批过的文件发给我，我看看哪些数据还能更新。"}],"usage":"","distinction":"Payroll processing 指日常薪资处理的全流程；payroll calculation 聚焦金额核算；payroll disbursement 指已核定工资的实际支付。","aliases":[],"new":true,"order":506,"collocationZh":"完成本期薪资处理","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈpeɪrəʊl ˈprəʊsesɪŋ","ipaUS":"ˈpeɪroʊl ˈprɑːsesɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Payroll processing","exampleZh":"本薪资周期的处理工作包括核对加班工资和扣款。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What needs to be updated in HR operations?","zh":"HR 运营方面有哪些信息需要更新？"},"extension":{"en":"During payroll processing, the team checks for unusual changes in net pay.","zh":"在处理薪资时，团队会检查实发金额是否有异常变动。"}},{"id":"HRV6-M8-105","moduleId":"m8","module":"HR运营与数据分析","term":"Payroll cutoff date","zh":"薪资数据提交截止日","definition":"在常规薪资流程中，为将变更、考勤或津贴等数据纳入当期核算而规定的最迟提交时间。","example":"Our payroll team reviews changes submitted after the payroll cutoff date to determine when they can be processed.","collocation":"meet the payroll cutoff date","dialogue":[{"role":"Team Lead","en":"I missed the payroll cutoff date for this overtime correction. What should I do?","zh":"这笔加班工资更正错过了薪资数据提交截止日，我该怎么办？"},{"role":"Payroll Coordinator","en":"Send me the approved correction now. I'll check whether we can make a separate payment and let you know the timing.","zh":"现在把核准过的更正发给我。我查一下能否单独支付，再告诉你处理时间。"}],"usage":"","distinction":"Payroll cutoff date 是本期薪资数据的提交截止日；pay date 是发薪日；end of the pay period 是计薪周期结束日。三者可由公司薪资日历分别设定。","aliases":[],"new":true,"order":507,"collocationZh":"在薪资数据提交截止前报送","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈpeɪrəʊl ˈkʌtɒf deɪt","ipaUS":"ˈpeɪroʊl ˈkʌtɔːf deɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Payroll cutoff date","exampleZh":"薪资团队会审核在数据提交截止后收到的变更，确定何时可以处理。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What needs to be updated in HR operations?","zh":"HR 运营方面有哪些信息需要更新？"},"extension":{"en":"The payroll cutoff date falls a day earlier this month because of the holiday.","zh":"由于假期，本月薪资数据提交截止日提前了一天。"}},{"id":"HRV6-M8-106","moduleId":"m8","module":"HR运营与数据分析","term":"Leave balance","zh":"剩余休假额度／假期余额","definition":"截至某个日期，员工某类假期的剩余额度。是否扣除已预约但尚未休的假期，取决于系统口径。","example":"Employees can check their leave balance in self-service.","collocation":"check your leave balance","dialogue":[{"role":"Employee","en":"My leave balance still shows six days. Does that already account for the Friday I booked?","zh":"我的假期余额还是显示六天。已经扣掉我约的周五了吗？"},{"role":"HR Coordinator","en":"It includes approved bookings. Your Friday request is still pending, so the balance hasn't changed yet.","zh":"系统会扣掉已批准的休假。你周五的申请还没批，所以余额还没变。"}],"usage":"","distinction":"Leave balance 是某一日期的剩余额度；leave accrual 是按规则累计的额度或累计过程；leave entitlement 指员工按规则享有的休假权利或额度。","aliases":[],"new":true,"order":508,"collocationZh":"查看剩余休假额度","collocationReview":"V18.2 模型编辑复核","ipaUK":"liːv ˈbæləns","ipaUS":"liːv ˈbæləns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Leave balance","exampleZh":"员工可在自助服务系统中查看剩余休假额度。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What needs to be updated in HR operations?","zh":"HR 运营方面有哪些信息需要更新？"},"extension":{"en":"Check your projected leave balance before booking time off for next quarter.","zh":"计划下季度休假前，先看一下届时预计还有多少假可休。"}},{"id":"HRV6-M8-107","moduleId":"m8","module":"HR运营与数据分析","term":"Leave accrual","zh":"休假额度累计","definition":"员工按服务时间、工作时数或适用规则逐步取得休假额度的过程。","example":"Annual leave accrual is calculated monthly under the policy.","collocation":"calculate leave accrual","dialogue":[{"role":"Employee","en":"I started halfway through the month. Why did I earn less leave than this chart shows?","zh":"我是月中入职的。为什么我累计的假期比这张图上显示的少？"},{"role":"HR Coordinator","en":"Under our policy, the first month's leave accrual is prorated based on your start date.","zh":"按公司政策，入职第一个月的假期额度会根据入职日期按比例累计。"}],"usage":"","distinction":"Leave accrual 侧重休假额度如何随时间或工时产生；leave balance 是扣减已休等项目后的剩余额度；leave carryover 则指未用额度按规则结转到下一期。","aliases":[],"new":true,"order":509,"collocationZh":"计算累计休假额度","collocationReview":"V18.2 模型编辑复核","ipaUK":"liːv əˈkruːəl","ipaUS":"liːv əˈkruːəl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Leave accrual","exampleZh":"根据政策，年假按月累计。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What needs to be updated in HR operations?","zh":"HR 运营方面有哪些信息需要更新？"},"extension":{"en":"The payroll team checked whether the change in scheduled hours affected leave accrual.","zh":"薪资团队核查了排班工时变更是否会影响休假额度的累计。"}},{"id":"HRV6-M8-108","moduleId":"m8","module":"HR运营与数据分析","term":"Unpaid leave","zh":"无薪假／不带薪休假","definition":"员工暂时休假且相应期间不领取正常工资的安排，可依政策获批或按当地规定享有。","example":"The employee requested two weeks of unpaid leave.","collocation":"apply for unpaid leave","dialogue":[{"role":"Employee","en":"I've used all my annual leave, but I need Friday off to help a family member move.","zh":"我的年假用完了，但周五想请假帮家人搬家。"},{"role":"Manager","en":"You can submit an unpaid leave request. I'll check whether we can cover your shift.","zh":"你可以提交无薪假申请。我看看能不能安排人顶班。"}],"usage":"","distinction":"Unpaid leave 说明休假期间不支付正常工资；leave of absence 指获准或按规定休假，可带薪也可无薪；unpaid absence 也可能指未经批准且不计薪的缺勤。","aliases":[],"new":true,"order":510,"collocationZh":"申请无薪假","collocationReview":"V18.2 模型编辑复核","ipaUK":"ʌnˈpeɪd liːv","ipaUS":"ənˈpeɪd liːv","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Unpaid leave","exampleZh":"该员工申请了两周无薪假。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What needs to be updated in HR operations?","zh":"HR 运营方面有哪些信息需要更新？"},"extension":{"en":"HR checked how the unpaid leave would affect the employee's benefit contributions.","zh":"人力资源部门核查了无薪假将如何影响该员工的福利缴费。"}},{"id":"HRV6-M8-109","moduleId":"m8","module":"HR运营与数据分析","term":"Offboarding checklist","zh":"离职流程清单／离职手续清单","definition":"用于分派和跟踪工作交接、资产归还、系统权限处理等离职任务的清单，通常由多个部门协作完成。","example":"The offboarding checklist includes system access removal.","collocation":"complete the offboarding checklist","dialogue":[{"role":"IT Coordinator","en":"Who is arranging the laptop return for the employee working remotely?","zh":"这位远程办公的员工由谁安排退还笔记本电脑？"},{"role":"HR Coordinator","en":"Facilities owns that task on the offboarding checklist. I'll ask them to send a prepaid shipping label.","zh":"离职清单上这一项由行政团队负责。我请他们发一个预付运费的寄件标签。"}],"usage":"","distinction":"Offboarding checklist 跟踪整个离职流程中各方要办的事项；exit clearance 更侧重核验或签核项目完成情况；handover checklist 通常聚焦工作、资料和联系人移交。","aliases":[],"new":true,"order":511,"collocationZh":"完成离职清单所列事项","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɒfˈbɔː.dɪŋ ˈtʃeklɪst","ipaUS":"ɔːfˈbɔːr.dɪŋ ˈtʃeklɪst","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Offboarding checklist","exampleZh":"离职清单包括取消系统访问权限。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What needs to be updated in HR operations?","zh":"HR 运营方面有哪些信息需要更新？"},"extension":{"en":"The offboarding checklist names an owner and due date for each task.","zh":"离职流程清单列明了每项任务的负责人和截止日期。"}},{"id":"HRV6-M8-110","moduleId":"m8","module":"HR运营与数据分析","term":"Headcount reconciliation","zh":"人员数量对账／在职人数与编制核对","definition":"核对 HR、薪资或财务系统中的人员数量和相关编制数据，按统一时点和口径解释并处理差异。","example":"We conduct headcount reconciliation before monthly reporting.","collocation":"perform headcount reconciliation","dialogue":[{"role":"Finance Analyst","en":"Our total is two lower than HR's. Did transfers post on different dates?","zh":"我们的人员总数比人力资源部门少两人。是不是调动在两个系统的入账日期不同？"},{"role":"HR Analyst","en":"I'll check the transfer dates and record any timing differences in the headcount reconciliation.","zh":"我会核对调动日期，在人数对账表里记录发现的时点差异。"}],"usage":"","distinction":"Headcount reconciliation 是对照来源解释人数差异；headcount reporting 是汇报某一口径下的人数；FTE reconciliation 核对按工时折算的全职当量，同一名兼职员工的计数与 FTE 可以不同。","aliases":[],"new":true,"order":512,"collocationZh":"开展人员数量对账","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈhedkaʊnt ˌrekənˌsɪlɪˈeɪʃən","ipaUS":"ˈhedkaʊnt ˌrekənˌsɪliːˈeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Headcount reconciliation","exampleZh":"我们在出具月报前核对人员数量。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What needs to be updated in HR operations?","zh":"HR 运营方面有哪些信息需要更新？"},"extension":{"en":"The headcount reconciliation uses the same reporting date for HR and Finance data.","zh":"人员数量对账对人力资源和财务数据采用同一报告日期。"}},{"id":"HRV6-M8-111","moduleId":"m8","module":"HR运营与数据分析","term":"Employment verification","zh":"雇佣信息核验／任职证明","definition":"按组织流程和适用规则，核实个人现任或过往雇佣关系、任职期间或岗位等信息。出具书面证明是常见方式之一。","example":"The bank requested employment verification with the employee's authorization.","collocation":"provide employment verification","dialogue":[{"role":"Former Employee","en":"My new employer wants to verify when I worked here. Where should they send the request?","zh":"我的新雇主想核实我之前在这里的任职时间。申请该发到哪里？"},{"role":"HR Coordinator","en":"We have an employment verification portal. I'll send you the link and tell you what information they'll need to submit.","zh":"我们有任职信息核验平台。我把链接发给你，再告诉你对方需要提交哪些信息。"}],"usage":"","distinction":"Employment verification 是核实雇佣事实的过程，可能涵盖已离职员工；employment verification letter 是书面任职证明；reference check 可进一步了解工作表现，处理范围应符合适用规则。","aliases":[],"new":true,"order":513,"collocationZh":"提供任职信息核验","collocationReview":"V18.2 模型编辑复核","ipaUK":"ɪmˈplɔɪ.mənt ˌverɪfɪˈkeɪʃən","ipaUS":"ɪmˈplɔɪ.mənt ˌverəfəˈkeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Employment verification","exampleZh":"银行在取得员工授权后提出了任职信息核验请求。","meaningReview":"HR场景校订","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What needs to be updated in HR operations?","zh":"HR 运营方面有哪些信息需要更新？"},"extension":{"en":"The employment verification request asked for the employee's dates of employment and job title.","zh":"任职信息核验请求要求提供该员工的任职起止日期和职务名称。"}},{"id":"HRV6-M8-112","moduleId":"m8","module":"HR运营与数据分析","term":"Personnel action","zh":"人事异动／人事变更","definition":"对员工人事记录作出的正式变更，例如调岗、晋升、调薪或离职。具体所用表单和审批流程因组织而异。","example":"HR submitted a personnel action for the employee's transfer.","collocation":"submit a personnel action","dialogue":[{"role":"HR Coordinator","en":"The personnel action for Lina's promotion is approved, but her record still shows the old job title.","zh":"莉娜的晋升流程已经获批，但她的记录里还是原来的职务名称。"},{"role":"HR Systems Analyst","en":"Let's check the effective date. The title may be set to change at the start of next month.","zh":"我们看看生效日期。系统可能设的是下个月初才更新职务名称。"}],"usage":"","distinction":"Personnel action 指正式人事变更或办理该变更的流程；personnel action form（PAF）是发起或记录变更的表单；disciplinary action 专指纪律处理。","aliases":[],"new":true,"order":514,"collocationZh":"提交人事异动申请","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌpɜːsəˈnel ˈækʃən","ipaUS":"ˌpɝːsəˈnel ˈækʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Personnel action","exampleZh":"人力资源部门已提交该员工的调岗申请。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What needs to be updated in HR operations?","zh":"HR 运营方面有哪些信息需要更新？"},"extension":{"en":"The personnel action takes effect at the start of the next pay period.","zh":"这项人事异动从下一个计薪周期开始时生效。"}},{"id":"HRV6-M8-113","moduleId":"m8","module":"HR运营与数据分析","term":"HR compliance audit","zh":"人力资源合规审计","definition":"对劳动用工、员工记录、权限或政策执行的合规性进行系统核查。","example":"The HR compliance audit identified gaps in record retention.","collocation":"conduct an HR compliance audit","dialogue":[{"role":"Auditor","en":"The spreadsheet says all the contracts were signed, but two files have no signatures.","zh":"表格显示所有合同都签了，但有两份档案里找不到签名。"},{"role":"HR Operations Lead","en":"Let's check the original files before we log that as a finding in the HR compliance audit.","zh":"先查一下原始档案，再决定是否把这一项记为人力资源合规审计的发现。"}],"usage":"","distinction":"HR compliance audit 用明确的法律、政策或控制标准核查用工流程和记录；HR process review 可侧重效率与体验；labor inspection 通常指主管机关依职权开展的检查。","aliases":[],"new":true,"order":515,"collocationZh":"开展人力资源合规审计","collocationReview":"V18.2 模型编辑复核","ipaUK":"eɪtʃ ɑː kəmˈplaɪəns ˈɔːdɪt","ipaUS":"eɪtʃ ɑːr kəmˈplaɪəns ˈɔːdɪt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"H R compliance audit","exampleZh":"人力资源合规审计发现档案留存方面存在不足。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What needs to be updated in HR operations?","zh":"HR 运营方面有哪些信息需要更新？"},"extension":{"en":"The HR compliance audit sampled files from several sites to test how the policy was applied.","zh":"人力资源合规审计从多个站点抽取档案，核查政策的执行情况。"}},{"id":"HRV6-M9-101","moduleId":"m9","module":"海外派遣与全球流动","term":"Assignee","zh":"国际派遣员工／外派员工","definition":"在全球流动语境中，指按派遣安排到另一国家或地区工作一定期间的员工。","example":"The assignee will relocate to Singapore next month.","collocation":"support an assignee","dialogue":[{"role":"Host Manager","en":"Who should the assignee call if their temporary housing isn't ready on arrival?","zh":"外派员工抵达时，如果临时住房还没准备好，该找谁？"},{"role":"Mobility Coordinator","en":"Have them call me. I'll check in with the housing provider the day before they fly.","zh":"让他们打电话给我。我会在他们起飞前一天跟住房服务商确认。"}],"usage":"","distinction":"Assignee 在全球流动中指承担派遣任务的员工；expatriate 更宽泛，指在本国以外居住或工作的人；在合同法律语境中，assignee 还可指权利受让人。","aliases":[],"new":true,"order":516,"collocationZh":"为国际派遣员工提供支持","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌæs.aɪˈniː","ipaUS":"əˌsaɪˈniː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Assignee","exampleZh":"这位外派员工下个月将搬到新加坡。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we check for this international assignment?","zh":"这次国际派遣需要核查哪些事项？"},"extension":{"en":"Each assignee receives a briefing on local workplace practices before departure.","zh":"每位外派员工出发前都会听取一场关于派驻地工作惯例的说明。"}},{"id":"HRV6-M9-102","moduleId":"m9","module":"海外派遣与全球流动","term":"Secondment","zh":"借调／临时派驻","definition":"员工暂时到另一团队、关联实体或外部组织工作的一种安排，通常保留与原单位的雇佣关系，具体职责和安排由适用规则及协议确定。","example":"The secondment agreement defines the employee's reporting line.","collocation":"secondment agreement","dialogue":[{"role":"Employee","en":"During the secondment, who should approve my leave: my current manager or the host team?","zh":"借调期间，我休假该找现在的经理批，还是找接收团队批？"},{"role":"HR Adviser","en":"The host manager approves leave under this agreement. Let's update the system before the secondment starts.","zh":"按这份协议，由接收方经理审批休假。我们在借调开始前把系统设置更新一下。"}],"usage":"","distinction":"Secondment 侧重暂时借调至另一团队或单位，通常保留与原单位的雇佣关系；permanent transfer 侧重长期转岗或调动；international assignment 强调跨境工作，也可以采用借调形式。","aliases":[],"new":true,"order":517,"collocationZh":"借调协议","collocationReview":"V18.2 模型编辑复核","ipaUK":"sɪˈkɒnd.mənt","ipaUS":"səˈkɑːnd.mənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Secondment","exampleZh":"借调协议规定了该员工的汇报关系。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we check for this international assignment?","zh":"这次国际派遣需要核查哪些事项？"},"extension":{"en":"The secondment gives the employee six months of experience in the regional office.","zh":"这次借调让该员工有机会在区域办公室工作六个月。"}},{"id":"HRV6-M9-103","moduleId":"m9","module":"海外派遣与全球流动","term":"Short-term assignment","zh":"短期国际派遣","definition":"按组织全球流动政策归为期限较短的跨境派遣，常见为数周或数月。时长门槛及移民、税务义务需分别按相关规则判断。","example":"For this short-term assignment, the mobility team confirmed that a work permit was required.","collocation":"arrange a short-term assignment","dialogue":[{"role":"Project Lead","en":"We need an engineer on site for eight weeks to help install the equipment. Should I put this through as a business trip?","zh":"我们需要一名工程师到现场协助安装设备，时间是八周。按商务出差申请可以吗？"},{"role":"Mobility Partner","en":"Let's review the planned work and location. It may need to go through our short-term assignment process.","zh":"我们先看看具体工作内容和地点。这可能需要走公司的短期国际派遣流程。"}],"usage":"","distinction":"Short-term assignment 侧重有限期限内在境外承担工作；business trip 通常指访问、开会等出差安排。能否从事具体活动及所需手续，应按目的地规定和实际工作判断。","aliases":[],"new":true,"order":518,"collocationZh":"安排短期国际派遣","collocationReview":"V18.2 模型编辑复核","ipaUK":"ʃɔːt tɜːm əˈsaɪnmənt","ipaUS":"ʃɔːrt tɝːm əˈsaɪnmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Short-term assignment","exampleZh":"全球流动团队已确认，这次短期国际派遣需要工作许可。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we check for this international assignment?","zh":"这次国际派遣需要核查哪些事项？"},"extension":{"en":"The short-term assignment was extended by two weeks after a review of the local requirements.","zh":"核查当地要求后，这次短期国际派遣延长了两周。"}},{"id":"HRV6-M9-104","moduleId":"m9","module":"海外派遣与全球流动","term":"Long-term assignment","zh":"长期国际派遣","definition":"按组织全球流动政策划分的较长时间跨境派遣，通常有预计结束日期，期限门槛和福利以具体政策为准。","example":"The long-term assignment package includes housing support.","collocation":"approve a long-term assignment","dialogue":[{"role":"Assignee","en":"The long-term assignment is for two years. What happens to my role at home while I'm away?","zh":"这次长期外派为期两年。我外派期间，原来的岗位怎么安排？"},{"role":"Mobility Partner","en":"Your home team plans to fill it temporarily. Let's check what your assignment letter says about the return process.","zh":"原团队打算暂时找人顶岗。我们一起看看派遣函里关于回任流程的约定。"}],"usage":"","distinction":"Long-term assignment 是通常设有期限的长期外派；permanent international transfer 通常表示长期转入目的地岗位而无预定回任安排。不能仅凭派遣时长推断雇佣主体或福利。","aliases":[],"new":true,"order":519,"collocationZh":"批准长期国际派遣","collocationReview":"V18.2 模型编辑复核","ipaUK":"lɒŋ tɜːm əˈsaɪnmənt","ipaUS":"lɔːŋ tɝːm əˈsaɪnmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Long-term assignment","exampleZh":"这份长期国际派遣的待遇方案包含住房支持。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we check for this international assignment?","zh":"这次国际派遣需要核查哪些事项？"},"extension":{"en":"The long-term assignment letter sets out the expected end date and the review schedule.","zh":"长期国际派遣函列明预计结束日期和定期复核安排。"}},{"id":"HRV6-M9-105","moduleId":"m9","module":"海外派遣与全球流动","term":"International transfer","zh":"跨国岗位调动","definition":"员工正式从一国的岗位或工作地点调动到另一国的安排，可能伴随雇佣主体或合同条件变更。","example":"HR reviewed the employment terms for the international transfer.","collocation":"manage an international transfer","dialogue":[{"role":"Employee","en":"I'm moving from Toronto to Berlin for the new role. Will I still be employed by the Canadian entity?","zh":"我会从多伦多调到柏林担任新职。我还是由加拿大这边的公司雇用吗？"},{"role":"Mobility Partner","en":"This international transfer is set up as a local hire in Germany. Let's go through the proposed contract before you sign.","zh":"这次跨国调动安排由德国当地实体聘用。签字前我们一起过一遍拟议的合同。"}],"usage":"","distinction":"International transfer 侧重岗位或主要工作地点由一国转到另一国；international assignment 通常强调一定期限的外派；relocation 侧重实际搬迁，可以伴随两种安排。","aliases":[],"new":true,"order":520,"collocationZh":"办理跨国岗位调动","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɪntəˈnæʃənəl ˈtræns.fɜː","ipaUS":"ˌɪntɚˈnæʃənəl ˈtræns.fɝː","ipaSource":"音素词典与英式语音规则推导","speakTerm":"International transfer","exampleZh":"人力资源部门审查了该员工跨国调动的雇佣条款。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we check for this international assignment?","zh":"这次国际派遣需要核查哪些事项？"},"extension":{"en":"The international transfer moved the employee to a new team and a different payroll entity.","zh":"这次跨国调动将该员工转入新的团队，也更换了发薪主体。"}},{"id":"HRV6-M9-106","moduleId":"m9","module":"海外派遣与全球流动","term":"Host-country payroll","zh":"派驻国薪资处理","definition":"针对外派员工在派驻国办理的薪资记录、计算、预扣或申报等流程。是否实际由当地发薪取决于具体安排。","example":"The host-country payroll team will confirm local tax withholding.","collocation":"process host-country payroll","dialogue":[{"role":"Assignee","en":"My salary still comes from my home office. Why does the host-country payroll team need a copy of my payslip?","zh":"我的工资还是由派出地办公室发。派驻国薪资团队为什么也要工资单？"},{"role":"Payroll Adviser","en":"They need to check what earnings to include in the local payroll reporting for your assignment.","zh":"他们要核对你的哪些收入应计入这次派遣的当地薪资申报。"}],"usage":"","distinction":"Host-country payroll 指在派驻国处理的薪资；home-country payroll 指由派出国处理的薪资；shadow payroll 可在派驻国记录应税收入及办理某些申报或预扣，即使员工仍主要从派出国收款。","aliases":[],"new":true,"order":521,"collocationZh":"办理派驻国薪资处理","collocationReview":"V18.2 模型编辑复核","ipaUK":"həʊst ˈkʌntri ˈpeɪrəʊl","ipaUS":"hoʊst ˈkʌntriː ˈpeɪroʊl","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Host-country payroll","exampleZh":"派驻国薪资团队将核实当地的税款预扣安排。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we check for this international assignment?","zh":"这次国际派遣需要核查哪些事项？"},"extension":{"en":"The host-country payroll team needs the taxable value of the housing allowance.","zh":"派驻国薪资团队需要知道住房津贴的应税金额。"}},{"id":"HRV6-M9-107","moduleId":"m9","module":"海外派遣与全球流动","term":"Home leave","zh":"外派探亲假／返乡休假","definition":"部分外派政策或合同约定的返回派出地或指定地点休假安排，可包含符合条件的旅费福利。","example":"Under the assignment policy, the assignee is eligible for one home leave trip each year.","collocation":"home leave entitlement","dialogue":[{"role":"Assignee","en":"Could I take my home leave in July, when my children's school is on break?","zh":"我能在七月孩子放暑假时休外派探亲假吗？"},{"role":"Mobility Coordinator","en":"Check the dates with your manager, then send them to me so I can confirm how to book the flights under our policy.","zh":"先和经理确认日期，再把日期发给我，我来核实按公司政策该怎么订机票。"}],"usage":"","distinction":"Home leave 是外派期间返回派出地或约定地点的休假安排；annual leave 指一般年假；home leave travel allowance 专指相关差旅补贴。假期与旅费是否合并以具体政策为准。","aliases":[],"new":true,"order":522,"collocationZh":"外派探亲假待遇","collocationReview":"V18.2 模型编辑复核","ipaUK":"həʊm liːv","ipaUS":"hoʊm liːv","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Home leave","exampleZh":"按外派政策，这位外派员工每年可享受一次返乡探亲安排。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we check for this international assignment?","zh":"这次国际派遣需要核查哪些事项？"},"extension":{"en":"The policy explains whether eligible family members can travel on a home leave trip.","zh":"外派政策说明了符合条件的家属能否随行返乡探亲。"}},{"id":"HRV6-M9-108","moduleId":"m9","module":"海外派遣与全球流动","term":"Dependent visa","zh":"随行家属签证／家属陪同签证","definition":"供符合条件的主申请人家属陪同或团聚的签证类别。当地也可能采用居留许可等形式，资格和附带权利依目的地及类别而异。","example":"The mobility team will assist with the dependent visa application.","collocation":"apply for a dependent visa","dialogue":[{"role":"Assignee","en":"If my partner gets a dependent visa, can they start working right away?","zh":"我的伴侣如果拿到随行家属签证，可以马上开始工作吗？"},{"role":"Mobility Adviser","en":"That depends on the visa category and local rules. I'll confirm what applies to your partner's application.","zh":"这要看签证类别和当地规定。我会核实哪些规则适用于你伴侣的申请。"}],"usage":"","distinction":"Dependent visa 以与主申请人的家属关系为基础；visitor visa 一般对应短期访问；work authorization 指能否工作。家属签证本身是否允许工作，须核对目的地和具体类别。","aliases":[],"new":true,"order":523,"collocationZh":"申请随行家属签证","collocationReview":"V18.2 模型编辑复核","ipaUK":"dɪˈpendənt ˈviːzə","ipaUS":"dɪˈpendənt ˈviːzə","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Dependent visa","exampleZh":"全球流动团队将协助准备随行家属签证申请。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we check for this international assignment?","zh":"这次国际派遣需要核查哪些事项？"},"extension":{"en":"Check whether the dependent visa application requires official translations of family documents.","zh":"请核对随行家属签证申请是否要求提交家庭关系文件的正式译本。"}},{"id":"HRV6-M9-109","moduleId":"m9","module":"海外派遣与全球流动","term":"Immigration sponsorship","zh":"雇主移民担保／雇主签证担保","definition":"雇主在适用的移民类别下，以担保方身份为员工的工作签证、移民或工作许可申请提交材料或履行相应义务。","example":"The host entity confirmed that it could provide immigration sponsorship for the role.","collocation":"provide immigration sponsorship","dialogue":[{"role":"Candidate","en":"The posting mentions immigration sponsorship. Is it available for this particular role?","zh":"招聘公告提到了雇主移民担保。这个岗位也可以提供吗？"},{"role":"Recruiter","en":"The hiring entity is willing to sponsor this role. Our immigration adviser still needs to review which route, if any, applies in your case.","zh":"招聘实体愿意为这个岗位提供担保。移民顾问还需要评估有没有适合你的申请路径。"}],"usage":"","distinction":"Immigration sponsorship 指雇主在有关移民路径中承担正式的担保角色；visa assistance 可以仅指协助准备材料；visa approval 由有权机关作出，提供担保并不等于申请获批。","aliases":[],"new":true,"order":524,"collocationZh":"由雇主提供移民担保","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɪmɪˈɡreɪʃən ˈspɒnsəˌʃɪp","ipaUS":"ˌɪməˈɡreɪʃən ˈspɑːnsɚˌʃɪp","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Immigration sponsorship","exampleZh":"接收实体确认可为该岗位提供雇主移民担保。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we check for this international assignment?","zh":"这次国际派遣需要核查哪些事项？"},"extension":{"en":"The recruiter confirmed which legal entity would provide immigration sponsorship.","zh":"招聘专员确认了将由哪个法人实体提供雇主移民担保。"}},{"id":"HRV6-M9-110","moduleId":"m9","module":"海外派遣与全球流动","term":"Relocation reimbursement","zh":"搬迁费用报销","definition":"员工因工作地点变更而支出费用后，按已有协议或组织政策核销符合条件的搬家、交通等费用。","example":"Under our relocation policy, employees need prior approval and receipts to claim relocation reimbursement.","collocation":"claim relocation reimbursement","dialogue":[{"role":"Employee","en":"The movers charged me for two nights of storage. Can I add that to my relocation reimbursement claim?","zh":"搬家公司收了两晚的仓储费。这笔能一起申请搬迁费用报销吗？"},{"role":"Mobility Coordinator","en":"Send me the invoice and your approval email. I'll check whether temporary storage was covered.","zh":"把发票和审批邮件发给我，我来确认临时仓储在不在报销范围内。"}],"usage":"","distinction":"Relocation reimbursement 通常根据实际合规支出和凭证报销；relocation allowance 通常指预设的搬迁补贴；direct billing 是由公司直接向服务商结算。","aliases":[],"new":true,"order":525,"collocationZh":"申请搬迁费用报销","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌriː.ləʊˈkeɪ.ʃən ˌriː.ɪmˈbɜːs.mənt","ipaUS":"ˌriː.loʊˈkeɪ.ʃən ˌriː.ɪmˈbɝːs.mənt","ipaSource":"https://dictionary.cambridge.org/dictionary/english/relocation | https://dictionary.cambridge.org/dictionary/english/reimbursement","speakTerm":"Relocation reimbursement","exampleZh":"按公司搬迁政策，员工须事先获批并提供收据，才能申请搬迁费用报销。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we check for this international assignment?","zh":"这次国际派遣需要核查哪些事项？"},"extension":{"en":"Keep the moving company's itemized invoice for your relocation reimbursement claim.","zh":"请保留搬家公司的明细发票，申请搬迁费用报销时会用到。"}},{"id":"HRV6-M9-111","moduleId":"m9","module":"海外派遣与全球流动","term":"Cross-border tax compliance","zh":"跨境税务合规（全球流动语境）","definition":"在跨境派遣、出差等安排中，识别并履行相关法域的税务义务，可涉及个人所得税申报和雇主预扣、申报等义务。","example":"Our mobility policy calls for a cross-border tax compliance review before an assignment begins.","collocation":"review cross-border tax compliance","dialogue":[{"role":"Project Lead","en":"The engineer spent only a few weeks abroad, but she made three trips this year. Does the tax review need all the dates?","zh":"工程师在国外只待了几周，但今年去了三次。税务审查需要每一趟的日期吗？"},{"role":"Mobility Tax Adviser","en":"Yes, please send all the travel dates and work locations. We'll use them to assess cross-border tax compliance for the trips.","zh":"需要。请把所有出行日期和工作地点发给我。我们会据此评估这几趟出差的跨境税务合规情况。"}],"usage":"","distinction":"Cross-border tax compliance 关注在相关法域履行税务义务；tax equalization 是由公司政策约定的外派税负平衡安排；immigration compliance 则处理入境、居留和工作许可等要求。","aliases":[],"new":true,"order":526,"collocationZh":"审查跨境税务合规情况","collocationReview":"V18.2 模型编辑复核","ipaUK":"krɒs ˈbɔːdə tæks kəmˈplaɪəns","ipaUS":"krɔːs ˈbɔːrdɚ tæks kəmˈplaɪəns","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Cross-border tax compliance","exampleZh":"公司全球流动政策要求在派遣开始前进行跨境税务合规审查。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we check for this international assignment?","zh":"这次国际派遣需要核查哪些事项？"},"extension":{"en":"The cross-border tax compliance review considered where the employee actually performed the work.","zh":"跨境税务合规审查考虑了员工实际在哪些地点工作。"}},{"id":"HRV6-M9-112","moduleId":"m9","module":"海外派遣与全球流动","term":"Tax gross-up","zh":"税款补足／税前金额加算","definition":"在约定的薪酬或津贴基础上增加税前金额，以覆盖纳入计算的税费，让税后金额达到约定目标。适用项目、税费和计算口径以具体安排为准。","example":"The assignment package includes a tax gross-up for certain allowances.","collocation":"calculate a tax gross-up","dialogue":[{"role":"Assignee","en":"The housing allowance on my payslip is higher than the amount in my assignment letter. Is that a mistake?","zh":"工资单上的住房津贴比派遣函里写的金额高。是不是弄错了？"},{"role":"Payroll Adviser","en":"The difference is the tax gross-up for that allowance. I can show you the allowance and the gross-up on the calculation sheet.","zh":"差额是这笔津贴的税款补足。我可以在计算表上指给你看津贴和补足金额各是多少。"}],"usage":"","distinction":"Tax gross-up 通过加算税前款项覆盖约定税费，通常也考虑加算金额本身的税负；tax reimbursement 侧重报销约定的已支付税款；tax equalization 依政策平衡外派前后税负。","aliases":[],"new":true,"order":527,"collocationZh":"计算税款补足金额","collocationReview":"V18.2 模型编辑复核","ipaUK":"tæks ɡrəʊs ʌp","ipaUS":"tæks ɡroʊs ʌp","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Tax gross-up","exampleZh":"外派方案对部分津贴提供税款补足安排。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we check for this international assignment?","zh":"这次国际派遣需要核查哪些事项？"},"extension":{"en":"The payroll team documented which tax rates it used for the gross-up.","zh":"薪资团队记录了计算税款补足金额时使用的税率。"}},{"id":"HRV6-M9-113","moduleId":"m9","module":"海外派遣与全球流动","term":"Repatriation support","zh":"外派回任支持","definition":"员工结束海外派遣返回派出地前后获得的支持，可涉及返程搬迁、岗位衔接和重新融入。","example":"Our repatriation support starts before the assignment ends.","collocation":"plan repatriation support","dialogue":[{"role":"Assignee","en":"I know when I'm flying home, but I don't know which team I'll join when I get back.","zh":"我知道哪天飞回去，但还不知道回去后会加入哪个团队。"},{"role":"Mobility Partner","en":"Let's cover that in your repatriation support meeting. I'll invite your home-country HR partner so we can discuss roles that may be available.","zh":"我们在回任支持会上谈这个。我会请派出地的人力资源伙伴参加，一起看看有哪些岗位可选。"}],"usage":"","distinction":"Repatriation support 侧重外派结束后返回派出地并重新融入；relocation support 侧重搬迁本身；home leave 指派遣仍在进行期间的短期返乡休假。","aliases":[],"new":true,"order":528,"collocationZh":"规划外派回任支持","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˌpætrɪˈeɪʃən səˈpɔːt","ipaUS":"riːˌpeɪtriːˈeɪʃən səˈpɔːrt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Repatriation support","exampleZh":"我们的外派回任支持在派遣结束前就会启动。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"What should we check for this international assignment?","zh":"这次国际派遣需要核查哪些事项？"},"extension":{"en":"Repatriation support may include help transferring school records before the family moves back.","zh":"外派回任支持可包括协助家人在搬回前转交子女的学籍资料。"}},{"id":"HRV6-M10-101","moduleId":"m10","module":"HR商务沟通与汇报","term":"Policy briefing","zh":"人力资源政策宣讲／说明会","definition":"向特定受众介绍政策内容、变更、实施安排或注意事项的简报或说明活动。","example":"HR will hold a policy briefing for line managers.","collocation":"deliver a policy briefing","dialogue":[{"role":"Line Manager","en":"People are asking whether the new remote-work rules apply to arrangements we've already approved.","zh":"大家都在问，之前已经批准的远程办公安排是否适用新规定。"},{"role":"HR Partner","en":"I'll add that to the policy briefing and bring two examples for managers to work through.","zh":"我把这个问题加进政策说明会，带两个例子让经理们一起看看怎么处理。"}],"usage":"","distinction":"Policy briefing 负责解释政策及其实施影响；policy document 是政策正文；policy announcement 侧重告知发布或变更，通常可以比说明会更简短。","aliases":[],"new":true,"order":529,"collocationZh":"开展人力资源政策宣讲","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈpɒlɪsi ˈbriːfɪŋ","ipaUS":"ˈpɑːləsiː ˈbriːfɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Policy briefing","exampleZh":"人力资源部门将为直线经理举办政策说明会。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we communicate the next step to stakeholders?","zh":"我们应如何向相关方沟通下一步安排？"},"extension":{"en":"The policy briefing covered how existing requests would be handled after the change.","zh":"政策说明会讲解了政策变更后如何处理此前已提交的申请。"}},{"id":"HRV6-M10-102","moduleId":"m10","module":"HR商务沟通与汇报","term":"Business justification","zh":"业务必要性说明／业务理由","definition":"在招聘、预算或项目审批中，说明提议对应的业务需求、预期价值或不采取行动的影响。","example":"The headcount request must include a clear business justification.","collocation":"provide a business justification","dialogue":[{"role":"Finance Partner","en":"I can see the cost of another analyst. Which problem would the hire solve?","zh":"我看得到再招一名分析师要花多少钱。这次招聘能解决什么问题？"},{"role":"Hiring Manager","en":"I'll revise the business justification to show how much client reporting we're delaying and what capacity the new analyst would add.","zh":"我会修改业务必要性说明，写清有多少客户报告延期，以及新分析师能增加多少处理能力。"}],"usage":"","distinction":"Business justification 直接说明为什么有业务必要性；business case 往往还比较方案、成本、收益和风险；supporting evidence 是支撑论证的数据或实例。","aliases":[],"new":true,"order":530,"collocationZh":"提供业务必要性说明","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈbɪznəs ˌdʒʌstɪfɪˈkeɪʃən","ipaUS":"ˈbɪznəs ˌdʒʌstəfəˈkeɪʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Business justification","exampleZh":"人员编制申请必须包含清晰的业务必要性说明。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we communicate the next step to stakeholders?","zh":"我们应如何向相关方沟通下一步安排？"},"extension":{"en":"The business justification cites the growth in weekend orders and the current staffing gap.","zh":"业务必要性说明引用了周末订单增长和当前人手不足的数据。"}},{"id":"HRV6-M10-103","moduleId":"m10","module":"HR商务沟通与汇报","term":"Budget sign-off","zh":"预算正式审批／预算签批","definition":"具备相应权限的人或机构对预算作出正式批准，可通过审批系统、书面签批等方式记录。","example":"Our team can launch the program once it has budget sign-off.","collocation":"obtain budget sign-off","dialogue":[{"role":"Project Lead","en":"Finance said the numbers look good. Can I confirm the booking with the vendor?","zh":"财务说金额没问题。我可以跟供应商确认预订了吗？"},{"role":"Finance Partner","en":"The review is done, but budget sign-off is still with the budget owner. I'll let you know when it's recorded.","zh":"审核完了，但预算还在负责人那里等签批。审批一登记，我就通知你。"}],"usage":"","distinction":"Budget sign-off 强调有权人员对预算作出正式批准；budget review 是审核预算，可发生在批准之前；spending approval 可能另针对具体开支。","aliases":[],"new":true,"order":531,"collocationZh":"取得预算正式批准","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈbʌdʒɪt saɪn ɒf","ipaUS":"ˈbʌdʒɪt saɪn ɔːf","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Budget sign-off","exampleZh":"预算正式获批后，我们团队就可以启动这个项目。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we communicate the next step to stakeholders?","zh":"我们应如何向相关方沟通下一步安排？"},"extension":{"en":"Budget sign-off covered the pilot only, so the broader rollout will need its own approval.","zh":"此次预算只批准了试点费用，扩大实施范围还需单独审批。"}},{"id":"HRV6-M10-104","moduleId":"m10","module":"HR商务沟通与汇报","term":"Approval matrix","zh":"审批权限矩阵","definition":"按事项、金额或岗位明确各级审核与批准权限的管理表。","example":"The approval matrix identifies who signs off on each request.","collocation":"update the approval matrix","dialogue":[{"role":"HR Coordinator","en":"The vendor quote is above the department head's limit. Who should I route it to?","zh":"供应商报价超过了部门负责人的审批额度。我该转给谁？"},{"role":"Procurement Partner","en":"Use the approval matrix for consulting spend. At that amount, it goes to the finance director.","zh":"查一下审批权限矩阵里咨询支出的那一项。这个金额要送财务总监审批。"}],"usage":"","distinction":"Approval matrix 说明不同类型或金额的事项由谁审批；approval workflow 说明申请如何在各环节流转；RACI matrix 还可列出负责执行、协商和知会等角色。","aliases":[],"new":true,"order":532,"collocationZh":"更新审批权限矩阵","collocationReview":"V18.2 模型编辑复核","ipaUK":"əˈpruːvəl ˈmeɪtrɪks","ipaUS":"əˈpruːvəl ˈmeɪtrɪks","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Approval matrix","exampleZh":"审批权限矩阵明确了每类申请由谁正式批准。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we communicate the next step to stakeholders?","zh":"我们应如何向相关方沟通下一步安排？"},"extension":{"en":"The approval matrix sets different thresholds for software purchases and consulting fees.","zh":"审批权限矩阵对软件采购和咨询费用规定了不同的审批金额门槛。"}},{"id":"HRV6-M10-105","moduleId":"m10","module":"HR商务沟通与汇报","term":"Leadership briefing","zh":"管理层简报／面向管理层的情况说明","definition":"面向管理层集中呈现进展、风险和待决事项的简短材料或说明会。","example":"The CHRO prepared a leadership briefing on workforce risks.","collocation":"prepare a leadership briefing","dialogue":[{"role":"HR Analyst","en":"I've put all twelve site dashboards in the deck. Is that too much for a ten-minute leadership briefing?","zh":"我把 12 个站点的看板都放进幻灯片了。管理层简报只有十分钟，是不是太多了？"},{"role":"HR Director","en":"Focus on the three sites with issues in the main deck. Put all twelve dashboards in the appendix in case anyone asks for details.","zh":"主体内容重点讲三个有问题的站点。把 12 个站点的看板都放到附录，有人问细节时再看。"}],"usage":"","distinction":"在 HR 汇报语境中，leadership briefing 通常指面向管理层的简报，既可指材料也可指说明会；status report 侧重报告进度；decision memo 则通常详细说明一个待决事项及其选项。","aliases":[],"new":true,"order":533,"collocationZh":"准备管理层简报","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈliːdəˌʃɪp ˈbriːfɪŋ","ipaUS":"ˈliːdɚˌʃɪp ˈbriːfɪŋ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Leadership briefing","exampleZh":"首席人力资源官准备了一份关于用工风险的管理层简报。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we communicate the next step to stakeholders?","zh":"我们应如何向相关方沟通下一步安排？"},"extension":{"en":"The leadership briefing opens with the two decisions executives need to make this week.","zh":"管理层简报首先列出高管本周需要作出的两项决定。"}},{"id":"HRV6-M10-106","moduleId":"m10","module":"HR商务沟通与汇报","term":"Implementation timeline","zh":"实施时间表","definition":"按时间列出政策或项目实施的主要阶段、任务及关键节点的安排。","example":"The implementation timeline includes a two-week pilot.","collocation":"confirm the implementation timeline","dialogue":[{"role":"Project Manager","en":"IT can't finish the access changes until the 18th. Can training still start on the 15th?","zh":"IT 要到 18 日才能改完权限。培训还能在 15 日开始吗？"},{"role":"L&D Lead","en":"We can do a walkthrough on the 15th and move hands-on practice after the access change. I'll update the implementation timeline.","zh":"15 日可以先演示，把实操挪到权限改完之后。我来更新实施时间表。"}],"usage":"","distinction":"Implementation timeline 聚焦实施各阶段何时发生；implementation plan 还涉及责任、资源及风险等；milestone 是时间表中的一个关键节点。","aliases":[],"new":true,"order":534,"collocationZh":"确认实施时间表","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˌɪmplɪmənˈteɪʃən ˈtaɪmlaɪn","ipaUS":"ˌɪmpləmenˈteɪʃən ˈtaɪmlaɪn","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Implementation timeline","exampleZh":"实施时间表包括为期两周的试点。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we communicate the next step to stakeholders?","zh":"我们应如何向相关方沟通下一步安排？"},"extension":{"en":"The implementation timeline allows a week to review comments before the next phase.","zh":"实施时间表留出一周，用于在下一阶段开始前审阅意见。"}},{"id":"HRV6-M10-107","moduleId":"m10","module":"HR商务沟通与汇报","term":"Meeting agenda","zh":"会议议程","definition":"会前准备的议题和讨论顺序，可列出预期成果、各议题负责人和计划用时。","example":"Please circulate the meeting agenda before the HR review.","collocation":"share the meeting agenda","dialogue":[{"role":"Facilitator","en":"There's a lot to cover. Which item needs a decision today?","zh":"要谈的内容不少。哪一项今天必须定下来？"},{"role":"HR Project Lead","en":"The pilot location. Could you move it to the top of the meeting agenda?","zh":"试点地点。能把这一项放到会议议程的第一位吗？"}],"usage":"","distinction":"Meeting agenda 是会前拟定的讨论安排；meeting minutes 是会后对讨论、决定和行动项的记录；calendar invite 是邀请通知，可附议程。","aliases":[],"new":true,"order":535,"collocationZh":"发送会议议程","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈmiːtɪŋ əˈdʒendə","ipaUS":"ˈmiːtɪŋ əˈdʒendə","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Meeting agenda","exampleZh":"请在人力资源评审会前分发会议议程。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we communicate the next step to stakeholders?","zh":"我们应如何向相关方沟通下一步安排？"},"extension":{"en":"The meeting agenda reserves the final ten minutes for decisions and next steps.","zh":"会议议程留出最后十分钟，用于确认决定和后续行动。"}},{"id":"HRV6-M10-108","moduleId":"m10","module":"HR商务沟通与汇报","term":"Decision memo","zh":"决策备忘录／决策建议书","definition":"供决策人审议的简短文件，通常说明待决事项、备选方案、取舍和建议，也可用于记录决定及理由。","example":"The decision memo summarizes the proposed policy changes.","collocation":"draft a decision memo","dialogue":[{"role":"HR Director","en":"The decision memo recommends Option B. What happens if we keep the current process for another quarter?","zh":"决策备忘录建议选方案 B。如果再沿用一个季度的现有流程，会怎么样？"},{"role":"Project Lead","en":"I'll add that as an option and show its likely effect on workload and cost.","zh":"我把这个也列为一个选项，说明它可能对工作量和成本产生什么影响。"}],"usage":"","distinction":"Decision memo 围绕一个具体决定，可供决策前审议或记录决定和理由；briefing note 主要提供背景；decision log 则集中记录多个已作出的决定。","aliases":[],"new":true,"order":536,"collocationZh":"起草决策备忘录","collocationReview":"V18.2 模型编辑复核","ipaUK":"dɪˈsɪʒən ˈmeməʊ","ipaUS":"dɪˈsɪʒən ˈmemoʊ","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Decision memo","exampleZh":"决策备忘录汇总了拟议的政策变更。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we communicate the next step to stakeholders?","zh":"我们应如何向相关方沟通下一步安排？"},"extension":{"en":"The decision memo explains why the team recommends a phased rollout.","zh":"决策备忘录说明了团队为什么建议分阶段实施。"}},{"id":"HRV6-M10-109","moduleId":"m10","module":"HR商务沟通与汇报","term":"Stakeholder engagement","zh":"相关方沟通与参与","definition":"持续识别并与受项目或政策影响、或能影响实施的各方沟通，让其提供意见或参与推进。","example":"Our global policy rollout plan includes stakeholder engagement in each region.","collocation":"strengthen stakeholder engagement","dialogue":[{"role":"Project Lead","en":"The site managers have seen the draft. Who else should be involved before we decide?","zh":"站点经理已经看过草案了。作决定前，还应该让谁参与？"},{"role":"HR Partner","en":"Add shift leads and employee representatives to the stakeholder engagement plan. They can tell us how the change would work on the floor.","zh":"把班组长和员工代表也纳入相关方参与计划。他们知道这项调整在现场怎么落地。"}],"usage":"","distinction":"Stakeholder engagement 强调让相关方持续沟通并参与；stakeholder communication 可以只是传递信息；stakeholder consultation 通常指针对特定事项征求意见的环节。","aliases":[],"new":true,"order":537,"collocationZh":"加强相关方沟通与参与","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈsteɪkhəʊldə enˈɡeɪdʒmənt","ipaUS":"ˈsteɪkˌhoʊldɚ enˈɡeɪdʒmənt","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Stakeholder engagement","exampleZh":"按全球政策实施计划，我们会在各地区与相关方沟通，请他们参与实施。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we communicate the next step to stakeholders?","zh":"我们应如何向相关方沟通下一步安排？"},"extension":{"en":"The stakeholder engagement plan includes evening sessions for teams on later shifts.","zh":"相关方参与计划安排了晚间交流场次，方便上较晚班次的团队参加。"}},{"id":"HRV6-M10-110","moduleId":"m10","module":"HR商务沟通与汇报","term":"Working session","zh":"专题工作会议／协同研讨会","definition":"围绕某个具体问题开展讨论和协作，并争取当场推进方案、决定或其他成果的会议。","example":"Let's schedule a working session to finalize the HR process.","collocation":"host a working session","dialogue":[{"role":"HR Operations Lead","en":"We keep going back and forth by email about who handles each exception.","zh":"哪些例外情况由谁处理，我们已经来回发了好多封邮件。"},{"role":"Process Owner","en":"Let's book a working session with payroll and HR. We can go through three real cases and agree who owns each step.","zh":"我们约薪资团队和人力资源团队开个专题工作会。拿三个实际案例一起过一遍，定好每一步由谁负责。"}],"usage":"","distinction":"Working session 让参与者当场分析、修改或完成具体工作；status meeting 主要同步进度；briefing 侧重说明情况或传达信息。","aliases":[],"new":true,"order":538,"collocationZh":"组织专题工作会议","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈwɜːkɪŋ ˈseʃən","ipaUS":"ˈwɝːkɪŋ ˈseʃən","ipaSource":"音素词典与英式语音规则推导","speakTerm":"Working session","exampleZh":"我们安排一次工作会议，敲定人力资源流程吧。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we communicate the next step to stakeholders?","zh":"我们应如何向相关方沟通下一步安排？"},"extension":{"en":"The working session ended with a draft handover checklist and two open questions.","zh":"专题工作会议结束时，大家拿出了一份交接清单草案，还留下两个待解决的问题。"}},{"id":"HRV6-M10-111","moduleId":"m10","module":"HR商务沟通与汇报","term":"Compliance update","zh":"合规动态通报／合规进展通报","definition":"用于向相关方通报法规或内部要求变动、审查发现或整改进展的消息、简报或定期更新。","example":"HR shared a compliance update with regional managers.","collocation":"send a compliance update","dialogue":[{"role":"Regional Manager","en":"The sites are asking when to switch to the revised form. Can we give them a date?","zh":"各站点都在问什么时候换新版表格。我们能给个日期吗？"},{"role":"Compliance Lead","en":"Once legal confirms the effective date for each location, I'll include it in the next compliance update.","zh":"法务确认各地的生效日期后，我会把日期列在下一期合规通报里。"}],"usage":"","distinction":"Compliance update 通报合规要求变化或落实情况；regulatory alert 通常针对一项法规或监管变化发出提醒；audit report 记录审计范围、证据和发现。","aliases":[],"new":true,"order":539,"collocationZh":"发送合规进展通报","collocationReview":"V18.2 模型编辑复核","ipaUK":"kəmˈplaɪ.əns ˈʌp.deɪt","ipaUS":"kəmˈplaɪ.əns ˈʌp.deɪt","ipaSource":"https://dictionary.cambridge.org/dictionary/english/compliance | https://dictionary.cambridge.org/dictionary/english/update","speakTerm":"Compliance update","exampleZh":"人力资源部门向区域管理者通报了最新合规动态。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we communicate the next step to stakeholders?","zh":"我们应如何向相关方沟通下一步安排？"},"extension":{"en":"The compliance update lists the open corrective actions and the owner of each item.","zh":"合规进展通报列出了尚未完成的整改事项及各项负责人。"}},{"id":"HRV6-M10-112","moduleId":"m10","module":"HR商务沟通与汇报","term":"Follow-up email","zh":"跟进邮件／会后跟进邮件","definition":"在会议、沟通或提交请求之后发送的邮件，用于确认结果、补充资料、催询进度或推进后续行动。","example":"I will send a follow-up email with the agreed next steps.","collocation":"send a follow-up email","dialogue":[{"role":"HR Coordinator","en":"The vendor still hasn't sent the invoice we asked for on Monday.","zh":"我们周一向供应商要的发票，他们还没发过来。"},{"role":"Project Lead","en":"Send a short follow-up email and ask whether they can get it to us before Friday's payment run.","zh":"发封简短的跟进邮件，问问能不能赶在周五这批付款前把发票发给我们。"}],"usage":"","distinction":"Follow-up email 强调接续之前的沟通或事项，可用于确认结论、补充材料或询问进度；reminder email 侧重提醒待办或期限；meeting minutes 是会议纪要，可作为跟进邮件的附件。","aliases":[],"new":true,"order":540,"collocationZh":"发送跟进邮件","collocationReview":"V18.2 模型编辑复核","ipaUK":"ˈfɒl.əʊ.ʌp ˈiː.meɪl","ipaUS":"ˈfɑː.loʊ.ʌp ˈiː.meɪl","ipaSource":"https://dictionary.cambridge.org/dictionary/english/follow | https://dictionary.cambridge.org/dictionary/english/up | https://dictionary.cambridge.org/dictionary/english/email","speakTerm":"Follow-up email","exampleZh":"我会发一封跟进邮件，列明已商定的下一步行动。","ipaReview":"组成词已核对，完整词头待核对","ipaNote":"按词典组成词记音，完整词头发音待核对。朗读使用设备语音。","legacyDialogueBookmark":{"en":"How should we communicate the next step to stakeholders?","zh":"我们应如何向相关方沟通下一步安排？"},"extension":{"en":"The follow-up email included a link to the revised draft and a deadline for comments.","zh":"跟进邮件里附了修订稿链接，并写明意见反馈的截止日期。"}},{"id":"HRV8-001","moduleId":"m10","module":"HR商务沟通与汇报","term":"Revise","zh":"修订（人力资源政策／岗位说明书等）","definition":"在 HR 工作中指根据反馈、组织变化或法律要求，对岗位说明书、员工手册、薪酬政策等正式文件作出修改或修订。","example":"We need to revise the job description before posting the vacancy.","collocation":"revise a policy draft","collocationZh":"修订政策草案","dialogue":[{"role":"HR Business Partner","en":"The handbook still sends people to the old expense portal.","zh":"员工手册还让大家去旧的报销平台。"},{"role":"HR Operations Specialist","en":"I’ll revise that section today and have Finance check the new link.","zh":"我今天会修订那一节，再请财务核对新链接。"}],"usage":"revise 是“修订（文件、政策）”，与 review（审阅）不同；在业务沟通中还可以说 revise the compensation policy（修订薪酬政策）。","new":true,"order":541,"aliases":["revise a policy","修订制度","修订政策"],"distinction":"Revise 表示实际修改文件。Review 表示审阅文件，审阅后可以维持原文。Amend 常见于正式条款或协议的局部修改。","collocationReview":"V18.2 模型编辑复核","ipaUK":"rɪˈvaɪz","ipaUS":"rɪˈvaɪz","ipaSource":"词典重点校订","speakTerm":"Revise","exampleZh":"发布岗位招聘信息前，我们需要修订岗位说明书。","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","legacyDialogueBookmark":{"en":"Could you revise the job description to reflect the new responsibilities?","zh":"你能否修订岗位说明书，反映新增的岗位职责？"},"extension":{"en":"Legal asked us to revise the leave policy to clarify how requests are approved.","zh":"法务请我们修订休假政策，明确申请的审批流程。"}},{"id":"HRV178-001","moduleId":"m2","module":"薪酬激励与福利","term":"Housing provident fund","zh":"住房公积金","definition":"中国内地的住房专项储金制度，通常由适用单位和职工按规定缴存。缴存和使用涉及当地执行规则。","example":"Employees can check their housing provident fund contributions online.","exampleZh":"员工可以在线查询住房公积金缴存记录。","collocation":"contribute to the housing provident fund","collocationZh":"缴存住房公积金","dialogue":[{"role":"New Hire","en":"I moved here from Chengdu. Can I transfer my housing provident fund balance?","zh":"我从成都搬过来，原来的住房公积金余额可以转过来吗？"},{"role":"Payroll Specialist","en":"Let’s check the local provident fund centre’s transfer requirements before you apply.","zh":"你提交申请前，我们先查一下当地住房公积金管理中心的转移要求。"}],"usage":"中国住房保障制度下由单位和职工缴存的住房专项储金。","new":true,"order":542,"aliases":[],"distinction":"在中国内地，housing provident fund 指住房公积金。Provident fund 单独使用时要结合地区判断，有些地区用它指退休储蓄安排。","ipaUK":"ˈhaʊzɪŋ ˈprɒvɪdənt fʌnd","ipaUS":"ˈhaʊzɪŋ ˈprɑːvədənt fʌnd","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Housing provident fund","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Where can employees check their monthly housing contributions?","zh":"员工在哪里可以查询每月住房公积金缴存情况？"},"extension":{"en":"The housing provident fund contribution appears as a separate line on my payslip.","zh":"我的工资单上单独列出了住房公积金缴存额。"}},{"id":"HRV178-002","moduleId":"m4","module":"学习培训与人才发展","term":"Career development","zh":"职业发展","definition":"个人在职业生涯中积累经验、发展能力并拓展职业机会的过程。","example":"Managers should discuss career development with their team members.","exampleZh":"管理者应与团队成员讨论职业发展。","collocation":"support career development","collocationZh":"支持职业发展","dialogue":[{"role":"Employee","en":"I’d like to move into product operations eventually. Could I shadow someone on that team?","zh":"我希望以后转做产品运营。可以跟着那个团队的一位同事观摩学习吗？"},{"role":"Manager","en":"Yes. Let’s make that part of your career development plan for this quarter.","zh":"可以。我们把这项安排纳入你本季度的职业发展计划吧。"}],"usage":"员工长期职业能力与发展机会的提升过程。","new":true,"order":543,"aliases":[],"distinction":"Career development 涵盖长期职业成长，可通过项目轮岗、技能提升或晋升实现。Career planning 侧重选定职业方向并制定行动计划。","ipaUK":"kəˈrɪə dɪˈveləpmənt","ipaUS":"kəˈrɪr dɪˈveləpmənt","ipaSource":"英美音标文本复核（非真人试听）; https://dictionary.cambridge.org/pronunciation/english/development","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Career development","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"What should managers cover in their one-on-one meetings?","zh":"管理者在一对一面谈中应讨论哪些内容？"},"extension":{"en":"A cross-functional project can support career development by giving employees experience outside their usual role.","zh":"跨职能项目让员工有机会积累本职工作之外的经验，从而支持职业发展。"}},{"id":"HRV178-003","moduleId":"m4","module":"学习培训与人才发展","term":"Training and development (T&D)","zh":"培训与发展","definition":"通过培训和发展活动提升员工当前及未来岗位能力。","example":"We invest in training and development to build future capabilities.","exampleZh":"我们对培训与发展投入资源，以培养未来所需的能力。","collocation":"invest in training and development","collocationZh":"对培训与发展投入资源","dialogue":[{"role":"Operations Manager","en":"Two technicians want to qualify as shift leads. Can we support them?","zh":"有两名技术员想取得带班资格。我们能给他们一些支持吗？"},{"role":"Training Lead","en":"Let’s add supervised practice to next quarter’s training and development plan.","zh":"我们把带教实操加到下季度的培训与发展计划里吧。"}],"usage":"通过培训和发展活动提升员工当前及未来岗位能力。","new":true,"order":544,"aliases":[],"distinction":"Training and development（T&D）常指培训与发展活动，涵盖当前技能和未来职责所需能力。Learning and development（L&D）与其用法有重叠，也常用作统筹正式培训、辅导和日常学习的职能名称。","ipaUK":"ˈtreɪnɪŋ ən dɪˈveləpmənt","ipaUS":"ˈtreɪnɪŋ ən dɪˈveləpmənt","ipaSource":"英美音标文本复核（非真人试听）; https://dictionary.cambridge.org/pronunciation/english/training; https://dictionary.cambridge.org/pronunciation/english/development","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Training and development. T and D","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How are we preparing employees for future roles?","zh":"我们如何帮助员工为未来岗位做好准备？"},"extension":{"en":"Our training and development budget covers both technical courses and management coaching.","zh":"我们的培训与发展预算涵盖技术课程和管理辅导。"}},{"id":"HRV178-004","moduleId":"m4","module":"学习培训与人才发展","term":"Orientation training","zh":"新员工入职培训","definition":"帮助新员工了解组织、制度及基本工作要求的入职培训。","example":"New hires attend orientation training in their first week.","exampleZh":"新员工在入职第一周参加入职培训。","collocation":"attend orientation training","collocationZh":"参加入职培训","dialogue":[{"role":"New Hire","en":"My orientation training is on Friday, but I’m visiting the warehouse tomorrow.","zh":"我的入职培训在周五，可我明天就要去仓库。"},{"role":"Onboarding Coordinator","en":"I’ll arrange a separate safety briefing before your visit.","zh":"我会在你去仓库之前另行安排一次安全说明。"}],"usage":"帮助新员工了解组织、制度及基本工作要求的入职培训。","new":true,"order":545,"aliases":[],"distinction":"Orientation training 通常集中介绍入职初期需要了解的制度、设施和基本流程。Onboarding 涵盖更长的融入过程，还可包括岗位带教和后续沟通。","ipaUK":"ˌɔːriənˈteɪʃən ˈtreɪnɪŋ","ipaUS":"ˌɔːriənˈteɪʃən ˈtreɪnɪŋ","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/orientation; https://dictionary.cambridge.org/pronunciation/english/training","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Orientation training","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"When do new hires learn about company policies?","zh":"新员工什么时候了解公司政策？"},"extension":{"en":"The orientation training includes a short walkthrough of the timekeeping system.","zh":"入职培训包括一段简短的考勤系统操作演示。"}},{"id":"HRV178-005","moduleId":"m4","module":"学习培训与人才发展","term":"Skills training","zh":"技能培训","definition":"针对具体工作技能开展的培训。","example":"We provide skills training for new supervisors.","exampleZh":"我们为新任主管提供技能培训。","collocation":"provide skills training","collocationZh":"提供技能培训","dialogue":[{"role":"Team Lead","en":"The crew knows the new scanning procedure, but they’re still making mistakes on returns.","zh":"大家已经了解新的扫码流程，但处理退货时还是会出错。"},{"role":"Training Specialist","en":"I’ll run a hands-on skills training session using sample returns.","zh":"我会用模拟退货单带大家做一次技能实操培训。"}],"usage":"针对具体工作技能开展的培训。","new":true,"order":546,"aliases":[],"distinction":"Skills training 侧重练习工作所需的操作或行为。Briefing 主要用来传达新信息或说明要求。以反馈为例，说明会可以介绍新流程，技能培训则可以安排员工模拟谈话。","ipaUK":"skɪlz ˈtreɪnɪŋ","ipaUS":"skɪlz ˈtreɪnɪŋ","ipaSource":"英美音标文本复核（非真人试听）; https://dictionary.cambridge.org/pronunciation/english/training","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Skills training","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How are we helping newly appointed supervisors?","zh":"我们如何帮助新任主管？"},"extension":{"en":"The skills training ends with a practice session on resolving customer complaints.","zh":"技能培训最后安排了处理客户投诉的实操练习。"}},{"id":"HRV178-006","moduleId":"m7","module":"企业文化与员工体验","term":"Employee satisfaction survey","zh":"员工满意度调查","definition":"收集员工对工作环境、待遇等满意程度的调查。","example":"We will conduct an employee satisfaction survey next month.","exampleZh":"我们将在下个月开展员工满意度调查。","collocation":"conduct an employee satisfaction survey","collocationZh":"开展员工满意度调查","dialogue":[{"role":"Site Manager","en":"The night shift says shift swaps take too long to approve.","zh":"夜班同事反映，调班审批等得太久。"},{"role":"People Analyst","en":"Let’s add a question about shift swaps to the employee satisfaction survey.","zh":"我们在员工满意度调查里加一道关于调班的问题吧。"}],"usage":"收集员工对工作环境、待遇等满意程度的调查。","new":true,"order":547,"aliases":[],"distinction":"Employee satisfaction survey 测量员工对薪酬、工时或工作环境等方面的满意程度。Employee engagement survey 则常关注员工与工作的投入程度、归属感或对组织的认同，具体维度随问卷设计而异。","ipaUK":"ɪmˈplɔɪiː ˌsætɪsˈfækʃən ˈsɜːveɪ","ipaUS":"ɪmˈplɔɪiː ˌsætɪsˈfækʃən ˈsɝːveɪ","ipaSource":"Cambridge employee（组成词）: https://dictionary.cambridge.org/us/pronunciation/english/employee","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Employee satisfaction survey","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"When will we collect feedback on working conditions?","zh":"我们什么时候收集员工对工作条件的反馈？"},"extension":{"en":"The employee satisfaction survey asks staff to rate the predictability of their schedules.","zh":"员工满意度调查请员工评价自己能否提前知道班次。"}},{"id":"HRV178-007","moduleId":"m6","module":"员工关系与劳动合规","term":"Labor law","zh":"劳动法","definition":"规范雇佣和劳动关系的法律领域，可涉及劳动标准、工会活动和集体谈判。具体涵盖范围因司法辖区而异。","example":"HR must comply with applicable labor law.","exampleZh":"人力资源部门必须遵守适用的劳动法。","collocation":"comply with labor law","collocationZh":"遵守劳动法","dialogue":[{"role":"Employee Relations Manager","en":"The union has asked us to change how we schedule weekend shifts.","zh":"工会要求我们调整周末排班方式。"},{"role":"Legal Counsel","en":"Before we respond, let’s check the collective agreement and the labor law that applies at this site.","zh":"答复前，我们先核对集体协议和这个工作地点适用的劳动法。"}],"usage":"规范劳动关系的法律，具体规定因司法辖区而异。","new":true,"order":548,"aliases":[],"distinction":"Labor law 是美式拼写，英式作 labour law。在美国法律语境中，labor law 常侧重工会与集体劳动关系，employment law 常涵盖工资、反歧视等雇佣事项。具体用法和法律范围随司法辖区而异。","ipaUK":"ˈleɪbə lɔː","ipaUS":"ˈleɪbər lɔː","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Labor law","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"What legal framework applies to our employment practices?","zh":"我们的用工实践适用什么法律框架？"},"extension":{"en":"Our counsel flagged a change in local labor law that may affect the bargaining timetable.","zh":"法律顾问提醒我们，当地劳动法的一项变动可能影响集体谈判的时间安排。"}},{"id":"HRV178-008","moduleId":"m6","module":"员工关系与劳动合规","term":"Grievance handling","zh":"员工申诉处理","definition":"受理、调查和处理员工申诉的实际工作。","example":"We train managers in effective grievance handling.","exampleZh":"我们向管理者提供培训，帮助他们有效处理员工申诉。","collocation":"improve grievance handling","collocationZh":"改进员工申诉处理","dialogue":[{"role":"Line Manager","en":"An employee has filed a grievance about the rota. I drew up that rota myself.","zh":"有位员工对排班表提出了申诉，那张表是我排的。"},{"role":"Employee Relations Adviser","en":"I’ll take the lead on handling this grievance. Please send me the rota and any related messages.","zh":"这起申诉由我牵头处理。请把排班表和相关消息发给我。"}],"usage":"受理、调查和处理员工申诉的实际工作。","new":true,"order":549,"aliases":[],"distinction":"Grievance handling 指受理、核实和跟进申诉的实际工作。Grievance procedure 指正式流程，通常列明申诉渠道、处理步骤和复核安排。","ipaUK":"ˈɡriːvəns ˈhændlɪŋ","ipaUS":"ˈɡriːvəns ˈhændlɪŋ","ipaSource":"英美音标文本复核（非真人试听）; https://dictionary.cambridge.org/pronunciation/english/grievance; https://dictionary.cambridge.org/pronunciation/english/handling","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Grievance handling","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How do we help managers respond to formal employee complaints?","zh":"我们如何帮助管理者处理员工正式申诉？"},"extension":{"en":"Good grievance handling begins with acknowledging the complaint and explaining what happens next.","zh":"妥善处理员工申诉，首先要确认收到申诉，并向员工说明下一步安排。"}},{"id":"HRV178-009","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Promotion","zh":"晋升","definition":"员工升至更高职级或职责层级。","example":"The manager recommended her for promotion.","exampleZh":"经理推荐她晋升。","collocation":"recommend an employee for promotion","collocationZh":"推荐员工晋升","dialogue":[{"role":"Engineering Manager","en":"Lena has been leading the team since March. Can we make the role permanent?","zh":"莉娜从三月起就在带这个团队，可以正式任命她吗？"},{"role":"HR Business Partner","en":"I’ll check whether the role change needs to go through the promotion panel.","zh":"我会确认这次岗位变动是否需要提交晋升评审委员会。"}],"usage":"员工升至更高职级或职责层级。","new":true,"order":550,"aliases":[],"distinction":"Promotion 指升至更高的职位、职级或职责层级。Lateral move 指平级流动。Pay raise 指薪酬上调，员工留在原职级时也可能加薪。","ipaUK":"prəˈməʊʃən","ipaUS":"prəˈmoʊʃən","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/promotion","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Promotion","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"What did the manager recommend at the talent review?","zh":"经理在人才评审会上提出了什么建议？"},"extension":{"en":"Her promotion to regional manager takes effect on 1 July.","zh":"她晋升为区域经理的任命于 7 月 1 日生效。"}},{"id":"HRV178-010","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Job transfer","zh":"岗位调动","definition":"员工在岗位、部门或地点之间的调动。","example":"She requested a job transfer to another department.","exampleZh":"她申请调往另一个部门。","collocation":"request a job transfer","collocationZh":"申请岗位调动","dialogue":[{"role":"Employee","en":"I’ve seen a vacancy at the York office. Could I apply for a job transfer?","zh":"我看到约克办公室有个空缺，可以申请调过去吗？"},{"role":"HR Adviser","en":"Yes. Send me the vacancy reference and I’ll show you how to apply internally.","zh":"可以。把岗位编号发给我，我告诉你怎么走内部申请流程。"}],"usage":"员工在岗位、部门或地点之间的调动。","new":true,"order":551,"aliases":[],"distinction":"Job transfer 侧重员工调往另一岗位、部门或地点。Lateral move 强调调动前后的职级相近。Relocation 强调工作地点和居住地的迁移，一个员工也可能调岗而无须搬家。","ipaUK":"dʒɒb ˈtrænsfɜː","ipaUS":"dʒɑːb ˈtrænsfɝː","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Job transfer","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Why did she contact HR about moving teams?","zh":"她为什么就调换团队联系HR？"},"extension":{"en":"The job transfer takes effect after the employee hands over her current projects.","zh":"这名员工交接完当前项目后，岗位调动正式生效。"}},{"id":"HRV178-011","moduleId":"m6","module":"员工关系与劳动合规","term":"Resignation","zh":"辞职／主动离职","definition":"员工主动提出结束雇佣关系。","example":"He submitted his resignation on Monday.","exampleZh":"他周一提交了辞职通知。","collocation":"submit your resignation","collocationZh":"提交辞职通知","dialogue":[{"role":"Employee","en":"I’ve handed in my resignation. Can we talk about who’ll take over the client accounts?","zh":"我已经提交辞职通知了。我们能聊聊这些客户后续由谁接手吗？"},{"role":"Manager","en":"Let’s make a list this afternoon so we can introduce the new contacts before you leave.","zh":"我们今天下午列个清单，争取在你离职前把新的对接人介绍给客户。"}],"usage":"员工主动提出结束雇佣关系。","new":true,"order":552,"aliases":[],"distinction":"Resignation 侧重员工主动提出辞职。Dismissal 由雇主发起。Mutual separation 指双方协商结束雇佣关系。具体用语和法律后果依适用规则而异。","ipaUK":"ˌrezɪɡˈneɪʃən","ipaUS":"ˌrezɪɡˈneɪʃən","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/resignation","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Resignation","collocationReview":"V18.2 模型编辑复核","comparison":[{"term":"Resignation","note":"员工主动辞职。","relation":"本词"},{"term":"Dismissal","note":"雇主解除雇佣关系。","relation":"易混淆"},{"term":"Layoff","note":"通常因业务原因裁减人员，美式也可指暂时停工。","relation":"易混淆"},{"term":"Redundancy","note":"英式常指岗位不再需要而导致的裁员。","relation":"易混淆"},{"term":"Termination for cause","note":"基于特定原因解除雇佣关系，具体标准依合同和法律。","relation":"易混淆"},{"term":"Mutual separation agreement","note":"双方协商结束劳动关系的协议。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"When did he formally notify the company that he was leaving?","zh":"他什么时候正式通知公司自己要离职？"},"extension":{"en":"Please acknowledge receipt of her resignation and confirm the handover arrangements.","zh":"请确认已收到她的辞职通知，并确认工作交接安排。"}},{"id":"HRV178-012","moduleId":"m6","module":"员工关系与劳动合规","term":"Employment termination","zh":"雇佣关系终止或解除","definition":"雇佣关系的结束。在人事流程中可按广义使用，涵盖辞职、解雇或某些合同届满情形。具体含义以文件用语及适用法律为准。","example":"HR records the reason and effective date for each employment termination.","exampleZh":"人力资源部门记录每次雇佣关系终止的原因和生效日期。","collocation":"document an employment termination","collocationZh":"记录雇佣关系终止情况","dialogue":[{"role":"Payroll Specialist","en":"The system shows June 30, but the letter says July 2. Which date should I use for the final pay calculation?","zh":"系统里写的是 6 月 30 日，通知函上却是 7 月 2 日。核算最后一笔工资时该用哪个日期？"},{"role":"HR Adviser","en":"Hold the calculation for now. I’ll verify the employment termination date and update the record.","zh":"先暂缓核算。我会核实雇佣关系结束日期，再更新记录。"}],"usage":"雇佣关系结束，原因可能包括辞职、解雇或合同到期。","new":true,"order":553,"aliases":[],"distinction":"Employment termination 在离职管理中可泛指雇佣关系结束，在一些政策或法律语境中也可能专指雇主解除。Termination for cause 侧重有明确事由的解除。Contract expiration 只说明约定期限届满，届满后的雇佣状态须按适用规则判定。","ipaUK":"ɪmˈplɔɪmənt ˌtɜːmɪˈneɪʃən","ipaUS":"ɪmˈplɔɪmənt ˌtɝːməˈneɪʃən","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/employment; https://dictionary.cambridge.org/pronunciation/english/termination","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Employment termination","collocationReview":"V18.2 模型编辑复核","comparison":[{"term":"Employment termination","note":"在人事流程中可泛指雇佣关系结束，部分文件或法律语境中指雇主解除。","relation":"本词"},{"term":"Contract expiration","note":"合同约定期限届满。届满后的雇佣状态视合同和适用法律而定。英式英语常用 contract expiry。","relation":"易混淆"},{"term":"Termination for cause","note":"雇主基于明确事由解除雇佣关系，具体标准依适用合同和法律而定。","relation":"易混淆"},{"term":"Terminate","note":"动词，表示终止合同或雇佣关系，具体时间取决于上下文。","relation":"易混淆"},{"term":"Expire","note":"动词，表示合同、许可等到期。","relation":"易混淆"},{"term":"Expiry","note":"名词，英式英语常用，表示到期。","relation":"易混淆"},{"term":"Expiration","note":"名词，美式英语常用，表示到期。","relation":"易混淆"},{"term":"Contract renewal","note":"续订合同。","relation":"易混淆"},{"term":"Contract extension","note":"延长现有合同期限。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"How will HR handle the end of this employment relationship?","zh":"HR将如何处理这段雇佣关系的终止？"},"extension":{"en":"We track voluntary and involuntary employment terminations separately in our quarterly report.","zh":"我们在季度报告中分别统计员工主动离职与非自愿离职。"}},{"id":"HRV178-013","moduleId":"m7","module":"企业文化与员工体验","term":"Diversity and inclusion (D&I)","zh":"多元与包容","definition":"推动人员背景和观点的多样性，并改善不同员工参与、表达和发挥作用的条件。","example":"Our managers promote diversity and inclusion in their teams.","exampleZh":"我们的管理者在团队中促进多元与包容。","collocation":"promote diversity and inclusion","collocationZh":"促进多元与包容","dialogue":[{"role":"Employee Network Lead","en":"Colleagues on the late shift can’t make the lunchtime listening session.","zh":"上晚班的同事参加不了午间意见交流会。"},{"role":"D&I Lead","en":"Let’s ask the D&I committee to add an evening session so they can share their views in person.","zh":"我们请多元与包容委员会加一场晚间交流会，让他们也能当面表达意见。"}],"usage":"促进员工群体多元性及包容性参与，不等同于包含公平维度的DEI。","new":true,"order":554,"aliases":[],"distinction":"Diversity 关注人员背景、经历和观点的多样性。Inclusion 关注员工能否参与并表达意见。DEI 把 equity 明确列为一项，关注影响机会和资源获取的障碍。","ipaUK":"daɪˈvɜːsəti ən ɪnˈkluːʒən","ipaUS":"daɪˈvɝːsəti ən ɪnˈkluːʒən","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Diversity and inclusion. D and I","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How do managers help everyone feel included?","zh":"管理者如何帮助每个人感受到归属感？"},"extension":{"en":"Our diversity and inclusion committee invited field staff to help design the employee forum.","zh":"公司的多元与包容委员会邀请一线员工参与设计员工论坛。"}},{"id":"HRV178-014","moduleId":"m7","module":"企业文化与员工体验","term":"Remote work","zh":"远程办公","definition":"在常规办公场所以外开展工作。","example":"The policy allows remote work two days a week.","exampleZh":"该政策允许每周远程办公两天。","collocation":"allow remote work","collocationZh":"允许远程办公","dialogue":[{"role":"Employee","en":"Would it count as remote work if I spent Friday at a coworking space?","zh":"我周五在共享办公空间上班，也算远程办公吗？"},{"role":"Manager","en":"Yes. Check with IT that you can connect securely from there.","zh":"算。先和 IT 确认一下在那里能否安全接入公司系统。"}],"usage":"在常规办公场所以外开展工作。","new":true,"order":555,"aliases":["Telecommuting"],"distinction":"Remote work 是在常规工作场所之外工作，也可在共享办公空间进行。Work from home 特指在家工作。Hybrid work 通常指远程与现场办公相结合。","ipaUK":"rɪˈməʊt wɜːk","ipaUS":"rɪˈmoʊt wɝːk","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Remote work","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How many days a week can employees work remotely under the policy?","zh":"根据政策，员工每周可以远程办公几天？"},"extension":{"en":"The remote work agreement specifies which locations employees may work from.","zh":"远程办公协议明确列出了员工可以办公的地点。"}},{"id":"HRV178-015","moduleId":"m7","module":"企业文化与员工体验","term":"Flexible working hours","zh":"弹性工作时间","definition":"在约定范围内灵活安排上下班时间。","example":"Our team offers flexible working hours.","exampleZh":"我们团队提供弹性工作时间。","collocation":"offer flexible working hours","collocationZh":"提供弹性工作时间","dialogue":[{"role":"Employee","en":"Can I start at seven on Tuesdays so I can pick up my daughter after school?","zh":"我周二能七点上班吗？这样就能接女儿放学。"},{"role":"Manager","en":"Yes, that fits our flexible working hours. Just put your Tuesday hours on the team calendar.","zh":"可以，这符合我们的弹性工作时间安排。把你周二的工作时段标在团队日历上就行。"}],"usage":"在约定范围内灵活安排上下班时间。","new":true,"order":556,"aliases":[],"distinction":"Flexible working hours 关注上班和下班时间的弹性。Flexible working 的范围更广，可包括工时、工作地点或工作方式。弹性上下班的安排也可以规定核心工作时段。","ipaUK":"ˈfleksəbəl ˈwɜːkɪŋ ˈaʊəz","ipaUS":"ˈfleksəbəl ˈwɝːkɪŋ ˈaʊərz","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Flexible working hours","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Can employees adjust their start and finish times?","zh":"员工可以调整上下班时间吗？"},"extension":{"en":"Our flexible working hours policy lets employees start anytime between seven and ten.","zh":"按公司的弹性工作时间政策，员工可以在七点到十点之间自行选择上班时间。"}},{"id":"HRV178-016","moduleId":"m1","module":"招聘与人才获取","term":"Internship program","zh":"实习项目","definition":"为实习生提供实践经验的结构化项目。","example":"We will launch an internship program this summer.","exampleZh":"我们将在今年夏天启动实习项目。","collocation":"launch an internship program","collocationZh":"启动实习项目","dialogue":[{"role":"Hiring Manager","en":"Could we give the summer interns a real project of their own?","zh":"能给暑期实习生安排一个由他们自己负责的实际项目吗？"},{"role":"Campus Recruiter","en":"Yes. For this internship program, let’s give each intern a project sponsor and weekly check-ins.","zh":"可以。这个实习项目里，我们给每位实习生安排一位项目指导人，每周跟进一次。"}],"usage":"为实习生提供实践经验的结构化项目。","new":true,"order":557,"aliases":[],"distinction":"Internship program 通常有明确的实践任务和指导安排。Job shadowing 主要通过跟岗观察学习。Apprenticeship 通常围绕职业技能安排较系统的在岗学习与培训，具体制度因地区而异。","ipaUK":"ˈɪntɜːnʃɪp ˈprəʊɡræm","ipaUS":"ˈɪntɝːnʃɪp ˈproʊɡræm","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/internship","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Internship program","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How will we attract students this summer?","zh":"今年夏天我们将如何吸引学生人才？"},"extension":{"en":"The internship program ends with a presentation on each intern’s project.","zh":"实习项目结束时，每位实习生都会汇报自己的项目。"}},{"id":"HRV178-017","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Job title","zh":"职位名称","definition":"用于标识岗位的正式名称。","example":"Please update the job title in the HR system.","exampleZh":"请在HR系统中更新职位名称。","collocation":"update a job title","collocationZh":"更新职位名称","dialogue":[{"role":"Recruiter","en":"The manager wants the ad to say “Data Scientist”, but the requisition says “Data Analyst”.","zh":"用人经理希望招聘广告写“数据科学家”，但申请单上写的是“数据分析师”。"},{"role":"HR Business Partner","en":"Let’s confirm the official job title before the ad goes live.","zh":"广告发布前，我们先确认正式的职位名称。"}],"usage":"用于标识岗位的正式名称。","new":true,"order":558,"aliases":[],"distinction":"Job title 是岗位名称。Job grade 表示组织内部的岗位等级。Job description 说明职责、工作范围等内容。不同机构即使使用相同的职位名称，岗位等级也可能不同。","ipaUK":"dʒɒb ˈtaɪtəl","ipaUS":"dʒɑːb ˈtaɪt̬əl","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/job ; https://dictionary.cambridge.org/pronunciation/english/title","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Job title","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"What needs to change in the system after the promotion?","zh":"晋升后系统中需要更新什么？"},"extension":{"en":"The job title on my email signature has changed since I moved to Operations.","zh":"我调到运营部后，邮件签名里的职位名称也改了。"}},{"id":"HRV178-018","moduleId":"m6","module":"员工关系与劳动合规","term":"Full-time employee","zh":"全职员工","definition":"按适用的全职工时或工作安排受雇的员工。全职标准可因机构及适用法律而异。","example":"We plan to hire a full-time employee for this role.","exampleZh":"我们计划为该岗位招聘一名全职员工。","collocation":"hire a full-time employee","collocationZh":"招聘全职员工","dialogue":[{"role":"Finance Partner","en":"The staffing plan adds 1.0 FTE. Are you splitting those hours between two people?","zh":"人员计划里多了 1.0 个全职当量。你打算把这些工时分给两个人吗？"},{"role":"Store Manager","en":"I’d prefer one full-time employee to coordinate the weekday shifts.","zh":"我更希望安排一名全职员工来协调工作日的班次。"}],"usage":"按全职工作安排受雇的员工；FTE通常指全职当量而非员工身份。","new":true,"order":559,"aliases":[],"distinction":"Full-time employee 指按适用全职安排工作的员工。Full-time equivalent（FTE）通常是折算的用工量。两名各按标准全职工时的一半工作的员工合计为 1 FTE，实际人数为两人。","ipaUK":"ˌfʊl ˈtaɪm ɪmˈplɔɪiː","ipaUS":"ˌfʊl ˈtaɪm ɪmˈplɔɪiː","ipaSource":"Cambridge employee（组成词）: https://dictionary.cambridge.org/us/pronunciation/english/employee","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Full-time employee","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Are we hiring someone on a full-time or part-time basis?","zh":"我们要招聘全职还是兼职人员？"},"extension":{"en":"A full-time employee joined the team to take over the weekday rota.","zh":"团队新来了一名全职员工，负责接手工作日排班。"}},{"id":"HRV178-019","moduleId":"m6","module":"员工关系与劳动合规","term":"Part-time employee","zh":"兼职员工／非全职员工","definition":"工作时间少于全职标准的员工，法律定义因地区而异。","example":"We hired a part-time employee to cover the evening shift.","exampleZh":"我们招聘了一名兼职员工负责晚班。","collocation":"hire a part-time employee","collocationZh":"招聘兼职员工","dialogue":[{"role":"Store Manager","en":"Sales are busiest on Saturdays. Could we add one person for the weekend shift?","zh":"周六店里最忙。能给周末班加个人吗？"},{"role":"Recruiter","en":"If you’ll need that coverage year-round, we can advertise for a part-time employee.","zh":"如果全年都需要有人上这个班，我们可以发布兼职招聘信息。"}],"usage":"工作时间少于全职标准的员工，法律定义因地区而异。","new":true,"order":560,"aliases":[],"distinction":"Part-time employee 强调员工的约定工时低于适用的全职标准。Temporary employee 强调用工期限，临时员工也可能按全职工时工作。中国内地的“非全日制用工”另有法定判断标准。","ipaUK":"ˌpɑːt ˈtaɪm ɪmˈplɔɪiː","ipaUS":"ˌpɑːrt ˈtaɪm ɪmˈplɔɪiː","ipaSource":"Cambridge employee（组成词）: https://dictionary.cambridge.org/us/pronunciation/english/employee","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Part-time employee","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How did we cover the evening shift?","zh":"我们如何解决晚班人员安排？"},"extension":{"en":"The part-time employee works three mornings a week at the reception desk.","zh":"这名兼职员工每周在前台工作三个上午。"}},{"id":"HRV178-020","moduleId":"m6","module":"员工关系与劳动合规","term":"Contractor","zh":"承包方／独立承包人员","definition":"按合同承接并提供服务的个人或机构。个人是否属于独立承包人员等类别，须结合实际工作安排和适用法律判断。","example":"We engaged an independent contractor to provide specialized services for the project.","exampleZh":"我们委托了一名独立承包人员，为该项目提供专业服务。","collocation":"engage an independent contractor","collocationZh":"委托独立承包人员提供服务","dialogue":[{"role":"Project Manager","en":"We’d like the contractor to start attending daily stand-ups and work the same hours as our team.","zh":"我们想让这位承包人员参加每天的站会，工时也和团队一致。"},{"role":"HR Adviser","en":"Let’s have Legal review the proposed arrangement before we change how the work is managed.","zh":"调整工作管理方式前，我们先请法务审查拟议安排。"}],"usage":"按服务合同提供服务的个人或机构，法律身份取决于实际安排。","new":true,"order":561,"aliases":[],"distinction":"Contractor 可指按合同承接服务的个人或机构。Independent contractor 用于强调独立承包关系，具体身份认定须结合实际工作安排和适用法律。Fixed-term employee 指按有固定期限的雇佣合同受雇的员工。","ipaUK":"kənˈtræktə","ipaUS":"ˈkɑːntræktɚ","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/contractor","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Contractor","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Who did we bring in to deliver the project?","zh":"我们引入了谁来完成该项目？"},"extension":{"en":"The contractor will deliver the first draft by Friday, as agreed in the statement of work.","zh":"按工作说明书的约定，承包方将在周五前交付初稿。"}},{"id":"HRV178-021","moduleId":"m1","module":"招聘与人才获取","term":"Intern","zh":"实习生","definition":"参加实习以获得工作经验的人员。","example":"Each intern will have a designated mentor.","exampleZh":"每位实习生都将有一名指定导师。","collocation":"supervise an intern","collocationZh":"督导实习生","dialogue":[{"role":"Team Lead","en":"Our intern has asked to sit in on a client call next week.","zh":"我们团队的实习生问，下周能不能旁听一次客户电话会议。"},{"role":"Supervisor","en":"Pick a suitable call and check with the client first. Then we can debrief with her afterwards.","zh":"先挑一场合适的会议，征得客户同意。会后我们可以和她一起复盘。"}],"usage":"参加实习以获得工作经验的人员。","new":true,"order":562,"aliases":[],"distinction":"Intern 是为积累实践经验而参加实习的人。Trainee 泛指接受培训的人员，可用于正式员工的培养岗位。实习生的法律身份和待遇依实际安排及当地规定而定。","ipaUK":"ˈɪntɜːn","ipaUS":"ˈɪntɝːn","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/intern","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Intern","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Who will guide the interns during the program?","zh":"实习期间由谁指导实习生？"},"extension":{"en":"The intern presented her findings to the product team at the end of the placement.","zh":"实习结束时，这名实习生向产品团队汇报了她的研究发现。"}},{"id":"HRV178-022","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Job evaluation","zh":"岗位价值评估","definition":"系统评估岗位相对价值，为薪酬和定级提供依据。","example":"We conducted a job evaluation before setting the pay grade.","exampleZh":"我们在确定薪酬等级前开展了岗位价值评估。","collocation":"conduct a job evaluation","collocationZh":"开展岗位价值评估","dialogue":[{"role":"Department Head","en":"The procurement role now covers three countries instead of one. Should we revisit its grade?","zh":"采购岗原来只负责一个国家，现在负责三个。我们要重新看看它的等级吗？"},{"role":"Compensation Partner","en":"Send me the updated job description so we can start a job evaluation.","zh":"把更新后的岗位说明书发给我，我们就可以启动岗位价值评估。"}],"usage":"系统评估岗位相对价值，为薪酬和定级提供依据。","new":true,"order":563,"aliases":[],"distinction":"Job evaluation 评估岗位本身的相对价值。Performance appraisal 评估在岗员工的工作表现。Job grading 则侧重将岗位归入组织的等级体系。","ipaUK":"ˈdʒɒb ɪ.væl.juˌeɪ.ʃən","ipaUS":"ˈdʒɑːb ɪ.væl.juˌeɪ.ʃən","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/job-evaluation","ipaReview":"完整词头英美音标文本核对","ipaNote":"英美音标据 Cambridge 发音词头核对。朗读使用设备语音。","speakTerm":"Job evaluation","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How did we determine the appropriate pay grade?","zh":"我们如何确定合适的薪酬等级？"},"extension":{"en":"A job evaluation considers the scope of the role and the level of responsibility it carries.","zh":"岗位价值评估会考虑岗位的工作范围及承担的责任层级。"}},{"id":"HRV178-023","moduleId":"m4","module":"学习培训与人才发展","term":"Learning and development (L&D)","zh":"学习与发展","definition":"组织促进员工学习、能力提升与发展的职能。","example":"She leads learning and development for the region.","exampleZh":"她负责该区域的学习与发展工作。","collocation":"lead learning and development","collocationZh":"负责学习与发展","dialogue":[{"role":"Sales Director","en":"The training scores are high, but people still struggle on live calls.","zh":"培训测验分数很高，可一到实际通话，大家还是应付不来。"},{"role":"HR Business Partner","en":"I’ll ask Learning and Development to pair the new hires with experienced reps for call practice.","zh":"我会请学习与发展团队安排资深销售和新员工结对，练习客户通话。"}],"usage":"组织促进员工学习、能力提升与发展的职能。","new":true,"order":564,"aliases":[],"distinction":"Learning and development（L&D）常用作员工学习与发展职能的名称，涵盖正式课程、辅导和在岗学习等。Training and development（T&D）也可指同一职能，措辞更突出培训与发展活动。","ipaUK":"ˈlɜːnɪŋ ən dɪˈveləpmənt","ipaUS":"ˈlɝːnɪŋ ən dɪˈveləpmənt","ipaSource":"英美音标文本复核（非真人试听）; https://dictionary.cambridge.org/pronunciation/english/development","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Learning and development. L and D","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Who oversees employee learning in this region?","zh":"谁负责该区域的员工学习工作？"},"extension":{"en":"The learning and development team tracks whether managers apply new skills on the job.","zh":"学习与发展团队会跟踪管理者是否在工作中应用新技能。"}},{"id":"HRV178-024","moduleId":"m4","module":"学习培训与人才发展","term":"Training program","zh":"培训项目","definition":"围绕明确学习目标设计的培训活动组合。","example":"We designed a training program for first-time managers.","exampleZh":"我们为初任管理者设计了培训项目。","collocation":"design a training program","collocationZh":"设计培训项目","dialogue":[{"role":"HR Coordinator","en":"The warehouse team can’t release everyone for a full morning.","zh":"仓库没法让所有人同时离岗一上午。"},{"role":"Training Manager","en":"Let’s run the same training program in two cohorts so each shift stays covered.","zh":"我们把同一个培训项目分两批开展，确保每个班次都有人值守。"}],"usage":"围绕明确学习目标设计的培训活动组合。","new":true,"order":565,"aliases":[],"distinction":"Training program 通常围绕共同目标组织多个培训环节。Training session 是其中可单独排期的一次活动。Training curriculum 侧重课程内容、顺序和学习目标的安排。","ipaUK":"ˈtreɪnɪŋ ˈprəʊɡræm","ipaUS":"ˈtreɪnɪŋ ˈproʊɡræm","ipaSource":"英美音标文本复核（非真人试听）; https://dictionary.cambridge.org/pronunciation/english/training","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Training program","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"What support is available for new managers?","zh":"新任管理者可以获得哪些支持？"},"extension":{"en":"The training program combines short online modules with supervised practice.","zh":"该培训项目结合了简短的在线学习单元和带教实操。"}},{"id":"HRV178-025","moduleId":"m4","module":"学习培训与人才发展","term":"Workshop","zh":"工作坊／研讨式培训","definition":"以参与和实践为主的专题学习活动。","example":"HR will facilitate a workshop on feedback skills.","exampleZh":"HR将主持一场反馈技巧工作坊。","collocation":"facilitate a workshop","collocationZh":"主持工作坊","dialogue":[{"role":"HR Partner","en":"Can we skip the slides this time and give managers a case to work through?","zh":"这次能少讲幻灯片，给管理者一个案例来练吗？"},{"role":"Facilitator","en":"Yes. I’ll turn the briefing into a workshop and have them compare their approaches.","zh":"可以。我会把说明会改成工作坊，让他们交流各自的处理方法。"}],"usage":"以参与和实践为主的专题学习活动。","new":true,"order":566,"aliases":[],"distinction":"Workshop 往往安排讨论、演练或共同产出。Presentation 侧重由讲者传递信息。同一场工作坊可以先安排简短讲解，再让参与者动手练习。","ipaUK":"ˈwɜːkʃɒp","ipaUS":"ˈwɝːkʃɑːp","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Workshop","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How will managers practice giving feedback?","zh":"管理者将如何练习反馈技巧？"},"extension":{"en":"Each group will leave the workshop with a draft action plan.","zh":"各小组将在工作坊结束时拿出一份行动计划草案。"}},{"id":"HRV178-026","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Career path","zh":"职业发展路径","definition":"员工职业发展中可能经历的岗位或层级路线。","example":"We discussed a possible career path for the employee.","exampleZh":"我们讨论了该员工可能的职业发展路径。","collocation":"explore a career path","collocationZh":"探索职业发展路径","dialogue":[{"role":"Analyst","en":"I’d like to move into workforce planning, but I’ve only worked in payroll.","zh":"我想转做人力规划，可我之前只做过薪资。"},{"role":"Career Coach","en":"Let’s map out a career path that starts with a project on headcount forecasting.","zh":"我们来梳理一条职业发展路径，先从参与一个人数预测项目开始。"}],"usage":"员工职业发展中可能经历的岗位或层级路线。","new":true,"order":567,"aliases":[],"distinction":"Career path 指可能经过的岗位、职能或职级路线，可包含横向转岗。Career pathing 指梳理和规划这些路线的过程。Career ladder 更强调在某一岗位序列中逐级发展。","ipaUK":"kəˈrɪə pɑːθ","ipaUS":"kəˈrɪr pæθ","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Career path","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"What did you discuss in the career conversation?","zh":"你们在职业发展面谈中讨论了什么？"},"extension":{"en":"The specialist career path gives engineers a way to progress without moving into management.","zh":"专家职业发展路径让工程师无需转做管理也能继续发展。"}},{"id":"HRV178-027","moduleId":"m4","module":"学习培训与人才发展","term":"Skills gap analysis","zh":"技能差距分析","definition":"将个人或团队现有技能与工作所需的技能对照，找出差距，为培训、招聘或人员调配提供依据。","example":"A skills gap analysis helped us identify training priorities.","exampleZh":"技能差距分析帮助我们确定培训重点。","collocation":"conduct a skills gap analysis","collocationZh":"开展技能差距分析","dialogue":[{"role":"Operations Lead","en":"We’re buying new equipment. How do we decide who needs training before it arrives?","zh":"我们要买新设备。在设备到货前，怎么确定哪些人需要培训？"},{"role":"Learning Partner","en":"Let’s run a skills gap analysis against the tasks people will actually perform on the new machines.","zh":"我们根据大家实际要用新设备完成的任务，做一次技能差距分析。"}],"usage":"比较现有技能与目标技能以识别培训需求。","new":true,"order":568,"aliases":[],"distinction":"Skills gap analysis 是比较现有技能与所需技能的分析过程。Skills gap 是识别出的差距。Training needs analysis 进一步判断差距是否适合用培训解决，也可考虑工具、流程等因素。","ipaUK":"skɪlz ɡæp əˈnæləsɪs","ipaUS":"skɪlz ɡæp əˈnæləsɪs","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Skills gap analysis","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How did you identify the most urgent training needs?","zh":"你们如何识别最迫切的培训需求？"},"extension":{"en":"The skills gap analysis showed that several teams needed more practice with data visualisation.","zh":"技能差距分析显示，有几个团队需要多练习数据可视化。"}},{"id":"HRV178-028","moduleId":"m4","module":"学习培训与人才发展","term":"Certification","zh":"认证／资格认证","definition":"由相关机构确认符合特定标准或资格的过程或结果。","example":"For this credential, employees must pass a practical assessment to obtain certification.","exampleZh":"员工须通过实操考核，才能获得这项资格认证。","collocation":"obtain certification","collocationZh":"获得认证","dialogue":[{"role":"Employee","en":"I’ve finished the online course. Can I add the certification to my profile?","zh":"我上完了线上课程，可以把这项认证加到个人档案里吗？"},{"role":"Learning Coordinator","en":"You can add the course completion now. The certification requires a separate assessment.","zh":"现在可以先记录课程已完成。要取得这项认证，还需要单独参加考核。"}],"usage":"由相关机构确认符合特定标准或资格的过程或结果。","new":true,"order":569,"aliases":[],"distinction":"Certification 指按特定标准进行的认证，也可指获得的资格认证。Certificate 是证书，可用来证明通过认证，也可仅证明完成课程。License 在受监管职业中通常指执业许可，具体要求依地区和行业而异。","ipaUK":"ˌsɜːtɪfɪˈkeɪʃən","ipaUS":"ˌsɝːt̬əfɪˈkeɪʃən","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Certification","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How can employees earn the professional credential?","zh":"员工如何获得该专业资质？"},"extension":{"en":"Please check whether your certification is still valid before signing up for the project.","zh":"报名参与项目前，请确认你的资格认证是否仍在有效期内。"}},{"id":"HRV178-029","moduleId":"m4","module":"学习培训与人才发展","term":"Soft skills","zh":"软技能","definition":"沟通、协作等非技术性能力。","example":"The program helps employees develop soft skills such as communication and teamwork.","exampleZh":"该项目帮助员工培养沟通与团队协作等软技能。","collocation":"develop soft skills","collocationZh":"培养软技能","dialogue":[{"role":"Recruiter","en":"Both candidates passed the technical exercise. How should we compare their soft skills?","zh":"两位候选人都通过了技术测试。我们怎么比较他们的软技能？"},{"role":"Hiring Manager","en":"Let’s ask both of them to explain the same technical issue to a nontechnical colleague.","zh":"我们请两人分别向一位非技术同事解释同一个技术问题。"}],"usage":"沟通、协作等非技术性能力。","new":true,"order":570,"aliases":[],"distinction":"Soft skills 指沟通、协作、适应等可通过行为展示和练习的能力。Hard skills 指具体的技术或程序性技能。一次客服演练可以同时考查倾听能力和工单系统操作。","ipaUK":"ˈsɒft ˌskɪlz","ipaUS":"ˈsɑːft ˌskɪlz","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Soft skills","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"What interpersonal skills does the program help employees develop?","zh":"该项目帮助员工培养哪些人际交往能力？"},"extension":{"en":"The supervisor gave specific feedback on the soft skills the team used during the negotiation.","zh":"主管就团队在谈判中运用的软技能给出了具体反馈。"}},{"id":"HRV178-030","moduleId":"m4","module":"学习培训与人才发展","term":"Hard skills","zh":"硬技能／专业技术技能","definition":"可在具体任务中展示和评估的技术或专业技能，例如焊接、编程或对账。","example":"The interview includes a test to assess hard skills.","exampleZh":"面试包含一项评估专业技能的测试。","collocation":"assess hard skills","collocationZh":"评估硬技能","dialogue":[{"role":"Recruiter","en":"One applicant hasn’t used our software. Is that a deal-breaker?","zh":"有位应聘者没用过我们的软件，这就不能考虑了吗？"},{"role":"Hiring Manager","en":"Let’s test the hard skills that matter for the role, like reconciling discrepancies in the sample data.","zh":"我们测试这个岗位真正需要的专业技能，比如核对样本数据中的差异。"}],"usage":"可通过训练和考核获得的具体技术或专业技能。","new":true,"order":571,"aliases":[],"distinction":"Hard skills 指具体、可通过实际任务展示的技术或专业技能，例如编写 SQL 查询。Soft skills 指沟通、协作等能力，也可以通过可观察的行为来评估。","ipaUK":"hɑːd skɪlz","ipaUS":"hɑːrd skɪlz","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Hard skills","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How do we assess candidates' technical abilities?","zh":"我们如何评估候选人的技术能力？"},"extension":{"en":"The job posting lists the hard skills applicants will need for the data migration.","zh":"招聘公告列出了应聘者参与数据迁移工作所需的专业技能。"}},{"id":"HRV178-031","moduleId":"m2","module":"薪酬激励与福利","term":"Annual incentive plan (AIP)","zh":"年度激励计划","definition":"以年度绩效周期为依据的激励安排，通常列明适用对象、考核指标及奖励计算规则。","example":"The annual incentive plan links bonuses to business results.","exampleZh":"年度激励计划将奖金与经营业绩挂钩。","collocation":"design an annual incentive plan","collocationZh":"设计年度激励计划","dialogue":[{"role":"Sales Director","en":"Can we add a retention target for next year without dropping the revenue target?","zh":"明年能保留营收目标，再加一项客户留存目标吗？"},{"role":"Compensation Manager","en":"Yes. I’ll model both targets in next year’s annual incentive plan and show you how payouts could change.","zh":"可以。我会把这两个目标都纳入明年年度激励计划的测算，看看奖金可能会怎么变。"}],"usage":"以年度绩效周期为基础的激励安排。","new":true,"order":572,"aliases":[],"distinction":"Annual incentive plan（AIP）是按年度绩效周期设计的激励计划，通常规定参与资格、指标和奖金计算方式。Short-term incentive（STI）覆盖年度及更短周期的激励。Annual bonus 指年度奖金这项支付。","ipaUK":"ˈænjuəl ɪnˈsentɪv plæn","ipaUS":"ˈænjuəl ɪnˈsent̬ɪv plæn","ipaSource":"英美音标文本复核（非真人试听）; https://dictionary.cambridge.org/pronunciation/english/annual; https://dictionary.cambridge.org/pronunciation/english/incentive","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Annual incentive plan. A I P","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How are annual bonuses linked to company performance?","zh":"年度奖金如何与公司业绩挂钩？"},"extension":{"en":"The annual incentive plan explains how payouts are calculated for employees who join midyear.","zh":"年度激励计划说明了如何为年中入职的员工计算奖金。"}},{"id":"HRV178-032","moduleId":"m2","module":"薪酬激励与福利","term":"Short-term incentive (STI)","zh":"短期激励","definition":"通常以一年或更短周期为基础的激励。","example":"The company offers a short-term incentive tied to quarterly results.","exampleZh":"公司提供与季度业绩挂钩的短期激励。","collocation":"offer a short-term incentive","collocationZh":"提供短期激励","dialogue":[{"role":"Business Lead","en":"The team needs a reason to stay focused through the three-month launch.","zh":"项目上线期有三个月，我们需要让团队在这段时间保持投入。"},{"role":"Compensation Partner","en":"A short-term incentive could work. Let’s agree on what the team can actually measure by launch day.","zh":"可以考虑短期激励。我们先定好到上线当天团队确实能衡量哪些成果。"}],"usage":"通常以一年或更短周期为基础的激励。","new":true,"order":573,"aliases":[],"distinction":"Short-term incentive（STI）通常依据一年或更短周期的表现，季度奖金和年度绩效奖金都可属于这一类。Long-term incentive（LTI）通常以多年绩效或分期归属为基础。","ipaUK":"ˌʃɔːt ˈtɜːm ɪnˈsentɪv","ipaUS":"ˌʃɔːrt ˈtɝːm ɪnˈsent̬ɪv","ipaSource":"英美音标文本复核（非真人试听）; https://dictionary.cambridge.org/pronunciation/english/incentive","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Short-term incentive. S T I","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Is there an incentive tied to quarterly performance?","zh":"是否有与季度业绩挂钩的激励？"},"extension":{"en":"Employees can track progress toward their short-term incentive targets in the monthly report.","zh":"员工可以在月报中查看短期激励目标的完成进度。"}},{"id":"HRV178-033","moduleId":"m2","module":"薪酬激励与福利","term":"Allowance","zh":"津贴／补贴","definition":"雇主针对特定开支、工作条件或派遣安排发放的津贴或补贴。","example":"Employees on assignment receive a travel allowance under the policy.","exampleZh":"根据政策，派遣员工可获得差旅津贴。","collocation":"provide a travel allowance","collocationZh":"提供差旅津贴","dialogue":[{"role":"Employee","en":"The assignment letter lists a housing allowance. Does it cover my deposit as well?","zh":"派遣函上列了住房补贴，租房押金也能用这笔补贴吗？"},{"role":"Mobility Adviser","en":"That allowance is for monthly rent. Let me check whether the relocation policy covers deposits separately.","zh":"这项补贴用于月租。我查一下搬迁政策是否另有押金安排。"}],"usage":"针对特定费用或工作条件提供的津贴。","new":true,"order":574,"aliases":[],"distinction":"Allowance 是针对特定开支或工作条件发放的金额，常按预定标准计算。Reimbursement 通常按符合条件的实际开支报销。具体凭证和税务要求依政策及适用规定而定。","ipaUK":"əˈlaʊəns","ipaUS":"əˈlaʊəns","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Allowance","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"What travel support is available to employees on assignment?","zh":"派遣员工可以获得哪些差旅支持？"},"extension":{"en":"The field technicians receive a meal allowance on overnight assignments.","zh":"外勤技术人员执行需要在外过夜的任务时，可领取餐费津贴。"}},{"id":"HRV178-034","moduleId":"m2","module":"薪酬激励与福利","term":"Insurance","zh":"保险","definition":"通过保险合同转移约定风险的保障安排。","example":"HR explains the insurance coverage during onboarding.","exampleZh":"人力资源部门在员工入职时说明保险保障范围。","collocation":"provide insurance coverage","collocationZh":"提供保险保障","dialogue":[{"role":"Employee","en":"Is my new dependent covered from today or from next month?","zh":"我刚加进去的家属从今天起有保障，还是下个月才开始？"},{"role":"Benefits Adviser","en":"I’ll check the effective date of their insurance coverage with the insurer.","zh":"我会向保险公司核对这位家属的保险保障生效日期。"}],"usage":"通过保险合同转移约定风险的保障安排。","new":true,"order":575,"aliases":[],"distinction":"Insurance 指保险安排。Coverage 指受保障的范围和限额。Premium 指保费。即使属于同一保险计划的参保人员，也应按适用条款确认某项费用是否受保。","ipaUK":"ɪnˈʃɔːrəns","ipaUS":"ɪnˈʃɝːəns","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/insurance","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Insurance","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"When do new hires learn what their insurance covers?","zh":"新员工什么时候了解保险保障范围？"},"extension":{"en":"New hires can find a summary of their insurance options in the benefits portal.","zh":"新员工可以在福利平台查看可选保险的概要。"}},{"id":"HRV178-035","moduleId":"m2","module":"薪酬激励与福利","term":"Pension plan","zh":"养老金计划","definition":"为成员退休后提供养老金的安排，给付方式、缴费规则和适用资格因计划及地区而异。","example":"Eligible employees can contribute to the pension plan.","exampleZh":"符合条件的员工可以向养老金计划缴费。","collocation":"contribute to a pension plan","collocationZh":"向养老金计划缴费","dialogue":[{"role":"Employee","en":"I’m transferring to the subsidiary next month. What happens to my pension plan?","zh":"我下个月要调到子公司，我的养老金计划会怎么处理？"},{"role":"Benefits Specialist","en":"I’ll check the rules for both plans and confirm whether your contributions can continue.","zh":"我会核对两边计划的规则，确认你能否继续缴费。"}],"usage":"为退休后收入提供保障的养老金安排。","new":true,"order":576,"aliases":[],"distinction":"Pension plan 侧重为退休提供养老金的安排。Retirement plan 是较宽泛的说法，也可包括退休储蓄账户等安排。不同司法辖区对 pension 和 retirement plan 的制度用语存在差异。","ipaUK":"ˈpenʃən ˌplæn","ipaUS":"ˈpenʃən ˌplæn","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/pension-plan","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Pension plan","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Can employees make contributions toward their retirement benefits?","zh":"员工可以为退休福利缴费吗？"},"extension":{"en":"The pension plan booklet explains how employer contributions are calculated.","zh":"养老金计划手册介绍了雇主缴费额的计算方式。"}},{"id":"HRV178-036","moduleId":"m6","module":"员工关系与劳动合规","term":"Non-compete agreement","zh":"竞业限制协议","definition":"约定个人在特定时期或范围内限制竞争活动的协议，常见于离职后安排。适用对象、范围和效力依当地法律及协议条款而定。","example":"Legal counsel will review the non-compete agreement.","exampleZh":"法律顾问将审查竞业限制协议。","collocation":"review a non-compete agreement","collocationZh":"审查竞业限制协议","dialogue":[{"role":"Hiring Manager","en":"The finalist says her current employer may object to her joining us. She mentioned a non-compete agreement.","zh":"这位进入最终面试的候选人说，现雇主可能会反对她加入我们。她提到有一份竞业限制协议。"},{"role":"Recruiter","en":"I’ll refer it to Legal so we can understand any restrictions before we discuss a start date.","zh":"我会请法务看一下，先弄清可能有哪些限制，再谈到岗日期。"}],"usage":"约定竞争活动限制的协议，效力取决于适用法律。","new":true,"order":577,"aliases":[],"distinction":"Non-compete agreement 以限制特定竞争活动为主要内容。Non-compete clause 可作为雇佣协议等文件中的一项条款。Confidentiality agreement 侧重保密义务。竞业限制是否允许及其效力取决于适用法律和个案情况。","ipaUK":"ˌnɒnkəmˈpiːt əˈɡriːmənt","ipaUS":"ˌnɑːnkəmˈpiːt əˈɡriːmənt","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Non-compete agreement","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Who will assess the enforceability of the agreement?","zh":"谁将评估该协议的可执行性？"},"extension":{"en":"The draft non-compete agreement lists the activities it would restrict.","zh":"竞业限制协议草案列出了拟限制的活动。"}},{"id":"HRV178-037","moduleId":"m8","module":"HR运营与数据分析","term":"Outsourcing","zh":"业务外包","definition":"将部分业务或服务委托外部供应商。","example":"HR is evaluating outsourcing options for payroll administration.","exampleZh":"人力资源部门正在评估薪资管理的外包方案。","collocation":"evaluate outsourcing options","collocationZh":"评估外包方案","dialogue":[{"role":"Payroll Manager","en":"If we outsource payroll processing, who signs off on the monthly pay run?","zh":"如果把薪资处理外包，每月的发薪还由谁审核？"},{"role":"Finance Partner","en":"We’ll keep final approval in-house. The vendor can prepare the files for us to review.","zh":"最终审批仍由我们内部负责。供应商可以准备文件，交给我们审核。"}],"usage":"将部分业务或服务委托外部供应商。","new":true,"order":578,"aliases":[],"distinction":"Outsourcing 关注由外部供应商承担业务或服务。Offshoring 关注将工作移至另一国家或地区，承接方也可以是同一企业的境外团队。外包可以在本地进行。","ipaUK":"ˈaʊtˌsɔː.sɪŋ","ipaUS":"ˈɑʊtˌsɔr.sɪŋ","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/outsourcing | https://dictionary.cambridge.org/dictionary/english/outsource","ipaReview":"完整词头英美音标文本核对","ipaNote":"英美音标据 Cambridge 发音词头核对。朗读使用设备语音。","speakTerm":"Outsourcing","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Are we considering an external payroll provider?","zh":"我们是否在考虑外部薪资服务商？"},"extension":{"en":"The outsourcing contract sets response times for employee payroll queries.","zh":"外包合同规定了回复员工薪资咨询的时限。"}},{"id":"HRV178-038","moduleId":"m8","module":"HR运营与数据分析","term":"Benchmarking","zh":"对标分析","definition":"与外部或内部参照对象比较指标和实践。","example":"We use benchmarking to compare our benefits with those offered by similar employers.","exampleZh":"我们通过对标分析，将公司的福利与同类雇主提供的福利进行比较。","collocation":"conduct benchmarking","collocationZh":"开展对标分析","dialogue":[{"role":"Benefits Manager","en":"That employer offers more leave, but its workforce is mostly office-based.","zh":"那家雇主的假期更长，但员工大多在办公室工作。"},{"role":"Rewards Analyst","en":"For the benchmarking exercise, let’s also include employers with a similar mix of office and shift workers.","zh":"做对标时，我们也纳入一些办公室员工和轮班员工比例相近的雇主。"}],"usage":"与外部或内部参照对象比较指标和实践。","new":true,"order":579,"aliases":[],"distinction":"Benchmarking 是选择参照对象并开展比较的过程。Benchmark 是用来比较的参考值或标准。Salary benchmarking 特指薪酬对标，通常需要匹配岗位职责、级别和劳动力市场。","ipaUK":"ˈbentʃˌmɑːkɪŋ","ipaUS":"ˈbentʃˌmɑːrkɪŋ","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/benchmarking","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Benchmarking","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How do we know whether our benefits are competitive?","zh":"我们如何判断福利是否具有竞争力？"},"extension":{"en":"Our benchmarking compares turnover across sites with similar headcounts and shift patterns.","zh":"我们的对标分析比较了人员规模和排班模式相近的各工作地点的离职率。"}},{"id":"HRV178-039","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Mergers and acquisitions (M&A)","zh":"兼并与收购（并购）","definition":"企业合并和收购交易的统称。人力资源工作可涉及交易前尽职调查、员工沟通和交易后的人员整合。","example":"HR supports workforce integration during mergers and acquisitions.","exampleZh":"HR在企业并购期间支持人员整合。","collocation":"support mergers and acquisitions","collocationZh":"支持企业并购","dialogue":[{"role":"Integration Lead","en":"People from both companies keep asking whether their reporting lines will change.","zh":"两家公司的员工都在问，汇报关系会不会变。"},{"role":"HR Director","en":"Let’s take that to the M&A team and agree on what we can communicate this week.","zh":"我们把这个问题带到并购团队，商定这周可以对员工说明哪些信息。"}],"usage":"企业合并与收购交易及相关整合活动。","new":true,"order":580,"aliases":[],"distinction":"Merger 指企业合并。Acquisition 指一方收购另一家企业、部分股权或资产等。Post-merger integration 指交易后的整合工作，也可用于收购后的整合语境。","ipaUK":"ˈmɜːdʒəz ən ˌækwɪˈzɪʃənz","ipaUS":"ˈmɝːdʒərz ən ˌækwəˈzɪʃənz","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Mergers and acquisitions. M and A","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"What is HR's role when two companies combine?","zh":"两家公司合并时HR承担什么职责？"},"extension":{"en":"The mergers and acquisitions team asked HR to estimate the cost of combining benefit plans.","zh":"并购团队请人力资源部门估算整合福利计划的成本。"}},{"id":"HRV178-040","moduleId":"m1","module":"招聘与人才获取","term":"Hiring","zh":"招聘／录用","definition":"招募并录用员工的过程。","example":"The company decided to freeze hiring for noncritical roles.","exampleZh":"公司决定暂停非关键岗位招聘。","collocation":"freeze hiring","collocationZh":"暂停招聘","dialogue":[{"role":"Finance Partner","en":"The new budget includes two analyst positions. When can interviews start?","zh":"新预算里有两个分析师岗位。什么时候能开始面试？"},{"role":"Hiring Manager","en":"I’ll confirm the hiring timeline once we’ve agreed on the job profiles.","zh":"等我们敲定岗位要求，我就确认招聘时间表。"}],"usage":"招募并录用员工的过程。","new":true,"order":581,"aliases":[],"distinction":"Hiring 可泛指招聘和录用，强调填补岗位。Recruiting 更常强调吸引、寻找和推进候选人，广义时与 hiring 重叠。Onboarding 侧重新员工入职后的融入安排。","ipaUK":"ˈhaɪərɪŋ","ipaUS":"ˈhaɪrɪŋ","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/hiring","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Hiring","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"What has the company decided about noncritical vacancies?","zh":"公司对非关键岗位空缺作出了什么决定？"},"extension":{"en":"The hiring team expects to fill two specialist roles by September.","zh":"招聘团队预计在九月前填补两个专业岗位。"}},{"id":"HRV178-041","moduleId":"m1","module":"招聘与人才获取","term":"Panel interview","zh":"多面试官面试","definition":"由多位面试官共同面试候选人的形式。","example":"The candidate will attend a panel interview tomorrow.","exampleZh":"候选人明天将参加多面试官面试。","collocation":"conduct a panel interview","collocationZh":"开展多面试官面试","dialogue":[{"role":"Hiring Manager","en":"Last time we all asked about the same project. Can we split up the questions?","zh":"上次大家都在问同一个项目。我们能把问题分一下吗？"},{"role":"Recruiter","en":"For the next panel interview, I’ll assign each interviewer a different competency to cover.","zh":"下次多面试官面试，我会给每位面试官分配一项不同的能力去考查。"}],"usage":"由多位面试官共同面试候选人的形式。","new":true,"order":582,"aliases":[],"distinction":"Panel interview 指多名面试官共同面试候选人的形式。Interview panel 指这组面试官。Group interview 常指多名候选人同时参加面试，具体用法可随机构而异。","ipaUK":"ˈpænəl ˈɪntəvjuː","ipaUS":"ˈpænəl ˈɪntərvjuː","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Panel interview","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"What's the next step for the candidate?","zh":"候选人的下一步流程是什么？"},"extension":{"en":"The panel interview includes a short case discussion with representatives from three departments.","zh":"多面试官面试包括一个简短的案例讨论，三个部门的代表会参加。"}},{"id":"HRV178-042","moduleId":"m1","module":"招聘与人才获取","term":"Make an offer","zh":"发出录用邀请","definition":"在招聘中，向候选人提出录用并告知相关条件，例如薪资或拟定的到岗日期。","example":"We plan to make an offer to the selected candidate next week.","exampleZh":"我们计划下周向选定的候选人发出录用邀请。","collocation":"make an offer to a candidate","collocationZh":"向候选人发出录用邀请","dialogue":[{"role":"Hiring Manager","en":"The finalist has another deadline on Thursday. Can we call her today?","zh":"最终候选人周四前要给另一家公司答复。我们今天能给她打电话吗？"},{"role":"Recruiter","en":"Yes. I’ll make her an offer by phone and send the written terms afterwards.","zh":"可以。我会先在电话里提出录用邀请，再把书面条款发给她。"}],"usage":"向候选人提出录用邀请。","new":true,"order":583,"aliases":[],"distinction":"Make an offer 指向候选人提出录用及相关条件，可先口头沟通。An offer letter 是书面录用通知。Accept an offer 指候选人接受录用条件。","ipaUK":"meɪk ən ˈɒfə","ipaUS":"meɪk ən ˈɔːfər","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Make an offer","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"When do we expect to make an offer to the selected candidate?","zh":"我们预计何时向选定的候选人发出录用邀请？"},"extension":{"en":"We need the salary range approved before we can make an offer.","zh":"薪资范围获批后，我们才能发出录用邀请。"}},{"id":"HRV178-043","moduleId":"m6","module":"员工关系与劳动合规","term":"Put in your notice","zh":"正式提出离职／提交离职通知","definition":"正式告知雇主自己将离职。","example":"I plan to put in my notice next week.","exampleZh":"我计划下周正式提出离职。","collocation":"put in your notice","collocationZh":"向雇主提交辞职通知","dialogue":[{"role":"Employee","en":"I put in my notice yesterday. Should I tell the project team myself?","zh":"我昨天提交了辞职通知。要我自己告诉项目组吗？"},{"role":"Manager","en":"Let’s tell them together at tomorrow’s stand-up so we can explain the handover.","zh":"我们在明天的站会上一起告诉大家，也好说明怎么交接。"}],"usage":"正式告知雇主自己将离职。","new":true,"order":584,"aliases":["Give notice"],"distinction":"Put in your notice 是日常职场用语，强调向雇主发出辞职通知。Submit your resignation 语气更正式，适合书面沟通。Notice period 指通知发出后到雇佣关系结束之间的通知期，具体计算依适用条款和规则而定。","ipaUK":"pʊt ɪn jɔː ˈnəʊtɪs","ipaUS":"pʊt ɪn jʊr ˈnoʊtɪs","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Put in your notice","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"When do you intend to tell your manager you're leaving?","zh":"你打算什么时候告诉经理你要离职？"},"extension":{"en":"Maya put in her notice and offered to train her replacement.","zh":"玛雅提交了辞职通知，并主动提出培训接替她的人。"}},{"id":"HRV178-044","moduleId":"m6","module":"员工关系与劳动合规","term":"Last working day","zh":"最后工作日","definition":"员工实际工作的最后一天，可能不同于雇佣关系终止日。","example":"HR will confirm your last working day in writing.","exampleZh":"HR将以书面形式确认你的最后工作日。","collocation":"confirm the last working day","collocationZh":"确认最后工作日","dialogue":[{"role":"Departing Employee","en":"My last working day is Friday, but I’m on leave until my contract ends. Who will cover the Monday client call?","zh":"周五是我的最后工作日，之后我会休假到合同结束。下周一的客户会议由谁来接手？"},{"role":"Manager","en":"Priya will. Please introduce her to the client before you go on leave.","zh":"普里娅来接手。请在休假前把她介绍给客户。"}],"usage":"员工实际工作的最后一天，可能不同于雇佣关系终止日。","new":true,"order":585,"aliases":[],"distinction":"Last working day 指实际工作的最后一天，适合安排交接。Employment end date 指雇佣关系正式结束的日期。休假或免到岗等安排可能使两者落在不同日期。","ipaUK":"lɑːst ˈwɜːkɪŋ deɪ","ipaUS":"læst ˈwɝːkɪŋ deɪ","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Last working day","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How will I know my final date at work?","zh":"我如何确认自己的最后工作日？"},"extension":{"en":"Please return your access badge by the end of your last working day.","zh":"请在最后工作日结束前归还门禁卡。"}},{"id":"HRV178-045","moduleId":"m1","module":"招聘与人才获取","term":"Backfill","zh":"补招／填补空缺岗位","definition":"为既有岗位因调动、离职或休假等产生的空缺安排人员，可为临时或长期补位。","example":"We need approval to backfill this role, either through an internal transfer or external recruitment.","exampleZh":"我们需要获得审批，通过内部调动或外部招聘填补该岗位空缺。","collocation":"backfill a role","collocationZh":"填补岗位空缺","dialogue":[{"role":"Operations Director","en":"If Sam moves to the launch team, who’ll handle the supplier audits?","zh":"如果萨姆调到上线团队，供应商审计由谁负责？"},{"role":"HR Business Partner","en":"We can backfill his role with an internal candidate while he’s on the project.","zh":"他参与项目期间，我们可以安排一位内部人选补上他的岗位。"}],"usage":"补招或安排人员填补现有岗位空缺。","new":true,"order":586,"aliases":[],"distinction":"Backfill a role 指为既有岗位空缺补位，可通过内部调配或外部招聘。Add headcount 指增加人员编制。Backfill 也可作名词，指补位人选或补位安排。","ipaUK":"ˈbækfɪl","ipaUS":"ˈbækfɪl","ipaSource":"https://dictionary.cambridge.org/us/pronunciation/english/backfill","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Backfill","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Can we fill the vacancy left by the employee who just resigned?","zh":"我们可以填补刚辞职员工留下的岗位空缺吗？"},"extension":{"en":"We’ll backfill the analyst role for six months while its current holder is on leave.","zh":"现任分析师休假期间，我们会为该岗位安排六个月的临时补位。"}},{"id":"HRV178-046","moduleId":"m3","module":"绩效管理","term":"Align on goals","zh":"就目标达成一致","definition":"就目标达成共同理解和一致意见。","example":"Let's align on goals before the next review cycle.","exampleZh":"我们在下一轮评估周期开始前先就目标达成一致吧。","collocation":"align on goals with the team","collocationZh":"与团队就目标达成一致","dialogue":[{"role":"Product Lead","en":"I’m aiming for a May launch, but Support wants a smaller pilot first.","zh":"我想在五月上线，但客服团队希望先做一次规模更小的试点。"},{"role":"Program Manager","en":"Let’s align on goals for the pilot before we commit to a launch date.","zh":"在承诺上线日期前，我们先就试点目标达成一致。"}],"usage":"就目标达成共同理解和一致意见。","new":true,"order":587,"aliases":[],"distinction":"Align on goals 强调各方就要实现的目标达成一致。Align goals with strategy 强调让目标符合战略方向。前者常与人或团队搭配，后者把目标和方向联系起来。","ipaUK":"əˈlaɪn ɒn ɡəʊlz","ipaUS":"əˈlaɪn ɑːn ɡoʊlz","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Align on goals","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"What should we do before the next review cycle?","zh":"下一轮评估周期开始前我们应该做什么？"},"extension":{"en":"Sales and Operations need to align on goals before they agree on the launch budget.","zh":"销售和运营需要先就目标达成一致，再商定上线预算。"}},{"id":"HRV178-047","moduleId":"m3","module":"绩效管理","term":"Goals","zh":"目标","definition":"希望在一定时期内实现的工作结果。","example":"Managers should set measurable goals with employees.","exampleZh":"管理者应与员工共同设定可衡量的目标。","collocation":"set measurable goals","collocationZh":"设定可衡量的目标","dialogue":[{"role":"Employee","en":"My draft says “run a weekly team meeting.” Does that work as a goal?","zh":"我在草案里写了“每周开一次团队会”。这能算目标吗？"},{"role":"Manager","en":"That’s a good action. For the goal, tell me what you want the meetings to achieve.","zh":"这是个不错的行动安排。至于目标，你希望通过这些会议实现什么？"}],"usage":"希望在一定时期内实现的工作结果。","new":true,"order":588,"aliases":[],"distinction":"Goals 指要达成的结果。Tasks 是为实现目标而采取的行动。KPIs 是跟踪表现的关键指标，同一个指标可用来衡量某个目标达成得如何。","ipaUK":"ɡəʊlz","ipaUS":"ɡoʊlz","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Goals","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How can managers make performance expectations clearer?","zh":"管理者如何让绩效要求更明确？"},"extension":{"en":"One of our goals is to resolve 90 percent of support tickets within two business days.","zh":"我们的目标之一是在两个工作日内解决 90% 的支持工单。"}},{"id":"HRV178-048","moduleId":"m10","module":"HR商务沟通与汇报","term":"Push back","zh":"提出异议／表达反对意见","definition":"对提议或要求提出异议或质疑。","example":"We should push back on unrealistic deadlines and suggest alternatives.","exampleZh":"我们应对不切实际的截止日期提出异议，并建议替代方案。","collocation":"push back on a proposal","collocationZh":"对提案提出异议","dialogue":[{"role":"Project Lead","en":"Finance wants the figures by noon, but the regional totals are still unverified.","zh":"财务希望中午前拿到数据，可各区域的汇总数还没核实。"},{"role":"HR Analyst","en":"I’ll push back on the noon deadline and offer to send the verified figures by three.","zh":"我会对中午的截止时间提出异议，建议三点前发送核实后的数据。"}],"usage":"对提议或要求提出异议或质疑。","new":true,"order":589,"aliases":[],"distinction":"Push back on 指对提议、要求或决定提出异议，语气通常比 reject 更适合商谈。Reject 表示明确拒绝。Push back the deadline 中 push back 表示推迟截止日期。","ipaUK":"pʊʃ ˈbæk","ipaUS":"pʊʃ ˈbæk","ipaSource":"英美音标文本复核（非真人试听）","ipaReview":"继承既有记音，本轮未核对完整词头","ipaNote":"既有教学记音，本轮未核对完整词头。朗读使用设备语音。","speakTerm":"Push back","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"How should we respond to the proposed deadlines?","zh":"我们应该如何回应拟定的截止日期？"},"extension":{"en":"The HR team pushed back on the proposal to shorten the consultation period.","zh":"人力资源团队对缩短征询意见期限的提案提出了异议。"}},{"id":"HRV180-001","moduleId":"m9","module":"海外派遣与全球流动","term":"Assignment policy","zh":"海外派遣政策","definition":"机构管理跨境员工派遣的内部规则，通常规定派遣类型、适用资格、审批流程和支持项目。","example":"HR checks the assignment policy before confirming an assignee’s relocation benefits.","exampleZh":"人力资源部门在确认派遣员工的搬迁福利前，会查阅海外派遣政策。","collocation":"check the assignment policy","collocationZh":"查阅海外派遣政策","dialogue":[{"role":"Mobility Coordinator","en":"He’ll be in Seoul for four months. Can we book a serviced apartment?","zh":"他要去首尔四个月。我们可以订服务式公寓吗？"},{"role":"Mobility Manager","en":"Check the assignment policy for short stays before you make the booking.","zh":"预订前先查一下海外派遣政策里对短期停留的规定。"}],"usage":"","new":true,"order":590,"aliases":[],"distinction":"Assignment policy 是机构层面的派遣规则，规定适用对象、审批和支持范围。Assignment letter 记录某次派遣的具体条款，例如派遣地点、日期及津贴。","ipaUK":"","ipaUS":"","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/assignment","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Assignment policy","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We need to check the assignment policy.","zh":"我们需要查阅派遣政策。"},"extension":{"en":"The assignment policy sets different housing limits for different locations.","zh":"海外派遣政策按派遣地点设定不同的住房支持上限。"}},{"id":"HRV180-002","moduleId":"m9","module":"海外派遣与全球流动","term":"Assignment duration","zh":"派遣期限","definition":"员工被派往某地或承担指定职责的时长，通常按约定起止日期计算。","example":"The assignment duration is twelve months, starting in April.","exampleZh":"派遣期限为十二个月，从四月开始。","collocation":"confirm the assignment duration","collocationZh":"确认派遣期限","dialogue":[{"role":"Host Manager","en":"Six months may be too short if the local team has to take over the whole process.","zh":"如果当地团队要接手整个流程，六个月可能不够。"},{"role":"Mobility Adviser","en":"Let’s use the handover milestones to agree on an assignment duration before you make an offer.","zh":"我们先按交接里程碑商定派遣期限，再向员工提出派遣安排。"}],"usage":"","new":true,"order":591,"aliases":[],"distinction":"Assignment duration 指派遣持续的时间。Assignment end date 指派遣结束的具体日期。Assignment extension 指延长派遣的安排，可能改变时长和结束日期。","ipaUK":"","ipaUS":"","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/assignment","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Assignment duration","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We need approval to extend the assignment duration.","zh":"我们需要获得延长派遣期限的批准。"},"extension":{"en":"The assignment duration affects which relocation benefits our policy provides.","zh":"派遣期限会影响员工依据公司政策可以获得哪些搬迁福利。"}},{"id":"HRV180-003","moduleId":"m9","module":"海外派遣与全球流动","term":"Pre-departure briefing","zh":"派遣前说明会","definition":"员工赴接收地前举行的说明会，通常介绍出行、安置、准备事项及当地联系人。","example":"The pre-departure briefing covers health and safety guidance for the host location.","exampleZh":"派遣前说明会将介绍接收地的健康与安全指引。","collocation":"conduct a pre-departure briefing","collocationZh":"开展派遣前说明会","dialogue":[{"role":"Assignee","en":"I’m flying out next week, and I’m unsure whom to call if the accommodation falls through.","zh":"我下周飞过去，如果住宿临时出了问题，我还不知道该联系谁。"},{"role":"Mobility Coordinator","en":"I’ll go over the emergency contacts at your pre-departure briefing and email you the list today.","zh":"我会在派遣前说明会上和你过一遍紧急联系人，今天也会把名单邮件发给你。"}],"usage":"","new":true,"order":592,"aliases":[],"distinction":"Pre-departure briefing 在赴任出发前说明行程、准备事项和联系人。Post-arrival orientation 在抵达后帮助员工熟悉当地工作和生活环境。","ipaUK":"","ipaUS":"","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/briefing","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Pre-departure briefing","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"During the pre-departure briefing.","zh":"在派遣前说明会上。"},"extension":{"en":"Bring your travel itinerary to the pre-departure briefing so we can check the airport pickup.","zh":"请带着行程单参加派遣前说明会，方便我们核对接机安排。"}},{"id":"HRV180-004","moduleId":"m9","module":"海外派遣与全球流动","term":"Post-arrival orientation","zh":"抵达后适应培训","definition":"员工抵达派遣接收地后参加的介绍和适应活动，内容可包括当地办公流程、工作场所和生活信息。","example":"The host office arranges post-arrival orientation for assignees.","exampleZh":"接收地办公室为派遣员工安排抵达后适应培训。","collocation":"arrange post-arrival orientation","collocationZh":"安排抵达后适应培训","dialogue":[{"role":"Assignee","en":"I picked up my badge yesterday, but I still don’t know how the shuttle works.","zh":"我昨天拿到了门禁卡，可还是不清楚怎么坐班车。"},{"role":"Host HR Adviser","en":"I’ll bring the shuttle timetable to your post-arrival orientation tomorrow.","zh":"明天做抵达后适应培训时，我会把班车时刻表带给你。"}],"usage":"","new":true,"order":593,"aliases":[],"distinction":"Post-arrival orientation 指派遣员工抵达接收地后的适应培训。New-hire orientation 面向新入职员工。原已在本机构任职的员工到新地点赴任后，也可能参加抵达后的适应培训。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Post-arrival orientation","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"The host HR team will arrange post-arrival orientation.","zh":"东道国HR团队会安排抵达后适应培训。"},"extension":{"en":"Post-arrival orientation includes a tour of the site and an introduction to the local support team.","zh":"抵达后适应培训包括参观工作场所，以及认识当地的支持团队。"}},{"id":"HRV180-005","moduleId":"m9","module":"海外派遣与全球流动","term":"Accompanied assignment","zh":"家属随行派遣","definition":"机构安排员工赴接收地任职，并允许符合条件的家属随同迁居。实际迁居须符合适用的入境及居留规定。","example":"Family benefits depend on the terms of the accompanied assignment.","exampleZh":"家属可享受哪些福利，取决于家属随行派遣的具体条款。","collocation":"approve an accompanied assignment","collocationZh":"批准家属随行派遣","dialogue":[{"role":"Assignee","en":"My partner would like to join me after the first month. Can the assignment be accompanied from that point?","zh":"我伴侣想等我过去一个月后再来会合。到那时可以改为家属随行派遣吗？"},{"role":"Mobility Adviser","en":"Let’s check whether the policy allows the change and what entry documents your partner would need.","zh":"我们先确认政策是否允许变更，再看看你的伴侣需要办理哪些入境文件。"}],"usage":"","new":true,"order":594,"aliases":[],"distinction":"Accompanied assignment 指符合条件的家属随员工在接收地居住的派遣安排。Unaccompanied assignment 指员工赴任而家属留在原居住地的安排。家属资格、许可及支持范围须按当地规定和机构政策确认。","ipaUK":"","ipaUS":"","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/assignment","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Accompanied assignment","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"She has requested an accompanied assignment, but the arrangements are not final.","zh":"她已申请家属随行派遣，但安排尚未最终确定。"},"extension":{"en":"We’re checking school availability before confirming the accompanied assignment.","zh":"确认家属随行派遣安排前，我们正在了解当地学校是否有学位。"}},{"id":"HRV180-006","moduleId":"m9","module":"海外派遣与全球流动","term":"Unaccompanied assignment","zh":"家属不随行派遣","definition":"员工赴接收地任职、家属不随同迁居的派遣安排。探亲和家属支持视具体条款而定。","example":"He opted for an unaccompanied assignment lasting one year.","exampleZh":"他选择了一年期的家属不随行派遣。","collocation":"undertake an unaccompanied assignment","collocationZh":"接受家属不随行派遣","dialogue":[{"role":"Assignee","en":"My family will stay in Madrid. Could I switch to a smaller apartment at the host site?","zh":"我家里人会留在马德里。我能在派遣地换一套小一点的公寓吗？"},{"role":"Mobility Coordinator","en":"Let’s check the housing budget for an unaccompanied assignment before we confirm the lease.","zh":"确认租约前，我们先查一下家属不随行派遣的住房预算。"}],"usage":"","new":true,"order":595,"aliases":[],"distinction":"Unaccompanied assignment 通常指员工赴任而家属留在原居住地的派遣安排。Unaccompanied 强调家属是否随迁。Short-term assignment 强调派遣期限，短期派遣也可能有家属随行。","ipaUK":"","ipaUS":"","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/assignment","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Unaccompanied assignment","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"No, this is an unaccompanied assignment.","zh":"不会，这是家属不随行派遣。"},"extension":{"en":"The unaccompanied assignment package includes two trips home under our policy.","zh":"按公司政策，这项家属不随行派遣安排包含两次探亲返程。"}},{"id":"HRV180-007","moduleId":"m9","module":"海外派遣与全球流动","term":"Commuter assignment","zh":"跨境通勤式派遣","definition":"跨境派遣的一种安排。员工通常保留原居住地，按约定频率往返原居住地与另一国家或地区的工作地点。","example":"We’re considering a commuter assignment to cover two sites on either side of the border.","exampleZh":"我们正在考虑采用跨境通勤式派遣，为边境两侧的工作地点提供支持。","collocation":"arrange a commuter assignment","collocationZh":"安排跨境通勤式派遣","dialogue":[{"role":"Project Lead","en":"Can Ana stay based in Geneva and come to the French site every Tuesday and Wednesday?","zh":"安娜能继续住在日内瓦，每周二、周三到法国的工作地点上班吗？"},{"role":"Mobility Adviser","en":"That could work as a commuter assignment. I’ll have our advisers check the proposed schedule before we confirm it.","zh":"可以考虑跨境通勤式派遣。在敲定前，我会请顾问审查拟定的往返安排。"}],"usage":"","new":true,"order":596,"aliases":[],"distinction":"Commuter assignment 关注员工在原居住地与跨境工作地点之间定期往返。Short-term assignment 关注派遣期限。短期派遣也可采用跨境通勤安排。出入境、税务和社保要求须结合具体安排评估。","ipaUK":"","ipaUS":"","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/assignment","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Commuter assignment","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Not necessarily. We are considering a commuter assignment.","zh":"不一定，我们正在考虑跨境通勤式派遣。"},"extension":{"en":"The commuter assignment involves three days a week at the Lyon office.","zh":"这项跨境通勤式派遣要求员工每周在里昂办公室工作三天。"}},{"id":"HRV180-008","moduleId":"m9","module":"海外派遣与全球流动","term":"Home-country payroll","zh":"派出国薪资发放","definition":"派出国的薪资处理和发放安排。Home country 在这里指派出国，员工的国籍可能不同。","example":"The employee remains on the home-country payroll during the assignment.","exampleZh":"派遣期间，该员工继续由派出国发薪。","collocation":"remain on the home-country payroll","collocationZh":"继续由派出国发薪","dialogue":[{"role":"Assignee","en":"If I stay on the home-country payroll, can my salary still go into the same account?","zh":"如果继续由派出国发薪，工资还能打到原来的账户吗？"},{"role":"Payroll Specialist","en":"Send me your assignment reference. I’ll check which payment instructions are on file.","zh":"把你的派遣编号发给我。我查一下系统里登记的收款信息。"}],"usage":"","new":true,"order":597,"aliases":[],"distinction":"Home-country payroll 指在派出国处理薪资。Host-country payroll 指在接收国处理薪资。发薪安排本身无法确定税务居民身份、代扣义务或社保适用地。","ipaUK":"","ipaUS":"","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/payroll","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Home-country payroll","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"He will remain on home-country payroll.","zh":"他将继续由派出国薪资系统发薪。"},"extension":{"en":"Employees can download their payslips from the home-country payroll portal.","zh":"员工可以从派出国的薪资平台下载工资单。"}},{"id":"HRV180-009","moduleId":"m9","module":"海外派遣与全球流动","term":"Tax briefing","zh":"税务说明会","definition":"向派遣员工介绍可能涉及的纳税、申报和记录要求的说明会，内容随涉及的司法辖区及个人情况而异。","example":"We schedule a tax briefing to explain potential filing obligations.","exampleZh":"我们安排税务说明会，解释员工可能涉及的纳税申报义务。","collocation":"schedule a tax briefing","collocationZh":"安排税务说明会","dialogue":[{"role":"Assignee","en":"My start date in Singapore moved to June. Should I mention that to the tax adviser?","zh":"我去新加坡的到岗日期改到了六月。需要跟税务顾问提一下吗？"},{"role":"Mobility Coordinator","en":"Yes. Bring your updated travel dates to the tax briefing so the adviser can explain what the change might affect.","zh":"需要。参加税务说明会时带上更新后的出行日期，顾问可以说明日期变动可能有哪些影响。"}],"usage":"","new":true,"order":598,"aliases":[],"distinction":"Tax briefing 介绍派遣可能涉及的税务义务、时间安排或记录要求。Tax return preparation 指收集资料和准备具体申报表。个案义务须结合适用规则与个人情况判断。","ipaUK":"","ipaUS":"","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/briefing","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Tax briefing","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We will arrange a tax briefing with an adviser.","zh":"我们会安排税务顾问开展说明会。"},"extension":{"en":"At the tax briefing, the adviser explained which travel records the employee should keep.","zh":"税务顾问在税务说明会上解释了这名员工应保留哪些出行记录。"}},{"id":"HRV180-010","moduleId":"m9","module":"海外派遣与全球流动","term":"Tax return preparation","zh":"纳税申报准备","definition":"为提交纳税申报表而收集资料、核算相关信息并编制申报表的过程。适用材料和程序取决于司法辖区及个案。","example":"The tax adviser assists eligible assignees with tax return preparation.","exampleZh":"税务顾问协助符合条件的派遣员工准备纳税申报材料。","collocation":"assist with tax return preparation","collocationZh":"协助准备纳税申报","dialogue":[{"role":"Assignee","en":"I’ve uploaded the documents for tax return preparation. Will the adviser file the return for me as well?","zh":"我已经上传了准备纳税申报所需的资料。顾问还会帮我提交申报表吗？"},{"role":"Mobility Coordinator","en":"I’ll check the scope of your service. In the meantime, look out for the adviser’s request to review the draft.","zh":"我会确认你可使用的服务范围。你先留意顾问发来的申报表草稿核对通知。"}],"usage":"","new":true,"order":599,"aliases":[],"distinction":"Tax return preparation 指收集资料、核算信息并准备申报表。Tax filing 指向税务机关提交申报。两者可以由不同人员负责，具体服务范围以委托安排为准。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Tax return preparation","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Our tax adviser can assist with tax return preparation.","zh":"我们的税务顾问可以协助准备纳税申报。"},"extension":{"en":"Accurate travel records can help the adviser with tax return preparation.","zh":"准确的出行记录有助于税务顾问准备纳税申报材料。"}},{"id":"HRV180-011","moduleId":"m9","module":"海外派遣与全球流动","term":"Immigration counsel","zh":"移民事务法律顾问","definition":"就签证、居留身份或工作许可等事项提供法律意见的移民事务专业法律顾问。执业资格及服务范围依当地规则而定。","example":"HR consults immigration counsel before confirming the start date.","exampleZh":"人力资源部门在确认到岗日期前会咨询移民事务法律顾问。","collocation":"consult immigration counsel","collocationZh":"咨询移民事务法律顾问","dialogue":[{"role":"Host Manager","en":"We’re moving her to a different site partway through the assignment. Do we need to report the change?","zh":"我们打算在派遣期间把她调到另一个工作地点。这项变动需要申报吗？"},{"role":"Mobility Adviser","en":"I’ll send the new address and duties to immigration counsel so they can check what’s required.","zh":"我会把新的工作地址和职责发给移民事务法律顾问，请他们核对有何要求。"}],"usage":"","new":true,"order":600,"aliases":[],"distinction":"Immigration counsel 是就签证、居留或工作许可等事项提供法律意见的专业顾问。Relocation vendor 通常负责搬迁等实务服务。由谁提供移民法律意见，须按适用司法辖区的专业资格规则确认。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Immigration counsel","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We should consult immigration counsel first.","zh":"我们应该先咨询移民事务法律顾问。"},"extension":{"en":"Immigration counsel asked for an updated description of the employee’s duties.","zh":"移民事务法律顾问要求提供一份更新后的员工岗位职责说明。"}},{"id":"HRV180-012","moduleId":"m9","module":"海外派遣与全球流动","term":"Relocation vendor","zh":"搬迁服务供应商","definition":"受企业或员工委托，提供跨地区搬迁服务的外部供应商。","example":"Procurement and HR jointly select a relocation vendor.","exampleZh":"采购部门与HR共同选择搬迁服务供应商。","collocation":"select a relocation vendor","collocationZh":"选择搬迁服务供应商","dialogue":[{"role":"Mobility Lead","en":"Who will coordinate the international move?","zh":"谁负责协调国际搬迁？"},{"role":"HRBP","en":"Our relocation vendor will coordinate it.","zh":"我们的搬迁服务供应商会负责协调。"}],"usage":"","new":true,"order":601,"aliases":[],"distinction":"Relocation vendor 指承接搬迁服务的外部机构。Moving company 通常以打包和运输为主，而 relocation vendor 也可能协助找房或安排落地服务。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Relocation vendor","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Our relocation vendor will coordinate it.","zh":"我们的搬迁服务供应商会负责协调。"},"extension":{"en":"Please ask the relocation vendor for an itemized quote.","zh":"请向搬迁服务供应商索取明细报价。"}},{"id":"HRV180-013","moduleId":"m9","module":"海外派遣与全球流动","term":"Temporary accommodation","zh":"临时住宿","definition":"员工在正式入住前，或在短期派遣期间使用的过渡性住所。","example":"The mobility team books temporary accommodation for eligible assignees.","exampleZh":"全球人才流动团队为符合条件的外派员工预订临时住宿。","collocation":"book temporary accommodation","collocationZh":"预订临时住宿","dialogue":[{"role":"Assignee","en":"Where will I stay before finding an apartment?","zh":"找到公寓前我住在哪里？"},{"role":"Mobility Adviser","en":"We can arrange temporary accommodation under the policy.","zh":"我们可以按政策安排临时住宿。"}],"usage":"","new":true,"order":602,"aliases":[],"distinction":"Temporary accommodation 强调住所的临时用途。Housing allowance 指一笔住房津贴，其适用期限及金额由政策规定。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Temporary accommodation","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We can arrange temporary accommodation under the policy.","zh":"我们可以按政策安排临时住宿。"},"extension":{"en":"Can I extend my temporary accommodation by a week?","zh":"我的临时住宿可以延长一周吗？"}},{"id":"HRV180-014","moduleId":"m9","module":"海外派遣与全球流动","term":"Household goods shipment","zh":"家庭物品运输","definition":"员工搬迁时将家具和个人生活用品运往目的地的服务或安排。","example":"The vendor coordinates the shipment of household goods and prepares customs documentation.","exampleZh":"供应商协调家庭物品运输并准备海关申报文件。","collocation":"coordinate household goods shipment","collocationZh":"协调家庭物品运输","dialogue":[{"role":"Assignee","en":"Who will arrange the shipment of our furniture?","zh":"谁负责安排家具运输？"},{"role":"Move Coordinator","en":"The vendor handles household goods shipment.","zh":"供应商负责家庭物品运输。"}],"usage":"","new":true,"order":603,"aliases":[],"distinction":"Household goods shipment 指家庭物品运输。Excess baggage 通常指旅客随行但超过免费额度的行李。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Household goods shipment","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"The vendor handles household goods shipment.","zh":"供应商负责家庭物品运输。"},"extension":{"en":"Does the policy cover storage before the household goods shipment leaves?","zh":"政策涵盖家庭物品起运前的仓储费用吗？"}},{"id":"HRV180-015","moduleId":"m9","module":"海外派遣与全球流动","term":"Repatriation planning","zh":"回任规划","definition":"预先安排派遣员工返回原工作地或派出单位，以及回任后岗位衔接和重新融入的过程。","example":"HR starts repatriation planning before the overseas assignment ends.","exampleZh":"人力资源部门在海外派遣结束前着手制定回任计划。","collocation":"start repatriation planning","collocationZh":"启动回任规划","dialogue":[{"role":"HRBP","en":"When should we discuss her next role?","zh":"我们应该什么时候讨论她的下一岗位？"},{"role":"Line Manager","en":"We should start repatriation planning now.","zh":"我们现在就应该启动回任规划。"}],"usage":"","new":true,"order":604,"aliases":[],"distinction":"Repatriation planning 关注海外派遣结束后的回归与衔接。Relocation planning 关注人员及物品搬迁，也可用于派遣开始时。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Repatriation planning","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We should start repatriation planning now.","zh":"我们现在就应该启动回任规划。"},"extension":{"en":"Please include a handover meeting in the repatriation plan.","zh":"请在回任计划中安排一次交接会议。"}},{"id":"HRV180-016","moduleId":"m2","module":"薪酬激励与福利","term":"Pay mix","zh":"薪酬组合","definition":"基本薪资和浮动薪酬等组成部分在某一薪酬口径中的比例配置。","example":"We increased the variable pay component of the pay mix for sales roles.","exampleZh":"我们提高了销售岗位薪酬组合中浮动薪酬的占比。","collocation":"adjust the pay mix","collocationZh":"调整薪酬组合","dialogue":[{"role":"Sales Director","en":"Could we offer a higher base salary for this sales role?","zh":"这个销售岗位的基本薪资可以定高一点吗？"},{"role":"Rewards Partner","en":"Possibly. We’d need to review the pay mix and the target commission together.","zh":"有可能。我们得把薪酬组合和目标提成放在一起重新考虑。"}],"usage":"","new":true,"order":605,"aliases":[],"distinction":"Pay mix 强调各项薪酬的占比，例如固定薪资占目标现金薪酬的七成。Total cash compensation 强调现金薪酬总额。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Pay mix","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Why are we reviewing the pay mix?","zh":"为什么要审查薪酬组合？"},"extension":{"en":"What pay mix would make the role competitive without raising target total cash compensation?","zh":"怎样设置薪酬组合，才能在提高岗位吸引力的同时保持目标现金薪酬总额？"}},{"id":"HRV180-017","moduleId":"m2","module":"薪酬激励与福利","term":"Salary range penetration","zh":"薪酬区间渗透率","definition":"衡量实际薪资在指定薪资区间内的相对位置，通常按（实际薪资－区间下限）÷（区间上限－区间下限）计算，区间宽度须大于零。","example":"Her salary range penetration is 50 percent because her salary is halfway between the range minimum and maximum.","exampleZh":"她的工资处于区间最低值与最高值的正中间，因此区间渗透率为50%。","collocation":"calculate salary range penetration","collocationZh":"计算薪酬区间渗透率","dialogue":[{"role":"Manager","en":"Which number shows how far Ana has moved through her salary range?","zh":"哪个数值能反映安娜的工资在区间里走到了什么位置？"},{"role":"Rewards Analyst","en":"Check her salary range penetration. A value of zero puts her at the range minimum.","zh":"看她的薪酬区间渗透率。数值为零就表示她的薪资正好在区间下限。"}],"usage":"","new":true,"order":606,"aliases":[],"distinction":"Range penetration 以区间下限为起点衡量位置。Compa-ratio 以区间中点为分母，所以处于中点时两项指标通常分别为 50% 和 100%。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Salary range penetration","collocationReview":"V18.2 模型编辑复核","comparison":[{"term":"Salary band","note":"岗位或等级对应的薪资区间。","relation":"易混淆"},{"term":"Pay grade","note":"薪酬等级，通常关联一个薪资区间。","relation":"易混淆"},{"term":"Pay range midpoint","note":"薪资区间中点。","relation":"易混淆"},{"term":"Compa-ratio","note":"实际薪资除以区间中点。","relation":"易混淆"},{"term":"Salary range penetration","note":"实际薪资减区间最低值，再除以区间宽度。","relation":"本词"},{"term":"Broadbanding","note":"将多个窄薪资等级合并为宽薪资带。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Is range penetration the same as compa-ratio?","zh":"区间渗透率与薪酬比较率相同吗？"},"extension":{"en":"With her salary below the unchanged range maximum, raising the minimum reduced her salary range penetration.","zh":"她的薪资低于保持不变的区间上限，因此调高区间下限后，她的薪酬区间渗透率下降了。"}},{"id":"HRV180-018","moduleId":"m2","module":"薪酬激励与福利","term":"Broadbanding","zh":"宽带薪酬","definition":"把多个较窄的薪级合并为数量更少、跨度更大的薪酬带的薪酬结构设计方式。","example":"After introducing broadbanding, the company went from twelve pay grades to four broad bands.","exampleZh":"采用宽带薪酬后，公司把原来的十二个薪级合并为四个宽薪酬带。","collocation":"introduce broadbanding","collocationZh":"引入宽带薪酬","dialogue":[{"role":"HR Director","en":"Why are we consolidating salary grades?","zh":"为什么要合并薪级？"},{"role":"Rewards Partner","en":"Broadbanding can give us more flexibility in managing pay.","zh":"宽带薪酬可以提高薪酬管理的灵活性。"}],"usage":"","new":true,"order":607,"aliases":[],"distinction":"Broadbanding 涉及合并较窄的薪级。Widening a salary range 指扩大某个薪资区间的跨度，可以在保留原有薪级数量的情况下进行。","ipaUK":"ˈbrɔːdbændɪŋ","ipaUS":"ˈbrɔːdbændɪŋ","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/broadbanding","ipaReview":"完整词头英美音标文本核对","ipaNote":"英美音标据 Cambridge 发音词头核对。朗读使用设备语音。","speakTerm":"Broadbanding","collocationReview":"V18.2 模型编辑复核","comparison":[{"term":"Salary band","note":"岗位或等级对应的薪资区间。","relation":"易混淆"},{"term":"Pay grade","note":"薪酬等级，通常关联一个薪资区间。","relation":"易混淆"},{"term":"Pay range midpoint","note":"薪资区间中点。","relation":"易混淆"},{"term":"Compa-ratio","note":"实际薪资除以区间中点。","relation":"易混淆"},{"term":"Salary range penetration","note":"实际薪资减区间最低值，再除以区间宽度。","relation":"易混淆"},{"term":"Broadbanding","note":"将多个窄薪资等级合并为宽薪资带。","relation":"本词"}],"legacyDialogueBookmark":{"en":"Broadbanding can give us more flexibility in managing pay.","zh":"宽带薪酬可以提高薪酬管理的灵活性。"},"extension":{"en":"Before adopting broadbanding, we should agree on how to manage pay differences within each band.","zh":"采用宽带薪酬前，我们应先商定如何管理同一薪酬带内的薪资差异。"}},{"id":"HRV180-019","moduleId":"m2","module":"薪酬激励与福利","term":"Pay progression","zh":"薪酬增长／薪酬增长机制","definition":"员工的薪资在既定薪酬框架内随时间上升的过程，或管理这一过程的规则。","example":"Pay progression may depend on skills, performance or time in the role.","exampleZh":"薪酬增长可能取决于技能、绩效或任职时间。","collocation":"define pay progression criteria","collocationZh":"明确薪酬增长标准","dialogue":[{"role":"Employee","en":"Does moving through the pay range require a promotion?","zh":"在薪酬区间内提高工资需要晋升吗？"},{"role":"HR Partner","en":"Not necessarily. Our pay progression rules allow increases within the same grade.","zh":"不一定。我们的薪酬增长规则允许在同一薪级内加薪。"}],"usage":"","new":true,"order":608,"aliases":[],"distinction":"Pay progression 可在同一薪级内发生。Promotion increase 指因晋升发生的薪资调整。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Pay progression","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Not necessarily. Our pay progression rules allow increases within the same grade.","zh":"不一定。我们的薪酬增长规则允许在同一薪级内加薪。"},"extension":{"en":"The handbook explains how employees qualify for pay progression within their grade.","zh":"员工手册说明了员工如何达到本薪级内的加薪条件。"}},{"id":"HRV180-020","moduleId":"m2","module":"薪酬激励与福利","term":"Market pricing","zh":"市场薪酬定价","definition":"将本企业岗位与外部调查中的可比岗位匹配，并参考外部薪酬数据为本企业岗位设定有竞争力的薪酬水平。","example":"We use market pricing to establish competitive pay ranges for comparable jobs.","exampleZh":"我们通过市场薪酬定价为可比岗位制定具有竞争力的薪酬区间。","collocation":"conduct market pricing","collocationZh":"开展市场薪酬定价","dialogue":[{"role":"Hiring Manager","en":"Can we use jobs with the same title for market pricing?","zh":"做市场薪酬定价时，可以直接比较名称相同的岗位吗？"},{"role":"Compensation Partner","en":"Only if the responsibilities are comparable. The title alone is a poor guide.","zh":"要看职责是否相当。只比岗位名称容易产生误判。"}],"usage":"","new":true,"order":609,"aliases":[],"distinction":"Market pricing 主要看外部可比岗位的薪酬。Job evaluation 侧重评估岗位在组织内部的相对价值。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Market pricing","collocationReview":"V18.2 模型编辑复核","comparison":[{"term":"Market pricing","note":"依据外部市场数据确定岗位薪酬水平。","relation":"本词"},{"term":"Salary benchmark","note":"用于比较的市场薪酬基准。","relation":"易混淆"},{"term":"Salary survey","note":"收集市场薪酬数据的调查。","relation":"易混淆"},{"term":"Internal equity","note":"关注内部岗位及员工之间的薪酬合理性。","relation":"易混淆"},{"term":"Pay equity","note":"关注薪酬公平，尤其是无不合理差异。","relation":"易混淆"},{"term":"Pay compression","note":"不同经验或职责员工之间的薪酬差距过小。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"How did we set the salary range for this role?","zh":"这个岗位的薪酬区间是如何确定的？"},"extension":{"en":"For market pricing, match the scope of the role before comparing salaries.","zh":"做市场薪酬定价时，应先核对岗位职责范围，再比较薪资。"}},{"id":"HRV180-021","moduleId":"m2","module":"薪酬激励与福利","term":"Job-based pay","zh":"岗位薪酬","definition":"主要依据岗位职责、要求和相对价值确定薪酬的方式。","example":"A job-based pay structure links pay primarily to the value of the job.","exampleZh":"岗位薪酬体系主要将薪酬与岗位价值挂钩。","collocation":"adopt a job-based pay structure","collocationZh":"采用岗位薪酬体系","dialogue":[{"role":"Manager","en":"Why do these roles have different pay ranges?","zh":"为什么这些岗位的薪酬区间不同？"},{"role":"Compensation Partner","en":"Our job-based pay structure reflects differences in job responsibilities and value.","zh":"我们的岗位薪酬体系体现岗位职责和价值的差异。"}],"usage":"","new":true,"order":610,"aliases":[],"distinction":"Job-based pay 以岗位为主要定薪依据。Skill-based pay 重视员工掌握并证明具备的相关技能。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Job-based pay","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Our job-based pay structure reflects differences in job responsibilities and value.","zh":"我们的岗位薪酬体系体现岗位职责和价值的差异。"},"extension":{"en":"Under job-based pay, a broader role may be placed in a higher salary grade.","zh":"实行岗位薪酬时，职责范围更广的岗位可能被划入较高薪级。"}},{"id":"HRV180-022","moduleId":"m2","module":"薪酬激励与福利","term":"Skill-based pay","zh":"技能薪酬","definition":"根据员工掌握并能证明具备的相关技能确定或调整薪酬的方式。","example":"Skill-based pay rewards employees for acquiring and demonstrating relevant skills.","exampleZh":"技能薪酬对员工掌握并展示相关技能给予薪酬回报。","collocation":"implement skill-based pay","collocationZh":"实施技能薪酬","dialogue":[{"role":"Employee","en":"Will completing the course automatically increase my pay?","zh":"完成课程就会自动加薪吗？"},{"role":"Team Lead","en":"Under our skill-based pay policy, you must also demonstrate the required skills.","zh":"根据我们的技能薪酬政策，你还必须展示所要求的技能。"}],"usage":"","new":true,"order":611,"aliases":[],"distinction":"Skill-based pay 与可验证的技能挂钩。Performance-based pay 与达到的绩效结果或考核评价挂钩。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Skill-based pay","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Under our skill-based pay policy, you must also demonstrate the required skills.","zh":"根据我们的技能薪酬政策，你还必须展示所要求的技能。"},"extension":{"en":"The skill-based pay policy lists which certifications qualify for an increase.","zh":"技能薪酬政策列出了哪些认证可作为加薪依据。"}},{"id":"HRV180-023","moduleId":"m2","module":"薪酬激励与福利","term":"Bonus pool","zh":"奖金池","definition":"在特定考核周期或激励计划下，可供分配的奖金总额。","example":"The company sets the bonus pool based on its financial results and incentive plan rules.","exampleZh":"公司根据财务业绩及激励计划规则确定奖金池。","collocation":"allocate the bonus pool","collocationZh":"分配奖金池资金","dialogue":[{"role":"Manager","en":"Has the bonus pool been approved?","zh":"奖金池已经获批了吗？"},{"role":"Rewards Partner","en":"Yes, but individual awards still need to be determined.","zh":"是的，但个人奖金金额仍需确定。"}],"usage":"","new":true,"order":612,"aliases":[],"distinction":"Bonus pool 指可供分配的总额。Individual bonus 指某一员工获得的奖金，其金额还取决于计划的分配规则。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Bonus pool","collocationReview":"V18.2 模型编辑复核","comparison":[{"term":"Annual bonus","note":"按年度周期发放或评定的奖金。","relation":"易混淆"},{"term":"Performance bonus","note":"依据绩效结果确定的奖金。","relation":"易混淆"},{"term":"Target bonus","note":"达到目标时对应的奖金水平。","relation":"易混淆"},{"term":"Bonus pool","note":"可供分配的奖金总额。","relation":"本词"},{"term":"Sign-on bonus","note":"入职激励奖金。","relation":"易混淆"},{"term":"Retention bonus","note":"为鼓励员工留任而设的奖金。","relation":"易混淆"},{"term":"Commission","note":"通常按销售等业绩计算的提成。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Has the bonus pool been approved?","zh":"奖金池已经获批了吗？"},"extension":{"en":"We’ve set aside part of the bonus pool for team awards.","zh":"我们从奖金池中预留了一部分资金用于团队奖励。"}},{"id":"HRV180-024","moduleId":"m2","module":"薪酬激励与福利","term":"Clawback provision","zh":"追回条款","definition":"在规定条件和适用规则下，要求返还或以其他方式追回已支付或已授予报酬的合同、政策或计划条款。","example":"The incentive plan includes a clawback provision for specified circumstances.","exampleZh":"该激励计划包含适用于特定情形的追回条款。","collocation":"include a clawback provision","collocationZh":"纳入追回条款","dialogue":[{"role":"Executive","en":"Can previously paid bonuses be recovered?","zh":"已经支付的奖金可以追回吗？"},{"role":"Legal Counsel","en":"That depends on the clawback provision and applicable law.","zh":"这取决于追回条款及适用法律。"}],"usage":"","new":true,"order":613,"aliases":[],"distinction":"Clawback 可涉及已发放的奖励。Malus 在一些激励安排中指依据计划条款扣减或取消尚未兑现的奖励。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Clawback provision","collocationReview":"V18.2 模型编辑复核","comparison":[{"term":"Stock option","note":"按约定价格购买股票的权利。","relation":"易混淆"},{"term":"Restricted stock unit (RSU)","note":"满足条件后交付股票或等值款项的单位。","relation":"易混淆"},{"term":"Performance shares","note":"与绩效条件挂钩的股份奖励。","relation":"易混淆"},{"term":"Equity vesting","note":"股权奖励逐步取得归属权的过程。","relation":"易混淆"},{"term":"Vesting schedule","note":"规定归属时间或条件的安排。","relation":"易混淆"},{"term":"Clawback provision","note":"在约定条件下追回已支付或授予报酬的条款。","relation":"本词"}],"legacyDialogueBookmark":{"en":"That depends on the clawback provision and applicable law.","zh":"这取决于追回条款及适用法律。"},"extension":{"en":"Ask legal counsel how the clawback provision applies to a restatement of financial results.","zh":"请法务说明财务业绩重述时追回条款如何适用。"}},{"id":"HRV180-025","moduleId":"m2","module":"薪酬激励与福利","term":"Performance shares","zh":"绩效股份（股权激励）","definition":"以企业或个人达到预设绩效条件为依据，确定实际获得或归属数量的股份类激励。","example":"The number of performance shares earned depends on the achievement of specified performance goals.","exampleZh":"最终获得的绩效股份数量取决于规定绩效目标的达成情况。","collocation":"grant performance shares","collocationZh":"授予绩效股份","dialogue":[{"role":"Employee","en":"Why does the award statement show a target number of performance shares?","zh":"为什么奖励说明里列的是绩效股份目标数量？"},{"role":"Equity Adviser","en":"It’s the reference point. The final number depends on how we perform against the plan’s goals.","zh":"那是参考值。最终数量取决于我们完成计划目标的情况。"}],"usage":"","new":true,"order":614,"aliases":[],"distinction":"Performance shares 的实际获得数量或归属通常受绩效条件影响。Time-based equity awards 主要依据服务期限等时间条件归属。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Performance shares","collocationReview":"V18.2 模型编辑复核","comparison":[{"term":"Stock option","note":"按约定价格购买股票的权利。","relation":"易混淆"},{"term":"Restricted stock unit (RSU)","note":"满足条件后交付股票或等值款项的单位。","relation":"易混淆"},{"term":"Performance shares","note":"与绩效条件挂钩的股份奖励。","relation":"本词"},{"term":"Equity vesting","note":"股权奖励逐步取得归属权的过程。","relation":"易混淆"},{"term":"Vesting schedule","note":"规定归属时间或条件的安排。","relation":"易混淆"},{"term":"Clawback provision","note":"在约定条件下追回已支付或授予报酬的条款。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Are the performance shares guaranteed?","zh":"绩效股份是保证获得的吗？"},"extension":{"en":"The committee will certify the results before determining how many performance shares were earned.","zh":"委员会将先确认绩效结果，再确定实际获得的绩效股份数量。"}},{"id":"HRV180-026","moduleId":"m2","module":"薪酬激励与福利","term":"Vesting schedule","zh":"归属时间表","definition":"列明激励权益在何时及按何种节奏归属的时间安排，归属仍须满足计划条件。","example":"The vesting schedule specifies when employees acquire rights to their equity awards, subject to plan conditions.","exampleZh":"归属时间表规定员工在满足计划条件时何时取得股权奖励相关权利。","collocation":"review the vesting schedule","collocationZh":"审查归属时间表","dialogue":[{"role":"Employee","en":"Can I sell the shares as soon as they vest?","zh":"股份一旦归属就可以出售吗？"},{"role":"Equity Adviser","en":"Not always. Trading restrictions may still apply.","zh":"不一定，仍可能受到交易限制。"}],"usage":"","new":true,"order":615,"aliases":[],"distinction":"Vesting schedule 说明权益何时归属。Exercise window 说明可在什么期间行使期权，已归属期权仍可能受行权期限制。","ipaUK":"","ipaUS":"","ipaSource":"https://dictionary.cambridge.org/us/pronunciation/english/vesting","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Vesting schedule","collocationReview":"V18.2 模型编辑复核","comparison":[{"term":"Stock option","note":"按约定价格购买股票的权利。","relation":"易混淆"},{"term":"Restricted stock unit (RSU)","note":"满足条件后交付股票或等值款项的单位。","relation":"易混淆"},{"term":"Performance shares","note":"与绩效条件挂钩的股份奖励。","relation":"易混淆"},{"term":"Equity vesting","note":"股权奖励逐步取得归属权的过程。","relation":"易混淆"},{"term":"Vesting schedule","note":"规定归属时间或条件的安排。","relation":"本词"},{"term":"Clawback provision","note":"在约定条件下追回已支付或授予报酬的条款。","relation":"易混淆"}],"legacyDialogueBookmark":{"en":"Can I sell the shares as soon as they vest?","zh":"股份一旦归属就可以出售吗？"},"extension":{"en":"The vesting schedule in your grant agreement shows how much vests on each date.","zh":"你的授予协议中列明了每个日期归属的份额。"}},{"id":"HRV180-027","moduleId":"m2","module":"薪酬激励与福利","term":"Benefits harmonization","zh":"福利制度整合","definition":"协调不同组织或员工群体的福利安排，使制度在可行范围内衔接或逐步趋同。","example":"HR is reviewing both companies’ benefit plans as part of benefits harmonization after the merger.","exampleZh":"作为并购后福利制度整合的一部分，HR正在审查两家公司的福利计划。","collocation":"plan benefits harmonization","collocationZh":"规划福利制度整合","dialogue":[{"role":"Employee","en":"Will everyone receive identical benefits immediately?","zh":"所有员工会立即获得完全相同的福利吗？"},{"role":"Benefits Partner","en":"Not necessarily. We need to consider local requirements and existing commitments.","zh":"不一定，我们需要考虑当地要求及现有承诺。"}],"usage":"","new":true,"order":616,"aliases":[],"distinction":"Benefits harmonization 强调协调既有方案，可保留受当地要求或承诺约束的差异。Benefits standardization 更强调统一规则或流程。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Benefits harmonization","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Will everyone receive identical benefits immediately?","zh":"所有员工会立即获得完全相同的福利吗？"},"extension":{"en":"The benefits harmonization plan includes a transition period for employees on the legacy plan.","zh":"福利制度整合方案为仍适用原方案的员工设置了过渡期。"}},{"id":"HRV180-028","moduleId":"m8","module":"HR运营与数据分析","term":"HR business partner (HRBP)","zh":"人力资源业务伙伴","definition":"与业务负责人合作，将人员管理和组织能力等议题纳入业务决策的人力资源岗位。","example":"The HR business partner helped the warehouse manager review turnover on the night shift.","exampleZh":"人力资源业务伙伴协助仓库经理分析夜班员工的离职情况。","collocation":"consult the HR business partner","collocationZh":"咨询HR业务伙伴","dialogue":[{"role":"Manager","en":"Who can help us assess the staffing issue?","zh":"谁能协助我们评估人员配置问题？"},{"role":"HR Adviser","en":"Let's consult our HR business partner.","zh":"我们咨询一下HR业务伙伴吧。"}],"usage":"","new":true,"order":617,"aliases":[],"distinction":"HRBP 通常贴近所支持的业务部门。HR shared services 通常集中处理标准化的服务事项，例如受理员工证明申请。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"HR business partner","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Who can help us assess the staffing issue?","zh":"谁能协助我们评估人员配置问题？"},"extension":{"en":"The HRBP helped the product team plan its staffing for the launch.","zh":"人力资源业务伙伴协助产品团队规划上线所需的人手。"}},{"id":"HRV180-029","moduleId":"m8","module":"HR运营与数据分析","term":"HR operating model","zh":"人力资源运营模式","definition":"人力资源职能组织分工、治理、流程和服务交付的整体方式。","example":"We are redesigning the HR operating model to clarify responsibilities.","exampleZh":"我们正在重新设计HR运营模式，以明确职责。","collocation":"redesign the HR operating model","collocationZh":"重新设计HR运营模式","dialogue":[{"role":"Manager","en":"Does the new HR operating model change who approves exceptions?","zh":"人力资源运营模式调整后，例外事项的审批人会变吗？"},{"role":"HR Director","en":"Yes. Regional teams will handle routine cases and refer policy exceptions to headquarters.","zh":"会。区域团队处理常规事项，政策例外报总部审批。"}],"usage":"","new":true,"order":618,"aliases":[],"distinction":"HR operating model 说明 HR 如何分工运作与提供服务。People strategy 说明组织希望实现哪些人才和组织目标。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"HR operating model","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"The new HR operating model should clarify that.","zh":"新的HR运营模式应明确这一点。"},"extension":{"en":"The new HR operating model gives regional teams discretion over local hiring processes.","zh":"新的人力资源运营模式让区域团队可以自主决定当地招聘流程。"}},{"id":"HRV180-030","moduleId":"m8","module":"HR运营与数据分析","term":"HR service delivery","zh":"人力资源服务交付","definition":"向员工和管理者提供人力资源服务所采用的流程、渠道和支持方式。","example":"We track response times to improve HR service delivery.","exampleZh":"我们跟踪响应时间，以改善HR服务交付。","collocation":"improve HR service delivery","collocationZh":"改善HR服务交付","dialogue":[{"role":"Manager","en":"People keep sending the same request to several teams.","zh":"员工总把同一份申请发给好几个团队。"},{"role":"HR Service Lead","en":"Let’s make the first point of contact clearer. That’s a good place to start improving HR service delivery.","zh":"先明确该找谁受理。这是改进人力资源服务交付的一个切入点。"}],"usage":"","new":true,"order":619,"aliases":[],"distinction":"HR service delivery 强调员工和管理者如何获得服务。HR shared services 指一种将重复性服务集中处理的组织安排。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"HR service delivery","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We need to improve HR service delivery.","zh":"我们需要改善HR服务交付。"},"extension":{"en":"A single intake form simplified HR service delivery for managers.","zh":"统一申请表简化了管理者获取人力资源服务的流程。"}},{"id":"HRV180-031","moduleId":"m8","module":"HR运营与数据分析","term":"Center of excellence (CoE)","zh":"专业能力中心（CoE）","definition":"集中专业知识、制定标准并为业务提供专门方案的团队，如薪酬、人才发展专业中心。","example":"The compensation center of excellence develops reward frameworks.","exampleZh":"薪酬专业能力中心负责制定薪酬激励框架。","collocation":"establish a center of excellence","collocationZh":"建立专业能力中心","dialogue":[{"role":"HRBP","en":"Who designs the new grading framework?","zh":"谁负责设计新的岗位定级框架？"},{"role":"HR Director","en":"Our center of excellence will lead the design.","zh":"我们的专业能力中心将牵头设计。"}],"usage":"","new":true,"order":620,"aliases":[],"distinction":"CoE 提供专家能力与专业标准。Shared services center 通常集中处理可标准化、可重复的事务。","ipaUK":"ˌsen.tər əv ˈek.səl.əns","ipaUS":"sen.t̬ɚ əv ˈek.səl.əns","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/center-of-excellence","ipaReview":"完整词头英美音标文本核对","ipaNote":"英美音标据 Cambridge 发音词头核对。朗读使用设备语音。","speakTerm":"Center of excellence","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Who designs the new grading framework?","zh":"谁负责设计新的岗位定级框架？"},"extension":{"en":"Ask the rewards CoE to review the proposed job grades before we publish them.","zh":"发布拟定薪级前，请薪酬激励专业中心先行审查。"}},{"id":"HRV180-032","moduleId":"m8","module":"HR运营与数据分析","term":"Workforce demand forecast","zh":"人力需求预测","definition":"依据业务计划、工作量等信息，估算未来需要的员工数量、岗位或技能。","example":"The workforce demand forecast reflects expected business growth.","exampleZh":"人力需求预测反映预期业务增长。","collocation":"update the workforce demand forecast","collocationZh":"更新人力需求预测","dialogue":[{"role":"Operations Lead","en":"How many engineers might we need next year?","zh":"明年我们可能需要多少工程师？"},{"role":"Workforce Analyst","en":"Let's update the workforce demand forecast.","zh":"我们更新一下人力需求预测吧。"}],"usage":"","new":true,"order":621,"aliases":[],"distinction":"Workforce demand forecast 预测未来需要多少人、哪些技能。Workforce supply forecast 估计未来可获得多少人及技能。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Workforce demand forecast","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Let's update the workforce demand forecast.","zh":"我们更新一下人力需求预测吧。"},"extension":{"en":"The workforce demand forecast assumes the new warehouse will open in October.","zh":"这份人力需求预测以新仓库于十月启用为前提。"}},{"id":"HRV180-033","moduleId":"m8","module":"HR运营与数据分析","term":"Workforce supply forecast","zh":"人力供给预测","definition":"考虑内部流动、离职、招聘渠道等因素，估计未来可获得的人员数量与技能。","example":"The workforce supply forecast accounts for expected departures.","exampleZh":"人力供给预测考虑预计离职情况。","collocation":"prepare a workforce supply forecast","collocationZh":"编制人力供给预测","dialogue":[{"role":"Operations Lead","en":"Will our current team meet next year's needs?","zh":"现有团队能满足明年的需求吗？"},{"role":"Workforce Planner","en":"We need a workforce supply forecast first.","zh":"我们需要先进行人力供给预测。"}],"usage":"","new":true,"order":622,"aliases":[],"distinction":"Workforce supply forecast 估计未来可用的人力。Skills inventory 记录组织目前掌握的技能，可作为供给预测的输入。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Workforce supply forecast","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We need a workforce supply forecast first.","zh":"我们需要先进行人力供给预测。"},"extension":{"en":"Our workforce supply forecast includes the technicians who are expected to complete certification this year.","zh":"我们的人力供给预测纳入了预计今年完成认证的技术人员。"}},{"id":"HRV180-034","moduleId":"m8","module":"HR运营与数据分析","term":"Build-buy-borrow strategy","zh":"培养、招聘与引入外部人才策略","definition":"通过内部培养、对外招聘和短期引入外部人才或服务，填补技能与人力缺口的策略。","example":"We use a build-buy-borrow strategy to close capability gaps.","exampleZh":"我们通过内部培养、外部招聘和借助外部人才弥补能力差距。","collocation":"apply a build-buy-borrow strategy","collocationZh":"采用培养、招聘与外部借力策略","dialogue":[{"role":"Project Lead","en":"Should we hire or train people for this project?","zh":"这个项目应该招聘还是培养人才？"},{"role":"HRBP","en":"Let's consider a build-buy-borrow strategy.","zh":"我们考虑一下培养、招聘与外部借力策略。"}],"usage":"","new":true,"order":623,"aliases":[],"distinction":"Build 指培养内部人员，buy 指对外招聘，borrow 指通过临时借调、承包等方式取得能力。Outsourcing 在部分情况下可属于 borrow，通常强调由供应商承担某项工作或服务。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Build-buy-borrow strategy","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Let's consider a build-buy-borrow strategy.","zh":"我们考虑一下培养、招聘与外部借力策略。"},"extension":{"en":"A build-buy-borrow strategy gives us time to train staff while contractors cover the launch.","zh":"通过培养、招聘和引入外部人才相结合的策略，我们可以由合同人员支持上线，同时为员工培训腾出时间。"}},{"id":"HRV180-035","moduleId":"m8","module":"HR运营与数据分析","term":"Workforce scenario planning","zh":"人力情景规划","definition":"设定若干有实质差异的未来情景，并据此分析人员需求、供给和应对措施。","example":"Workforce scenario planning helps us prepare for different growth rates.","exampleZh":"人力情景规划帮助我们应对不同增长速度。","collocation":"conduct workforce scenario planning","collocationZh":"开展人力情景规划","dialogue":[{"role":"Operations Lead","en":"What if demand falls next year?","zh":"如果明年需求下降怎么办？"},{"role":"Workforce Planner","en":"We can model that through workforce scenario planning.","zh":"我们可以通过人力情景规划模拟这种情况。"}],"usage":"","new":true,"order":624,"aliases":[],"distinction":"Scenario planning 用多个可能情景测试不同决策。Baseline forecast 依据一组基准假设给出估算，可作为某个情景的参照。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Workforce scenario planning","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We can model that through workforce scenario planning.","zh":"我们可以通过人力情景规划模拟这种情况。"},"extension":{"en":"Use workforce scenario planning to test how a delayed opening would affect hiring.","zh":"用人力情景规划检验推迟开业会如何影响招聘。"}},{"id":"HRV180-036","moduleId":"m8","module":"HR运营与数据分析","term":"People strategy","zh":"人才与组织战略","definition":"围绕人力配置、人才发展、组织能力与员工体验等议题制定的整体战略，用于支持业务目标。","example":"Our people strategy supports the company's expansion plans.","exampleZh":"我们的人才与组织战略支持公司的扩张计划。","collocation":"develop a people strategy","collocationZh":"制定人才与组织战略","dialogue":[{"role":"Business Lead","en":"How will HR support the new markets?","zh":"HR将如何支持新市场？"},{"role":"HR Director","en":"We need a people strategy that addresses local talent needs.","zh":"我们需要制定满足当地人才需求的人才与组织战略。"}],"usage":"","new":true,"order":625,"aliases":[],"distinction":"People strategy 指人才与组织的整体方向。HR strategy 在实践中也可作近义词，有时更侧重 HR 职能的工作重点。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"People strategy","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We need a people strategy that addresses local talent needs.","zh":"我们需要制定满足当地人才需求的人才与组织战略。"},"extension":{"en":"The people strategy prioritizes internal mobility as the business enters new markets.","zh":"随着企业进入新市场，人才与组织战略把内部人员流动列为重点。"}},{"id":"HRV180-037","moduleId":"m8","module":"HR运营与数据分析","term":"Strategic alignment","zh":"战略一致性／战略协同","definition":"不同层级或职能的目标、决策和行动对共同战略目标形成支持的程度。","example":"We review HR priorities to ensure strategic alignment with business goals.","exampleZh":"我们审视HR重点工作，确保与业务目标保持战略协同。","collocation":"ensure strategic alignment","collocationZh":"确保战略协同","dialogue":[{"role":"L&D Lead","en":"How can we check strategic alignment for this course?","zh":"怎么判断这门课是否符合战略方向？"},{"role":"HRBP","en":"Map the skills it teaches to the expansion plan before we set the budget.","zh":"定预算前，先把课程培养的技能与扩张计划逐一对应。"}],"usage":"","new":true,"order":626,"aliases":[],"distinction":"Strategic alignment 关心措施是否服务于战略方向。Cross-functional coordination 关心不同职能之间如何配合。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Strategic alignment","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We want to ensure strategic alignment with business needs.","zh":"我们希望确保与业务需求保持战略协同。"},"extension":{"en":"We checked the hiring priorities for strategic alignment before requesting additional headcount.","zh":"申请增加编制前，我们核对了招聘优先事项是否符合战略方向。"}},{"id":"HRV180-038","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Organizational diagnosis","zh":"组织诊断","definition":"通过访谈、数据和流程观察等方式，系统分析组织运行现状、问题及可能成因的过程。","example":"We conducted an organizational diagnosis to identify decision-making bottlenecks.","exampleZh":"我们开展组织诊断，以识别决策瓶颈。","collocation":"conduct an organizational diagnosis","collocationZh":"开展组织诊断","dialogue":[{"role":"Operations Lead","en":"The survey flagged low morale, but we still don’t know what is driving it.","zh":"调查发现士气低落，但我们还不清楚原因。"},{"role":"OD Partner","en":"An organizational diagnosis could combine those results with interviews and workload data.","zh":"可以做一次组织诊断，把调查结果和访谈、工作量数据结合起来。"}],"usage":"","new":true,"order":627,"aliases":[],"distinction":"Organizational diagnosis 旨在解释组织问题及成因。Organizational design 关注如何配置组织结构、职责与协作机制。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Organizational diagnosis","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"An organizational diagnosis may help us identify the causes.","zh":"组织诊断可能帮助我们找出原因。"},"extension":{"en":"The organizational diagnosis combined interviews with a review of approval data.","zh":"组织诊断结合了访谈和审批数据分析。"}},{"id":"HRV180-039","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Delayering","zh":"管理层级精简","definition":"通过减少管理层级来调整组织结构的做法。","example":"We assessed the impact of delayering on managers' workloads.","exampleZh":"我们评估了管理层级精简对管理者工作量的影响。","collocation":"assess the impact of delayering","collocationZh":"评估管理层级精简的影响","dialogue":[{"role":"Operations Director","en":"Will removing a management layer speed up decisions?","zh":"减少一个管理层级会加快决策吗？"},{"role":"OD Partner","en":"We need to assess the impact of delayering first.","zh":"我们需要先评估管理层级精简的影响。"}],"usage":"","new":true,"order":628,"aliases":[],"distinction":"Delayering 强调减少纵向管理层次。Downsizing 强调缩减人员规模，两者可能同时发生。","ipaUK":"diːˈleɪ.ər.ɪŋ","ipaUS":"diːˈleɪ.ɚ.ɪŋ","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/delayering","ipaReview":"完整词头英美音标文本核对","ipaNote":"英美音标据 Cambridge 发音词头核对。朗读使用设备语音。","speakTerm":"Delayering","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We need to assess the impact of delayering first.","zh":"我们需要先评估管理层级精简的影响。"},"extension":{"en":"Delayering increased the number of people reporting directly to each regional director.","zh":"管理层级精简后，每位区域总监的直接下属人数增加了。"}},{"id":"HRV180-040","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Matrix organization","zh":"矩阵式组织","definition":"将多个管理维度组合起来的结构，员工可能同时受职能和项目等不同维度的管理。","example":"In our matrix organization, designers report to a functional manager and take project direction from a product lead.","exampleZh":"在我们的矩阵式组织中，设计师向职能经理汇报，并接受产品负责人对项目的指导。","collocation":"work in a matrix organization","collocationZh":"在矩阵式组织中工作","dialogue":[{"role":"Employee","en":"Who sets my project priorities?","zh":"谁确定我的项目优先级？"},{"role":"Project Lead","en":"In our matrix organization, both managers coordinate them.","zh":"在我们的矩阵式组织中，两位管理者共同协调。"}],"usage":"","new":true,"order":629,"aliases":[],"distinction":"Matrix organization 同时设置两个或更多管理维度。Functional structure 主要按专业职能分组。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Matrix organization","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"In our matrix organization, both managers coordinate them.","zh":"在我们的矩阵式组织中，两位管理者共同协调。"},"extension":{"en":"In a matrix organization, managers need a clear way to resolve competing priorities.","zh":"在矩阵式组织中，管理者需要明确如何处理互相冲突的优先事项。"}},{"id":"HRV180-041","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Functional structure","zh":"职能型组织结构","definition":"主要按财务、营销、人力资源、研发等专业职能划分部门的组织结构。","example":"Under the functional structure, all software engineers report through the engineering department.","exampleZh":"在职能型组织结构下，所有软件工程师均通过工程部门逐级汇报。","collocation":"adopt a functional structure","collocationZh":"采用职能型组织结构","dialogue":[{"role":"Team Lead","en":"Why are finance teams grouped together?","zh":"为什么财务团队集中设置？"},{"role":"OD Partner","en":"We use a functional structure.","zh":"我们采用职能型组织结构。"}],"usage":"","new":true,"order":630,"aliases":[],"distinction":"Functional structure 按专业职能划分部门。Divisional structure 通常按产品、市场或地区划分，各事业部可能管理多个职能。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Functional structure","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We use a functional structure.","zh":"我们采用职能型组织结构。"},"extension":{"en":"A functional structure helped the start-up pool its engineering expertise.","zh":"职能型组织结构帮助这家初创企业集中工程专业能力。"}},{"id":"HRV180-042","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Divisional structure","zh":"事业部制组织结构","definition":"主要按产品、市场、客户或地区组成业务单元的组织结构，各单元通常承担一定经营责任。","example":"The company moved to a divisional structure organized around product lines.","exampleZh":"公司转向按产品线划分的事业部制组织结构。","collocation":"move to a divisional structure","collocationZh":"转向事业部制组织结构","dialogue":[{"role":"Manager","en":"Will each product line have its own leadership team?","zh":"每条产品线都会有自己的领导团队吗？"},{"role":"HRBP","en":"That's the plan under the new divisional structure.","zh":"这是新事业部制组织结构下的计划。"}],"usage":"","new":true,"order":631,"aliases":[],"distinction":"Divisional structure 主要按业务单元划分，即使部门内也设财务、销售等职能。Functional structure 主要按专业职能划分。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Divisional structure","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"That's the plan under the new divisional structure.","zh":"这是新事业部制组织结构下的计划。"},"extension":{"en":"In the divisional structure, each business unit sets its own sales priorities.","zh":"在事业部制组织结构下，各业务单元自行确定销售重点。"}},{"id":"HRV180-043","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Centralization","zh":"集中化","definition":"将某类决策权集中到总部、上级或统一机构的组织安排。","example":"Centralization of decision-making can improve consistency across regions.","exampleZh":"决策权集中有助于提高各地区的一致性。","collocation":"centralization of decision-making","collocationZh":"决策权集中","dialogue":[{"role":"Regional Manager","en":"Who will approve exceptions?","zh":"谁负责审批例外事项？"},{"role":"HR Director","en":"Under our new centralized approval process, headquarters will handle those approvals.","zh":"根据新的集中审批流程，总部将负责这些审批。"}],"usage":"","new":true,"order":632,"aliases":[],"distinction":"Centralization 涉及决策权集中。Standardization 涉及统一做法，即使各单位保留执行或决策权，也可以采用统一标准。","ipaUK":"ˌsen.trə.laɪ.ˈzeɪ.ʃən","ipaUS":"ˌsen.trə.lə.ˈzeɪ.ʃən","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/centralization","ipaReview":"完整词头英美音标文本核对","ipaNote":"英美音标据 Cambridge 发音词头核对。朗读使用设备语音。","speakTerm":"Centralization","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Who will approve exceptions?","zh":"谁负责审批例外事项？"},"extension":{"en":"Centralization of hiring approvals may slow down decisions during peak season.","zh":"招聘审批权集中后，旺季的决策速度可能会变慢。"}},{"id":"HRV180-044","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Decentralization","zh":"分权化","definition":"将部分决策权分配给较低管理层级或各地区、业务单元的组织安排。","example":"Decentralization of authority can help local teams respond faster.","exampleZh":"权限下放有助于当地团队更快响应。","collocation":"decentralization of authority","collocationZh":"权限下放","dialogue":[{"role":"Site Manager","en":"Can regional managers approve local requests?","zh":"区域经理可以审批当地请求吗？"},{"role":"Operations Lead","en":"Yes, under the new decentralization policy.","zh":"可以，根据新的分权政策。"}],"usage":"","new":true,"order":633,"aliases":[],"distinction":"Decentralization 通常指较稳定的权力分布。Delegation 可指经理就某一事务或职责授予下属决策权。","ipaUK":"ˌdiː.sen.trə.laɪˈzeɪ.ʃən","ipaUS":"ˌdiː.sen.trə.ləˈzeɪ.ʃən","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/decentralization","ipaReview":"完整词头英美音标文本核对","ipaNote":"英美音标据 Cambridge 发音词头核对。朗读使用设备语音。","speakTerm":"Decentralization","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Yes, under the new decentralization policy.","zh":"可以，根据新的分权政策。"},"extension":{"en":"Decentralization gave site managers more authority over shift schedules.","zh":"分权后，各站点负责人在排班方面获得了更多权限。"}},{"id":"HRV180-045","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Change sponsorship","zh":"变革领导支持","definition":"有权提供资源和作出决策的领导者为变革明确方向、承担责任并持续提供公开支持的做法。","example":"Strong change sponsorship helps secure resources for implementation.","exampleZh":"有力的变革领导支持有助于获得实施资源。","collocation":"secure executive sponsorship for a change","collocationZh":"争取高管对变革的支持","dialogue":[{"role":"Change Lead","en":"Who will resolve cross-team barriers?","zh":"谁负责解决跨团队障碍？"},{"role":"HRBP","en":"We need stronger change sponsorship from senior leaders.","zh":"我们需要高层领导提供更有力的变革支持。"}],"usage":"","new":true,"order":634,"aliases":[],"distinction":"Change sponsorship 强调具备决策权的领导层承担责任。Change management 涵盖沟通、培训、推进和跟踪等更广的实施工作。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Change sponsorship","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We need stronger change sponsorship from senior leaders.","zh":"我们需要高层领导提供更有力的变革支持。"},"extension":{"en":"Effective change sponsorship requires leaders to make time for decisions throughout the rollout.","zh":"要持续支持变革，领导者需要在推行全过程中安排时间作出相关决策。"}},{"id":"HRV180-046","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Change champion","zh":"变革推动者","definition":"在业务团队中推广变革、帮助同事采用新做法并反馈实施障碍的人。","example":"Each department appointed a change champion to support the rollout.","exampleZh":"各部门指定了一名变革推动者支持推广实施。","collocation":"appoint a change champion","collocationZh":"指定变革推动者","dialogue":[{"role":"Team Lead","en":"Who can help colleagues learn the new process?","zh":"谁能帮助同事学习新流程？"},{"role":"Manager","en":"Our change champion can provide guidance.","zh":"我们的变革推动者可以提供指导。"}],"usage":"","new":true,"order":635,"aliases":[],"distinction":"Change champion 往往在一线推动采纳和反馈。Change sponsor 通常有正式决策权，可协调资源并承担变革责任。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Change champion","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Our change champion can provide guidance.","zh":"我们的变革推动者可以提供指导。"},"extension":{"en":"Our change champions collected feedback from colleagues after the first week of the pilot.","zh":"试点运行一周后，变革推动者收集了同事的反馈。"}},{"id":"HRV180-047","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Change adoption","zh":"变革采纳／新做法采用","definition":"员工开始实际使用新系统、流程或工作方式的过程，或衡量实际使用的程度。","example":"We monitor change adoption through actual use of the new process.","exampleZh":"我们通过新流程的实际使用情况监测变革采纳情况。","collocation":"monitor change adoption","collocationZh":"监测变革采纳情况","dialogue":[{"role":"Project Lead","en":"Is training attendance enough to measure success?","zh":"仅凭培训出勤率就能衡量成功吗？"},{"role":"Change Analyst","en":"No, we also need to monitor change adoption.","zh":"不能，我们还需要监测变革采纳情况。"}],"usage":"","new":true,"order":636,"aliases":[],"distinction":"Change adoption 看新行为是否实际发生。Training participation 看人员是否参与培训，可为判断采纳提供背景。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Change adoption","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"No, we also need to monitor change adoption.","zh":"不能，我们还需要监测变革采纳情况。"},"extension":{"en":"We will measure change adoption by checking whether teams submit requests through the new portal.","zh":"我们将通过检查团队是否使用新门户提交申请来衡量变革采纳情况。"}},{"id":"HRV180-048","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Succession risk","zh":"继任风险","definition":"重要岗位的潜在继任者不足、就绪程度不高或交接准备不足所带来的运营中断风险。","example":"We assess succession risk for critical leadership roles.","exampleZh":"我们评估关键领导岗位的继任风险。","collocation":"assess succession risk","collocationZh":"评估继任风险","dialogue":[{"role":"HRBP","en":"The plant manager has a deputy. Why is succession risk still high?","zh":"厂长有副手，为什么继任风险仍然较高？"},{"role":"Talent Partner","en":"The deputy can run the site but hasn’t been cleared to sign off on major spending.","zh":"副手能管理工厂日常运营，但还未获准审批重大支出。"}],"usage":"","new":true,"order":637,"aliases":[],"distinction":"Succession risk 关注岗位出现空缺时组织所受影响和接任准备。Flight risk 关注某位员工离职的可能性。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Succession risk","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We need to assess succession risk for that role.","zh":"我们需要评估该岗位的继任风险。"},"extension":{"en":"The succession risk is high because there is no deputy who can take over at short notice.","zh":"由于没有能临时接任的副手，该岗位的继任风险较高。"}},{"id":"HRV180-049","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Successor coverage","zh":"继任覆盖情况／继任覆盖率","definition":"关键岗位拥有符合所设条件的潜在继任者的覆盖情况，可用岗位比例表示。","example":"We aim to improve successor coverage for critical roles.","exampleZh":"我们致力于提高关键岗位的继任覆盖水平。","collocation":"improve successor coverage","collocationZh":"提高继任覆盖水平","dialogue":[{"role":"HR Director","en":"Do we include interim appointees in successor coverage?","zh":"计算继任覆盖情况时，要把临时代理人也算进去吗？"},{"role":"Talent Partner","en":"Only if they meet the criteria for a longer-term successor.","zh":"只有符合长期继任人选条件的才计入。"}],"usage":"","new":true,"order":638,"aliases":[],"distinction":"Successor coverage 衡量有继任人选的岗位范围。Bench strength 还可关注候选人的数量、能力和就绪程度。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Successor coverage","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Not yet. We need to improve successor coverage.","zh":"还没有，我们需要提高继任覆盖水平。"},"extension":{"en":"Our successor coverage improves if we count people who could be ready within two years.","zh":"如果将两年内可能具备接任条件的人选计入，继任覆盖率会提高。"}},{"id":"HRV180-050","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Emergency succession plan","zh":"应急继任计划","definition":"为应对关键岗位突然空缺或负责人暂时无法履职而制定的连续性安排，通常明确临时接任、权限及通知流程。","example":"The board reviews the emergency succession plan annually.","exampleZh":"董事会每年审查应急继任计划。","collocation":"prepare an emergency succession plan","collocationZh":"制定应急继任计划","dialogue":[{"role":"Board Director","en":"Who takes over if the CEO is suddenly unavailable?","zh":"如果CEO突然无法履职，谁来接任？"},{"role":"Company Secretary","en":"The emergency succession plan identifies an interim leader.","zh":"应急继任计划明确了临时负责人。"}],"usage":"","new":true,"order":639,"aliases":[],"distinction":"Emergency succession plan 关注突发接任与短期连续性。Long-term succession planning 关注培养未来候选人和长期的人才储备。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Emergency succession plan","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"The emergency succession plan identifies an interim leader.","zh":"应急继任计划明确了临时负责人。"},"extension":{"en":"The emergency succession plan specifies who can approve payments during the CEO’s absence.","zh":"应急继任计划明确了首席执行官缺席期间谁有权审批付款。"}},{"id":"HRV180-051","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Talent differentiation","zh":"人才差异化管理","definition":"依据一致的标准，考虑员工的贡献、发展潜力或需要，对培养、岗位安排等人才举措采用差异化配置。","example":"Talent differentiation should be based on consistent assessment criteria.","exampleZh":"人才差异化管理应基于一致的评估标准。","collocation":"apply talent differentiation","collocationZh":"实施人才差异化管理","dialogue":[{"role":"Manager","en":"Should everyone receive the same development support?","zh":"每个人都应该获得相同的发展支持吗？"},{"role":"Talent Partner","en":"Talent differentiation can help tailor support to individual needs.","zh":"人才差异化管理有助于根据个人需求提供支持。"}],"usage":"","new":true,"order":640,"aliases":[],"distinction":"Talent differentiation 体现为按人才情况配置资源与机会。Talent segmentation 侧重按规则分组，可作为差异化管理的基础。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Talent differentiation","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Talent differentiation can help tailor support to individual needs.","zh":"人才差异化管理有助于根据个人需求提供支持。"},"extension":{"en":"We reviewed the talent differentiation criteria before allocating coaching places.","zh":"分配教练辅导名额前，我们复核了人才差异化管理的标准。"}},{"id":"HRV180-052","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Potential assessment","zh":"潜力评估","definition":"评估个人未来承担更复杂、范围更大或不同类型职责的成长潜力。","example":"A potential assessment considers capacity for future responsibilities.","exampleZh":"潜力评估考虑承担未来职责的能力。","collocation":"conduct a potential assessment","collocationZh":"开展潜力评估","dialogue":[{"role":"Manager","en":"Does strong performance prove leadership potential?","zh":"出色绩效能证明领导潜力吗？"},{"role":"Talent Partner","en":"Not necessarily. We need a separate potential assessment.","zh":"不一定，我们需要单独开展潜力评估。"}],"usage":"","new":true,"order":641,"aliases":[],"distinction":"Potential assessment 关注未来可发展到什么程度。Performance assessment 关注员工在当前职责下的工作成果或表现。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Potential assessment","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Not necessarily. We need a separate potential assessment.","zh":"不一定，我们需要单独开展潜力评估。"},"extension":{"en":"The potential assessment drew on examples of how she learned in unfamiliar roles.","zh":"潜力评估参考了她在不熟悉岗位中的学习表现。"}},{"id":"HRV180-053","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Readiness assessment","zh":"任职就绪度评估","definition":"围绕特定岗位或职责及相关时间范围，评估候选人是否已具备任职所需能力与经验。","example":"The readiness assessment identifies gaps before promotion.","exampleZh":"任职就绪度评估识别晋升前的能力差距。","collocation":"conduct a readiness assessment","collocationZh":"开展任职就绪度评估","dialogue":[{"role":"HRBP","en":"Marco did well in the acting role. Can we promote him now?","zh":"马可代理期间表现出色，现在可以晋升他吗？"},{"role":"Talent Partner","en":"Let’s use the readiness assessment to check how much of the permanent role he has actually covered.","zh":"我们用任职就绪度评估看看，他实际承担过正式岗位的哪些职责。"}],"usage":"","new":true,"order":642,"aliases":[],"distinction":"Readiness assessment 关注某个岗位在当前或指定时间内的任职准备程度。Potential assessment 关注更长期的成长空间。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Readiness assessment","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Let's conduct a readiness assessment.","zh":"我们开展一次任职就绪度评估吧。"},"extension":{"en":"The readiness assessment identified one gap in budget management.","zh":"任职就绪度评估发现，候选人在预算管理方面存在一项能力缺口。"}},{"id":"HRV180-054","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Career aspiration","zh":"职业发展意愿","definition":"个人希望在未来从事的职业方向、承担的职责或实现的职业目标，常用复数 career aspirations。","example":"Managers should discuss career aspirations during development conversations.","exampleZh":"管理者应在发展面谈中讨论员工的职业发展意愿。","collocation":"discuss career aspirations","collocationZh":"交流职业发展意愿","dialogue":[{"role":"Manager","en":"Does he want to move into management?","zh":"他希望转向管理岗位吗？"},{"role":"HRBP","en":"We should discuss his career aspirations first.","zh":"我们应该先了解他的职业发展意愿。"}],"usage":"","new":true,"order":643,"aliases":[],"distinction":"Career aspirations 表达本人希望如何发展。Career path 描述可行或既定的职业发展路线。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Career aspiration","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We should discuss his career aspirations first.","zh":"我们应该先了解他的职业发展意愿。"},"extension":{"en":"Her career aspirations include leading a regional customer success team.","zh":"她的职业目标之一是带领一支地区客户成功团队。"}},{"id":"HRV180-055","moduleId":"m5","module":"组织与人才发展（OD/TD）","term":"Developmental assignment","zh":"发展性任务","definition":"以积累特定经验或培养明确能力为目的而安排的一项实际工作。","example":"To build negotiation skills, Maya took on a developmental assignment in procurement.","exampleZh":"为了锻炼谈判能力，玛雅承担了一项采购方面的发展性任务。","collocation":"offer a developmental assignment","collocationZh":"提供发展性工作任务","dialogue":[{"role":"Manager","en":"How can she gain cross-functional experience?","zh":"她如何获得跨职能经验？"},{"role":"Talent Partner","en":"We could offer her a developmental assignment.","zh":"我们可以为她提供一项发展性工作任务。"}],"usage":"","new":true,"order":644,"aliases":[],"distinction":"Developmental assignment 强调学习目标。Stretch assignment 更强调任务挑战超过员工现有的常规职责或能力要求。","ipaUK":"","ipaUS":"","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/assignment","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Developmental assignment","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"We could offer her a developmental assignment.","zh":"我们可以为她提供一项发展性工作任务。"},"extension":{"en":"The developmental assignment includes a monthly check-in with her sponsor.","zh":"这项发展性任务安排她每月与支持该任务的负责人沟通一次。"}},{"id":"HRV180-056","moduleId":"m8","module":"HR运营与数据分析","term":"Revenue per employee","zh":"人均营收","definition":"在约定统计期间内，以营收除以按统一规则确定的员工人数或全职当量所得的指标。","example":"We calculate revenue per employee using average quarterly headcount.","exampleZh":"我们以季度平均员工人数为分母计算人均营收。","collocation":"track revenue per employee","collocationZh":"跟踪人均营收","dialogue":[{"role":"Finance Partner","en":"Can we compare this metric across regions?","zh":"我们可以跨地区比较这个指标吗？"},{"role":"HR Analyst","en":"Yes, if revenue and headcount definitions are consistent.","zh":"可以，前提是营收和人员数量口径一致。"}],"usage":"","new":true,"order":645,"aliases":[],"distinction":"Revenue per employee 的分子是营收。Profit per employee 的分子是利润。比较时需对齐期间及分母口径。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Revenue per employee","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Can we compare this metric across regions?","zh":"我们可以跨地区比较这个指标吗？"},"extension":{"en":"Before comparing revenue per employee, check whether both reports use average headcount or full-time equivalents.","zh":"比较人均营收前，请确认两份报告是以平均员工人数还是全职当量为分母。"}},{"id":"HRV180-057","moduleId":"m8","module":"HR运营与数据分析","term":"Labor cost ratio","zh":"人工成本比率","definition":"人工成本与营收、总成本等约定财务基数之比，比较时应统一分子与分母口径。","example":"In this report, the labor cost ratio is total labor costs divided by revenue.","exampleZh":"在本报告中，人工成本比率等于人工总成本除以营收。","collocation":"monitor the labor cost ratio","collocationZh":"监测人工成本比率","dialogue":[{"role":"Finance Partner","en":"Why did the ratio increase this quarter?","zh":"为什么本季度比率上升了？"},{"role":"HR Analyst","en":"Revenue fell while labor costs remained stable.","zh":"营收下降，而人工成本保持稳定。"}],"usage":"","new":true,"order":646,"aliases":[],"distinction":"Labor cost ratio 反映人工成本相对于某个财务基数的占比。Labor cost per employee 反映平均到每位员工的人工成本。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Labor cost ratio","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Why did the ratio increase this quarter?","zh":"为什么本季度比率上升了？"},"extension":{"en":"The labor cost ratio in this dashboard uses net revenue as the denominator.","zh":"该仪表板中的人工成本比率以净营收为分母。"}},{"id":"HRV180-058","moduleId":"m8","module":"HR运营与数据分析","term":"Human capital return on investment","zh":"人力资本投资回报率","definition":"按明确的方法，将可归于人力资本的产出或财务回报与相应的人力资本成本联系起来测算的指标。","example":"We calculate human capital return on investment using a documented methodology.","exampleZh":"我们采用有明确记录的方法计算人力资本投资回报率。","collocation":"calculate human capital return on investment","collocationZh":"计算人力资本投资回报率","dialogue":[{"role":"Finance Partner","en":"Our human capital return on investment looks higher this year.","zh":"今年的人力资本投资回报率似乎更高。"},{"role":"HR Analyst","en":"Did we count contractor costs the same way in both years?","zh":"两年采用了相同的合同人员成本计算口径吗？"}],"usage":"","new":true,"order":647,"aliases":[],"distinction":"Human capital ROI 关注回报与投入成本的关系。Revenue per employee 以人数或全职当量为分母，侧重营收产出。","ipaUK":"","ipaUS":"","ipaSource":"待权威词典核验","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Human capital return on investment","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Can we compare this figure with another company?","zh":"我们可以与另一家公司比较这个数值吗？"},"extension":{"en":"We document which costs are included whenever we report human capital return on investment.","zh":"每次报告人力资本投资回报率时，我们都会记录纳入计算的成本项目。"}},{"id":"HRV180-059","moduleId":"m8","module":"HR运营与数据分析","term":"Cohort analysis","zh":"群组分析","definition":"按共同特征或起始事件划分群组，并追踪或比较各群组在可比时间跨度内的结果。","example":"We conducted a cohort analysis of employees hired in the same quarter.","exampleZh":"我们对同一季度入职的员工开展群组分析。","collocation":"conduct a cohort analysis","collocationZh":"开展群组分析","dialogue":[{"role":"HR Director","en":"Can you do a cohort analysis by onboarding program?","zh":"可以按入职培训方案做群组分析吗？"},{"role":"People Analyst","en":"Yes. I’ll compare each group’s retention after the same length of service.","zh":"可以。我会比较各组在相同任职时长下的留任情况。"}],"usage":"","new":true,"order":648,"aliases":[],"distinction":"Cohort analysis 可按入职月份等共同起点追踪结果。A point-in-time snapshot 只呈现某一时点的整体或分组状态。","ipaUK":"","ipaUS":"","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/cohort","ipaReview":"完整词头音标待补证","ipaNote":"缺少完整词头证据的音标栏显示待核验。朗读使用设备语音。","speakTerm":"Cohort analysis","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"A cohort analysis can help us compare retention patterns.","zh":"群组分析可以帮助我们比较留任模式。"},"extension":{"en":"The cohort analysis compares retention at 90 days across three hiring quarters.","zh":"这项群组分析比较了三个招聘季度的员工入职 90 天留任情况。"}},{"id":"HRV180-060","moduleId":"m8","module":"HR运营与数据分析","term":"Leading indicator","zh":"领先指标","definition":"在目标结果出现前可观察、用于提示未来变化风险或趋势的指标，其预测价值需要验证。","example":"We are testing whether engagement scores serve as a leading indicator of turnover.","exampleZh":"我们正在验证敬业度得分能否作为员工离职的领先指标。","collocation":"identify a leading indicator","collocationZh":"识别领先指标","dialogue":[{"role":"HRBP","en":"Can we detect retention risks earlier?","zh":"我们能更早识别员工流失风险吗？"},{"role":"People Analyst","en":"Let's validate a suitable leading indicator.","zh":"我们验证一个合适的领先指标吧。"}],"usage":"","new":true,"order":649,"aliases":[],"distinction":"Leading indicator 用于提前观察信号。Lagging indicator 记录已发生的结果。同一指标的类别取决于它相对哪个结果以及哪个观察期。","ipaUK":"ˌliː.dɪŋ ˈɪn.dɪ.keɪ.tə(r)","ipaUS":"ˌliː.dɪŋ ˈɪn.də.keɪ.t̬ɚ","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/leading-indicator","ipaReview":"完整词头英美音标文本核对","ipaNote":"英美音标据 Cambridge 发音词头核对。朗读使用设备语音。","speakTerm":"Leading indicator","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Let's validate a suitable leading indicator.","zh":"我们验证一个合适的领先指标吧。"},"extension":{"en":"Check whether overtime is a leading indicator of absence in this team.","zh":"请检验加班时长是否是这个团队缺勤情况的领先指标。"}},{"id":"HRV180-061","moduleId":"m8","module":"HR运营与数据分析","term":"Lagging indicator","zh":"滞后指标","definition":"反映已经发生的结果或变化，往往在相关事件发生后才可计算的指标。","example":"Last quarter’s turnover rate is a lagging indicator of workforce retention.","exampleZh":"上季度离职率是反映员工留任结果的滞后指标。","collocation":"track a lagging indicator","collocationZh":"跟踪滞后指标","dialogue":[{"role":"Manager","en":"Could we use last quarter’s turnover rate to predict who might leave next?","zh":"能不能用上一季度的离职率预测接下来谁可能离职？"},{"role":"People Analyst","en":"It’s a lagging indicator. We should look for earlier signals alongside it.","zh":"它是个滞后指标。我们还应同时寻找更早出现的信号。"}],"usage":"","new":true,"order":650,"aliases":[],"distinction":"Lagging indicator 记录已发生的结果，例如季度结束后统计的离职率。Leading indicator 关注可能先于目标结果出现的信号。","ipaUK":"ˌlæɡ.ɪŋ ˈɪn.dɪ.keɪ.tə(r)","ipaUS":"ˌlæɡ.ɪŋ ˈɪn.də.keɪ.t̬ɚ","ipaSource":"https://dictionary.cambridge.org/pronunciation/english/lagging-indicator","ipaReview":"完整词头英美音标文本核对","ipaNote":"英美音标据 Cambridge 发音词头核对。朗读使用设备语音。","speakTerm":"Lagging indicator","collocationReview":"V18.2 模型编辑复核","legacyDialogueBookmark":{"en":"Not on its own. It is a lagging indicator.","zh":"仅凭它不能，它是一个滞后指标。"},"extension":{"en":"We use customer complaints as a lagging indicator of service quality.","zh":"我们把客户投诉作为服务质量的滞后指标，用来反映已经出现的问题。"}}],"scenarios":[{"id":"S01","moduleId":"m1","title":"招聘需求确认","titleEn":"Planning a new hire","lines":[{"role":"Hiring Manager","en":"We need to hire two engineers next quarter. Has the headcount been approved?","zh":"下季度我们需要招聘两名工程师。编制获批了吗？"},{"role":"Recruiter","en":"Not yet. Please submit a job requisition with the business justification.","zh":"还没有。请提交招聘申请单并说明业务理由。"},{"role":"Hiring Manager","en":"Once it is approved, how quickly can we start sourcing candidates?","zh":"获批后，我们多快能开始寻访候选人？"},{"role":"Recruiter","en":"We can publish the job posting and start outreach within two working days.","zh":"我们可以在两个工作日内发布职位信息并开始主动接触候选人。"}],"quiz":"What document needs approval before hiring begins?","answer":"job requisition","quizZh":"招聘开始前需要审批哪份文件？","answerZh":"招聘申请单"},{"id":"S02","moduleId":"m1","title":"录用进度沟通","titleEn":"Discussing an offer","lines":[{"role":"Recruiter","en":"The final candidate has a six-week notice period.","zh":"最终候选人的离职通知期是六周。"},{"role":"Hiring Manager","en":"Can we adjust the start date in the offer letter?","zh":"我们能在录用通知书中调整入职日期吗？"},{"role":"Recruiter","en":"Yes. I will confirm the salary expectations and send the revised offer.","zh":"可以。我会确认薪酬期望，然后发送修订后的录用通知。"},{"role":"Hiring Manager","en":"Please keep the candidate updated throughout the process.","zh":"请在整个过程中持续向候选人同步进展。"}],"quiz":"What document is being revised?","answer":"offer letter","quizZh":"正在修订哪份文件？","answerZh":"录用通知书"},{"id":"S03","moduleId":"m2","title":"薪资区间与公平","titleEn":"Explaining salary bands","lines":[{"role":"HRBP","en":"The proposed salary is above the midpoint. Does it fit the band?","zh":"拟议工资高于区间中点。它仍在薪资范围内吗？"},{"role":"Compensation Partner","en":"Yes, but we should review internal equity before making the offer.","zh":"是的，但在发出录用前应复核内部薪酬公平。"},{"role":"HRBP","en":"Can we share the salary band with the hiring manager?","zh":"我们可以向用人经理提供薪资区间吗？"},{"role":"Compensation Partner","en":"Of course. I will also explain the compa-ratio and approval rules.","zh":"当然。我还会解释薪酬比较率和审批规则。"}],"quiz":"Which ratio compares pay with a range midpoint?","answer":"compa-ratio","quizZh":"哪项比率用于比较员工薪酬与薪资区间中点？","answerZh":"薪酬比较率（Compa-ratio）"},{"id":"S04","moduleId":"m2","title":"奖金方案沟通","titleEn":"Discussing a bonus plan","lines":[{"role":"Manager","en":"Is the target bonus part of the employee’s base salary?","zh":"目标奖金包含在员工基本工资里吗？"},{"role":"Rewards Partner","en":"No. It is variable pay and depends on the plan conditions.","zh":"不包含。它属于浮动薪酬，取决于激励计划条件。"},{"role":"Manager","en":"What if the team exceeds the performance threshold?","zh":"如果团队超过绩效门槛，会怎样？"},{"role":"Rewards Partner","en":"The final payout will follow the approved incentive formula.","zh":"最终发放额会按照获批的激励公式执行。"}],"quiz":"Is a target bonus fixed base salary or variable pay?","answer":"variable pay","quizZh":"目标奖金属于固定基本工资还是浮动薪酬？","answerZh":"浮动薪酬"},{"id":"S05","moduleId":"m3","title":"绩效校准讨论","titleEn":"Calibrating performance ratings","lines":[{"role":"HRBP","en":"Some teams gave higher ratings than others for similar results.","zh":"有些团队对相似成果给出了更高的绩效等级。"},{"role":"Manager","en":"Should we change the ratings during calibration?","zh":"我们应该在校准会上调整评级吗？"},{"role":"HRBP","en":"Let’s compare documented evidence against the same rating criteria first.","zh":"先用统一的评级标准比较记录在案的证据。"},{"role":"Manager","en":"Agreed. I will bring examples of the employee’s outcomes.","zh":"同意。我会带上员工工作成果的具体例子。"}],"quiz":"What should we compare against the same rating criteria?","answer":"documented evidence","quizZh":"我们应该用统一的评级标准比较什么？","answerZh":"有记录的事实证据"},{"id":"S06","moduleId":"m3","title":"绩效改进沟通","titleEn":"Discussing a performance improvement plan","lines":[{"role":"Manager","en":"I’m concerned that the team has repeatedly missed project deadlines.","zh":"团队已多次未能按期完成项目，我对此有些担心。"},{"role":"HRBP","en":"Have you provided specific feedback and support?","zh":"你是否提供了具体反馈和支持？"},{"role":"Manager","en":"Yes. We should now agree on measurable improvement milestones.","zh":"提供了。现在我们需要确定可衡量的改进里程碑。"},{"role":"HRBP","en":"Let us document the expectations, resources and review dates in the PIP.","zh":"我们把预期、支持资源和复盘日期写入绩效改进计划。"}],"quiz":"What does PIP stand for?","answer":"performance improvement plan","quizZh":"PIP 是什么的缩写？","answerZh":"绩效改进计划"},{"id":"S07","moduleId":"m4","title":"培训需求评估","titleEn":"Assessing learning needs","lines":[{"role":"L&D Partner","en":"Our managers say stakeholder communication is a major challenge.","zh":"经理们反馈，利益相关方沟通是一个主要难点。"},{"role":"HRBP","en":"Should we launch training right away?","zh":"我们应该马上启动培训吗？"},{"role":"L&D Partner","en":"First, we need a training needs assessment to confirm the gaps.","zh":"首先，我们需要通过培训需求评估确认能力差距。"},{"role":"HRBP","en":"Good. Then we can define learning outcomes and choose the format.","zh":"好。之后我们再明确学习目标，并选择培训形式。"}],"quiz":"What should be done before choosing the training format?","answer":"training needs assessment","quizZh":"在选择培训形式前应先开展什么工作？","answerZh":"培训需求评估"},{"id":"S08","moduleId":"m4","title":"培训效果复盘","titleEn":"Reviewing training effectiveness","lines":[{"role":"L&D Manager","en":"Course completion reached ninety percent, but has behavior changed?","zh":"课程完成率达到了百分之九十，但行为有改变吗？"},{"role":"Facilitator","en":"We can ask managers to observe whether new skills are used at work.","zh":"我们可以请经理观察员工是否将新技能用于工作。"},{"role":"L&D Manager","en":"That will help us assess learning transfer.","zh":"这有助于评估学习迁移。"},{"role":"Facilitator","en":"Let us collect follow-up evidence after sixty days.","zh":"我们在六十天后收集后续证据。"}],"quiz":"What is the transfer of skills into daily work called?","answer":"learning transfer","quizZh":"将学到的技能运用于日常工作称为什么？","answerZh":"学习迁移／培训成果转化"},{"id":"S09","moduleId":"m5","title":"汇报关系解释","titleEn":"Understanding reporting lines","lines":[{"role":"Employee","en":"Can you explain the reporting line in this organization?","zh":"你能解释一下这个组织中的汇报关系吗？"},{"role":"HRBP","en":"You report directly to the country manager. That’s your solid-line reporting relationship.","zh":"你直接向国别负责人汇报，这就是你的实线汇报关系。"},{"role":"Employee","en":"And what does the dotted-line relationship mean?","zh":"那虚线汇报关系意味着什么？"},{"role":"HRBP","en":"The regional lead provides functional guidance but is not your direct manager.","zh":"区域负责人提供职能指导，但不是你的直属经理。"}],"quiz":"Which term describes a functional, indirect reporting relationship?","answer":"dotted-line reporting","quizZh":"哪种术语描述职能上的间接汇报关系？","answerZh":"虚线汇报关系"},{"id":"S10","moduleId":"m5","title":"继任计划讨论","titleEn":"Reviewing succession plans","lines":[{"role":"HR Director","en":"Do we have a ready-now successor for the operations director role?","zh":"运营总监岗位有可以立即接任的人选吗？"},{"role":"Talent Partner","en":"Not yet. Two potential successors need more cross-functional exposure.","zh":"暂时没有。两名潜在继任者还需要更多跨职能历练。"},{"role":"HR Director","en":"Can we add job rotation to their development plans?","zh":"我们能把岗位轮换加入他们的发展计划吗？"},{"role":"Talent Partner","en":"Yes. We will review successor readiness again in six months.","zh":"可以。我们将在六个月后再次评估继任者准备度。"}],"quiz":"What is the formal process for preparing future role holders?","answer":"succession planning","quizZh":"为未来关键岗位培养接任者的正式流程叫什么？","answerZh":"继任规划"},{"id":"S11","moduleId":"m6","title":"员工申诉处理","titleEn":"Handling an employee grievance","lines":[{"role":"Employee","en":"I would like to raise a concern about how my complaint was handled.","zh":"我想反映一下我的投诉处理过程存在的问题。"},{"role":"HR Partner","en":"Thank you for telling us. We will explain the grievance procedure.","zh":"谢谢你告知我们。我们会说明员工申诉程序。"},{"role":"Employee","en":"Will the information be kept confidential?","zh":"相关信息会被保密吗？"},{"role":"HR Partner","en":"We will limit access to those who need the information for a fair review.","zh":"我们只会让为公平审查而需知悉此事的人员接触相关信息。"}],"quiz":"Which procedure addresses a formal employee complaint?","answer":"grievance procedure","quizZh":"处理正式员工投诉所使用的程序是什么？","answerZh":"员工申诉程序"},{"id":"S12","moduleId":"m6","title":"调查与合规","titleEn":"Investigating a policy concern","lines":[{"role":"Manager","en":"Someone reported a possible code-of-conduct violation.","zh":"有人举报可能违反行为准则的情况。"},{"role":"HR Partner","en":"We should start an impartial workplace investigation.","zh":"我们应该开展公正的职场调查。"},{"role":"Manager","en":"Should I make a decision before we interview witnesses?","zh":"我应该在询问证人之前就作出决定吗？"},{"role":"HR Partner","en":"No. Gather the facts first and follow due process.","zh":"不应该。先收集事实并遵守正当程序。"}],"quiz":"What principle requires a fair procedure before a decision?","answer":"due process","quizZh":"什么原则要求在作出决定之前遵循公平程序？","answerZh":"正当程序"},{"id":"S13","moduleId":"m7","title":"敬业度调研复盘","titleEn":"Acting on engagement feedback","lines":[{"role":"People Partner","en":"The engagement survey shows employees want more career conversations.","zh":"敬业度调查显示员工希望有更多职业发展沟通。"},{"role":"Team Lead","en":"How do we show that their feedback matters?","zh":"我们如何让员工感受到他们的反馈受到重视？"},{"role":"People Partner","en":"Agree on visible actions and share progress after the next pulse survey.","zh":"确定具体可见的改进行动，并在下次简短跟踪调查后同步进度。"},{"role":"Team Lead","en":"I will start monthly one-on-one development check-ins.","zh":"我会开始每月一次的一对一发展沟通。"}],"quiz":"Which survey is usually short and frequent?","answer":"pulse survey","quizZh":"哪一种调查通常更简短、开展得更频繁？","answerZh":"短频调查（脉搏调查）"},{"id":"S14","moduleId":"m7","title":"心理安全与发言","titleEn":"Creating psychological safety","lines":[{"role":"Manager","en":"People rarely challenge ideas during team meetings.","zh":"大家很少在团队会议上提出不同意见。"},{"role":"HRBP","en":"Psychological safety improves when leaders welcome questions.","zh":"当领导者欢迎提问时，心理安全感会提升。"},{"role":"Manager","en":"What should I do when someone points out a mistake?","zh":"有人指出错误时，我该怎么做？"},{"role":"HRBP","en":"Thank them, ask for details and respond without blaming them.","zh":"感谢对方、询问具体情况，并在回应时避免责备。"}],"quiz":"What term means feeling safe to speak up?","answer":"psychological safety","quizZh":"让员工放心表达意见的心理状态叫什么？","answerZh":"心理安全感"},{"id":"S15","moduleId":"m8","title":"HR数据口径","titleEn":"Aligning people metrics","lines":[{"role":"Analyst","en":"The headcount report and payroll report show different totals.","zh":"员工人数报表与薪资报表显示的总人数不一致。"},{"role":"HR Manager","en":"Could the reports be using different definitions?","zh":"是否可能因为报表采用了不同的统计口径？"},{"role":"Analyst","en":"Yes. We should document headcount and FTE separately in the data dictionary.","zh":"是的。我们应该在数据字典中分别定义人数和全职当量。"},{"role":"HR Manager","en":"Please confirm the calculation rules before the board meeting.","zh":"请在董事会会议前确认计算规则。"}],"quiz":"Which document defines metric calculation rules?","answer":"data dictionary","quizZh":"哪份文件规定指标的定义和计算口径？","answerZh":"数据字典"},{"id":"S16","moduleId":"m8","title":"HR工单与服务","titleEn":"Resolving an HR service ticket","lines":[{"role":"Employee","en":"My leave balance in the HR system looks incorrect.","zh":"我在人事系统里的假期余额似乎不正确。"},{"role":"HR Service Desk","en":"Please open an HR service ticket so we can track the issue.","zh":"请创建一个 HR 服务工单，方便我们跟踪问题。"},{"role":"Employee","en":"When can I expect an initial response?","zh":"大概什么时候能收到初步回复？"},{"role":"HR Service Desk","en":"Our service level agreement sets a two-working-day response target.","zh":"我们的服务级别协议规定，目标响应时间为两个工作日。"}],"quiz":"What does SLA stand for?","answer":"service level agreement","quizZh":"SLA 是什么的缩写？","answerZh":"服务级别协议"},{"id":"S17","moduleId":"m9","title":"派遣启动会议","titleEn":"Preparing an international assignment","lines":[{"role":"Mobility Lead","en":"The employee will relocate to Singapore for eighteen months.","zh":"员工将派往新加坡工作十八个月。"},{"role":"HRBP","en":"Have we checked work permit and tax residency requirements?","zh":"我们核查过工作许可和税收居民身份要求了吗？"},{"role":"Mobility Lead","en":"The immigration review is underway, and tax advisers are assessing the assignment.","zh":"移民事务审查正在进行，税务顾问也在评估此次派遣。"},{"role":"HRBP","en":"Please include the approved allowances in the assignment letter.","zh":"请把获批的相关津贴写入派遣函。"}],"quiz":"Which document summarizes the terms of an assignment?","answer":"assignment letter","quizZh":"哪份文件概述国际派遣的条件与条款？","answerZh":"派遣函"},{"id":"S18","moduleId":"m9","title":"外派薪资与税务","titleEn":"Coordinating international payroll","lines":[{"role":"Payroll Lead","en":"The employee remains on home-country payroll but works in the host country.","zh":"员工仍通过派出国发薪，但在东道国工作。"},{"role":"Mobility Lead","en":"Do we need shadow payroll for local reporting?","zh":"为了向当地部门申报，我们是否需要做影子薪资核算？"},{"role":"Payroll Lead","en":"Possibly. We need a jurisdiction-specific tax review first.","zh":"有可能。我们需要先按当地法规开展税务评估。"},{"role":"Mobility Lead","en":"Let us document the decision and explain tax equalization separately.","zh":"我们记录决策，并另行解释税负平衡机制。"}],"quiz":"Which payroll process may report income without paying it again?","answer":"shadow payroll","quizZh":"哪种薪资核算流程可以申报收入而不再重复发薪？","answerZh":"影子薪资核算"},{"id":"S19","moduleId":"m10","title":"经营层汇报","titleEn":"Presenting to executives","lines":[{"role":"HR Director","en":"What is the key takeaway from the overseas talent program review?","zh":"海外人才项目复盘的核心结论是什么？"},{"role":"HRBP","en":"The pilot reduced delays, but the approval workflow still needs simplification.","zh":"试点减少了延误，但审批流程仍需简化。"},{"role":"HR Director","en":"Please lead with the recommendation and show the supporting data points.","zh":"请先讲建议方案，再展示支持建议的数据。"},{"role":"HRBP","en":"I will revise the executive summary and share it before the meeting.","zh":"我会修改管理层摘要并在会议前发出。"}],"quiz":"Which section helps executives grasp the key points quickly?","answer":"executive summary","quizZh":"哪个章节帮助管理层快速把握要点？","answerZh":"管理层／经营层摘要"},{"id":"S20","moduleId":"m10","title":"会议跟进","titleEn":"Following up after a meeting","lines":[{"role":"Project Owner","en":"Before we close, can we confirm the next steps?","zh":"结束会议前，我们能确认一下下一步安排吗？"},{"role":"HR Manager","en":"Legal will review the policy, and finance will validate the cost assumptions.","zh":"法务会审阅政策，财务会验证成本假设。"},{"role":"Project Owner","en":"I will capture the action items and owners in the meeting minutes.","zh":"我会在会议纪要里记录行动项和责任人。"},{"role":"HR Manager","en":"Great. Please flag any blockers before Friday.","zh":"很好。如有阻碍事项，请在周五前提出。"}],"quiz":"Where should action owners be documented after the meeting?","answer":"meeting minutes","quizZh":"会议结束后，行动项的负责人应该记录在哪里？","answerZh":"会议纪要"},{"id":"S21","moduleId":"m1","title":"招聘进度沟通","titleEn":"Hiring progress","lines":[{"role":"Hiring Manager","en":"How's the hiring process going for the marketing role?","zh":"市场营销岗位的招聘进展如何？"},{"role":"Recruiter","en":"We have three strong candidates. The panel will interview them tomorrow, and we hope to make an offer next week.","zh":"目前有三位实力较强的候选人。面试小组明天会面试他们，我们希望下周发出录用通知。"}],"quiz":"When is the panel interview?","answer":"tomorrow","quizZh":"面试小组何时面试候选人？","answerZh":"明天"},{"id":"S22","moduleId":"m6","title":"员工离职与岗位补招","titleEn":"Resignation and backfill","lines":[{"role":"Colleague","en":"John has handed in his notice. His last working day is Friday.","zh":"约翰已经提交辞职通知，最后工作日是周五。"},{"role":"HRBP","en":"Has the employee relations team conducted his exit interview yet? We need to backfill this role as soon as possible.","zh":"员工关系团队已经和他做过离职访谈了吗？我们需要尽快补招该岗位。"}],"quiz":"What interview should be conducted?","answer":"exit interview","quizZh":"需要进行什么面谈？","answerZh":"离职访谈"},{"id":"S23","moduleId":"m3","title":"绩效目标沟通","titleEn":"Performance goals","lines":[{"role":"Manager","en":"Next quarter’s planning session is coming up. Please align with your team on the goals.","zh":"下季度规划会快到了，请和团队就目标达成一致。"},{"role":"HRBP","en":"The sales KPI seems overly ambitious. I think we need to push back and propose a more realistic target.","zh":"销售绩效指标似乎定得过高。我认为我们需要提出异议，并建议一个更切合实际的目标。"}],"quiz":"What should we propose?","answer":"a more realistic target","quizZh":"我们应提出什么建议？","answerZh":"更切合实际的目标"}],"references":[{"name":"SHRM HR Glossary","url":"https://www.shrm.org/topics-tools/tools/hr-glossary"},{"name":"CIPD Profession Map — Talent management","url":"https://www.cipd.org/en/the-people-profession/the-profession-map/explore-the-profession-map/specialist-knowledge/talent-management/"},{"name":"CIPD — Performance management guide","url":"https://www.cipd.org/en/knowledge/guides/effective-performance-management/"},{"name":"ATD — Learning and development","url":"https://www.td.org/talent-development-glossary-terms/what-is-learning-and-development"},{"name":"Acas — Garden leave during notice","url":"https://www.acas.org.uk/notice-periods/when-an-employee-is-not-required-to-work-their-notice"},{"name":"SHRM — Background checks vs reference checks","url":"https://www.shrm.org/in/topics-tools/news/blogs/conducting-candidate-reference-and-background-checks"}],"editorial_note":"V18.2 逐条模型语言编辑。词典证据详见交付审校台账。"};
