 if(status){status.textContent=playing?`正在播放 · 第 ${scenePlayer.index+1}/${s?.lines.length||0} 句`:paused?`已暂停 · 点击继续，将从第 ${scenePlayer.index+1} 句重新播放`:finished?'✓ 对话播放完成':'可随时播放、暂停和继续';}
 const stop=document.querySelector('[data-action="stopScene"]');
