function studyView(){if(!state.deck.length)startDeck();let id=state.deck[state.deckIndex],w=byId(id);if(!w)return `<div class="deck-toolbar">${deckControls()}<button class="link-btn" data-action="reshuffle">换一组</button></div><div class="empty">当前范围没有新词，可选择重新学习。</div>`;let info=entry(id),level=info.level||0,daily=learningSummary(),groupDone=state.deck.filter(wid=>STORE.words[wid]?.lastDay===today()).length;return `<div class="page-head study-heading"><div><h1>每日闪卡</h1><p class="study-subtitle">每天一点，持续积累。</p></div></div><div class="deck-toolbar">${deckControls()}<button class="link-btn" data-action="reshuffle">换一组 ${icon('repeat','sm')}</button></div><div class="study-layout"><div class="study-card-container">${STORAGE_READY?'':'<div class="save-hint compact-save" role="alert">⚠ 当前环境不支持可靠保存，请使用 Safari / Chrome 正式网页</div>'}<div class="study-progress"><div class="study-topline"><small>今日已学 <strong>${daily.done} / ${daily.goal}</strong></small><small>累计已学 <strong>${daily.seen}</strong> 个</small></div><div class="bar" role="progressbar" aria-label="今日学习进度" aria-valuenow="${Math.min(daily.done,daily.goal)}" aria-valuemin="0" aria-valuemax="${daily.goal}"><span style="width:${daily.pct}%"></span></div>${daily.done>=daily.goal?'<div class="goal-achieved" role="status">✓ 今日达标 · 可继续学习</div>':''}</div><div class="tapcard ${state.flipped?'is-flipped':''}" data-action="flip" tabindex="0" role="button" aria-label="翻转记忆卡 ${h(w.term)}"><div class="flashcard"><div class="flash-face front"><span class="flash-label flash-category">${h(modById(w.moduleId)?.title)}</span><div class="flash-term">${h(w.term)}</div>${ipaView(w)}<button class="listen" data-play-word="${h(w.id)}">${icon('sound','sm')} 听发音 · ${Number(STORE.rate)===1?'1.0':STORE.rate}×</button><div class="flash-footer">${icon('rotate','sm')} 点击任意空白处翻转卡片</div></div><div class="flash-face back"><span class="flash-label">CHINESE · 核心释义</span><div class="flash-zh">${h(w.zh)}</div><p class="flash-meaning">${h(w.definition)}</p>${phraseView(w)}<div class="flash-footer">${icon('rotate','sm')} 再次点击返回英文</div></div></div></div><div class="flash-actions"><button class="dontknow" data-rate="0">${icon('repeat')} 还不熟悉</button><button class="iknow" data-rate="1">${icon('check')} 我记住了</button></div><div class="flash-tools"><button class="textbtn" data-action="prev" ${state.deckIndex===0?'disabled':''}>${icon('left','sm')} 上一张</button><button class="textbtn" data-detail="${h(id)}">完整释义 · 对话 · 练习 ${icon('right','sm')}</button><button class="textbtn" data-action="next" ${state.deckIndex===state.deck.length-1?'disabled':''}>下一张 ${icon('right','sm')}</button></div></div><div class="study-side"><div class="surface"><span class="tag lav">${icon('spark','sm')} 学习建议</span><h3>记住用法，比死记翻译更重要。</h3><div class="side-detail"><div><small>职场例句 · 中英对照</small><b>${h(w.example)}</b><p class="example-side-zh">${h(w.exampleZh||'')}</p></div>${phraseView(w)}<button class="listen" data-say="${h(w.example)}">${icon('sound','sm')} 朗读例句</button></div></div><div class="tipbox">✨ 每次点击“我记住了”，系统会安排更晚的复习时间；不熟悉的单词会更早进入复习计划；随机新词模式不会重复已学词。</div></div></div>`}
function wordAliasText(w){return [...(w.aliases||[]),...(w.searchAliases||[])].join(' ')}
function wordScore(w,q){let t=w.term.toLowerCase(),z=w.zh.toLowerCase(),a=wordAliasText(w).toLowerCase();return t===q?0:t.startsWith(q)?1:z===q?2:t.includes(q)?3:a.includes(q)?4:z.includes(q)?5:6}
function wordsInScope(){
 const q=state.query.trim().toLowerCase();
 return DB.words.filter(w=>(state.module==='all'||state.module===w.moduleId)&&
  (!q||[w.term,w.zh,w.definition,w.example,w.collocation,w.module,wordAliasText(w),w.usage||'',w.distinction||''].some(x=>String(x||'').toLowerCase().includes(q))));
}
function hasWordStatus(w,status){
 const item=STORE.words[w.id]||{};
 switch(status){
  case 'new':return !item.seen&&(item.level||0)<3;
  case 'learning':return !!item.seen&&(item.level||0)<3;
  case 'mastered':return (item.level||0)>=3;
  case 'favorites':return !!item.favorite;
  case 'due':return !!item.seen&&item.due<=Date.now();
  case 'added':return w.id.startsWith('HRV6');
  default:return true;
 }
}
function filteredWords(){
 const q=state.query.trim().toLowerCase();
 return wordsInScope().filter(w=>hasWordStatus(w,state.filter))
  .sort((a,b)=>q?wordScore(a,q)-wordScore(b,q):0);
}
